     \subsubsection{Computation of the terms  {\textcircled{c}} and \textcircled{d}} 
     Now, we will consider the terms $\mbox{\textcircled{c}}$ and $\mbox{\textcircled{d}}$ for which some approximations will be performed to avoid the explicit calculation of the projectors $P_k$. 

      First let recall the expression of the term $\mbox{\textcircled{c}}$
      $$
      \mbox{\textcircled{c}}=\sum_{k=1}^{N'} {\cal A}_k^{-1} P_k \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left\{F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N}. 
      $$
On the one side, we observe that the term $\mbox{\textcircled{c}}$ decays exponentially fast and thus does not contribute in the diffusion limit. 
On the other side, in the transport limit $\varepsilon\to +\infty$, one has 
    \begin{align}
 \sum_{k=1}^{N'} {\cal A}_k^{-1} P_k &=   \sum_{k=1}^{N'} \frac{1}{\exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) + \frac{\lambda_k}{\lambda_\star} \left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right)} P_k \nonumber\\
 &= \sum_{k=1}^{N'} P_k + O(1/\varepsilon) = (I - P_0) + O(1/\varepsilon).
    \end{align}
Hence, from these asymptotic behaviors,  and in view of constructing a method which does not require the knowledge of $P_k$, 
%and in view of simplifying as much as possible, 
we propose the following approximation for $\mbox{\textcircled{c}}$  
    \begin{equation}
    \label{crond}
    \mbox{\textcircled{c}} 
    %\frac{1}{\exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) + \left(\frac{\lambda_k}{\lambda_\star}\right) \left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right)} 
    %&&\sum_{k=1}^{N'} {\cal A}_k^{-1}
    %P_k \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left(F_{i,j}(t_n) \mathds{1}_{v_j > 0} + F_{i+1,j}(t_n) \mathds{1}_{v_j < 0}\right)_j \nonumber\\
    \approx  
    (I - P_0) \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left\{F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N}. 
    \end{equation}

%\paragraph{Term $\mbox{\textcircled{d}}$\\}
Let now consider the term $\mbox{\textcircled{d}}$ and 
first, let recall its expression 
%of $\mbox{\textcircled{d}}$ 
 \begin{equation}
     \label{def:termd}
 \mbox{\textcircled{d}}= \sum_{k=1}^{N'}{\cal A}_k^{-1} P_k \left\{ \langle v_j e_j, \frac{\mathcal{C}(t)}{\lambda_\star} (D - \lambda_\star I) \left[-\frac{\varepsilon}{\sigma} \frac{F_{i+1}^n - F_i^n}{\Delta x}\right] \rangle \right\}_{j=1, \dots, 2N}. 
 \end{equation}
Then, we observe that in the diffusion limit, we have, for any arbitrary $q\in\mathbb{N}$:
    \begin{align}
\sum_{k=1}^{N'} \frac{{\cal A}_k^{-1}}{\lambda_\star} P_k 
\label{approx4}
&= \sum_{k=1}^{N'} \frac{1}{\lambda_k} P_k + O(\varepsilon^q) = D^{+} + O(\varepsilon^q), 
    \end{align}
   since from the definition \eqref{defAk} of ${\cal A}_k$,  
   %= \frac{1}{\lambda_\star \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) + {\lambda_k} \left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right)}$, so that 
   we deduce ${\cal A}_k^{-1}$ tends to $\lambda_\star/\lambda_k$ as $\varepsilon\to 0$ and from Prop. \ref{prop1}, we have $D = \sum_{k=1}^{N'} \lambda_k P_k$. However, little can be said about the term in braces in \eqref{def:termd} except that $\displaystyle %\lim_{diff} \mathcal{C}(t) =
    \lim_{\eta=\varepsilon \to 0} \mathcal{C}(t) = 1/\lambda_\star$. Moreover, using the approximation \eqref{approx4} imposes the term into braces to be orthogonal to ${\bf 1}$ which is not the case due to the presence of $F^n_{i+1}-F_i^n$. Hence, the calculation of the term $\mbox{\textcircled{d}}$ would require the knowledge of the projectors $P_k$ which we want to avoid since it may be very costly in the general case. 
    Hence, in the next subsection, we will consider another reconstruction which will avoid the knowledge of the projectors $P_k$. 

    \subsection{Spatial Approximation: third attempt}
    Due to the obstacle observed previously, we thus consider the following reconstruction for $F_j(t, x)$  
    \begin{equation}
        \label{third}
         F_j(t, x) = F_{i+1/2,j}(t) + \frac{\rho_{i+1}^n-\rho_{i}^n}{\Delta x}(x-x_{i+1/2}). 
    \end{equation}
    As before, assessing \eqref{duhamel2} at $x=x_{i+1/2}$, using  reconstruction \eqref{third} for the integral term and \eqref{approx_cl} for the first term, we get 
the following interface relation for $F_{i+1/2, j}(t)$ 
    \begin{eqnarray}
    F_{i+1/2, j}(t)&=& \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left(F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right) \notag \\
        \label{discrete3}
        &&\hspace{-1.2cm}+ \langle e_j, \int_{0}^{{\frac{\sigma (t - t_n)}{\eta\varepsilon}}} \exp\left({\lambda_\star u}\right) (D - \lambda_\star I) \left[F_{i+1/2}(t) - \frac{\varepsilon v_j {{u}}}{\sigma} \frac{\rho_{i+1}^n - \rho_i^n}{\Delta x}{\bf 1}\right] du \rangle. 
    \end{eqnarray}
    The same calculations as the ones done before can be performed since the expression of $M(t)^{-1}$ given by \eqref{M-1} is unchanged, but the expression of $S(t)$ in \eqref{defS} is slightly modified since its expression is now 
    \begin{eqnarray}
        S_j(t) &=& \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left(F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right) \notag \\
        \label{defS2}
        &+& \langle v_j e_j, \int_{0}^{{\frac{\sigma (t - t_n)}{\eta\varepsilon}}} \exp\left({\lambda_\star u}\right) (D - \lambda_\star I) \left[-\frac{\varepsilon {u}}{\sigma} \frac{\rho_{i+1}^n - \rho_i^n}{\Delta x}{\bf 1}\right] du \rangle. 
    \end{eqnarray}
    So now $F_{i+1/2}$ satisfies $F_{i+1/2}(t) = M(t)^{-1}S(t)$ and decompose
    $F_{i+1/2}(t) = \mbox{\textcircled{a}}+\mbox{\textcircled{b}}+\mbox{\textcircled{c}}+\mbox{\textcircled{d}}$ as: 
    \begin{eqnarray}
    \mbox{\textcircled{a}}&=&P_0\left\{F^n_{i,j}\mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N}\nonumber\\
    \mbox{\textcircled{b}}&=&-\frac{\varepsilon \mathcal{C}(t)}{\sigma} \frac{1}{2N} \langle (D V - \lambda_\star V), \frac{\rho_{i+1}^n - \rho_i^n}{\Delta x} \rangle \bigbold{1}\nonumber\\
    \mbox{\textcircled{c}}&=&\sum_{k=1}^{N'} {\cal A}_k^{-1} P_k \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left\{F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N}\nonumber\\
    \mbox{\textcircled{d}}&=&\sum_{k=1}^{N'}{\cal A}_k^{-1} P_k \left\{ \langle v_j e_j, \frac{\mathcal{C}(t)}{\lambda_\star} (D - \lambda_\star I) \left[-\frac{\varepsilon}{\sigma} \frac{\rho_{i+1}^n - \rho_i^n}{\Delta x}\bf 1\right] \rangle \right\}_{j=1, \dots, 2N}.  \nonumber
    \end{eqnarray}
    As previously, we now deal with the decomposition. Since 
    $\mbox{\textcircled{a}}$ and $\mbox{\textcircled{c}}$ do not depend on the gradient reconstruction, they are unchanged and respectively given by \eqref{arond} and \eqref{crond}; we  focus  on $\mbox{\textcircled{c}}$ and $\mbox{\textcircled{d}}$. 

    \subsubsection{Calculation of the term  {\textcircled{b}}}
    Regarding the term $\mbox{\textcircled{b}}$, we now have the following expression 
     \begin{eqnarray*}
    \mbox{\textcircled{b}} &=&  - \frac{\varepsilon {\cal C}(t)}{\sigma} \frac{1}{2N} \langle (D  - \lambda_\star I)V,  \frac{\rho_{i+1}^n - \rho_i^n}{\Delta x} \rangle {\bf 1} \nonumber\\
    &=&  - \frac{\varepsilon {\cal C}(t)}{\sigma} \frac{1}{2N} \langle V, (D  - \lambda_\star I)\frac{\rho_{i+1}^n - \rho_i^n}{\Delta x} \rangle {\bf 1}\nonumber\\
    &=&   \frac{\varepsilon \lambda_\star {\cal C}(t)}{\sigma} \frac{1}{2N} \langle V, \frac{\rho_{i+1}^n - \rho_i^n}{\Delta x} \rangle {\bf 1}=  \frac{\varepsilon \lambda_\star {\cal C}(t)}{\sigma} \frac{1}{2N} \sum_{k=1}^{2N} v_k \, \frac{\rho_{i+1}^n - \rho_i^n}{\Delta x}{\bf 1}   = {\bf 0},  
    \end{eqnarray*}
     since the velocity grid satisfies $\sum_{k=1}^{2N} v_k=0$ by assumption. 


