     \subsubsection{Computation of the Interface value}
 All in all, inserting the expressions \eqref{arond}, \eqref{crond} and \eqref{drond} of $\mbox{\textcircled{a}},  \mbox{\textcircled{c}}$ and $\mbox{\textcircled{d}}$  (recalling that $\mbox{\textcircled{b}}=0$) in \eqref{resFi} leads to the following expression for the interface value:
    \begin{eqnarray}
    F_{i+1/2}(t) &=& \left(\rho_i^{+,n} + \rho_{i+1}^{-,n}\right) \bigbold{1} \nonumber\\ %\textcolor{blue}{- \frac{\varepsilon \mathcal{C}(t)}{\sigma} \frac{1}{2N} \langle (D V - \lambda_\star V), \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x} \bigbold{1} \rangle \bigbold{1}}\nonumber\\
    &+& (I - P_0) \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left\{F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N} \nonumber\\
    &+& \lambda_\star \mathcal{C}(t) \left[\frac{\varepsilon}{\sigma} \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x}\right] U \nonumber\\
    &=& \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left\{F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N} \nonumber\\
    %&&\textcolor{blue}{- \frac{\varepsilon \mathcal{C}(t)}{\sigma} \frac{1}{2N} \langle (D V - \lambda_\star V), \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x} \bigbold{1} \rangle \bigbold{1}}\nonumber\\
    &&\hspace{-0.6cm} + \left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right) \left(\rho_i^{+,n} + \rho_{i+1}^{-,n}\right) \bigbold{1} + \lambda_\star \mathcal{C}(t) \left[\frac{\varepsilon}{\sigma} \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x}\right] U. \label{resFi3}
    \end{eqnarray}
    This expression of $F_{i+1/2}(t)$ will be inserted in the finite volume scheme which will lead to a new UGKS described hereafter. 


    \subsection{New UGKS}
    The complete scheme consists of considering \eqref{ugks_rho}-\eqref{ugks_f} with the following definition for the flux $\phi_{i+1/2,j}$  
    $$
    \phi_{i+1/2,j}=\frac{1}{\eta \Delta t} \int_{t_n}^{t_{n+1}} v_j F_{i+1/2,j}(t) dt, 
    $$
     where the expression \eqref{resFi3} is used for the interface value $F_{i+1/2,j}(t)$. Some calculation enables to get  the following explicit expression for the flux:     
%    \begin{eqnarray}
%    \label{scheme_ugks}
%    F_{i,j}(t_{n+1}) - F_{i,j}(t_n) = -\frac{\Delta t}{\Delta x} \left(\phi_{i+1/2,j} - \phi_{i-1/2,j}\right) + \frac{\sigma}{\eta\varepsilon} \Delta t \langle e_j, D F_i(t_n + \Delta t) \rangle,
%    \end{eqnarray}
%    where:
    \begin{eqnarray}
    \phi_{i+1/2,j} &=& \frac{1}{\eta \Delta t} \int_{t_n}^{t_n + \Delta t} {v_j}\Bigg[ \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left(F_{i,j}^n\mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right)  \nonumber\\
    &&\hspace{-1cm} +  \left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right) \left(\rho_i^{+,n} + \rho_{i+1}^{-,n}\right) + \lambda_\star \mathcal{C}(t) \frac{\varepsilon}{\sigma} \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x} U_j \Bigg] dt \nonumber\\
    && \hspace{-1cm}= \mbox{A}(\Delta t, \sigma, \eta, \varepsilon) \left(F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right) v_j + \mbox{C}(\Delta t, \sigma, \eta, \varepsilon) \left(\rho_i^{+,n} + \rho_{i+1}^{-,n}\right) v_j \nonumber\\
    \label{flux_ugks}
    &&\hspace{-0.5cm} + \mbox{D}(\Delta t, \sigma, \eta, \varepsilon) \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x} \lambda_\star U_j v_j,
    \end{eqnarray}
    where the coefficients A,C,D are given by (using the notation $w= \lambda_\star\sigma\Delta t/ (\eta \varepsilon)$):
    \begin{eqnarray}
    \label{coef_A}
 \hspace{1.cm}\mbox{A}(\Delta t, \sigma, \eta, \varepsilon) &=& \frac{1}{\eta w} (e^w-1) \\ %\;\;:\frac{\varepsilon}{\sigma \lambda_\star \Delta t} \left(\exp\left({\frac{\lambda_\star \sigma \Delta t}{\eta \varepsilon}}\right) - 1\right), \\
  \label{coef_C}
    \mbox{C}(\Delta t, \sigma, \eta, \varepsilon) &=& \frac{1}{\eta} - \mbox{A}(\Delta t, \sigma, \eta, \varepsilon) \\ %= \frac{1}{\eta} - \frac{\varepsilon}{\sigma \lambda_\star \Delta t} \left(\exp\left({\frac{\lambda_\star \sigma \Delta t}{\eta \varepsilon}}\right) - 1\right), \\
    \mbox{D}(\Delta t, \sigma, \eta, \varepsilon) 
    %&=& \frac{\varepsilon}{\sigma} \frac{1}{\eta \Delta t} \int_{t_n}^{t_n + \Delta t} \frac{1}{\lambda_\star} \Bigg[\left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right) \nonumber\\
    %&&+ {\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}} \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\Bigg] dt \nonumber\\
    %&=& \frac{\varepsilon}{\sigma \lambda_\star} \left(\frac{1}{\eta} \left(1 + \exp\left({\frac{\lambda_\star \sigma \Delta t}{\eta \varepsilon}}\right)\right) - \frac{2 \varepsilon}{\sigma \lambda_\star \Delta t} \left(\exp\left({\frac{\lambda_\star \sigma \Delta t}{\eta \varepsilon}}\right) - 1\right)\right), \nonumber\\
    %&=& \frac{\varepsilon}{\sigma \lambda_\star} \Bigg[C(\Delta t, \sigma, \eta, \varepsilon) \nonumber\\ 
%    \label{coef_D}
%    &&+ \frac{1}{\eta} \left(\exp\left({\frac{\lambda_\star \sigma \Delta t}{\eta \varepsilon}}\right) - \frac{\eta \varepsilon}{\sigma \lambda_\star \Delta t} \left(\exp\left({\frac{\lambda_\star \sigma \Delta t}{\eta \varepsilon}}\right) - 1\right)\right)\Bigg].\nonumber\\ 
    \label{coef_D}
    &=& \frac{\varepsilon}{\sigma \lambda_\star} (\mbox{C}(\Delta t, \sigma, \eta, \varepsilon)-\mbox{A}(\Delta t, \sigma, \eta, \varepsilon))+\frac{\varepsilon }{\eta \sigma \lambda_\star}e^w.  %\exp\left({\frac{\lambda_\star \sigma \Delta t}{\eta \varepsilon}}\right) 
    \end{eqnarray}
    This exactly matches the scheme proposed by Mieussens in \cite{mieussens2013} for the BGK operator, if the interface value for the density used in \cite{mieussens2013} is set to $(\rho^n_i + \rho^n_{i+1})/2$.     Once the fluxes have been written, it remains to define the scheme satisfied  by $F^{n+1}_i\in \mathbb{R}^{2N}$ from \eqref{ugks_f}
    \begin{eqnarray}
    \label{ugks_new}
    \left(I - \frac{\sigma \Delta t}{\varepsilon \eta} D\right) F_i^{n+1} = F^n_i - \frac{\Delta t}{\Delta x} \left(\phi_{i+1/2} - \phi_{i-1/2}\right).
    \end{eqnarray}
    Due to the implicit treatment of the collision operator $D$, a linear system has to be inverted for each spatial cell, which is fully aligned with other strategies for stiff kinetic problems. 

Let us now consider the macroscopic flux $\Phi_{i+1/2}$ which is defined by 
    $$
    \Phi_{i+1/2}=\frac{1}{2N}\sum_{j=1}^{2N} \phi_{i+1/2,j},    
    $$
where the (microscopic) flux $\phi_{i+1/2,j}$ is given by  \eqref{flux_ugks}. Some simple calculations enable to get 
\begin{eqnarray*}
\Phi_{i+1/2}&=& \mbox{A}(\Delta t, \sigma, \eta, \varepsilon) (J^{+,n}_i+J^{-,n}_i) +\mbox{D}(\Delta t, \sigma, \eta, \varepsilon) \frac{\lambda_\star}{2N}\frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x} \langle U, {V} \rangle,   \nonumber 
\end{eqnarray*}
with $J^{\pm,n}_i$ are given by 
$$
J_i^{-,n} =\frac{1}{2N}\sum_{j=1}^N v_j F_{i,j}^n \;\; \mbox{ and } \;\; J_i^{+,n} =\frac{1}{2N}\sum_{j=N+1}^{2N} v_j F_{i,j}^n. 
$$
But from Prop. \ref{prop1}, one has 
$\lambda_\star \langle U,  {V} \rangle = \langle V,  {V} \rangle$ so that the macroscopic flux $\Phi_{i+1/2}$ finally becomes 
\begin{eqnarray}
\label{flux_ugks_rho}
\Phi_{i+1/2}&=& \text{A}(\Delta t, \sigma, \eta, \varepsilon) (J^{+,n}_i+J^{-,n}_i)+ \frac{\text{D}(\Delta t, \sigma, \eta, \varepsilon)}{2N} \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x} \langle V, V \rangle, 
\end{eqnarray}
and the macroscopic density is updated by as 
\begin{equation}
\label{new_ugks_rho}
    \frac{\rho^{n+1}_i - \rho^n_i}{\Delta t} + \frac{\Phi_{i+1/2}-\Phi_{i-1/2}}{\Delta x} = 0.   
\end{equation}


\begin{remark}

\

\begin{itemize}
    \item  Let us remark that, contrary to the standard UGKS applied to the BGK equation, the update of $\rho^{n+1}$ is not required to update the kinetic unknown $F^{n+1}$ in \eqref{ugks_new}. Indeed, in this version of UGKS, 
 $F^{n+1}$ is updated from \eqref{ugks_new} and then, 
 $\rho^{n+1}$ is computed from \eqref{new_ugks_rho}. 
 \item Solving  $\eqref{ugks_new}$ requires a linear solver (Conjugate Gradient method in this paper) in each spatial cell if $D$ has no clear properties. When $D$ comes from BGK model, the trick is to update $\rho$  through \eqref{new_ugks_rho}: the system becomes diagonal. When $D$ is linked to FP model, one has  to use Thomas algorithm for tridiagonal matrices for more efficiency and  precision (the matrix is badly conditioned for Conjugate Gradient method). 
\end{itemize}

\end{remark}    

    \section{Asymptotic behavior}
 Here, we formally  investigate the asymptotic behavior of the new UGKS \eqref{ugks_new}-\eqref{flux_ugks}-\eqref{new_ugks_rho}-\eqref{flux_ugks_rho} presented above. 
 First, we study the free transport regime $\varepsilon\to +\infty$ and then the diffusion limit $\eta=\varepsilon\to 0$ is studied. 

 \phantomsection

    \subsection{Free transport regime}
 The asymptotic behavior follows from the ones of the coefficients  defined in \eqref{coef_A}, \eqref{coef_C}, \eqref{coef_D}. 

 \begin{proposition}
 When $\varepsilon\to +\infty$ (and $\eta$ constant), one has 
 \begin{itemize}
     \item \emph{A}$(\Delta t, \sigma, \eta, \varepsilon)$ tends to  $\frac{1}{\eta}$. 
     \item \emph{C}$(\Delta t, \sigma, \eta, \varepsilon)$ tends to $0$. 
     \item \emph{D}$(\Delta t, \sigma, \eta, \varepsilon)$ tends to $0$. 
 \end{itemize}
 \end{proposition}
As a consequence, the flux \eqref{flux_ugks} verifies when $\varepsilon\to +\infty$ 
$$
\phi_{i+1/2,j} \to \frac{v_j}{\eta} \left(F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right), 
$$
and the scheme becomes 
$$
F^{n+1}_{i,j}-F^n_{i,j} +\frac{v_j\Delta t}{\eta\Delta x} \left(F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right)  = 0, 
$$
which is the standard first order upwind scheme for the free transport equation $\partial_t f+\frac{v}{\eta}\partial_x f=0$. 

