    \subsection{Implicit diffusion}

    The version where the limit scheme is implicit is obtained simply by modifying the flux as:
    \begin{eqnarray}
    \phi_{i+1/2,j} &=& \text{A}(\Delta t, \sigma, \eta, \varepsilon) \left(F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right) v_j \notag \\
    \label{flux_imp}
    &+& \text{C}(\Delta t, \sigma, \eta, \varepsilon) \left(\rho_i^{+,n} + \rho_{i+1}^{-,n}\right) v_j + \text{D}(\Delta t, \sigma, \eta, \varepsilon) \frac{\rho_{i+1}^{n+1} - \rho_{i}^{n+1}}{\Delta x} \lambda_\star U_j v_j.
    \end{eqnarray}
    However, to compute $\rho_{i}^{n+1}$, the macroscopic fluxes $\Phi_{i+1/2,j}$ are now obtained by summing on $j$ the microscopic fluxes \eqref{flux_imp}. From the previous calculations, we get 
\begin{eqnarray}
\Phi_{i+1/2} &=&    \frac{1}{2N} \sum_{j=1}^{2N} {\phi_{i+1/2,j} } \notag\\
%&=& \frac{1}{2N} A(\Delta t, \sigma, \eta, \varepsilon) \left(\sum_{j=1}^N F_{i,j}^n v_j + \sum_{j=N+1}^{2N} F_{i+1,j}^n v_j\right) \notag \\
%    && + \frac{\langle V, V \rangle}{2N} D(\Delta t, \sigma, \eta, \varepsilon) \frac{\rho_{i+1}^{n+1} - \rho_{i}^{n+1}}{\Delta x} \notag \\
  &=& \text{A}(\Delta t, \sigma, \eta, \varepsilon) (J_i^{+,n} + J_{i+1}^{-,n}) + \frac{\langle V, V \rangle}{2N} \text{D}(\Delta t, \sigma, \eta, \varepsilon) \frac{\rho_{i+1}^{n+1} - \rho_{i}^{n+1}}{\Delta x},
    \end{eqnarray}
    so that the scheme on $\rho$ finally becomes 
    (with the notations %$\rho^n_i = \rho_i(t_n)$,$J^{\pm,n}_i = J^\pm_i(t_n)$, and 
    $J_{i+1/2}^n = J_{i+1}^{-,n} + J_i^{+,n}$):
    \begin{eqnarray*}
        \frac{\rho_i^{n+1} - \rho_i^n}{\Delta t} &=& - \text{A}(\Delta t, \sigma, \eta, \varepsilon) \frac{J_{i+1/2}^n - J_{i-1/2}^n}{\Delta x} 
        - \frac{\langle V, V \rangle}{2N} \text{D}(\Delta t, \sigma, \eta, \varepsilon) \frac{\rho_{i+1}^{n+1} - 2\rho_i^{n+1} + \rho_{i-1}^{n+1}}{\Delta x^2},
    \end{eqnarray*}
    where A and D are given by \eqref{coef_A} and \eqref{coef_D}. 

    \begin{remark}
    Since we have an implicit diffusion in space, one needs first to solve  $\rho^{n+1}$ through a linear solver and then solve  $F^{n+1}$.
    \end{remark}




    \subsection{Some remarks for the BGK operator}
    In the BGK case, the computations simplify significantly. 
Indeed, first, all the eigenvalues $\lambda_k  (k\geq 1)$ are equal to $\lambda_\star = \textcolor{blue}{-}1$, and $\lambda_0=0$. Hence, the coefficients ${\cal A}_k$ defined in \eqref{defAk} becomes independent of $k$ and can be written as  
        $$
        {\cal A}_k=\exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) + \frac{\lambda_k}{\lambda_\star} \left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right)=1, 
        $$ 
        so that the inverse $M(t)^{-1}$ defined in \eqref{M-1} of $M(t)$ defined in \eqref{matrixM} becomes:
        \begin{eqnarray*}
        M(t)^{-1} &=& \exp\left(-{\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) P_0 + \sum_{k=1}^{N'} 
        %\frac{1}{\exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) + (1) \left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right)} 
        {\cal A}_k^{-1} P_k 
%        &=& \exp\left(-{\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) P_0 + \sum_{k=1}^{N'} P_k \\
        = \exp\left(-{\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) P_0 + (I - P_0).
        \end{eqnarray*}
     Besides, in the BGK case, one can observe that $D=P_0+\lambda_\star I$ or $D - \lambda_\star I = P_0$. It turns out that for the BGK case, the second reconstruction  \eqref{reconstruction} and the third reconstruction \eqref{third} gives  the same expression for $S(t)$ defined by \eqref{defS} and \eqref{defS2} respectively. Indeed, the reconstruction gives \eqref{reconstruction} 
        \begin{eqnarray}
        S_j(t) &=& \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left(F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right) \nonumber\\
        &+& \langle v_j e_j, \int_{0}^{\frac{\sigma t}{\eta\varepsilon}} \exp\left({\lambda_\star u}\right) P_0 \left[-\frac{\varepsilon u}{\sigma} \frac{F_{i+1}^n - F_i^n}{\Delta x}\right] du \rangle \nonumber\\
        \label{S_BGK}
        &=& \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left(F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right) + \frac{\mathcal{C}(t) v_j}{\lambda_\star} \frac{\varepsilon}{\sigma} \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x},
        \end{eqnarray}
        which is the expression that we would have obtained using the third reconstruction \eqref{third} (let  recall the definition \eqref{defC} of $\mathcal{C}(t)$).  
        %\begin{eqnarray*}
    %    \mathcal{C}(t) &=& \lambda_\star \int_{0}^{\frac{\sigma t}{\eta\varepsilon}} \exp\left({\lambda_\star u}\right) u du \nonumber\\
%&=& \frac{1}{\lambda_\star} \left[\left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right) + {\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}} \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right].
%        \end{eqnarray*}           
       We can observe that the second term in \eqref{S_BGK} is collinear to $V$, ie orthogonal to Ker $D$ or $P_0 V=0$. Solving the system $M(t)F_{i+1/2}(t) = S(t)$ thus leads  to:
        \begin{eqnarray*}
        F_{i+1/2}(t) &=& M(t)^{-1} S(t) \\
        &&\hspace{-1.5cm}= P_0 \left\{F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N} + {\bf 0} \\
        &&\hspace{-1.5cm}+ (I - P_0) \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left\{F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N} + \frac{\varepsilon}{\sigma} \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x} \frac{\mathcal{C}(t) V}{\lambda_\star} \\
        &&\hspace{-1.5cm} = \left(1 - \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right)\right) \left(\rho_i^{+,n} + \rho_{{i+1}}^{-,n}\right) \bigbold{1} \\
        &&\hspace{-1.5cm}+ \exp\left({\frac{\lambda_\star \sigma (t - t_n)}{\eta \varepsilon}}\right) \left\{F_{i,j}^n \mathds{1}_{v_j > 0} + F_{i+1,j}^n \mathds{1}_{v_j < 0}\right\}_{j=1, \dots, 2N} + \frac{\varepsilon}{\sigma} \frac{ \rho_{i+1}^n - \rho_i^n}{\Delta x} \frac{\mathcal{C}(t) V}{\lambda_\star}. 
        \end{eqnarray*}
We observe that this expression and the one obtained in \cite{mieussens2013} match except for the last term 
in which half-slopes reconstructions have been used for $\rho$ in \cite{mieussens2013}. This is due to the fact that in \cite{mieussens2013}, the BGK model requires a reconstruction for $F$ and for $\rho$ which is not the case in this work. 

%        where the notations $\rho_i^+(t_n) = (\sum_{k=1}^N F_{i,j}(t_n))/(2N)$ and $\rho_i^-(t_n) = (\sum_{j=N+1}^{2N} F_{i,j}(t_n))/(2N)$ denote the half-densities associated with positive and negative velocities.


    \subsection{Some remarks for the Fokker-Planck operator} \label{subsecfp}
    To apply our scheme to  Fokker-Planck operator, we need to give a discretization of ${\cal D}$. Moreover, we  discuss how the interface value $F_{i+1/2}(t)$ behave in this case. 

    \phantomsection

    \subsubsection{Discretization of the collision operator}
        First, let recall that for the continuous Fokker-Planck operator defined by \eqref{eq:collision_operator_diff}, the eigenvalues are $\lambda_k=-k(k+1), k\in \mathbb{N}$. The zero eigenvalue is labelled by $k=0$ and the eigenvalue $\lambda_1$ is associated with the eigenfunction $v$ (which can easily recovered from    \eqref{eq:collision_operator_diff}). Let us remark that we will choose $\lambda_\star=\lambda_1$ since this is the eigenvalue which enables to get the correct diffusion limit. 

        Second, let introduce a velocity discretization  $D$ of ${\cal D}$  given by \eqref{eq:collision_operator_diff}. With the definitions introduced above, we use  {(we recall that we have chosen $c=1$ )}
        \begin{equation}
        \label{discrete_FP}
        ({\cal D}f)(v_j)\approx (DF)_j = \frac{1}{\Delta v^2}\Big((1-v_{j+1/2}^2) (F_{j+1}-F_j) - (1-v_{j-1/2}^2) (F_{j}-F_{j-1})\Big), 
        \end{equation}
        where we defined $v_{j+1/2}=(v_j+v_{j+1})/2$. 
        Using this approximation, one can check that 
        the first two eigenvalues $\lambda_0=0$ and $\lambda_1=-2$ are exactly recovered.
        \begin{proposition}
        \label{prop2}
        The discretization \eqref{discrete_FP} satisfies  $D{\bf 1}=0$ and $DV=-2V$. Besides $D$ is symmetric, its non diagonal coefficients are positive and $I+\delta D$ is  bistochastic  for $\delta>0$ small enough.
        \end{proposition}
        \begin{proof}   
         The fact that $\lambda_0=0$ is true is a direct consequence of the conservative form of the discretization \eqref{discrete_FP} 
        so that $D{\bf 1}=0$. 

        Regarding the relation, let replace $F_j$ by $v_j$ in \eqref{discrete_FP}: 
        \begin{eqnarray*}
        (D V)_j &=& \frac{1}{\Delta v^2}\Big((1-v_{j+1/2}^2) (v_{j+1}-v_j) - (1-v_{j-1/2}^2) (v_{j}-v_{j-1})\Big) \nonumber\\
        &=& \frac{1}{\Delta v^2}\Big((1-v_{j+1/2}^2) \Delta v - (1-v_{j-1/2}^2) \Delta v\Big) \nonumber\\
        &=& \frac{1}{\Delta v}(-v_{j+1/2}^2+v_{j-1/2}^2)  = -2 v_j, 
        \end{eqnarray*}
        so that $DV=-2V$ and $V$ is an  eigenvector associated to the eigenvalue $\lambda_\star=-2$. 



        By construction, we clearly have that $D$ is symmetric, its non diagonal coefficients are positive and $I+\delta D$ is a bistochastic matrix for $\delta>0$ small enough.
                \end{proof}

  %      \textcolor{blue}{(rappeler que $\lambda_\star=\lambda_1$)}

  \subsubsection{Interface value}
In the Fokker-Planck case, the eigenstructure of $D$ is more involved than in the BGK case so that the third reconstruction \eqref{third} is required to avoid the knowledge of the projectors $P_k$. However, it can be noticed that for the second reconstruction \eqref{reconstruction}, the term $\mbox{\textcircled{b}}$ defined in \eqref{termb_1} vanishes. Indeed, thanks to Prop. \ref{prop2}, one has $(D-\lambda_\star I)V=0$, even if $F^n_{i,j}$ is employed for the gradient. 

    \subsection{Some remarks for the scattering operator} \label{subsecscat}

    For scattering operator defined by \eqref{eq:collision_operator_scat},
   the resulting matrix $D$ 
    must be symmetric negative with only $\bigbold{1}$ in the kernel and  positive coefficients apart on the diagonal. 
   Spectrum and projectors are not always exactly known, thus $\lambda_\star$ has to be numerically determined from  \eqref{lambdastar} and in this case  reconstruction \eqref{discrete3} is fully justified. % since it would involve a very important numerical cost. 
    Up to our knowledge, there is no physically relevant non isotropic  1D collision   operator. Therefore, to test our approach, we  artificially define the following scattering matrix $D=\frac1{10}D_1$ with $D_1$  the periodic Laplacian matrix given by :
 $$
  {(D_1)}_{i,j} = \frac{1}{\Delta v^2}
  \begin{cases}
  \displaystyle -2, & \text{if } i = j, \\   \displaystyle 1 , & \text{if } i = j-1 [N_v] \mbox{ or }  i = j+1 [N_v] \quad (N_v=2N)
  \end{cases}
  $$
 which owns the required properties (negativity, kernel, positive coefficients).
   The factor $1/10$ is chosen so that the $\lambda_\star$ value in this case is between the one of BGK model and the one FP model. The eigenvalues of $D_1$  are known: \[
\lambda_k = -\frac{2}{\Delta v^2} \left(1 - \cos\left( \frac{2\pi k}{N_v} \right) \right), \quad k = 0, 1, \dots, N_v-1. 
\]

 \noindent  The numerical value for $\lambda_\star(D)$ is obtained by the code for $N_v=100$ is roughly $-1.49835$.
   \begin{remark} \
  \noindent    The vector $V$ is not an eigenvector since eigenvectors are discrete Fourier modes. Using Fourier analysis one gets that  when $\Delta v$ tends to zero:
 \begin{itemize}
 \item  {$D_1$ tends to the Laplacian so that $U$ obeys to $U''(v)=v \; (v\in [-1, 1]$) with periodic boundary conditions $U(1)=U(-1)$, $U$ and satisfies $\frac 12\int_{-1}^1 U(v) dv=0$  (to be in the orthogonal of  the constants). The solution $U$ is $U(v)=\frac16 v^3-\frac16v$. }

  \item One can compute the corresponding  pseudo-eigenvalue $\lambda_\star$ by considering the limit as $\Delta v\to 0$ in \eqref{lambdastar}. Using $\int_{-1}^1 U(v) v dv=-1/45$ and $\int_{-1}^1 v^2 dv=1/3$, one has 
  %Using
 %$\ds
 %\frac 12\int_{-1}^1 v^2dv=\frac13 \quad,\quad
 %\frac 12\int_{-1}^1 U(v)v dv=\frac{1}{30}-\frac1{18}=-\frac{1}{45}.
%$
% one gets:
 $$\lambda_\star(D_1): = \frac{\langle V, V \rangle}{\langle U, V \rangle} \underset{\Delta v \rightarrow 0}{\longrightarrow}\left.\left(\frac 12\int_{-1}^1 v^2dv\right)\right/\left(\frac 12\int_{-1}^1 U(v){v} dv\right)=-15. 
