  \tikzset{vertex/.style={circle,fill=white!25,minimum size=12pt,inner sep=2pt}}
  \tikzset{every loop/.style={}}%removes arrow head from all loops.
    \node[vertex] (eNc) at (-1,0) [shape=circle,dotted,draw=black,minimum size=2em] {$N$};
    \node[vertex] (eNf1) at (1,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (eNf2) at (1,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 2pt] eNc.east) to ([yshift= 0pt] eNf1.west);
    \draw[->-=.5] ([yshift= 0pt] eNf2.west) to ([yshift= -2pt] eNc.east);

    \node at (0,0.7) {\tiny$Q$};
    \node at (0,-0.7) {\tiny$\WQ$};
    \node at (0,-1.5) {$W_A=  0$};

    \node at (3.5,0.2) {$\overset{\text{Dual}}{\longleftrightarrow}$};

    \node[vertex] (mNc) at (6,0) [shape=circle,dotted,draw=black,minimum size=2em] {$\WN$};
    \node[vertex] (mNf1) at (8,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (mNf2) at (8,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 0pt] mNf1.west) to ([yshift= 2pt] mNc.east);
    \draw[->-=.5] ([yshift= -2pt] mNc.east) to ([yshift= 0pt] mNf2.west);
    \draw[->-=.5] ( mNf2.north) to ( mNf1.south);

    \node at (7,0.7) {\tiny$\Wq$};
    \node at (7,-0.7) {\tiny$q$};
    \node at (8.5,0) {\tiny$M$};
    \node at (7,-1.5) {$W_B = M\, \Wq q$};

\end{tikzpicture}
\label{eq: Seiberg quiver}
\end{equation}
%
Through the paper, we use quivers to conveniently depict various dualities. The (dotted) circular and the square nodes represent ($SU(N)$) $U(N)$ gauge and $SU(F)$ flavor symmetry groups, respectively. An arrow represents a chiral multiplet in the bi--fundamental representation, i.e., (anti)--fundamental representation under the (ending) beginning node. So, the LHS theory of \eqref{eq: Seiberg quiver} is a 4d $\CN=1$ $SU(N)$ SQCD with $F$ flavors $(Q,\WQ)$ and trivial superpotential, while the RHS theory is a $SU(\WN)$ SQCD ($\WN=F-N$) with $F$ flavors $(q,\Wq)$ and the meson--singlet coupling superpotential $W_B$ where the gauge and flavor indices are contracted. The chiral ring generators, $\WQ Q$ on the LHS are mapped to the singlets $M$ on the RHS. Such meson to singlet map is the universal feature for the other Seiberg--like dualities.




\paragraph{Aharony duality} The 3d version of the Seiberg duality was suggested by Aharony \cite{Aharony:1997gp} and named as the {\it Aharony duality}:
%
\begin{equation}
\begin{tikzpicture}%[shorten >=1pt]
  \tikzset{vertex/.style={circle,fill=white!25,minimum size=12pt,inner sep=2pt}}
  \tikzset{every loop/.style={}}%removes arrow head from all loops.
    \node[vertex] (eNc) at (-1,0) [shape=circle,draw=black,minimum size=2em] {$N$};
    \node[vertex] (eNf1) at (1,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (eNf2) at (1,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 2pt] eNc.east) to ([yshift= 0pt] eNf1.west);
    \draw[->-=.5] ([yshift= 0pt] eNf2.west) to ([yshift= -2pt] eNc.east);

    \node at (0,0.7) {\tiny$Q$};
    \node at (0,-0.7) {\tiny$\WQ$};
    \node at (0,-1.5) {$W_A=  0$};

    \node at (3.5,0.2) {$\overset{\text{Dual}}{\longleftrightarrow}$};

    \node[vertex] (mNc) at (6,0) [shape=circle,draw=black,minimum size=2em] {$\WN$};
    \node[vertex] (mNf1) at (8,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (mNf2) at (8,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 0pt] mNf1.west) to ([yshift= 2pt] mNc.east);
    \draw[->-=.5] ([yshift= -2pt] mNc.east) to ([yshift= 0pt] mNf2.west);
    \draw[->-=.5] ( mNf2.north) to ( mNf1.south);

    \node at (7,0.7) {\tiny$\Wq$};
    \node at (7,-0.7) {\tiny$q$};
    \node at (8.5,0) {\tiny$M$};
    \node at (7,-1.5) {$W_B = M\, \Wq q + V^+ \hat{v}^+ + V^- \hat{v}^-$};

\end{tikzpicture}
\label{eq: Aharony quiver}
\end{equation}
%
where the gauge groups are now unitary, $U(N)$ and $U(\WN)$ respectively ($\WN = F-N$), also there are a pair of extra singlets, $V^\pm$, on the dual side that correspond to the monopole operators $\hat V^\pm$ on the original side. Those singlets are coupled to the dual monopole operators $\hat v^\pm$ respectively as given in the superpotential $W_B$.\footnote{The monopole operators here are charged under the $U(1)_T$ topological symmetry from the diagonal of the unitary gauge group, whose charges are denoted on the upper indices of the monopole operators. We set the generators of both $U(1)_T$ topological symmetries of the dual theories, say $T$ and $T'$, such that they are mapped as $T \leftrightarrow -T'$ under the duality so that the terms $V^{\pm} \hat v^\pm$ in $W_B$ are indeed $U(1)_T$ singlets.} Although it is similar to the Seiberg duality, it took a while to figure out a correct derivation by dimensional reduction due to a non-trivial monopole superpotential effect \cite{Aharony:2013dha}. Such monopole operators play very interesting and non-trivial roles and provide rich physics in 3d supersymmetric gauge theories.

\paragraph{Benini--Benvenuti--Pasquetti (BBP) duality}
%
One such interesting application with the monopole operator is to consider a monopole superpotential deformed version of the Aharony duality as studied in \cite{Benini:2017dud}, and named as the {\it Benini--Benvenutti--Pasquetti(BBP) duality}:
%
\begin{equation}
\begin{tikzpicture}%[shorten >=1pt]
  \tikzset{vertex/.style={circle,fill=white!25,minimum size=12pt,inner sep=2pt}}
  \tikzset{every loop/.style={}}%removes arrow head from all loops.
    \node[vertex] (eNc) at (-1,0) [shape=circle,draw=black,minimum size=2em] {$N$};
    \node[vertex] (eNf1) at (1,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (eNf2) at (1,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 2pt] eNc.east) to ([yshift= 0pt] eNf1.west);
    \draw[->-=.5] ([yshift= 0pt] eNf2.west) to ([yshift= -2pt] eNc.east);

    \node at (0,0.7) {\tiny$Q$};
    \node at (0,-0.7) {\tiny$\WQ$};
    \node at (0,-1.5) {$W_A=  \hat V^\pm $};

    \node at (3.5,0.2) {$\overset{\text{Dual}}{\longleftrightarrow}$};

    \node[vertex] (mNc) at (6,0) [shape=circle,draw=black,minimum size=2em] {$\WN$};
    \node[vertex] (mNf1) at (8,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (mNf2) at (8,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 0pt] mNf1.west) to ([yshift= 2pt] mNc.east);
    \draw[->-=.5] ([yshift= -2pt] mNc.east) to ([yshift= 0pt] mNf2.west);
    \draw[->-=.5] ( mNf2.north) to ( mNf1.south);

    \node at (7,0.7) {\tiny$\Wq$};
    \node at (7,-0.7) {\tiny$q$};
    \node at (8.5,0) {\tiny$M$};
    \node at (7,-1.5) {$W_B = \hat v^\pm + M\, \Wq q + V^\mp \hat{v}^\mp$};

\end{tikzpicture}
\label{eq: BBP quiver}
\end{equation}
%
where the rank of the dual gauge group is reduced by one, $\WN = F-N-1$, compared to the Aharony duality. Let us denote this duality as $\text{BBP}^\pm$. If we consider $\text{BBP}^+$, for instance, the monopole operator $\hat V^-$ is mapped to a singlet $V^-$ that couples to the dual monopole operator $\hat v^-$ in the RHS theory, while the monopole operator $\hat V^+$ is directly mapped to the dual monopole operator $\hat v^+$.
%

Let us consider a further deformation at the LHS theory by the other monopole operator, i.e., $W_A = \hat V^+ + \hat V^-$, then one can check that a successive dualization as in \eqref{eq: BBP2 quiver} along the counterclockwise direction achieves another BBP duality:
%
\begin{equation}
\centering
\begin{tikzpicture}%[shorten >=1pt]
  \tikzset{vertex/.style={circle,fill=white!25,minimum size=12pt,inner sep=2pt}}
  \tikzset{every loop/.style={}}%removes arrow head from all loops.
    % Theory A
    \node[vertex] (eNc) at (-1,0) [shape=circle,draw=black,minimum size=2em] {$N$};
    \node[vertex] (eNf1) at (1,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (eNf2) at (1,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 2pt] eNc.east) to ([yshift= 0pt] eNf1.west);
    \draw[->-=.5] ([yshift= 0pt] eNf2.west) to ([yshift= -2pt] eNc.east);

    \node at (0,0.7) {\tiny$Q$};
    \node at (0,-0.7) {\tiny$\WQ$};
    \node at (0,-1.5) {\scriptsize$W_A=  \hat V^+ + \hat V^- $};

    \node at (3.5,0.2) {$\overset{\text{Dual}}{\longleftrightarrow}$};

    % Theory B
    \node[vertex] (mNc) at (6,0) [shape=circle,draw=black,minimum size=2em] {$\WN$};
    \node[vertex] (mNf1) at (8,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (mNf2) at (8,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 0pt] mNf1.west) to ([yshift= 2pt] mNc.east);
    \draw[->-=.5] ([yshift= -2pt] mNc.east) to ([yshift= 0pt] mNf2.west);
    \draw[->-=.5] ( mNf2.north) to ( mNf1.south);

    \node at (7,0.7) {\tiny$\Wq$};
    \node at (7,-0.7) {\tiny$q$};
    \node at (8.5,0) {\tiny$M$};
    \node at (7,-1.5) {\scriptsize$W_B = \hat v^+ + \hat v^- + M\, \Wq q$};

    % Theory A'
    \node[vertex] (eeNc) at (-1,-4) [shape=circle,draw=black,minimum size=2em] {$N'$};
    \node[vertex] (eeNf1) at (1,-4+0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (eeNf2) at (1,-4-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5]  ([yshift= 0pt] eeNf1.west) to ([yshift= 2pt] eeNc.east);
    \draw[->-=.5]  ([yshift= -2pt] eeNc.east) to ([yshift= 0pt] eeNf2.west);
    \draw[->-=.5] ( eeNf2.north) to ( eeNf1.south);

    \node at (0,-4+0.7) {\tiny$q'$};
    \node at (0,-4-0.7) {\tiny$\Wq'$};
    \node at (1.5,-4) {\tiny$M'$};
    \node at (0.5,-4-1.5) {\scriptsize$W_{A'}=  \hat U^+ + V^- + V^-\hat U^- + M'\Wq'q'$};

    \node at (3.5,-4+0.2) {$\overset{\text{Aharony}}{\longleftrightarrow}$};

    % Theory B'
    \node[vertex] (mmNc) at (6,-4) [shape=circle,draw=black,minimum size=2em] {$\WN'$};
    \node[vertex] (mmNf1) at (8,-4+0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (mmNf2) at (8,-4-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[->-=.5] ([yshift= 2pt] mmNc.east) to ([yshift= 0pt] mmNf1.west);
    \draw[->-=.5] ([yshift= 0pt] mmNf2.west) to ([yshift= -2pt] mmNc.east);

    \node at (7,-4+0.7) {\tiny$\WQ'$};
    \node at (7,-4-0.7) {\tiny$Q'$};
    \node at (7,-4-1.5) {\scriptsize$W_{B'} = U^+ + \hat u^- + U^+ \hat u^+$};

    % arrows
    \node at (-0.7,-2.5) {\scriptsize$\text{BBP}^+$};
    \node at (0,-2.5){$\updownarrow$};

    \node at (7+0.7,-2.5) {\scriptsize$\text{BBP}^-$};
    \node at (7,-2.5){$\updownarrow$};

\end{tikzpicture}
\label{eq: BBP2 quiver}
\end{equation}
%
where the dual gauge rank is now reduced by two compared to the Aharony duality,
%
\begin{align}
    \WN &= F - \WN'-1
    \nonumber\\
    & = F - (F-N') - 1
    \nonumber\\
    & = F - \big( F - (F - N - 1) \big) - 1
    \nonumber\\
    & = F - N - 2 \,,
\end{align}
%
and the monopole operators $\hat V^\pm$ are successively mapped along the process to $\hat v^\pm$:
%
\begin{align}
    &\hat V^+ 
    \;\;\rightarrow\;\;
    \hat U^+
    \;\;\rightarrow\;\;
    U^+
    \;\;\rightarrow\;\;
    \hat v^+
    \nonumber\\
    &\hat V^-
    \;\;\rightarrow\;\;
    V^-
    \;\;\rightarrow\;\;
    \hat u^-
    \;\;\rightarrow\;\;
    \hat v^-
\end{align}
%
This was also proposed in the same paper which we will denote as $\text{BBP}_2$. The duality chain \eqref{eq: BBP2 quiver} tells us that $\text{BBP}_2$ can be understood from the Aharony and $\text{BBP}^\pm$ dualities. Conversely, the Aharony and $\text{BBP}^{\pm}$ can be obtained from real mass deformations on $\text{BBP}_2$ \cite{Hwang:2020wpd}. The point is that the Aharony and BBP dualities are not independent but closely related to each other.
%

\paragraph{Kim--Park(KP) duality}
%
Another way to generalize the Aharony duality is to add tensorial matters. One plausible attempt would be adding a chiral multiplet in the adjoint representation with a monomial superpotential, which was studied in \cite{Kim:2013cma} and named, the {\it Kim--Park duality}:
%
\begin{equation}
\begin{tikzpicture}%[shorten >=1pt]
  \tikzset{vertex/.style={circle,fill=white!25,minimum size=12pt,inner sep=2pt}}
  \tikzset{every loop/.style={}}%removes arrow head from all loops.
    \node[vertex] (eNc) at (-1,0) [shape=circle,draw=black,minimum size=2em] {$N$};
    \node[vertex] (eNf1) at (1,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (eNf2) at (1,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[-to, min distance=1cm]  (eNc) edge [out=150, in=210] node {} (eNc);
    \draw[->-=.5] ([yshift= 2pt] eNc.east) to ([yshift= 0pt] eNf1.west);
    \draw[->-=.5] ([yshift= 0pt] eNf2.west) to ([yshift= -2pt] eNc.east);

    \node at (-1.6,0.6) {\tiny$X$};
    \node at (0,0.7) {\tiny$Q$};
    \node at (0,-0.7) {\tiny$\WQ$};
    \node at (0,-1.5) {$W_A=  \Tr X^{p+1}$};

    \node at (3.5,0.2) {$\overset{\text{Dual}}{\longleftrightarrow}$};

    \node[vertex] (mNc) at (7,0) [shape=circle,draw=black,minimum size=2em] {$\WN$};
    \node[vertex] (mNf1) at (9,0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};
    \node[vertex] (mNf2) at (9,-0.7) [shape=rectangle,draw=black,minimum height=2em, minimum width=2em] {$F$};

    \draw[-to, min distance=1cm]  (mNc) edge [out=150, in=210] node {} (mNc);
    \draw[->-=.5] ([yshift= 0pt] mNf1.west) to ([yshift= 2pt] mNc.east);
    \draw[->-=.5] ([yshift= -2pt] mNc.east) to ([yshift= 0pt] mNf2.west);
    \draw[->-=.5] ( mNf2.north) to ( mNf1.south);

    \node at (6.4,0.6) {\scriptsize$x$};
    \node at (8,0.7) {\tiny$\Wq$};
    \node at (8,-0.7) {\tiny$q$};
    \node at (9.5,0) {\tiny$M_i$};
    \node at (8,-1.5) {$W_B = \Tr x^{p+1} \!+\! M_i \,\Wq x^{p\texttt{-}i\texttt{-}1} q + V_{p\texttt{-}i\texttt{-}1}^+ \hat v_{i}^+ + V_{p\texttt{-}i\texttt{-}1}^- \hat v_{i}^-$};

\end{tikzpicture}
\label{eq: KP quiver}
\end{equation}
%
with dual gauge rank $\WN = pF-N$, $X$ and $x$ are the adjoint chiral multiplets, that give rise to $p$ pairs of monopole operators by dressing powers of them to the bare monopole operators:
%
\begin{align}
    \hat V_i^\pm \equiv \Tr_{U(N-1)}' X^i \hat V_0^\pm
    \quad,\quad
    \hat v_i^\pm \equiv \Tr_{U(\WN-1)}' x^i \hat v_0^\pm
    \label{eq: dressed monopole}
\end{align}
%
for $i=0,\cdots,p-1$. Here the traces are taken over the unbroken $U(N-1)$ and $U(\WN-1)$ sectors of the background magnetic fluxes $m = (\pm 1,0,\cdots,0)$ by the bare monopole operators $\hat V_0^\pm$ and $\hat v_0^\pm$ respectively. We use $\Tr' X^n$ to conveniently denote a possible linear combination of products of traces $\Tr X^{i_1} \Tr X^{i_2}\cdots \Tr X^{i_l}$ with $i_1+i_2+\cdots+i_l=n$ such that each factor is free from the trace relation by the gauge rank in consideration\footnote{See \cite{Hwang:2018uyj,Hwang:2022jjs} for more rigorous explanations from the operator-state correspondence with examples.}. The truncation of the dressing number is due to the F-term equation $X^p = 0$. We explicitly leave the indices $i$ in the superpotential $W_B$ for the summations over $i=0,\cdots,p-1$. The monopole operators $\hat V_i^\pm$ in the LHS are mapped to the singlets $V_i^\pm$ in the RHS that couple to the dual monopole operators $\hat v_{p\texttt{-}i\texttt{-}1}^\pm$. Likewise, the mesons, $\WQ X^i Q$, $i=0,\cdots,p-1$ in the LHS are mapped to the singlets, $M_i$ in the RHS. Note that when $p=1$, the adjoints in both sides become massive, exactly reproducing the Aharony duality. In this sense, the KP duality is a natural generalization of the Aharony duality.


