    \node at (9.5,0) {\tiny$M_i$};
    \node at (8,-1.5) {$W_B = \hat v_\a^+ + \hat v_\a^- + \Tr x^{p+1} \!+\! M_i \,\Wq x^{p\texttt{-}i\texttt{-}1} q$};

