%
\begin{align}
    W_A = \hat V_\a^+ + \hat V_\b^- + \Tr X^{p+1}
\end{align}
%
and since there is a linear term of the $\a$-th dressed monopole operator $\hat V_\a^+$, we can apply $\text{KP}_\a^+$ to get, $U(N')$ SQCD ($N'=pF-N-p+\a$) with $F$ flavors $(q',\Wq')$, adjoint $x'$, and superpotential,
%
\begin{align}
    W_{A'} & = \hat U_\a^+ + V_\b^- + \Tr x'^{p+1} + V_i^-\,\hat U_{p\texttt{-}i\texttt{-}1}^- + M_i'\,\Wq' x'^{p-i-1} q'
\end{align}
%
where the monopole operators of positive charge are mapped to the monopole operators as, $\hat V_i^+ \to \hat U_i^+$, while the negatively charged ones are mapped to singlets $\hat V_i^- \to V_i^-$ that couple to dual monopole operators $\hat U_{p-i-1}^-$. The mesons are mapped to singlets, $\WQ X^i Q \to M_i'$ coupled to dual mesons $\Wq' x^{p-i-1} q'$. Next, we apply the KP duality to get $U(\WN')$ SQCD $(\WN' = pF - N')$ with $F$ flavors $(Q',\WQ')$, adjoint $X'$, and superpotential,
%
\begin{align}
    W_{B'} & = U_\a^+ + V_\b^- + \Tr X'^{p+1} + V_i^- \, U_{p\texttt{-}i\texttt{-}1}^- + M_i' \, m_{p\texttt{-}i\texttt{-}1}
    \nonumber\\
    &\qquad + m_{p\texttt{-}i\texttt{-}1}\, \WQ' X'^i Q
    + U_{p\texttt{-}i\texttt{-}1}^+ \hat u_{i}^+ + U_{p\texttt{-}i\texttt{-}1}^- \hat u_{i}^-
\end{align}
%
where the monopole operators are mapped to singlets, $\hat U_i^\pm \to U_i^\pm$, coupled to dual monopoles $\hat u_{p\texttt{-}i\texttt{-}1}^\pm$, and the mesons are mapped to singlets, $\Wq' x'^i q' \to m_i$, coupled to dual mesons $\WQ' X'^i Q'$. By integrating out the massive singlets $V_i^-$, $U_{i}^-$, $M_i'$, and $m_i$, we get,
%
\begin{align}
    W_{B'} = U_\a^+ + \hat u_\b^- + \Tr X'^{p+1} + U_{p-i-1}^+\,\hat u_i^+
    \,.
\end{align}
%
Thanks to the linear monopole term $\hat u_\b^-$, we can apply $\text{KP}_\b^-$ to obtain $U(\WN)$ SQCD ($\WN = pF - \WN' - p + \b$) with $F$ flavors $(q,\Wq)$, adjoint $x$, and superpotential,
%
\begin{align}
    W_B = \hat v_\a^+ + \hat v_\b^- + \Tr x^{p+1} + M_i\,\Wq x^{p\texttt{-}i\texttt{-}1}q
\end{align}
%
where the mesons are mapped to singlets, $\WQ' X'^i Q' \to M_i$, coupled to dual mesons, $\Wq x^{p\texttt{-}i\texttt{-}1} q$, and the negatively charged monopoles are mapped to the dual monopoles of negative charge, $\hat u_i^- \to \hat v_i^-$, while the positively charged ones are mapped to singlets, $\hat u_i^+ \to u_i^+$, which are massive and integrated out, generating the linear term $\hat v_\b^-$. This completes the derivation.
%

%
The symmetry charges of the chiral rings and their map along the derivation are summarized in Table \ref{tab: two monopole KP chiral ring map} with the resulting chiral ring map,
%
\begin{align}
    \Tr X^i \qquad&\longleftrightarrow\qquad \Tr x^i
    \nonumber\\
    \WQ X^i Q \qquad&\longleftrightarrow\qquad M_i
    \nonumber\\
    \hat V_i^\pm \qquad&\longleftrightarrow\qquad \hat v_i^\pm
\end{align}
%
where the Coulomb branch parametrized by $\hat V_j^+$, $\hat v_j^+$ for $j\geq\a$, and $\hat V_l^-$, $\hat v_l^-$ for $l\geq\b$ are lifted \cite{Hwang:2022jjs}. As a duality check, we could confirm the perfect matching of the superconformal indices of the dual theories in $\text{KP}_{\a,\b}$ which is rather guaranteed by the KP and $\text{KP}_\a^\pm$ dualities, see appendix \ref{app: index result}.
%


