    %
    \begin{align}
        \mathcal{S}_2 :=
        \big\{ (p,\a,\b)\,\big|\, \b\neq p-1,\; p\!\!\!\!\!\mod 2 = \a \!\!\!\!\! \mod 2 = 0 \;\text{or}\; 1 \big\}
    \end{align}
    %
