\subsection{$S_b^3$ partition function and diagrammatic expression} \label{app: ptf quiver diagram}
%
Let us review the localization formula of the squashed three-sphere partition function \cite{Hama:2011ea} and its identities from the basic $3d$ $\CN=2$ IR dualities. We also provide a recipe for reading the formula from a given quiver diagram.
%

%
The squashed three-sphere partition function of a $3d$ $\CN=2$ gauge theory with gauge group $G$ and a set of chiral multiplets, collectively denoted by $\Phi$, having $R$-charge $r_\Phi$ and charged under the gauge and global symmetries with weights $\r_\Phi$ and $\phi_\Phi$ of representation $R_\Phi$ and $R_\phi$ respectively, with real mass parameter $M$, is given by an integral over the Coulomb branch parameter $\s$ as follows:
%
\begin{align}
    Z_{S_b^3} = \frac{1}{|W|} 
    \int \prod_{j=1}^{\text{rank}(G)}\!\!\! d \s_j\;
    e^{2\pi i \z \Tr \s}
    \frac{
    \prod_{\Phi} \prod_{\r_\Phi \in R_\Phi} \prod_{\phi_\Phi \in R_\phi} s_b (\frac{i Q}{2}(1-r_\Phi) - \rho_\Phi(\s) - \phi_\Phi(M) )
    }
    {
    \prod_{\a\in \text{root}} s_b(\a(\s) + \frac{i Q}{2})
    }
    \label{eq: S_b^3 ptf integral formula}
\end{align}
%
where $W$ is the Weyl group of $G$, $Q\equiv b + b^{-1}$ parametrizes the squashing parameter $b$, $\a$ runs over the roots of the gauge group $G$, and $\z$ is the Fayet-Illiopoulos parameter for the $U(1)$ factors in $G$. The double-sine function $s_b(x)$ is defined by
%
\begin{align}
    s_b(x) := \prod_{l,n\geq 0}
    \frac{l b + n b^{-1} + Q/2 - i x}{l b + n b^{-1} + Q/2 + i x} \,,
\end{align}
%
which satisfies a property $s_b(x) s_b(-x) = 1$ reflecting a cancellation of the contributions of two coupled massive chiral fields. There is an alternative way for the partition function evaluation by using geometric manipulations, so-called the A-model approach \cite{Closset:2018ghr,Closset:2019hyt,Closset:2023vos,Closset:2023jiq,Closset:2023bdr,Closset:2023izb,Closset:2024sle,Closset:2025lqt}, which does not involve integrals but summing the fibering and the handle gluing operators over Bethe vacua at rational values of the squared squashing parameter $b^2 \in \mathbb{Q}$.
\\

%
Let us present the partition function identities of the Aharony and BBP dualities:
%
\paragraph{Aharony duality}
%
\begin{align}
    &\frac{1}{N!} \int \prod_{j=1}^{N} d\s_j
    e^{\pi i \z \sum_{j=1}^{N} \s_j}
    \frac{\prod_{j=1}^{N} \prod_{a=1}^{F}s_b( \s_j - m_a + i Q/2 )\prod_{b=1}^{F} s_b(-\s_j - \Wm_b + i Q/2) }
    {\prod_{i\neq j}^{N} s_b(\s_i - \s_j + i Q/2)}
    \nonumber\\
    &=s_b\Big( \frac{iQ}{2}(N-F)+\frac{\sum_{a=1}^{F} m_a +\sum_{b=1}^{F} \Wm_b}{2} \pm \frac{\z}{2} \Big)
    \prod_{a,b=1}^{F} s_b (-m_a - \Wm_b + iQ/2)
    \nonumber\\
    &\quad\times
    \frac{1}{(F - N)!} \int \prod_{j=1}^{F - N}d\s_j
    e^{\pi i (-\z) \sum_{j=1}^{F_N} \s_j}
    \frac{\prod_{j=1}^{F-N} \prod_{a=1}^{F}s_b( -\s_j + m_a)\prod_{b=1}^{F} s_b(\s_j + \Wm_b) }
    {\prod_{i\neq j}^{F-N} s_b(\s_i - \s_j + i Q/2)}
    \label{eq: Aharony int}
\end{align}
%
where we have used a shorthand notation $s_b(x \pm y )\equiv s_b(x+y)s_b(x-y)$.
%

\paragraph{One-monopole BBP duality}
%
\begin{align}
    &\frac{1}{N} \int \prod_{j=1}^{N} d\s_j
    e^{\pi i \z \sum_{j=1}^{N} \s_j}
    \frac{\prod_{j=1}^{N} \prod_{a=1}^{F}s_b( \s_j - m_a + i Q/2 )\prod_{b=1}^{F} s_b(-\s_j - \Wm_b + i Q/2) }
    {\prod_{i\neq j}^{N} s_b(\s_i - \s_j + i Q/2)}
    \nonumber\\
    &=s_b\Big( \frac{iQ}{2}(N\!-\!F)+\frac{\sum_{a=1}^{F} m_a \!+\!\sum_{b=1}^{F} \Wm_b}{2} \!+\! \frac{\z}{2} \Big)
    \prod_{a,b=1}^{F}\!\! s_b (iQ/2 -m_a - \Wm_b )
    e^{-\frac{\pi i}{2}\sum_{a=1}^{F} (m_a^2 - \Wm_a^2) }
    \nonumber\\
    &\quad\times
    \frac{1}{\WN !} \int \prod_{j=1}^{\WN}d\s_j
    e^{\pi i (-\z+iQ) \sum_{j=1}^{\WN} \s_j}
    \frac{\prod_{j=1}^{\WN} \prod_{a=1}^{F}s_b( -\s_j + m_a)\prod_{b=1}^{F} s_b(\s_j + \Wm_b) }
    {\prod_{i\neq j}^{\WN} s_b(\s_i - \s_j + i Q/2)}
    \label{eq: BBP int}
\end{align}
%
where $\WN = F - N - 1$ and the condition for monopole superpotential is given as
%
\begin{align}
    \sum_{a=1}^{F} m_a + \sum_{b=1}^{F}\Wm_b = \z + iQ(F - N - 1).
    \label{eq: BBP1 condition}
\end{align}
%

\paragraph{Partition function from a quiver diagram}
%
It is convenient to use a quiver diagram for the integral expressions of the partition function. Let us provide a recipe for it:
%
\begin{equation}
    \begin{tikzpicture}[baseline={([yshift=-.5ex]current bounding box.center)}]
  \tikzset{vertex/.style={circle,fill=white!25,minimum size=12pt,inner sep=2pt}}
  \tikzset{every loop/.style={}}%removes arrow head from all loops.
    \node[vertex] (N) at (0,0) [shape=circle,draw=black,minimum size=2em] {$N$};
    \node at (0,-0.6) {\scriptsize $\eta$};
    \end{tikzpicture}
    \;\;\Longleftrightarrow \;\;
    \frac{1}{N!} \int \prod_{i=1}^{N} d\s_i \; e^{\pi i\; \frac{iQ}{2}\eta \sum_{i=1}^{N} \s_i} \frac{1}{\prod_{i\neq j}^{N} s_b ( \s_i - \s_j + \frac{iQ}{2} )} \,,
    \label{eq: circular node}
\end{equation}
%
\begin{equation}
\begin{tikzpicture}[baseline={([yshift=-.5ex]current bounding box.center)}]
  \tikzset{vertex/.style={circle,fill=white!25,minimum size=12pt,inner sep=2pt}}
  \tikzset{every loop/.style={}}%removes arrow head from all loops.
    \node[vertex] (N) at (0,0) {$N$};
    \node[vertex] (M) at (1.5,0) {$M$};
    \node at (0.7,0.3) {$\D$};
    \draw[->-=.55] ([yshift= 0pt] N.east) to ([yshift= 0pt] M.west);
    \end{tikzpicture}
    \;\;\Longleftrightarrow\;\;
    \prod_{i=1}^{N} \prod_{j=1}^{M} 
    s_b \Big( y_j - x_i + \frac{iQ}{2}(1-\D) \Big) \,,
    \qquad\qquad
    \label{eq: arrow}
\end{equation}
%
\begin{equation}
    +\big\{\D\big\}
    \;\;\Longleftrightarrow\;\;
    s_b \Big(\frac{iQ}{2}(1-\D) \Big) \,.
    \qquad\qquad\qquad
    \label{eq: singlet}
\end{equation}
%
The circular node \eqref{eq: circular node} represents $U(N)$ gauge group and we associate it with an integration over the Coulomb branch parameter $\s_j$ with a vector multiplet contribution and the FI parameter $\eta$ written under the node.\footnote{For convenience, we use a different normalization for the FI parameter compared to the one in \eqref{eq: S_b^3 ptf integral formula}, which are related by $\z = \frac{iQ}{2}\eta$.} An arrow in \eqref{eq: arrow} between two nodes, either circular (gauge) or square (flavor), represents a chiral multiplet contribution in the (anti-)fundamental representation of the $U(N)$ ($U(M)$) node whose fugacities are $x_i$ $(y_j)$ with real mass parameter $\D$.\footnote{Similar to the FI parameter, the real mass parameter here is normalized as $\D = \frac{2}{iQ} m+r$ where $m$ is an original real mass parameter appearing in \eqref{eq: S_b^3 ptf integral formula} and $r$ is the R-charge of the chiral multiplet.} We also put a list of real masses with curly-bracket as in \eqref{eq: singlet} to represent extra singlet contributions. For example, the Aharony and BBP dualities in a general linear quiver can be drawn instead of the integrals \eqref{eq: Aharony int} and \eqref{eq: BBP int} as:
