\subsection{$S^3$ partition function and F-maximization} \label{app: f-max result}
%
The proposed duality in the main paper assumes relevance of the monopole superpotential deformation that can be checked using the F-maximization \cite{Jafferis:2010un}, which states that the three-sphere free energy of a 3d $\CN=2$ theory,
%
\begin{align}
    F_{S^3} = - \log |Z_{S^3}|\,,
\end{align}
%
is maximized at the superconformal fixed point. Namely, the superconformal R-charges, or the conformal dimensions of the chiral operators are determined by maximizing the free energy $F_{S^3}$. Since only the operator of the conformal dimension less than two can trigger an RG flow to a distinct new IR fixed point, we call the operator as relevant. We follow the convention of \cite{Pufu:2016zxm} for the computation of the $S^3$-partition function $Z_{S^3}$:
%
\begin{align}
    Z_{S^3} = \frac{1}{|W|} 
    \int \prod_{i=1}^{\text{rank}(G)}\!\!\! d \s_i
    \,
    e^{-2\pi \t \Tr \s}
    \prod_{\a\in\text{root}} \big( 2 \sinh(\pi \a(\s))\big)
    \prod_{\Phi} \prod_{\r_\Phi \in R_\Phi}
    e^{l\big(1-r_\Phi + i \r_\Phi(\s)\big)}
\end{align}
%
with
%
\begin{align}
    l(z) := -z\, \log(1-e^{2\pi i\, z})
    + \frac{i}{2} \Big(
    \pi z^2 + \frac{1}{\pi} \text{Li}_2 \big( e^{2\pi i\, z} \big)
    \Big) - \frac{\pi i }{12}
\end{align}
%
where $\t$ is the FI parameter that corresponds to the mixing parameter for $U(1)_T$ topological symmetry, $\Phi$ runs for chiral multiplets of R-charge $r_\Phi$ with representation $R_\Phi$ whose weights are $\r_\Phi$. A subtlety in the F-maximization procedure is that one needs to take care about the decoupling operator hitting the unitary bound of the conformal dimension 1/2. Once there arises a decoupling operator, it should be extracted from the theory by introducing a flip field that couples to it in the superpotential and repeat the procedure until there is no decoupling operator in the IR fixed point. 
%

%
In the following, we perform F--maximization for 3d $\CN=2$ SQCD of $U(N)$ gauge group with $F$ flavors $(Q,\WQ)$ and an adjoint, $X$, of superpotential $\Tr X^{p+1}$ for various choices of $p$, $N$, and $F$, with $N\leq 3$. If we denote the superconformal R-charge of flavors as $\D_Q$, then the superconformal R-charge of the dressed monopole operator becomes,
%
\begin{align}
    R_\a^\pm :=
    R[\hat V_\a^\pm] = F(1-\D_Q) - \frac{2}{p+1}(N-1-\a) \pm \t\,.
\end{align}
%
where $\t$ is the mixing parameter of the $U(1)_T$ topological symmetry. We begin by assuming a fixed point with superpotential $W= \Tr X^{p+1}$, which we denote $\CT$. At $\CT$, we check the relevance of the monopole operators $\hat V_\a^+$. If $\hat V_\a^+$ is a relevant operator, deform $\CT$ by $\D W_1 = \hat V_\a^+$ to get a new fixed point by RG flow, say $\CT_\a$, in which case we achieve the IR fixed point for $\text{KP}_\a^+$ duality. If this is the case, we check the relevance of $\hat V_\b^-$ further here. If $\hat V_\b^-$ is also relevant, we can get a fixed point for the $\text{KP}_{\a,\b}$ duality by deforming with it, say $\CT_{\a,\b}$. Here we enumerate detailed processes for various cases:
\\
%
\paragraph{$\ast \;\; U(1)$ gauge group}
%
\begin{itemize}
    \item $(p,F)=(2,2)\;:$
    %
    At $\CT$, $R_0^+ = 1.1829$ so that we can flow to $\CT_0$ and $\CT_1$. At $\CT_0$ and $\CT_1$, we find $R_0^- = 0.78983$, $1.1113$ respectively so that we achieve fixed points $\CT_{0,0},\CT_{1,0},\CT_{0,1}$, and $\CT_{1,1}$.

    \item $(p,F)=(2,3)\;:$
    %
    At $\CT$, $R_0^+ = 1.6891$ so that we can flow to $\CT_0$ where we find $R_0^- = 1.5439$, achieving a fixed point $\CT_{0,0}$.

    \item $(p,F)=(3,2)\;:$
    %
    At $\CT$, $R_0^+ = 1.1829$ so that we can flow to $\CT_0$ and $\CT_1$ where we find $R_0^- = 0.7898,1.03139$ respectively, achieving fixed points $\{\CT_{0,\b}\}_{\b\leq 2}$ and $\{\CT_{1,\b}\}_{\b\leq 1}$.

    \item $(p,F)=(3,3)\;:$
    %
    At $\CT$, $R_0^+ = 1.6891$ so that we can flow to $\CT_0$ where we find $R_0^- = 1.5439$, achieving a fixed point $\CT_{0,0}$.

    \item $(p,F)=(4,2)\;:$
    %
    At $\CT$, $R_0^+ = 1.1829$ so that we can flow to $\{\CT_\a\}_{\a=0,1,2}$ where we find $R_0^- = 0.7898,0.9833,1.1748$ respectively, achieving fixed points $\{\CT_{0,\b}\}_{\b\leq 3}$,$\{\CT_{1,\b}\}_{\b\leq 2}$ and $\{\CT_{2,\b}\}_{\b\leq 2}$.

    \item $(p,F)=(5,2)\;:$
    %
    At $\CT$, $R_0^+ = 1.1829$ so that we can flow to $\{\CT_\a\}_{\a=0,1,2}$ where we find $R_0^- = 0.7898,0.9511,1.1113$ respectively, achieving fixed points $\{\CT_{0,\b}\}_{\b\leq 3}$,$\{\CT_{1,\b}\}_{\b\leq 3}$ and $\{\CT_{2,\b}\}_{\b\leq 2}$.
\end{itemize}
%
\paragraph{$\ast \;\; U(2)$ gauge group}
%
\begin{itemize}
    \item $(p,F)=(2,2)\;:$
    %
    At $\CT$, $R_0^+ = 0.7322$ so that we can flow to $\{\CT_\a\}_{\a=0,1}$. For $\a=0$, we need to flip $\WQ Q$ and $\WQ X Q$ to get $R_0^- = 3.1201$ so that no further relevant monopole deformation is possible. For $\a=1$, we should flip $\WQ Q$ to get $R_0^- = 0.5509$, achieving fixed points $\{\CT_{1,\b}\}_{\b\leq 2}$.

    \item $(p,F)=(2,3)\;:$
    %
    At $\CT$, $R_0^+ = 1.2313$ so that we can flow to $\{\CT_\a\}_{\a=0,1}$ where we find $R_0^- = 0.8637,1.1818$ respectively, achieving fixed points $\{\CT_{0,\b}\}_{\b\leq 1}$ and $\{\CT_{1,\b}\}_{\b\leq 1}$.

    \item $(p,F)=(2,4)\;:$
