	\noindent \textbf{Notations.} If $X$ is a finite set, we use $\# X$ to denote its cardinality. If $X$ is a measurable set, we use $|X|$ to denote its Lebesgue measure. We use $B^N(c,r)$ to represent a closed ball centered at $c$ with radius $r$ in $\mathbb{R}^N$. We abbreviate $B^{N}(c,r)$ to $B(c,r)$ if $\mathbb{R}^{N}$ is clear in the content, and abbreviate $B(0,R)$ to $B_R$. We write $A\lesssim_\epsilon B$ to mean that there exists a constant $C$ depending on $\epsilon$ such that $A\leq CB$. Moreover, $A \sim B$ means $A \lesssim B$ and $A\gtrsim B$. Define $e(b):=e^{ i b}$ for each $b \in \mathbb{R}$. Let $p'$ denote the dual exponent of $p$, i.e., $1/p+1/p'=1$. For any $m_1,m_2\in\N^+$, let $\R^{m_1\times m_2}$ denote the space of all real $m_1\times m_2$ matrices. For any $m \in \N^+$, let ${\rm O}(m,\R)$ denote the real orthogonal group of order $m$, ${\rm GL}(m,\R)$ denote the real general linear group of order $m$, ${\rm SL} (m,\R)$ denote the real special linear group of order $m$, ${\rm S}(m,\R)$ denote the space of all real symmetric matrices of order $m$. Let $I$ be the identity matrix whose order is always adapted to the context.

    Suppose that $S_\psi \coloneqq \{ (\xi,\psi(\xi)): \xi \in U \}$ is a graph in $\mathbb{R}^{d+n}$, where $U$ is a bounded open/closed region of $\R^d$ and $\psi:U\rightarrow\R^n$ is a smooth function. Then we define 
    $$N_{\delta}(S_\psi|_U):=\big\{(\xi,\psi(\xi) + t): \xi\in U , ~|t|<\delta\big\}.$$
	And we abbreviated $N_{\delta}(S_\psi|_U)$ as $N_{\delta}(S_\psi)$ if $U=[0,1]^d$.

	We say that a set $Z \in \mathbb{R}^d$ is called a semi-algebraic set if it can be written as a finite union of sets of the form
	\begin{equation}\label{sg1}
		\{  x\in \mathbb{R}^d:~P_1(x) = 0,...,P_{l}(x)=0,P_{l+1}(x)>0,...,P_{l+k}(x)>0   \},  
	\end{equation}
	where $P_1$,..., $P_{l+k}$ are polynomials. Define the complexity of $Z$ to be the smallest sum
	of the degrees of the polynomials appearing in all possible descriptions (\ref{sg1}). Define the dimension of $Z$ to be the Hausdorff dimension of the set $Z$.


	For any ball $B=B(c_B,K)$ with $K\geq 1$, we define $w_B$ as
    \begin{equation}\label{notation_wb}
        w_B(x):=\Big(   1+ \frac{|x-c_B|}{K} \Big)^{-100(d+n)}.
    \end{equation}

    Let $\dot{P}_d^\kappa$ be the space of all real homogeneous polynomials of degree $\kappa$ in $d$ variables.

    Define the surface measure of $S_\mathbf{Q}$ to be $\mu_\mathbf{Q}^* \coloneqq \mu_\mathbf{Q}\chi_{[0,1]^d}$, i.e., $$d\mu_\mathbf{Q}^*(\xi,\eta) \coloneqq \chi_{[0,1]^d}(\xi) d\mu_\mathbf{Q}(\xi,\eta), \qquad \forall\,(\xi,\eta)\in\R^d\times\R^n.$$





	\section{Preliminaries}\label{secadd2}

	In this section, we will introduce some notations and basic tools. Readers only interested in Theorem~\ref{th1} may safely skip Subsection~\ref{obe_aff_cur_con_sec2_1}.



    \subsection{Several versions of decoupling}\label{dec_qua_man_sec2_2}\phantom{x}

	For $p\geq 2$, by Definition \ref{decouping def for high codim}, we have\footnote{For simplicity, we will suppress technicalities like ``for all $f$ supported on $[0,1]^d$, all dyadic $K\geq1$, and all $\epsilon>0$''.}
    \begin{equation}\label{eq:decoupling_extension_2}
        \|E^{\mathbf{Q}}f\|_{L^p(\R^{d+n})} \lesssim_\epsilon K^{\Gamma_{p}^d(\mathbf{Q})+\epsilon} \Big(   \sum_{\tau} \|E^{\mathbf{Q}}f_\tau\|_{L^p(\R^{d+n})}^2  \Big)^{\frac{1}{2}},
    \end{equation}
    where $\{\tau\}$ is the partition of $[0,1]^d$ into $K^{-1}$-cubes, and $f=\sum_\tau f_\tau =\sum_\tau f\chi_\tau$. 

    It is a kind of folklore that (\ref{eq:decoupling_extension_2}) has several essentially equivalent formulations, such as the local version:
    \begin{equation}\label{eq:decoupling_extension_3}
        \|E^{\mathbf{Q}}f\|_{L^p(B_{K^{2}})} \lesssim_\epsilon K^{\Gamma_{p}^d(\mathbf{Q})+\epsilon} \Big(   \sum_\tau \|E^{\mathbf{Q}}f_\tau\|_{L^p(w_{B_{K^{2}}})}^2  \Big)^{\frac{1}{2}},
    \end{equation}
    and the neighborhood version:
    \begin{align}\label{eq:decoupling_neighborhood}
        \| \widehat{F}\|_{L^p(\R^{d+n})} \lesssim_\epsilon K^{\Gamma_{p}^d(\mathbf{Q})+\epsilon} \Big(   \sum_\tau \big\|\widehat{F_\tau}\big\|_{L^p(\R^{d+n})}^2  \Big)^{\frac{1}{2}},
    \end{align}
    where $F$ is supported on $N_{K^{-2}}(S_{\mathbf{Q}})$, $F=\sum_\tau F_\tau$, and each $F_\tau$ is supported on $N_{K^{-2}}(S_{\mathbf{Q}}|_\tau)$. 
    Readers can see Proposition~9.15 in \cite{demeter2020} on the equivalence of the three versions.



	For future applications, we also need to introduce the lower-dimensional version of (\ref{eq:decoupling_extension_2}). To begin with, Gan, Guth and Oh \cite{ggo23} introduced the following transversality condition designed for the study of higher-codimensional Fourier restriction theory:

    \begin{definition}[\cite{ggo23}, $\theta$-uniform condition]\label{def:theta_uniform}
        Let $\theta \in (0,1]$, and $M,K\geq 1$. Let $  \{ X_m \}_{m=1}^{d+n} $ be nonnegative integers and $\{\tau_j\}_{j=1}^M$ be a collection of $K^{-1}$-cubes in $[0,1]^d$. We say that $\{\tau_j\}_{j=1}^M$ is $\theta$-uniform with the controlling sequence $  \{ X_m \}_{m=1}^{d+n} $ if for each $1\leq m\leq d+n$ and any subspace $V\subset \mathbb{R}^{d+n}$ with $\dim V=m$, there are at most $\theta M$ many $\tau_j$ intersecting 
        \begin{equation}\label{s3t1e1}
            \left\{  \xi \in \mathbb{R}^d:\dim (\pi_{V_\xi}(V)) <X_m   \right\}.
        \end{equation}
    \end{definition}

    This condition can lead to adaptive lower-dimensional $\ell^2 L^p$ decoupling:

    \begin{lemma}[\cite{ggo23}, Theorem 3.2]\label{dec low var}
        Let $0\leq k\leq d-1$, and $p \geq 2$. Given $E> 100$ and $\epsilon>0$, there exist constants $L=L(d,E)$, $\mu_0=\mu_0(d,E,\epsilon)$ and $c=c(d,E,\epsilon)$, such that the following holds true. Let $Z\subset \mathbb{R}^d$ be a $k$-dimensional semi-algebraic set  with complexity $\leq E$. For every $0<K^{-1}<\mu_0$, there exist	
        \begin{equation}\label{sec3 rel0}
            K^c \leq K_1 \leq K_2 \leq \cdots\leq K_L \leq K^{\frac{1}{2}}
        \end{equation}
        and collections of pairwise disjoint $1/K_j$-cubes $\mathcal{W}_j$ for  $j=1,2,...,L,$ such that 
        \begin{equation}\label{sec3 rel1}
            N_{1/K}(Z) \cap [0,1]^d \subset  \bigcup_{j=1}^L \bigcup_{W \in \mathcal{W}_j} W
        \end{equation}
        and
        \begin{equation}\label{dec low var e1}
            \Big\|\sum_{W \in \mathcal{W}_j} E^{\mathbf{Q}}f_W\Big\|_{L^p(\R^{d+n})} \leq C_{\epsilon,p,E} \cdot K_j^{\Gamma_{p}^k(\mathbf{Q})+\epsilon} \Big(   \sum_{W \in \mathcal{W}_j}  \|E^{\mathbf{Q}}f_W\|_{L^p(\R^{d+n})}^2\Big)^{\frac{1}{2}}.
        \end{equation}
    \end{lemma}

    Since the formulation of Lemma~\ref{dec low var} is not exactly the same as that of Theorem~3.2 in \cite{ggo23}, we will provide some clarifications below.

    Firstly, Theorem~3.2 of \cite{ggo23} is $\ell^pL^p$ decoupling, rather than $\ell^2L^p$ decoupling. However, the same proof for the current version also works (even holds for all $\ell^qL^p$ decoupling with $q\leq p$), and we do not repeat the arguments here. 

    Secondly, in Theorem~3.2 of \cite{ggo23}, the power of $K_j$ in $\text{(\ref{dec low var e1})}$ is actually ${\rm D}_{p}(\mathbf{Q}|_{L_k})$, which denotes the optimal power of $\ell^2L^p$ decoupling constant for all functions $f$ supported on $N_{K_j^{-2}}(L_k)$ with $L_k$ being a $k$-dimensional linear subspace. To bridge this discordance, note that $S_{\mathbf{Q}}|_{L_k}$ is a $k$-dimensional manifold of codimension $n$, so we can repeat the proof of Theorem 2.2 in \cite{gzk20} (or Corollary 5.4 in \cite{gozzk23}) to obtain
    $$   \text{D}_{p}(\mathbf{Q}|_{L_k}) \leq \sup_{L_k} \Gamma_{p}^k(\mathbf{Q}|_{L_k})+\epsilon = \Gamma_{p}^k(\mathbf{Q})+\epsilon, $$
    where the second equality can be shown by combining (\ref{dec th1 00}) with the observation that
    $$   \mathfrak{d}_{d',n'}(\mathbf{Q}) = \inf_{L_k} \mathfrak{d}_{d',n'}(\mathbf{Q}|_{L_k})   $$
    for any $d'\leq k$ and $n'\leq n$. Thus we get Lemma~\ref{dec low var}. 

    Finally, we point out that (\ref{dec low var e1}) is also equivalent to its local version 
    \begin{equation}\label{dec low var e2}
        \Big\|\sum_{W \in \mathcal{W}_j} E^{\mathbf{Q}}f_W\Big\|_{L^p(B_{K_j^2})} \leq C_{\epsilon,p,E} \cdot K_j^{\Gamma_{p}^k(\mathbf{Q})+\epsilon} \Big(   \sum_{W \in \mathcal{W}_j}  \|E^{\mathbf{Q}}f_W\|_{L^p(w_{B_{K_j^2}})}^2\Big)^{\frac{1}{2}}.
    \end{equation}



    \subsection{Well-curvedness}\label{obe_aff_cur_con_sec2_1}\phantom{x}

    As mentioned before, a core condition in Theorem~\ref{thm:relation_diagram} that we shall elaborate on is well-curvedness. However, the scope of this subsection is well beyond explaining the concepts: Firstly, it includes a brief exposition of the main tools from \cite{gressman19} that will be used in the proof of $\circled{6}$, $\circled{7}$, $\circled{8}$ in Theorem~\ref{thm:relation_diagram}; secondly, it also contains a bunch of new results that were not proved in \cite{gressman19}, because we need to remould some of the tools for our own purposes.



    \subsubsection{Well-curvedness and the Oberlin condition}\phantom{x}

    To state the definition of well-curvedness, we need to first introduce the Oberlin condition. It was introduced by Oberlin \cite{oberlin00} for hypersurfaces and systematically developed by Gressman \cite{gressman19} for higher-codimensional submanifolds.

    \begin{definition}[\cite{gressman19}, the Oberlin condition]\label{def:oberlin_condition}
        A Borel measure $\mu$ in $\R^{N}$ will be said to satisfy the Oberlin condition with exponent $\alpha \geq 0$\footnote{When $\alpha=0$, the condition simply tells us $\mu$ is finite. We include this trivial case purely for some uniformity of exposition.} when there exists a finite positive constant $C$ such that, for any convex body\footnote{By ``convex body'' we mean any compact convex set with nonempty interior. In \cite{gressman19} it is only assumed that $K$ is compact and convex, but this really does not matter: Any convex set $K$ with empty interior must be contained in a hyperplane, so when $\alpha>0$, (\ref{eq: oberlin_condition}) simply tells us that $\mu(K)=0$; however, this can also be derived by applying (\ref{eq: oberlin_condition}) to a sequence of convex bodies $K_n$ shrinking to $K$.} $K$ in $\R^{N}$, we have
        \begin{align}\label{eq: oberlin_condition}
            \mu(K) \leq C|K|^\alpha.
        \end{align}
    \end{definition}

    This is a Knapp-type testing condition and corresponds to the Frostman condition when $K$ is restricted to balls. However, by extending from balls to 
    convex bodies, we are able to capture not only dimension but also curvature, which will become clear later on. In fact, we can alternatively define the Oberlin condition by testing the measure $\mu$ on a much smaller category of geometric objects than convex bodies. This is the content of the following lemma, which should be a folklore but not formally presented anywhere in the literature:
	\begin{lemma}\label{lem:Oberlin_equiv}
		Let $\alpha\geq 0$, and $\mu$ be any Borel measure in $\R^{N}$. Then the following are equivalent to each other:

        \noindent $(i)$ There exists a finite positive constant $C$ such that, for any convex body $K$ in $\R^N$, we have $\mu(K) \leq C|K|^\alpha$. {\rm(}Definition~{\rm\ref{def:oberlin_condition})}

        \noindent $(ii)$ There exists a finite positive constant $C$ such that, for any ellipsoid\footnote{By ``ellipsoid'' we mean the image of $B(0,1)$ under a nonsingular affine transformation.} $J$ in $\R^N$, we have $\mu(J) \leq C|J|^\alpha$.

        \noindent $(iii)$ There exists a finite positive constant $C$ such that, for any rectangular box\footnote{By ``rectangular box'' we mean the image of $\prod_{i=1}^N [-c_i,c_i]$ ($c_i>0$) under an isometry.} $T$ in $\R^N$, we have $\mu(T) \leq C|T|^\alpha$.
	\end{lemma}
	\begin{proof}
		$(i) \Rightarrow (ii)$: This is trivial because any ellipsoid is a convex body.

		$(ii) \Rightarrow (i)$: By John’s ellipsoid theorem (Theorem III in \cite{john2014extremum}), for any convex body $K$ in $\R^N$, there is an ellipsoid $J$ so that if $c$ is the center of $J$, then $c+N^{-1}(J-c)\footnote{This is the dilation of $J$ by a factor of $N^{-1}$ with center $c$, i.e., $\{c+N^{-1}(x-c): x\in J\}$.} \subset K \subset J$. Note that $$|J| = N^N |c+N^{-1}(J-c)| \leq N^N|K|,$$ so we have $$\mu(K) \leq \mu(J) \leq C|J|^\alpha \leq CN^{N\alpha} |K|^\alpha,$$ as desired. 

		$(ii) \Rightarrow (iii)$: For any rectangular box $T$, there exists a nonsingular affine transformation $L$ of $\R^N$ such that $L([-\frac{1}{\sqrt{N}}, \frac{1}{\sqrt{N}}]^N) = T$. Let $J \coloneqq L(B(0,1))$, then $[-\frac{1}{\sqrt{N}}, \frac{1}{\sqrt{N}}]^N \subset B(0,1)$ implies $T \subset J$, and $|J| = C_N|T|$ for some constant $C_N = |B(0,1)|/(\frac{2}{\sqrt{N}})^N$. Therefore, we have $$\mu(T) \leq \mu(J) \leq C|J|^\alpha \leq CC_N^\alpha |T|^\alpha,$$ as desired.

		$(iii) \Rightarrow (ii)$: For any ellipsoid $J$, there exists a nonsingular affine transformation $L$ of $\R^N$ such that $L(B(0,1)) = J$. Let $L(x) = A\cdot x + b$, where $A \in {\rm GL}(N, \R)$ is the linear part of $L$ and $b \in \R^N$ is the translation part of $L$. By the singular value decomposition, there exists $D \in {\rm GL}(N,\R)$ diagonal with positive entries $\{c_i\}_{i=1}^N$, $O_1,O_2 \in {\rm O}(N,\R)$ such that $A = O_1 D O_2$. Let $X \coloneqq O_2^{-1}([-1,1]^N)$, then $$L(X) = A(X) + b = O_1 D O_2(X) + b = O_1 D([-1,1]^N) +b$$ is a rectangular box, since it is the image of $D([-1,1]^N)$ under an isometry. Also, $B(0,1) \subset X$ implies $J \subset T$, and $|T| = C_N|J|$ for some constant $C_N = |X|/|B(0,1)| = 2^N/|B(0,1)|$. Therefore, we have $$\mu(J) \leq \mu(T) \leq C|T|^\alpha \leq CC_N^\alpha |J|^\alpha,$$ as desired.
	\end{proof}
    Sometimes, the equivalent formulations of the Oberlin condition are more convenient to use, such as in the proof of Proposition~\ref{prop:convex_test}. Also, all statements in Lemma~\ref{lem:Oberlin_equiv} trivially implies that $\mu$ is $\sigma$-finite.


	Our Definition~\ref{def:oberlin_condition} is actually more general than that in \cite{gressman19}, where $\mu$ is supported on a $d$-dimensional immersed submanifold of $\R^{d+n}$\footnote{This will also be our main focus, but the definition itself surely makes sense for general Borel measures.}. Under this additional assumption, Gressman \cite{gressman19} examined the Oberlin condition in the case of maximal nondegeneracy by combining aspects of geometric invariant theory, convex geometry, and frame theory. In particular, he canonically constructed an equiaffine-invariant measure which is essentially the largest possible measure satisfying the Oberlin condition for the largest nontrivial choice of $\alpha$. To say that $\alpha$ is nontrivial means that there is a nonzero measure $\mu$ satisfying (\ref{eq: oberlin_condition}) for this $\alpha$ on some immersed
	submanifold of dimension $d$ and codimension $n$. 

    To state Gressman's main results, we also need the concept of \textit{homogeneous dimension} $D = D(d,n)$, which is defined to be the smallest positive integer which equals the sum of the degrees of some collection of $d+n$ distinct, nonconstant monomials in $d$ variables. For example, for nontrivial quadratic manifolds, we always have $n \leq \frac{d(d+1)}{2}$, which implies $D = d+2n$.

    \begin{theorem}[{\cite{gressman19}, Theorem 1}]\label{thm:gressman_thm1}
        Suppose that $\Sigma$ is an immersed $d$-dimensional submanifold of $\R^{d+n}$. To any such $\Sigma$, one may associate a nonnegative Borel measure $\mu_{\mathcal{A}}$ on $\R^{d+n}$, constructed in Section {\rm2} of \cite{gressman19}, which is supported on $\Sigma$. Then the following are true:

        \noindent {\rm (1)} If $\mu$ is any nonnegative Borel measure supported on $\Sigma$ which satisfies {\rm(\ref{eq: oberlin_condition})} with exponent $\alpha > d/D$, then $\mu$ is the zero measure.

        \noindent {\rm (2)} If $\mu$ is any nonnegative Borel measure supported on $\Sigma$ which satisfies {\rm(\ref{eq: oberlin_condition})} with exponent $\alpha = d/D$, then $\mu \lesssim \mu_{\mathcal{A}}$.

        \noindent {\rm (3)} If $\Sigma$ is the image of an immersion $f: \Omega \rightarrow \R^{d+n}$, where $\Omega \subset \R^d$ is open with compact closure $\overline{\Omega}$ and $f$ extends to be real analytic on a neighborhood of $\overline{\Omega}$, then the measure $\mu_{\mathcal{A}}$ satisfies {\rm(\ref{eq: oberlin_condition})} with exponent $\alpha = d/D$ and is consequently the largest such measure, up to a multiplicative constant.

        We call $\mu_{\mathcal{A}}$ the {\rm(}Oberlin{\rm)} affine measure of $\Sigma$. 
        Furthermore, the correspondence sending $\Sigma$ to $\mu_{\mathcal{A}}$ is equiaffine invariant, meaning that if $\Sigma$ and $\Sigma_0$ are immersed submanifolds such that $\Sigma_0$ is the image of $\Sigma$ under some equiaffine transformation\footnote{Affine transformations that preserve volumes.} $T$ of $\R^{d+n}$, then the affine measure $\mu'_{\mathcal{A}}$ of $\Sigma_0$ and the affine measure $\mu_{\mathcal{A}}$ of $\Sigma$ satisfy $\mu'_{\mathcal{A}}(T(E)) = \mu_{\mathcal{A}}(E)$ for all Borel sets $E$.
    \end{theorem}

	Suppose $\Sigma$ is parametrized by $f: \Omega \rightarrow \R^{d+n}$ ($\Omega \subset \R^d$) with $f(t) = (t, f_1(t),\dots, f_n(t))$, then the affine measure $\mu_{\mathcal{A}}$ is defined as the pushforward via $f$ of the measure $\nu_{\mathcal{A}}$ on $\R^d$ whose density is generated by certain ``affine curvature tensor''. One can see (14) in \cite{gressman19} for the precise definition of $\nu_{\mathcal{A}}$, which is inspired by geometric invariant theory. From this construction, the uniqueness of $\mu_{\mathcal{A}}$ and $\nu_{\mathcal{A}}$ follows immediately. However, we do not know beforehand how regular $\mu_{\mathcal{A}}$ or $\nu_{\mathcal{A}}$ is.

	To certify the nontriviality of Theorem~\ref{thm:gressman_thm1}, i.e., to show that $\mu_{\mathcal{A}}$ is not simply the zero measure for all possible choices of $\Sigma$, Gressman \cite{gressman19} considered $f$ of the form
	\begin{align}\label{canonical_poly_form}
		f(t) \coloneqq ((t^\gamma)_{1\leq|\gamma|<\kappa}, p_1(t), \dots, p_m(t)),
	\end{align}
	where $p_1,\dots,p_m$ are linearly independent elements in $\dot{P}_d^\kappa$, and $m$ and $\kappa$ are chosen (as functions of $n$ and $d$ only) so that the right-hand side of (\ref{canonical_poly_form}) is an element of $\R^{d+n}$. Let $P_{j\ell}(t) \coloneqq \partial_j p_\ell(t)$ for $j = 1,\dots,d$, $\ell = 1,\dots,m$. Such an embedding $f$ will be called a \textit{model form} when there exist real numbers $c$ and $c'$ such that
	\begin{align}\label{model_poly_form}
		\sum_{j=1}^d P_{j\ell}(\partial) P_{j\ell'}(t)|_{t=0} = c\delta_{\ell,\ell'}  \quad \text{and} \quad \sum_{\ell=1}^m P_{j\ell}(\partial) P_{j'\ell}(t)|_{t=0} = c'\delta_{j,j'}
	\end{align}
	where $\delta$ is the Kronecker delta. The main result for model forms in \cite{gressman19} is:
    \begin{theorem}[\cite{gressman19}, Theorem 2]\label{thm:gressman_thm2}
        The following are true for embeddings $f$ of the form {\rm(\ref{canonical_poly_form})}.

        \noindent {\rm (1)} The closure of the orbit $\{Nf(M^Tt)\}_{N\in {\rm SL}(d+n,\R), M \in {\rm SL}(d,\R)}$ in the space of $(d+n)$-tuples of polynomials of degree at most $\kappa$ always contains an embedding of the form {\rm(\ref{canonical_poly_form})} which is a model form {\rm(\ref{model_poly_form})}. If any embedding in the closure of the orbit is degenerate, then all are degenerate {\rm(}i.e., $\mu_{\mathcal{A}} = 0$ for each embedding in the orbit closure or $\mu_{\mathcal{A}} \neq 0$ for each embedding{\rm)}.

        \noindent {\rm (2)} For any $p \coloneqq (p_1,\dots,p_m)$ satisfying {\rm(\ref{model_poly_form})}, the affine measure $\mu_{\mathcal{A}}$ of the submanifold of $\R^{d+n}$ parameterized by {\rm(\ref{canonical_poly_form})} is a nonzero constant times the pushforward of Lebesgue measure via $f$ if and only if $c$ and $c'$ are nonzero.

        \noindent {\rm (3)} For any pair $(d,n)$, there is some $p \coloneqq (p_1,\dots,p_m)$ satisfying {\rm(\ref{model_poly_form})} for nonzero $c$ and $c'$. Consequently, in any dimension and codimension, there is a submanifold $\Sigma$ whose affine measure $\mu_{\mathcal{A}}$ is everywhere nonzero on $\Sigma$. In this case, we say that $\Sigma$ is ``well-curved''.
    \end{theorem}
    For simplicity, we say that a quadratic form $\mathbf{Q}$ is well-curved if $S_\mathbf{Q}$ is well-curved.

    The proof of (2) in \cite{gressman19} relies on a direct computation of $\nu_{\mathcal{A}}$ (Lemma 4 there) via the so-called first fundamental theorem of invariant theory (Lemma 5 there), which yields an explicit expression of $\nu_{\mathcal{A}}$. However, if we only care about the ``constant'' property, then there is a much simpler proof, which we now present. We choose to do so not only because it is elegant and yields more general results (Proposition~\ref{prop:TDI_affine_const}), but also because it contains geometric insights that also appear in the proof of $\circled{11}$ in Theorem~\ref{thm:relation_diagram}.
    \begin{definition}\label{def:TDI_mfd}
        We say that $\Sigma$ is a {\rm TDI} manifold {\rm(}translation-dilation-invariant manifold{\rm)} if each $f_j$ in the parametrization of $\Sigma$ is a homogeneous polynomial whose all partial derivatives are linear combinations of $f_1,\dots,f_n$.
    \end{definition}
    Historically, TDI manifolds play an important role in decoupling theory, since they enjoy a large group of symmetries that resembles the classical ``parabolic rescaling'' for paraboloids. For example, all quadratic manifolds are TDI. In fact, one can easily check that any parametrization (\ref{canonical_poly_form}) induces a TDI manifold, so the following proposition recovers the ``constant'' property in (2) of Theorem~\ref{thm:gressman_thm2} from a very different perspective.
    \begin{proposition}\label{prop:TDI_affine_const}
        Suppose $\Sigma$ is a {\rm TDI} manifold, then $\nu_{\mathcal{A}}$ is a constant {\rm(}might be zero{\rm)} times the Lebesgue measure on $\R^d$.
    \end{proposition}
    \begin{proof}
        The key point is the equiaffine invariance of $\mu_{\mathcal{A}}$. Note that for any Borel set $E \subset \R^d$ and $a\in\R^d$, there exists some $T_a \in {\rm SL}(d+n,\R)$ such that $\Sigma$ is invariant under $T_a$ and $T_a(f(E)) = f(E+a)$ (``parabolic rescaling'' for TDI manifolds). By taking $\Sigma_0 = \Sigma$ and $T=T_a$ in Theorem~\ref{thm:gressman_thm1}, we have $\mu'_{\mathcal{A}}=\mu_{\mathcal{A}}$ by the uniqueness of $\mu_{\mathcal{A}}$, and 
        $$\nu_{\mathcal{A}}(E) = \mu_{\mathcal{A}}(f(E)) = \mu_{\mathcal{A}}(T_a(f(E))) = \mu_{\mathcal{A}}(f(E+a)) = \nu_{\mathcal{A}}(E+a).$$
        In other words, $\nu_{\mathcal{A}}$ is translation invariant, so for any $\varphi \in C_c^\infty(\R^d)$ with $\int \varphi = 1$ and $\varphi\geq 0$, we have $\nu_{\mathcal{A}} * \varphi = \nu_{\mathcal{A}}$. This is because for any Borel set $E \subset \R^d$, by Tonelli's theorem we have
        \begin{align*}
            \nu_{\mathcal{A}} * \varphi (E) &= \int_{\R^d}\int_{\R^d} \varphi(\xi-\eta)d\nu_{\mathcal{A}}(\eta) \chi_E(\xi) d\xi\\
            &= \int_{\R^d}\int_{\R^d} \varphi(\xi) \chi_E(\xi+\eta) d\xi d\nu_{\mathcal{A}}(\eta)\\
            &= \int_{\R^d}\int_{\R^d} \chi_{E-\xi}(\eta) d\nu_{\mathcal{A}}(\eta) \varphi(\xi) d\xi\\
            &= \int_{\R^d} \nu_{\mathcal{A}}(E) \varphi(\xi) d\xi = \nu_{\mathcal{A}}(E).
        \end{align*}
        Thus $\nu_{\mathcal{A}} = \nu_{\mathcal{A}} * \varphi$ must be smooth. But any translation invariant smooth function must be a constant, so we are done.
    \end{proof}


    \subsubsection{Newton-type polyhedra characterizations}\phantom{x}

	Recall that the original definition of the Oberlin condition (Definition~\ref{def:oberlin_condition}) only involves concepts from convex geometry. So it is remarkable that Gressman \cite{gressman19} obtained many other characterizations in different flavors besides convex geometry, such as algebra, geometric invariant theory, sublevel set estimates, and Newton-type polyhedra. However, for our purposes, we shall only need the Newton-type polyhedra characterization, which will be presented below.

    Let us first fix some notations. For $p=(p_1,\dots,p_m)$ being an $m$-tuple of real homogeneous polynomials in $d$ variables, we define $R_{N,M} p \coloneqq (p\circ M)\cdot N$\footnote{We rewrite the definition of $R_{N,M}$ in \cite{gressman19} to better match the definition of $\mathfrak{d}_{d',n'}(\mathbf{Q})$ in the literature, which will be convenient for later discussions. For example, when $p = \mathbf{Q}$, this agrees with our previous definition of $R_{N,M}$ in (\ref{def:R_{M',M}}). Such a modification does not change the content of the theorems in \cite{gressman19}.} for any $(N,M) \in {\rm GL}(m,\R) \times {\rm GL}(d,\R)$. Also, let $\1_u \coloneqq (1,\dots,1) \in [0,\infty)^u$ for any $u \in \N^+$. Then we have:

    \begin{theorem}[\cite{gressman19}, Theorem 6]\label{thm:gressman_thm6}
        Let $\{e_1,\dots,e_m\}$ be the standard basis of $\R^m$. For any $p = (p_1,\dots,p_m)$ being an $m$-tuple of real homogeneous polynomials of degree $\kappa$ in $d$ variables, let $\mathcal{N}(p) \subset [0,\infty)^m \times [0,\infty)^d$ be the convex hull of all points $(e_j, \gamma)$ such that 
        \begin{align*}
            \partial^\gamma p_j(t)|_{t=0} \neq 0.
        \end{align*}
        Then the associated submanifold defined by {\rm(\ref{canonical_poly_form})} is well-curved if and only if 
        \begin{align}\label{eq:newton_convex_hull}
            \left( \frac{1}{m} \1_m, \frac{\kappa}{d} \1_d \right) \in \mathcal{N}(R_{O_1,O_2} p)
        \end{align}
        for all $(O_1,O_2) \in {\rm O}(m, \R) \times {\rm O}(d, \R)$.
    \end{theorem}

	Although we have introduced the full versions of the theorems in \cite{gressman19} for completeness and for the reader's convenience, in this paper we will only care about their applications to quadratic manifolds. An unusual benefit that we enjoy by restricting ourselves to this special (but still quite general compared with paraboloids/hyperbolic paraboloids) class of manifolds is that now the form (\ref{canonical_poly_form}) comes for free, so Theorem~\ref{thm:gressman_thm2} and \ref{thm:gressman_thm6} are directly applicable (take $m=n$, $\kappa=2$, $p = \mathbf{Q}$, and $f(\xi) = (\xi, \mathbf{Q}(\xi))$). Theorem~\ref{thm:gressman_thm6} is vital in the proof of $\circled{6}$ in Theorem~\ref{thm:relation_diagram}.
    % \begin{corollary}\label{cor:gressman_thm6}
    %     Let $\{e_1,\dots,e_n\}$ be the standard basis of $\R^n$. For any $\mathbf{Q} = (Q_1,\dots,Q_n)$ being an $n$-tuple of quadratic forms in $d$ variables, let $\mathcal{N}(\mathbf{Q}) \subset [0,\infty)^n \times [0,\infty)^d$ be the convex hull of all points $(e_j, \gamma)$ such that 
    %     \begin{align*}
    %         \partial^\gamma Q_j(\xi)|_{\xi=0} \neq 0.
    %     \end{align*}
    %     Then $\mathbf{Q}$ is well-curved if and only if 
    %     \begin{align}\label{cond:Newton_poly_quad}
    %         \left( \frac{1}{n} \1_n, \frac{2}{d} \1_d \right) \in \mathcal{N}(R_{O_1,O_2} \mathbf{Q})
    %     \end{align}
    %     for all $(O_1,O_2) \in {\rm O}(n, \R) \times {\rm O}(d, \R)$.
    % \end{corollary}

    On the other hand, in the proof of $\circled{8}$ in Theorem~\ref{thm:relation_diagram}, we need to connect well-curvedness with algebraic quantities $\mathfrak{d}_{d',n'}(\mathbf{Q})$. For this purpose, we will prove the following variant of Theorem~\ref{thm:gressman_thm6}:
    \begin{theorem}\label{thm:gressman_thm6_variant}
        Let $\{e_1,\dots,e_m\}$ be the standard basis of $\R^m$. For any $p = (p_1,\dots,p_m)$ being an $m$-tuple of real homogeneous polynomials of degree $\kappa$ in $d$ variables, let $\mathcal{N}(p) \subset [0,\infty)^m \times [0,\infty)^d$ be the convex hull of all points $(e_j, \gamma)$ such that 
        \begin{align*}
            \partial^\gamma p_j(t)|_{t=0} \neq 0.
        \end{align*}
        Then the associated submanifold defined by {\rm(\ref{canonical_poly_form})} is well-curved if and only if 
        \begin{align*}
            \left( \frac{1}{m} \1_m, \frac{\kappa}{d} \1_d \right) \in \mathcal{N}(R_{N,M} p)
        \end{align*}
        for all $(N,M) \in {\rm GL}(m, \R) \times {\rm GL}(d, \R)$.
    \end{theorem}

    Compared with Theorem~\ref{thm:gressman_thm6}, which only tests (\ref{eq:newton_convex_hull}) over $(N,M) \in {\rm O}(n,\R) \times {\rm O}(d,\R)$, here in Theorem~\ref{thm:gressman_thm6_variant} we are testing over $(N,M) \in {\rm GL}(n,\R) \times {\rm GL}(d,\R)$, which is much larger. Therefore, if we want to prove the well-curvedness of some $\mathbf{Q}$ via the Newton-type polyhedra, then there is no benefit of resorting to Theorem~\ref{thm:gressman_thm6_variant}. However, if we aim to show that some $\mathbf{Q}$ is not well-curved, then Theorem~\ref{thm:gressman_thm6_variant} is much more convenient to use and automatically matches the definition of $\mathfrak{d}_{d',n'}(\mathbf{Q})$. This is the punchline behind the proof of $\circled{8}$ in Theorem~\ref{thm:relation_diagram}.

    Note that the action of $\{R_{N,M}\}_{(N,M) \in {\rm GL}(n,\R) \times {\rm GL}(d,\R)}$ forms a group, so we have the following by-product of Theorem~\ref{thm:gressman_thm6_variant} (take $m=n$, $\kappa=2$, $p = \mathbf{Q}$, and $f(\xi) = (\xi, \mathbf{Q}(\xi))$), which is a reflection of the intuition that the ${\rm GL}$-action does not change the ``shape'' of a surface:
    \begin{corollary}\label{cor:quad_equiv_curved}
        For $\mathbf{Q} \equiv \mathbf{Q}'$, $\mathbf{Q}$ is well-curved if and only if $\mathbf{Q}'$ is well-curved.
    \end{corollary}

	Now we turn to the proof of Theorem~\ref{thm:gressman_thm6_variant}, which is very similar to that of (1) in Theorem~\ref{thm:gressman_thm2}. The key ingredient is Lemma 4 in \cite{gressman19}, for which we shall further introduce some notations. We equip $\dot{P}_d^\kappa$ with the inner product $\langle\cdot,\cdot\rangle_\kappa$ given by $\langle q, r \rangle_\kappa = \kappa! q(\partial)r(t)|_{t=0}$ for any $q, r \in \dot{P}_d^\kappa$, and let $\norm{\cdot}_\kappa$ be the norm induced by $\langle\cdot,\cdot\rangle_\kappa$. Then we have:

    \begin{lemma}[\cite{gressman19}, Lemma 4]\label{lem:nu_simple_express}
        Let $f$ have the form {\rm(\ref{canonical_poly_form})}. Let $p \coloneqq (p_1,\dots,p_m) \in (\dot{P}_d^\kappa)^m$ be the $m$-tuple of highest order parts of $f$. Then $\nu_{\mathcal{A}}$ is a constant times Lebesgue measure on $\R^d$, and
        \begin{align}\label{eq:nu_simple_express}
            \frac{d \nu_{\mathcal{A}}}{d t} = C \Big[\inf_{\substack{N\in {\rm SL}(m,\R)\\ M\in {\rm SL}(d,\R)}} \sum_{j=1}^m \norm{(R_{N,M}p)_j}_\kappa^2\Big]^{\frac{md}{2D}}
        \end{align}
        for some constant $C = C(d,n)$. Here $D = D(d,n)$ is the homogeneous dimension.
    \end{lemma}
    \begin{proof}[Proof of Theorem~\ref{thm:gressman_thm6_variant}]
        The ``if'' part is trivial: If the Newton-type polyhedra condition holds for all $(N,M) \in {\rm GL}(n,\R) \times {\rm GL}(d,\R)$, then it in particular holds for all $(N,M) \in {\rm O}(n,\R) \times {\rm O}(d,\R)$, and by Theorem~\ref{thm:gressman_thm6}, we get well-curvedness. So it remains to prove the ``only if'' part.

        By Lemma~\ref{lem:nu_simple_express}, we have
        \begin{align*}
            \frac{d \nu_{\mathcal{A}}}{d t} = C \Big[\inf_{\substack{N\in {\rm SL}(m,\R)\\ M\in {\rm SL}(d,\R)}} \sum_{j=1}^m \norm{(R_{N,M}p)_j}_\kappa^2\Big]^{\frac{md}{2D}}.
        \end{align*}
        By noting that interchanging columns of $N$ or rows of $M$ does not affect the value of the expression, we can replace the infimum above by $\inf_{|\det(N)|=|\det(M)|=1}$. The key point here is that if we replace $p$ with $R_{N',M'}p$ for some $(N',M') \in {\rm GL}(n,\R) \times {\rm GL}(d,\R)$, then the corresponding $d\nu'_{\mathcal{A}}/d t$ differs from $d\nu_{\mathcal{A}}/d t$ by a factor $C'\in \R^+$. This is because we can always write $N' = aN''$ and $M' = bM''$ for some $a, b \in\R^+$ and $|\det(N'')|=|\det(M'')|=1$, under which $$R_{N,M}(R_{N',M'}p) = R_{N,M}\left( R_{N'',M''} (R_{aI,bI}p) \right) = (R_{N,M}\circ R_{N'',M''})(ab^\kappa\cdot p) = ab^\kappa R_{N''N,M''M}p,$$ and then by Lemma~\ref{lem:nu_simple_express} with $p = R_{N',M'}p$ and $f(t) = ((t^\gamma)_{1\leq |\gamma|<\kappa},R_{N',M'}p(t))$ we have
        \begin{align*}
            \frac{d \nu'_{\mathcal{A}}}{d t} &= C \Big[\inf_{\substack{|\det(N)|=1 \\ |\det(M)|=1}} \sum_{j=1}^m \norm{\left(R_{N,M}(R_{N',M'}p)\right)_j}_\kappa^2\Big]^{\frac{md}{2D}}\\
            &= C \Big[\inf_{\substack{|\det(N)|=1\\ |\det(M)|=1}} \sum_{j=1}^m \norm{(ab^\kappa R_{N''N,M''M}p)_j}_\kappa^2\Big]^{\frac{md}{2D}}\\
            &= C (ab^\kappa)^{\frac{md}{D}} \cdot \Big[\inf_{\substack{|\det(N)|=1 \\ |\det(M)|=1}} \sum_{j=1}^m \norm{(R_{N,M}p)_j}_\kappa^2\Big]^{\frac{md}{2D}}\\
            &= (ab^\kappa)^{\frac{md}{D}} \cdot \frac{d \nu_{\mathcal{A}}}{d t}.
        \end{align*}

        Therefore, if we assume $\{((t^\gamma)_{1\leq |\gamma|<\kappa}, p(t))\}$ is well-curved, then so is the modified $\{((t^\gamma)_{1\leq |\gamma|<\kappa},R_{N',M'}p(t))\}$ for any $(N',M') \in {\rm GL}(m,\R) \times {\rm GL}(d,\R)$. By applying Theorem~\ref{thm:gressman_thm6} to $R_{N',M'}p$, we know that 
        $$\left( \frac{1}{m} \1_m, \frac{\kappa}{d} \1_d \right) \in \mathcal{N}(R_{O_1,O_2} (R_{N',M'}p))$$ for all $(O_1,O_2) \in {\rm O}(m, \R) \times {\rm O}(d, \R)$. In particular, by taking $O_1$ and $O_2$ to be identity matrices, we get $$\left( \frac{1}{m} \1_m, \frac{\kappa}{d} \1_d \right) \in \mathcal{N}(R_{N',M'}p)$$ for all $(N',M') \in {\rm GL}(m,\R) \times {\rm GL}(d,\R)$, as desired.
    \end{proof}




    \subsection{Several versions of the Fourier extension operator}\label{subsec:E^Q_versions}\phantom{x}

    \subsubsection{Most general version}\phantom{x}

    The most general formulation of Fourier extension is with respect to Borel measures. For any Borel measure $\mu$ in $\R^{N}$, we define its associated Fourier extension operator as
    \begin{align*}
        E^\mu f (x) \coloneqq \int_{\R^N} e^{ix\cdot \xi} f(\xi) d\mu(\xi), \qquad x\in \R^N.
    \end{align*}

    In this general setting, we can connect the Fourier restriction to the Oberlin condition (see  Definition~\ref{def:oberlin_condition})\footnote{This was mentioned but not proved in \cite{gressman19}.} by the following proposition, which will be of use in the proof of $\circled{6}$ in Theorem~\ref{thm:relation_diagram}:
    \begin{proposition}\label{prop:convex_test}
        Let $p \in (1,\infty]$, $q \in [1,\infty]$, and $\mu$ be any Borel measure in $\R^{N}$. 
        Suppose $E^\mu$ is bounded from $L^p(\mu)$ to $L^q(\R^{N})$, then $\mu$ satisfies the Oberlin condition with exponent $p'/q$.
    \end{proposition}

    \begin{proof}
        By the duality of $L^p$-spaces, for any $F \in \mathcal{S}(\R^N)$, we have
        \begin{align*}
            \big\Vert\widehat{F}\big\Vert_{L^{p'}(\mu)} &= \sup_{\norm{g}_{L^p(\mu)}=1} \abs{\int_{\R^N} \widehat{F}g d\mu }\\
            & = \sup_{\norm{g}_{L^p(\mu)}=1} \abs{\int_{\R^N} F \widetilde{E^\mu g}}\\
            & \leq \sup_{\norm{g}_{L^p(\mu)}=1} \norm{F}_{L^{q'}(\R^N)} \norm{E^\mu g}_{L^{q}(\R^N)} \\
            & \lesssim \sup_{\norm{g}_{L^p(\mu)}=1} \norm{F}_{L^{q'}(\R^N)} \norm{g}_{L^p(\mu)} = \norm{F}_{L^{q'}(\R^N)},
        \end{align*}
        which is the ``restriction'' formulation of $E^\mu$. Here $\widetilde{E^\mu g}(x) \coloneqq E^\mu g (-x)$.

        For any rectangular box $T$ in $\R^N$, let $T = L(\prod_{i=1}^N[-c_i,c_i])$ for some isometry $L$, then $|T| \sim \prod_{i=1}^N c_i$. Fix a $\phi \in C_c^\infty(\R)$ with $\phi \equiv 1$ on $[-1,1]$. Let  $\Phi(\xi) \coloneqq \prod_{i=1}^N \phi(\xi_i/c_i)$, then $\Phi \in C_c^\infty(\R^N)$ with $\Phi \equiv 1$ on $\prod_{i=1}^N[-c_i,c_i]$, so $\Phi_T \coloneqq \Phi \circ L^{-1} \in C_c^\infty(\R^N)$ satisfies $\Phi_T \equiv 1$ on $T$. Plugging $F = (\Phi_T)^\vee$ into the restriction estimate above, we get $$\norm{\Phi_T}_{L^{p'}(\mu)} \lesssim \norm{(\Phi_T)^\vee}_{L^{q'}(\R^N)}.$$ 
        Furthermore, we have 
        $$\norm{(\Phi_T)^\vee}_{L^{q'}(\R^N)} = \norm{(\Phi)^\vee}_{L^{q'}(\R^N)} = \prod_{i=1}^N \norm{(\phi(\cdot/c_i))^\vee}_{L^{q'}(\R)}  \sim_\phi \prod_{i=1}^N c_i^{1/q} \sim |T|^{1/q}.$$ 
        However, note that $$\norm{\Phi_T}_{L^{p'}(\mu)} \geq \norm{\chi_T}_{L^{p'}(\mu)} = \mu(T)^{1/p'}.$$  
        Therefore, we get 
        $$\mu(T) \lesssim |T|^{p'/q}$$
        for any rectangular box $T$ in $\R^N$, with the constant independent of $T$. Finally, by Lemma~\ref{lem:Oberlin_equiv}, we conclude that $\mu$ satisfies the Oberlin condition with exponent $p'/q$, as desired.
    \end{proof}
    \begin{remark}
        Proposition~{\rm\ref{prop:convex_test}} does not include the case when $p=1$, which is actually trivial when $\mu$ is $\sigma$-finite {\rm(}which is always the case in practice{\rm)}. The proof above mostly carries through when $p=1$, with the duality justified by the fact that $\mu$ is $\sigma$-finite. The only difference is that when we arrive at $\norm{\Phi_T}_{L^{p'}(\mu)} \geq \norm{\chi_T}_{L^{p'}(\mu)}$, we may without loss of generality assume $\mu(T)>0$ {\rm(}we can always pick such a $T$ as long as $\mu$ is not trivial{\rm)}, under which we have $\norm{\chi_T}_{L^{p'}(\mu)} = 1$. Therefore, we get $1 \lesssim |T|^{1/q}$. Note that we can choose $T$ such that $\mu(T)>0$ and $|T|$ is arbitrarily small by subdividing the original $T$, so $1 \lesssim |T|^{1/q}$ cannot be true unless $q=\infty$. On the other hand, if $p=1$ and $q=\infty$, then one trivially has the boundedness of $E^\mu$ from $L^1(\mu)$ to $L^\infty(\R^N)$.
    \end{remark}

    \subsubsection{Fourier extension for submanifolds and its neighborhood version}\phantom{x}

    From now on, we restrict ourselves to the case when the Borel measure $\mu$ in $E^\mu$ is a surface measure. 

    Suppose that $S_\psi \coloneqq \{ (\xi,\psi(\xi)): \xi \in U \}$ is a graph in $\mathbb{R}^{d+n}$, where $U$ is a bounded open/closed region of $\R^d$ and $\psi:U\rightarrow\R^n$ is a smooth function. Then we define the Fourier extension operator    \begin{align}\label{def:general_ext_op}
        E_U^\psi f(x) \coloneqq \int_U e^{ix\cdot(\xi,{\psi(\xi)})} f(\xi) d\xi, \qquad x\in\R^{d+n},
    \end{align}
    as well as the (bump) smoothed Fourier extension operator
    \begin{align}\label{def:bump_extension}
        \widetilde{E}_\varphi^\psi f(x) \coloneqq \int_{\R^{d}} e^{ix\cdot(\xi,{\psi(\xi)})} f(\xi) \cdot\varphi(\xi) d\xi, \qquad x\in\R^{d+n},
    \end{align}
    where $\varphi \in C_c^\infty(\R^d)$ with $\varphi \not\equiv 0$ on $U$. Also, when $U = [0,1]^d$, we abbreviate $E_U^\psi$ to $E^\psi$. This matches our definition of $E^\mathbf{Q}$ in (\ref{s1e0}).


    Now we introduce the thickening lemma, which basically says that the $L^p \rightarrow L^q$ estimates of $E_U^\psi$ are equivalent to those of its neighborhood version. As this is well-known in the Fourier restriction community but hard to find a directly applicable version in the literature, we will largely omit the proofs and only state the version that is the most useful to us. 

    \begin{lemma}[Thickening]\label{lem:thickening}
        For any $\alpha\geq 0$, the following are equivalent:

        \noindent ${(i)}$ $$\norm{E_U^\psi f}_{L^q(B_R)} \lesssim R^\alpha \norm{f}_{L^p(U)}$$
            holds for any $f\in L^p(U)$ and $R\geq 1$.

        \noindent ${(ii)}$ $$\big\Vert\widehat{F}\big\Vert_{L^q(B_R)} \lesssim R^{\alpha-\frac{n}{p'}} \norm{F}_{L^p(N_{R^{-1}}(S_\psi))}$$
            holds for any $F \in L^p(N_{R^{-1}}(S_\psi))$ and $R\geq 1$.
    \end{lemma}
    The proof of Lemma~\ref{lem:thickening} is exactly the same as that of Proposition~1.27 in \cite{demeter2020}, which handles the $n=1$ case.


    \subsubsection{Smoothed versions for quadratic forms}\phantom{x}

    From now on, we will further restrict ourselves to the case when $U = [0,1]^d$, $\psi = \mathbf{Q}$, and $S_\psi = S_\mathbf{Q}$. Our main goal here is to prove the equivalence between $E^\mathbf{Q}$ and its smoothed versions in terms of (weighted) restriction theory. Before that, we need to first introduce some notations.

    Let $x = (x',x'') \in\R^{d+n}$ with $x' = (x_1,\dots,x_d)\in\R^d$ and $x'' = (x_{d+1},\dots,x_{d+n})\in \R^n$, $\xi = (\xi_1,\dots,\xi_d) \in \R^d$, and $\mathbf{Q}(\xi) = (Q_1(\xi),\dots,Q_n(\xi))$. Then the Hessian matrix $\nabla_\xi^2 Q_j$ of each quadratic form $Q_j(\xi)$ satisfies
      $$\quad Q_j(\xi) = \frac{1}{2}\xi^T\cdot \nabla_\xi^2 Q_j \cdot \xi.$$ Thus if we define the $d \times d$ matrix 
    \begin{equation}\label{098765}
        \overline{Q}(x'') \coloneqq \sum_{j=1}^n x_{d+j}\nabla_\xi^2Q_j,
    \end{equation}
    then we can rewrite the Fourier extension operator in (\ref{s1e0}) as
    \begin{align*}
        E^\mathbf{Q}f(x) = \int_{[0,1]^{d}} e^{i(x'\cdot\xi + \xi^T\cdot \overline{Q}(x'')\cdot\xi/2)} f(\xi) d\xi, \quad \quad x = (x',x'') \in \R^{d+n},
    \end{align*}
    and the (Gaussian) smoothed Fourier extension operator in (\ref{eq:gaussian_integral}) as
    \begin{align}
        \widetilde{E}^\mathbf{Q}f(x) = \int_{\R^d} e^{i(x'\cdot\xi + \xi^T\cdot \overline{Q}(x'')\cdot\xi/2)} f(\xi) \cdot e^{-|\xi|^2/2} d\xi, \quad\quad x = (x',x'') \in \R^{d+n}.
    \end{align}

    It would also be convenient to formally introduce affine transformations preserving $\mu_\mathbf{Q}$ here. For any $\xi_0 \in \R^d$, we define the affine transformation $L_{\xi_0}$ on $\R^{d+n}$ as
    \begin{align}\label{def:affine_trans}
        L_{\xi_0}(\xi,\eta) \coloneqq (\xi - \xi_0, \eta - \nabla_\xi\mathbf{Q}(\xi_0)\cdot\xi - \mathbf{Q}(\xi_0)), \qquad \forall~(\xi,\eta) \in\R^d \times \R^n. 
    \end{align}
    The effect of $L_{\xi_0}$ is to translate the data function on $\R^d$ by $-\xi_0$ on the frequency side. Correspondingly, on the physical side, we will distort everything by the adjoint transformation $L_{\xi_0}^* \coloneqq (A^T)^{-1}$, where $A \in {\rm SL}(d+n,\R)$ is the linear part of $L_{\xi_0}$. Both $L_{\xi_0}$ and $L_{\xi_0}^*$ preserve volumes in $\R^{d+n}$, and $L_{\xi_0}$ also preserves $\mu_\mathbf{Q}$.


    Now we show that weighted restriction theories of $E^\mathbf{Q}$ and $\widetilde{E}^\mathbf{Q}$ are equivalent, which justifies our usage of the smoothing trick in Shayya's argument (Subsection~\ref{subsec:shayya}):
    \begin{proposition}\label{prop:smooth_equiv}
        Let $p,q \in [1,\infty]$ and $\alpha\in (0,d+n]$. Then for any $\beta >0$ and $\eta \geq 0$, the following two statements are equivalent: 

        \noindent $(i)$ We have \begin{equation*}\label{2211}
                \norm{E^\mathbf{Q}f}_{L^q(B_R,H)} \lesssim A_\alpha(H)^\beta R^\eta \norm{f}_{L^p([0,1]^d)}
            \end{equation*}
            for any $\alpha$-dimensional weight $H$, $f \in L^p([0,1]^d)$, and $R\geq 1$.

        \noindent $(ii)$ We have \begin{equation*}\label{2212}
                \norm{\widetilde{E}^\mathbf{Q}f}_{L^q(B_R,H)} \lesssim A_\alpha(H)^\beta R^\eta \norm{f}_{L^p(\R^d)}  
            \end{equation*}    
            for any $\alpha$-dimensional weight $H$, $f \in L^p(\mathbb{R}^d)$, and $R\geq 1$. 
    \end{proposition}
    \begin{proof}
        $(ii)\Rightarrow(i)$: This is immediate by only considering those $f\in L^p([0,1]^d)$ and noting that $e^{-|\xi|^2/2} \sim 1$ over $[0,1]^d$.

        $(i)\Rightarrow(ii)$: Partition $\R^d$ into unit cubes $\{\nn + [0,1]^d\}_{\nn\in \Z^d}$. We claim $(i)$ implies
        $$       \norm{E^\mathbf{Q}f}_{L^q(B_R,H)} \lesssim A_\alpha(H)^\beta R^\eta (1+|\nn|)^C\norm{f}_{L^p(\nn +[0,1]^d)},     $$
        for some constant $C$. In fact, note that $L_\nn$ translates the data function on $\R^d$ from $\nn + [0,1]^d$ to $[0,1]^d$ on the frequency side, while $L_\nn^*$ preserves volumes and distorts everything on the physical side by a factor polynomially bounded by $\nn$. Thus, if $\widetilde{H} \coloneqq L_\nn^* (H)$ and $B_{\widetilde{R}} $ is the smallest ball containing $L_\nn(B_R)$, then $A_\alpha(\widetilde{H})$ and $\widetilde{R}$ will differ from $A_\alpha(H)$ and $R$ at most by a factor of $(1+|\nn|)^C$ respectively for some constant $C$. The claim is now self-evident.

        Let $f_\nn \coloneqq f\chi_{\nn+[0,1]^d}$, then
        \begin{align*}
            \norm{\widetilde{E}^\mathbf{Q}f}_{L^q(B_R,H)}
            \leq & \sum_{\nn\in\Z^d} \norm{\widetilde{E}^\mathbf{Q}f_\nn}_{L^q(B_R,H)}\\
            \lesssim & A_\alpha(H)^\beta R^\eta \sum_{\nn\in\Z^d} (1+|\nn|)^C \norm{f_\nn e^{-|\cdot|^2/2}}_{L^p(\R^d)}\\
            \lesssim& A_\alpha(H)^\beta R^\eta \sum_{\nn\in\Z^d} (1+|\nn|)^C e^{-|\nn|^2/2} \norm{f_\nn}_{L^p(\R^d)}\\
            \leq & A_\alpha(H)^\beta R^\eta \left( \sum_{\nn\in\Z^d} \Big((1+|\nn|)^C e^{-|\nn|^2/2} \Big)^{p'} \right)^{1/p'} \left( 
            \sum_{\nn\in\Z^d} \norm{f_\nn}_{L^p(\R^d)}^p \right)^{1/p}\\
            \lesssim & A_\alpha(H)^\beta R^\eta \norm{f}_{L^p(\R^d)}.
        \end{align*}
        And the proof is completed.
    \end{proof}

    Next, we show that restriction estimates of $E^\mathbf{Q}$, $\widetilde{E}^\mathbf{Q}$, and $\widetilde{E}_\varphi^\mathbf{Q}$ are all equivalent to each other. Besides justifying smoothing tricks, this also saves us from worrying about compatibility when we cite results in the literature later on, which may be stated for any of the three versions. In particular, the following proposition will be of use in the proof of $\circled{2}$ and $\circled{5}$ in Theorem~\ref{thm:relation_diagram}:
    \begin{proposition}\label{prop:restriction_equiv}
        Let $p,q \in [1,\infty]$, and $\varphi \in C_c^\infty(\R^d)$ with $\varphi\not\equiv0$. The following three estimates are equivalent to each other:

        \noindent $(i)$ $\norm{E^\mathbf{Q}f}_{L^q(\R^{d+n})} \lesssim \norm{f}_{L^p([0,1]^d)}, \,\forall f \in L^p([0,1]^d).$

        \noindent $(ii)$ $\norm{\widetilde{E}^\mathbf{Q} f}_{L^q(\R^{d+n})} \lesssim \norm{f}_{L^p(\R^d)}, \,\forall f \in L^p(\R^d).$

        \noindent $(iii)$ $\norm{\widetilde{E}_{\varphi}^\mathbf{Q} f}_{L^q(\R^{d+n})} \lesssim \norm{f}_{L^p(\R^d)}, \,\forall f \in L^p(\R^d).$
    \end{proposition}
    \begin{proof}
        The spirit is very similar to that of Proposition~\ref{prop:smooth_equiv}, so we only briefly sketch the proof here.

        $(i) \Rightarrow (ii)$: Partition $\R^d$ into unit cubes $\{\nn + [0,1]^d\}_{\nn\in \Z^d}$. By applying $L_\nn$ to $f$ and $L_\nn^*$ to $E_{\nn+[0,1]^d}^\mathbf{Q}f$, we see that $(i)$ implies
        % \footnote{Here we slightly abuse $E^\mathbf{Q}$, so that the integral domain is $\nn+[0,1]^d$ (or $\cup_{f}\supp f$) instead of $[0,1]^d$. We will always choose to do this when we think the context is clear and there is no potential confusion.}
        $$       \norm{E_{\nn+[0,1]^d}^\mathbf{Q}f}_{L^q(\R^{d+n})} \lesssim \norm{f}_{L^p(\nn +[0,1]^d)} $$
        with constant uniform in $\nn\in\Z^d$. By exploiting the rapid decay property of $e^{-|\xi|^2/2}$, we can sum the estimates on each $\nn + [0,1]^d$ up in a well-controlled way as we did in Proposition~\ref{prop:smooth_equiv}, which yields the desired estimate for $\widetilde{E}^\mathbf{Q}$.

        $(ii) \Rightarrow (iii)$: Let $\zeta = (\zeta',\zeta'') \in  \R^{d+n}$ with $\zeta' \in\R^d$ and $\zeta'' \in \R^n$. Let $\Phi(\zeta) \coloneqq \varphi(\zeta')\psi(\zeta'')$ for some fixed $\psi \in C_c^\infty(\R^n)$, such that $\Phi(\xi,\mathbf{Q}(\xi)) = \varphi(\xi)$ for all $\xi \in \R^d$, and $\widetilde{\Phi}(\zeta) \coloneqq \Phi(\zeta)e^{|\zeta'|^2/2}$. Then $\Phi, \widetilde{\Phi} \in C_c^\infty(\R^{d+n})$, and we have
        \begin{align*}
            \abs{\widetilde{E}_\varphi^\mathbf{Q}f} = \abs{(\Phi fd\mu_\mathbf{Q})^\vee} &= \abs{\left( \widetilde{\Phi}(\zeta) f(\zeta')e^{-|\zeta'|^2/2} 
                d\mu_\mathbf{Q} \right)^\vee}\\
            &= \abs{\left( \widetilde{\Phi}(\zeta)\right)^\vee * \left( f(\zeta') e^{-|\zeta'|^2/2} d\mu_\mathbf{Q} \right)^\vee}\\
            &= \abs{\left( \widetilde{\Phi}(\zeta)\right)^\vee * \widetilde{E}^\mathbf{Q}f}.
        \end{align*}
        Since $\widetilde{\Phi}  ^\vee \in \mathcal{S}(\R^{d+n}) \subset L^1(\R^{d+n})$, by Young's convolution inequality we have 
        \begin{align*}
            \norm{\widetilde{E}_\varphi^\mathbf{Q}f}_{L^q(\R^{d+n})} = \norm{\left( \widetilde{\Phi}(\zeta)\right)^\vee * \widetilde{E}^\mathbf{Q}f}_{L^q(\R^{d+n})} \lesssim \norm{\widetilde{E}^\mathbf{Q}f}_{L^q(\R^{d+n})} \lesssim \norm{f}_{L^p(\R^d)},
        \end{align*}
        as desired.

        $(iii) \Rightarrow (i)$: According to our assumption, there exists $\xi_0 \in \R^d$ such that $|\varphi(\xi_0)| = \max_{\xi\in\R^d}|\varphi(\xi)| \neq 0$. Without loss of generality, we may assume that $\varphi(\xi_0) > 0$. By continuity, we can then fix a dyadic $0 < c_0 < 1$ such that $\varphi> \varphi(\xi_0)/2$ on $\xi_0 + [0,c_0]^d$. Only considering those $f\in L^p(\xi_0 + [0,c_0]^d)$ and noting that $\varphi \sim 1$ over $\xi_0 + [0,c_0]^d$, we see that $(iii)$ implies  $$\norm{E_{\xi_0 + [0,c_0]^d}^\mathbf{Q}f}_{L^q(\R^{d+n})} \lesssim \norm{f}_{L^p(\xi_0 + [0,c_0]^d)}.$$ 
        Partition $[0,1]^d$ into $\{c_0\nn + [0,c_0]^d \}_{\nn\in\Z^d\cap[0, c_0^{-1})^d}$. By applying $L_{\xi_0 - c_0\nn}$ to $f$ and $L_{\xi_0 - c_0\nn}^*$ to $E^\mathbf{Q}f$, we see that $E^\mathbf{Q}: L^p(c_0\nn + [0,c_0]^d) \rightarrow L^q(\R^{d+n})$ uniformly holds for any $\nn \in \Z^d\cap [0,c_0^{-1})^d$. Since there are only finitely many pieces, by summing them up we get the desired boundedness of $E^\mathbf{Q}$ over the whole $[0,1]^d$.
    \end{proof}
    \begin{remark}\label{rmk:restriction_equiv}
        Firstly, one can see that the proof of Proposition~{\rm\ref{prop:restriction_equiv}} actually works for all {\rm TDI} manifolds {\rm(}Definition~{\rm\ref{def:TDI_mfd})}, not necessarily quadratic manifolds. Secondly, an immediate corollary of Proposition~{\rm\ref{prop:restriction_equiv}} is that for any two $\varphi_1, \varphi_2 \in C_c^\infty(\R^d)$ with $\varphi_1,\varphi_2\not\equiv0$, $\widetilde{E}_{\varphi_1}^\mathbf{Q}$ and $\widetilde{E}_{\varphi_2}^\mathbf{Q}$ have the same $L^p \rightarrow L^q$ boundedness property. Finally, there is no special role played by $[0,1]^d$ in ${\rm(}i{\rm)}$, and our proof works equally well when $E^{\mathbf{Q}}$ is replaced by  $E_B^{\mathbf{Q}}$ for any cube $B$ in $\R^d$ {\rm(}not necessarily of unit side length or parallel to the coordinate axes{\rm)}. In particular, since the form of ${\rm(}ii{\rm)}$ is symmetric and remains the same, we know that $E_B^{\mathbf{Q}}$ and ${E}^{\mathbf{Q}}$ have the same $L^p \rightarrow L^q$ boundedness property.
    \end{remark}














	\section{Uniform Fourier decay for quadratic manifolds}\label{sec2}

	In this section, we will provide a complete characterization of the uniform Fourier decay for quadratic manifolds of arbitrary codimensions, i.e., (\ref{thm:uniform_decay_eq}). As we have pointed out, this estimate is not only used in the proof of weighted restriction estimates in Section \ref{sec3}, but also plays a role in establishing relationships between various nondegeneracy conditions in Section~\ref{appendix:relationships}. Note that, when $n=1$, the Fourier decay of surface measure is essential and plays a role in many problems, such as Stein-Tomas estimates, Stein's spherical maximal estimates, Falconer's distance set problem, Strichartz estimates for the Schrödinger equation and so on. So we believe that (\ref{thm:uniform_decay_eq}), as one generation of the case $n=1$, will have further applications beyond those presented in this paper.




	In view of the equivalence between smooth and nonsmooth versions of Fourier extension operators (Proposition~\ref{prop:smooth_equiv}), we may without loss of generality work with $\widetilde{E}^\mathbf{Q}$ instead of $E^\mathbf{Q}$. Our main result in this subsection is as follows:
	\begin{theorem}[Uniform Fourier decay]\label{thm:uniform_decay}
		We have
		\begin{equation}\label{thm:uniform_decay_eq}
			|\widetilde{E}^\mathbf{Q}1(x)| \lesssim_\mathbf{Q} (1+|x|)^{-\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}}, \quad \quad x\in \R^{d+n}.
		\end{equation}
		Moreover, this bound is optimal in the sense that for any $ \gamma > \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$, we cannot have $|\widetilde{E}^\mathbf{Q}f(x)| \lesssim_\mathbf{Q} (1+|x|)^{-\gamma}$ uniformly for all $x\in \R^{d+n}$.
	\end{theorem}


	Before proving Theorem~\ref{thm:uniform_decay}, we first collect some preparatory results in matrix analysis.

	Given any quadratic form $\mathbf{Q}$, define $\rho_\mathbf{Q}$ to be its ``uniform spectral radius'', i.e.,
	\begin{align*}
		\rho_\mathbf{Q} \coloneqq \sup_{\theta\in\mathbb{S}^{n-1}} \rho({\overline{Q}(\theta)}),
	\end{align*}
	where $\rho(A) \coloneqq \{|\lambda|: \lambda \in \C \text{ is the largest eigenvalue of } A\}$ is the classical spectral radius for any $A \in \R^{d\times d}$.
	In other words, $\rho_\mathbf{Q}$ is the supremum of the spectral radii of all (normalized) linear combinations of Hessian matrices $\{\nabla_\xi^2 Q_j\}_{j=1}^n$ associated with $\mathbf{Q}$. However, it is not clear a priori whether $\rho_\mathbf{Q}$ is finite or not, as well as how it depends on $\mathbf{Q}$. The following results answer these questions.

	\begin{lemma}[\cite{hj12matrix}, Corollary 6.1.5]\label{lem:single_spectral}
		If $A = [a_{ij}] \in \R^{d\times d}$, then 
		\begin{align*}
			\rho(A) \leq \min\Big\{\max_i \sum_{j=1}^d |a_{ij}|, \max_j \sum_{i=1}^d |a_{ij}|\Big\}.
		\end{align*}
	\end{lemma}

	Note that Lemma~\ref{lem:single_spectral} is quantitative and works for any square matrices, not just for real symmetric matrices like $\overline{Q}(\theta)$. It is an immediate corollary of the famous Gershgorin circle theorem (one may consult Theorem 6.1.1 of \cite{hj12matrix}). By using this lemma, one can easily see that:
	\begin{corollary}\label{cor:uniform_spectral}
		We have $\rho_\mathbf{Q} \leq C_\mathbf{Q}$ for some constant $C_\mathbf{Q}$ depending only on $\mathbf{Q}$.
	\end{corollary}
	\begin{proof}
		Combine the definition of $\rho_\mathbf{Q}$, Lemma~\ref{lem:single_spectral}, and the following simple fact
		$$  \Big|\sum_{j=1}^n \theta_j b_j\Big| \leq |\theta||b| = |b|,   $$
		for any $\theta \in \mathbb{S}^{n-1} $ and $b \in \R^n$.
	\end{proof}
	By carrying out the proof carefully, it is easy to write out the upper bound $C_\mathbf{Q}$ explicitly. For later convenience, we may always assume $C_\mathbf{Q} \geq 1$.

	The following classical result in matrix analysis is vital for us to obtain uniform bounds:
	\begin{lemma}\label{lem:perturb}
		For any matrix in ${\rm S}(d,\mathbb{R})$, its eigenvalues depend continuously on its elements, in the sense that if $A = [a_{ij}], B = [b_{ij}] \in {\rm S}(d,\mathbb{R})$, $\lambda_1 \leq \cdots \leq \lambda_d$ are eigenvalues of $A$, $\widehat{\lambda_1} \leq \cdots \leq \widehat{\lambda_d}$ are eigenvalues of $A+B$, then for any $i,j$, there is
		$$ \sum_{k=1}^d |\widehat{\lambda_k} - \lambda_k| \rightarrow 0,  \quad \quad\quad\text{~as~~~}~~ b_{ij} \rightarrow 0.$$ 
	\end{lemma}
	\begin{proof}
		Although by linear algebra, all eigenvalues of any matrix in ${\rm S}(d,\mathbb{R})$ are real numbers, it is the easiest to work in the field of complex numbers. For any $M \in \R^{d\times d}$, let $f_M(\lambda) \coloneqq \det(\lambda I - M)$ be its characteristic polynomial. Then by our assumption, $\lambda_1 \leq \cdots \leq \lambda_d$ are the roots of 
		$f_A$, while $\widehat{\lambda_1} \leq \cdots \leq \widehat{\lambda_d}$ are the roots of $f_{A+B}$. Note that the coefficients of $f_{A+B}(\lambda)$ depend continuously on $b_{ij}$. Thus by Rouché's theorem, if $f_A(\lambda_0) = 0$ for some $\lambda_0 \in \{\lambda_1, \dots, \lambda_d\}$, then for any small $\epsilon > 0$ such that $\lambda_0$ is the unique zero in $B_\epsilon(\lambda_0)$, there exists $\delta>0$ such that $f_{A+B}$ and $f_A$ have the same number of zeros inside $B_\epsilon(\lambda_0)$ (each zero is counted as many times as its multiplicity) whenever $|b_{ij}| \leq \delta, \forall \,i,j$. This just tells us that $|\widehat{\lambda_k} - \lambda_k| \rightarrow 0$ for each $k$ as $b_{ij} \rightarrow 0, \forall\, i,j$, so the proof is completed. 
	\end{proof}
	% \begin{remark}
		%     For more general and quantitative versions of Lemma~\ref{lem:perturb} (with other proof strategies), one may consult Section 6.3 of \cite{hj12matrix}. \note{may remove?}
		% \end{remark}

	For any $\theta\in\mathbb{S}^{n-1}$, let $\{\mu_j(\theta)\}_{j=1}^d$ be the $d$ real eigenvalues of $\overline{Q}(\theta)$ and $\Lambda_k(\theta)$ be the $k$-th largest element (if there are multiple choices, then take any one of them) in $\{|\mu_j(\theta)|\}_{j=1}^d$. Then we have:
	\begin{corollary}\label{cor:k_continuity}
		For any $k$, $\Lambda_k(\theta)$ is a continuous function on $\mathbb{S}^{n-1}$.
	\end{corollary}
	In particular, by taking $k=1$ in Corollary~\ref{cor:k_continuity} and using the compactness of $\mathbb{S}^{n-1}$, we recover Corollary~\ref{cor:uniform_spectral} qualitatively. However, the full power of Corollary~\ref{cor:k_continuity} is that we can get a strictly positive lower bound of all eigenvalues, once we throw away those degenerate ones. Let 
	$$m \coloneqq \inf_{\theta\in \mathbb{S}^{n-1}} \#\Big\{j\in \{1,\dots,d\}: \mu_j(\theta)\neq0\Big\},$$ 
	then $\Lambda_1(\theta), \dots, \Lambda_m(\theta)$ are all strictly positive continuous functions on $\mathbb{S}^{n-1}$. Thus, by the compactness of $\mathbb{S}^{n-1}$, we get $\Lambda_k(\theta) \geq c_\mathbf{Q}$ on $\mathbb{S}^{n-1}$ for any $k = 1,\dots,m$, where $c_\mathbf{Q}$ is a strictly positive constant depending only on $\mathbf{Q}$. 

	We can summarize what we have got so far as:
	\begin{theorem}\label{thm:U_L_bound_eigen}
		For any $\theta \in \mathbb{S}^{n-1}$ and $k=1,...,m$, we have
		$$0<c_\mathbf{Q} \leq \Lambda_k(\theta) \leq C_\mathbf{Q} <\infty.$$ 
	\end{theorem}

	Before proceeding, let us first point out that $m$ actually enjoys a clean algebraic characterization by language of $\mathfrak{d}_{d',n'}(\mathbf{Q})$: 
	\begin{lemma}\label{lem:alg_char_m}
		$m = \mathfrak{d}_{d,1}(\mathbf{Q})$. 
	\end{lemma}
	\begin{proof} 
		Set $x''=|x''| \theta$. Then
		\begin{align*}
			\mathfrak{d}_{d,1}(\mathbf{Q}) & = \inf_{\substack{M\in \R^{d\times d}\\ \rank(M) = d}} \inf_{\substack{M'\in \R^{n\times 1}\\ \rank(M) = 1}} {\rm NV}((\mathbf{Q}\circ M) \cdot M')\\
			& = \inf_{x'' \in \R^n\setminus\{0\}}
			\inf_{\substack{M\in \R^{d\times d}\\ \rank(M) = d}} {\rm NV}(\overline{Q}(x'') \circ M)\\
			& = 
			\inf_{x'' \in \R^n\setminus\{0\}} \rank(\overline{Q}(x''))\\
			& = \inf_{\theta \in \mathbb{S}^{n-1}} \rank(\overline{Q}(\theta))\\
			& = \inf_{\theta \in \mathbb{S}^{n-1}} \#\{j\in \{1,\dots,d\}: \mu_j(\theta)\neq0\}\\
			& = m,
		\end{align*}
		where in the third line we used Lemma A.2 in \cite{ggo23}.
	\end{proof}
    Although the proof of Lemma~\ref{lem:alg_char_m} is fairly straightforward, it is the key bridge relating Fourier decay to algebraic quantities in the literature.

	Now we begin the proof of Theorem~\ref{thm:uniform_decay}, which is divided into several steps.
	\begin{proposition}\label{prop:direct_compute}
		The following bound holds uniformly for all $x \in \R^{d+n}$:
		\begin{align*}
			\abs{\widetilde{E}^\mathbf{Q}1 (x)} \lesssim e^{-\frac{1}{2}\frac{|x'|^2}{1+\rho_\mathbf{Q}^2|x''|^2}} \cdot \prod_{j=1}^d (1+|x''||\mu_j(\theta)|)^{-\frac{1}{2}},
		\end{align*}
		where $\theta = x''/|x''| \in \mathbb{S}^{n-1}$. 
	\end{proposition}
	\begin{proof}
		We perform some direct computations, which is inspired by \cite{mockenhaupt96}:
		\begin{align}\label{eq:tilde_E_pointwise}
			\abs{\widetilde{E}^\mathbf{Q}1(x)} 
			& = \abs{\int_{\R^d} e^{i(x'\cdot\xi + \xi^T\cdot \overline{Q}(x'')\cdot\xi/2)} \cdot e^{-|\xi|^2/2} d\xi}\nonumber\\
			& = \abs{\int_{\R^d} e^{i x'\cdot\xi} e^{- \xi^T\cdot (I - i\overline{Q}(x'')) \cdot\xi/2} d\xi}\nonumber\\
			& = \abs{(2\pi)^{\frac{d}{2}} \cdot \det(I - i\overline{Q}(x''))^{-\frac{1}{2}} \cdot e^{-{x'}^T\cdot (I - i\overline{Q}(x''))^{-1} \cdot x'/2}} \nonumber\\
			& \sim \abs{\det(I - i\overline{Q}(x''))}^{-\frac{1}{2}} \cdot \abs{e^{-{x'}^T\cdot (I - i\overline{Q}(x''))^{-1} \cdot x'/2}},
		\end{align}
		where in the second to last line we used Lemma 2.4 in \cite{mockenhaupt96}.

		We estimate the two factors above separately. Firstly, by simply noting that $\{1 - i|x''|\mu_j(\theta)\}_{j=1}^d$ are eigenvalues of $I - i\overline{Q}(x'')$, we get
		\begin{align}\label{eq:det_eigen_express}
			\abs{\det(I - i\overline{Q}(x''))}^{-\frac{1}{2}} 
			=& \abs{\prod_{j=1}^d (1-i|x''|\mu_j(\theta))}^{-\frac{1}{2}} \nonumber\\
			=& \prod_{j=1}^d (1 + |x''|^2|\mu_j(\theta)|^2)^{-\frac{1}{4}} \nonumber\\
			\sim & \prod_{j=1}^d (1 + |x''||\mu_j(\theta)|)^{-\frac{1}{2}}.
		\end{align}
		Secondly, by linear algebra, there exists $O \in {\rm O}(d,\mathbb{R})$ such that
		\begin{align*}
			\overline{Q}(x'') = |x''|\cdot O^T
			\begin{bmatrix}
				\mu_1(\theta) & & \\
				& \ddots & \\
				& & \mu_d(\theta)
			\end{bmatrix} O.
		\end{align*}
		Thus
		\begin{align*}
			I - i \overline{Q}(x'') & = O^T
			\begin{bmatrix}
				1 - i|x''|\mu_1(\theta) & & \\
				& \ddots & \\
				& & 1 - i|x''|\mu_d(\theta)
			\end{bmatrix} O,\\
		\end{align*}
		and then
		\begin{align*}
			(I - i \overline{Q}(x''))^{-1} & = 
			O^T
			\begin{bmatrix}
				\frac{1}{1 - i|x''|\mu_1(\theta)} & & \\
				& \ddots & \\
				& & \frac{1}{1 - i|x''|\mu_d(\theta)}
			\end{bmatrix} O\\
			& = O^T
			\begin{bmatrix}
				\frac{1 + i|x''|\mu_1(\theta)}{1 + |x''|^2|\mu_1(\theta)|^2} & & \\
				& \ddots & \\
				& & \frac{1 + i|x''|\mu_d(\theta)}{1 + |x''|^2|\mu_d(\theta)|^2}
			\end{bmatrix} O,
		\end{align*}
		which implies
		\begin{align*}
			\abs{e^{-{x'}^T\cdot (I - i\overline{Q}(x''))^{-1} \cdot x'/2)}} & = 
			\abs{ \exp\left(- \frac{1}{2} (Ox')^T
				\begin{bmatrix}
					\frac{1 + i|x''|\mu_1(\theta)}{1 + |x''|^2|\mu_1(\theta)|^2} & & \\
					& \ddots & \\
					& & \frac{1 + i|x''|\mu_d(\theta)}{1 + |x''|^2|\mu_d(\theta)|^2}
				\end{bmatrix} (Ox') \right) }\\
			& = \exp\left(- \frac{1}{2} (Ox')^T
			\begin{bmatrix}
				\frac{1}{1 + |x''|^2|\mu_1(\theta)|^2} & & \\
				& \ddots & \\
				& & \frac{1}{1 + |x''|^2|\mu_d(\theta)|^2}
			\end{bmatrix} (Ox') \right) \\
			& \leq \exp\left(- \frac{1}{2} (Ox')^T
			\begin{bmatrix}
				\frac{1}{1 + |x''|^2\rho_\mathbf{Q}^2} & & \\
				& \ddots & \\
				& & \frac{1}{1 + |x''|^2\rho_\mathbf{Q}^2}
			\end{bmatrix} (Ox') \right)\\
			& = e^{-\frac{1}{2}\frac{|Ox'|^2}{1 + |x''|^2\rho_\mathbf{Q}^2}} \\
			& = e^{-\frac{1}{2}\frac{|x'|^2}{1 + |x''|^2\rho_\mathbf{Q}^2}}.
		\end{align*}
		And the proof is completed.
	\end{proof}

	Proposition~\ref{prop:direct_compute} immediately implies the following Fourier decay estimate, which is essentially Lemma 2.1.1 of \cite{banner02}:
	\begin{proposition}\label{prop:recover_banner}
		The following bound holds uniformly for all $x \in \R^{d+n}$:
		\begin{align*}
			\abs{\widetilde{E}^\mathbf{Q}1 (x)} \lesssim \prod_{j=1}^d (1+|x||\mu_j(\theta)|)^{-\frac{1}{2}},
		\end{align*}
		where $\theta = x''/|x''| \in \mathbb{S}^{n-1}$. 
	\end{proposition}
	\begin{proof}
		If $|x| \leq 10$, note $|x||\mu_j(\theta)| \leq 10C_\mathbf{Q}$, then 
		\begin{align*}
			\abs{\widetilde{E}^\mathbf{Q}1 (x)} \lesssim 1 &\lesssim_\mathbf{Q} \prod_{j=1}^d(1+10C_\mathbf{Q})^{-\frac{1}{2}}\leq \prod_{j=1}^d(1+|x||\mu_j(\theta)|)^{-\frac{1}{2}}.
		\end{align*}
		So without loss of generality, we may assume $|x| \geq 10$.

		By Proposition~\ref{prop:direct_compute} and Corollary~\ref{cor:uniform_spectral}, we have
		\begin{align*}
			\abs{\widetilde{E}^\mathbf{Q}1 (x)} \lesssim e^{-\frac{1}{2}\frac{|x'|^2}{1+C_\mathbf{Q}^2|x''|^2}} \cdot \prod_{j=1}^d (1+|x''||\mu_j(\theta)|)^{-\frac{1}{2}}.
		\end{align*}
		If $|x''| \leq 1$, then $|x'|\geq |x|/2$ as $|x|\geq 10$. Thus
		\begin{align*}
			\abs{\widetilde{E}^\mathbf{Q}1 (x)} & \lesssim e^{-\frac{1}{2}\frac{|x'|^2}{1+C_\mathbf{Q}^2|x''|^2}}\\ & \leq e^{-\frac{1}{8}\frac{|x|^2}{1+C_\mathbf{Q}^2}}\\
			& \lesssim_\mathbf{Q} \prod_{j=1}^d (1+C_\mathbf{Q}|x|)^{-\frac{1}{2}}\\
			& \leq \prod_{j=1}^d(1+|x||\mu_j(\theta)|)^{-\frac{1}{2}},
		\end{align*}
		where in the last line we used $|\mu_{j}(\theta)| \leq C_\mathbf{Q}$. 
		If $|x''|\geq 1$, then let $u \coloneqq |x'|/|x''| \in (0,\infty)$. We have
		\begin{align*}
			\abs{\widetilde{E}^\mathbf{Q}1 (x)} & \lesssim e^{-\frac{1}{4}\frac{|x'|^2}{C_\mathbf{Q}^2|x''|^2}} \cdot \prod_{j=1}^d \left(\frac{|x''|}{|x|} + \frac{|x''|}{|x|}|x||\mu_j(\theta)|\right)^{-\frac{1}{2}}\\
			& = \left( 
			\frac{|x|}{|x''|} \right)^{\frac{d}{2}}e^{-\frac{1}{4}\frac{|x'|^2}{C_\mathbf{Q}^2|x''|^2}} \cdot \prod_{j=1}^d \left(1 + |x||\mu_j(\theta)|\right)^{-\frac{1}{2}}\\
			& = \left( 
			1 + u^2 \right)^{\frac{d}{4}}e^{-\frac{1}{4}\frac{u^2}{C_\mathbf{Q}^2}} \cdot \prod_{j=1}^d \left(1 + |x||\mu_j(\theta)|\right)^{-\frac{1}{2}}\\
			& \lesssim_\mathbf{Q} \prod_{j=1}^d \left(1 + |x||\mu_j(\theta)|\right)^{-\frac{1}{2}}.
		\end{align*}
		So in any case, the proof is completed.
	\end{proof}

	Now we are finally ready to prove our main result.
	\begin{proof}[Proof of Theorem~\ref{thm:uniform_decay}] 
		Starting from Proposition~\ref{prop:recover_banner}, we have 
		\begin{align*}
			\abs{\widetilde{E}^\mathbf{Q}1 (x)} & \lesssim \prod_{j=1}^d (1+|x||\mu_j(\theta)|)^{-\frac{1}{2}}\\
			& \leq \prod_{k=1}^m (1 + \Lambda_k(\theta)|x|)^{-\frac{1}{2}}\\
			& \leq \prod_{k=1}^m (1 + c_\mathbf{Q}|x|)^{-\frac{1}{2}}\\
			& \lesssim_\mathbf{Q} (1 + |x|)^{-\frac{m}{2}}\\
			& = (1 + |x|)^{-\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}}
		\end{align*}
		as desired. Here in the third line we used \text{Theorem }\ref{thm:U_L_bound_eigen}, and in the last line we used \text{Lemma }\ref{lem:alg_char_m}.

		To see the optimality of our estimate, take $\theta_0 \in \mathbb{S}^{n-1}$ such that $m = \# \{j\in\{1,\dots,d\}: \mu_j(\theta_0)\neq 0\}$, and consider $x =(x',x'')=(0,|x''|\theta_0)$. By computations in the proof of Proposition~\ref{prop:direct_compute}, we have
		\begin{align*}
			\abs{\widetilde{E}^\mathbf{Q}f(x)} & = \abs{(2\pi)^{\frac{d}{2}} \cdot \det(I - i\overline{Q}(x''))^{-\frac{1}{2}}}\\
			& \sim \prod_{j=1}^d(1 + |x''||\mu_j(\theta_0)|)^{-\frac{1}{2}}\\
			& = \prod_{j=1}^m (1 + |x| \Lambda_j(\theta_0))^{-\frac{1}{2}}\\
			& \geq \prod_{j=1}^m (1 + |x|  C_\mathbf{Q})^{-\frac{1}{2}}\\
			& \gtrsim_\mathbf{Q} (1 + |x|)^{-\frac{m}{2}}\\
			& = (1 + |x|)^{-\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}},
		\end{align*}
		where in the fourth line we used \text{Theorem }\ref{thm:U_L_bound_eigen}, and in the last line we used \text{Lemma }\ref{lem:alg_char_m}.
		Suppose that we have $|\widetilde{E}^\mathbf{Q}f(x)| \lesssim_\mathbf{Q} (1+|x|)^{-\gamma}$ for some $\gamma > \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$, then $(1 + |x|)^{-\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}} \lesssim (1+|x|)^{-\gamma}$, which fails when $|x| \gg_\mathbf{Q} 1$, a contradiction. Thus the optimality is proved. 
	\end{proof}

	Although Theorem~\ref{thm:uniform_decay} is already sufficient for our applications, Gaussian smoothing factors are uncommon in the literature of oscillatory integrals. For example, Lemma 2.1.1 of \cite{banner02} uses compactly supported smooth bumps ($C_c^\infty(\R^d)$) in place of Gaussian functions. By taking $\psi = \mathbf{Q}$ and $U = \supp \varphi$ in (\ref{def:bump_extension}) and using the notation (\ref{098765}), we are led to   \begin{align}\label{eq:oscillatory_integral}
		\widetilde{E}_\varphi^\mathbf{Q}f(x) \coloneqq \int_{\R^d} e^{i(x'\cdot\xi + \xi^T\cdot \overline{Q}(x'')\cdot\xi/2)} f(\xi) \cdot \varphi(\xi) d\xi, \quad\quad  x = (x',x'') \in \R^{d+n},
    \end{align}
    where $\varphi \in C_c^\infty(\R^d)$ with $\varphi \not\equiv 0$. The next result tells us that $\widetilde{E}_\varphi^\mathbf{Q}$ satisfies the same uniform Fourier decay estimate as $\widetilde{E}^\mathbf{Q}$.
	\begin{corollary}\label{cor:recover_banner}
		For any $\varphi \in C_c^\infty(\R^d)$ with $\varphi\not\equiv0$, we have 
		\begin{align*}
			\abs{\widetilde{E}_\varphi^\mathbf{Q}1 (x)} \lesssim_\mathbf{Q} (1+|x|)^{-\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}}, \quad \quad x\in \R^{d+n}.
		\end{align*}
		Moreover, this bound is optimal in the sense that for any $ \gamma > \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$, we cannot have $|\widetilde{E}_\varphi^\mathbf{Q}f(x)| \lesssim_\mathbf{Q} (1+|x|)^{-\gamma}$ uniformly for all $x\in \R^{d+n}$.
	\end{corollary}
	\begin{proof}

		Define $\Phi$ and $\widetilde{\Phi}$ as in the proof of $(ii) \Rightarrow (iii)$ in Proposition~\ref{prop:restriction_equiv}. Then 
        \begin{align*}
            \abs{\widetilde{E}_\varphi^\mathbf{Q}1} = \abs{(\Phi d\mu_\mathbf{Q})^\vee} = \abs{\left( \widetilde{\Phi}(\zeta) e^{-|\zeta'|^2/2} 
                d\mu_\mathbf{Q} \right)^\vee} = \abs{\left( \widetilde{\Phi}(\zeta)\right)^\vee * \left( e^{-|\zeta'|^2/2} d\mu_\mathbf{Q} \right)^\vee}.
        \end{align*}
		Since $\widetilde{\Phi}  ^\vee \in \mathcal{S}(\R^{d+n})$, we have $\abs{\widetilde{\Phi}  ^\vee}  \lesssim_N (1 + |\cdot|)^{-N}$ for any $N \in \N^+$. Also note that $( e^{-|x'|^2/2} d\mu_\mathbf{Q})^\vee = \widetilde{E}^\mathbf{Q}1$. Therefore, we can apply \text{Theorem }\ref{thm:uniform_decay} to get
		\begin{align*}
			\abs{\widetilde{E}_\varphi^\mathbf{Q}1} & \leq \abs{\widetilde{\Phi}^\vee} * \abs{\widetilde{E}^\mathbf{Q}1} \lesssim_{\mathbf{Q}, N} (1 + |\cdot|)^{-N} * (1 + |\cdot|)^{-\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}} \lesssim_\mathbf{Q} (1 + |\cdot|)^{-\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}},
		\end{align*}
		where in the last step we used the properties of convolutions in Appendix B.1 of \cite{grafakos2014modern}.

		To prove the optimality of the estimate, it is not easy to compute everything directly as in the proof of Theorem~\ref{thm:uniform_decay}, as the bump $\varphi$ is arbitrary. To address this issue, we need to first do some reductions.

		Our strategy is to argue by contradiction. Suppose $|\widetilde{E}_\varphi^\mathbf{Q}1(x)| \lesssim_\mathbf{Q} (1+|x|)^{-\gamma}$ for some $\gamma > \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$. Since $\varphi \not \equiv 0$, there exists $\xi_0 \in \R^d$ such that $\varphi(\xi_0) \neq 0$. By change of variables $\xi \mapsto \xi_0 + \xi$, we have
		\begin{align*}
			\abs{\widetilde{E}_\varphi^\mathbf{Q}1(x)} & = \abs{ \int_{\R^d} e^{i\left(x'\cdot(\xi_0 + \xi) + (\xi_0 + \xi)^T\cdot \overline{Q}(x'')\cdot(\xi_0 + \xi)/2\right)} \varphi(\xi_0 + \xi) d\xi } \\
			& = \abs{ \int_{\R^d} e^{i\left( (x' + \xi_0^T \cdot \overline{Q}(x'') )\cdot \xi + \xi^T\cdot \overline{Q}(x'')\cdot \xi/2\right)} \varphi(\xi_0 + \xi) d\xi } \\
			& \eqqcolon \abs{ \int_{\R^d} e^{i\left( \tilde{x}' \cdot \xi + \xi^T\cdot \overline{Q}(\tilde{x}'')\cdot \xi/2\right)} \tilde{\varphi}(\xi) d\xi } = \abs{\widetilde{E}_{\tilde{\varphi}}^\mathbf{Q}1(\tilde{x})},
		\end{align*}
		where $\tilde{x}' \coloneqq x' + \xi_0^T \cdot \overline{Q}(x'')$, $\tilde{x}'' \coloneqq x''$, $\tilde{x} = (\tilde{x}', \tilde{x}'')$, and $\tilde{\varphi}(\xi) \coloneqq \varphi(\xi_0 + \xi)$. Thus by our hypothesis, we have
		\begin{align*}
			\abs{\widetilde{E}_{\tilde{\varphi}}^\mathbf{Q}1(\tilde{x})} 
			& \lesssim_\mathbf{Q} (1+|x|)^{-\gamma}\\
			& = \left( 1 + \sqrt{|x'|^2 + |x''|^2} \right)^{-\gamma}\\
			& = \left( 1 + \sqrt{|\tilde{x}' - \xi_0^T \cdot \overline{Q}(\tilde{x}'')|^2 + |\tilde{x}''|^2} \right)^{-\gamma}.
		\end{align*}
		Note that there exists some constant $C \geq 1$ depending on $\xi_0$ and $\mathbf{Q}$, such that $|\xi_0^T \cdot \overline{Q}(\tilde{x}'')| \leq C |\tilde{x}''|$. Therefore, if $|\tilde{x}'| \leq 2C |\tilde{x}''|$, then $|\tilde{x}| \sim |\tilde{x}''|$, and $\abs{\widetilde{E}_{\tilde{\varphi}}^\mathbf{Q}1(\tilde{x})} \lesssim_\mathbf{Q} (1 + |\tilde{x}''|)^{-\gamma} \sim (1 + |\tilde{x}|)^{-\gamma}$; while if $|\tilde{x}'| > 2C |\tilde{x}''|$, then $|\tilde{x}' - \xi_0^T \cdot \overline{Q}(\tilde{x}'')| > |\tilde{x}'|/2$, and still $\abs{\widetilde{E}_{\tilde{\varphi}}^\mathbf{Q}1(\tilde{x})} \lesssim (1 + |\tilde{x}|)^{-\gamma}$. So we get $\abs{\widetilde{E}_{\tilde{\varphi}}^\mathbf{Q}1(\tilde{x})} \lesssim (1 + |\tilde{x}|)^{-\gamma}$ for all $\tilde{x} \in \R^{d+n}$. This means without loss of generality, we may assume $\varphi(0) \neq 0$.

		By Lemma~\ref{lem:alg_char_m}, there exists $\theta_0 \in \mathbb{S}^{n-1}$ such that $\mathfrak{d}_{d,1}(\mathbf{Q}) = \rank (\overline{Q}(\theta_0)) = m$. Also, by linear algebra, there exists $O \in {\rm O}(d,\R)$ such that 
		\begin{align*}
			\overline{Q}(\theta_0) = 
			O^T
			\begin{bmatrix}
				\mu_1(\theta_0) & & \\
				& \ddots & \\
				& & \mu_d(\theta_0)
			\end{bmatrix} O.
		\end{align*}
		Without loss of generality, we may assume $\mu_j(\theta_0) \neq 0$ for $j\leq m$ and $\mu_j(\theta_0) = 0$ for $j>m$. Since we assume $\varphi(0) \neq 0$, there exists $r > 0$ such that $\varphi(O^T\cdot) \neq 0$ on $[-r,r]^d$. Fix any nonnegative even function $\phi$ on $\R$ such that $\phi(0)>0$ and $\supp\phi \subset [-c_\mathbf{Q}^{1/2}r,c_\mathbf{Q}^{1/2}r]$, where $c_\mathbf{Q}$ comes from Theorem~\ref{thm:U_L_bound_eigen}. Let 
		$$\varphi_0(\xi) \coloneqq \prod_{j=1}^m \phi\Big(|\mu_j(\theta_0)|^{\frac{1}{2}}\xi_j\Big) \cdot \prod_{j=m+1}^d \phi\Big(c_\mathbf{Q}^{\frac{1}{2}}\xi_j\Big).$$ 
		Then $\supp\varphi_0 \subset [-r,r]^d$, and by further truncating $\widetilde{E}_\varphi^\mathbf{Q}1$ with respect to $\varphi_0(O\cdot)/\varphi \in C_c^\infty(\R^d)$ as in the first part of the proof, we know that 
		$$\abs{\widetilde{E}_{\varphi_0(O\cdot)}^\mathbf{Q}1(x)} \lesssim_\mathbf{Q} (1+|x|)^{-\gamma}, \quad \quad \forall ~\gamma > \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2} = \frac{m}{2}.$$ 
		Consider $x = (x',x'') = (0, |x''|\theta_0)$, then 
	\begin{align*}
			\widetilde{E}_{\varphi_0(O\cdot)}^\mathbf{Q}1(x) & = \int_{\R^d} e^{i|x|(\xi^T\cdot \overline{Q}(\theta_0)\cdot\xi/2)} \varphi_0(O\xi) d\xi\\
			& = \int_{\R^d} e^{i\frac{|x|}{2} \sum_{j=1}^m \mu_j(\theta_0) (O\xi)_j^2} \varphi_0(O\xi) d\xi\\
			& = \int_{\R^d} e^{i\frac{|x|}{2} \sum_{j=1}^m \mu_j(\theta_0) \xi_j^2} \varphi_0(\xi) d\xi\\
			& = \prod_{j=1}^m \int_{\R} e^{i\frac{|x|}{2}\mu_j(\theta_0)\xi_j^2} \phi\Big(|\mu_j(\theta_0)|^{\frac{1}{2}} \xi_j\Big) d\xi_j \cdot \prod_{j=m+1}^d \int_{\R} \phi\Big(c_\mathbf{Q}^{\frac{1}{2}}\xi_j\Big)d\xi_j\\
			& = \Big(c_\mathbf{Q}^{-\frac{1}{2}}\int\phi\Big)^{d-m} \prod_{j=1}^m 
			|\mu_j(\theta_0)|^{-\frac{1}{2}} \cdot \prod_{j=1}^m \int_{\R} e^{\pm i\frac{|x|}{2}\xi_j^2} \phi(\xi_j) d\xi_j \\
			& \sim_{\phi,\mathbf{Q}} \prod_{j=1}^m \int_{\R} e^{\pm i\frac{|x|}{2}\xi_j^2} \phi(\xi_j) d\xi_j.
	\end{align*}
		As $\phi$ is real-valued, the ``$\pm$'' in the exponential does not affect the absolute value. So we have
		\begin{align*}
			\abs{\widetilde{E}_{\varphi_0(O\cdot)}^\mathbf{Q}1(x)} \sim_{\phi,\mathbf{Q}} \prod_{j=1}^m \abs{\int_{\R} e^{ i\frac{|x|}{2}\xi_j^2} \phi(\xi_j) d\xi_j} = \abs{\int_{\R} e^{ i\frac{|x|}{2}u^2} \phi(u) du}^m \eqqcolon \Big|I\Big( \frac{|x|}{2}\Big)\Big|^m,
		\end{align*}
		where 
		$$I(\lambda) \coloneqq \int_{\R} e^{ i\lambda u^2} \phi(u) du,    \quad\quad \forall~ \lambda \in \R.$$
		Plugging this into 
		$$\abs{\widetilde{E}_{\varphi_0(O\cdot)}^\mathbf{Q}1(x)} \lesssim_\mathbf{Q} (1+|x|)^{-\gamma}, \quad \quad \gamma > \frac{m}{2},$$ 
		we get 
		$$\Big|I\Big( \frac{|x|}{2}\Big)\Big| \lesssim_{\phi,\mathbf{Q}} (1 + |x|)^{- \frac{\gamma}{m}}, \quad \quad \forall~ |x|>0,$$ i.e., there exists $\gamma'>\frac{1}{2}$ such that 
		$$\abs{I(\lambda)} \lesssim_{\phi,\mathbf{Q}} (1 + \lambda)^{-\gamma'},\quad \quad  \forall~ \lambda>0.$$ 
		Since $\phi$ is real-valued, we know that $|I(\lambda)|$ is even, which means
		\begin{align}\label{eq:one_dim_oscillatory}
			\abs{I(\lambda)} \lesssim_{\phi,\mathbf{Q}} (1 + |\lambda|)^{-\gamma'}, \quad \forall\, \lambda\in\R.
		\end{align}
		On the other hand, by the fact that $\phi$ is even and change of variables $u \mapsto \sqrt{v}$, we get $$I(\lambda) = 2\int_0^\infty e^{ i\lambda u^2} \phi(u) du = \int_0^\infty e^{ i\lambda v} \frac{\phi(\sqrt{v})}{\sqrt{v}} dv, \quad\quad \forall\, \lambda\in\R.$$ 
		If we let 
		$$\tilde{\phi}(v) \coloneqq \chi_{[0,\infty)}(v) \cdot   \frac{\phi(\sqrt{v})}{\sqrt{v}},$$ 
		then (\ref{eq:one_dim_oscillatory}) together with $\gamma'>\frac{1}{2}$ tells us that $I(\lambda) = (\tilde{\phi})^\vee(\lambda)$ lies in $L^2(\R)$. By Plancherel's identity, we must have $\tilde{\phi} \in L^2(\R)$. However, this is impossible, as $\phi(\sqrt{v})^2/v \sim 1/v$ near $0$ (recall $\phi(0)>0$), and $1/v$ is not integrable. Thus our proof by contradiction is completed, and the Fourier decay is optimal.
	\end{proof}
	\begin{remark}
		Corollary~{\rm \ref{cor:recover_banner}} can be interpreted as a certain stability/uniformity result for the oscillatory integral {\rm (\ref{eq:oscillatory_integral})} when $f=1$, which can be rewritten as
		\begin{align*}
			I(\lambda, t) = \int_{\R^d} e^{i \lambda \phi(\xi,t)} \varphi(\xi) d\xi,
		\end{align*}
		where $\lambda = |x|$, $t = (t',t'') \in \R^d \times \R^n $ with $t' = x'/|x|, t'' = x''/|x|$, and $\phi(\xi,t) = t'\cdot\xi + \xi^T\cdot \overline{Q}(t'')\cdot\xi/2$. Corollary~{\rm \ref{cor:recover_banner}} tells us that 
		$$I(\lambda,t) \lesssim \lambda^{-\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}}, \quad \quad \text{uniform~in~}t\in \mathbb{S}^{d+n-1}.$$
		Our setting here closely follows Chapter {\rm 8} of \cite{gilula2016real}, which also pointed out that nondegeneracy may help us obtain stability. This is indeed the case for us: Although $\overline{Q}(\theta)$ may be more degenerate for some $\theta$ than the others, if we only care about the ``common'' degree {\rm(}$m = \mathfrak{d}_{d,1}(\mathbf{Q})${\rm)} of nondegeneracy, then we can still have a uniform estimate. However, our method relies heavily on linear algebra for quadratic forms, so does not work for manifolds of higher degrees. Also, our stability is regarding $\{\phi(\xi,t): t\in \mathbb{S}^{d+n-1}\}$, while a more widely studied kind of stability is regarding the family of phase functions whose derivatives are uniformly lower bounded. The latter is in general much harder, especially in multidimensional cases. One may consult \cite{ccw99} or \cite{pss01} for more historical remarks and results on the stability of oscillatory integrals.
	\end{remark}






	\section{The proof of Theorem \ref{th1}}\label{sec3}


	 In this section, we mainly concern the proofs of (\ref{t1e1}) and (\ref{t1e2}) in Theorem \ref{th1}.


     \subsection{Shayya's argument}\label{subsec:shayya}\phantom{x}

   	This subsection is devoted to prove (\ref{t1e1}). Since the last bound in (\ref{t1e1}) is the classical Agmon-H\"ormander inequality (\ref{AH ineq}), it suffices to prove the first and second bounds in (\ref{t1e1}). Our proof mainly follows Shayya's argument \cite{shayya21}. In fact, compared with (\ref{s1e1}),  Shayya studied stronger weighted estimates, which are global and include accurate information on the weight $H$, i.e.,
	\begin{equation}\label{s2e1}
		\|E^{\mathbf{Q}}f\|_{L^p(\mathbb{R}^{d+n},H)}\lesssim  A_\alpha(H)^{\frac{1}{p}}\|f\|_{L^2([0,1]^d)}.
	\end{equation}
	For $0<\alpha\leq d+n$ and $1\leq p\leq \infty$, define $P(\alpha,\mathbf{Q})$ to be the infimum of all numbers $p$ such that (\ref{s2e1}) holds for all functions $f \in L^2([0,1]^d)$ and all $\alpha$-dimensional weights $H$ on $\mathbb{R}^{d+n}$. 

	When $S_{\mathbf{Q}}$ is a paraboloid or a hyperbolic paraboloid with $n=1$, Shayya proved 
    		\begin{align}\label{shayya_result}
			~P(\alpha,\mathbf{Q})\leq 
			\begin{cases}
				~	2, \quad \quad\quad \quad    & 0<  \alpha < \frac{d}{2},   \\
				~	\frac{4\alpha}{d}, \quad \quad \quad\quad &\alpha\geq \frac{d}{2}. 
			\end{cases}
		\end{align}
    We will generalize this result to all quadratic manifolds as follows:
        \begin{align}\label{shayya_result2}
			~P(\alpha,\mathbf{Q})\leq 
			\begin{cases}
				~	2, \quad \quad\quad \quad    & 0<\alpha< \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2},   \\
				~	\frac{4\alpha}{\mathfrak{d}_{d,1}(\mathbf{Q})}, \quad \quad \quad\quad &\alpha\geq \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}. 
			\end{cases}
		\end{align}

    We first use Theorem~\ref{thm:uniform_decay} to prove the first bound in (\ref{shayya_result2}). Its proof is similar to that in Section 6 in \cite{shayya21}, with some small modifications. For completeness, we briefly sketch the proof here.

	By Proposition~\ref{prop:smooth_equiv}, it suffices to show\footnote{For the optimal uniform Fourier decay rate $\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$ to hold, it is important to replace the roughly truncated surface measure with a suitably smoothed one. Such a technical issue is not taken care of by Shayya \cite{shayya21}. There is no such problem if we were dealing with the sphere, which is a closed manifold.} 
	\begin{equation}\label{s2ef2}
		\|\widetilde{E}^{\mathbf{Q}}f\|_{L^p(\mathbb{R}^{d+n},H)}\lesssim  A_\alpha(H)^{\frac{1}{p}}\|f\|_{L^2([0,1]^d)}
	\end{equation}
	for all $p>2$, when $0<\alpha< \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$. Set $dw(x) \coloneqq H(x)dx$, then by the layer cake representation, we have
	\begin{equation}\label{s2ef3}
		\|\widetilde{E}^{\mathbf{Q}}f\|_{L^p(\mathbb{R}^{d+n},H)}^p =p\int_0^{\|f\|_{L^1}} \lambda^{p-1} w(\{  |\widetilde{E}^{\mathbf{Q}}f|\geq \lambda  \}) d\lambda,
	\end{equation}
	where the upper limit of integration arises from a trivial estimate
	$$    \|\widetilde{E}^{\mathbf{Q}}f\|_{L^\infty(\R^{d+n})} \leq \|f\|_{L^1([0,1]^d)}.   $$
	By dividing $\widetilde{E}^{\mathbf{Q}}f$ into positive part, negative part, real part, and imaginary part, combined with the  distribution inequality, it is enough to consider the set $\{ \Re (\widetilde{E}^{\mathbf{Q}}f )\geq \lambda/4  \}$, which we denote by $G$. So we only need to estimate $w(G)$. On the one hand, by Parseval’s relation and H\"older's inequality, we have 
	\begin{align*}
		\frac{\lambda}{4} w(G) &\leq \int_G \Re (\widetilde{E}^{\mathbf{Q}}f) dw    \\
		&= \Re \int_{\R^{d+n}} \chi_G \widehat{fd\tilde{\mu}_{\mathbf{Q}}} dw     \\
		& =\Re \int_{\R^{d+n}} \widehat{\chi_G dw}  fd\tilde{\mu}_{\mathbf{Q}} \\ 
		& \leq \|\widehat{\chi_G dw}\|_{L^2(d\tilde{\mu}_{\mathbf{Q}})} \|f\|_{L^2(d\tilde{\mu}_{\mathbf{Q}})}, 
	\end{align*}
	where $f$ is equivalently regarded as a function on the surface $S_{\mathbf{Q}}$, and $d\tilde{\mu}_{\mathbf{Q}}:=e^{-|\xi|^2/2}d\mu_{\mathbf{Q}}$. On the other hand, we use Parseval’s relation again to get
	$$   \|\widehat{\chi_G dw}\|_{L^2(d\tilde{\mu}_{\mathbf{Q}})}^2= \int_{\R^{d+n}} \widehat{\chi_G dw}   \overline{\widehat{\chi_G dw}} d\tilde{\mu}_{\mathbf{Q}} = \int_{\R^{d+n}} \left( (\chi_G dw)\ast  \widehat{d\tilde{\mu}_{\mathbf{Q}}}  \right)  \chi_G dw.  $$
	Combining the above two estimates, one concludes
	\begin{equation}\label{s2ef4}
		\lambda^2 w(G)^2 \lesssim \int_{\R^{d+n}} \left( (\chi_G dw)\ast  \widehat{d\tilde{\mu}_{\mathbf{Q}}}  \right)  \chi_G dw \cdot \|f\|_{L^2([0,1]^d)}^2.
	\end{equation}


	To estimate the integral in (\ref{s2ef4}) above, we use annulus decomposition. Let $\varphi_0$ be a smooth bump function in $\mathbb{R}^{d+n}$ satisfying $\varphi_0=1$ on $B(0,1)$, and $\varphi_0=0$ outside $B(0,2)$. Also, for $l\in \mathbb{N}$, we define $\varphi_l(x)=\varphi_0(x/2^l)-\varphi_0(x/2^{l-1})$. By choosing $\varphi_0$ suitably, we can have
	$$    \sum_{l=0}^{\infty}  \varphi_l(x)\equiv 1,\quad \quad x\in \mathbb{R}^{d+n}.  $$
	Thus we obtain
	\begin{align*}
		\left| (\chi_G dw)\ast  \widehat{d\tilde{\mu}_{\mathbf{Q}}}(x) \right| &\leq \sum_{l=0}^{\infty}  \left| (\chi_G dw)\ast  (\varphi_l\widehat{d\tilde{\mu}_{\mathbf{Q}}})(x) \right| \\
		& \leq \sum_{l=0}^{\infty} \int_{\R^{d+n}} | \varphi_l(x-y)\widehat{d\tilde{\mu}_{\mathbf{Q}}}(x-y) | \chi_G(y) dw(y) \\
		& \lesssim \sum_{l=0}^{\infty}  2^{-\frac{l \cdot\mathfrak{d}_{d,1}(\mathbf{Q}) }{2}} \int_{\R^{d+n}} \chi_{B(x,2^{l+1})}(y)\chi_G(y)dw(y) \\
		& \leq \sum_{l=0}^{\infty}  2^{-\frac{l \cdot\mathfrak{d}_{d,1}(\mathbf{Q}) }{2}} w(B(x,2^{l+1})) \\
		& \lesssim   \sum_{l=0}^{\infty}  2^{-\frac{l (\mathfrak{d}_{d,1}(\mathbf{Q})-2\alpha) }{2}} A_\alpha(H) \\
		& \lesssim  A_\alpha(H).
	\end{align*}
	Here in the third line we used Theorem~\ref{thm:uniform_decay}, in the fourth line we used the definition of $\alpha$-dimensional weight $H$, and in the last line we used the assumption $0<\alpha< \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$. Plugging this estimate into (\ref{s2ef4}), we get
	$$  w(G) \lesssim \lambda^{-2} A_{\alpha}(H) \|f\|_{L^2([0,1]^d)}^2.   $$
	And then (\ref{s2ef3}) becomes
	$$     \|\widetilde{E}^{\mathbf{Q}}f\|_{L^p(\mathbb{R}^{d+n},H)}^p \lesssim  \int_0^{\|f\|_{L^1}} \lambda^{p-3} d\lambda \cdot A_{\alpha}(H) \|f\|_{L^2([0,1]^d)}^2\lesssim A_{\alpha}(H) \|f\|_{L^2([0,1]^d)}^p,  $$
	provided $p>2$. This finishes the proof of (\ref{s2ef2}).


	Next we prove the second bound in (\ref{shayya_result2}). Our main tool is the weighted H\"older-type inequality built by Shayya: For any Lebesgue measurable function $F:~\mathbb{R}^{d+n}\rightarrow [0,\infty)$, define
	$$ M_{\alpha}F =\sup_{  \substack{  H: \\ 0<A_\alpha(H)<\infty  }}  \left(\int_{\R^{d+n}} F(x)^\alpha\cdot  \frac{H(x)}{A_\alpha(H)} dx \right)^{\frac{1}{\alpha}}.  $$
	Then for $0<\beta \leq \alpha\leq d+n$, there is
	\begin{equation}\label{s2ef5}
		M_\alpha F \leq M_\beta F.
	\end{equation}
	Based on (\ref{s2ef5}), Shayya showed an interesting monotone property on $P(\alpha,\mathbf{Q})$: For $0<\beta \leq \alpha\leq d+n$, there is 
	\begin{equation}\label{s2ef6}
		\frac{P(\alpha,\mathbf{Q})}{\alpha}\leq \frac{P(\beta,\mathbf{Q})}{\beta}.
	\end{equation}
	Now, if we take $0<\beta <\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2} \leq \alpha \leq d+n$, then the first bound in (\ref{shayya_result2}) and (\ref{s2ef6}) imply
	$$     \frac{P(\alpha,\mathbf{Q})}{\alpha}\leq \frac{P(\beta,\mathbf{Q})}{\beta}\leq \frac{2}{\beta}.  $$
	Letting $\beta \rightarrow \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$, we get
	\begin{equation}\label{s2ef7}
		P(\alpha,\mathbf{Q}) \leq \frac{4\alpha}{\mathfrak{d}_{d,1}(\mathbf{Q})}.
	\end{equation}
	We have finished the proof of (\ref{shayya_result2}).




	After considering the global estimate (\ref{s2e1}), we go back to  the local estimate (\ref{s1e1}). Firstly, using the first bound in (\ref{shayya_result2}), we can get
    \begin{equation}
		s(\alpha,\mathbf{Q})=0 ,\quad \quad  0<\alpha< \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2},
	\end{equation}
	which is just the first bound in (\ref{t1e1}). Then we consider the case $\alpha\geq \mathfrak{d}_{d,1}(\mathbf{Q})/2$. Set $q=4\alpha/\mathfrak{d}_{d,1}(\mathbf{Q})$. Combining (\ref{s2ef7}) and H\"older's inequality, we obtain
	\begin{align*}
		\|E^{\mathbf{Q}}f\|_{L^2(B_R,H)}&  \leq \|E^{\mathbf{Q}}f\|_{L^{q}(B_R,H)}  \left(\int_{B_R} H(x)dx\right)^{\frac{1}{2}-\frac{1}{q}}  \\
		& \lesssim R^\epsilon A_\alpha(H)^{\frac{1}{q}} \|f\|_{L^2([0,1]^d)} \cdot (A_\alpha(H) R^\alpha)^{\frac{1}{2}-\frac{1}{q}} \\
		& = A_\alpha(H)^{\frac{1}{2}}  R^{\frac{\alpha}{2}-\frac{\alpha}{q}+\epsilon}  \|f\|_{L^2([0,1]^d)} \\
		&=  A_\alpha(H)^{\frac{1}{2}}  R^{\frac{2\alpha-\mathfrak{d}_{d,1}(\mathbf{Q})}{4}+\epsilon}  \|f\|_{L^2([0,1]^d)} .
	\end{align*}
	This means 
	\begin{equation}
		s(\alpha,\mathbf{Q})\leq \frac{2\alpha-\mathfrak{d}_{d,1}(\mathbf{Q})}{4} ,\quad \quad  \alpha\geq  \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2},
	\end{equation}
	which is just the second bound in (\ref{t1e1}).


	\begin{remark}
		For the parabolic case, in addition to the approaches presented above, Shayya \cite{shayya21} also applied other methods, which incorporate Du-Zhang's weighted restriction estimates to further improve the upper bound of $P(\alpha,\mathbf{Q})$ in {\rm(\ref{shayya_result})} for $\alpha>\frac{d+1}{2}$. It is worth mentioning that by combining Theorem {\rm \ref{th1}}, Theorem~{\rm \ref{thm:uniform_decay}} in the last section, and the proof strategy of Shayya, we can also obtain improved bounds for quadratic manifolds in {\rm(\ref{shayya_result2})} when $\alpha>\frac{\mathfrak{d}_{d,1}(\mathbf{Q})+1}{2}$, whose details are left to interested readers. 


	\end{remark}


	\subsection{The Du-Zhang method}\label{du_zhang_method}\phantom{x}

	This subsection is devoted to prove (\ref{t1e2}). As we have mentioned in the introduction, we will adopt the strategy of Du and Zhang \cite{dz19}. Compared with the Du-Zhang method in \cite{dz19}, apart from differences in the mode of the broad-narrow analysis, we also need to adopt the induction at the new scale for matching associated $\ell^2L^p$ decoupling for general quadratic forms in the narrow part.        



	Via a similar argument as in \cite{dz19}, the estimate in (\ref{t1e2}) can be derived by the following inductive proposition. We say that a collection is essentially a dyadic constant if all the quantities in this collection are in a common dyadic interval of the form $[2^j,2^{j+1}]$, where $j$ is an integer.


	\begin{proposition}\label{main_prop:du_zhang}
		Let $d,n \geq 1$, and $\mathbf{Q}=(Q_1,...,Q_n)$ be an $n$-tuple of real quadratic forms in $d$ variables. Let $p\geq 2$, and $2\leq k\leq d+1$ be an integer. For any $\epsilon >0$, there exist constants $C_\epsilon$ and $\delta=\delta(\epsilon)$ such that the following fact holds for any $R \geq 1$ and every $f$ with ${\rm supp}f \subset [0,1]^d$. Let  $Y=\cup_{i=1}^M B_i$ be a union of lattice $K^2$-cubes in $B^{d+n}(0,R)$ with $K=R^\delta$. Suppose that 
		\begin{equation}\label{assump:dyadic_constant}
			\|E^{\mathbf{Q}} f\|_{L^p(B_i)}  \text{~is~essentially~a ~dyadic~constant~in~}   i=1,2,...,M. 
		\end{equation}
		Let $1\leq \alpha\leq d+n$ and 
		$$  \gamma:=\max_{\substack{  B(x',r)\subset B(0,R) \\ x'\in \mathbb{R}^{d+n},~r\geq K^2 }} \frac{\#\{ B_i:B_i \subset B(x',r)\}}{r^\alpha}.  $$
		Then we have
		\begin{equation}\label{eq:main_estimate}
			\|E^{\mathbf{Q}}f\|_{L^p(Y)}\leq C_\epsilon M^{\frac{1}{p}-\frac{1}{2}} \gamma^{\frac{1}{2}-\frac{1}{p}}R^{w(p,k,\alpha,\mathbf{Q})+\epsilon}\|f\|_{L^2([0,1]^d)},
		\end{equation}
		where $w(p,k,\alpha,\mathbf{Q})$ is given by 
		\begin{equation}\label{eq:key_exponent}
			w(p,k,\alpha,\mathbf{Q})= \max\left\{   \max_{1\leq m\leq d+n} \frac{m-X(\mathbf{Q},k,m)}{2m}\cdot\alpha ,~\frac{\Gamma_p^{k-2}(\mathbf{Q})}{2}+\frac{d+n-\alpha}{2p}+\frac{\alpha+n-d}{4} \right\}.
		\end{equation}   
	\end{proposition}


	\begin{proof} This proposition will be demonstrated by induction on scales. If $R\lesssim 1$, we can take a sufficiently large $C_\epsilon$, and then (\ref{eq:main_estimate}) holds trivially. From now on, we assume that Proposition \ref{main_prop:du_zhang} is true for $R$ replaced by $R/2$.

		Decompose $[0,1]^d$ into disjoint $K^{-1}$-cubes $\tau$, and write $f=\sum_{\tau} f_\tau$, where $f_\tau=f \chi_\tau$. For every $K^2$-cube $B$ in $Y$, we define its significant set as
		$$    \mathcal{S}_0(B) :=\Big\{ \tau: \| E^{\mathbf{Q}} f _\tau\|_{L^p(B)} \geq \frac{1}{\# \{\tau\} } \max_{\tau'}\|  E^{\mathbf{Q}} f_{\tau'}  \|_{L^p(B)} \Big\}.  $$
		We run the following algorithm. Let $\iota\geq 0$. If $\mathcal{S}_\iota(B)=\varnothing$ or $\mathcal{S}_\iota(B)$ is $\epsilon$-uniform with the controlling sequence $\{X(\mathbf{Q},k,m)\}_{m=1}^{d+n}$, then we set $\mathcal{S}_\iota(B):=\mathcal{T}(B)$ and terminate. Otherwise, there is an $m$-dimensional 
		subspace $V$ such that there are more than $\epsilon|\mathcal{S}_\iota|$ many $\tau \in \mathcal{S}_\iota$ intersecting 
		$$   Z_V:=\left\{   \xi \in \mathbb{R}^d:\dim (\pi_{V_\xi}(V)) <X(\mathbf{Q},k,m)   \right\}.   $$
		By the definition of $X(\mathbf{Q},k,m)$, we have $\dim Z_V\leq k-2$. Applying Lemma \ref{dec low var}, one gets
		$$   N_{1/K}(Z_V) \cap [0,1]^d \subset  \bigcup_{j=1}^L \bigcup_{W \in \mathcal{W}_{\iota,j}(B)} W,  $$
		where each $\mathcal{W}_{\iota,j}(B)$ denotes the collection of pairwise disjoint $1/K_j$-cubes. Then we run the algorithm to
		$$   \mathcal{S}_{\iota+1}(B)  := \mathcal{S}_\iota(B) \backslash \bigcup_{j=1}^L \bigcup_{W \in \mathcal{W}_{\iota,j}(B)} \mathcal{P}(W,K^{-1}), $$
		where $\mathcal{P}(W,K^{-1})$ denotes the partition of $W$ into disjoint $K^{-1}$-cubes $\tau$. Note this algorithm will terminate after at most $O(\log K)$ steps, which implies $\iota \lesssim \log K$. Finally, this algorithm produces the following two sets:
		$$  \mathcal{T}(B)\quad \text{~~~~~and~~~~}\quad   \bigcup_{\iota} \bigcup_{j=1}^L \mathcal{W}_{\iota,j}(B)     ,   $$
		and each $\tau \in \mathcal{S}_0(B)$ must be covered by exactly one set.
		Then by the triangle inequality, one has
		\begin{equation}\label{met1 eq2}
			\|E^{\mathbf{Q}}f\|_{L^p(B)} \leq \Big\|\sum_{\tau \in \mathcal{T}(B)} E^{\mathbf{Q}}f_\tau\Big\|_{L^p(B)}+\Big\|  \sum_{\tau \in \cup_\iota \cup_j \mathcal{W}_{\iota,j}(B) } E^{\mathbf{Q}}f_\tau \Big\|_{L^p(B)} +\Big\|   \sum_{\tau \notin\mathcal{S}_0(B)  }  E^{\mathbf{Q}}f_\tau\Big\|_{L^p(B)}.
		\end{equation}
		We say $B$ is broad if the first term dominates, otherwise we say $B$ is narrow. Denote the union of broad cubes $B $ in $ Y$ by $Y_{\text{broad}}$ and the union of narrow cubes $B $ in $ Y$ by $Y_{\text{narrow}}$. We say that we are in the broad case if $Y_{\text{broad}}$ contains $\geq M/2$ many $K^2$-cubes, and the narrow case otherwise. 

		\vskip0.5cm

		\noindent \textbf{Broad case.} For each broad cube $B$, we have
		\begin{equation*}
			\|E^{\mathbf{Q}} f \|_{L^p(B)} \lesssim \Big\|\sum_{\tau \in \mathcal{T}(B)} E^{\mathbf{Q}}f_\tau\Big\|_{L^p(B)} \lesssim K^d \max_{\tau \in \mathcal{T}(B)} \|E^{\mathbf{Q}}f_\tau\|_{L^p(B)} .
		\end{equation*}
		Set $\mathcal{T}(B)=\{ \tau_1,...,\tau_J\}$. It follows from the definition of $\mathcal{S}_0(B)$ that 
		$$    K^d \max_{\tau \in \mathcal{T}(B)} \|E^{\mathbf{Q}}f_\tau\|_{L^p(B)} \lesssim K^{2d} \prod_{j=1}^J \|E^{\mathbf{Q}}f_{\tau_j}\|^{\frac{1}{J}}_{L^p(B)} .$$
		We want to use reverse H\"older to bound the above geometric average of $L^p$-integrals by an $L^p$-integral of the geometric average. Although $E^{\mathbf{Q}}f_{\tau_j}$ does not satisfy the locally constant property on each $K^2$-cube $B$, this process still works up to a $K^{O(1)}$ loss via an additional translation argument. Readers may consult Section 3 in \cite{dz19} for details. Thus, we conclude
		\begin{align*}
			\|E^{\mathbf{Q}} f \|_{L^p(B)}  \lesssim K^{2d} \prod_{j=1}^J \|E^{\mathbf{Q}}f_{\tau_j}\|^{\frac{1}{J}}_{L^p(B)} \lesssim K^{O(1)} \Bigg\|     \prod_{j=1}^{J} |E^{\mathbf{Q}}f_{\tau_j,v_j}|^{\frac{1}{J}} \Bigg\|_{L^p(B(x_B,2))}, 
		\end{align*}
		where $x_B$ is the center of $B$, and
		$$  v_j \in B(0,K^2) \cap \mathbb{Z}^{d+n},\quad f_{\tau_j,v_j}(\xi):= f_{\tau_j}(\xi)  e^{ iv_j\cdot(\xi, \mathbf{Q}(\xi))}. $$
		We point out that the parameters $\tau_j,v_j$ and $J$ may depend on the choices of $B$. However, such dependence is in fact harmless. Since there are only $K^{O(1)}$ choices for $\tau_j,v_j$ and $J$, by pigeonholing, there exist $\tilde{\tau}_j,\tilde{v}_j,\tilde{J}$ such that the above inequality holds for at least $\geq K^{-C}M$ many broad $K^2$-cubes $B$. In the rest of the proof of the broad case, we fix $\tilde{\tau}_j,\tilde{v}_j$ and $\tilde{J}$.  Write $f_j=f_{\tilde{\tau}_j,\tilde{v}_j}$ for brevity, and denote by $\mathcal{B}$ the collection of the broad $K^2$-cubes $B$ associated with $\tilde{\tau}_j,\tilde{v}_j$ and $\tilde{J}$. Relying on these pigeonholing and (\ref{assump:dyadic_constant}), we can sum over all $B\in \mathcal{B}$ and get
		\begin{equation}
			\|E^{\mathbf{Q}} f \|_{L^p(Y)}  \lesssim K^{O(1)} \Bigg\| \prod_{j=1}^{\tilde{J}} |E^{\mathbf{Q}} f_j |^{\frac{1}{\tilde{J}}}  \Bigg\|_{L^p(\cup_{B\in \mathcal{B} } B(x_B,2))}.   
		\end{equation}

		To exploit the transverse condition, i.e., $\mathcal{T}(B)$ is $\epsilon$-uniform with the controlling sequence $\{X(\mathbf{Q},k,m)\}_{m=1}^{d+n}$, we apply the following $k$-linear restriction estimates for general quadratic forms.


		\begin{theorem}[\cite{ggo23}, Theorem 2.1]\label{thm:k-linear} 
			Let $\theta,J,K>0$, and $\{\tau_j \}_{j=1}^J$ be a collection of $K^{-1}$cubes in $[0,1]^d$ which is $\theta$-uniform with the controlling sequence $\{X_m\}_{m=1}^{d+n}$. Then for each $2 \leq q\leq 2J$ and $0<\epsilon\ll 1$, we have
			\begin{equation}\label{eq:k-linear}
				\Bigg\|   \prod_{j=1}^{J}   |E^{\mathbf{Q}}f_{\tau_j}|^{\frac{1}{J}} \Bigg\|_{L^q(B_R)} \leq C_{\epsilon,\theta,q,K} R^{\epsilon+\frac{(d+n)\theta}{2}}\max_{1\leq m\leq d+n}R^{\frac{m}{q}-\frac{X_m}{2}} \prod_{j=1}^{J}\|f_{\tau_j}\|^{\frac{1}{J}}_{L^2([0,1]^d)}.
			\end{equation}
		\end{theorem}

		Set $\theta=\epsilon$, $J=\tilde{J}$, and $X_m=X(\mathbf{Q},k,m)$ in above theorem. Via some basic calculations, we can take
		$$     q= \max_{1\leq m\leq d+n} \frac{2m}{X(\mathbf{Q},k,m)}  ,$$
		which is the endpoint of  (\ref{eq:k-linear}) in Theorem~\ref{thm:k-linear}. From the definition of $X(\mathbf{Q},k,m)$, we have
		\begin{equation}\label{xqkmrela}
			0\leq X(\mathbf{Q},k,m)\leq m,
		\end{equation}
		which means $2\leq q \leq \infty$. Although the situation $q>2\tilde{J}$ may happen, it is harmless. Since the $\theta$-uniform condition says that $\{\tau_j\}_{j=1}^{\tilde{J}}$ cannot be clustered near a low dimensional set (\ref{s3t1e1}), this condition is effective only when $\tilde{J} \gg 1$. In the current environment, $\tilde{J}\sim K^{c}$ for some constant $c$ in general. By (\ref{xqkmrela}), we get the case $q>2\tilde{J}$ will happen only when $X(\mathbf{Q},k,m)=0$ for some $1\leq m\leq d+n$, and then $q=\infty$. In this case, the estimate (\ref{eq:k-linear}) holds trivially.

		There are two cases according to whether $p\geq q$ or not. We first assume that $p\geq q$. Then we sort $B \in \mathcal{B}$ by the value of $ \|\prod_{j=1}^{\tilde{J}} |E^{\mathbf{Q}} f _j|^{\frac{1}{\tilde{J}}}\|_{L^\infty(B(x_B,2))}$: For each dyadic number $A$, define
		$$ \mathbb{Y}_A:=\Bigg\{B \in \mathcal{B}: \Bigg\|\prod_{j=1}^{\tilde{J}} |E^{\mathbf{Q}} f _j|^{\frac{1}{\tilde{J}}}\Bigg\|_{L^\infty(B(x_B,2))} \sim A\Bigg\} .  $$
		Let $Y_{A}$ be the union of the $K^2$-cubes $B$ in $\mathbb{Y}_{A}$. Without loss of generality, assume that $\|f\|_{L^2([0,1]^d)}=1$. And we can further assume that $R^{-C} \leq A \leq 1$ for some constant $C$, because those $\mathbb{Y}_A$'s with $A \leq R^{-C}$ only make a negligible contribution for sufficiently large $C$. So there are only $O(\log R) \leq O(K)$ choices on $A$. By dyadic pigeonholing, there exists a constant $\tilde{A}$ such that 
		\begin{equation*}
			\# \{  B: B\subset Y_{\tilde{A}}  \} \gtrsim (\log R)^{-1} \#  \mathcal{B}. 
		\end{equation*}
		Now we fix $\tilde{A}$, and denote the collection of $K^2$-cubes $B$ in $Y_{\tilde{A}}$ by $\mathcal{B}'$. This uniformization procedure allows us to use reverse H\"older to pass from $L^p$ to $L^q$. Thus, we get  
		\begin{align*}
			\|E^{\mathbf{Q}} f \|_{L^p(Y)}  &\lesssim K^{O(1)} \Bigg\| \prod_{j=1}^{\tilde{J}} |E^{\mathbf{Q}} f_j |^{\frac{1}{\tilde{J}}}  \Bigg\|_{L^p(\cup_{B\in \mathcal{B} } B(x_B,2))} \\ 
			& \leq K^{O(1)} \Bigg\| \prod_{j=1}^{\tilde{J}} |E^{\mathbf{Q}} f_j |^{\frac{1}{\tilde{J}}}  \Bigg\|_{L^p(\cup_{B\in \mathcal{B}'} B(x_B,2))}  \\
			& \sim K^{O(1)} M^{\frac{1}{p}-\frac{1}{q}} \Bigg\| \prod_{j=1}^{\tilde{J}} |E^{\mathbf{Q}}f _j|^{\frac{1}{\tilde{J}}}  \Bigg\|_{L^{q}(\cup_{B\in \mathcal{B}'} B(x_B,2))}     \\
			& \leq   K^{O(1)} M^{\frac{1}{p}-\frac{1}{q}}  \Bigg\| \prod_{j=1}^{\tilde{J}} |E^{\mathbf{Q}} f _j|^{\frac{1}{\tilde{J}}}  \Bigg\|_{L^{q}(B_R)}   \\
			& \lesssim    K^{O(1)} M^{\frac{1}{p}-\frac{1}{q}}  R^\epsilon\|f\|_{L^2([0,1]^d)},   
		\end{align*}
		where we used (\ref{assump:dyadic_constant}) in the second line, and Theorem \ref{thm:k-linear} in the last line. On the other hand, by testing two extreme values $r=K^2$ and $r=R$ in the definition of $\gamma$, one can easily see that
		$$   \gamma \geq K^{-2\alpha},\quad   M\leq \gamma R^\alpha.    $$
		Combining these two estimates, we then have
		$$   M^{\frac{1}{p}-\frac{1}{q}}  \leq  M^{\frac{1}{p}-\frac{1}{2}}  \gamma^{\frac{1}{2}-\frac{1}{q}} R^{(\frac{1}{2}-\frac{1}{q})\alpha} \leq K^{O(1)} M^{\frac{1}{p}-\frac{1}{2}}  \gamma^{\frac{1}{2}-\frac{1}{p}} R^{(\frac{1}{2}-\frac{1}{q})\alpha},  $$
		where we also used $q\geq 2$ and $p\geq q$. It follows that
		$$     \|E^{\mathbf{Q}} f \|_{L^p(Y)}   \lesssim    K^{O(1)}M^{\frac{1}{p}-\frac{1}{2}}  \gamma^{\frac{1}{2}-\frac{1}{p}} R^{(\frac{1}{2}-\frac{1}{q})\alpha}\|f\|_{L^2([0,1]^d)}. $$
		Since  
		$$    \left(\frac{1}{2}-\frac{1}{q}\right)\alpha=\max_{1\leq m\leq d+n} \frac{m-X(\mathbf{Q},k,m)}{2m}\cdot\alpha,  $$
		we have obtained the first quantity of $w(p,k,\alpha,\mathbf{Q})$ in (\ref{eq:key_exponent}).

		It remains to consider case $2\leq p\leq q$. Note that when $p=2$, our aim (\ref{eq:main_estimate}) becomes
		\begin{equation*}
			\|E^{\mathbf{Q}}f\|_{L^2(Y)}\leq C_\epsilon R^{w(2,k,\alpha,\mathbf{Q})+\epsilon}\|f\|_{L^2([0,1]^d)},
		\end{equation*}
		where
		\begin{equation*}
			w(2,k,\alpha,\mathbf{Q})= \max\left\{   \max_{1\leq m\leq d+n} \frac{m-X(\mathbf{Q},k,m)}{2m}\cdot\alpha ,~\frac{n}{2} \right\}\geq \frac{n}{2}.
		\end{equation*}   
		So it holds trivially by the classical Agmon-H\"ormander inequality (\ref{AH ineq}). Then the estimates (\ref{eq:main_estimate}) for $2<p<q$ can be derived via interpolating between the estimates for $p=2$ and $p=q$. 



		\vskip0.5cm




		\noindent \textbf{Narrow case.}  For each narrow cube $B$, we have
		\begin{equation*}
			\|E^{\mathbf{Q}}f\|_{L^p(B)} \lesssim \Big\|  \sum_{\tau \in \cup_\iota \cup_j \mathcal{W}_{\iota,j}(B) } E^{\mathbf{Q}}f_\tau \Big\|_{L^p(B)} +\Big\|   \sum_{\tau \notin\mathcal{S}_0(B)  }  E^{\mathbf{Q}}f_\tau\Big\|_{L^p(B)}.
		\end{equation*}
		If the second term dominates, by the definition of $\mathcal{S}_0(B)$, one gets
		$$\Big\|   \sum_{\tau \notin\mathcal{S}_0(B)  }  E^{\mathbf{Q}}f_\tau\Big\|_{L^p(B)}  \leq \sum_{\tau \notin\mathcal{S}_0(B)  }   \|   E^{\mathbf{Q}}f_\tau\|_{L^p(B)} \leq \max_{\tau'}\|  E^{\mathbf{Q}} f_{\tau'}  \|_{L^p(B)} ,  $$
		which can be reduced to the first term. From now on, we will only consider the first term. By the triangle inequality, one gets
		\begin{equation}\label{add}
			\|E^{\mathbf{Q}}f\|_{L^p(B)} \lesssim \Big\|  \sum_{\tau \in \cup_\iota \cup_j W_{\iota,j}(B) } E^{\mathbf{Q}}f_\tau \Big\|_{L^p(B)} \leq  \sum_{\iota} \sum_{j=1}^{L}\Big\|  \sum_{\tau \in \mathcal{W}_{\iota,j}(B) } E^{\mathbf{Q}}f_\tau \Big\|_{L^p(B)}  .
		\end{equation}
		Recall that $\iota \lesssim \log K$ and $L=L(d)$. Without loss of generality, we assume that the contribution from $\mathcal{W}_{1,1}(B) $ dominates in (\ref{add}) for a $\gtrsim (\log R)^{-1}$ fraction of all $B 
		\subset Y_{\text{narrow}}$. Denote the union of such $B$'s by $Y_1$. Thus for each $B \subset  Y_1$, one has
		\begin{equation}\label{s3equ11}
			\|E^{\mathbf{Q}}f\|_{L^p(B)} \lesssim  \log K \Big\|  \sum_{\tau \in \mathcal{W}_{1,1}(B) } E^{\mathbf{Q}}f_\tau \Big\|_{L^p(B)} .
		\end{equation}

		We plan to study (\ref{add}) through the same steps as in Section 3 in \cite{dz19}: do some dyadic pigeonholing, apply lower-dimensional $\ell^2L^p$ decoupling, and use rescaling and induction on scale $R/K^2$. However, since $\mathcal{W}_{1,1}(B) $ is a collection of $1/K_1$-cubes in our environment, we will use induction on scale $R/K_1^2$ rather than $R/K^2$. More precisely, we rewrite (\ref{s3equ11}) as
		\begin{equation}\label{s3equ1}
			\|E^{\mathbf{Q}}f\|_{L^p(B)} \lesssim   \log K \Big\|  \sum_{W \in \mathcal{W}_{1,1}(B) } E^{\mathbf{Q}}f_W \Big\|_{L^p(B)}  ,
		\end{equation}
		where  each $W$ is a $1/K_1$-cube with center $c(W)$. Break $B^d(0,R)$ in the physical space into $R/K_1$-cubes $D$ with center $c(D)$, and write 
		$$\sum_{W \in \mathcal{W}_{1,1}(B) } f_W=\sum_{W,D} f_{W,D},$$ 
		where each $f_{W,D}$ is Fourier supported on $W \in \mathcal{W}_{1,1}(B) $, and essentially supported on $D$. Then  
		$$ \sum_{W \in \mathcal{W}_{1,1}(B) } E^{\mathbf{Q}}f_W=\sum_{W,D} E^{\mathbf{Q}} f_{W,D}.$$ 
		Through the stationary phase method \cite{bll17}, we can see that each $E^{\mathbf{Q}} f_{W,D}$ restricted in $B_R$ is essentially supported on 
		$$\Box_{W,D}:=\Big\{    (x,y) \in B_R  : \Big|x+\sum_{j=1}^n y_j \nabla Q_j(c(W))-c(D)    \Big|\leq R/K_1 \Big\}.$$
		Since a given $B$ lies in exactly one box $\Box_{W,D}$ for each $W$, it follows from (\ref{dec low var e2}) and $K_1\leq K$ that
		\begin{equation}\label{eeeeeeee}
			\Big\|  \sum_{W \in \mathcal{W}_{1,1}(B) } E^{\mathbf{Q}}f_W \Big\|_{L^p(B)} \lesssim  K_1^{\Gamma_p^{k-2}(\mathbf{Q})+\epsilon^2} \Big(\sum_{ \Box}  \left\| E^{\mathbf{Q}}f_\Box \right\|^2_{L^p(w_B)}\Big)^{\frac{1}{2}} , 
		\end{equation}	
		where $w_B$ is given by (\ref{notation_wb}), and $\Box:=\Box_{W,D}$ for brevity.	






		Set $\tilde{R}=R/K_1^2$ and $\tilde{K}=\tilde{R}^\delta$. Tile $\Box$ by the
		rectangle boxes $S$ with $d$ short sides of length $K_1\tilde{K}^2$ pointing in the same directions as the short sides of $\Box$, and $n$ long sides of length 
		$K_1^2\tilde{K}^2$ pointing in complementary directions. In what follows, we will perform dyadic pigeonholing   to $S$ and $\Box$: 

		\noindent (1) For each $\Box$, sort $S \subset \Box$ that intersect $Y_{1}$ according to the value of $\|E^{\mathbf{Q}} f_{\Box}\|_{L^p(S)}$ and the number of $K^2$-cubes in $Y_{1}$ contained in it: For dyadic numbers $\eta,\beta_1$, define
		$$    \mathbb{S}_{\Box,\eta,\beta_1}:=\Big\{ S\subset \Box:S~\text{contains}\sim\eta~\text{many}~K^2\text{-cubes~in~}Y_{1},~ \|E^{\mathbf{Q}} f_{\Box}\|_{L^p(S)}\sim\beta_1  \Big\}.    $$
		Let $Y_{\Box,\eta,\beta_1}$ be the union of the rectangular boxes $S$ in $\mathbb{S}_{\Box,\eta,\beta_1}$.  	

		\noindent (2) For fixed $\eta$ and $\beta_1$, sort $\Box$ according to the value of $\|f_\Box\|_{L^2([0,1]^d)}$ and the number $\#\mathbb{S}_{\Box,\eta,\beta_1}$: For dyadic numbers $\beta_2,M_1$, define
		$$   \mathbb{B}_{\eta,\beta_1,\beta_2,M_1}:=\Big\{ \Box: \|f_\Box\|_{L^2([0,1]^d)}\sim \beta_2,~ \# \mathbb{S}_{\Box,\eta,\beta_1}\sim M_1\Big\}.  $$


		For each $B\subset Y_{1}$, we have
		$$\sum_{W \in \mathcal{W}_{1,1}(B) } E^{\mathbf{Q}}f_W =\sum_{\eta,\beta_1,\beta_2,M_1}\left( \sum_{\substack{\Box\in \mathbb{B}_{\eta,\beta_1,\beta_2,M_1}  \\ B\subset Y_{\Box,\eta,\beta_1}}} E^{\mathbf{Q}} f_\Box  \right). $$
		Under the hypothesis $\|f\|_{L^2([0,1]^d)}=1$, we can further assume that
		\begin{align*}
			1\leq \eta \leq K^{O(1)}, \quad R^{-C} \leq \beta_1 \leq K^{O(1)}, \quad R^{-C} \leq \beta_2 \leq 1,    \quad 1 \leq M_1 \leq R^{O(1)}
		\end{align*}
		for some constant $C$. Thus there are only $O(\log R)$ choices for each dyadic number. By dyadic pigeonholing, these exist $\eta,\beta_1,\beta_2,M_1$ depending on $B$ such that (\ref{s3equ1}) becomes
		\begin{equation}\label{absd}
			\|E^{\mathbf{Q}}f\|_{L^p(B)} \lesssim  (\log R)^5     \Bigg\| \sum_{\substack{\Box\in \mathbb{B}_{\eta,\beta_1,\beta_2,M_1}  \\ B\subset Y_{\Box,\eta,\beta_1}}} E^{\mathbf{Q}}f_\Box  \cdot   \chi_{Y_{\Box,\eta,\beta_1}}  \Bigg\|_{L^p(B)}  .
		\end{equation}

		Finally, we sort $B \subset  Y_{1}$. Since there are only $O(\log R)$ choices on $\eta,\beta_1,\beta_2,M_1$, by pigeonholing, we can find $\tilde{\eta},\tilde{\beta}_1,\tilde{\beta}_2,\tilde{M}_1$ such that (\ref{absd}) holds for a $\gtrsim (\log R)^{-4}$ fraction of all $B\subset Y_{1}$. Denote the union of such $B$ by $ Y'$. From now on, we abbreviate $Y_{\Box,\tilde{\eta},\tilde{\beta}_1}$ and $\mathbb{B}_{\tilde{\eta},\tilde{\beta}_1,\tilde{\beta}_2,\tilde{M}_1}$ to $Y_\Box$ and $\mathbb{B}$, respectively. Next we further sort $B \subset  Y'$ by the number $\# \{ \Box \in \mathbb{B}: B \subset Y_\Box  \}$: For each dyadic number $\mu$, define
		$$  \mathbb{Y}_\mu :=\Big\{  B \subset Y':  \#  \{ \Box \in \mathbb{B}: B\subset Y_\Box \}\sim\mu \Big\}.  $$
		Let $Y_{\mu}$ be the union of $B$'s in $\mathbb{Y}_\mu$. Using dyadic pigeonholing again, we can choose $\tilde{\mu}$ such that
		\begin{equation}\label{flr eq7}
			\#\{ B : B \subset Y_{\tilde{\mu}} \} \gtrsim (\log R)^{-1} \#\{B : B \subset Y' \}. 
		\end{equation}
		From now on, we fix $\tilde{\mu}$, and denote $Y_{\tilde{\mu}}$ by $Y''$. 

		For each $B\subset Y''$, it follows from (\ref{eeeeeeee}) and (\ref{absd}) that
		\begin{align*}
			\| E^{\mathbf{Q}} f \|_{L^p(B)} \lesssim&  (\log R)^5 \Big\|  \sum_{\Box \in\mathbb{B} : B \subset Y_\Box}E^{\mathbf{Q}} f_\Box \cdot \chi_{Y_{\Box}}  \Big\|_{L^p(B)}  \\
			\lesssim  & (\log R)^5  K_1^{\Gamma_p^{k-2}(\mathbf{Q})+\epsilon^2} \Big( \sum_{
				\Box \in \mathbb{B}: B \subset Y_\Box} \|E^{\mathbf{Q}} f_\Box \|^2_{L^p(w_B)}  \Big)^{\frac{1}{2}}  \\
			\lesssim   &  (\log R)^5 K_1^{\Gamma_p^{k-2}(\mathbf{Q})+\epsilon^2}\tilde{\mu}^{\frac{1}{2}-\frac{1}{p}} \Big( \sum_{\Box \in \mathbb{B}: B \subset Y_\Box} \|E^{\mathbf{Q}} f_\Box \|^p_{L^p(w_B)}  \Big)^{\frac{1}{p}}.    
		\end{align*}
		Summing over all $B\subset Y''$ and combining (\ref{assump:dyadic_constant}), there is
		\begin{align}
			\|E^{\mathbf{Q}}f \|_{L^p(Y)} &\lesssim (\log R)^6 \|E^{\mathbf{Q}} f \|_{L^p(Y'')}     \nonumber \\
			& \lesssim  (\log R)^{11} K_1^{\Gamma_p^{k-2}(\mathbf{Q})+\epsilon^2} \tilde{\mu}^{\frac{1}{2}-\frac{1}{p}} \Big(\sum_{\Box \in \mathbb{B}} \|E^{\mathbf{Q}} f _\Box\|^p_{L^p(Y_\Box)}\Big)^{\frac{1}{p}} .   \label{11}
		\end{align}
		For every individual term $ \|E^{\mathbf{Q}}f _\Box\|_{L^p(Y_\Box)}$, we can use the change of variables $$ \xi   \rightarrow c(\tau)+K_1^{-1}\xi,$$ 
		and then 
		$$  |E^{\mathbf{Q}} f _\Box(x)|   = K_1^{-\frac{d}{2}}|E^{\mathbf{Q}}g(\tilde{x})|    $$
		for some function $g$ with Fourier support in $[0,1]^d$ and $\|g\|_{L^2([0,1]^d)}=\|f_\Box\|_{L^2(\tau)}$, where the new coordinates $\tilde{x}=(\tilde{x}',\tilde{x}'')\in \R^{d}\times \R^n$ are related to the old coordinates $x=(x',x'')\in \R^{d}\times \R^n$ by
		\begin{align*}
			\begin{cases}
				~	\tilde{x}'=K_1^{-1}x'+K_1^{-1} c(\tau)^T\cdot \overline{Q}(x''),    \\
				~	\tilde{x}''=K_1^{-2}x'',
			\end{cases}
		\end{align*}  
		where $\overline{Q}(x'')$ is defined in (\ref{098765}). We set $\tilde{x}=Fx$. Therefore one gets
		\begin{equation}\label{12}
			\|E^{\mathbf{Q}} f _\Box\|_{L^p(Y_\Box)}=K_1^{\frac{d+2n}{p}-\frac{d}{2}} \|E^{\mathbf{Q}}g\|_{L^p(\tilde{Y})},
		\end{equation}
		where $\tilde{Y}$ denotes the image of $Y_\Box$ under the transformation in the physical space. Note that $\|E^{\mathbf{Q}}g\|_{L^p(\tilde{Y})}$ satisfies the inductive hypothesis of Proposition \ref{main_prop:du_zhang} under the new scale $\tilde{R}$ and parameter $\tilde{M}_1$: $\tilde{Y}=F(Y_\Box)$ consists of $\sim \tilde{M}_1$ many $\tilde{K}^2$-cubes $F(S)$ in an $\tilde{R}$-ball $F(\Box)$, and $\|E^{\mathbf{Q}}g\|_{L^p(F(S))}$ is essentially a dyadic constant in $S \subset Y_\Box$. If let
		$$   \tilde{\gamma}_1=\max_{\substack{  B(x',r)\subset B(0,\tilde{R}) \\ x'\in \mathbb{R}^{d+n},r\geq \tilde{K}^2 }} \frac{\#\{  B_i:B_i \subset B(x',r)\}}{r^\alpha}, $$
		then we can apply the inductive hypothesis to obtain
		\begin{equation}\label{13}
			\|E^{\mathbf{Q}}g\|_{L^p(\tilde{Y})} \lesssim  \tilde{M}_1^{\frac{1}{p}-\frac{1}{2}} \tilde{\gamma}_1^{\frac{1}{2}-\frac{1}{p}} \tilde{R}^{w(p,k,\alpha,\mathbf{Q})+\epsilon} \|g\|_{L^2([0,1]^d)}.
		\end{equation}
		Combining (\ref{11}), (\ref{12}) with (\ref{13}), one gets
		\begin{align}
			\|E^{\mathbf{Q}} f \|_{L^p(Y)} & \leq  K_1^{\Gamma_p^{k-2}(\mathbf{Q})+\frac{d+2n}{p}-\frac{d}{2}+2\epsilon^2}  \left( \frac{\tilde{\mu} \tilde{\gamma}_1}{\tilde{M}_1} \right)^{\frac{1}{2}-\frac{1}{p}}  \tilde{R}^{w(p,k,\alpha,\mathbf{Q})+\epsilon} \Big(\sum_{\Box \in \mathbb{B}}  \|f_\Box\|_{L^2([0,1]^d)}^p \Big)^{\frac{1}{p}}\nonumber   \\
			& \sim K_1^{\Gamma_p^{k-2}(\mathbf{Q})+\frac{d+2n}{p}-\frac{d}{2}+2\epsilon^2}  \left( \frac{\tilde{\mu} \tilde{\gamma}_1}{\tilde{M}_1 \#\mathbb{B}} \right)^{\frac{1}{2}-\frac{1}{p}}  \tilde{R}^{w(p,k,\alpha,\mathbf{Q})+\epsilon}   \|f\|_{L^2([0,1]^d)}. \label{14}
		\end{align}
		Here $(\log R)^{11}$ is absorbed into $K_1^{\epsilon^2}$ due to $ K^c \leq K_1 \leq K=R^\delta$.

		On the other hand, the relations between the old parameters $M,\gamma$ and new parameters $\tilde{M}_1,\tilde{\gamma}_1$ are listed as follows
		\begin{equation}\label{15}
			\frac{\tilde{\mu}}{\#\mathbb{B}}\lesssim \frac{(\log R)^6 \tilde{M}_1\tilde{\eta}}{M},\quad \quad\tilde{\gamma}_1 \tilde{\eta}\lesssim  \gamma  K_1^{\alpha+n}.  
		\end{equation}
		We omit the proof of (\ref{15}), and readers may consult Section 3 in \cite{dz19} and Section 3 in \cite{cmw24} for more details. Plugging (\ref{15}) into (\ref{14}), we get 
		$$    \| E^{\mathbf{Q}} f \|_{L^p(Y)}  \lesssim K_1^{\Gamma_p^{k-2}(\mathbf{Q})+\frac{d+n-\alpha}{p}+\frac{\alpha+n-d}{2}-2w(p,k,\alpha,\mathbf{Q}) +3\epsilon^2-2\epsilon}M^{\frac{1}{p}-\frac{1}{2}}\gamma^{\frac{1}{2}-\frac{1}{p}}R^{ 
			w(p,k,\alpha,\mathbf{Q})  +\epsilon}\|f\|_{L^2([0,1]^d)}.$$
		In order to make the induction work for the narrow case, we need the following constraint
		$$ \Gamma_p^{k-2}(\mathbf{Q})+\frac{d+n-\alpha}{p}+\frac{\alpha+n-d}{2}-2w(p,k,\alpha,\mathbf{Q})\leq 0. $$
		Via some simple calculations, it is equivalent to
		$$  w(p,k,\alpha,\mathbf{Q}) \geq  \frac{\Gamma_p^{k-2}(\mathbf{Q})}{2}+\frac{d+n-\alpha}{2p}+\frac{\alpha+n-d}{4},  $$
		which is just the second quantity of $w(p,k,\alpha,\mathbf{Q})$ in (\ref{eq:key_exponent}). 
	\end{proof}

	In the final part of the subsection, we give one remark on Proposition \ref{main_prop:du_zhang}. In Section 4 in \cite{cmw24}, the authors considered another simpler version of this proposition. To be more precise, instead of using the broad-narrow analysis, they ran the argument for the narrow part of Du-Zhang method directly, combined with $\ell^2L^p$ decoupling (not lower-dimensional version as above), to get 
	\begin{equation}
		\|E^{\mathbf{Q}}f\|_{L^p(Y)}\leq C_\epsilon M^{\frac{1}{p}-\frac{1}{2}} \gamma^{\frac{1}{2}-\frac{1}{p}}R^{w(p,\alpha,\mathbf{Q})+\epsilon}\|f\|_{L^2([0,1]^d)},
	\end{equation}
	where $w(p,\alpha,\mathbf{Q})$ is given by 
	\begin{equation}\label{s3ff1}
		w(p,\alpha,\mathbf{Q})= \frac{\Gamma_p^{d}(\mathbf{Q})}{2}+\frac{d+n-\alpha}{2p}+\frac{\alpha+n-d}{4} .
	\end{equation}   
	To some extent, this bound can been seen as the special case of $ w(p,k,\alpha,\mathbf{Q})$ when $k=d+2$. Though this bound seems rough, it is amazing that it is better than (\ref{eq:key_exponent}) for some special degenerate quadratic forms. (\ref{s3ff1}) will also be used in the next two sections.





	\section{Optimality of several estimates in Theorem \ref{th1}}\label{sec4}



	Having obtained the upper bounds of $s(\alpha,\mathbf{Q})$ in Theorem \ref{th1} in the previous two sections, we will discuss the optimality  of the first and third estimates and associated ranges in (\ref{t1e1}) of the section.



	To start with, we consider the first estimate in (\ref{t1e1}). Note that $s(\alpha,\mathbf{Q})=0$ is sharp. The associated range $0<  \alpha \leq \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$ is due to the uniform Fourier decay estimate (\ref{thm:uniform_decay_eq}) and Shayya's argument. In the following, we will take one example to show that $s(\alpha,\mathbf{Q})>0$ when $\alpha>\frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2} $, which means that the range $0<  \alpha \leq \frac{\mathfrak{d}_{d,1}(\mathbf{Q})}{2}$ satisfying $s(\alpha,\mathbf{Q})=0$ is maximal possible. This illustrates that there is no loss in the argument of applying uniform Fourier decay and Shayya's proof for general quadratic manifolds.


	There is no harm in assuming that $d'>0$. After linear changes of variables, we may assume that $Q_1$ only depends on $\xi_1,...,\xi_{d'}$. Write frequency points in $[0,1]^d$ as $\xi =(\xi',\xi''),$ with $\xi'=(\xi_1,...,\xi_{d'})$ and $\xi''=(\xi_{d'+1},...,\xi_d)$. Write spatial points in $\mathbb{R}^{d+n}$ as
	$$  x=(x',x'',x_{d+1},...,x_{d+n}),    $$
	with $x'=(x_1,...,x_{d'})$ and $x''=(x_{d'+1},...,x_{d})$. Then we can rewrite $E^{\mathbf{Q}}f$ as
	$$   E^{\mathbf{Q}}f(x)=\int_{\R^{d+n}} e\left(   x' \cdot \xi'+x''\cdot \xi'' +x_{d+1}Q_1(\xi')+x_{d+2}Q_2(\xi)+\cdots+x_{d+n}Q_n(\xi)   \right)    f(\xi) d\xi. $$
	Using linear changes of variables again, we can diagonalize $Q_1(\xi')$, and it becomes
	\begin{align*}
		&E^{\mathbf{Q}}g(y)  \\
		=&\int_{\R^{d+n}} e\left(   y' \cdot \eta'+y''\cdot \eta'' +y_{d+1}(\eta_1^2\pm \eta_2^2\pm \cdots\pm \eta_{d'}^2)+y_{d+2}\tilde{Q}_2(\eta)+\cdots+y_{d+n}\tilde{Q}_n(\eta)   \right)    g(\eta) d\eta, 
	\end{align*}
	for some new coordinates $y$ and $\eta$, and the functions $\tilde{Q}_j$ and $g$. Now we restrict
	$$    |y''|\leq c,~ |y_{d+2}|\leq c,...,~|y_{d+n}|\leq c ,   $$
	for some small constant $c>0$ that may depend on $d$, $n$ and $\mathbf{Q}$. Note that $|\eta|\leq 1$, so it follows from the locally constant property that
	$$   |E^{\mathbf{Q}}g(y)| \sim  \left|\int_{\R^{d+n}} e\left(   y' \cdot \eta'+y_{d+1}(\eta_1^2\pm \eta_2^2\pm \cdots\pm \eta_{d'}^2)   \right)    g(\eta) d\eta\right|. $$
	On the other hand, we define an $\alpha$-dimensional weight $H$ in $\R^{d'+1}$ on the variables $y'$ and $y_{d+1}$. We also take
	$$    g(\eta)= g_1(\eta') \chi_{[0,1]^{d-d'}}(\eta'').  $$
	Based on these choices, we get
	$$  \frac{\|E^{\mathbf{Q}}f\|_{L^2(B_R^{d+n},H)}}{\|f\|_{L^2([0,1]^d)}} \sim \frac{\|E_1 g_1\|_{L^2(B_R^{d'+1},H)}}{\|g_1\|_{L^2([0,1]^{d'})}},   $$
	where $E_1 g_1$ is given by
	$$    E_1 g_1:= \int_{\R^{d'}} e\left(   y' \cdot \eta'+y_{d+1}(\eta_1^2\pm \eta_2^2\pm \cdots\pm \eta_{d'}^2)   \right)    g_1(\eta') d\eta',   $$
	which denotes the Fourier extension operator of the hyperbolic paraboloids in $\mathbb{R}^{d'+1}$. In \cite{bbcrv07}, Barcel\'{o}, Bennett, Carbery, Ruiz and Vilela studied the lower bounds of $s(\alpha,\mathbf{Q})$ for the paraboloids. By constructing a fractal example, they showed that if $\mathbf{Q}(\xi)=(\xi_1^2+\cdots+\xi_d^2)$, there is
	$$  s(\alpha,\mathbf{Q})\geq \frac{2\alpha-d}{2(d+2)} ,\quad \quad \alpha\geq \frac{d}{2}.   $$
	Note that their example is also suitable for the hyperbolic paraboloids. Therefore, as long as taking $\alpha>d'/2$, we can get
	$$    \frac{\|E^{\mathbf{Q}}f\|_{L^2(B_R^{d+n},H)}}{\|f\|_{L^2([0,1]^d)}} \sim \frac{\|E_1 g_1\|_{L^2(B_R^{d'+1},H)}}{\|g_1\|_{L^2([0,1]^{d'})}} \gtrsim R^{  \frac{2\alpha-d'}{2(d'+2)}  },      $$
	which implies
	$$   s(\alpha,\mathbf{Q})\geq \frac{2\alpha-d'}{2(d'+2)}>0.   $$



	Next, we consider the third estimate in (\ref{t1e1}). Although the bound $n/2$ is trivial, we can take one example to show this bound is optimal when $ d-\tilde{d}+n\leq \alpha \leq d+n$, where $\tilde{d}$ is defined in Theorem \ref{th1}. For convenience, we assume that $0<\tilde{d}<d$. By (1.15) of \cite{gozzk23}, there is 
	$$  \mathfrak{d}_{\tilde{d},n}(\mathbf{Q})=  \mathfrak{d}_{\tilde{d},n}(\mathbf{Q}|_H) , $$
	for some $H\subset \mathbb{R}^d$ which is a $\tilde{d}$-dimensional linear subspace. After the linear transformation, without loss of generality, we can assume 
	$$  H=\{  \xi_1=\xi_2=\cdots=\xi_{d-\tilde{d}}=0  \}.   $$
	From the definition of $\tilde{d}$, we get
	$$   \mathfrak{d}_{\tilde{d},n}(\mathbf{Q}|_H) =0, $$
	which is equivalent to 
	$$\mathbf{Q}|_H \equiv 0.$$
	This fact means that all monomials in $\mathbf{Q}(\xi)$ depending on $\xi_{d-\tilde{d}+1}$, ..., $\xi_d$ must be of the forms $\xi_i \xi_{d-\tilde{d}+1}$, ..., $\xi_i \xi_{d}$ for some $i\in \{ 1,2,...,d-\tilde{d}\}.$ Take $f$ as
	$$  f(\xi)=\chi_{[0,R^{-1}]^{d-\tilde{d}}}(\xi_1,...,\xi_{d-\tilde{d}}) \chi_{[0,1]^{\tilde{d}}}(\xi_{d-\tilde{d}+1},...,\xi_d) .      $$
	Thus
	$$ \|f\|_{L^2([0,1]^d)}=  R^{-\frac{d-\tilde{d}}{2}}.   $$
	On the other hand, by the locally constant property, there is 
	$$  |E^{\mathbf{Q}}f(x)| \gtrsim R^{-(d-d')},   $$
	when $x=(x_1,...,x_{d+n})$ belongs to
	$$ \left\{ |x_1|\leq cR,...,|x_{d-\tilde{d}}|\leq cR, |x_{d-\tilde{d}+1}|\leq c,...,|x_d|\leq c, |x_{d+1}|\leq cR,...,|x_{d+n}|\leq cR     \right\},   $$
	for some small constant $c>0$. Denote this set by $T$. Then we obtain
	$$    \frac{\|E^{\mathbf{Q}}f\|_{L^2(B_R,H)}}{\|f\|_{L^2([0,1]^d)}}\geq \frac{\|E^{\mathbf{Q}}f\|_{L^2(T,H)}}{\|f\|_{L^2([0,1]^d)}} \gtrsim  R^{-\frac{d-\tilde{d}}{2}} \left(\int_T H(x)dx  \right)^{\frac{1}{2}}.  $$
	Next, we choose a $(d-\tilde{d}+n)$-dimensional weight $H$ in $\R^{d-\tilde{d}+n}$ on the variables $x_1$, ..., $x_{d-\tilde{d}}$, $x_{d+1}$,..., $x_{d+n}$, and $H$ restricted in each 1-dimensional subspace of these variables is produced by the Lebesgue measure. Thus  the above further becomes
	$$    \frac{\|E^{\mathbf{Q}}f\|_{L^2(B_R,H)}}{\|f\|_{L^2([0,1]^d)}}\gtrsim  R^{-\frac{d-\tilde{d}}{2}} \cdot R^{\frac{d-\tilde{d}+n}{2}}=R^{\frac{n}{2}},  $$
	which implies
	$$   s(\alpha,\mathbf{Q})\geq  \frac{n}{2} ,\quad \quad d-\tilde{d}+n\leq \alpha \leq d+n.  $$


	We have used one example to show the bound $n/2$ in the range $d-\tilde{d}+n\leq \alpha \leq d+n$ is sharp. Besides, we can also  prove that this range such that $s(\alpha,\mathbf{Q})=n/2$ is maximal possible. More accurately, we will show $s(\alpha,\mathbf{Q})< n/2$ when $\alpha< d-\tilde{d}+n$. It relies on the estimates built in Subsection \ref{du_zhang_method}. In fact, (\ref{s3ff1}) is enough to obtain this conclusion:
	$$    s(\alpha,\mathbf{Q})\leq \min_{ p\geq 2 } \left(   \frac{\Gamma_p^{d}(\mathbf{Q})}{2}+\frac{d+n-\alpha}{2p}+\frac{\alpha+n-d}{4} \right).  $$
	Note this quality is just $n/2$ when $p=2$, so it suffices to show: For $\alpha< d-\tilde{d}+n$, there exists $p>2$ such that
	\begin{equation}\label{ex3e1}
		\Gamma_p^{d}(\mathbf{Q})+\frac{d+n-\alpha}{p}+\frac{\alpha+n-d}{2} <n. 
	\end{equation}
	Using the range of $\alpha$ and (\ref{dec th1 00}), one gets
	\begin{align*}
		&\Gamma_p^{d}(\mathbf{Q})+\frac{d+n-\alpha}{p}+\frac{\alpha+n-d}{2} \\
		<& \Gamma_p^{d}(\mathbf{Q})-\left( \frac{1}{2}-\frac{1}{p}\right)\tilde{d}+n    \\
		=  &   \max_{d',n'}  \Big\{ \Big(d'- \mathfrak{d}_{d',n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(n-n')}{p}    \Big\}-\left( \frac{1}{2}-\frac{1}{p}\right)\tilde{d}+n  \\
		= &   \max_{d',n'}  \Big\{ \Big(d'-\tilde{d}- \mathfrak{d}_{d',n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(n-n')}{p}    \Big\}+n.
	\end{align*}
	So we only need to show: For any $0\leq d'\leq d$ and $0\leq n'\leq n$, there exists $p>2$ such that 
	\begin{equation}\label{ex3e2}
		\Big(d'-\tilde{d}- \mathfrak{d}_{d',n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(n-n')}{p}   \leq 0. 
	\end{equation}

	We divide the proof of (\ref{ex3e2}) into three cases. The first case is $0\leq d'\leq \tilde{d}$ and $0\leq n'\leq n$. Then (\ref{ex3e2}) holds for all $p>2$ by noting $\mathfrak{d}_{d',n'}(\mathbf{Q})\geq 0$ for all $d'$ and $n'$. The second case is $\tilde{d}< d'\leq d$ and $n'= n$. In this case, we only need to show
	$$   d'-\tilde{d}- \mathfrak{d}_{d',n}(\mathbf{Q})\leq 0,  \quad \quad \tilde{d}< d'\leq d,    $$
	and then (\ref{ex3e2}) holds for all $p>2$. In fact, it is equivalent to
	\begin{equation}\label{s4final}
		\mathfrak{d}_{d',n}(\mathbf{Q}) \geq d'-\tilde{d}, \quad \quad \tilde{d}< d'\leq d. 
	\end{equation}
	If $d'=\tilde{d}+1$, by the definition of $\tilde{d}$, we have 
	$$     \mathfrak{d}_{d',n}(\mathbf{Q}) \geq 1,  $$
	and (\ref{s4final}) follows. If $d'>\tilde{d}+1$, we have one simple observation: As long as $\mathfrak{d}_{d',n}(\mathbf{Q})>0$, there is
	$$    \mathfrak{d}_{d',n}(\mathbf{Q})>\mathfrak{d}_{d'-1,n}(\mathbf{Q}).   $$
	Applying this observation, we can obtain (\ref{s4final}) immediately, and then (\ref{ex3e2}) follows. Finally, we consider the third case: $\tilde{d}<d'\leq d$ and $0\leq n'< n$. We can further assume $d'-\tilde{d}- \mathfrak{d}_{d',n'}(\mathbf{Q})> 0$, otherwise we can repeat the argument of the first case, and then the result follows. Next we can rewrite (\ref{ex3e2}) as follows
	\begin{equation}\label{ex3e3}
		2 < p\leq 2+\frac{4(n-n')}{d'-\tilde{d}- \mathfrak{d}_{d',n'}(\mathbf{Q})}.  
	\end{equation}
	Considering the ranges of $d',n'$ of this case, we can choose an appropriate $p$ to make (\ref{ex3e3}) hold. 






	\section{Several examples of Theorem \ref{th1}}\label{sec5}



	In this section, we will deal with several examples of Theorem \ref{th1}, such as the paraboloids, hyperbolic paraboloids, all quadratic manifolds with $d+n\leq 5$, and good manifolds. 


    \subsection{Paraboloids and hyperbolic paraboloids}\phantom{x}

	Firstly, we consider the parabolic case of Theorem \ref{th1}. The estimates in Theorem \ref{th1} will recover (\ref{his1}) for all $0 <\alpha \leq d+1$, which are the best results yet.

	\begin{corollary}[Paraboloids]\label{cor1}
		Suppose that $\mathbf{Q}$ denotes the paraboloids, i.e.,
		$$\mathbf{Q}(\xi)=(\xi_1^2+\xi_2^2+\cdots+\xi_d^2).$$ 
		Then we have    
		\begin{align}\label{cor1e1}
			~s(\alpha,\mathbf{Q})\leq 
			\begin{cases}
				~	0, \quad \quad\quad \quad    & 0<  \alpha \leq \frac{d}{2},   \\
				~	\frac{2\alpha-d}{4}, \quad \quad \quad\quad 
				&\frac{d}{2}<  \alpha< \frac{d+1}{2},   \\
				~	\frac{\alpha}{2(d+1)}, \quad \quad \quad\quad &\frac{d+1}{2}\leq   \alpha\leq d+1. 
			\end{cases}
		\end{align}
	\end{corollary}

	\begin{proof} By Definition \ref{s1d1}, we have: For each $0\leq d'\leq d$, there is
		\begin{align}
			\mathfrak{d}_{d',1}(\mathbf{Q})&= \inf_{\substack{   M \in \mathbb{R}^{d\times d} \\ {\rm rank}(M)=d'   }} \rank \big( M \cdot \nabla_\xi^2\mathbf{Q} \cdot M^T  \big) \nonumber \\
			&=  \inf_{\substack{   M \in \mathbb{R}^{d\times d} \\ {\rm rank}(M)=d'   }} \rank \big( M  \cdot M^T  \big) \nonumber \\ 
			&= \inf_{\substack{   M \in \mathbb{R}^{d\times d} \\ {\rm rank}(M)=d'   }} \rank(M) = d'. \label{s5c51eq1}
		\end{align}

		For $2\leq k\leq d+2$, from (\ref{dec th1 00}), we can obtain
		\begin{align*}
			\Gamma_p^{k-2}(\mathbf{Q}) &=  \max_{0\leq d'\leq k-2} \max_{0\leq n' \leq 1} \Big\{  \Big(d'- \mathfrak{d}_{d',n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(1-n')}{p}    \Big\} \\
			&=  \max_{0\leq d'\leq k-2}\max\Big\{ d'\Big( \frac{1}{2} -\frac{1}{p} \Big)-\frac{2}{p},~0    \Big\}  \\
			&= \max\Big\{ \frac{k-2}{2}-\frac{k}{p},~0    \Big\} .
		\end{align*}
		Thus we get the endpoint of $\ell^2L^p$ decoupling is $p=\frac{2k}{k-2}$, and corresponding $\Gamma_p^{k-2}(\mathbf{Q})=0$. On the other hand, repeating the arguments of Appendix C in  \cite{ggo23}, we can get  
		$$   X(\mathbf{Q},k,m) \geq m \cdot \frac{k-1}{k}.   $$
		Combining the two results and doing some calculations, (\ref{t1e2}) implies the third bound in (\ref{cor1e1}), and then Theorem \ref{th1} implies Corollary \ref{cor1}.
	\end{proof}



	Next, we consider the hyperbolic case on Theorem \ref{th1}.

	\begin{corollary}[Hyperbolic paraboloids]\label{cor2}
		Suppose that $\mathbf{Q}$ denotes the hyperbolic paraboloids, i.e.,
		$$\mathbf{Q}(\xi)=(\xi_1^2+\cdots+\xi_{d-m}^2-\xi_{d-m+1}^2-\cdots-\xi_d^2)$$ 
		for some $m\leq d/2$. Then we have    
		\begin{align}\label{cor2e1}
			~s(\alpha,\mathbf{Q})\leq 
			\begin{cases}
				~	0, \quad \quad\quad \quad    & 0<  \alpha \leq \frac{d}{2},   \\
				~	\frac{2\alpha-d}{4}, \quad \quad \quad\quad 
				&\frac{d}{2}<  \alpha< d+1-m,   \\
				~	\frac{1}{2}, \quad \quad \quad\quad &d+1-m\leq   \alpha\leq d+1. 
			\end{cases}
		\end{align}
		Moreover, for $m>1$ and $j\in [1,m-1]$, there is
		\begin{align}\label{cor2e2}
			~s(\alpha,\mathbf{Q})\leq 
			\begin{cases}
				~	\frac{\alpha}{2(d+1-j)}, \quad \quad\quad \quad    & \frac{(j-1)(d+1-j)}{m-1}  \leq  \alpha <\frac{j(d+1-j)}{m},   \\
				~	\frac{\alpha-j}{2(d+1-j-m)}, \quad \quad \quad\quad 
				&\frac{j(d+1-j)}{m} \leq   \alpha< \frac{j(d-j)  }{m-1}.
			\end{cases}
		\end{align}
	\end{corollary}


	\begin{proof} 
		We claim
		\begin{align}\label{s5c52eq1}
			~\mathfrak{d}_{d-\ell,1}(\mathbf{Q})=
			\begin{cases}
				~	d-2\ell, \quad \quad\quad \quad    & 0\leq   \ell\leq m,   \\
				~	d-\ell-m, \quad \quad \quad\quad 
				&m<  \ell< d-m,   \\
				~	0, \quad \quad \quad\quad &d-m\leq \ell\leq d. 
			\end{cases}
		\end{align}
		In fact, when $0\leq   \ell\leq m$, note
		\begin{equation}\label{s5c51eq2}
			\mathfrak{d}_{d-\ell,1}(\mathbf{Q}) = \inf_{L {\rm ~of~dim~}d-\ell} \mathfrak{d}_{d-\ell,1}(\mathbf{Q}|_{L}).  
		\end{equation}
        By taking 
        $$  L=\big\{  \xi_1=\xi_{d-m+1},~\xi_2=\xi_{d-m+2},\dots,~\xi_\ell=\xi_{d-m+\ell} \big\}      $$
        in (\ref{s5c51eq2}), we have 
        $$   \mathbf{Q}(\xi)|_{L}=(\xi_{\ell+1}^2+\cdots+\xi_{d-m}^2-\xi_{d-m+\ell+1}^2-\cdots-\xi_d^2), $$
        which means $  \mathfrak{d}_{d-\ell,1}(\mathbf{Q}) \leq d-2\ell  $ when $\ell \leq m$. 
		On the other hand, by Lemma 3.1 of \cite{gozzk23}, we know this upper bound is also the lower bound, so we have proved the first equation in (\ref{s5c52eq1}). When $m<  \ell \leq  d-m$, note that $\mathfrak{d}_{d-\ell,1}(\mathbf{Q}) \leq \mathfrak{d}_{d-m,1}(\mathbf{Q}) - (\ell-m) = d - \ell - m$, so it suffices to prove $\mathfrak{d}_{d-\ell,1}(\mathbf{Q}) \geq d - \ell - m$. By Definition \ref{s1d1}, we have: For each $0\leq d'\leq d$, there is
		\begin{align*}
			\mathfrak{d}_{d-\ell,1}(\mathbf{Q})&= \inf_{\substack{   M \in \mathbb{R}^{d\times d} \\ {\rm rank}(M)=d-\ell   }} \rank \big( M \cdot \nabla_\xi^2\mathbf{Q} \cdot M^T  \big) \\
			&= \inf_{\substack{   M \in \mathbb{R}^{(d-\ell)\times d} \\ {\rm rank}(M)=d-\ell   }} \rank \left( M \cdot \begin{pmatrix}
				I_{d-m} & 0\\
				0 & -I_m
			\end{pmatrix} \cdot M^T  \right)\\
			&= \inf_{\dim V = d-\ell} \dim \pi_V (T(V)),
		\end{align*}
		where $V$ is the subspace in $\R^d$ spanned by row vectors of $M$, $\pi_V$ is defined as in Definition \ref{s1d2}, and $T: \R^d \rightarrow \R^d$ with $T(x_1,\dots,x_d)=(x_1,\dots,x_{d-m}, - x_{d-m+1},-x_d)$. In the last line above we used the facts that $M\cdot w = M \cdot \pi_V(w)$ for any $w \in \R^d$, and for any basis $\{v_j\}_{j=1}^{d-\ell}$ of $V$, the map $v\in V \rightarrow (v\cdot v_j)_{j=1}^{d-\ell} \in \R^{d-\ell}$ is a linear isomorphism. 
		Let $W \coloneqq \{v \in \R^d: T(v) = v\}$, then $\dim W = d-m$, and so 
		\begin{align*}
			\dim \, T(V) \cap V &\geq \dim \, W \cap V \\
			&= \dim W + \dim V - \dim \R^d \\
			&= (d-m) + (d-\ell) - d\\ 
			&= d-\ell-m
		\end{align*}
		for any subspace $V \subset \R^d$ with $\dim V = d-\ell$. This implies that
		\begin{align*}
			\mathfrak{d}_{d-\ell,1}(\mathbf{Q}) &= \inf_{\dim V = d-\ell} \dim \pi_V (T(V))\\
			&\geq \inf_{\dim V = d-\ell} \dim \, T(V) \cap V\\
			&\geq d-\ell-m,
		\end{align*}
		as desired. So we have proved the second equation in (\ref{s5c52eq1}). Finally, the last equation in (\ref{s5c52eq1}) is obvious in view of the case $\ell=d-m$, and the proof of the claim is completed.

		For $m+2\leq k\leq d+2$, from (\ref{dec th1 00}), we can obtain
		\begin{align*}
			\Gamma_p^{k-2}(\mathbf{Q}) &=  \max_{0\leq d'\leq k-2} \max_{0\leq n' \leq 1} \Big\{  \Big(d'- \mathfrak{d}_{d',n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(1-n')}{p}    \Big\} \\
			&=  \max_{0\leq d'\leq k-2}\max\Big\{ d'\Big( \frac{1}{2} -\frac{1}{p} \Big)-\frac{2}{p},~\Big(d'- \mathfrak{d}_{d',1}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big)    \Big\}  \\
			&= \max\Big\{ \frac{k-2}{2}-\frac{k}{p},~\max_{0\leq d'\leq k-2} \Big(d'- \mathfrak{d}_{d',1}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big)    \Big\} \\
			&= \max\Big\{ \frac{k-2}{2}-\frac{k}{p},~m\Big(\frac{1}{2}-\frac{1}{p}\Big)  \Big\} .
		\end{align*}
		Thus we get the endpoint of $\ell^2L^p$ decoupling is $p=\frac{2(k-m)}{k-m-2}$, and corresponding $\Gamma_p^{k-2}(\mathbf{Q})=\frac{m}{k-m}$. On the other hand, via the same argument as in Appendix C in \cite{ggo23}, there is
		$$   X(\mathbf{Q},k,m) \geq m \cdot \frac{k-1}{k}.   $$
		Combining above two estimates, by (\ref{t1e2}), we conclude
		\begin{equation}\label{cor2e20}
			s(\alpha,\mathbf{Q})\leq  \min_{m+2\leq k\leq d+1} \max \left\{ \frac{\alpha}{2k},~\frac{k-d+\alpha-1}{2(k-m)}     \right\}. 
	\end{equation}
		In fact, we can find that (\ref{cor2e2}) and (\ref{cor2e20}) are equivalent through some algebraic calculations, see Section 5 in \cite{beh21} for more details. Therefore, Theorem \ref{th1} implies Corollary \ref{cor2}.

	\end{proof}

	\begin{remark}
		Note that {\rm (\ref{cor2e1})} and {\rm (\ref{cor2e2})} in Corollary {\rm \ref{cor2}} are exactly {\rm (\ref{his2})} and {\rm (\ref{his3})} from \cite{beh21}. But {\rm (\ref{his4})} is beyond the power of Theorem {\rm \ref{th1}}. When $n=1$, Barron, Erdo\u{g}an and Harris proved {\rm (\ref{his4})} by using bilinear weighted restriction estimates due to Lee \cite{lee06} when $d \geq 2$ and Vargas \cite{vargas05} independently when $d = 2$. The bilinear restriction estimates in turn rely on another way of exploiting the curvature property of hyperbolic paraboloids, which is closely related to the so-called ``rotational curvature'' condition. One may consult \cite{bll17} for a higher-codimensional generalization of the bilinear restriction method as well as the rotational curvature. It is interesting to also generalize such a bilinear method to all quadratic forms in our weighted restriction setting, which might further improve Theorem {\rm \ref{th1}}, at least in some special cases. However, the current state of the art of the bilinear method in the higher-codimensional cases relies heavily on the concept of rotational curvature, while quadratic manifolds generically fail to have nonvanishing rotational curvature. One may consult the discussions in \cite{gressman15} or Section~{\rm 5} of \cite{cmp24} for additional background on this issue. Therefore, since we are pursuing a general theory that can be applied to any quadratic form including degenerate ones, we will not proceed along the direction of bilinear restriction in this paper.
	\end{remark}

    \subsection{Quadratic manifolds with \texorpdfstring{$d+n \leq 5$}{d+n≤5}}\phantom{x}

	Now let us consider all higher-codimensional quadratic forms $\mathbf{Q}$ with $d+n\leq 5$ that do not miss any variable ($\mathfrak{d}_{d,n}(\mathbf{Q})=d$) and are linearly independent ($\mathfrak{d}_{d,1}(\mathbf{Q})>0$). The two constraints on $\mathfrak{d}_{d',n'}(\mathbf{Q})$ are not essential, since they only exclude some trivial cases. Guo and Oh \cite{go22} classified the quadratic forms for the case $d=3$ and $n=2$ by some algebra. The following version stated by using the quantities $\mathfrak{d}_{d',n'}(\mathbf{Q})$ is from Theorem 1.1 in \cite{cmw24}. 

    \begin{lemma}\label{addth1}
		Let $d=3$ and $n=2$. Suppose that the quadratic form $\mathbf{Q}=(Q_1,Q_2)$ satisfies   $\mathfrak{d}_{3,2}(\mathbf{Q})=3$ and $\mathfrak{d}_{3,1}(\mathbf{Q})>0$. Then 


		\noindent {\rm (1)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=1$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=1$, then $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_2^2+\xi_1\xi_3)$ or  $(\xi_1^2,\xi_2\xi_3)$.

		\noindent {\rm (2)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=1$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=2$, then $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_2^2+\xi_3^2)$.

		\noindent {\rm (3)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=0$, then $\mathbf{Q}(\xi)\equiv (\xi_1 \xi_2,\xi_1\xi_3)$.

		\noindent {\rm (4)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=1$, then $\mathbf{Q}(\xi)\equiv (\xi_1\xi_2,\xi_2^2+\xi_1\xi_3)$ or $ (\xi_1\xi_2,\xi_1^2\pm\xi^2_3)$.

		\noindent {\rm (5)} $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=2$ if and only if $\mathbf{Q}$ satisfies the ${\rm (CM)}$ condition. 
    \end{lemma}

	We note the classification of the case $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=2$ in above lemma is still not explicit enough. Now we will further categorize this case. In fact, we will provide a complete classification of all higher-codimensional quadratic forms $\mathbf{Q}$ with $d+n\leq 5$ satisfying $\mathfrak{d}_{d,n}(\mathbf{Q})=d$ and $\mathfrak{d}_{d,1}(\mathbf{Q})>0$. 

	\begin{lemma}\label{addth2}
		Let $d+n\leq 5$ and $n\geq 2$. Suppose that the quadratic form $\mathbf{Q}$ satisfies $\mathfrak{d}_{d,n}(\mathbf{Q})=d$ and $\mathfrak{d}_{d,1}(\mathbf{Q})>0$. 

		\noindent {\rm (a)} Suppose that $d=n=2$, then

		{\rm (a1)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{2,1}(\mathbf{Q})=1$ and $\mathfrak{d}_{1,2}(\mathbf{Q})=0$, then $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_1\xi_2)$.

		{\rm (a2)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{2,1}(\mathbf{Q})=1$ and $\mathfrak{d}_{1,2}(\mathbf{Q})=1$, then $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_2^2)$.

		{\rm (a3)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{2,1}(\mathbf{Q})=2$, then $\mathbf{Q}(\xi)\equiv (\xi_1 \xi_2,\xi_1^2-\xi_2^2)$.

		\noindent {\rm (b)} Suppose that $d=2$ and $n=3$, then $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_1\xi_2,\xi_2^2)$.

		\noindent {\rm (c)} Suppose that $d=3$ and $n=2$, then

		{\rm (c1)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=1$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=1$, then $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_2^2+\xi_1\xi_3)$ or  $(\xi_1^2,\xi_2\xi_3)$.

		{\rm (c2)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=1$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=2$, then $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_2^2+\xi_3^2)$.

		{\rm (c3)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=0$, then $\mathbf{Q}(\xi)\equiv (\xi_1 \xi_2,\xi_1\xi_3)$.

		{\rm (c4)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=1$, then $\mathbf{Q}(\xi)\equiv (\xi_1\xi_2,\xi_2^2+\xi_1\xi_3)$ or $ (\xi_1\xi_2,\xi_1^2\pm\xi^2_3)$.

		{\rm (c5)} If $\mathbf{Q}$ satisfies $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=2$, then $\mathbf{Q}(\xi)\equiv (\xi_1^2+\xi_2^2,\xi_2^2+\xi_3^2)$ or $ (\xi_1^2-\xi_2^2,\xi_2^2-\xi_3^2)$ or $(\xi_1^2-\xi_2^2,\xi_1\xi_2+\xi_3^2)$.

		Moreover, all possible cases of higher-codimensional quadratic forms with $d+n\leq 5$ are listed above, and they are not equivalent to each other. In other words, we get a complete classification.
	\end{lemma}




	\begin{proof} When $d=1$, we note the case for $2 \leq n \leq 4$ is vacuous. When $d=n=2$, readers can see Theorem 5.1 in \cite{cmp24} for reference. When $d=2$ and $n=3$, since the dimension of the linear space spanned by all quadratic monomials in $2$ variables is exactly $3$, $\mathbf{Q}\equiv (\xi_1^2,\xi_1\xi_2,\xi_2^2)$ is the only quadratic form satisfying $\mathfrak{d}_{2,3}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,1}(\mathbf{Q})>0$. When $d=3$ and $n=2$, combined with Lemma \ref{addth1}, we only need to consider the case $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ and $\mathfrak{d}_{2,2}(\mathbf{Q})=2$.

		We pick $M\in \mathbb{R}^{3\times 3}$ and $M'\in \mathbb{R}^{1\times 2}$ such that the equality in (\ref{s2def2e1}) with $d'=3,n'=1$ is achieved. By linear transformations, we may suppose that $M=I$ and $M'=(1,0)$. Then $\mathfrak{d}_{3,1}(\mathbf{Q})=2$ implies that $Q_1$ depends on 2 variables. We use linear transformations again to diagonalize $Q_1$, then
		$$ (Q_1(\xi),Q_2(\xi))\equiv (\xi_1^2\pm\xi_2^2, b_{11}\xi_1^2 +b_{22}\xi_2^2+b_{33}\xi_3^2+2b_{12}\xi_1\xi_2+2b_{13}\xi_1\xi_3+2b_{23}\xi_2\xi_3).     $$
		We divide it into two cases: $Q_1(\xi)=\xi_1^2+\xi_2^2$ and $Q_1(\xi)=\xi_1^2-\xi_2^2$. 

		We begin with the first case, i.e., $Q_1(\xi)=\xi_1^2+\xi_2^2$. We first prove $b_{33}\neq 0$. Otherwise, suppose $b_{33}= 0$, then
		$$ (Q_1(\xi),Q_2(\xi))\equiv (\xi_1^2+\xi_2^2, b_{11}\xi_1^2 +2b_{12}\xi_1\xi_2+2b_{13}\xi_1\xi_3+2b_{23}\xi_2\xi_3).     $$
		However, it is easy to see that $\det(x_1Q_1+x_2Q_2)$ has a factor $x_2^2$, which contradicts our assumption that $\mathbf{Q}$ satisfies the (CM) condition. 

		Note that $b_{33}\neq 0$, by a change of variables in $\xi_3$, we obtain
		\begin{align*}
			(Q_1(\xi),Q_2(\xi))&\equiv (\xi_1^2+\xi_2^2, b_{11}\xi_1^2 +b_{22}\xi_2^2+2b_{12}\xi_1\xi_2+\xi_3^2)    \\
			&\equiv (\xi_1^2+\xi_2^2, b_{22}\xi_2^2+2b_{12}\xi_1\xi_2+\xi_3^2).
		\end{align*}
		Here we are slightly abusing the notation $b_{ij}$, whose exact meaning may change after linear transformations. We choose to do so for convenience as we only care about the form of the expression. 
		If $b_{22}=0$, then $b_{12}\neq 0$, since otherwise it becomes the case (c2), which contradicts the (CM) assumption. So 
		\begin{equation}\label{addt2e1}
			(Q_1(\xi),Q_2(\xi))\equiv  (\xi_1^2+\xi_2^2, \xi_1\xi_2+\xi_3^2) \equiv  (\xi_1^2+\xi_2^2, \xi_2^2+\xi_3^2).  
		\end{equation}
		If $b_{22}\neq 0$, we can write
		$$    (Q_1(\xi),Q_2(\xi))\equiv (\xi_1^2+\xi_2^2, \xi_2^2+2b_{12}\xi_1\xi_2+\xi_3^2). $$
		By adding a multiple of $Q_1$ to $Q_2$, we form a complete square in $Q_2$. Using a change of variables again, we obtain
		$$    (Q_1(\xi),Q_2(\xi))\equiv (f(\xi_1,\xi_2), \xi_2^2-\xi_3^2) $$
		for some quadratic form $f(\xi_1,\xi_2)$, and it is reduced to the second case.

		Now we consider the second case, i.e., $Q_1(\xi)=\xi_1^2-\xi_2^2$. By a change of variables, we can assume $Q_1(\xi)=\xi_1\xi_2$, and then
		$$ (Q_1(\xi),Q_2(\xi))\equiv (\xi_1\xi_2, b_{11}\xi_1^2 +b_{22}\xi_2^2+b_{33}\xi_3^2+2b_{13}\xi_1\xi_3+2b_{23}\xi_2\xi_3).     $$
		Similar to the argument in the first case, we have $b_{33}\neq 0$, and thus
		$$ (Q_1(\xi),Q_2(\xi))\equiv (\xi_1\xi_2, b_{11}\xi_1^2 +b_{22}\xi_2^2+\xi_3^2+2b_{13}\xi_1\xi_3+2b_{23}\xi_2\xi_3).     $$
		Via additional elementary transformation, we get
		$$ (Q_1(\xi),Q_2(\xi))\equiv (\xi_1\xi_2, b_{11}\xi_1^2 +b_{22}\xi_2^2+\xi_3^2).     $$
		We will actually show that $b_{11}\neq 0$ and $b_{22}\neq0$.

		If $b_{11}=b_{22}=0$, one gets
		$$ (Q_1(\xi),Q_2(\xi))\equiv (\xi_1\xi_2, \xi_3^2),     $$
		which is the case (c1), a contradiction. If $b_{11}\neq 0$ and $b_{22}=0$, one gets
		$$ (Q_1(\xi),Q_2(\xi))\equiv (\xi_1\xi_2, \xi_1^2 +\xi_3^2),     $$
		which is the case (c4), still a contradiction. The cases  $b_{11}= 0$ and $b_{22}\neq 0$ are the same. 

		Thus we have proved $b_{11}\neq 0$ and $b_{22}\neq0$. In this setting, we have either
		\begin{equation}\label{addt2e2}
			(Q_1(\xi),Q_2(\xi))\equiv (\xi_1\xi_2, \xi_1^2 +\xi_2^2+\xi_3^2)\equiv (\xi_1^2+\xi_2^2,\xi_2^2+\xi_3^2), 
		\end{equation}
		or 
		\begin{equation}\label{addt2e3}
			(Q_1(\xi),Q_2(\xi))\equiv (\xi_1\xi_2, \xi_1^2 +\xi_2^2-\xi_3^2)\equiv (\xi_1^2-\xi_2^2,\xi_2^2-\xi_3^2), 
		\end{equation}
		or
		\begin{equation}\label{addt2e4}
			(Q_1(\xi),Q_2(\xi))\equiv (\xi_1\xi_2, \xi_1^2 -\xi_2^2+\xi_3^2)\equiv (\xi_1^2-\xi_2^2,\xi_1\xi_2+\xi_3^2).
		\end{equation}
		Note that (\ref{addt2e2}) is just (\ref{addt2e1}), and we have completed the classification of the case (c5). In addition, for (\ref{addt2e2}), we can easily check $\mathfrak{d}_{2,1}(\mathbf{Q})=0$ and $\mathfrak{d}_{1,2}(\mathbf{Q})=1$. For (\ref{addt2e3}) and (\ref{addt2e4}), we can easily check that $\mathfrak{d}_{2,1}(\mathbf{Q})=0$ and $\mathfrak{d}_{1,2}(\mathbf{Q})=0$.  

		To show that we get a complete classification, first note that by our proof these are indeed the only possible cases, so it remains to show that they are not equivalent to each other. Such an issue is not discussed in \cite{go22}.

		If two quadratic forms have different $(d,n)$, or have the same $(d,n)$ but different $\mathfrak{d}_{d',n'}(\mathbf{Q})$, then they are not equivalent. This is because $\mathfrak{d}_{d',n'}(\mathbf{Q})$ is an invariant under the equivalence. By this fact, combined with the calculations on the case (c5), we only need to show that $(\xi_1^2,\xi_2^2+\xi_1\xi_3)$ and  $(\xi_1^2,\xi_2\xi_3)$ in (c1) are not equivalent, $(\xi_1\xi_2,\xi_2^2+\xi_1\xi_3)$ and $ (\xi_1\xi_2,\xi_1^2\pm\xi^2_3)$ in (c4) are not equivalent, and $(\xi_1^2-\xi_2^2,\xi_2^2-\xi_3^2)$ and $(\xi_1^2-\xi_2^2,\xi_1\xi_2+\xi_3^2)$ in (c5) are not equivalent.

		A very useful property that we will use is that, for $\mathbf{Q} = (Q_1,Q_2)$, the distribution of the zero set
		$$\Lambda \coloneqq \{(x:y) \in \mathbb{RP}^1 : \det(xQ_1+yQ_2) = 0\}$$ 
		is an invariant under the equivalence. Here by ``distribution'' we mean the number of distinct zeros as well as the multiplicities of these zeros. This property can be proved by simply noting that change of variables only multiplies the value of $\det$ by a nonzero constant, and linear transformation of $\mathbf{Q}$ only distorts the zero set in $\mathbb{RP}^1$ by an invertible linear isomorphism. 

		For $(\xi_1^2,\xi_2^2+\xi_1\xi_3)$ and  $(\xi_1^2,\xi_2\xi_3)$ in (c1), the $\Lambda$ of the former is given by $$2y^3 = 0 \Leftrightarrow (x:y) = (1:0),$$ 
		while the $\Lambda$ of the latter is given by 
		$$2xy^2 = 0 \Leftrightarrow (x:y) = (1:0), (0:1).$$
		So they are not equivalent.

		Similarly, for $(\xi_1^2-\xi_2^2,\xi_2^2-\xi_3^2)$ and $(\xi_1^2-\xi_2^2,\xi_1\xi_2+\xi_3^2)$ in (c5), the $\Lambda$ of the former is given by 
		$$8x(x-y)y = 0 \Leftrightarrow (x:y) = (1:0), (1:1), (0:1),$$ 
		while the $\Lambda$ of the latter is given by 
		$$2y(4x^2+y^2) = 0 \Leftrightarrow (x:y) = (1:0).$$ 
		So they are not equivalent.

		Next, for $(\xi_1\xi_2,\xi_2^2+\xi_1\xi_3)$ and $ (\xi_1\xi_2,\xi_1^2\pm\xi_3^2)$ in (c4), the $\Lambda$ of the former is given by 
		$$2y^3 = 0 \Leftrightarrow (x:y) = (1:0),$$ 
		while the $\Lambda$ of the latter is given by 
		$$\pm 2yx^2 = 0 \Leftrightarrow (x:y) = (1:0), (0:1).$$ 
		So they are not equivalent. 

		Finally, we still need to show that $(\xi_1\xi_2,\xi_1^2 + \xi_3^2)$ and $ (\xi_1\xi_2,\xi_1^2 - \xi_3^2)$ are not equivalent, and all the tricks introduced before do not work any more. Therefore, we proceed with a direct computation. Assume by contradiction that $(\xi_1\xi_2,\xi_1^2 + \xi_3^2)$ and $ (\xi_1\xi_2,\xi_1^2 - \xi_3^2)$ are equivalent, then there must exist some invertible linear transformation
		$$(\widetilde{\xi}_1, \widetilde{\xi}_2, \widetilde{\xi}_3) = (a_1\xi_1 + b_1\xi_2 + c_1\xi_3, a_2\xi_1 + b_2\xi_2 + c_2\xi_3, a_3\xi_1 + b_3\xi_2 + c_3\xi_3)$$
		such that 
		$$(\widetilde{\xi}_1\widetilde{\xi}_2, \widetilde{\xi}_1^2 + \widetilde{\xi}_3^2) = (A_1\xi_1\xi_2 + B_1(\xi_1^2 - \xi_3^2), A_2\xi_1\xi_2 + B_2(\xi_1^2 - \xi_3^2))$$ 
		with $A_1B_2-A_2B_1 \neq 0$. By comparing the coefficients of $\xi_1^2$ and $\xi_3^2$ in the second factor $\widetilde{\xi}_1^2 + \widetilde{\xi}_3^2$, we see that $a_1^2 + a_3^2 = B_2$ and $c_1^2 + c_3^2 = -B_2$, which means $a_1^2 + a_3^2 + c_1^2 + c_3^2 = 0$ and thus we must have $a_1 = a_3 = c_1 = c_3 = 0$. However, this implies that the $3 \times 3$ matrix
		\begin{align*}
			\begin{pmatrix}
				a_1 & b_1 & c_1 \\
				a_2 & b_2 & c_2 \\
				a_3 & b_3 & c_3
			\end{pmatrix}
			=
			\begin{pmatrix}
				0 & b_1 & 0 \\
				a_2 & b_2 & c_2 \\
				0 & b_3 & 0
			\end{pmatrix}
		\end{align*}
		is not invertible, a contradiction. So $(\xi_1\xi_2,\xi_1^2 + \xi_3^2)$ and $ (\xi_1\xi_2,\xi_1^2 - \xi_3^2)$ are not equivalent. And the proof is completed.

	\end{proof}

	Based on this classification, combined with Theorem \ref{th1}, we can obtain the following weighted restriction results. In particular, for the case $d=3$ and $n=2$, Theorem \ref{th1} can improve the results of \cite{cmw24}. 


	\begin{corollary}\label{th3}
		Let $d+n\leq 5$ and $n\geq 2$. Suppose that the quadratic form $\mathbf{Q}$ satisfies $\mathfrak{d}_{d,n}(\mathbf{Q})=d$ and $\mathfrak{d}_{d,1}(\mathbf{Q})>0$. 


		\noindent {\rm (a)} Suppose that $d=n=2$, then


		{\rm (a1)} If $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_1\xi_2)$, we have
		\begin{equation}\label{kk1}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,\frac{1}{2}],   \\
				~	\frac{2\alpha-1}{4}, \quad \quad&\alpha\in(\frac{1}{2},2],  \\
				~	\frac{\alpha+1}{4}, \quad \quad&\alpha\in(2,3],   \\
				~	1, \quad \quad& \alpha\in(3,4].
			\end{cases}
		\end{equation}


		{\rm (a2)} If $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_2^2)$, we have
		\begin{equation}\label{kk2}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,\frac{1}{2}],   \\
				~	\frac{2\alpha-1}{4}, \quad \quad&\alpha\in(\frac{1}{2},\frac{3}{2}],  \\
				~	\frac{\alpha}{3}, \quad \quad&\alpha\in(\frac{3}{2},2],   \\
				~	\frac{\alpha+2}{6}, \quad \quad& \alpha\in(2,4].
			\end{cases}
		\end{equation}

		{\rm (a3)} If $\mathbf{Q}(\xi)\equiv (\xi_1 \xi_2,\xi_1^2-\xi_2^2)$, we have
		\begin{equation}\label{kk3}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,1],   \\
				~	\frac{\alpha-1}{2}, \quad \quad&\alpha\in(1,2],  \\
				~	\frac{\alpha}{4}, \quad \quad& \alpha\in(2,4].
			\end{cases}
		\end{equation}



		\noindent {\rm (b)} Suppose that $d=2$ and $n=3$. If $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_1\xi_2,\xi_2^2)$, we have
		\begin{equation}\label{kk4}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,\frac{1}{2}],   \\
				~	\frac{2\alpha-1}{4}, \quad \quad&\alpha\in(\frac{1}{2},2],  \\
				~	\frac{3\alpha}{8}, \quad \quad& \alpha\in(2,\frac{16}{5}]   \\
				~    \frac{\alpha+4}{6}  , \quad \quad& \alpha\in(\frac{16}{5},5] .
			\end{cases}
		\end{equation}


		\noindent {\rm (c)} Suppose that $d=3$ and $n=2$.

		{\rm (c1)} If $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_2^2+\xi_1\xi_3)$ or  $(\xi_1^2,\xi_2\xi_3)$, we have
		\begin{equation}\label{kk5}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,\frac{1}{2}],   \\
				~	\frac{2\alpha-1}{4}, \quad \quad&\alpha\in(\frac{1}{2},\frac{3}{2}],  \\
				~	\frac{\alpha}{3}, \quad \quad&\alpha\in(\frac{3}{2},2],   \\
				~	\frac{\alpha+2}{6} , \quad \quad& \alpha\in(2,4],  \\
				~	1, \quad  \quad& \alpha\in(4,5].
			\end{cases}
		\end{equation}



		{\rm (c2)} If $\mathbf{Q}(\xi)\equiv (\xi_1^2,\xi_2^2+\xi_3^2)$, we have
		\begin{equation}\label{kk6}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,\frac{1}{2}],   \\
				~	\frac{2\alpha-1}{4}, \quad \quad&\alpha\in(\frac{1}{2},\frac{3}{2}],  \\
				~	\frac{\alpha}{3}, \quad \quad& \alpha\in(\frac{3}{2},\frac{9}{5}],   \\		~	\frac{\alpha+3}{8} , \quad \quad&  \alpha\in(\frac{9}{5},5].
			\end{cases}
		\end{equation}


		{\rm (c3)} If $\mathbf{Q}(\xi)\equiv (\xi_1 \xi_2,\xi_1\xi_3)$, we have
		\begin{equation}\label{kk7}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,1],   \\
				~	\frac{\alpha-1}{2}, \quad \quad& \alpha\in(1,3],   \\
				~	1, \quad  \quad& \alpha\in(3,5].
			\end{cases}
		\end{equation}


		{\rm (c4)} If $\mathbf{Q}(\xi)\equiv (\xi_1\xi_2,\xi_2^2+\xi_1\xi_3)$ or $ (\xi_1\xi_2,\xi_1^2\pm\xi^2_3)$, we have
		\begin{equation}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,1],   \\
				~	\frac{\alpha-1}{2}, \quad \quad&\alpha\in(1,2],  \\
				~	\frac{\alpha}{4}, \quad \quad& \alpha\in(2,4],   \\
				~	1, \quad  \quad&  \alpha\in(4,5].
			\end{cases}
		\end{equation}

		{\rm (c5)} If $\mathbf{Q}(\xi)\equiv (\xi_1^2+\xi_2^2,\xi_2^2+\xi_3^2)$, we have
		\begin{equation}\label{th3e7}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,1],   \\
				~	\frac{\alpha-1}{2}, \quad \quad&\alpha\in(1,2],  \\
				~	\frac{\alpha}{4}, \quad \quad& \alpha\in(2,3],  \\
				~	\frac{\alpha+3}{8} , \quad \quad&  \alpha\in(3,5].
			\end{cases}
		\end{equation}




		{\rm (c6)} If $\mathbf{Q}(\xi)\equiv (\xi_1^2-\xi_2^2,\xi_2^2-\xi_3^2)$ or $(\xi_1^2-\xi_2^2,\xi_1\xi_2+\xi_3^2)$, we have
		\begin{equation}\label{th3e8}
			~s(\alpha,\mathbf{Q}) \leq \begin{cases}
				~	0, \quad \quad&\alpha\in(0,1],   \\
				~	\frac{\alpha-1}{2}, \quad \quad&\alpha\in(1,2],  \\
				~	\frac{\alpha}{4}, \quad \quad& \alpha\in(2,4],   \\
				~	1, \quad  \quad&  \alpha\in(4,5].
			\end{cases}
		\end{equation}

	\end{corollary}


	\begin{proof} The proof of this corollary is mainly some tedious calculations. Nonetheless, for completeness, we still record the detailed proof of one case, such as (a2). Suppose that $\mathbf{Q}(\xi) = (\xi_1^2,\xi_2^2)$. We note
		\begin{equation}
			\mathfrak{d}_{1,1}(\mathbf{Q})=0,~\mathfrak{d}_{1,2}(\mathbf{Q})=1,~\mathfrak{d}_{2,1}(\mathbf{Q})=1,~\mathfrak{d}_{2,2}(\mathbf{Q})=2.    
		\end{equation}
		These facts together with (\ref{t1e1}) in Theorem \ref{th1} give the first and second bounds in (\ref{kk2}). Besides, we can obtain $\Gamma_p^0(\mathbf{Q})=0$, and
		\begin{align}
			\Gamma_p^1(\mathbf{Q}) &=  \max_{0\leq d'\leq 1} \max_{0\leq n' \leq 2} \Big\{  \Big(d'- \mathfrak{d}_{d',n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(2-n')}{p}    \Big\}  \nonumber \\
			&=  \max_{0\leq n' \leq 2}\Big\{ \Big(1- \mathfrak{d}_{1,n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(2-n')}{p}     \Big\} \nonumber \\
			&= \max\Big\{ \frac{1}{2}-\frac{3}{p},~0    \Big\} ,  \label{cor6e2}
		\end{align}
		and
		\begin{align}
			\Gamma_p^2(\mathbf{Q}) &=  \max_{0\leq d'\leq 2} \max_{0\leq n' \leq 2} \Big\{  \Big(d'- \mathfrak{d}_{d',n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(2-n')}{p}    \Big\}  \nonumber\\
			&=     \max\Big\{\frac{1}{2}-\frac{3}{p},~0 ,~ \max_{0\leq n'\leq 2} \Big\{ \Big(2- \mathfrak{d}_{2,n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(2-n')}{p}   \Big\}    \Big\} \nonumber \\
			&= \max\Big\{ 1-\frac{6}{p},~0    \Big\} .   \label{cor6e3}
		\end{align}
		On the other hand, we start to calculate the values of $X(\mathbf{Q},k,m)$ for all $2\leq k\leq 3$ and $0\leq m \leq 4$. Recall that $V_\xi$ denotes the tangent space of the graph  $S_{\mathbf{Q}}$ at the point $(\xi,\mathbf{Q}(\xi))$, so
		\begin{equation*}
			V_{\xi}=  \begin{pmatrix}
				1 & 0 & 2\xi_1 &0 \\
				0 & 1 & 0 & 2\xi_2
			\end{pmatrix}  .  
		\end{equation*}
		We also use $V_\xi^{\perp}$ to denote the normal space of the graph  $S_{\mathbf{Q}}$ at the point $(\xi,\mathbf{Q}(\xi))$, so
		\begin{equation*}
			V_{\xi}^{\perp}=  \begin{pmatrix}
				2\xi_1 & 0 & -1 &0 \\
				0 & 2\xi_2 & 0 & -1
			\end{pmatrix}  .  
		\end{equation*}
		Let's first state the final calculation results: When $m=3$, there are
		\begin{align}
			&\sup_{\dim V=3} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V)) \geq 3  \}=0,  \label{c6e1}\\   
			&\sup_{\dim V=3} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V))\leq 2   \}=2,  \label{c6e2}\\  
			&\sup_{\dim V=3} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V))\leq 1   \}=1,  \label{c6e3}\\  
			&\sup_{\dim V=3} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V)) \leq 0   \}=0. \label{c6e4}
		\end{align}
		When $m=2$, there are
		\begin{align}
			&\sup_{\dim V=2} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V)) \geq 3  \}=0,  \label{c6e5}\\   
			&\sup_{\dim V=2} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V))\leq 2   \}=2,  \label{c6e6}\\  
			&\sup_{\dim V=2} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V))\leq 1   \}=2, \label{c6e7} \\  
			&\sup_{\dim V=2} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V)) \leq 0   \}=0.\label{c6e8}
		\end{align}
		When $m=1$, there are
		\begin{align}   
			&\sup_{\dim V=1} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V))\geq 2   \}=0, \label{c6e9} \\  
			&\sup_{\dim V=1} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V))\leq 1   \}=2, \label{c6e10} \\  
			&\sup_{\dim V=1} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi} (V)) \leq 0   \}=1.\label{c6e11}
		\end{align}
		Combining these estimates with Definition \ref{s1d2}, we have
		\begin{align}
			&X(\mathbf{Q},2,1)=0,~ X(\mathbf{Q},2,2)=1,~X(\mathbf{Q},2,3)=1,~X(\mathbf{Q},2,4)=2, \label{c6e12}\\
			&X(\mathbf{Q},3,1)=1,~ X(\mathbf{Q},3,2)=1,~X(\mathbf{Q},3,3)=2,~X(\mathbf{Q},3,4)=2.  \label{c6e13}
		\end{align}
		Here the case for $m=4$ is obvious by noting $\dim (\pi_{V_\xi} (V))=2$ for all $\xi \in \mathbb{R}^2$. It suffices to prove (\ref{c6e1})-(\ref{c6e11}). We will only prove the case $m=3$, i.e., (\ref{c6e1})-(\ref{c6e4}), and the arguments for other cases are similar. Let $V$ be a subspace with dimension $3$. By the rank inequality, we have
		$$     1 \leq  \dim (\pi_{V_\xi} (V)) \leq 2.  $$
		This fact implies (\ref{c6e1}), (\ref{c6e2}) and (\ref{c6e4}) immediately. So we still need to prove (\ref{c6e3}). In view of Lemma 5.3 in \cite{ggo23}, (\ref{c6e3}) is equivalent to
		\begin{equation}\label{c6e14}
			\sup_{\dim W=1} \dim \{ \xi\in \mathbb{R}^2 : \dim (\pi_{V_\xi^{\perp}} (W))\leq 0   \}=1.   
		\end{equation}
		Let $W =\text{span} \{(a,b,c,d)\}$, then 
		\begin{equation*}
			\dim (\pi_{V_\xi^{\perp}} (W))= \text{rank}_{\mathbb{R}} \begin{pmatrix}
				2\xi_1 & 0 & -1 &0 \\
				0 & 2\xi_2 & 0 & -1
			\end{pmatrix}  
			\begin{pmatrix}
				a \\
				b \\
				c \\
				d
			\end{pmatrix}=
			\text{rank}_{\mathbb{R}} \begin{pmatrix}
				2a\xi_1-c \\
				2b\xi_2-d
			\end{pmatrix} . 
		\end{equation*}
		Then the condition $ \dim (\pi_{V_\xi^{\perp}} (W))\leq 0$ implies 
		\begin{equation}\label{c6e20}
			2a\xi_1-c= 2b\xi_2-d=0.   
		\end{equation}
		Noting that $a,b,c,d$ are not zero simultaneously, (\ref{c6e20}) denotes a submanifold in $\mathbb{R}^2$ with dimensions not exceeding 1 (can reach 1), and then (\ref{c6e3}) follows. After calculating the quantities $X(\mathbf{Q},k,m)$ and $\Gamma_p^{k-2}(\mathbf{Q})$, we can use (\ref{t1e2}) to get 
		\begin{align}
			~s(\alpha,\mathbf{Q})\leq 
			\begin{cases}
				~	\frac{\alpha}{2}, \quad \quad\quad \quad    & 0<  \alpha \leq 1,   \\
				~	\frac{\alpha+2}{6}, \quad \quad \quad\quad 
				&1<  \alpha   \leq 4,
			\end{cases}
		\end{align}
		which gives the final bound in (\ref{kk2}). So Theorem \ref{th1} implies (\ref{kk2}) except the third bound $\alpha/3$. 

		The bound $\alpha/3$ in (\ref{kk2}) can be derived by a Stein-Tomas-type inequality. To be more precise, we can easily check that $\mathbf{Q}= (\xi_1^2,\xi_2^2)$ satisfies the (CM) condition. By Theorem 2.14 in \cite{mockenhaupt96}, we have the following sharp estimate:
		$$   \|E^{\mathbf{Q}}f\|_{L^6(B_R)} \lesssim \|f\|_{L^2([0,1]^d)}.   $$
		Using H\"older's inequality, one concludes
		$$     \|E^{\mathbf{Q}}f\|_{L^2(B_R,H)} \lesssim R^{\frac{\alpha}{3}} \|f\|_{L^2([0,1]^d)},  $$
		which gives the third bound in (\ref{kk2}). We also point out that the estimate (\ref{s3ff1}) derived by (\ref{cor6e3}) is 
		$$    ~s(\alpha,\mathbf{Q})\leq \frac{\alpha+2}{6}, $$
		which is not better than that from (\ref{t1e2}).


	\end{proof}


	\begin{remark}\label{rmk:ST_characterization}
		From the proof above, we see that in certain ranges, the bounds derived by Theorem {\rm \ref{th1}} are worse than those in Corollary {\rm \ref{th3}} {\rm(}or Theorem {\rm 1.3} in \cite{cmw24}{\rm)}, such as the third bound in {\rm (\ref{kk2})}, {\rm (\ref{kk4})}, {\rm (\ref{kk5})} and {\rm (\ref{kk6})}. These bounds were obtained by sharp Stein-Tomas-type inequalities as above. Therefore, it is also an interesting problem to excavate such type of argument for general quadratic forms, which should further improve Theorem {\rm \ref{th1}}, at least in some cases. For example, when $d=3$ and $n=2$, this has been completely solved in \cite{cmw24} by using the broad-narrow analysis, adaptive decoupling and adaptive induction on scales.

        However, due to possible degenerate structures, attaining sharp Stein-Tomas-type inequalities for general quadratic forms is still an open problem. Another obstacle is to find the correct nondegeneracy condition. Although the algebraic quantities $\mathfrak{d}_{d',n'}(\mathbf{Q})$ are enough to characterize the properties $s(\alpha,\mathbf{Q})=0$ and $s(\alpha,\mathbf{Q})=n/2$\footnote{This is because in {\rm (\ref{t1e1})}, the first and third estimates, as well as their associated ranges, are sharp.}, they cannot fully characterize the endpoints of Stein-Tomas-type inequalities. For example, $(\xi_1\xi_2,\xi_2^2+\xi_1\xi_3)$ and $ (\xi_1\xi_2,\xi_1^2\pm\xi^2_3)$ possess the same $\mathfrak{d}_{d',n'}(\mathbf{Q})$ for all $0\leq d'\leq d$ and $0\leq n'\leq n$, but they have different sharp Stein-Tomas-type inequalities {\rm(}see Section {\rm1} in \cite{cmw24}{\rm)}. 

        Based on these considerations, we do not intend to study Stein-Tomas inequalities systematically in this paper. However, in Section {\rm \ref{appendix:relationships}}, we will propose a conjecture about the complete geometric/algebraic characterization of quadratic manifolds satisfying ``best possible'' Stein-Tomas-type inequalities, as well as prove one direction of the implication, which may facilitate future works along this direction. 
	\end{remark}

    \subsection{Good manifolds}\phantom{x}

	Finally, we consider good quadratic forms (Definition~\ref{def:good_mfd}). The following corollary of Theorem~\ref{th1} relies on results obtained in our study of Theorem~\ref{thm:relation_diagram}, such as Proposition~\ref{prop:diag_not_str}.


	\begin{corollary}\label{cor:good_mfd}
		Suppose that $\mathbf{Q}$ is a good quadratic form and $d \geq 4$\footnote{This additional assumption is introduced purely to ensure that all the ranges that appear make sense, especially $\lfloor\frac{d+1}{2}\rfloor + 3 \leq k \leq d+1$. However, since when $n=2$, all the cases $d \leq 3$ have been explicitly computed in Corollary \ref{th3}, such an assumption is not a big deal.}, then    
		\begin{align}\label{cor4e1}
			~s(\alpha,\mathbf{Q})\leq 
			\begin{cases}
				~	0, \quad \quad\quad \quad    & 0<  \alpha \leq \frac{d-1}{2},   \\
				~	\frac{2\alpha-d+1}{4}, \quad \quad \quad\quad 
				&\frac{d-1}{2}<  \alpha< \frac{d+3}{2}.
			\end{cases}
		\end{align}
		Moreover, when $\frac{d-1}{2}<\alpha\leq d+2$, we have
		$$  s(\alpha,\mathbf{Q})\leq \min_{3\leq k\leq d+1}  \max\Big\{   \frac{\alpha}{k+1} ,~ \mu(k,\alpha)\Big\},  $$
		where $\mu(k,\alpha)$ is given by
		\begin{align*}
			~\mu(k,\alpha)=
			\begin{cases}
				~	\frac{2k+\alpha-d-2}{2k}, \quad \quad\quad \quad    & 3\leq k\leq \lfloor\frac{d+1}{2}\rfloor+2,   \\
				~	\min\big\{ \frac{k+\alpha-d}{2(k-\lfloor\frac{d+1}{2}\rfloor)},~ \frac{2\lfloor\frac{d+1}{2}\rfloor+\alpha+2-d}{2(\lfloor\frac{d+1}{2}\rfloor+2)}  \big\}, \quad \quad \quad\quad 
				&\lfloor\frac{d+1}{2}\rfloor + 3 \leq k \leq d+1.
			\end{cases}
		\end{align*}
	\end{corollary}



	\begin{proof} From Lemma 5.1 in \cite{ggo23}, we have
		\begin{equation}\label{cor4pe1}
			\mathfrak{d}_{d-m,2}(\mathbf{Q})  \geq d-m , \quad  \mathfrak{d}_{d-m,1}(\mathbf{Q})  \geq d-2m-1.      
		\end{equation}
		We note $\mathfrak{d}_{d,1}(\mathbf{Q})  \geq d-1$. In fact, using one basic computation, we have $\mathfrak{d}_{d,1}(\mathbf{Q}) = d-1$, and then (\ref{cor4e1}) follows. 

		By the proof of Proposition~\ref{prop:diag_not_str} and Remark~\ref{rmk:d_even_partial}, we have $\mathfrak{d}_{\frac{d+1}{2},1}(\mathbf{Q}) =0$ when $d$ is odd, and $\mathfrak{d}_{\frac{d}{2},1}(\mathbf{Q}) =0$ when $d$ is even. In summary, we have $\mathfrak{d}_{\lfloor\frac{d+1}{2}\rfloor,1}(\mathbf{Q}) =0$, where $\lfloor a\rfloor$ represents the maximum integer not greater than $a$. We now use all above results to calculate $\ell^2L^p$ decoupling exponents:
		\begin{align}
			\Gamma_p^{k-2}(\mathbf{Q}) &=  \max_{0\leq d'\leq k-2} \max_{0\leq n' \leq 2} \Big\{  \Big(d'- \mathfrak{d}_{d',n'}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2(2-n')}{p}    \Big\} \nonumber \\
			&=     \max\Big\{\frac{k-2}{2}-\frac{k+2}{p},~0 ,~ \max_{0\leq d'\leq k-2} \Big\{ \Big(d'- \mathfrak{d}_{d',1}(\mathbf{Q})\Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2}{p}   \Big\}    \Big\}. \label{cor4pe2} 
		\end{align}
		If $k-2\leq \lfloor\frac{d+1}{2}\rfloor$, then (\ref{cor4pe2}) becomes
		\begin{align*}
			\Gamma_p^{k-2}(\mathbf{Q}) &=     \max\Big\{\frac{k-2}{2}-\frac{k+2}{p},~0 ,~ \max_{0\leq d'\leq k-2} \Big\{d'\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2}{p}   \Big\}    \Big\} \\
			&= \max\Big\{\frac{k-2}{2}-\frac{k}{p},~0  \Big\}.
		\end{align*}
		Thus we get the endpoint of $\ell^2L^p$ decoupling and the corresponding exponent:
		$$ p=\frac{2k}{k-2},\quad \quad    \Gamma_p^{k-2}(\mathbf{Q})=0. $$
		If $k-2> \lfloor\frac{d+1}{2}\rfloor$, then (\ref{cor4pe2}) becomes
		\begin{align*}
			\Gamma_p^{k-2}(\mathbf{Q}) &\leq  \max\Big\{\frac{k-2}{2}-\frac{k+2}{p},~0 ,\max_{0\leq d'\leq \lfloor\frac{d+1}{2}\rfloor} \Big\{d'\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2}{p}   \Big\} ,\\
			&\quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad~\max_{\lfloor\frac{d+1}{2}\rfloor+1\leq d'\leq k-2} \Big\{\Big(d-d'+1 \Big)\Big(\frac{1}{2}-\frac{1}{p}\Big) -\frac{2}{p}   \Big\}    \Big\} \\
			&=  \max\Big\{\frac{k-2}{2}-\frac{k+2}{p},~\frac{\lfloor\frac{d+1}{2}\rfloor}{2}-\frac{\lfloor\frac{d+1}{2}\rfloor+2}{p},~\frac{\lceil\frac{d-1}{2}\rceil}{2}-\frac{\lceil\frac{d-1}{2}\rceil+2}{p},~0   \Big\}    \\
			&=   \max\Big\{\frac{k-2}{2}-\frac{k+2}{p},~\frac{\lfloor\frac{d+1}{2}\rfloor}{2}-\frac{\lfloor\frac{d+1}{2}\rfloor+2}{p},~0   \Big\}  ,
		\end{align*}
		where $\lceil a\rceil$ represents the smallest integer not less than $a$.
		Thus we get the endpoints of $\ell^2L^p$ decoupling and the corresponding exponents:
		$$ p=\frac{2(\lfloor\frac{d+1}{2}\rfloor+2)}{\lfloor\frac{d+1}{2}\rfloor}, \quad\quad  \Gamma_p^{k-2}(\mathbf{Q})=0;    $$
		and
		$$    p=\frac{2(k-\lfloor\frac{d+1}{2}\rfloor)}{k-\lfloor\frac{d+1}{2}\rfloor-2}, \quad\quad  \Gamma_p^{k-2}(\mathbf{Q})=\frac{2\lfloor\frac{d+1}{2}\rfloor-k+2}{k-\lfloor\frac{d+1}{2}\rfloor}.   $$
		On the other hand, by Proposition 5.2 in \cite{ggo23}, we have
		$$   X(\mathbf{Q},k,m) \geq m \cdot \frac{k-1}{k+1}.   $$
		Using all estimates we obtained above, (\ref{t1e2}) becomes
		\begin{align*}
			s(\alpha,\mathbf{Q})&\leq \min_{ \substack{ 3\leq k\leq d+1 \\ p\geq 2 } } \max\Big\{   \frac{\alpha}{k+1} ,~\frac{\Gamma_p^{k-2}(\mathbf{Q})}{2}+\frac{d+2-\alpha}{2p}+\frac{\alpha+2-d}{4} \Big\}    \\
			&=   \min_{ 3\leq k\leq d+1  }  \max\Big\{   \frac{\alpha}{k+1} ,~\min_{  p\geq 2  }\Big\{\frac{\Gamma_p^{k-2}(\mathbf{Q})}{2}+\frac{d+2-\alpha}{2p}+\frac{\alpha+2-d}{4}\Big\} \Big\}  \\
			&\leq   \min \Big\{ \min_{3\leq k\leq \lfloor\frac{d+1}{2}\rfloor+2} \max\Big\{  \frac{\alpha}{k+1} , \frac{2k+\alpha-d-2}{2k} \Big\} ,   \\
			&\quad \quad \quad \quad \quad \quad  \min_{\lfloor\frac{d+1}{2}\rfloor+3\leq k  \leq d} \max\Big\{  \frac{\alpha}{k+1} ,    \frac{k+\alpha-d}{2(k-\lfloor\frac{d+1}{2}\rfloor)}\Big\} , ~   \frac{2\lfloor\frac{d+1}{2}\rfloor+\alpha+2-d}{2(\lfloor\frac{d+1}{2}\rfloor+2)}\Big\}.
		\end{align*}

	\end{proof} 




	\section{The proof of Theorem~\ref{thm:relation_diagram} and additional remarks}\label{appendix:relationships}

    The goal of this section is to present the proof of Theorem~\ref{thm:relation_diagram}, which is quite lengthy: there are so many arrows that we need to justify. So we will split the proof into $12$ subsections. As we have mentioned, not all parts of the proof belong to us, and we will cite references at the proper time along the way when something has already been done in the literature. We also devote one additional subsection to remarks on general higher-codimensional Fourier restriction theory, which can be viewed as a natural extension of the discussions in this section and may inspire future work.

    Without loss of generality, we may always assume $\mathbf{Q}$ is nontrivial, i.e., $\mathfrak{d}_{d,1}(\mathbf{Q}) \geq 1$, throughout this section. Otherwise $S_\mathbf{Q}$ would be degenerate and compressed into a low-dimensional vector space, so Theorem~\ref{thm:relation_diagram} is vacuous.


    \addtocontents{toc}{\protect\setcounter{tocdepth}{0}}

    \subsection{Proof of \texorpdfstring{$\protect\circled{1}$}{①}}\label{subsec:1_proof}\phantom{x}

	``$\Longrightarrow$'' is due to Proposition~2.3 in \cite{mockenhaupt96}, while ``$\Longleftarrow$'' when $n=2$ is essentially due to discussions on page~17 of \cite{mockenhaupt96}. However, when $n \geq 3$, ``$\Longleftarrow$'' is not shown anywhere in the literature. Here we will provide a proof of it by performing a direct computation, part of which is similar to that in the proof of Proposition~2.3 in \cite{mockenhaupt96}. Even so, some annoying issues need to be taken care of to deal with the  ``endpoint'' cases. Therefore, for the reader's convenience as well as for demonstrating the additional difficulties, we begin by first rewriting the proof of ``$\Longrightarrow$'' in \cite{mockenhaupt96} by our notation in a rigorous way.

	By (\ref{eq:tilde_E_pointwise}) at the beginning of the proof of Proposition~\ref{prop:direct_compute}, we have

	\begin{align}\label{eq:tilde_E_Lp}
		\int_{\R^{d+n}} \abs{\widetilde{E}^\mathbf{Q}1(x)}^p dx & = \int_{\R^{d+n}} \abs{(2\pi)^{\frac{d}{2}} \cdot \det(I - i\overline{Q}(x''))^{-\frac{1}{2}} \cdot e^{-{x'}^T\cdot (I - i\overline{Q}(x''))^{-1} \cdot x'/2}}^p dx\nonumber\\
		& \sim \int_{\R^n} \abs{\det(I-i\overline{Q}(x''))}^{-\frac{p}{2}} \int_{\R^d}\abs{e^{-{x'}^T\cdot (I - i\overline{Q}(x''))^{-1} \cdot x'}}^{\frac{p}{2}} dx'dx''.
	\end{align}
	Note that $(I - i\overline{Q}(x''))^{-1} = (I + \overline{Q}(x'')^2)^{-1}(I + i\overline{Q}(x''))$, so we have
	\begin{align*}
		\int_{\R^d}\abs{e^{-{x'}^T\cdot (I - i\overline{Q}(x''))^{-1} \cdot x'}}^{\frac{p}{2}} dx' & = \int_{\R^d}\abs{e^{-{x'}^T\cdot (I + \overline{Q}(x'')^2)^{-1}(I + i\overline{Q}(x'')) \cdot x'}}^{\frac{p}{2}} dx'\\
		& = \int_{\R^d}\abs{e^{-{x'}^T\cdot (I + \overline{Q}(x'')^2)^{-1} \cdot x'}}^{\frac{p}{2}} dx'\\
		& = \det(I + \overline{Q}(x'')^2)^{\frac{1}{2}} \cdot \int_{\R^d}e^{-\frac{p}{2}|x'|^2} dx'\\
		& \sim \det(I + \overline{Q}(x'')^2)^{\frac{1}{2}}.
	\end{align*}
	Besides, for any $A\in \R^{d\times d}$, by $\det(I + A^2) = \det(I+iA)\det(I-iA)$ and $\det(I+iA) = \overline{\det(I-iA)}$, we see that $\det(I + A^2) = \abs{\det(I-iA)}^2$ (always nonnegative). For our purposes, we take $A = \overline{Q}(x'')$. Thus, by plugging these estimates back into (\ref{eq:tilde_E_Lp}), we get
	\begin{align}\label{eq:Lp_identity_moc96}
		\int_{\R^{d+n}} \abs{\widetilde{E}^\mathbf{Q}1(x)}^p dx & \sim \int_{\R^n} \abs{\det(I-i\overline{Q}(x''))}^{-\frac{p}{2}+1} dx'' \nonumber\\
		& \sim \int_{\R^n} \left[\prod_{j=1}^d (1 + |x''||\mu_j(\theta)|)\right]^{-\frac{p}{2} + 1} dx''\nonumber\\
		& = \int_{\mathbb{S}^{n-1}} \int_0^\infty \frac{r^{n-1}}{\left[\prod_{j=1}^d (1 + r|\mu_j(\theta)|)\right]^{\frac{p}{2} - 1}} dr d\sigma(\theta),
    \end{align}
	where in the second line we applied (\ref{eq:det_eigen_express}) with $\theta = x''/|x''|$, and in the last line we used polar coordinates transformation. Recall that we only care about the case when $p > \frac{2(d+n)}{d}$, which means the exponent $\frac{p}{2}-1 > \frac{n}{d} > 0$. As a side remark, the computations we have done so far follow \cite{mockenhaupt96} and will be used in the proofs of both ``$\Longrightarrow$'' and ``$\Longleftarrow$''.

	For ``$\Longrightarrow$'', Mockenhaupt \cite{mockenhaupt96} proceeded by first obtaining a good lower bound for the inner integral in (\ref{eq:Lp_identity_moc96}). Note that 
	$$\prod_{j=1}^d (1 + r|\mu_j(\theta)|)=\gamma_0(\theta) + \gamma_1(\theta) r + \cdots + \gamma_d(\theta) r^d,$$ where each coefficient $\gamma_k(\theta) \geq 0$, and
	$$  \gamma_0(\theta) = 1, \quad \gamma_d(\theta) = \prod_{j=1}^d \abs{\mu_j(\theta)} = \abs{\det(\overline{Q}(\theta))}.    $$
	Since each $\gamma_k(\theta)$ is a polynomial in $\{\abs{\mu_j(\theta)}\}_{j=1}^d$ which is uniformly bounded above by some constant $C_\mathbf{Q}$ (by Corollary~\ref{cor:uniform_spectral}), we know that there exists some constant $M_\mathbf{Q}$ such that $\gamma_k(\theta) \leq M_\mathbf{Q}$, $\forall\, k=1,\dots,d$. Now for each $\theta \in \mathbb{S}^{d-1}$, by considering $r \geq  \widetilde{C}_\mathbf{Q}/\gamma_d(\theta)$ \footnote{We interpret this as $r\geq \infty$ if $\gamma_d(\theta) = 0$, i.e., we simply ignore contribution to (\ref{eq:Lp_identity_moc96}) from such $\theta$'s.} where  $\widetilde{C}_\mathbf{Q} \coloneqq \max\{C_\mathbf{Q}, M_\mathbf{Q}\}$, we have $r \geq \widetilde{C}_\mathbf{Q}/C_\mathbf{Q} \geq 1$, which implies 
	$$   \gamma_d(\theta)r^d \geq \gamma_d(\theta)r \geq \widetilde{C}_\mathbf{Q} \geq C_\mathbf{Q} \geq 1 = \gamma_0(\theta)   $$
	and
	$$  \gamma_d(\theta)r^d \geq M_\mathbf{Q}r^k,\quad \quad \forall~ k = 1,\dots,d-1. $$
	Therefore, we can bound the inner integral in (\ref{eq:Lp_identity_moc96}) as follows: For each fixed $\theta \in \mathbb{S}^{n-1}$, we have
	\begin{align*}
		\int_0^\infty \frac{r^{n-1}}{\left[\prod_{j=1}^d (1 + r|\mu_j(\theta)|)\right]^{\frac{p}{2} - 1}} dr & = \int_0^\infty \frac{r^{n-1}}{(\gamma_0(\theta) + \gamma_1(\theta) r + \cdots + \gamma_d(\theta) r^d)^{\frac{p}{2} - 1}} dr\\
		& \geq \int_0^\infty \frac{r^{n-1}}{(\gamma_0(\theta) + M_\mathbf{Q}r + \cdots + M_\mathbf{Q}r^{d-1} + \gamma_d(\theta) r^d)^{\frac{p}{2} - 1}} dr\\
		& \geq \int_{\frac{\widetilde{C}_\mathbf{Q}}{\gamma_d(\theta)}}^\infty \frac{r^{n-1}}{(\gamma_0(\theta) + M_\mathbf{Q}r + \cdots + M_\mathbf{Q}r^{d-1} + \gamma_d(\theta) r^d)^{\frac{p}{2} - 1}} dr\\
		& \geq \int_{\frac{\widetilde{C}_\mathbf{Q}}{\gamma_d(\theta)}}^\infty \frac{r^{n-1}}{\big((d+1)\gamma_d(\theta) r^d\big)^{\frac{p}{2} - 1}} dr\\
		& \gtrsim \gamma_d(\theta)^{1-\frac{p}{2}} \int_{\frac{\widetilde{C}_\mathbf{Q}}{\gamma_d(\theta)}}^\infty r^{n-1-(\frac{p}{2}-1)d} dr\\
		& \sim_\mathbf{Q} \gamma_d(\theta)^{(\frac{p}{2}-1)(d-1) - n},
	\end{align*}
	where the last line holds due to $n-1-\big(\frac{p}{2}-1\big)d <-1$.
	Plugging this back into (\ref{eq:Lp_identity_moc96}), we get
	\begin{align*}
		\int_{\R^{d+n}} \abs{\widetilde{E}^\mathbf{Q}1(x)}^p dx & \gtrsim_\mathbf{Q} \int_{\mathbb{S}^{n-1}} \gamma_d(\theta)^{(\frac{p}{2}-1)(d-1) - n} d\sigma(\theta)\\
		& = \int_{\mathbb{S}^{n-1}} \abs{\det(\overline{Q}(\theta))}^{(\frac{p}{2}-1)(d-1) - n} d\sigma(\theta).
	\end{align*}
	So $\widetilde{E}^\mathbf{Q}1 \in L^p$ holds for any $p > \frac{2(d+n)}{d}$ will imply that (\ref{eq:CM}) holds for any index $0< \gamma < \frac{d}{n}$, i.e., the (CM) condition holds. And the proof of ``$\Longrightarrow$'' is completed.

	To prove ``$\Longleftarrow$'', our strategy is to bound $\int_{\R^{d+n}} \abs{\widetilde{E}^\mathbf{Q}1(x)}^p dx$ above by something like $\int_{\mathbb{S}^{d-1}} \abs{\det(\overline{Q}(\theta))}^{-\gamma} d\sigma(\theta)$. Our starting point is still (\ref{eq:Lp_identity_moc96}). However, additional difficulties arise. One naive way to proceed is to simply bound the inner integral above by $\int_0^\infty r^{d-1}/(1 + \gamma_d(\theta) r^d)^{\frac{p}{2} - 1}$, where the terms of intermediate degrees in the denominator are thrown away. Unfortunately, after some computation everything comes down to the endpoint (CM) condition (\ref{eq:CM_endpoint}), which is in general stronger than the (CM) condition (\ref{eq:CM}), so we are missing the endpoint case for ``$\Longleftarrow$''. 

	To remedy this defect, when $n=2$, Mockenhaupt \cite{mockenhaupt96} takes advantage of the fact that for any $\theta$ there is at least one nonzero $\mu_j(\theta)$, which ultimately yields an $\epsilon$-gain of the vanishing order of zeros of the one-variable function $\overline{Q}(\theta)$ in $\theta\in\mathbb{S}^1$. A crucial feature that makes his arguments work is that when $n=2$, the (CM) condition is equivalent to a certain condition on the vanishing order of zeros of $\overline{Q}(\theta)$. At first glance, this seems to be an essential barrier to handle cases when $n\geq 3$, as the zero set of $|\det(\overline{Q}(\theta))|$ can be a complicated algebraic variety, and there are no simple criteria in terms of vanishing orders to measure how singular $|\det(\overline{Q}(\theta))|^{-\gamma}$ is around this zero set. However, thanks to the properties of the eigenvalues $\{\mu_j(\theta)\}_{j=1}^d$ established in Section~\ref{sec2}, we are able to extend Mockenhaupt's argument to the $n\geq 3$ case through some modifications.

	The key point here is that we cannot crudely throw away all intermediate terms in the previous naive approach: much more delicate analysis is necessary to handle the endpoint cases. Recall that $\{\Lambda_k(\theta)\}_{k=1}^d$ are $\{|\mu_j(\theta)|\}_{j=1}^d$ in order, and by Corollary~\ref{cor:k_continuity}, they are all continuous functions on $\mathbb{S}^{n-1}$. Also, by Theorem~\ref{thm:U_L_bound_eigen}, Lemma~\ref{lem:alg_char_m}, and the assumption that $\mathfrak{d}_{d,1}(\mathbf{Q}) \geq 1$, we always have
	\begin{equation}\label{asdfgh}
		\Lambda_1(\theta) \sim_\mathbf{Q} 1, \quad \quad \theta \in \mathbb{S}^{n-1}.  
	\end{equation}
	Then for each fixed $\theta\in\mathbb{S}^{n-1}$, we have
	\begin{align*}
		\int_0^\infty \frac{r^{n-1}}{\left[\prod_{j=1}^d (1 + r|\mu_j(\theta)|)\right]^{\frac{p}{2} - 1}} dr & =  \int_0^\infty \frac{r^{n-1}}{\left[\prod_{k=1}^d (1 + r\Lambda_k(\theta))\right]^{\frac{p}{2} - 1}} dr\\
		& = \int_0^\infty \frac{r^{n-1}}{(\gamma_0(\theta) + \gamma_1(\theta) r + \cdots + \gamma_d(\theta) r^d)^{\frac{p}{2} - 1}} dr\\
		& \leq \int_0^\infty \frac{r^{n-1}}{(\gamma_0(\theta) + \gamma_{d-1}(\theta) r^{d-1}  + \gamma_d(\theta) r^d)^{\frac{p}{2} - 1}} dr,
	\end{align*}
	where 
	$$   \gamma_0(\theta) = 1,\quad \gamma_{d-1}(\theta) = \sum_{j=1}^d \prod_{k\neq j}\Lambda_k(\theta),\quad \gamma_d(\theta) = \prod_{k=1}^d \Lambda_k(\theta) = \abs{\det(\overline{Q}(\theta))}.    $$
	As a side remark, without loss of generality, we may always assume $d \geq 2$, which ensures the existence of the $r^{d-1}$ term, as $d=1$ implies $n=1$ and $\mathbf{Q}$ must be a parabola, for which the equivalence $\circled{1}$ trivially holds. By the AM-GM inequality and (\ref{asdfgh}), we have\footnote{Indeed, there is no unique way of doing this, and even choosing to work with the term $\gamma_{d-1}(\theta)$ is not a must. The only important thing is that the profit from $\Lambda_1(\theta)$ is exploited in some sense to gain a little bit of the exponent of $\abs{\det(\overline{Q}(\theta))}$.}
	\begin{align*}
		\gamma_{d-1}(\theta) & \geq \sum_{j=2}^d \prod_{k\neq j}\Lambda_k(\theta)\\
		& \geq (d-1) \left(\prod_{j=2}^d \prod_{k\neq j}\Lambda_k(\theta)\right)^{\frac{1}{d-1}}\\
		& = (d-1)\Lambda_1(\theta)\prod_{k=2}^d \Lambda_k(\theta)^{\frac{d-2}{d-1}}\\
		& \sim_\mathbf{Q} \prod_{k=1}^d \Lambda_k(\theta)^{\frac{d-2}{d-1}}\\
		& = \abs{\det(\overline{Q}(\theta))}^{\frac{d-2}{d-1}},
	\end{align*}
	which implies
	\begin{align*}
		\int_0^\infty \frac{r^{n-1}}{\left[\prod_{j=1}^d (1 + r|\mu_j(\theta)|)\right]^{\frac{p}{2} - 1}} dr & \lesssim_\mathbf{Q} 
		\int_0^\infty \frac{r^{n-1}}{\left(
			1 + \abs{\det(\overline{Q}(\theta))}^{\frac{d-2}{d-1}} r^{d-1}  + \abs{\det(\overline{Q}(\theta))} r^d \right)^{\frac{p}{2} - 1}} dr\\
		& \leq 
		\int_0^\infty \frac{r^{n-1}}{\left(
			1 + \abs{\det(\overline{Q}(\theta))}^{1-\frac{\epsilon}{d-1}} r^{d-\epsilon} \right)^{\frac{p}{2} - 1}} dr,
	\end{align*}
	for any $\epsilon\in (0,1)$. In the second line above, we used a simple fact from calculus that $a + b \geq a^\epsilon b^{1-\epsilon}$ for any $a,b\geq 0$ and $\epsilon\in (0,1)$. Define $r_0$ satisfying
	$$  \abs{\det(\overline{Q}(\theta))}^{1-\frac{\epsilon}{d-1}} r_0^{d-\epsilon} = 1,   $$
	then we can further bound the integral above by
	\begin{align*}
		&\int_0^{r_0} r^{n-1} dr + \abs{\det(\overline{Q}(\theta))}^{-(1-\frac{\epsilon}{d-1})(\frac{p}{2}-1)} \int_{r_0}^\infty r^{n-1-(d-\epsilon)(\frac{p}{2}-1)} dr \\
		\sim\,\, & r_0^n + \abs{\det(\overline{Q}(\theta))}^{-(1-\frac{\epsilon}{d-1})(\frac{p}{2}-1)} r_0^{n-(d-\epsilon)(\frac{p}{2}-1)}\\
		=\,\,& r_0^n = \abs{\det(\overline{Q}(\theta))}^{-\frac{n}{d-\epsilon}(1-\frac{\epsilon}{d-1})},
	\end{align*}
	as long as $\epsilon\in(0,1)$ is taken sufficiently small (depending on $p$) such that $n-1-(d-\epsilon)(\frac{p}{2}-1) < -1$, i.e., $\epsilon < d-n/(\frac{p}{2}-1)$ ($p>\frac{2(d+n)}{d}$ ensures its positivity). 

	Plugging the estimate just obtained back into (\ref{eq:Lp_identity_moc96}), we get
	\begin{align*}
		\int_{\R^{d+n}} \abs{\widetilde{E}^\mathbf{Q}1(x)}^p dx \lesssim_\mathbf{Q} \int_{\mathbb{S}^{n-1}} \abs{\det(\overline{Q}(\theta))}^{-\frac{n}{d-\epsilon}(1-\frac{\epsilon}{d-1})} d\sigma(\theta)
	\end{align*}
	for any $0 < \epsilon < d-n/(\frac{p}{2}-1)$. But note that 
	$$\frac{n}{d-\epsilon}\Big(1-\frac{\epsilon}{d-1}\Big) = \frac{n}{d} - \frac{n\epsilon}{d(d-1)(d-\epsilon)} \in \Big(0,\frac{n}{d}\Big),$$
	so by the (CM) condition the right hand side is finite, and $\widetilde{E}^{\mathbf{Q}}1 \in L^p$ for any $p > \frac{2(d+n)}{d}$. Thus we have proved ``$\Longleftarrow$'' in $\circled{1}$.

	\phantom{x}

    \subsection{Proof of \texorpdfstring{$\protect\circled{2}$}{②}}\label{subsec:2_proof}\phantom{x}



    Note that the best Stein-Tomas in Theorem~\ref{thm:relation_diagram} is formulated in terms of $E^\mathbf{Q}$ instead of $\widetilde{E}^\mathbf{Q}$ or $\widetilde{E}_\varphi^\mathbf{Q}$ (as defined in (\ref{eq:gaussian_integral}) and (\ref{eq:oscillatory_integral})), although the latter two are the most commonly used in the literature of Stein-Tomas-type inequalities. However, by Proposition~\ref{prop:restriction_equiv}, estimates for all these versions of Fourier extension operators are indeed equivalent to each other. This allows us to cite results in the literature without worrying about compatibility.

	For the proof of 
	$\circled{2}$, ``$\Longrightarrow$'' is due to Corollary~2.12 in \cite{mockenhaupt96}. Moreover, Theorem~2.11 in \cite{mockenhaupt96} also shows that the endpoint (CM) condition implies the endpoint best Stein-Tomas-type  inequality (i.e., $L^2\rightarrow L^{\frac{2(d+2n)}{d}}$). The main technique is complex interpolation of analytic family of operators. As a side remark, in Conjecture~4.1.2 in \cite{banner02}, it is conjectured that the (CM) condition together with the assumption that $n < d$ implies the endpoint best Stein-Tomas-type  inequality. By Theorem~2.14 in \cite{mockenhaupt96}, this conjecture is true when $n=2$.

	As for the reverse implication ``$\Longleftarrow$'', when $n=2$, Proposition~3.1 in \cite{christ82} proved\footnote{Although the statement of the proposition itself only says that the best ``endpoint'' Stein-Tomas-type inequality (i.e., $L^2 \rightarrow L^{\frac{2(d+4)}{d}}$) implies the (CM) condition, which requires slightly stronger assumption, its proof actually works well enough to provide what we want. As a side remark, something more general is proved: There is no need to confine ourselves to quadratic forms, and the result actually holds for any smooth manifolds. In this setting, by using Hessian matrices, the (CM) condition can also be defined in a similar way as in Definition~\ref{def:CM}.} that the best Stein-Tomas-type 
	inequality (i.e., $L^2 \rightarrow L^{\frac{2(d+4)}{d}+}$) implies the (CM) condition. The approach is based on deriving certain local ``normal forms'' for manifolds, followed by a Knapp-type infinitesimal homogeneity argument. Proving the existence of the normal forms (Proposition~3.2 in \cite{christ82}) is not an easy job and requires heavy manipulation of change of coordinates. There are other ways of proving ``$\Longleftarrow$'' when $n=2$. As we will soon see, $\circled{6}$ combined with ``$\Longleftarrow$'' of $\circled{7}$ when $n=2$ provides an alternative proof (although still not easy, see explanations in the $\circled{7}$ part later on), which relies on geometric invariant theory.

	However, when $n \geq 3$, ``$\Longleftarrow$'' is not true in general, even if we strengthen our assumption to endpoint best Stein-Tomas-type inequalities. Here we provide several counterexamples:
	\begin{itemize}
		\item When $d=5$ and $n=3$, 
		$$\mathbf{Q}(\xi) = (\xi_1^2 + \xi_3^2 + \xi_5^2, 2(\xi_1\xi_2 + \xi_3\xi_4), \xi_2^2 + \xi_4^2 +\xi_5^2)$$ 
		satisfies the endpoint best Stein-Tomas-type inequality, see Theorem~2.18 in \cite{mockenhaupt96} for the proof. However, it does not satisfy the (CM) condition, because Example~2.10 in \cite{mockenhaupt96} tells us that 
		$$\int_{\mathbb{S}^{2}}  |\det(\overline{Q}(\theta))|^{-\gamma}d\sigma(\theta) = \infty, \quad \quad \forall ~\gamma \geq \frac{1}{2},$$
		while for the (CM) condition to hold we need 
		$$\int_{\mathbb{S}^{2}}  |\det(\overline{Q}(\theta))|^{-\gamma}d\sigma(\theta) < \infty , \quad \quad \forall~\gamma < \frac{3}{5}.$$
		Another way to see the failure of the (CM) condition is through the equivalence in $\circled{1}$: Theorem~2.18 in \cite{mockenhaupt96} also tells us that $\widetilde{E}^\mathbf{Q}1 \not\in L^p$ whenever $p \leq \frac{10}{3}$, while for the (CM) condition to hold we need $\widetilde{E}^\mathbf{Q}1 \in L^p$ for all $p > \frac{16}{5}$.

		\item When $d=2$ and $n=3$, 
		$$\mathbf{Q}(\xi) = (\xi_1^2, 2\xi_1\xi_2, \xi_2^2)$$ 
		satisfies the endpoint best Stein-Tomas-type inequality, see Proposition~16.2 in \cite{christ82} or Theorem~2.15 in \cite{mockenhaupt96} for the proof. However, it does not satisfy the (CM) condition, because  
		$$\int_{\mathbb{S}^{2}}  |\det(\overline{Q}(\theta))|^{-\gamma}d\sigma(\theta) = \int_{\mathbb{S}^{2}}  |4(\theta_1\theta_3-\theta_2^2)|^{-\gamma}d\sigma(\theta) = \infty,\quad \quad \forall~\gamma \geq 1,$$
		while for the (CM) condition to hold we need 
		$$\int_{\mathbb{S}^{2}}  |\det(\overline{Q}(\theta))|^{-\gamma}d\sigma(\theta) < \infty, \quad \quad \forall~\gamma < \frac{3}{2}.$$
		Another way to see the failure of the (CM) condition is through the equivalence in $\circled{1}$: Theorem~2.15 in \cite{mockenhaupt96} also tells us that $\widetilde{E}^\mathbf{Q}1 \in L^p$ if and only if $p > 6$, while for the (CM) condition to hold we need $\widetilde{E}^\mathbf{Q}1 \in L^p$ if and only if $p > 5$.

		\item When $d=3$ and $n=5$, 
		$$\mathbf{Q}(\xi) = (2\xi_1\xi_2, 2\xi_1\xi_3, 2\xi_2\xi_3, \xi_2^2 - \xi_1^2, \xi_3^2 - \xi_1^2)$$ 
		satisfies the endpoint best Stein-Tomas-type inequality, see Proposition~6.1.2 in \cite{banner02} for the proof. However, it does not satisfy the (CM) condition, because in the proof of Proposition~6.1.2 in \cite{banner02} it is also shown that $\{\theta\in\mathbb{S}^4 : \overline{Q}(\theta)=0\}$ is a smooth submanifold of codimension one in $\mathbb{S}^4$, which implies 
		$$\int_{\mathbb{S}^{4}}  |\det(\overline{Q}(\theta))|^{-\gamma}d\sigma(\theta) = \infty,\quad \quad \forall~\gamma \geq 1,$$
		while for the (CM) condition to hold we need 
		$$\int_{\mathbb{S}^{4}}  |\det(\overline{Q}(\theta))|^{-\gamma}d\sigma(\theta) < \infty,\quad \quad \forall~\gamma < \frac{5}{3}.$$
		One may consult Corollary~2.6 in \cite{mockenhaupt96} for  more general discussions in this spirit.
	\end{itemize}

	\phantom{x}

    \subsection{Proof of \texorpdfstring{$\protect\circled{3}$}{③}}\label{subsec:3_proof}\phantom{x}

	By the definition of good manifolds, in what follows we always restrict ourselves to diagonal forms $\mathbf{Q}(\xi) = (a_1\xi_1^2 + \cdots + a_d\xi_d^2,b_1\xi_1^2 + \cdots + b_d\xi_d^2)$ of codimension $2$. When $d=2$, the ``$\Longrightarrow$'' is actually ``$\Longleftrightarrow$'', because in this case the only good manifold is $\mathbf{Q} \equiv (\xi_1^2, \xi_2^2)$, and so is the only strongly nondegenerate diagonal form.

	For any even $d \geq 4$, we claim that ``$\Longrightarrow$'' holds, while ``$\Longleftarrow$'' is not true in general. To verify that a good manifold $\mathbf{Q}$ is strongly nondegenerate, we need to check that $\mathfrak{d}_{d-m,n'}(\mathbf{Q}) \geq \frac{n'}{2}d - m$ for every $m$ with $0\leq m \leq d$ and every $n'$ with $0 \leq n' \leq 2$. The case $n'=0$ is trivial by noting $\mathfrak{d}_{d-m,0}(\mathbf{Q}) = 0$. If $n'=1$, since $\mathfrak{d}_{d-m,n'}(\mathbf{Q}) \geq 0$, without loss of generality we may assume $0 \leq m < \frac{d}{2}$, which implies $m \leq \frac{d}{2} - 1$ (note that $\frac{d}{2} \in \N^+$ for even $d$). By Lemma~5.1 in \cite{ggo23}, we have $\mathfrak{d}_{d-m,1}(\mathbf{Q}) \geq d-2m-1$, which is further bounded below by $\frac{d}{2}-m$, as $m \leq \frac{d}{2} - 1$. If $n'=2$, then by Lemma~5.1 in \cite{ggo23}, we directly have $\mathfrak{d}_{d-m,2}(\mathbf{Q}) \geq d-m$ for all $0\leq m \leq d$, as desired. Therefore, ``$\Longrightarrow$'' holds.

	To show that ``$\Longleftarrow$'' is not true in general, one may consider 
	$$\mathbf{Q}(\xi) = (\xi_1^2 + \cdots + \xi_{\frac{d}{2}}^2, \xi_{\frac{d}{2}+1}^2 + \cdots + \xi_d^2),$$
	which is clearly not good. To check strongly nondegeneracy, similarly to the discussions in the last paragraph, it suffices to show $\mathfrak{d}_{d-m,1}(\mathbf{Q}) \geq \frac{d}{2} - m$ and $\mathfrak{d}_{d-m,2}(\mathbf{Q}) \geq d-m$ for every $m$ with $0\leq m \leq d$. For the former, observe that 
	\begin{equation}\label{123321123321}
		\mathfrak{d}_{d-m,1}(\mathbf{Q}) = \inf_{\theta = (s,t)\in \mathbb{S}^1} \mathfrak{d}_{d-m,1}(\overline{Q}(\theta)),   
	\end{equation}
	where 
	$$\overline{Q}(\theta) = s(\xi_1^2 + \cdots + \xi_{\frac{d}{2}}^2) + t(\xi_{\frac{d}{2}+1}^2 + \cdots + \xi_d^2).$$
	If $s=0$ or $t=0$, then it is easy to see that $\mathfrak{d}_{d-m,1}(\overline{Q}(\theta)) \geq \frac{d}{2} - m$ (much similar to the paraboloid case in Corollary~\ref{cor1}), as desired. So it remains to consider the case when $s\neq 0$ and $t\neq 0$. If $s$ and $t$ have the same sign, then $\overline{Q}(\theta) \equiv \xi_1^2 + \cdots + \xi_d^2$, which by the paraboloid case in Corollary~\ref{cor1} satisfies $\mathfrak{d}_{d-m,1}(\overline{Q}(\theta)) \geq d-m > \frac{d}{2}-m$. If $s$ and $t$ have different signs, then by the hyperbolic paraboloid case in Corollary~\ref{cor2} (with $m=\frac{d}{2}$), we have $\mathfrak{d}_{d-m,1}(\overline{Q}(\theta)) = d-2m \geq \frac{d}{2}-m$ (note that without loss of generality we may assume $0\leq m\leq \frac{d}{2}$), as desired. Thus in any case we have verified $\mathfrak{d}_{d-m,1}(\mathbf{Q}) \geq \frac{d}{2}-m$. For the latter, observe that the proof of Lemma~5.1 in \cite{ggo23} carries through without any modification. To be more precise, suppose to the contrary $\mathfrak{d}_{d-m,2}(\mathbf{Q}) < d-m$, then they showed that there exists a nonzero vector $\vec{w} = (w_1,\dots,w_d)\in\R^d$ such that $\sum_{i=1}^d a_i (w_i)^2=0$ and $\sum_{i=1}^d b_i (w_i)^2=0$, where $a_i$'s and $b_i$'s are the coefficients in the diagonal form. But in our case this is exactly 
	$$\sum_{i=1}^{\frac{d}{2}} (w_i)^2=0, \quad \sum_{\frac{d}{2}+1}^d (w_i)^2=0,$$
	which implies $\vec{w}=0$, a contradiction. So the proof of strongly nondegeneracy is completed.

	For any odd $d \geq 3$, we claim that ``$\Longrightarrow$'' is not true in general, while ``$\Longleftarrow$'' is vacuous. To see that ``$\Longrightarrow$'' fails in general, one may consider 
	$$\mathbf{Q}(\xi) = \Big(\sum_{i=1}^d \xi_i^2, \sum_{i=1}^{\frac{d-1}{2}} i \xi_i^2 - \sum_{i=\frac{d+3}{2}}^{d} (d + 1 - i) \xi_{i}^2\Big).$$
	Note that the coefficient matrix of this $\mathbf{Q}$ is
	\begin{align*}
		\begin{pmatrix}
			a_1 & \cdots & a_d\\
			b_1 & \cdots & b_d
		\end{pmatrix}
		=
		\begin{pmatrix}
			1 & \cdots & 1 & 1 & 1 & \cdots & 1\\
			1 & \cdots & \frac{d-1}{2} & 0 & -\frac{d-1}{2} & \cdots & -1
		\end{pmatrix},
	\end{align*}
	we easily see that it is good. But by considering (\ref{123321123321}) with $m=\frac{d-1}{2}$, we have $$\mathfrak{d}_{\frac{d+1}{2},1}(\mathbf{Q}) \leq \mathfrak{d}_{\frac{d+1}{2},1}(\overline{Q}((0,1))) = \mathfrak{d}_{\frac{d+1}{2},1} \Big(\sum_{i=1}^{\frac{d-1}{2}} i \xi_i^2 - \sum_{i=\frac{d+3}{2}}^{d} (d + 1 - i) \xi_{i}^2 \Big) =0,$$
	which is much similar to the hyperbolic paraboloid case in Corollary~\ref{cor2}. So $\mathfrak{d}_{\frac{d+1}{2},1}(\mathbf{Q}) \geq \frac{1}{2}$ does not hold, and $\mathbf{Q}$ is not strongly nondegenerate.

	To show that ``$\Longleftarrow$'' is vacuous, we only need to prove:
	\begin{proposition}\label{prop:diag_not_str}
		For any odd $d\geq 3$, all diagonal forms $\mathbf{Q}(\xi) = (Q_1(\xi),Q_2(\xi)) \coloneqq (a_1\xi_1^2 + \cdots + a_d\xi_d^2,b_1\xi_1^2 + \cdots + b_d\xi_d^2)$ cannot be strongly nondegenerate.
	\end{proposition}
	\begin{proof}
		The key idea of the proof is to find a linear combination of $Q_1$ and $Q_2$ that is the most degenerate by tracing the signs of the coefficients. Firstly, as $\mathbf{Q}$ does not omit any variables, by perturbing $Q_1$ using $Q_2$, we may without loss of generality assume that $a_i\neq 0$ for any $1\leq i \leq d$. Let $n_+$ and $n_-$ be the numbers of positive and negative numbers in $\{a_i\}_{i=1}^d$ respectively, then $n_+ + n_- =d$. Also, note that $d$ is odd implies $n_+ \neq n_-$, so we may further assume that $n_+ > n_-$ (otherwise we replace $Q_1$ with $-Q_1$). Next, let $n_+(\lambda)$, $n_-(\lambda)$, and $n_0(\lambda)$ be the numbers of positive, negative, and zero numbers in $\{b_i+\lambda a_i\}_{i=1}^d$ (the coefficients of $Q_2 + \lambda Q_1$), respectively. Note that for $\lambda \gg 1$, the signature status of $\{b_i+\lambda a_i\}_{i=1}^d$ is the same as that of $\{a_i\}_{i=1}^d$, which means 
		$$   n_+(\lambda_L) = n_+, \quad n_-(\lambda_L) = n_-, \quad  n_0(\lambda_L)=0   $$
		for some large $\lambda_L$. Similarly, for $\lambda \ll -1$, the signature status of $\{b_i+\lambda a_i\}_{i=1}^d$ is the opposite of that of $\{a_i\}_{i=1}^d$, which means 
		$$  n_+(\lambda_S) = n_-, \quad   n_-(\lambda_S) = n_+, \quad n_0(\lambda_S)=0 $$
		for some small $\lambda_S$. 

		Roughly speaking, our goal is to find some $\lambda \in [\lambda_S,\lambda_L]$ such that $|n_+ - n_-|$ is as small as possible, which is believed to be the most degenerate scenario. To achieve this, observe that there can be at most finitely many $\lambda \in [\lambda_S,\lambda_L]$ such that $n_0(\lambda) > 0$, because any such $\lambda$ must be one of $\{-b_i/a_i\}_{i=1}^d$. Besides, by the intermediate value principle, for any subinterval $[\lambda_s,\lambda_l] \subset [\lambda_S,\lambda_L]$ satisfying $n_+(\lambda_s) \neq n_+(\lambda_l)$ or $n_-(\lambda_s) \neq n_-(\lambda_l)$, there must be at least one $\lambda \in [\lambda_s,\lambda_l]$ such that $n_0(\lambda) > 0$. In particular, recall that 
		$$  n_+(\lambda_S) = n_- < n_+ = n_+(\lambda_L), \quad  n_-(\lambda_S) = n_+ > n_- =  n_-(\lambda_L),   $$
		thus by taking $[\lambda_s,\lambda_l] = [\lambda_S,\lambda_L]$, there must be at least one $\lambda \in [\lambda_S,\lambda_L]$ such that $n_0(\lambda) > 0$. By our assumption that $n_0(\lambda_S) = n_0(\lambda_L)=0$, all such $\lambda$'s cannot be equal to $\lambda_S$ and $\lambda_L$, and so we can arrange them in order as 
		$$  (\lambda_0 \eqqcolon \lambda_S <) \, \lambda_1 < \cdots < \lambda_k \, (< \lambda_L \coloneqq \lambda_{k+1})   $$
		for some $k\in\N^+$. Note that for any $j = 0, \dots, k$, we have $n_0(\lambda) \equiv 0$ over $(\lambda_j, \lambda_{j+1})$, so applying our previous arguments to any subinterval $[\lambda_s,\lambda_l] \subset (\lambda_j, \lambda_{j+1})$ yields $n_+(\lambda_s) = n_+(\lambda_l)$ and $n_-(\lambda_s) = n_-(\lambda_l)$. In other words, on each $(\lambda_j,\lambda_{j+1})$ ($j=0,\dots, k$), not only $n_0(\lambda) \equiv0$, but also both $n_+(\lambda)$ and $n_-(\lambda)$ are constant, so we may define $n_{j,+}$ and $n_{j,-}$ to be these constant values of $n_+(\lambda)$ and $n_-(\lambda)$, respectively. Note that for each $j = 0,\dots,k$, $n_{j,+} + n_{j,-} = d$ with $d$ odd, so we have either $n_{j,+} > n_{j,-}$ or $n_{j,+} < n_{j,-}$. However, as $n_0(\lambda_S) = n_0(\lambda_L)=0$, by continuity at the two extreme endpoints $\lambda_S$ and $\lambda_L$, we know that 
		$$   n_{0,+} = n_+(\lambda_S) = n_-, \quad n_{0,-} = n_-(\lambda_S) = n_+,    $$
		$$   n_{k,+} = n_+(\lambda_L) = n_+, \quad  n_{k,-} = n_-(\lambda_L) = n_- ,$$
		which by $n_+>n_-$ implies 
		$$  n_{0,+} < n_{0,-},\quad n_{k,+} > n_{k,-}.  $$
		Therefore, by the intermediate value principle again, there must exist some $j_0 \in \{1,\dots,k+1\}$ such that 
		$$  n_{j_0-1,+} < n_{j_0-1,-}, \quad  n_{j_0,+} > n_{j_0,-}. $$
		Then $\lambda = \lambda_{j_0} \in [\lambda_S,\lambda_L]$ is the critical moment at which $Q_2 + \lambda Q_1$ is expected to be the most degenerate. In what follows we will show that this indeed forces 
		$$   \mathfrak{d}_{d-m,1}(Q_2 + \lambda_{j_0} Q_1) < \frac{d}{2} - m $$
		for some $0\leq m\leq d$, and thus $\mathfrak{d}_{d-m,1}(\mathbf{Q}) < \frac{d}{2} - m$ by definition, which implies that $\mathbf{Q}$ cannot be strongly nondegenerate as desired.

		For convenience, let $\widetilde{Q} \coloneqq Q_2 + \lambda_{j_0} Q_1$. By the definition of $\lambda_{j_0}$, we have $n_0(\lambda_{j_0}) > 0$. Also, without loss of generality, we may assume that $n_+(\lambda_{j_0}) \leq n_-(\lambda_{j_0})$ (the other case when $n_+(\lambda_{j_0}) \geq n_-(\lambda_{j_0})$ can be dealt with in a completely symmetric way). When $\lambda$ goes down from slightly above $\lambda_{j_0}$ to touching $\lambda_{j_0}$, each of $\{b_i+\lambda a_i\}_{i=1}^d$ varies monotonically, and we wish to track how their behavior on $\lambda_{j_0}$ is related to that slightly above $\lambda_{j_0}$. Define 
		$$ u \coloneqq \#\{1 \leq i \leq d: b_i+\lambda_{j_0} a_i = 0, a_i > 0\}   $$
		and 
		$$   v \coloneqq \#\{1 \leq i \leq d: b_i+\lambda_{j_0} a_i = 0, a_i < 0\} .$$
		As $a_i \neq 0$ for any $1\leq i \leq d$, we have $u+v = n_0(\lambda_{j_0})$, which further implies $n_+(\lambda_{j_0}) + n_-(\lambda_{j_0}) + u + v = d$. Moreover, it is not hard to observe that $n_+(\lambda_{j_0}) + u = n_{j_0,+}$ and $n_-(\lambda_{j_0}) + v = n_{j_0,-}$, which implies $n_+(\lambda_{j_0}) + u > n_-(\lambda_{j_0}) + v$ as $n_{j_0,+} > n_{j_0,-}$.  Therefore, we can summarize all the relations between the parameters as follows:
		\[
		\begin{cases}
			0 \leq n_-(\lambda_{j_0}) - n_+(\lambda_{j_0}) \leq u-v-1,\\
			n_-(\lambda_{j_0}) + n_+(\lambda_{j_0}) = d-u-v.
		\end{cases}
		\]
		Thus 
		$$n_+(\lambda_{j_0}) \geq \frac{(d-u-v) - (u-v-1)}{2} = \frac{d+1}{2} - u.$$ 

		We claim $\mathfrak{d}_{\frac{d+1}{2},1}(\widetilde{Q}) = 0$. First assume $u\leq \frac{d+1}{2}$. Then there are at least $\frac{d+1}{2} - u$ disjoint pairs of positive and negative coefficient numbers in $\{b_i+\lambda_{j_0}a_i\}_{i=1}^d$, which implies 
		$$  \mathfrak{d}_{d-(\frac{d+1}{2} - u), 1}(\widetilde{Q}) \leq (d-u-v) - 2\Big(\frac{d+1}{2} - u\Big)= u - v - 1, $$ much similar to the hyperbolic paraboloid case in Corollary~\ref{cor2}. Thus we have 
		$$\mathfrak{d}_{\frac{d+1}{2},1}(\widetilde{Q}) \leq \max\Big\{0, \mathfrak{d}_{\frac{d-1}{2}+u,1}(\widetilde{Q}) - (u-1)\Big\} \leq \max\{0,-v\} = 0.$$
		It remains to consider $u > \frac{d+1}{2}$. In this case, $n_0(\lambda_{j_0}) \geq u \geq \frac{d+3}{2}$ ($d$ odd), which implies 
		$$\mathfrak{d}_{d,1}(\widetilde{Q}) \leq d - \frac{d+3}{2} = \frac{d-3}{2}.$$
		Thus we have 
		$$\mathfrak{d}_{\frac{d+1}{2},1}(\widetilde{Q}) \leq \max\Big\{0,\mathfrak{d}_{d,1}(\widetilde{Q}) - \frac{d-1}{2}\Big\} = 0.$$ 
		Therefore, in any case, we get $\mathfrak{d}_{\frac{d+1}{2},1}(\widetilde{Q}) = 0$, and so $\mathfrak{d}_{\frac{d+1}{2},1}(\mathbf{Q}) = 0$. However, for $\mathbf{Q}$ to be strongly nondegenerate, we need $\mathfrak{d}_{\frac{d+1}{2},1}(\mathbf{Q}) \geq \frac{1}{2}$. So the proof is completed.
	\end{proof}

	\begin{remark}\label{rmk:d_even_partial}
		In fact, via a similar strategy, we can show that $\mathfrak{d}_{\frac{d}{2},1}(\mathbf{Q}) = 0$ when $d$ is even. When we run the proof of Proposition~{\rm\ref{prop:diag_not_str}} for $n$ even, the major problem is that we do not necessarily have $n_+ \neq n_-$ at the beginning. However, if $n_+ = n_-$, then by $n_+ + n_- = d$, we have $n_+ = n_- = \frac{d}{2}$, which immediately implies $\mathfrak{d}_{\frac{d}{2},1}(\mathbf{Q}) = 0$. Therefore, we may always assume $n_+ \neq n_-$. Similarly, in the process of locating $\lambda_0$ by the intermediate value principle, we can always assume $n_{j,+} \neq n_{j,-}$, and all arguments carry through. The only difference is the computation at the final stage. Since $d$ is even, we have $n_+(\lambda_{j_0}) \geq \frac{d+2}{2} - u$, which implies 
		$$  \mathfrak{d}_{d-(\frac{d+2}{2} - u), 1}(\widetilde{Q}) \leq (d-u-v) - 2\Big(\frac{d+2}{2} - u\Big)= u - v - 2.   $$
		Thus we have 
		$$\mathfrak{d}_{\frac{d}{2},1}(\widetilde{Q}) \leq \max\Big\{0, \mathfrak{d}_{\frac{d-2}{2}+u,1}(\widetilde{Q}) - (u-1)\Big\} \leq \max\{0,-v-1\} = 0.$$
		It remains to consider $u > \frac{d+2}{2}$. In this case, $n_0(\lambda_{j_0}) \geq u \geq \frac{d+4}{2}$ {\rm(}$d$ even{\rm)}, which implies 
		$$\mathfrak{d}_{d,1}(\widetilde{Q}) \leq d - \frac{d+4}{2} = \frac{d-4}{2}.$$
		Thus we have 
		$$\mathfrak{d}_{\frac{d}{2},1}(\widetilde{Q}) \leq \max\Big\{0,\mathfrak{d}_{d,1}(\widetilde{Q}) - \frac{d}{2}\Big\} = 0.$$ 
		Therefore, in any case, we get $\mathfrak{d}_{\frac{d}{2},1}(\widetilde{Q}) = 0$, and so $\mathfrak{d}_{\frac{d}{2},1}(\mathbf{Q}) = 0$ as desired.
	\end{remark}

