Extending this analysis to an n-linked pendulum on a cart (n+1 DOF) the general equations of motion are obtained:

\begin{equation}
    \dot{\mathbf{X}} = A_{n\times n} \textbf{X}_{n \times1} + B_{n\times m}\textbf{U}_{m \times 1}
\end{equation}
\begin{equation}
    \textbf{Y}_{p \times 1} = C_{p \times n} \textbf{U}_{n \times 1}
\end{equation}

The equations of motion for a n-linked pole on a cart has the following form,
\begin{equation}\label{GenEOM}
A\ddot{\mathbf{X}} = B + C 
\end{equation}
% (\sum_{i=1}^{n} m_i)l_1 & (\sum_{i=2}^{n} m_i)l_2 cos(\theta_1 - \theta_2) &  \dots 

where \\
\begin{align}
&A=\\
&\begin{bmatrix}
\sum_{i=1}^{n} m_i + M  & (\sum_{i=1}^{n} m_i) l_1 cos(\theta_1) & \dots &  m_n l_n cos(\theta_n)  \\
\\
(\sum_{i=1}^{n} m_i) cos(\theta_1) & \ddots & &  \\
%\vdots & \ddots & & \\
\vdots & & [a_{ij}] &\\
m_ncos(\theta_n) & & & \ddots \\
\end{bmatrix} 
\end{align}
\vspace{2mm}

where
\begin{equation}
a_{ij} = [\sum_{k=max(i,j)}^{n} m_k] l_j  cos(\theta_i - \theta_j)
\end{equation}
\begin{equation}
B = 
\begin{bmatrix}
\sum_{j=1}^{n} [(\sum_{i=j}^{n} m_i) l_j sin(\theta_j)(\dot{\theta_j})^2]  \\
\\
- \sum_{k=1}^{n} [(\sum_{j=max(1,k)}^{n} m_j) l_k (\dot{\theta_k})^2 sin(\theta_i - \theta_k)]\\
\vdots \\
\\
-m_n\sum_{k=1}^{n} [ l_k (\dot{\theta_k})^2 sin(\theta_i - \theta_k)]\\
\end{bmatrix}
\end{equation}

\begin{equation}
C =
\begin{bmatrix}
u \\
(\sum_{k=1}^{n} m_k) g sin(\theta_i)\\
\vdots\\
m_n g sin(\theta_n)\\
\end{bmatrix}
\end{equation}

Linearizing this model for small angles, the general equations of motion are derived:

\begin{equation}\label{GenLinEOM}
A_l \ddot{\mathbf{X}} = C_l
\end{equation}

where
\begin{equation}
A_l=
\begin{bmatrix}
\sum_{i=1}^{n} m_i + M  & (\sum_{i=1}^{n} m_i) l_1  & \dots &  m_n l_n  \\
\\
(\sum_{i=1}^{n} m_i)  & \ddots & &  \\
%\vdots & \ddots & & \\
\vdots & & [a_{l_{ij}}] &\\
m_n & & & \ddots \\
\end{bmatrix} 
\end{equation}
\vspace{2mm}

where
\begin{equation}
a_{l_{ij}} = [\sum_{k=max(i,j)}^{n} m_k] l_j 
\end{equation}
\begin{equation}
C =
\begin{bmatrix}
u \\
(\sum_{k=1}^{n} m_k) g \theta_i\\
\vdots\\
m_n g \theta_n\\
\end{bmatrix}
\end{equation}

