\section*{\textcolor{black}{Supplementary materials}}\label{sec7}

\subsection{Control Performance Metrics}
This section describes the metrics of control studied in this work.
\begin{itemize}

  \item \textbf{Rise Time} (\(t_r\)):\\
  The time required for the system response to rise from 10\% to 90\% of its final steady-state value.
  \[
  t_r = t_{90\%} - t_{10\%}
  \]

  \item \textbf{Peak Overshoot} (\(M_p\)):\\
  The maximum overshoot relative to the steady-state value, expressed as a percentage.
  \[
  M_p = \left( \frac{y_{\text{peak}} - y_\infty}{y_\infty} \right) \times 100\%
  \]

  \item \textbf{Settling Time} (\(t_s\)):\\
  The time required for the output to remain within a specified tolerance band (typically \(\pm2\%\) or \(\pm5\%\)) around the steady-state value.
  \[
  t_s = \text{time when } |y(t) - y_\infty| < \epsilon \text{ for all } t \ge t_s
  \]

  \item \textbf{Steady-State Error} (\(e_{ss}\)):\\
  The difference between the desired output and the actual output as time approaches infinity.
  \[
  e_{ss} = \lim_{t \to \infty} |r(t) - y(t)|
  \]

  \item \textbf{Integral of Absolute Error (IAE)}:\\
  Measures the total absolute error over time.
  \[
  \text{IAE} = \int_0^\infty |e(t)| \, dt
  \]

  \item \textbf{Integral of Time-weighted Absolute Error (ITAE)}:\\
  Penalizes errors that persist over time by weighting them with time.
  \[
  \text{ITAE} = \int_0^\infty t \cdot |e(t)| \, dt
  \]

  \item \textbf{Integral of Squared Control (ISU)}:\\
    Measures the total squared control effort applied over time. Useful in penalizing aggressive control inputs.
    \[
    \text{ISC} = \int_0^\infty u^2(t) \, dt
    \]


\end{itemize}


\subsection{Simulation Performance Metrics}
This section includes the metrics of simulation performance studied in this work.
\begin{itemize}

  \item \textbf{Sim Time}:\\
  The total simulated duration of the model or system, typically measured in seconds.\\
  Example: Simulating 10 seconds of robot behavior.

  \item \textbf{Wall Time}:\\
  The actual elapsed (real-world) time required to run the simulation on a computer.\\
  Example: A 10s simulation takes 20s of wall time.

  \item \textbf{Real-Time Factor (RTF)}:\\
  The ratio of simulated time to wall-clock time. Indicates simulation speed relative to real time.
  \[
  \text{RTF} = \frac{\text{Sim Time}}{\text{Wall Time}}
  \]
  - \( \text{RTF} > 1 \): faster than real-time  
  - \( \text{RTF} < 1 \): slower than real-time

  \item \textbf{Max Memory RSS (Resident Set Size)}:\\
  The maximum amount of physical RAM occupied by the simulation process during its execution, including code, data, and shared libraries.\\
  Typically measured in mebibytes (MiB) or gibibytes (GiB).

  \item \textbf{Peak Allocated Memory}:\\
  The highest amount of memory dynamically allocated by the simulation, excluding shared libraries or OS overhead.\\
  This is often reported by memory profilers.

  \item \textbf{Estimated CPU Energy}:\\
  An estimate of the total CPU energy consumed during simulation, often measured in joules (J) or watt-hours (Wh).\\ It is measured using the following formula:\\
  \(
  Energy\,(J) = Wall\,Time\,(s) \times CPU\,Utilization \times TDP\,(W)
 \)
  , where TDP stands for the Thermal Design Power of the CPU.
  Useful for evaluating power efficiency, especially on embedded or neuromorphic systems.

\end{itemize}

\subsection{Neuromorphic Performance Metrics}
This section includes the metrics of neuromorphic performance studied in this work.
\begin{itemize}
  \item \textbf{Spikes per neuron}:\\
   This metric shows the average number of spikes emitted by each neuron in the network/ensemble during the simulation.
   \item \textbf{Core Utilization}:\\
   This metric demonstrates the percentage of each neuromorphic core on average, utilized during building the spiking neural network model on a neuromorphic chip.
   \item \textbf{Experimental Area on Chip}:\\
   This is the experimentally determined chip area allocated to the spiking neural network during simulation. It is measured using the following formula:\\
   \(Expt\,Area \, (mm^2) = Area\,per\,Core\,(mm^2) \times \%\, per\,Core \times Number\,of\,Cores\)
   \item \textbf{Theoretical Area on Chip}: \\
   This is the area on chip allocated to the spiking neural network, theoretically calculated using the datasheet for the chip using the formula: \\
   \(Theo\,Area \, (mm^2) = \frac{Number\,of\,neurons\,in\,the\,network}{Neuron\,density\,(mm^{-2})}\)
   \item \textbf{Estimated Energy}:\\
   This is an estimate of the energy consumed by the board (excluding the idle power consumption required to keep the board ON), calculated using the following formula:\\
   \(Energy\,(J/inf)=Energy/synaptic\,op\times synaptic\,ops/inf\,(J/inf)\, + \, Energy/neuron\,update\times neuron\,updates/inf\,(J/inf)\)

\end{itemize}


