\section{Appendix I: Transmission in a phosphorene pn junction}

In \fig{10} we show the transmission in a phosphorene pn junction as a function of the electrostatic potential. The figure proves, in the same way as \fig{8} for FLBP, that anti-super-Klein tunneling is observed for a current flow in the $y$ direction (armchair direction), if the electrons go from the conduction to the valence band (or vice versa) at the interface of the pn junction.

\section{Appendix II: Calculating the energy bands of FLBP}

After performing a plane-wave ansatz, the few-layer black phosphorous Hamiltonian in \eq{1} can be written in the form \cite{Sousa2017}
\begin{equation}
    H(\vec{k}) = \left(\begin{array}{c c c c c}
        H_\textrm{1L}(\vec{k}) & C(\vec{k}) & 0 & 0 & 0  \\
         C^\dagger (\vec{k}) & H_\textrm{1L}(\vec{k}) & C(\vec{k}) & \cdot & \cdot\\
         \cdot & C^\dagger(\vec{k}) & \cdot & \cdot & \cdot \\
         \cdot & \cdot & \cdot & \cdot & C(\vec{k}) \\
         0 & 0 & 0 & C^\dagger(\vec{k}) & H_\textrm{1L}(\vec{k})
    \end{array}\right)
    \label{eq:Hk}
\end{equation}
where the monolayer Hamiltonian is given by
\begin{equation}
    H_\textrm{1L}(\vec{k}) = 
    \left(\begin{array}{cc}
          H_1(\vec{k}) & H_2(\vec{k}) \\
          H_2(\vec{k}) & H_1(\vec{k})
    \end{array}\right), 
\end{equation}
with 
\begin{equation}
     H_1(\vec{k}) = 
     \left(\begin{array}{cc}
     t_{AA}(\vec{k})   & t_{AB}(\vec{k}) \\
     t^{*}_{AB}(\vec{k})  & t_{AA}(\vec{k})
    \end{array}\right),
\end{equation}
and
\begin{equation}
     H_2(\vec{k}) = 
     \left(\begin{array}{cc}
      t_{AD}(\vec{k}) & t_{AC}(\vec{k}) \\
      t^{*}_{AC}(\vec{k}) & t_{AD}(\vec{k})
    \end{array}\right).
\end{equation}
The matrix 
\begin{equation}
     C(\vec{k}) = 
     \left(\begin{array}{cc}
     0 & H_3(\vec{k}) \\
     0 & 0
    \end{array}\right),
\end{equation}
with
\begin{equation}
    H_3(\vec{k}) = 
    \left(\begin{array}{cc}
      t_{AD}^{\perp}(\vec{k})   & t^{\perp}_{AC}(\vec{k}) \\
      t^{\perp *}_{AC}(\vec{k})  & t^{\perp}_{AD}(\vec{k})
    \end{array}\right).
\end{equation}
represents the coupling between the layers. The coupling elements read
\begin{align}
    t_{AA}(\v{k})&= 2t_3 \cos(\v{k} \cdot \v{r}_3),\nonumber\\
    t_{AB}(\v{k})&= t_1 \textstyle \sum_{\v{r}_1} e^{\I \v{k} \cdot \v{r}_1},\nonumber\\
    t_{AC}(\v{k})&= t_2 e^{\I \v{k} \cdot \v{r}_2} +t_4 e^{\I \v{k} \cdot \v{r}_4},\nonumber\\
    t_{AD}(\v{k})&= 0,\nonumber\\
    t_{AC}^\perp(\v{k})&= t_1^\perp \textstyle \sum_{\v{r}_1^\perp}
    e^{\I \v{k} \cdot \v{r}_1^\perp} +t_4^\perp \textstyle \sum_{\v{r}_4^\perp} e^{\I \v{k} \cdot \v{r}_4^\perp},\nonumber\\    
    t_{AD}^\perp(\v{k})&= 2t_2^{\perp} \cos(\v{k} \cdot \v{r}_2^{\perp}) +t_3^{\perp} \textstyle \sum_{\v{r}_3^\perp}
    e^{\I \v{k} \cdot \v{r}_{3}^\perp}.    
\end{align}
The coupling constants con be found in Table I and the vectors to the $n$th nearest neighbors read
\begin{align}
\v{r}_1&= a_1(-\cos(\alpha/2),\pm \sin(\alpha/2)), \nonumber\\
\v{r}_2&= a_2(\cos(\beta),0),\nonumber\\
\v{r}_3&= a_1(0,2\sin(\alpha/2)),\nonumber\\
\v{r}_4&= (-(2a_1 \cos(\alpha/2)+a_2\cos(\beta),0),\nonumber\\
\v{r}_1^\perp&= (a_2 \cos(\beta), \pm a_1 \sin(\alpha/2)),\nonumber\\
\v{r}_2^\perp&= (a_1 \cos(\alpha/2) +a_2\cos(\beta), 0),\nonumber\\
\v{r}_3^\perp&= (\pm (a_1 \cos(\alpha/2) +a_2\cos(\beta)), \pm 2a_1 \sin(\alpha/2)),\nonumber\\
\v{r}_4^\perp&= (-(2a_1\cos(\alpha/2)+a_2\cos(\beta)), \pm a_1\sin(\alpha/2)).
\end{align}
The eigenvalues of the Hamiltonian in \eq{Hk} for a 5-layer FLBP system are shown in \fig{2} and \fig{11} (blue curves). By following the development in Ref. \cite{Sousa2017}, which consists of applying Toeplitz theory, the Hamiltonian $H(\v{k})$ can be decomposed \textit{approximately} to block-diagonal matrix form. Each $2 \times 2$ block matrix is given by
\begin{equation}
    \label{eq:Hr}
    H_{n}^{\text{red}}(\vec{k}) = H_1(\vec{k}) + H_2(\vec{k})+\lambda_n H_3(\vec{k}).
\end{equation}
We found empirically that the coefficient $\lambda_n \equiv \cos\bigl(\frac{2n-1}{2M+1}\pi\bigr)$ shows (slightly) better agreement as the expression found in Ref. \cite{Sousa2017}, $\tilde\lambda_n \equiv \cos\bigl(\frac{n}{M+1}\pi\bigr)$, compare the red and green dashed curves in \fig{11}. However, \eq{Hr} is an approximation and both values of $\lambda_n$ deviate from the energy bands of the tight-binding Hamiltonian.

\begin{figure}[t]
  \centering
  \includegraphics[scale=0.6]{fig11.pdf}
  \caption{Energy bands of 5-layer FLBP calculated by means of the tight-binding Hamiltonian \eq{Hk} (blue curves), the reduced Hamiltonian \eq{Hr} with $\lambda_n$ (red dashed curve) and $\tilde\lambda_n$ (green dashed curve). The reduced Hamiltonian approximates well the tight-binding Hamiltonian.}
  \label{fig:11}
\end{figure}

It is known that any two-level system can be depicted by a general Hamiltonian
\begin{equation}\label{H2l}
    H_{2l} = d_0\sigma_0 + \vec{\sigma}\cdot\vec{d},
\end{equation}
where $\sigma_0$ and $\vec{\sigma} = (\sigma_x,\sigma_y,\sigma_z)$ are the Pauli matrices, $d_0$ and $\vec{d} = (d_x,d_y,d_z)$ indicates the pseudo-spin direction in the Bloch sphere. Eigenvalues and eigenvectors are
\begin{equation}
    E_s = d_0 + s d,
\end{equation}
with the band index $s = \pm 1$, and
\begin{eqnarray}
    \vec{\Psi}_{s = 1} & = & (\cos\theta/2, \textrm{e}^{i\phi}\sin\theta/2), \nonumber\\
    \vec{\Psi}_{s = -1} & = & (\sin\theta/2, -\textrm{e}^{i\phi}\cos\theta/2),
\end{eqnarray}
where $(\theta,\phi)$ are the spherical coordinates of $\vec{d}$ in the Bloch sphere. Comparing Eqs. \eq{Hr} and \eqref{H2l}, we obtain
\begin{eqnarray}
    d_0(\vec{k}) & = & t_{AA}(\vec{k})+t_{AD}(\vec{k})+\lambda_n t_{AD}^\perp(\vec{k}), \nonumber\\
    d_x(\vec{k}) & = & \Re{t_{AB}(\vec{k})+t_{AC}(\vec{k})+\lambda_n t_{AC}^\perp(\vec{k})}, \nonumber\\
    d_y(\vec{k}) & = & -\Im{t_{AB}(\vec{k})+t_{AC}(\vec{k})+\lambda_n t_{AC}^\perp(\vec{k})}, \nonumber\\
    d_z(\vec{k}) & = & 0.
\end{eqnarray}
Since $d_z(\vec{k}) = 0$ then $\theta = \pi/2$, the pseudo-spin is oriented in the $xy$ plane with the angle $\phi = \arctan(d_y/d_x)$.

For a continuum model, we expand the Hamiltonian around the $\Gamma$ point up to second order in $\vec{k}$, ending up with the Hamiltonian $H_n^\text{red}$ in \eq{4}.

