\vspace{.2cm}

As in the prior work \cite{KS}, the central object of the analysis are the $2L\times 2L$ transfer matrices at complex energy $E\in\CM$ defined by
%
\begin{equation}
\label{eq-TraDef}
\Tt^E
\;=\;
\begin{pmatrix}
(E\,\one-V)T^{-1} & - R \\ T^{-1} & 0 
\end{pmatrix}
\;,
\end{equation}
%
which allow to compute the solutions of the eigenvalue equation locally, see the proof of Propositon~\ref{prop-CharPol}. The results below state that the continuous part of the limit spectrum can be computed from $\Tt^E$, albeit in a highly non-trivial manner, and that merely the discrete part of the limit spectrum, also referred to as outliers, depend on the local perturbation $(A,B,C)$. For example, the limit spectrum of the circulant Toeplitz matrices, case (a), are given by
%
\begin{equation}
\label{eq-PeriodicSpec1}
\lim_{N\to\infty} \spec(H_N(R,V,T))
\;=\;
\Sigma\;,
\end{equation}
%
where $\Sigma$ is given in terms of the spectral theory of the transfer matrices by
%
\begin{equation}
\label{eq-PeriodicSpec2}
\Sigma
\;=\;
\big\{ E\in\CM\,:\,\spec(\Tt^E)\cap \SM^1\not= \emptyset\big\}
\;.
\end{equation}
%
In text books like \cite{BS} one rather finds $\Sigma=\{ \spec(H(z))\,:\,z\in\SM^1\}$ where $H(z)$ is the symbol defined by $z\in\CM\mapsto H(z)=R z^{-1}+V+Tz$, but it is straight-forward to check that this coincides with \eqref{eq-PeriodicSpec2}. Determining the limit spectrum in the case (b) is Widom's achievement \cite{Wid1} which was rederived by transfer matrix techniques in the previous work \cite{KS}. It is the special situation $C=V$ of case (c) which is described in detail next. Some notations have to be introduced. Let $z_1(E),\ldots,z_{2L}(E)$ be the eigenvalues of $\Tt^E$, ordered such that $|z_i(E)|\leq |z_{i+1}(E)|$ for $i=1,\ldots,2L-1$. Degeneracies are collected in the set
%
\begin{equation}
\label{eq-FDef}
\Ff
\;=\;
\big\{E\in\CM\,:\,{\Tt}^E\mbox{ has a degenerate eigenvalue}\big\}
\;.
\end{equation}
%
As in \cite{KS}, it will always be assumed that the set $\mathcal{F}$ is finite.  Given a subset $I\subset\{1,\ldots,2L\}$, let $\Rr^E_I$  denote the Riesz projection of $\Tt^E$ onto the eigenvalues $z_j(E)$ with $j\in I$: 
%
\begin{equation}
\label{eq-RI}
{\Rr}_\IndSet^E
\;=\;
\oint_{{\gamma}_I}\frac{dz}{2\pi\imath}\;(z\,\one-\Tt^E)^{-1}
\;,
\end{equation}
%
where $\gamma_I$ is a curve with winding number $1$ around each  $z_j(E)$ with $j\in I$, but winding $0$ around  $z_j(E)$ with $j\not\in I$. For the finite number of $E\in\Ff$ and more generally in case there are eigenvalues $z_j(E)$ of the same modulus, there are some ambiguities resulting from the choice of eigenvalue labelling with the set $I$, but these ambiguities turn out to be irrelevant in what follows. Introduce the functions
%
\begin{equation}
\label{eq-qDef}
\hat{q}_{I}(E)
\;=\;
{\det}_L\Big(
\binom{0}{\one}^*
{\Rr}_{I}^E
\begin{pmatrix}
E\,\one-C & - \one \\ \one & 0 
\end{pmatrix}
\binom{\one}{0}\Big)
\;,
\qquad
E\in\CM\setminus\Ff
\;.
\end{equation}
%
The next theorem, corresponding to the asymptotic spectral analysis of case (c) in the above list, generalizes the results of \cite{Wid1,KS} and shows that a local diagonal contribution does not modify the limit spectra, except for the outliers. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem} 
\label{theo-boundary}
Introduce
%
\begin{align}
\Lambda
\;=\;
\big\{E\in\CM\,:\,|z_L(E)|=|z_{L+1}(E)|\big\} .
\label{eq-LambdaDef}
\end{align}
%
Suppose that $|z_{L-1}(E)|<|z_L(E)|=|z_{L+1}(E)|<|z_{L+2}(E)|$ for all but finitely many $E \in \Lambda$. Then $\Lambda$ consists of a finite number of analytic arcs. Consider the two sets $I_0=\{L+1,\ldots,2L\}$ and $I_1=\{L,L+2,\ldots, 2L\}$ and 
suppose that the functions $\hat{q}_{\IndSet_0}$ and $\hat{q}_{\IndSet_1}$ have discrete zero sets in a neighbourhood of  $\LimitSet \setminus \mathcal{F}$. Finally introduce the set of outliers depending on the perturbation $C$ by
%
$$
\Gamma(C)
\;=\;
\big\{E\in\CM \setminus \LimitSet  \,:\,\hat{q}_{\IndSet_0}(E)=0  \big\}
\;.
$$
%
Then
%
\begin{equation}
\label{eq-Widom}
\lim_{N\to\infty} \spec(H_N(0,0,C))
\;=\;
\Lambda\cup\Gamma(C)
\;.
\end{equation}
%
\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%




Now let us come to the first main new result of the paper,  corresponding to case (d) in the list above. It will be assumed throughout that $B$ is invertible. It is again necessary to start out with some notations. For $I\subset \{1,\ldots,2L\}$,  let $I^c=\{1,\ldots,2L\}\setminus I$ be the complementary set. Then the Riesz projections satisfy $\Rr_{I^c}^E= \one - {\Rr}_{I}^E$. Further let us introduce  
%
\begin{equation}
\label{eq-qDef}
q_{I}(E)
\;=\;
{\det}_{2L}
\big(
{\Rr}_{I}^E
\Tt^E_{\mbox{\rm\tiny bd}}
\,-\,
\Rr_{I^c}^E\big)
\;,
\qquad
E\in\CM\setminus\Ff
\;,
\end{equation}
%
where the transfer matrix $\Tt^E_{\mbox{\rm\tiny bd}}$ of the boundary site is defined as in \eqref{eq-TraDef}, now for $A,B,C$: 
%
\begin{equation}
\label{eq-TraBDDef}
\Tt^E_{\mbox{\rm\tiny bd}}
\;=\;
\begin{pmatrix}
(E\,\one-C)B^{-1} & - A \\ B^{-1} & 0 
\end{pmatrix}
\;.
\end{equation}


%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}
\label{thm-LimitSpecIntro}
Suppose that $B$ is invertible and $A$ has rank $r=\rk(A)$. Introduce the sets
%
\begin{align}
\Sigma_r
&
\;=\;
\big\{E\in\CM\,:\,
\exists \;j\geq L-r+1 \;\mbox{ such that } |z_{j}(E)|=1
\big\} 
\;, 
\label{eq-SigmaRDef}
\\
\Lambda_r
&
\;=\;
\big\{E\in\CM\,:\,|z_{L-r}(E)|=|z_{L-r+1}(E)|\geq 1 \;\mbox{\rm and }|z_{L-r-1}(E)|\leq 1
\big\} ,
\label{eq-LambdaRDef}
\\
\Gamma_r
& 
\;=\;
\big\{E\in\CM \setminus (\Lambda_r\cup\Sigma_r)  \,:\,
q_{I^E_{>,r}}(E)=0 
\big\}
\;,
\label{eq-SigmaDef}
\end{align}
%
where
%
\begin{equation}
\label{eq-IE>Def}
I^E_{>,r}
\;=\;\big\{j=L-r+1,\ldots,2L\,:\,|z_j(E)|>1\big\}
\;.
\end{equation}
%
On each of these sets one makes the further assumptions:

\begin{itemize}

\item[{\rm (i)}] For all but finitely many $E\in\Sigma_r$ there is merely one $j$ such that $|z_j(E)|=1$, namely $|z_{j-1}(E)|<1<|z_{j+1}(E)|$.  Furthermore, the functions $q_{I'_j}$ and $q_{I'_{j+1}}$ for the index sets $I'_j=\{j,\ldots,2L\}$ and $I'_{j+1}=\{j+1,\ldots,2L\}$ have discrete zero sets in a neighbourhood of $\Sigma_r \setminus \mathcal{F}$.

\item[{\rm (ii)}]  One has $|z_{L-r-1}(E)|<|z_{L-r}(E)|=|z_{L-r+1}(E)|<|z_{L-r+2}(E)|$ for all but finitely many $E \in \Lambda_r$. For $I_0=\{L-r+1,\ldots,2L\}$ and $I_1=\{L-r,L-r+2,\ldots,2L\}$ the functions $q_{I_0}$ and $q_{I_1}$ have discrete zero sets in a neighbourhood of $\LimitSet_r \setminus \mathcal{F}$.

\item[{\rm (iii)}] The function $q_{I^E_{>,r}}$ has a discrete zero set. 

\end{itemize}
%
Then the limit spectrum of $H_N(A,B,C)$ satisfies
%
\begin{equation}
\label{eq-GenResult}
\lim_{N\to\infty} \spec(H_N(A,B,C))
\;=\;
\Lambda_r\cup\Sigma_r\cup\Gamma_r
\;.
\end{equation}
%
\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%

Both Theorem~\ref{theo-boundary} and Theorem~\ref{thm-LimitSpecIntro} have non-triviality assumptions on the functions $\hat{q}_I$ and $q_I$ for some $I$ which already appeared in \cite{Wid1,Del,KS} and which are quite tedious to check in concrete situations. It is, moreover, possible that these non-triviality assumptions do not hold, as show examples in both \cite{Wid1} and \cite{KS}. However, these examples require some artificially produced degeneracies and generically the non-triviality assumptions are satisfied, as shown by the following second main result of this work. It is proved in Section~\ref{sec-analyticity} by computing the large $E$ asymptotics of the Riesz-projections $\Rr^E_I$. 

%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}
\label{theo-Expansion}
For Lebesgue almost all matrix coefficients $R,T,V,A,B$ and $C$, all functions $\hat{q}_I$, with subsets $I\subset\{1,\ldots,2L\}$ of cardinality $L$, and all functions ${q}_I$, with subsets $I\subset\{1,\ldots,2L\}$, have discrete zero sets.
%
\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%

Next follow numerous remarks providing supplementary information on Theorems~\ref{theo-boundary} and \ref{thm-LimitSpecIntro} and outlining their proofs.

%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{remark}
{\rm
As already stressed above, the proof of Theorem~\ref{theo-boundary} is a minor modification of the proof in \cite{KS} resulting from the perturbation $C\not =V$.  Therefore, its full proof will only be outlined in this remark. This will also allow to point out some changes of notation compared to \cite{KS}. The main tool of the proof of Theorem~\ref{theo-boundary} is the Widom-type formula for the characteristic polynomial of $H_N=H_N(0,0,C)$: 
%
\begin{equation}
{\det}_{NL}(H_N - E\one_{NL})
\;=\; 
\sum_{|I|= L} Z_I(E)^{N} 
\,\hat{q}_I(E) 
\;,
\label{eq-OpenIdentityIntro}
\end{equation}
%
where the sum runs over subsets $I\subset\{1,\ldots,2L\}$ with cardinality $|I|=L$ and 
%
\begin{equation}
\label{eq-ZDef}
Z_I(E)
\;=\;
(-1)^{L}  {\det}_{L}(T)
\prod_{j\in I}z_j(E)
\;.
\end{equation}
%
The proof of \eqref{eq-OpenIdentityIntro} results from the first half of the proof of Theorem~31 in \cite{KS}. In the latter result, the index set was replaced by its complement, basically to follow Widom's notations from \cite{Wid1}, but it turns out to be more convenient (and actually more simple) to not do this here and in the generalization below. As a result, the factor $Z_I(E)$ defined in \eqref{eq-ZDef} uses the eigenvalues instead of their inverses. Based on \eqref{eq-OpenIdentityIntro}, the proof of Theorem~\ref{theo-boundary} now roughly proceeds as follows. For large $N$, the sum on the r.h.s. of \eqref{eq-OpenIdentityIntro} is dominated by the summand with the largest factor $Z_I(E)$ which due to ordering of the eigenvalues is simply given by the index set $I_0$. If its factor $\hat{q}_{I_0}(E)$ does not vanish, one concludes that in a sufficiently small  neighborhood of such $E$, $H_N$ has no eigenvalue for $N$ sufficiently large. On the other hand, if the factor $\hat{q}_{I_0}(E)$ vanishes, Hurwitz's theorem allows to show that there must be such an eigenvalue. This precisely defines the set $\Gamma(C)$ of outliers. Further zeros of the characteristic polynomial can appear if there are two factors $Z_I(E)$ which both have the largest (same) modulus. This is possible whenever there the middle two  eigenvalues are of the same modulus, hence leading to the definition of the set $\Lambda$. The hypothesis in the theorem assures that, away from a finite number of points, there is no other factor $Z_I(E)$ of same modulus, and then in Section~4.8 of \cite{KS} it is shown that one can indeed construct an eigenfunction for a nearby complex energy, leading to a zero of the characteristic polynomial. The proof of Theorem~\ref{thm-LimitSpecIntro} will   follow a similar reasoning, albeit based on a new Widom-type formula presented in Remark~\ref{rem-ProofOuline} and proved in Section~\ref{sec-LocalPerturbation}.
}
\hfill $\diamond$
\end{remark}
%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{remark}
\label{rem-MoreSites}
{\rm 
Theorem~\ref{theo-boundary} states that the arcs $\Lambda$ constituting the continuous part of the limit spectrum are independent of the local perturbation $C$. This holds true for more general  perturbations  supported within a fixed finite distance $K$ from the two boundaries. Supposing that all off-diagonal entries are invertible, one can then define transfer matrices over the sites with a perturbation by formula \eqref{eq-TraDef}. Let $\Tt^{E}_{\mbox{\rm\tiny le},1},\ldots,\Tt^{E}_{\mbox{\rm\tiny le},K}$ and $\Tt^{E}_{\mbox{\rm\tiny ri},1},\ldots,\Tt^{E}_{\mbox{\rm\tiny ri},K}$ denote the corresponding transfer matrices. Then replacing \eqref{eq-qDef} by
%
$$
\hat{q}_{I}(E)
\;=\;
{\det}_L\Big(
\binom{0}{\one}^*
\Tt^E_{\mbox{\rm\tiny ri},K}\cdots \Tt^E_{\mbox{\rm\tiny ri},1}
\,{\Rr}_{I}^E
\,\Tt^E_{\mbox{\rm\tiny le},K}\cdots \Tt^E_{\mbox{\rm\tiny le},1}
\binom{\one}{0}\Big)
\;,
$$
% 
all statements of Theorem~\ref{theo-boundary} remain valid.
\hfill $\diamond$
}
\end{remark}
%%%%%%%%%%%%%%%%%%%%%%%%%%

The remaining remarks mainly concern Theorem~\ref{thm-LimitSpecIntro}.

%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{remark}
{\rm
For rank $r=L$, namely both $A$ and $B$ are invertible, one has $\Sigma_L=\Sigma$ and $\Lambda_L=\emptyset$. Hence the limit spectrum consist of the periodic spectrum $\Sigma$ together with some outliers $\Gamma_L$ which depend continuously on $(A,B,C)$ because $q_{I^E_{>,r}}$ does so. More generally, note that $\Sigma_r$ and $\Lambda_r$ do not depend on the particular choice of the matrices $(A,B,C)$, but merely on the rank $r$ of $A$. With $r$ fixed, again only $\Gamma_r$ will depend on these matrices $(A,B,C)$. Similar as in Remark~\ref{rem-MoreSites}, a modification of the definition of $q_I$ allows to deal with any compactly supported perturbation. Again this does not modify $\Sigma_r$ and $\Lambda_r$. Let us finally note that in the semipermeable case with rank $r=0$ (namely $A$ vanishing and $B$ invertible), the two sets $\Sigma_0$ and $\Lambda_0$ are generically both non-empty, even though they take a somewhat more simple form. 
}
\hfill $\diamond$
\end{remark}
%%%%%%%%%%%%%%%%%%%%%%%%%%


%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{remark}
\label{rem-ArcsIsolatedPoints}
{\rm
The identities $|z_j(E)|=1$ and $|z_{L-r}(E)|=|z_{L-r+1}(E)|$ in \eqref{eq-SigmaRDef} and  \eqref{eq-LambdaRDef} respectively provide one real equation for the complex energy, while the two inequalities in \eqref{eq-LambdaRDef} hold on open sets. Generically, one hence expects  $\Sigma_r$ and $\Lambda_r$ to be locally one-dimensional subsets of the complex energy plane. As the functions $E\in\CM\to z_j(E)$ are locally analytic, one can hence show by the techniques of Lemmata~20 and 21 in \cite{KS} that $\Sigma_r$ and $\Lambda_r$ consist of a finite number of analytic arcs which do not have isolated points. Furthermore, $\Gamma_r$ is a discrete set, called the set of outliers. Let us briefly comment on the further assumptions (i), (ii) and (iii). Having respectively further unit eigenvalues or further eigenvalues of the same modulus are generically events of codimension $2$. Together with Theorem~\ref{theo-Expansion} this shows that the three conditions (i), (ii) and (iii) hold generically. 
}
\hfill $\diamond$
\end{remark}
%%%%%%%%%%%%%%%%%%%%%%%%%%


%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{remark}
\label{rem-ProofOuline}
{\rm
The proof of Theorem~\ref{thm-LimitSpecIntro} is based on a new Widom-type formula for the characteristic polynomial of $H_N=H_N(A,B,C)$: 
%
\begin{equation}
%\frac{{\det}_{NL}(H_N - E\one_{NL}) }{(-1)^{N(L-1)} {\det}_{L}(B)  {\det}_{L}(T)^{N-1} }
{\det}_{NL}(H_N - E\one_{NL})
\;=\; 
 {\det}_{L}(B) \, 
\sum_{|I|\leq L+r} Z_I(E)^{N-1} 
\,q_I(E) 
\;,
\label{eq-IdentityIntro}
\end{equation}
%
where the sum runs over subsets $I\subset\{1,\ldots,2L\}$ with cardinality less than or equal to $L+r$. The restriction onto the sum results from the fact that for larger cardinality the corresponding factors $q_I(E)$ vanishes, as can readily be understood by inspecting the definition~\eqref{eq-qDef} ({\it e.g.}, for $I=\{1,\ldots,2L\}$ one has $\Rr^E=\one$ so that clearly $q_I(E)=0$ for $r<L$) . For most $E\in\CM$, the sum on the r.h.s. of \eqref{eq-IdentityIntro} is dominated by a single term. In particular, the trivial  bound $|I^E_{>,r}|\leq L+r$ implies that the set $I^E_{>,r}$ is admissible in the identity \eqref{eq-IdentityIntro}, and indeed provides the largest factor. The associated summand can nevertheless vanish because the $q$-factor vanishes, and these zeros define the set $\Gamma_r$ of outliers. The sets $\Sigma_r$ and $\Lambda_r$ result from a different situation, namely there are two summands in  \eqref{eq-IdentityIntro} for which the $Z$-factors have the same modulus. Then a suitable linear combination of these two can (and does) lead to a zero of the characteristic polynomial. For the set $\Sigma_r$ this scenario results from an eigenvalue $z_j(E)$ of unit modulus, while for $\Lambda_r$ there are two eigenvalues of same modulus (which is typically not $1$). The conditions (i) and (ii) exclude the possibility that there are three eigenvalues of same modulus.
}
\hfill $\diamond$
\end{remark}
%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{remark}
{\rm
The $j$ appearing in \eqref{eq-SigmaRDef} can be strictly larger than $L-r+1$, corresponding to situations where there are fewer eigenvalues of modulus strictly larger than $1$.  Comparing \eqref{eq-SigmaRDef} with \eqref{eq-PeriodicSpec2}, one concludes 
%
$$
\Sigma_r\,\subset\,\Sigma
\;,
\qquad
\Sigma_L\;=\;\Sigma
\;,
$$
%
justifying the choice of notation. It is also possible to write out an expression for $\Sigma_r$ that exhibits it as a topological boundary of an open set $\Omega$. The definition of this set uses the winding number $\Wind^E(H)$ of $z\in\SM^1\mapsto{\det}_L(H(z)-E\,\one)$:
%
\begin{align*}
\Omega_r
&
\;=\;
\{E\in\CM\,:\,\Wind^E(H)>-r\}
\\
&
\;=\;
\big\{E\in\CM\,:\,|I^E_{>,r}|<L+r\;\,\mbox{\rm and }\spec(\Tt^E)\cap\SM^1=\emptyset\big\} 
\;.
\end{align*}
%
In the first set the inequality $\Wind^E(H)>-r$ includes the fact that $\Wind^E(H)$ exists, namely $\spec(\Tt^E)\cap\SM^1=\emptyset$, so that the second equality then follows from the well-known identity ({\it e.g.} \cite{BS}) 
%
\begin{equation}
\label{eq-WindStates}
\big|\big\{j=1,\ldots,2L\,:\,|z_j(E)|>1\big\}\big|
\;=\;
L-\Wind^E
\;.
\end{equation}
%
Now for $E\in \Omega_r$, there are $m_E < L + r$ eigenvalues of modulus larger than $1$. Moving inside $\Omega_r$, one may add eigenvalues of modulus larger than $1$, so go to $m_E+1$ of them, unless one passes to $m_E+1=L-r$. This passage is though an eigenvalue on the unit circle $\SM^1$ and this is then precisely a point on the boundary $\partial\Omega_r$. Hence one deduces $\Sigma_r=\partial \Omega_r$.
}
\hfill $\diamond$
\end{remark}
%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{remark}
{\rm
In the definition \eqref{eq-LambdaRDef} of $\Lambda_r$, if $|z_{L-r}(E)|=|z_{L-r+1}(E)|>1$  and $|z_{L-r-1}(E)|<1$, then there are $L+r+1$ eigenvalues of modulus larger than $1$. Then there are two possible choices for the largest allowed $Z$-factors in \eqref{eq-IdentityIntro}, namely those corresponding to the sets $I_0$ and $I_1$. On the other hand, if $|z_{L-r}(E)|=|z_{L-r+1}(E)|=1$ in  \eqref{eq-LambdaRDef}, then there are merely $L+r-1$ eigenvalues of modulus larger than $1$ (if $|z_{L-r+2}(E)|>1$). This case hence also corresponds to a point in $\Sigma_r$, albeit only one of those finite number of points described in Hypothesis (i). Hence $\Sigma_r\cap\Lambda_r$ may be non-zero, but consist of at most a finite number of points. An alternative definition of $\Lambda_r$ would require $|z_{L-r}(E)|=|z_{L-r+1}(E)|>1$, but then $\Lambda_r$ is not closed. 
}
\hfill $\diamond$
\end{remark}
