= & \; 
\{x_{i,j} - x_{nL+i,nL+j} \colon \left\lceil \tfrac{i}{L} \right\rceil + \left\lceil \tfrac{j}{L} \right\rceil \leq 4 \text{ and } 1 \leq n \leq N-2 \} 
