\section{Notations.\vspace{.3cm} \\}
Throughout $\R$, $\Q$, $\Z$, $\T$ and $\N$ will stand for the set of all real numbers, the set of all rational numbers, the set of all integers, the set of all complex numbers on the unit circle and the set of all natural numbers \em(note that we do not consider zero as a natural number) \em respectively. The first three are equipped with their usual abelian group structure and the circle group $\T=\R/\Z$ is equipped with the operation of addition mod 1. Following \cite{Ka}, we may identify $\T$ with the interval [0,1] identifying 0 and 1. Any real valued function $f$ defined on $\T$ can be identified with a periodic function defined on the whole real line $\R$ with period 1, i.e., $f(x+1)=f(x)$ for every real $x$. When referring to a set $X\subseteq \T$ we assume that $X\subseteq [0,1]$ and $0\in X$ if and only if $1\in X$. For a real $x$, we denote its fractional part by $\{x\}$ and $\|x\|$ the distance from the integers, i.e., $\min\big\{\{x\},1-\{x\}\big\}$.\\

Let $G$ be an abelian group. The cyclic subgroup of $G$ generated by $g\in G$ is denoted by $\langle g\rangle$. The cyclic group of order $n$ is denoted by $\Z(n)$. If $S\subseteq G$ then the subgroup generated by $S$ is defined as
$$
\langle S\rangle = \bigg\{\sum\limits_{i=1}^j m_is_i : j\in\N, m_i\in\Z, s_i\in S\bigg\}.
$$
The subgroup of torsion elements ($p$-torsion) of $G$ is denoted by $t(G)$ (resp., by $t_p(G)$). For the circle group $\T$ we denote $t_p(\T)$ by $\Z(p^\infty)$. A subgroup $H$ of $G$ is called torsion if $H=t(H)$.

For arithmetic sequences, the following facts will be used in this sequel time and again. So, before moving onto our main results here we recapitulate that once.
\begin{fact}\label{lemmanew}\cite{DI1}
For any arithmetic sequence $(a_n)$ and $x\in\T$, we can find a unique sequence $c_n\in [0,q_n-1]$ such that
\begin{equation}\label{canonical:repr}
x=\sum\limits_{n=1}^{\infty}\frac{c_n}{a_n},
\end{equation}
where $c_n<q_n-1$ for infinitely many $n$.
\end{fact}
%\begin{proof}
%For better clarity we recall the construction of the sequence $(c_n)$. Consider $c_1=\lfloor a_1x\rfloor$, where $\lfloor \ \rfloor$ denotes the integer part. Therefore, $x-\frac{c_1}{a_1}<\frac{1}{a_1}$.
%
%Suppose, $c_1,c_2,\ldots,c_k$ are defined for some $k\geq 1$ with $x_k=\sum\limits_{n=1}^{k}\frac{c_n}{a_n}$ and $x-x_k<\frac{1}{a_k}$. Then the $(k+1)$-th element is defined as $c_{k+1}=\lfloor a_{k+1}(x-x_k)\rfloor$.
%\end{proof}

For $x\in\T$ with canonical representation (\ref{canonical:repr}), we define
\begin{itemize}
\item[$\bullet$] $supp(x) = \{n\in \N: c_n \neq 0\}$,
\item[$\bullet$] $supp^q(x)=\{n\in\N\ : \ c_n=q_n-1\}$.
\end{itemize}
For an arithmetic sequence $(a_n)$, note that for each $j\in\N$,
\begin{equation}\label{eqsum}
\sum\limits_{i=j}^\infty \frac{c_i}{a_i} \leq \sum\limits_{i=j}^\infty \frac{q_i-1}{a_i} = \sum\limits_{i=j}^\infty \bigg(\frac{1}{a_{i-1}} - \frac{1}{a_i} \bigg) \leq \frac{1}{a_{j-1}}.
\end{equation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{uconlmain}\cite[Lemma 3.1]{DR}
For $x\in\T$ with canonical representation (\ref{canonical:repr}), for every natural $n > 1$ and every non-negative integer $t$,
\begin{equation}\label{eqlemain1}
\{a_{n-1}x\}=\frac{c_n}{q_n}+\frac{c_{n+1}}{q_nq_{n+1}}+\ldots+\frac{c_{n+t}}{q_n\ldots q_{n+t}}+\frac{\{a_{n+t}x\}}{q_n\ldots q_{n+t}}.
\end{equation}
In particular, for $t=1$, we get
\begin{equation}\label{eqlemain2}
\{a_{n-1}x\}=\frac{c_n}{q_n}+\frac{c_{n+1}}{q_nq_{n+1}}+\frac{\{a_{n+1}x\}}{q_nq_{n+1}}.
\end{equation}
\end{lemma}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The following facts are well known for integer norm:
\begin{eqnarray}\label{eqinorm1}
&\bullet& \ \mbox{for any } \ A\subseteq\N\ \mbox{ and }\ y_n=x_n+z_n \ \mbox{ if } \ \lim\limits_{n\in A} z_n=0, \ \mbox{ then } \  \lim\limits_{n\in A}\|y_n\|=\lim\limits_{n\in A}\|x_n\|. \\
&\bullet& \ \mbox{if } (x_n)  \mbox{ is  bounded  with } x_n\geq 0\mbox{ for all }n\in A \mbox{ and } \lim_{n\in A} \|y_n\|=0, \mbox{ then } \lim_{n\in A}\|x_ny_n\|=0.\\
&\bullet& \ \mbox{for any integer } \ n\ \mbox{ and } \ \mbox{for any real number } x, \|n+x\|=\|x\|.
\end{eqnarray}
Also note that for any $r\in\N$,
\begin{equation}\label{eqr}
\bullet \ \mbox{if } \ r\{a_nx\}<1\ \mbox{ then } \ \{ra_nx\}=r\{a_nx\}.
\end{equation}
\begin{equation}\label{eqrn}
\bullet \ \mbox{if } \ r\|a_nx\|<\frac{1}{2} \ \mbox{ then } \ \|ra_nx\|=r\|a_nx\|.
\end{equation}
