\begin{remark}\label{uconr1}
Since $(a_n)$ is a subsequence of $(e_n)$, we can write $a_k=e_{n_k}$. More precisely, we can write $e_{(n_{k-1}+i-1)}=r^k_ia_{k-1}$ where $1\leq i \leq n_{k}-n_{k-1}$ and $r^k_i\in [1,q_{k}-1]$ with $r^k_1=1$. In particular, if $(e_n)=(d_n)$ then $n_{k}-n_{k-1}=q_{k}-1$ and $d_{(n_{k-1}+i-1)}=ia_{k-1}.$ We simply denote $r^k_i$ by $r(e)$ when there is no confusion in the indexing.
\end{remark}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{remark}\label{uconr2}
Let $a_k=e_{n_k}$ and $A\subseteq \N$. We define
$$
L(A)=\bigcup\limits_{k\in A} [n_{k-1},n_{k}-1].
$$
Then, in view of Remark \ref{uconr1}, for any subsequence $(e_n)_{n\in B}$ of $(e_n)$ there exists a unique $A\subseteq\N$ such that $B\subseteq L(A)$ and if $A_1\subsetneq A$ then $B\not\subseteq L(A_1)$.
\end{remark}
