	\begin{proof}[{\bf Proof of Proposition \ref{prop2}.}]
		From Definition \ref{def1} and the Gauss equation we have, respectively,
		\begin{eqnarray*}
			\nabla^2 f(\nu,\,\nu) = f[Ric(\nu,\,\nu) + 2\langle E,\,\nu\rangle^2 - (|E|^2 + \Lambda)]
		\end{eqnarray*}
		and 
		\begin{eqnarray*}
			\frac{R}{2} = K + Ric(\nu,\,\nu) + \frac{1}{2}(|A|^2 - H^2),
		\end{eqnarray*}
		where $K$ is Gauss curvature of $\Sigma.$
		Combining the above equations and using \eqref{rrr}, we obtain 
		\begin{eqnarray*}
			\nabla^2 f(\nu,\,\nu) = f[ \frac{1}{2}(H^2 - |A|^2) - K + 2\langle E,\,\nu\rangle^2].
		\end{eqnarray*}


		Now, from 
		\begin{eqnarray}\label{decopLapla}
			\Delta f = \Delta^\Sigma f + \nabla^2 f(\nu,\,\nu) + H\langle \nabla f,\,\nu\rangle
		\end{eqnarray}
		and the last equation we deduce 
		\begin{eqnarray*}
			\frac{\Delta f}{f} = \frac{\Delta^\Sigma f}{f} + [ \frac{1}{2}(H^2 - |A|^2) - K + 2\langle E,\,\nu\rangle^2] + \frac{H}{f}\langle \nabla f,\,\nu\rangle.
		\end{eqnarray*}
		By integrating the above identity, we have
		\begin{eqnarray}\label{show}
			\int_{\Sigma}(|E|^2 - \Lambda)d\sigma &=&\int_{\Sigma}\frac{H}{f}\langle \nabla f,\,\nu\rangle d\sigma + \int_{\Sigma}\frac{|\nabla_{\Sigma}f|^2}{f^2}d\sigma \nonumber\\
   &+& \int_{\Sigma}\left[ \frac{1}{2}(H^2 - |A|^2) - K + 2\langle E,\,\nu\rangle^2\right]d\sigma.
		\end{eqnarray}




		We consider that
		\begin{eqnarray}\label{stata}
			\int_{\Sigma}( Ric(\nu,\,\nu) + |A|^2)d\sigma \leq \mathcal{C},
		\end{eqnarray}
  where $\mathcal{C}\in\mathbb{R}.$
		Dividing \eqref{vvv} by $f$ and by using \eqref{stata} we get
		\begin{eqnarray}\label{como1}
			\int_{\Sigma}\left(\frac{H}{f}\langle \nabla f,\,\nu\rangle +\frac{1}{f^2}|\nabla_\Sigma f|^2\right)d\sigma
			&\geq&   \int_{\Sigma}|A|^2d\sigma \nonumber\\
			&+& 2\int_{\Sigma}(|E|^2 - \langle E,\,\nu\rangle^2)d\sigma - \mathcal{C}.
		\end{eqnarray}


		Thus, from \eqref{show}, \eqref{como1} and the Gauss-Bonnet theorem we have
		\begin{eqnarray*}
			4\pi(1-g(\Sigma))&\geq& \int_{\Sigma}[ \frac{1}{2}(H^2 + |A|^2)]d\sigma + \int_{\Sigma}(|E|^2 + \Lambda)d\sigma - \mathcal{C},
		\end{eqnarray*} 
		and since $2|A|^2\geq H^2$, 
		\begin{eqnarray}\label{ggggenus}
			4\pi(1-g(\Sigma)) &\geq& \frac{3}{4}\int_{\Sigma}H^2d\sigma + \int_{\Sigma}(|E|^2 + \Lambda)d\sigma - \mathcal{C}.
		\end{eqnarray}
		With this inequality, we can analyze the topology of $\Sigma$. Indeed, $4\pi(1-g(\Sigma))+\mathcal{C}\geq0$, i.e., $$1+\dfrac{\mathcal{C}}{4\pi}\geq g(\Sigma).$$


		Combine the above inequality \eqref{ggggenus} with Definition \ref{hawkingmass}, i.e.,
		\begin{eqnarray*}
			2\pi\mathfrak{X}(\Sigma)  = 4\pi\sqrt{\frac{16\pi}{|\Sigma|}}\mathfrak{M}_{CH}(\Sigma)   + \frac{1}{4}\int_{\Sigma}(H^2 + \frac{4}{3}\Lambda)d\sigma - \frac{16\pi^2}{|\Sigma|}Q(\Sigma)^2  ,
		\end{eqnarray*}
		to obtain
		\begin{eqnarray*}
			4\pi\sqrt{\frac{16\pi}{|\Sigma|}}\mathfrak{M}_{CH}(\Sigma)     \geq  \frac{16\pi^2}{|\Sigma|}Q(\Sigma)^2 + \frac{1}{2}\int_{\Sigma}H^2d\sigma + \int_{\Sigma}|E|^2 d\sigma + \frac{2}{3}\Lambda|\Sigma| - \mathcal{C}.
		\end{eqnarray*}
		Moreover, applying H\"older's inequality to the definition of charge given by \eqref{chaaaarge} yields to
		\begin{eqnarray*}
		16\pi^2Q(\Sigma)^2=\left(\int_{\Sigma}\langle E,\,\nu\rangle d\sigma\right )^2  \leq|\Sigma|\int_{\Sigma}\langle E,\,\nu\rangle^2d\sigma\leq|\Sigma|\int_{\Sigma}|E|^2d\sigma.
		\end{eqnarray*}
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%5



		Finally, 
		\begin{eqnarray*}
			4\pi\sqrt{\frac{16\pi}{|\Sigma|}}\mathfrak{M}_{CH}(\Sigma)     \geq  \frac{32\pi^2}{|\Sigma|}Q(\Sigma)^2 + \frac{1}{2}\int_{\Sigma}H^2d\sigma + \frac{2}{3}\Lambda|\Sigma| - \mathcal{C}.
		\end{eqnarray*}
		The inequality above proves the theorem.


	\end{proof}


