	\begin{proof}[{\bf Proof of Theorem \ref{cocoro2}.}]
		It is well-known that a closed minimal surface of index one satisfies the inequality:
		\begin{eqnarray*}
			8\pi\left(1+ Int\left[\frac{1+g(\Sigma)}{2}\right]\right)\geq \int_{\Sigma}\left( |A|^2 + Ric(\nu, \nu)\right)\, d\sigma,
		\end{eqnarray*}
		where $Int[x]$ denotes the integer part of $x.$ See for instance \cite[Proposition 17]{tiarlos} and \cite{ritore92}. Considering $\mathcal{C}=8\pi\left(1+ Int\left[\dfrac{1+g(\Sigma)}{2}\right]\right)$ in Proposition \ref{prop2} will give us the desired result.

