\title{\textbf{On the genericity of irreducible subfactors}}
\author{Yoonkyeong Lee$^\circ$}
\address{$^\circ$Department of Mathematics, Michigan State University\hfill \url{leeyoo16@msu.edu}}
\author{Brent Nelson$^\bullet$}
\address{$^\bullet$Department of Mathematics, Michigan State University \hfill \url{brent@math.msu.edu}}
\date{}

\begin{document}


%\tableofcontents

\begin{abstract}
We show that finitely generated irreducible $\mathrm{II}_1$ subfactors are generic in the following sense. Given a separable $\mathrm{II}_1$ factor $M$ and an integer $n\geq 2$, equip the set of $n$-tuples of self-adjoint operators in $M$ with norm at most $1$ with the metric $d(x,y) = \max_{1\leq i \leq n} \|x_i - y_i\|_2$. Then the set of $n$-tuples that generate an irreducible subfactor of $M$ forms a dense $G_\delta$ set in this metric space. On the way to proving this result, we show that closable derivations vanish on the anticoarse space associated to their kernels, which leads to new applications of conjugate systems in free probability.
\end{abstract}

\maketitle

\section*{Introduction}

Recall that a unital inclusion of von Neumann algebras $N\leq M$ is said to be \emph{irreducible} if $N'\cap M=\C$. In this case, both $N$ and $M$ (as well as any intermediate von Neumann algebra $N\leq P\leq M$) are necessarily factors. Irreducibility can be interpreted as saying that $N$ is influential to the structure of $M$; for example, it is equivalent to saying that $L^2(M)$ has no non-trivial $N$-$M$-subbimodules. Our main result shows that finite tuples generating irreducible subalgebras are generic.


\begin{thm}\label{thm}
Let $M$ be a separable $\mathrm{II}_1$ factor. For any integer $n\geq 2$, equip $(M_{s.a.})_1^{\oplus n}$ with the metric
    \[
        d(x,y) = \max_{1\leq i \leq n} \| x_i - y_i \|_2.
    \]
Then $\{x\in (M_{s.a.})_1^{\oplus n} \colon W^*(x)\leq M \text{ is irreducible}\}$ is a dense $G_\delta$ set in this metric space.
\end{thm}

\noindent Here and throughout we denote $M_{s.a.}:=\{x\in M\colon x=x^*\}$, $(M)_1:=\{x\in M\colon \|x\|\leq 1\}$, and $(M_{s.a.})_1:= M_{s.a.}\cap (M)_1$. The above theorem answers a question posed by S. Kunnawalkam Elayavalli, who along with coauthors D. Gao, G. Patchell, and H. Tan showed in \cite[Proposition 3.29]{GKEPT24} that finite tuples in a $\mathrm{II}_1$ factor generically generate a subfactor. Our proof (which can be found in Section~\ref{sec:proof_of_thm}) is essentially a refinement of theirs, where density is achieved through a Baire category argument. But a crucial difference is in the use of the following technical result.


\begin{prop}\label{prop}
Let $(M,\tau)$ be a tracial von Neumann algebra and suppose
    \[
        \delta\colon \dom(\delta)\to [L^2(M,\tau)\otimes L^2(M,\tau)]^{\oplus \infty}
    \]
is a derivation whose domain $\dom(\delta)\subset M$ is a unital $*$-subalgebra. Let $Q,N\leq M$ be the von Neumann subalgebras generated by $\ker{\delta}\cap \ker{\delta^*}$ and $\dom(\delta)$, respectively. If $\delta$ is closable as a densely defined operator on $L^2(N,\tau)$, then the anticoarse space for $Q\leq N$ satisfies
    \[
        L^2_{\cross}(Q\leq N, \tau) \subset \ker{\bar{\delta}}
    \]
where $\bar{\delta}$ denotes the closure of $\delta$.
\end{prop}

\noindent The anticoarse space in the above proposition is defined as
    \[
        L^2_{\cross}(Q\leq N, \tau):= \bigcap \left\{ \ker{T}\colon T\in \text{Hom}_{Q-Q}(L^2(N,\tau), L^2(Q,\tau)\otimes L^2(Q,\tau)\right\},
    \]
and forms a closed $Q$-subbimodule of $L^2(N,\tau)$ (see \cite[Definition 1.1]{Hay18} and \cite[Section 2.1]{HJKE24}). 
The utility of Proposition~\ref{prop} comes from the absorption properties of this anticoarse space, and relatively mild assumptions about the inclusion $Q\leq N$ can even force $L^2_{\cross}(Q\leq N,\tau)= L^2(N,\tau)$ so that $\bar\delta \equiv 0$. This holds, for example, if $\dim_Q L^2(N,\tau) < \infty$ (see \cite[Proposition 2.2]{HJKE24}), or if $Q$ is diffuse and the inclusion is regular in the sense that $\mathcal{N}_N(Q)''=N$ (see \cite[Proposition 1.2]{Hay18}). To put it another way, the proposition tells us that $\delta$ being non-zero precludes the inclusion from having certain properties. The proof of Proposition~\ref{prop} (which can be found in Section~\ref{sec:proof_of_prop}) relies on a standard technique that mollifies the derivation into a bounded operator that is bilinear over its kernel (see, for example, \cite{Pet09,Dab10,Nel17,Lee24}).

The anticoarse space has been a vital tool in applications of $1$-bounded entropy to the structure of von Neumann algebras (see, for example, \cite{Hay18, HJKE24}), and the previous proposition appears to open the door to similar applications in the non-microstates setting. For example, if a tuple $(x_i)_{i\in I}$ of operators admits a conjugate system, then the corresponding free difference quotients are closable by \cite[Corollary 4.2]{Voi98} and have diffuse kernels by \cite[Proposition 8.18]{MS17}. In Corollary~\ref{cor}, these facts are leveraged via Proposition~\ref{prop} in order to obtain structural properties of the inclusion $W^*(x_j\colon j\in J)\leq W^*(x_i\colon i\in I)$ when $J\subsetneq I$ is a non-empty proper subset. In particular, the inclusion is irreducible provided $|J|\geq 2$, and this is ultimately what is used in the proof of Theorem~\ref{thm}. It should also be noted that an important application of Corollary~\ref{cor} is to finite $q$-deformed semicircular families, which are known to admit conjugate systems by \cite{MS23}.




\subsection*{Acknowledgments}

