\begin{lemma}
Let $(\bigarr_1, \imath_1, F_1)$ and $(\bigarr_2, \imath_2,F_2)$ be as in the preceding paragraph. For any linearly ordered multisets $J_1, J_2$ of hyperplanes of $\Harr_1$ and $\Harr_2$ respectively, we have the equality of forms 
\begin{equation*}
    \omega_{\bigarr_1,\imath_1,F_1, J_1}\wedge \omega_{\bigarr_2, \imath_2, F_2, J_2} = \omega_{\bigarr_1\cup_{\imath_1\imath_2}\bigarr_2, \imath_{12}, F_{12}, J_1\bullet J_2} 
\end{equation*}
in $\Omega_{PA}^{\bullet}(\SFM[\Harr], \R)$. 
\end{lemma}
\begin{proof}
Notice that we have a pullback diagram 
\begin{equation*}
    \begin{tikzpicture}
        \node[] (A) at (0,0) {$\SFM[\bigarr_1\cup_{\imath_{12}}\bigarr_2]$};
        \node[] (B) at (5,0) {$\SFM[\bigarr_1]$};
        \node[] (C) at (0,-3) {$\SFM[\bigarr_2]$};
        \node[] (D) at (5,-3) {$\SFM[\Harr]$};
        \draw[->] (A) -- (B) node[midway, above] {$\imath_1^{,-1}\overline{\pi}_{F'_1}$};
        \draw[->] (A) -- (C) node[midway, left] {$\imath^{,-1}_2\overline{\pi}_{F'_2}$};
        \draw[->] (B) -- (D) node[midway, right] {$\imath_1^{-1}\overline{\pi}_{F_1}$};
        \draw[->] (C) -- (D) node[midway, below] {$\imath_2^{-1}\overline{\pi}_{F_2}$};

    \end{tikzpicture}
\end{equation*}
This implies that we have the equalities 
\begin{align*}
    \omega_{\bigarr_1\cup_{\imath_1\imath_2}\bigarr_2, \imath_{12}, F_{12}, J_1\bullet J_2} &= \iota_{12}^{\star}(\overline{\pi}_{F_{12}})_{\star}(\theta_{J_1\bullet J_2})^{\star}(\prod_{H \in J_1\bullet J_2}\widetilde{f}_H)^{\star}(\vol_{J_1\bullet J_2}) \\
    &= \iota_{12}^{\star}(\overline{\pi}_{F_{12}})_{\star}\left(\biggl(\overline{\pi}_{F'_1}^{\star}\theta_{J_1}^{\star}(\prod_{H \in J_1} \widetilde{f}_H)^{\star}\vol_{J_1}\biggr) \wedge \biggl( \overline{\pi}_{F'_2}^{\star}\theta_{J_2}^{\star}(\prod_{H \in J_2} \widetilde{f}_H)^{\star}\vol_{J_2}\biggr)\right) \\ 
    &= \biggl(\imath_{12}^{\star}(\imath_1^{-1}\overline{\pi}_{F_1})_{\star}\theta_{J_1}^{\star}(\prod_{H \in J_1} \widetilde{f}_H)^{\star}\vol_{J_1} \biggr)\wedge \biggl(\imath_{12}^{\star}(\imath_2^{-1}\overline{\pi}_{F_2})_{\star}\theta_{J_2}^{\star}(\prod_{H \in J_2} \widetilde{f}_H)^{\star}\vol_{J_2}\biggr) \\
    &= \omega_{\bigarr_1,\imath_1,F_1, J_1}\wedge \omega_{\bigarr_2, \imath_2, F_2, J_2},
