\begin{madeflemma}[Modular element \cite{Stanley1971}]
    Let $F$ be an element in a geometric lattice $\L$. The following properties are equivalent: 
    \begin{enumerate}
        \item For all $F'\in \L$ we have the equality 
        \begin{equation*}
            \rk(F\wedge F') + \rk(F\vee F') = \rk(F) + \rk(F').
        \end{equation*}
        \item For all $A,B\in \L$ such that $A\leq F$, we have the equality $$F\wedge(A\vee B) = A \vee (F\wedge B).$$ 
        \item For all $A,B \in \L$ such that $A\leq B$, we have the equality $$ B\wedge(A\vee F) = A \vee (B\wedge F).$$
    \end{enumerate}
    If those properties are true we say that $F$ is \textit{modular}.
\end{madeflemma}
\begin{ex}\label{exmodular}
Note that an atom in a geometric lattice is always modular. At the other extreme, a coatom $F$ is modular if and only if taking the meet with $F$ drops the rank of a flat by at most one. For example for the geometric lattice $\L$ described in Example \ref{exgeolatt}, the line $\{a,b,c,d\}$ is modular in $\L$ because that line intersects every other line at a point of $\L$. On the other hand the line $\{a,e\}$ is not modular because that line has an empty intersection with the line $\{d',b\}$ for instance. 
\end{ex}
\begin{ex}\label{exmodulargraph}
Let $F$ be a flat of some geometric lattice $\L_G$ associated to graph $G= (V,E)$ (see Example \ref{exgeolattgraph}). Assume furthermore that $F$ is connected as a set of edges. By \cite[Proposition 4.3.2]{Brylawski_1975}, the flat $F$ is modular if and only if for all pairs of vertices $(u,v)$ in $V$, if $F$ contains a set of edges $J$ forming a path from $u$ to $v$ and there exists another path from $u$ to $v$ in $G$ which is vertex disjoint from $J$, then there exists an edge between $u$ and $v$ in $E$ (and so in $F$ as well). 
\end{ex}
We will need the following results about modularity.
\begin{lemma}[{\cite[Proposition 3.5]{Brylawski_1975}}]\label{lemmatransmod}
    Let $F_1 \leq F_2$ be two flats in a geometric lattice $\L$. If $F_1$ is modular in $[\zero,F_2]$ and $F_2$ is modular in $\L,$ then $F_1$ is modular in $\L$.
\end{lemma}
\begin{lemma}[{\cite[Proposition 3.8]{Brylawski_1975}}]\label{lemmaresmod}
Let $F$ be a modular flat of a geometric lattice $\L$. For any subset $J \subset \At(\L)$ containing $F$, $F$ is a modular flat of $\L_{|J}$. 
\end{lemma}
\begin{madef}[Modular extensions, modular diagrams] \label{defmoddiag}
Let $\L$ be a geometric lattice. 
\begin{itemize}
   \item  An \textit{extension of} $\L$ is the datum of a geometric lattice $\E$ together with an embedding $\imath: \L \rightarrow \E$ such that $\imath(\L)$ is an interval of the form $[\zero, F]$ with $F$ a flat of $\E$. In that case the element $F$ will be denoted $F_{\imath}$. 
   \item An extension $\imath:\L \hookrightarrow \E$ is called \textit{modular} if $F_{\imath}$ is modular in $\E$. 
    \item A \textit{modular diagram} $\Gamma$ of $\L$ is a triple $\Gamma = (\E, \imath, J)$ where $(\E, \imath)$ is a modular extension of $\L$ and $J$ is a linearly ordered multiset of atoms of $\E$. The multiset $J$ will be denoted $J_\Gamma$. 
     \item The degree of a modular diagram is defined by 
\begin{equation*}
    \deg \,(\E, \imath, J) = |J| - 2(\rk \medvee J - \rk (\medvee J)\wedge F).
\end{equation*}
\end{itemize}
\end{madef}
The definition of the modular extensions of a geometric lattice $\L$ may seem unnecessarily complicated, but this is the cleanest way of saying ``all the geometric lattices containing $\L$ as a modular flat'' in an equivariant-friendly way. By ``linearly ordered multiset of atoms of $\E$'' we mean a finite word in the alphabet $\At(\E).$ 
\begin{madef}\label{defMD}
Let $\L$ be a non-trivial geometric lattice. The $\Z$-graded vector space $\MD(\L)$ of modular diagrams of $\L$ is the vector space over $\Q$ freely spanned by the modular diagrams of $\L$ having degree as above, quotiented by the relations
    \begin{enumerate}[label={\arabic*)}]
        \item \label{rel1}$(\E, \imath,J) \sim -(\E, \imath, J')$ if $J$ and $J'$ differ by a transposition of their linear order. 
        \item \label{rel2}$(\E, \imath,J) \sim (\E', \imath', J')$ if there exists an embedding $\varphi: \E \hookrightarrow \E'$ such that $\rk(\E) = \rk(\E')$ and such that we have $\imath' = \varphi\circ \imath$ and $J' = \varphi(J)$. 
        \item \label{rel3}$(\E, \imath, J) \sim 0$ if $F_{\imath} \vee \bigvee J < \un_{\E}$.
        \item \label{rel4}$(\E, \imath, J) \sim 0$ if $\E$ is a product $\E_1\times\E_2$ with non-trivial $\E_1$ and $\E_2$, and we have $F_{\imath}\in \E_1\times \{\zero_{\E_2}\}$.
        \item \label{rel5} $(\E, \imath, J) \sim 0$ if there exists a modular element $F$ of $\E$ such that we have $F_{\imath} \leq F$ and such that the subset of elements of $J$ which are not below $F$ has cardinality $2$. 
    \end{enumerate}
\end{madef}
Note that we do not define the space of modular diagrams of a singleton, so we won't have access to $\Gra(1)$ for instance. This is because from the matroidal point of view we are unable to distinguish the case of one external vertex, that is, $\Gra(1)$ which is a silly object quasi-isomorphic to $\Q$, and the case of zero external vertex which we haven't defined and is quite complicated. Whenever we consider the space of modular diagrams of a geometric lattice it is implicitly assumed that this geometric lattice is non-trivial.

Note that relation \ref{rel1} implies that a modular diagram $\Gamma$ is zero in $\MD(\L)$ as soon as $J_{\Gamma}$ is not a set. A priori allowing $J_{\Gamma}$ to be a multiset will make our life easier later on. Note that in relation \ref{rel2} the embedding $\varphi$ could be an isomorphism. In the the braid case (geometric lattices associated to complete graphs) this will be responsible for the internal vertices (the vertices outside $F_{\imath}$) being unnumbered. Relation \ref{rel2} together with relation \ref{rel3} imply that we can always assume that we have $\At(\E) = F_{\imath}\cup J.$ Relations  \ref{rel3}, \ref{rel4} and \ref{rel5} are motivated by the results of the previous section. However, notice that relation \ref{rel4} is stronger than its geometric counterpart. This means that $\MD$ restricted to geometric lattices associated to complete graphs is not exactly $\Gra$. For instance the diagram 
