\begin{lemma}[\cite{birkhoff1940lattice}, Section IV.2]\label{lemmaisodiamond}
For any elements $F, F'$ in some geometric lattice $\E$, if $F$ is modular then taking the join with $F'$ defines an isomorphism of posets from $[F\wedge F', F]$ to $[F', F\vee F']$, with inverse given by taking the meet with $F$. 
\end{lemma}
We will denote this isomorphism by $\isomod_{F',F}$. We also have the following lemma. 
\begin{lemma}[{\cite[Lemma 2]{Stanley1971}\cite[Corollary 3.9]{Brylawski_1975}}]\label{lemmamodheredity}
For any elements $F,F'$ in a geometric lattice $\E$, if $F$ is modular in $\E$ then $F\vee F'$ is modular in $[F', \un]$ and $F\wedge F'$ is modular in $[\zero, F']$.
\end{lemma}
\begin{madeflemma}[Bridges, contractibility, contraction]
Let $\Gamma = (\E, \imath, J)$ be a modular diagram of $\L$. An atom $H \in J$ is called a \textit{bridge} if it is the only atom of $J$ not below some flat $F \geq F_{\imath}$. An atom $H \in J$ is called \textit{contractible} if $H$ is not a bridge and $H$ is not below $F_{\imath}$. The set of contractible atoms of $\Gamma$ will be denoted by $\Sc$. For any $H\in \Sc$, the \textit{contraction} $\Gamma / H$ of $\Gamma$ at $H$ is the modular diagram of $\L$ defined by $$\Gamma/H \coloneqq ([H, \un], H\vee \imath, H\vee (J\setminus \{H\}))$$ with linear order on $H\vee (J\setminus \{H\})$ induced by that on $J$. 
\end{madeflemma}
\begin{proof}
By Lemma \ref{lemmaisodiamond}, the morphism $H\vee \imath$ is an embedding with image $[H,H\vee F_{\imath}]\subset [H, \un]$ and by Lemma \ref{lemmamodheredity} the element $H\vee F_{\imath}$ is modular in $[H, \un]$, which implies that $([H, \un], H\vee \imath, H\vee J\setminus \{H\})$ is indeed a modular diagram of $\L$. 
\end{proof}
\begin{rmq}\label{rmkbridge}
Note that if a diagram $\Gamma = (\E, \imath, J)$ has a bridge $H$, unique atom of $J$ not below some flat $F \geq F_{\imath}$, then by relation \ref{rel3} in Definition \ref{defMD} we have $\Gamma \sim (\E_{|F \sqcup \{H\}}, \imath, J)$, but $\E_{|F \sqcup \{H\}}$ splits as the direct product $\E_{|F}\times [\zero, H]$ and so by relation \ref{rel3} we get $\Gamma \sim 0.$
\end{rmq}
\begin{ex}\label{excontraction}
Let us go back to the geometric lattice $\E$ described in Example \ref{exgeolatt}. As was noticed in Example \ref{exmodular} the inclusion $\imath: \L \coloneqq \E_{|\{a,b,c,d\}}\hookrightarrow \E$ is a modular extension. Let us consider the modular diagram $\Gamma = (\E, \imath, \{e\vartriangleleft b'\vartriangleleft c'\})$ of $\L$. We aim to compute the contraction $\Gamma/e$. Lemma \ref{lemmaisodiamond} tells us that we have an isomorphism $\vee_{e, \{a,b,c,d\}}:\L \simeq [e, \un]\subset \E$ given by taking the join with $e$. We have $e\vee b' = e\vee b$ which gives $\vee_{e, \{a,b,c,d\}}^{-1}(e\vee b')=b$, and $e\vee c' = e\vee c$ which gives $\vee_{e, \{a,b,c,d\}}^{-1}(e\vee c')=c$. This yields $$\Gamma /e = ([e,\un], \vee_{e, \{a,b,c,d\}}, \{e\vee b',e\vee c'\}) = (\L, \Id_{\L}, \{b,c\}).$$
Similar considerations give $\Gamma/b' = (\L, \Id_{\L}, \{b,a\})$ and $\Gamma/c' = (\L, \Id_{\L}, \{c,a\}).$
\end{ex}
\begin{rmq}\label{rmqdeg}
For all modular diagram $\Gamma$ and all contractible atom $H \in J_{\Gamma}^{contr}$ we have $\deg(\Gamma/H) = |J_{\Gamma}| - 1 - 2(\rk(\bigvee J) - \rk((\bigvee J) \wedge (F_{\imath} \vee H)))$, but by modularity of $F_{\imath}$ we have the equality $(\bigvee J)\wedge (F_{\imath} \vee H) = H \vee (\bigvee J \wedge F_{\imath})$ which gives $ \rk((\bigvee J)\wedge (F_{\imath} \vee H)) = \rk ((\bigvee J) \wedge F_{\imath}) + 1.$ This means that we have 
$$ \deg (\Gamma/H) =  |J_{\Gamma}| - 1 - 2(\rk(\bigvee J) - \rk((\bigvee J) \wedge F_{\imath}) - 1) = \deg(\Gamma) + 1.$$
\end{rmq}
We are now able to define the  differential of $\MD(\L)$.  
\begin{madeflemma}
The linear endomorphism $\d: \MD(\L)\rightarrow \MD(\L)$ taking value on modular diagrams $\Gamma = (\E, \imath, J= \{H_1 \vartriangleleft \cdots \vartriangleleft H_n\})$ 
\begin{equation*}
    \d(\Gamma) \coloneqq \sum_{H_i \in \Sc} (-1)^{i+1}\Gamma/H_i
\end{equation*}
is well-defined.
\end{madeflemma}
\begin{proof}
Let us check that the endomorphism $\d$ is compatible with relations \ref{rel1} to \ref{rel5} in Definition \ref{defMD}. For relation \ref{rel1} 1) one can see that if a modular diagram $\Gamma'$ can be obtained from another modular diagram $\Gamma$ by exchanging two atoms $H_p, H_{p+1}$ in the linear order of $J_{\Gamma}$ then for all $H \neq H_p, H_{p+1}$ we have $\Gamma'/H \sim -\Gamma/H$ because those two modular diagrams differ by a transposition of their linear order. Besides we obviously have $\Gamma/H_{p} = \Gamma'/H_{p}$ and $\Gamma/H_{p+1} = \Gamma'/H_{p+1}$ which finally gives $\d(\Gamma') \sim -\d(\Gamma)$. For relation \ref{rel2} the compatibility comes from the fact that if we have $\Gamma = (\E,\imath, J) \sim \Gamma' = (\E', \imath', J')$ via some embedding $\varphi:\E \hookrightarrow \E'$ then we have $\Gamma/H \sim \Gamma'/\varphi(H)$ via the embedding $\varphi_{|[H,\un]}.$ For relation \ref{rel3}, if for some modular diagram $\Gamma = (\E, \imath, J)$ we have $F_\imath \vee \bigvee J < \un_{\E}$ then one can see that for all $H \in \Sc$ we have $F_{H \vee \imath}\vee \bigvee(H\vee (J\setminus H))= F_{\imath}\vee \bigvee J < \un_{[H,\un]}$ which gives $\Gamma/H \sim 0$. For relation \ref{rel4}, if for some modular diagram $\Gamma = (\E, \imath, J)$ the geometric lattice $\E$ is a non-trivial product $\E'\times \E''$ with $\E'$ containing $F_{\imath}$, then for any $H\in\Sc$ the interval $[H, \E]$ is either isomorphic to $[H, \un_{\E'}]\times\E''$ or to $\E'\times [H, \un_{\E''}]$, which are both non-trivial products. Finally, for relation \ref{rel5} if a modular diagram $\Gamma = (\E, \imath, J)$ is such that we have exactly two atoms $H,H' \in J$ not below some modular flat $F\geq F_{\imath},$ then by relation \ref{rel3} we can assume that we have $F\vee H_1\vee H_2 = \un.$ First consider the case $\rk (F\vee H_1 \vee H_2) - \rk(F) = 1.$ In that case for all $H\in \Sc$ different from $H_1$ and $H_2$, the flats $H\vee H_1$ and $H\vee H_2$ are the only atoms of $[H,\un]$ not below $F$ and so by Remark \ref{rmkbridge} we have $\Gamma/H \sim 0$. Besides, by the diamond isomorphism lemma \ref{lemmaisodiamond} applied to $F$ the contractions $\Gamma/H_1$ and $\Gamma/H_2$ cancel out in $\d(\Gamma).$ In the case $\rk (F\vee H_1 \vee H_2) - \rk(F) = 2$ the contractions $\Gamma/H$ are equivalent to $0$ for all $H \neq H_1,H_2$ for the same reasons as above. Besides, the contraction $\Gamma/H_1$ is zero because $H_1\vee H_2$ is the unique atom of $H_1 \vee (J\setminus H_1)$ which is not below the modular flat $F\vee H_1 \in [H_1, \un]$, and the same goes for $\Gamma/H_2$. 
\end{proof}
\begin{ex}
Going back to the modular diagram $\Gamma$ considered in Example \ref{excontraction}, the computations in that example give 
\begin{equation*}
    \d(\Gamma) = (\L, \Id_{\L}, \{b,c\}) - (\L, \Id_{\L}, \{b,a\}) + (\L, \Id_{\L}, \{c,a\}).
\end{equation*}

\end{ex}
By Remark \ref{rmqdeg} the endomorphism $\d$ has degree $+1$. Besides, we have the following lemma. 
\begin{lemma}
The endomorphism $\d$ satisfies the equation $\d^2 = 0$.
\end{lemma}
\begin{proof}
Let $\Gamma = (\E, \imath, J= \{H_1 \vartriangleleft \cdots \vartriangleleft H_n\})$ be a modular diagram of $\L$, and let $H_i \vartriangleleft H_j \in \Sc$ be two contractible atoms. If the rank $2$ flat $H_i\vee H_j$ contains strictly more than two elements in $J$, then the term $(-1)^i(-1)^{j-1}(\Gamma/{H_i})/(H_i\vee H_j)$ appearing in the expansion of $\d^2(\Gamma)$ is $0$ because $J_{\Gamma/{H_i}}$ is not a set. Otherwise, that term is cancelled by $(-1)^j(-1)^i(\Gamma/H_j)/H_i\vee H_j$.
\end{proof}
Our next task is to define a commutative product on $\MD(\L)$ which is compatible with our newly defined differential. As we have seen in the previous section, at the level of modular extensions of $\L$ this product should be given by ``gluing extensions along $\L$''. In general gluing matroids along a minor, usually called 'amalgamation', is a non-trivial process. In particular, the gluing may not exist, or there may be several non-canonical gluings (see \cite[Section 11.4]{oxley}). However, in our case everything works out nicely because we are gluing along a modular flat. In this particular situation the gluing is called a \textit{generalized parallel connection} (see \cite[Section 5]{Brylawski_1975}). In this article we will prefer the more suggestive terminology of \textit{pushout}. This construction is indeed a pushout in a well-chosen category of geometric lattices but this will not play a role in this article. 
\begin{madef}[Pushout]\label{defpushout}
Let $\imath_1: \L \hookrightarrow \E_1$ and $\imath_2: \L \hookrightarrow \E_2$ be two modular extensions of $\L$. The \textit{pushout of $\E_1$ and $\E_2$ along $\L$}, denoted by $\E_1\cup_{\L}\E_2$, is the subposet of $\E_1\times \E_2$ consisting of elements $(F_1,F_2)\in \E_1\times \E_2$ such that we have the equality $\imath_{1}^{-1}(F_1\wedge F_{\imath_1}) = \imath_{2}^{-1}(F_2\wedge F_{\imath_2}).$ We denote by $\imath_{12}: \L \hookrightarrow \E_1\cup_{\L}\E_2$ the embedding sending a flat $F\in \L$ to $(\imath_{1}(F), \imath_{2}(F))$.
\end{madef}
\begin{ex}
If $\L = \{\star\}$ we simply get $\E_1\cup_{\L}\E_2 = \E_1\times \E_2,$ which is indeed the coproduct in the category of finite lattices for instance.
\end{ex}
\begin{ex}
Consider the geometric lattice $\L$ described in Example \ref{exgeolattres}. That geometric lattice is (isomorphic to) the pushout of the restrictions $\L_{|\{a,b,c,d\}}$ and $\L_{|\{a,b',c',d'\}}$ along the flat $\{a\}$ (which is modular in those restrictions because an atom is always modular). 
\end{ex}
\begin{ex}
If $\E_1$ and $\E_2$ are the geometric lattices associated to some graphs $G_1$, $G_2$, and $\L$ is the geometric lattice associated to some common modular subgraph $G$ then the pushout $\E_1\cup_{\L}\E_2$ is the geometric lattice associated to the graph obtained by gluing $G_1$ and $G_2$ along $G$.
\end{ex}
\begin{rmq}\label{rmkatomspushout}
    The atoms of a pushout $\E_1\cup_{\L}\E_2$ are the elements of the form $(H,\zero)$ for $H\in \At(\E_1)\setminus \iota_1(\L)$, the elements of the form $(\zero, H)$ for $H \in \At(\E_2)\setminus \iota_2(\L)$, and the elements of the form $(\iota_1(H), \iota_2(H))$ for $H \in \At(\L).$ We can thus naturally identify $\At(\E_1\cup_{\L}\E_2)$ with $\At(\E_1)\cup_{\At(\L)}\At(\E_2).$
\end{rmq}
\begin{rmq}\label{rmkembedpushout}
For any pushout $\E_1\cup_{\L}\E_2$ along $\imath_1, \imath_2$, we have an embedding $\imath_{\E_1}: \E_1\hookrightarrow \E_1\cup_{\L}\E_2$ defined by sending a flat $F\in \E_1$ to $(F, \imath_2\imath_1^{-1}(F\wedge F_{\imath_1})) \in \E_1\cup_{\L}\E_2$, and similarly for $\E_2$ by symmetry. Those embeddings give isomorphisms $\E_1 \simeq (\E_1\cup_{\L}\E_2)_{|\At(\E_1)}$ and $\E_2 \simeq (\E_1\cup_{\L}\E_2)_{|\At(\E_2)}$
\end{rmq}
We summarize the relevant properties of pushouts in the following lemma. We refer to \cite[Proposition 5.10]{Brylawski_1975} and \cite[Proposition 11.4.14]{oxley} for the proofs. 
\begin{lemma}\label{lemmapushout}
Let $\imath_1:\L \hookrightarrow \E_1$ and $\imath_2: \L \hookrightarrow \E_2$ be two modular extensions.
\begin{enumerate}[label={\arabic*)}]
    \item The poset $\E_1\cup_{\L} \E_2$ is a geometric lattice with rank given by $$\rk((F_1, F_2)) = \rk_{\E_1}(F_1) + \rk_{\E_2}(F_2) - \rk_{\L}(\imath_1^{-1}(F_1\wedge F_{\imath_1})).$$ Moreover, this is still true even if only one of $\imath_1$ and $\imath_2$ is modular. 
    \item The embedding $\imath_{\E_1}: \E_1 \hookrightarrow \E_1\cup_{\L}\E_2$ defined in Remark \ref{rmkembedpushout} is a modular extension. Moreover this is true even if only $\imath_2$ is modular.  
    \item The embedding $\imath_{12}$ is a modular extension.
    \item The modular extensions $\E_1\cup_\L\E_2$ and $\E_2\cup_{\L}\E_1$ are isomorphic. 
    \item If we have a third modular extension $\imath_3: \L \hookrightarrow \E_3$ then the modular extensions $(\E_1\cup_{\L} \E_2)\cup_{\L}\E_3$ and $\E_1\cup_\L(\E_2\cup_{\L}\E_3)$ are isomorphic. 
    \item If $H$ is an atom of $\E_1$ which is not below $F_{\imath_1}$ then the modular extension $(\E_1\cup_{\L}\E_2)_{\geq H}$ (with embedding $((H,\zero)\vee (\imath_1\times \imath_2))$) and the modular extension $(\E_1)_{\geq H}\cup_{\L}\E_2$ (with embedding $\L\hookrightarrow (\E_1)_{\geq H}$ given by $H\vee\imath_1$) are isomorphic.  
    \item For any $(F_1, F_2)\in \E_1\cup_\L\E_2$ the interval $[\zero, (F_1, F_2)]$ is isomorphic to $[\zero, F_1]\cup_{[\zero, \imath_{1}^{-1}(F_1\wedge F_{\imath_1})]}[\zero, F_2]$, and the interval $[(F_1, F_2), \un]$ is isomorphic to $[F_1, \un]\cup_{[\imath_{1}^{-1}(F_1\wedge F_{\imath_1}), \un]}[F_2,\un].$ 
    \item For any subset $S \subset \At(\E_1\cup_{\L}\E_2)$ containing $\At(\L)$, the restriction $(\E_1\cup_{\L}\E_2)_{|S}$ is isomorphic to the pushout $(\E_1)_{|S\cap \At(\E_1)}\cup_{\L}(\E_2)_{|S\cap \At(\E_2)}$.
\end{enumerate}
\end{lemma}
We will also need the following two lemmas.
\begin{lemma}[{\cite[Proposition 5.9]{Brylawski_1975}}]\label{lemmadetectionpushout}
Let $F_1$ and $F_2$ be two flats both containing a third flat $F$ in a geometric lattice $\E$. If $F$ is modular in $[\zero, F_1]$ then $\E$ is isomorphic to the pushout $[\zero, F_1]\cup_{[\zero,F]} [\zero, F_2]$ if and only if we have $[F,\un] \simeq [F,F_1]\times [F,F_2]$.   
\end{lemma}
\begin{lemma}\label{lemmamodularpushout}
Let $\imath_1:\L\hookrightarrow \E_1$ and $\imath_2:\L \hookrightarrow \E_2$ be two modular extensions of $\L$ and let $F$ be a flat of $\E_1$ greater than or equal to $F_{\imath_1}$. If $F$ is modular in $\E_1$ then $(F, \un_{\E_2})$ is modular in $\E_1\cup_{\L}\E_2$.
\end{lemma}
\begin{proof}
Let $(F_1,F_2)$ be a flat of $\E_1\cup_L\E_2$. We have 
\begin{align*}
    \rk((F_1,F_2)\vee (F, \un_{\E_2})) + \rk((F_1,F_2)\wedge (F, \un_{\E_2})) &= \rk((F_1\vee F, \un_{\E_2})) + \rk((F_1\wedge F, F_2)) \\
    &= \rk (F_1\vee F) + \rk(\E_2) - \rk(F_{\imath_1})\\
    & \,\,\,\,\,\,\,+ \rk(F_1\wedge F) + \rk(F_2) - \rk(F_1\wedge F\wedge F_2) \\
    &= \rk(F_1) + \rk(F) + \rk(\E_2) - \rk(F_{\imath_1})\\
    & \,\,\,\,\,\,\, + \rk(F_2) - \rk(F_1\wedge F\wedge F_2) \\
    &= \rk((F, \un_{\E_2})) + \rk((F_1,F_2)),
\end{align*}
where the third equality comes from the modularity of $F$ in $\E_1$. 
\end{proof}
We now proceed to define the commutative product on $\MD(\L)$. If $J_1$ and $J_2$ are two linearly ordered multisets in some common set, we denote by $J_1\cup J_2$ the multiset union of $J_1$ and $J_2$ with linear order given by concatenating the orders on $J_1$ and $J_2$, putting the elements of $J_1$ before the elements of $J_2$. 
\begin{madeflemma}
The bilinear endomorphism $\bullet:\MD(\L)\otimes \MD(\L) \rightarrow \MD(\L)$ taking value on modular diagrams 
\begin{equation*}
    (\E_1, \imath_1, J_1)\bullet(\E_2, \imath_1, J_2) \coloneqq (\E_1 \cup_{\L}\E_2, \imath_{12}, J_1\cup J_2),
\end{equation*}
is well-defined. 
\end{madeflemma}
Here we are taking the union $J_1\cup J_2$ in $\At(\E_1\cup_{\L}\E_2) = \At(\E_1)\cup_{\At(\L)}\At(\E_2)$ (see Remark \ref{rmkatomspushout}).
\begin{proof}
We must check that the bilinear endomorphism $\bullet$ is compatible with relations \ref{rel1} to \ref{rel5} in Definition \ref{defMD}. For relation \ref{rel1} it is obvious that if two modular diagrams $\Gamma_1,\Gamma_1'$ of $\E_1$ differ by a transposition of their linear order then $\Gamma_1\bullet \Gamma_2,\Gamma'_1 \bullet \Gamma_2$ will do too for any modular diagram $\Gamma_2$ of $\E_2$, which gives the result by symmetry. For relation \ref{rel2}, if $\Gamma_1, \Gamma_1'$ are two modular diagrams which are equivalent via some embedding $\varphi$, then by Lemma \ref{lemmapushout} item 8) the modular diagrams $\Gamma_1\bullet \Gamma_2$ and $\Gamma_1'\bullet \Gamma_2$ are also equivalent via some embedding for all $\Gamma_2$, which gives the result by symmetry. For relation \ref{rel3} if some modular diagram $\Gamma_1$ of $\E_1$ is such that we have $F_{\imath_1}\vee J_{\Gamma_1} < \un_{\E_1}$ then for all modular diagram $\Gamma_2$ in $\E_2$ we will have $(F_{\imath_1}, F_{\imath_2})\vee (J_{\Gamma_1}\cup J_{\Gamma_2}) \leq (F_{\imath_1}\vee J_{\Gamma_1}, \un_{\E_2}) < \un_{\E_1\cup_{\L}\E_2},$ which implies $\Gamma_1\bullet \Gamma_2 \sim 0$, which gives the result by symmetry. For relation \ref{rel4} assume we have two modular diagrams $\Gamma_1= (\E_1,\imath_1, J_1), \Gamma_2 = (\E_2, \imath_2, J_2)$ such that $\E_1$ is some non-trivial product $\E'_1\times \E''_1$ with $\E'_1$ containing $F_{\imath_1}$. One can check that the pushout $\E_1\cup_{\L}\E_2$ is isomorphic to the product $(\E'_1\cup_{\L}\E_2)\times \E''_1$ which implies $\Gamma_1\bullet \Gamma_2 \sim 0$. For relation \ref{rel5} if a modular diagram $\Gamma_1$ of $\E_1$ is such that $J_{\Gamma_1}$ contains exactly two atoms $H_1, H_2$ not below some modular flat $F \geq F_{\Gamma_1}$ then for all modular diagram $\Gamma_2$ in $\E_2$, by Lemma \ref{lemmamodularpushout} the element $(F_{\Gamma_1}, \un_{\E_2})$ is a modular flat of $\E_1\cup_\L\E_2$ greater than or equal to $(F_{\Gamma_1}, F_{\Gamma_2})$, and $H_1,H_2$ viewed as atoms of $\E_1\cup_{\L}\E_2$ are the unique atoms of $J_1\cup J_2$ not below that modular flat, and so we get $\Gamma_1\bullet \Gamma_2 \sim 0.$ 
\end{proof}
\begin{lemma}
The binary product $\bullet$ is graded commutative, associative and unitary. 
\end{lemma}
\begin{proof}
Commutativity is a direct consequence of Lemma \ref{lemmapushout} item 4), and associativity is a direct consequence of Lemma \ref{lemmapushout} item 5). The unit is given by the empty modular diagram with modular extension $\L \xrightarrow{\Id} \L$. 
\end{proof}
Next we must prove that the product and the differential on $\MD(\L)$ are compatible. 
\begin{lemma}\label{lemmaleibniz}
The binary product $\bullet$ satisfies the Leibniz identity
\begin{equation*}
    \d(\Gamma_1\bullet \Gamma_2) = \d(\Gamma_1)\bullet \Gamma_2 + (-1)^{\deg(\Gamma_1)}\Gamma_1\bullet \d(\Gamma_2). 
\end{equation*}
\end{lemma}
\begin{proof}
We can identify $J_{\Gamma_1\bullet \Gamma_2}^{contr} = J_{\Gamma_1}^{contr}\sqcup J_{\Gamma_2}^{contr}$. Furthermore by Lemma \ref{lemmapushout} item 6), for all $H$ in $J_{\Gamma_1}^{contr}$ (resp. in $J_{\Gamma_2}^{contr}$) we have $(\Gamma_1\bullet \Gamma_2)/H = (\Gamma_1/H)\bullet \Gamma_2$ (resp. $(\Gamma_1\bullet \Gamma_2)/H = \Gamma_1\bullet (\Gamma_2/H))$. This gives   
\begin{align*}
    \d(\Gamma_1\bullet \Gamma_2) &= \sum_{H_i \in J_{\Gamma_1\bullet \Gamma_2}^{contr}}(-1)^{i+1}(\Gamma_1\bullet \Gamma_2)/H_i \\
    &= \sum_{H_i \in J_{\Gamma_1}^{contr}}(-1)^{i+1}(\Gamma_1/H_i)\bullet \Gamma_2 + \sum_{H_j \in J_{\Gamma_2}^{contr}}(-1)^{|J_{\Gamma_1}|+j+1}\Gamma_1\bullet (\Gamma_2/H_j) \\
    &= \d(\Gamma_1)\bullet \Gamma_2 + (-1)^{\deg(\Gamma_1)}\Gamma_1\bullet \d(\Gamma_2).
\end{align*}
\end{proof}
From now on the notation $\MD(\L)$ refers to the cdga of modular diagrams with differential $\d$ and commutative product $\bullet$. The next proposition shows that $\MD(\L)$ is graded by the elements of $\L$, as is often the case for algebraic invariants of matroids. 
\begin{madefprop}\label{defgrading}
Let $\L$ be a geometric lattice. The $\L$-grading of a modular diagram $(\E, \imath, J) \in \MD(\L)$ is the flat of $\L$ defined by $\gr_{\L}(\E, \imath, J) \coloneqq \imath^{-1}((\bigvee J) \wedge F_{\imath}) \in \L$. If we denote by $\MD(\L, F)$ the subspace of modular diagrams of grading $F \in \L$, we have a decomposition of dg-complexes $\MD(\L) = \bigoplus_{F \in \L} \MD(\L, F)$. This decomposition is compatible with the commutative product $\bullet$ in the sense that we have $\MD(\L, F_1)\bullet \MD(\L,F_2) \subset \MD(\L, F_1\vee F_2).$ Furthermore for all $F\in \L$ we have an isomorphism of dg-complexes $\MD(\L, F) \simeq \MD([\zero, F], \un).$
\end{madefprop}
\begin{proof}
For all modular diagram $\Gamma = (\E, \imath, J)$ and for all contractible atom $H \in \Sc$, by modularity of $F_{\imath}$ we have 
\begin{align*}
    \gr_{\L}(\Gamma/H) & = (H\vee \imath)^{-1}((\medvee J) \wedge (H \vee F_{\imath})) \\
    &= (H\vee \imath)^{-1}(H \vee ((\medvee J) \wedge F_{\imath})) \\
    &= \imath^{-1}((\medvee J) \wedge F_{\imath}) \\
    &= \gr_{\L}(\Gamma).
\end{align*}
This implies that for all flat $F\in \L$ the subspace $\MD(\L,F)$ is a sub dg-complex of $\MD(\L)$, which gives the claimed decomposition. For all modular diagrams $\Gamma_1 = (\E_1, \imath_1, J_1), \Gamma_1 = (\E_1, \imath_1, J_1)$ of $\L$ we have
\begin{align*}
    F_{\imath_{12}}\wedge (\medvee (J_1 \cup J_2)) &= F_{\imath_{12}}\wedge (\medvee J_1 \vee \medvee J_2) \\
    &= F_{\imath_{12}}\wedge F_1\wedge (\medvee J_1 \vee \medvee J_2) \\
    &= F_{\imath_{12}}\wedge ( \medvee J_1 \vee (F_1\wedge \medvee J_2)) \\ 
    &= (F_{\imath_{12}} \wedge \medvee J_1)\vee (F_{\imath_{12}}\wedge \medvee J_2).
\end{align*}
Applying $\imath_{12}^{-1}$ we get $\gr_{\L}(\Gamma_1 \bullet \Gamma_2) = \gr_{\L}(\Gamma_1) \vee  \gr_{\L}(\Gamma_1),$ which gives the claimed inclusion. For all $F \in \L$ and all modular diagram $(\E, \imath, J)$ of grading $F$, by Lemma \ref{lemmamodheredity} the triple $(\E_{|\iota(F)\cup J}, \iota_{|F}, J)$ is a modular diagram of $[\zero,F]$, which has grading $\un_{[\zero,F]}$. This defines a morphism $\MD(\zero, F) \rightarrow \MD([\zero, F], \un).$ This morphism has an inverse given by sending a modular diagram $(\E, \imath, J)\in \MD([\zero, F], \un)$ to the modular diagram $(\L\cup_{[\zero, F]} \E, \imath_{\L}, J)\in \MD(\L, F)$. Note that even though $F$ is a priori not modular in $\L$, by assumption $F_{\imath}$ is modular in $\E$ which is enough to define the pushout $\L\cup_{[\zero, F]}\E$ (see Lemma \ref{lemmapushout} item 1)). Furthermore, the embedding $\L \hookrightarrow \L\cup_{[\zero, F]} \E$ is a modular extension by Lemma \ref{lemmapushout} item 2). 
\end{proof}
\begin{rmq}\label{rmkgradingzero}
Let $\Gamma = (\E, \imath, J) \in \MD(\L)$ be a modular diagram of $\L$-grading $\zero$ and such that $J$ is non-empty. If we denote $F = \bigvee J$, by relation \ref{rel2} we can assume $\At(\E) = \At(\L)\sqcup F$. By modularity of $F_{\imath}$ we have $\rk (\E) = \rk(F_{\imath}) + \rk(F)$, which implies that $\E$ decomposes as a direct product $\E \simeq \L\times [\zero, F]$. By relation \ref{rel4} this implies that we have $\Gamma \sim 0$. In other words, we have just proved that $\MD(\L, \zero)$ is isomorphic to $\Q$ concentrated in degree $0$, generated by the empty modular diagram. 
\end{rmq}
\begin{prop}
Let $\L_1$ and $\L_2$ be two geometric lattices. We have an isomorphism of cdgas $\MD(\L_1)\otimes \MD(\L_2) \simeq \MD(\L_1\times \L_2)$.
\end{prop}
\begin{proof}
One can easily check that if $\imath_1:\L_1\hookrightarrow\E_1$ and $\imath_2:\L_2 \hookrightarrow \E_2$ are two modular extensions, then the product embedding $\imath_1\times \imath_2:\L_1\times \L_2 \hookrightarrow \E_1 \times \E_2$ is also a modular extension. This allows us to define a morphism of cdgas $\MD(\L_1)\otimes \MD(\L_2) \rightarrow \MD(\L_1\times \L_2)$ by sending a pair of modular diagrams $(\E_1, \imath_1, J_1), (\E_2, \imath_2, J_2)$ to the modular diagram $(\E_1\times \E_2, \imath_1\times \imath_2, J_1 \sqcup J_2)$. By \cite[Corollary 3.16]{Brylawski_1975} any modular extension of $\L_1\times \L_2$ is a product of modular extensions of $\L_1$ and $\L_2$ respectively, which implies that the above morphism is an isomorphism. 
\end{proof}
\begin{prop}\label{propfree}
For any geometric lattice $\L$, the cdga $\MD(\L)$ is free as a graded commutative algebra. 
\end{prop}
\begin{proof}
Let us say that a modular extension $\imath: \L\hookrightarrow \E$ is irreducible if is not a pushout of two non-trivial modular extensions of $\L$. By Lemma \ref{lemmadetectionpushout} and Proposition \ref{propdecir} applied to $[F_{\imath}, \un]$ any modular extension decomposes uniquely as a pushout of irreducible modular extensions. This implies that the commutative graded algebra $\MD(\L)$ is free with generators given by equivalence classes of modular diagrams $\Gamma = (\E,\imath, J)$ such that $\imath$ is irreducible.
\end{proof}
We now turn to proving that in some good cases, the cdga $\MD(\L)$ is a model of $\OS(\L)$, meaning that we have a quasi-isomorphism of cdgas $\MD(\L) \simeq \OS(\L)$. The following proposition shows that we always have a well-defined morphism between those two cdgas.  
\begin{prop}\label{propmor}
For any geometric lattice $\L$ we have a morphism of cdgas $$\I_{\L}:\MD(\L) \rightarrow (\OS(\L),\d = 0)$$  defined on modular diagrams by $\I_{\L}(\E, \imath, J) \coloneqq e_{\imath^{-1}(J)}$ if no element of $J$ is contractible, and $\I_{\L}(\E, \imath, J) \coloneqq 0$ otherwise. 
\end{prop}
If the geometric lattice $\L$ is clear from the context we will simply write $\I$.
\begin{proof}
The fact that $\I$ is compatible with relations \ref{rel1} to \ref{rel5} in Definition \ref{defMD} is immediate, and so is the fact that $\I$ is a morphism of algebras. For the compatibility with the differential we need to show that for all modular diagrams $\Gamma \in \MD(\L)$ we have the equality $\I(\d(\Gamma)) = 0$. Let us denote $\Gamma = (\E, \imath, J)$. If no element of $J$ is contractible then we have $\d(\Gamma) = 0$ so the result follows. Furthermore, if $\rk \medvee J - \rk (\medvee J) \wedge F_{\imath}$ is strictly greater than $1$, then $\d(\Gamma)$ is a sum of modular diagrams all containing at least one contractible atom, which is sent to zero by $\I$. Let us assume that we have $\rk \medvee J - \rk (\medvee J) \wedge F_{\imath} = 1$. Notice that up to a sign we have the equality $$ \Gamma = \pm (\L, \Id_{\L}, J\setminus \Sc)\bullet (\E, \imath, \Sc)$$ and so by the Leibniz identity (Lemma \ref{lemmaleibniz}) we can assume $J = \Sc$. We now prove the result by induction on the cardinality of $J$. To simplify notations let us assume that $\imath$ is an inclusion. If $J$ has cardinality $3$ (the base case) and $\rk \bigvee J = 2$ then $\d(\Gamma)$ is already $0$. Otherwise if $\rk \bigvee J = 3$, let us denote $J = \{H_1,H_2,H_3\}$, $F = (\medvee J) \wedge F_{\imath}$, and $H_{ij} = (\vee_{H_i, F_{\imath}})^{-1}(H_i\vee H_j)$ for all $i\neq j \leq 3$. Note that for all $i \neq j \leq 3$ we have $H_{ij} = H_{ji} = (H_i \vee H_j)\wedge F.$ We can then compute $\I(\d(\Gamma)) = \pm\delta(e_{H_{12}}e_{ H_{13}}e_{H_{23}})$ which is zero since $\{H_{12}, H_{13}, H_{23}\}$ is a multiset of cardinality $3$ in the rank $2$ flat $F$. Next, assume that $J$ has cardinality $n$ for some integer $n$. Denote by $H_1 \vartriangleleft \cdots \vartriangleleft H_n$ the elements of $J$, which we can assume to be distinct. Denote by $H$ the element $(H_1\vee H_2)\wedge F_{\imath}$, which is an atom of $\L$. One can compute
\begin{align*}
    \d(\Gamma) - H\bullet \d(\Gamma\setminus H_2) + & H\bullet \d(\Gamma\setminus H_1) = \Gamma/H_1 - \Gamma/H_2 + \sum_{3 \leq k \leq n}(-1)^{k+1}\Gamma/H_k \\  
    &- H\bullet ((\Gamma\setminus H_2)/H_1) + \sum_{3\leq k\leq n}(-1)^{k+1} H\bullet ((\Gamma\setminus H_2)/H_k)\\
    & + H\bullet ((\Gamma\setminus H_1)/H_1) + \sum_{3 \leq k \leq n}(-1)^k H\bullet ((\Gamma\setminus H_1)/H_k) \\ 
    & = \sum_{3 \leq k \leq n }(-1)^{k+1}((H_1\vee H_k)\wedge F_{\imath})\bullet ((H_2\vee H_k)\wedge F_{\imath})\bullet((\Gamma\setminus H_1\setminus H_2)/H_k) \\
    & + \sum_{3 \leq k \leq n }(-1)^{k+1}H\bullet ((H_1\vee H_k)\wedge F_{\imath})\bullet((\Gamma\setminus H_1\setminus H_2)/H_k)\\ 
    &- \sum_{3 \leq k \leq n }(-1)^{k+1}H\bullet ((H_2\vee H_k)\wedge F_{\imath})\bullet((\Gamma\setminus H_1\setminus H_2)/H_k) \\
    &= \sum_{3 \leq k \leq n }(-1)^{k+1}\d(\{H_1, H_2, H_k\}) \bullet((\Gamma\setminus H_1\setminus H_2)/H_k),
\end{align*}
which gives the induction step. 
\end{proof}
Note that the above proof shows that $\I$ factors through the quadratic envelope of $\OS(\L)$ and so as soon as $\OS(\L)$ is not quadratic, the morphism $\I$ cannot be a quasi-isomorphism. For instance, if we consider the graphical geometric lattice $\L_{C_4}$ associated to the $4$-cycle $C_4$, with edges labeled from $1$ to $4$, then we have 
$$\OS(\L_{C_4}) = \frac{\bigwedge^{\bullet}[e_1, e_2, e_3, e_4]}{(e_1e_2e_3 - e_1e_2e_4 + e_1e_3e_4 - e_2e_3e_4)},$$ in which case $\I_{\L_{C_4}}$ is not a quasi-isomorphism. Determining which Orlik--Solomon algebras are quadratic is an interesting open question (see \cite[Section 4]{Falk_2001} \cite[Section 6]{Yuzvinsky_2001} for instance) which we will avoid in this article. Instead we will focus on a particular class of geometric lattices which are known to have quadratic (and even Koszul) Orlik--Solomon algebras, called supersolvable geometric lattices. To motivate their definition let us go back to braid arrangements. Recall from Section \ref{secgeo} that complements of braid arrangements admit a sequence of fibrations
\begin{equation*}
    \A_{\Br_n} \twoheadrightarrow \cdots \twoheadrightarrow \A_{\Br_2}\simeq \Cx^* \twoheadrightarrow \{*\}
\end{equation*}
given by forgetting points one after the other. This has strong consequences on the homotopy type of $\A_{\Br_n}$, for instance this implies that $\A_{\Br_n}$ is a $K(\pi, 1)$ space for all $n$. As explained in Section \ref{secgeo} the above fibrations can be seen at the combinatorial level, by noticing that the partitions 
\begin{equation*}
    12|3|\ldots|n < 123|4|\ldots|n < \cdots < 12\ldots n-1|n \in \Pi_n 
\end{equation*}
are modular elements of $\Pi_n$. This situation was generalized by Stanley \cite{Stanley_1972} as follow.
\begin{madef}[Supersolvable lattice]
    A geometric lattice is called \textit{supersolvable} if it admits a maximal chain of modular elements. 
\end{madef}
The terminology comes from supersolvable groups, whose lattice of subgroups admit a maximal chain of normal (and hence modular) subgroups. 
\begin{ex}
The geometric lattice $\L_G$ associated to a graph $G$ is supersolvable if and only if $G$ is chordal, meaning that every circuit in $G$ of length greater than or equal to $4$ has a chord. For instance the $4$-cycle $C_4$ does not have chords and so $\L_{C_4}$ is not supersolvable.
\end{ex}
The rest of this section will be devoted to proving the following theorem. 
\begin{theo}\label{theoqiso}
If a geometric lattice $\L$ is supersolvable then $\I_{\L}$ is a quasi-isomorphism. 
\end{theo}
One could vaguely sum up this result as saying that having enough modular flats implies having enough modular extensions. We must set the stage before starting the proof. Currently, our main issue is that we do not have any general method for producing modular extensions. Going back to partition lattices, in that case modular extensions of $\Pi_n$ are simply provided by embedding $\Pi_n$ in a bigger partition lattice $\Pi_n \hookrightarrow \Pi_{n+1}$. In terms of graphs, one can produce the $n+1$-th complete graph $K_{n+1}$ out of $K_n$ by first gluing two copies of $K_n$ along $K_{n-1}$ and then adding an edge between the two apexes. In matroidal terms we already know how to glue matroids (see Definition \ref{defpushout}) and there exists an explicit method for adding an element to a matroid in a controlled way, which we briefly describe now. We refer to \cite[Section 7.2]{oxley} for more details. The general idea is to freely add the element and then perform a so-called truncation along a modular cut. 
\begin{madef}[Modular cut]
Let $\L$ be a geometric lattice. A subset $\M \subset \L$ is called a \textit{modular cut} if it is upward-closed and if for all $F_1, F_2\in \M$ such that $\rk(F_1) + \rk(F_2) = \rk(F_1\wedge F_2) + \rk (F_1\vee F_2)$ we have $F_1 \wedge F_2 \in \M$. 
\end{madef}
\begin{madef}[Truncation]
Let $\M$ be a modular cut of a geometric lattice $\L$. The \textit{truncation of $\L$ along $\M$} is the geometric lattice 
$$ \Tr_{\M}(\L) \coloneqq \L \setminus \{F \in \L\setminus\M \, | \, F \textrm{ is covered by an element of } \M \}.$$
\end{madef}
One can easily check that if $\M$ is a modular cut of a geometric lattice $\L$ then the subset
 $\M\times \{e\} \subset \L\times \{\zero < e\}$ (for some symbol $e$) is a modular cut of $\L\times \{\zero < e\}$. 
\begin{madef}[Single-element extension]
Let $\M$ be a modular cut of a geometric lattice $\L$, and $e$ some symbol. The \textit{single-element extension of $\L$ along $\M$} is the geometric lattice $$\L\cup_{\M} e \coloneqq \Tr_{\M\times e}(\L\times \{\zero < e\}).$$
\end{madef}
Unless $\M$ contains an atom (which is a degenerate case), the atoms of $\L\cup_{\M} e$ are the atoms of $\L$ together with the symbol $e$. The map $\imath: \L \rightarrow \L\cup_{\M} e$ sending a flat $F$ to $(F, \zero)$ if $F\notin \M$ and to $(F, e)$ otherwise, is an embedding. Notice that by definition a flat $\imath(F)$ contains $e$ if and only if $F$ is in $\M$. In other words the choice of $\M$ dictates in which flats of $\L$ we add $e$. Going back to our example of complete graphs, the edge between the two apexes is added to every flat of $K_n\cup_{K_{n-1}} K_n$ containing two copies of an edge of $K_{n}$. The following definition generalizes this situation. 
\begin{madeflemma}[Symmetric extension]\label{lemmadefsymext}
Let $\L$ be a geometric lattice, $(\E, \imath)$ a modular extension of $\L$ and $F$ a modular coatom of $\L$. The subset 
$$\M \coloneqq \{F \in \L\cup_{[\zero, F]}\E \,\,  | \, \,\exists H \in \At(\L)\setminus [\zero, F] \, \textrm{ s.t. }\, (H, \imath(H))\leq F\}$$
is a modular cut of $\L\cup_{[\zero, F]}\E$. The associated single-element extension will be denoted by $\L\cup_F\E\cup_Fe$ and will be called the \textit{symmetric extension along $F$}. 
\end{madeflemma}
