\section{Proof of Theorem \ref{T.1.2}} \lb{S2}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We start with a crucial estimate for $\omega$ odd in $x_1$, which is a version of results from \cite{KS,ZlaEulerexp}.
For any $x\in[0,\infty)^2$ we let $\til x:=(-x_1,x_2)$, $\bar x:=(x_1,-x_2)$, and 
% $Q(x):=(x_1,\infty)\times(x_2,\infty)$.
$Q(r):=(0,\infty)^2\setminus \overline{B_{r}(0)}$.
%, and $P(x):=[0,x_1]\times [0,x_2]$.  
%In what follows, $C$ will always be some universal constant that may change between inequalities.
If $\omega \in (L^\infty\cap L^1)(\bbR\times\bbR^+)$ is odd in $x_1$ (we drop $t$ from the notation in most of our analysis), then the corresponding velocity $u$ is given by
\beq \lb{2.0}
\begin{split}
u_1(x) 
% = \frac 1{2\pi} \int_{[-1,1]^2} \sum_{n\in\bbZ^2} \frac{x_2-(y+2n)_2}{|x-(y+2n)|^2} \omega(t,y)dy 
& =  \frac {2x_1}{\pi} \int_{(0,\infty)^2}  \left( \frac{y_1(x_2-y_2)}{|x-y|^2 |x-\til y|^2}
-\frac{y_1(x_2+y_2)}{|x-\bar y|^2 |x+ y|^2}  \right) \omega(y) \, dy, \\
u_2(x) 
% = \frac 1{2\pi} \int_{[-1,1]^2} \sum_{n\in\bbZ^2} \frac{x_2-(y+2n)_2}{|x-(y+2n)|^2} \omega(t,y)dy 
& =  - \frac {2x_2}{\pi} \int_{(0,\infty)^2}  \left( \frac{y_2(x_1-y_1)}{|x-y|^2 |x-\bar y|^2}
-\frac{y_2(x_1+y_1)}{|x-\til y|^2 |x+ y|^2}  \right) \omega(y) \, dy.
\end{split}
\eeq
The leading term in both kernels as $|y|\to\infty$ is $-\frac{2y_1y_2}{|y|^4}$, and it turns out that after subtracting it, both integrals in \eqref{2.0} become bounded in all $x$ for which $\frac{x_2}{x_1}$ stays away from 0 and $\pm\infty$.

\begin{lemma}\lb{L.2.1}
There is $C\ge 1$ such that if  $\omega \in (L^\infty\cap L^1)(\bbR\times\bbR^+)$  is odd in $x_1$, then for each $x\in[0,\infty)^2\setminus\{(0,0)\}$ we have
\beq\lb{2.1}
u_j(x)=   (-1)^j \left( \frac 4\pi\int_{Q(|x|)}\frac{y_1y_2}{|y|^4} \omega(y) \, dy 
+  b_j(x)    \right) x_j  \qquad (j=1,2),
\eeq
%\begin{align}
%u_1(t,x)= &   x_1 \left( -\frac 4\pi\int_{Q(2x)}\frac{y_1y_2}{|y|^4} \omega(t,y) dy 
%+  B_1(t,x)    \right),  \lb{2.1}
%\\ u_2(t,x)= &  x_2 \left( \frac 4\pi\int_{Q(2x)}\frac{y_1y_2}{|y|^4} \omega(t,y) dy   
%+ B_2(t,x) \right),  \lb{2.2}
%\end{align}
where $b_1,b_2$ depend on $\omega$ and satisfy
\begin{align*}
|b_1(x)|\le C \|\omega\|_{L^\infty} \left( 1 + \min \left\{ \ln  \frac {x_1+x_2}{x_1}  , \frac{\|\nabla\omega\|_{L^\infty((0,2x_2)^2)}}{\|\omega\|_{L^\infty}} \, x_2 \right\} \right), %\lb{2.7}
\\ |b_2(x)|\le C\|\omega\|_{L^\infty} \left( 1 + \min \left\{ \ln  \frac {x_1+x_2}{x_2} , \frac{\|\nabla\omega\|_{L^\infty((0,2x_1)^2)}}{\|\omega\|_{L^\infty}}\,  x_1  \right\} \right). %\lb{2.8}
\end{align*}  
\end{lemma}

{\it Remark.}  
%1.  Notice that if $\omega_0$ is odd in $x_1,x_2$, then so is $\omega(t,\cdot)$.
%\smallskip
A similar result was proved on the torus in \cite{ZlaEulerexp}.  We will never use the second terms in both $\min$ here, and dropping them yields a result similar to one on the disc from \cite{KS}.  
%In that case $Q(2x)$ can be replaced by $Q(x)$ as well, which is done in \cite{KS}.
Our version mainly differs from these two results in the integration domain $Q(|x|)$, a change that --- while technically trivial --- allows for a better comparison of $u$ at different points.

\begin{proof}
First note that the claim of the lemma is equivalent to the one obtained when we replace $Q(|x|)$  by $Q'(2x):=(2x_1,\infty)\times(2x_2,\infty)$.  This is because the difference of these two domains is contained in $D:=[(0,2|x|)\times(\frac{|x|}2,\infty)]\cup [(\frac{|x|}2,\infty)\times(0,2|x|)]$, and
\[
\int_{D}\frac{y_1y_2}{|y|^4}  dy \le 2\int_{(0,2|x|)\times({|x|}/2,\infty)}\frac{y_1}{|y|^3}dy \le 8.
\]

This result with $Q''(2x):=(2x_1,1)\times(2x_2,1)$ in place of $Q'(2x)$ is proved in \cite{ZlaEulerexp} for bounded solutions on $(2\bbT)^2=[-1,1)^2$ (with $-1$ and 1 identified) that are odd in both $x_1$ and $x_2$, and for $x\in[0,\frac 12]^2\setminus\{(0,0)\}$.   This is the same as considering bounded solutions on $\bbR^2$ that are odd and 2-periodic in both variables, with all integrals being principal value ones.  We  consider here $L^\infty\cap L^1$ solutions on $\bbR^2$ that are odd in both variables (after an odd extension of $\omega$ to $\bbR^2$), so we can drop from the proof in \cite{ZlaEulerexp} all estimates involving integrals over $\bbR^2\setminus(-1,1)^2$, and  perform the estimates involving integrals over $(-1,1)^2$ instead with integrals over $\bbR^2$.  These all become appropriate integrals over $(0,1)^2$ resp.~$(0,\infty)^2$ due to the symmetries of $\omega$, as in \eqref{2.0}, and  the argument from \cite{ZlaEulerexp} now applies after simply changing all upper bounds 1 in the various integrals to $\infty$ (and $Q''(2x)$ to $Q'(2x)$).  We refer the reader to 
%the corresponding part of 
the short proof of \cite[Lemma 2.1]{ZlaEulerexp} 
%(a page if one drops the second terms in both $\min$ above) 
for details.
\end{proof}

Consider now points $(\pm\eps,0)\in\bbR^2$ with $\eps\in(0,1)$ and any $\omega \in (L^\infty\cap L^1)(\bbR^2)$ with $\|\omega\|_{L^\infty}=1$ and $\|\omega\|_{L^1}\le I$ for some fixed $I\ge 1$.  From \eqref{1.2} we see that the instantaneous approach velocity of the points $(\pm\eps,0)$  is
\[
u_1(-\eps,0)-u_1(\eps,0) = \frac {2\eps}{\pi} \int_{\bbR^2}  \frac{y_1y_2}{|(\eps,0)-y|^2 \,|(-\eps,0)-y|^2} \, \omega(y)dy, 
\]
which is clearly maximized when $\omega(y)=\sgn (y_1y_2)$ on the super-level set 
\[
L_\eps(a_{I,\eps}):=\left\{ y\in\bbR\,\bigg|\, \frac{|y_1y_2|}{|(\eps,0)-y|^2 \,|(-\eps,0)-y|^2} \ge a_{I,\eps} \right\} 
\]
with $a_{I,\eps}>0$ such that $|L_\eps(a_{I,\eps})|=I$, and $\omega=0$ on $\bbR^2\setminus L_\eps(a_{I,\eps})$.  Since $L_\eps(a_{I,\eps})$ is symmetric in both coordinates, we get
\beq\lb{2.20}
u_1(-\eps,0)-u_1(\eps,0) \le  \frac {8\eps}{\pi} \int_{(0,\infty)^2\cap L_\eps(a_{I,\eps})}  \frac{y_1y_2}{|(\eps,0)-y|^2 \,|(-\eps,0)-y|^2} \, dy, 
\eeq
with equality holding in the case described above.  But this maximal case is also realized by an $\omega\in (L^\infty\cap L^1)(\bbR\times\bbR^+)$ that is odd in $x_1$ (namely with $\omega\chi_{(0,\infty)^2}= \chi_{(0,\infty)^2\cap L_\eps(a_{I,\eps})}$), so Lemma~\ref{L.2.1} and oddness of $u_1$ in $x_1$ show that then
\[
\left| u_1(-\eps,0)-u_1(\eps,0)  - \frac {8\eps}\pi\int_{Q(\eps)\cap L_\eps(a_{I,\eps})}\frac{y_1y_2}{|y|^4} \,  dy 
  \right| \le 2 C\eps .
\]

For all small enough $\eps>0$ we clearly have $L_\eps(a_{I,\eps})\subseteq B_{10\sqrt I}(0)$, 
%and all $y\in\bbR^2$ with $\min\{|y_1|,|y_2|\}\ge (\frac {\pi}I)^{1/2} |y|^2$ belong to $L_\eps(a_{I,\eps})$ (the latter because then $\frac{|y_1y_2|}{|y^4|}\ge \frac\pi I > \frac{|x_1x_2|}{|x|^2}$ for all $x\notin B_{(I/\pi)^{1/2}}(0)$).
so we always obtain
\begin{align*}
u_1(-\eps,0)-u_1(\eps,0)  & \le  \frac {8\eps}\pi\int_{Q(\eps)\cap B_{10\sqrt I}(0)}\frac{y_1y_2}{|y|^4} \,  dy 
+ C\eps 
\\ & = \frac {8\eps}\pi   \ln\frac{10\sqrt I}\eps \int_0^{\pi/2}  \cos\theta \sin\theta \, d\theta +2C\eps
\\ & =  -\frac {4\eps\ln\eps}\pi  +\frac {4\ln(10\sqrt I)+2C\pi}\pi \,\eps.
\end{align*}

However, if also $ \|\nabla \omega\|_{L^\infty} \le \frac 1\eps$,
% (which happens when $\frac{|\omega(\eps,0)-\omega(-\eps,0)|}{2\eps}$ is close to $\|\nabla \omega\|_{L^\infty}$), 
then we can use $|\omega(y_1,y_2)-\omega(-y_1,y_2)|\le 2\|\nabla \omega\|_{L^\infty}|y_1|$ when $|y_1|\le \|\nabla \omega\|_{L^\infty}^{-1}$ (and cancellation of the kernel at these two points) in \eqref{2.20} to refine  the above estimates and obtain with $m:=\min\{\|\nabla \omega\|_{L^\infty}^{-1}, 1\}$,
\begin{align*}
u_1(-\eps,0)-u_1(\eps,0)  & \le  \frac {8\eps}\pi\int_{Q(\eps)\cap B_{10\sqrt I}(0)}\frac{y_1y_2}{|y|^4} \, \min\{\|\nabla \omega\|_{L^\infty}|y_1|,1\} \, dy 
+ 2C\eps 
\\ & \le   \frac {8\eps}\pi\int_{Q(m)\cap B_{10\sqrt I}(0)}\frac{y_1y_2}{|y|^4} \, dy 
+  \frac {8\eps \|\nabla \omega\|_{L^\infty}}\pi\int_{Q(\eps)\setminus Q(m)}\frac{dy}{|y|} \, dy 
+ 2C\eps 
\\ & \le   \frac {-4\ln m +4\ln(10\sqrt I)+(2C+16)\pi}\pi \,\eps.
\end{align*}

Rotational symmetry of the equation on $\bbR^2$ now shows that any two points with distance $\delta:=2\eps$ have instantaneous approach velocity no larger than  
\beq\lb{2.30}
\frac {2 \min\{-\ln \delta, - \ln m\}+C_I}\pi \,\delta,
\eeq
 with $C_I:=\frac 14 ({4\ln 2+4\ln(10\sqrt I)+(2C+16)\pi})$.   This means that 
 \[
 \frac d{dt} \|\nabla \omega(t,\cdot)\|_{L^\infty} \le \frac 2\pi  \big(\ln \max\{\|\nabla \omega(t,\cdot)\|_{L^\infty},1\} +C_I\big) \, \|\nabla \omega(t,\cdot)\|_{L^\infty}
 \]
 holds for solutions on $\bbR^2$ with  $\|\omega(0,\cdot)\|_{L^\infty}=1$ and $\|\omega(0,\cdot)\|_{L^1}\le I$ for all $t\ge 0$.

Since any solution on $\bbR\times\bbR^+$ also becomes a solution on $\bbR^2$ after odd reflextion in $x_2$, the same bound also holds for the former (when $\|\omega(0,\cdot)\|_{L^\infty}=1$ and $\|\omega(0,\cdot)\|_{L^1}\le \frac I2$).  Hence 
%points with distance $\delta(0)\in(0,1)$ at $t=0$ can be no closer than $\delta(t):=\exp(\ln\delta(0)e^{2t/\pi}-C't)$ at any time $t\ge 0$, so
\[
 \|\nabla \omega(t,\cdot)\|_{L^\infty} \le \exp\left( {\left| \ln \|\nabla \omega(0,\cdot)\|_{L^\infty} \right| e^{2t/\pi+C_I(1-e^{-2t/\pi}) /|\ln \|\nabla \omega(0,\cdot)\|_{L^\infty}|} } \right)
% \sup_{\delta\in(0,1)} \frac{\delta  \|\nabla \omega(0,\cdot)\|_{L^\infty}} {\exp(\ln\delta e^{2t/\pi}-C_It/\pi)}
\]
holds on both domains for all $t\ge 0$, and \eqref{1.3}  follows.

