\section{Proof of Theorem \ref{T.1.1}} \lb{S3}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Let
\[
g(s):=
%s^{ 1-|\ln s|^{-1/2}} = 
se^{|\ln s|^{1/2}} 
\]
for $s\ge 0$, and  for any $\eps\in[0,e^{-1}]$ let
\begin{align*}
\Omega_\eps := \big\{ x\in(0,\infty)^2\,\big|\, x_1\in(\eps,e^{-1}) \,\,\&\,\, x_2<g(x_1) \big \}.
%\\ D_\eps & := \big\{ x\in[(0,\infty)^2\cap B_{\sqrt 5}(0)] \setminus \overline{B_{\sqrt 5\,\eps}(0)} \,\big|\,  x_2<2x_1\} \big \},
\end{align*}
Then for all $s\in(0,e^{-4}]$ and $D_s:=\Omega_0\cap Q\big(\sqrt{s^2+g(s)^2}\,\big)\cap B_{e^{-1}}(0)$ we have
\beq \lb{6.1}
\frac 4\pi  \int_{D_s} \frac{y_1y_2}{|y|^4} dy =  h(s) |\ln s| ,
\eeq
for some $h:(0,e^{-4}]\to (0,\infty)$ such that 
\beq\lb{6.2}
\lim_{s\to 0} h(s)=\frac 2\pi.
\eeq
Indeed, these claims follow from
\[
\lim_{s\to 0} \frac{|\ln g(s)|}{|\ln s|}= \lim_{s\to 0} (1-|\ln s|^{-1/2}) =1,
\]
$\lim_{s\to 0} \frac{g(s)}s=\infty$, and
\[
\frac 4\pi  \int_0^{\pi/2}  \cos\theta \sin\theta \, d\theta = \frac 2\pi.
\]

Let $C$ be from Lemma \ref{L.2.1} and let $s_0\in(0,e^{-4}]$ be such that with the function
\beq\lb{6.11}
f(s):=2+ |\ln s|^{1/2} \ge 1+\ln\frac{s+g(s)}{s}
\eeq
(recall that $\ln (1+\beta ) \le 1+ \ln \beta$ for $\beta\ge 1$) we have
\[
h(s)|\ln s|\ge Cf(s) 
%\qquad \left( \ge C+C\ln\frac{s+g(s)}{s}  \right)
\]
 for all $s\in(0,s_0]$.  Also let
\[
C':=C\, \frac{g(s_0)}{s_0} \left( 1+\ln \frac{s_0+g(s_0)}{s_0} \right) 
= \max_{s\in[s_0,e^{-1}]} C\, \frac{g(s)}{s} \left( 1+\ln \frac{s+g(s)}{s} \right) .
\]

Next note that the unit outer normal vector to  $\Omega_\eps$ at $(s,g(s))$ is
$v_s(-1,\frac 1{g'(s)})$, where 
\[
v_s:=\sqrt{1+g'(s)^{-2}} \, ,
\]
and for $s\in(0,e^{-1}]$ we have
\[
g'(s)= e^{|\ln s|^{1/2}} \left(1-\frac 1{2|\ln s|^{1/2}} \right) \in\left(1, \frac{g(s)}s \right).
\]
We then let
\beq\lb{6.10}
\rho_0:= \frac{s_0}{2 |\ln s_0|^{1/2}} \le  s_0 \left( \left(1-\frac 1{2|\ln s_0|^{1/2}} \right)^{-1} -1\right) = \min_{s\in[s_0,e^{-1}]} \left( \frac{g(s)}{g'(s)}-s \right) . 
\eeq

If now $\eps\in(0,s_0]$, and  $\omega \in (L^\infty\cap L^1)(\bbR\times\bbR^+)$ is odd in $x_1$ and $\chi_{\Omega_\eps}\le \omega \chi_{(0,\infty)^2} \le \chi_{(0,\infty)^2}$, Lemma \ref{L.2.1}, our choice of $s_0$, and \eqref{6.1} show that the corresponding velocity $u$ satisfies 
\begin{align*}
(-1)^j u_j(s,g(s))\ge 0   & \qquad\text{for $s\in[\eps,s_0]$ and $j=1,2$}, %\lb{2.4}
\\ (-1)^j u_j(s,g(s)) \ge -C's  & \qquad\text{for $s\in[s_0,e^{-1}]$ and $j=1,2$}. %\lb{2.5}
\end{align*}  
Using also \eqref{6.2} and \eqref{6.11} gives us
\begin{align*}
% \eps^{-1} \sup_{s\in[0,\eps]} u_1(\eps,s) & \le c\ln\eps+2C,    %\lb{2.6}
 \eps^{-1} \sup_{s\in[0,g(\eps)]} u_1(\eps,s)   \le  -h(\eps)|\ln\eps|+Cf(\eps)+3C  + e \inf_{s\in[0,1]} u_1(e^{-1},s),
 \end{align*}  
%after using \eqref{2.2} and
%\[
%\frac 4\pi  \int_{2A}^\infty  \int_{0}^{2} \frac{y_1y_2}{|y|^4} dy_2  dy_1 \le \frac 1{9\pi} \le C.
%\]
and simple scaling then yields the following result.

\begin{lemma}\lb{L.6.1}
Let $\eps\in(0,s_0]$ and $\alpha>0$.  If  $\omega \in (L^\infty\cap L^1)(\bbR\times\bbR^+)$  is odd in $x_1$ and $\chi_{\alpha \Omega_\eps}\le \omega \chi_{(0,\infty)^2} \le \chi_{(0,\infty)^2}$,  then 
\begin{align}
(-1)^j u_j(s\alpha,g(s)\alpha)\ge 0   & \qquad\text{for $s\in[\eps, s_0]$ and $j=1,2$}, \lb{6.3}
\\ (-1)^j u_j(s\alpha,g(s)\alpha) \ge -C's\alpha  & \qquad\text{for $s\in[s_0,e^{-1}]$ and $j=1,2$}, \lb{6.4}
\end{align}  
as well as
\begin{align}
%(\eps\alpha)^{-1} \sup_{s\in[0,\eps\alpha]} u_1(\eps\alpha,s) & \le c\ln\eps +2C,    \lb{2.6}
 (\eps\alpha)^{-1} \sup_{s\in[0,g(\eps)\alpha]} u_1(\eps\alpha,s)   
 \le  -h(\eps)|\ln\eps|+Cf(\eps)+3C  + (e^{-1}\alpha)^{-1} \inf_{s\in[0,\alpha]} u_1(e^{-1}\alpha,s) .   \lb{6.5}
\end{align}  
\end{lemma}

Consider  now some decreasing $\eps:[0,\infty)\to (0,s_0]$ (to be determined),  and let $\omega$ be an odd-in-$x_1$ solution to \eqref{1.1} with  $\omega(0,\cdot) \in C^\infty_c(\bbR\times\bbR^+)$ such that $\chi_{\Omega_{\eps(0)}}\le \omega (0,\cdot)\chi_{(0,\infty)^2} \le \chi_{(0,\infty)^2}$.  Then of course $\|\omega(t,\cdot)\|_{L^\infty}=1$ for all $t\ge 0$.  Also let $\alpha:[0,\infty)\to(0,1]$ satisfy $\alpha(0)=1$ and 
\beq \lb{6.6}
\alpha'(t)=  -3(C's_0\rho_0^{-1}+C)\alpha(t) +  e \inf_{s\in[0,\alpha(t)]} u_1(t,e^{-1}\alpha(t),s)  
\eeq
for $t\ge 0$, with $u(t,\cdot)$ the velocity for $\omega(t,\cdot)$.  Note that Lemma \ref{L.2.1} shows that 
\beq \lb{6.7}
\alpha'(t)\le -3C' s_0\rho_0^{-1}\alpha(t) \qquad (<0),
\eeq
 and  $\alpha(t)$  remains positive because from \eqref{2.30} we see that
\begin{align*}
 |u_1(t,e^{-1}\alpha(t),s)  |  \le   |u_1(t,e^{-1}\alpha(t),s) -  u_1(t,0,s)| \le
\frac {2 |\ln (e^{-1}\alpha(t))| +C_{\frac 12\|\omega(0,\cdot)\|_{L^1}}}{\pi e} \, \alpha(t).
 \end{align*}

We now want to show that the boundary of the level set $\{ \omega(t,\cdot)=1 \}$ can never enter  $\alpha(t)\Omega_{\eps(t)}$ for appropriate functions $\eps$.
At any given time $t\ge 0$, the outer normal velocity of the boundary of the evolving domain $\alpha(t)\Omega_{\eps(t)}$ is $e^{-1}\alpha'(t)$ on  $\{(e^{-1}\alpha(t),s)\,|\, s\in[0, \alpha(t)]\}$, where the unit outer normal vector is $(1,0)$ and 
\[
u(t,e^{-1}\alpha(t),s)\cdot (1,0) = u_1(t,e^{-1}\alpha(t),s) > e^{-1} {\alpha'(t)}
\]
by \eqref{6.6}.  From \eqref{6.10} and \eqref{6.7} we see that that velocity is
\[
\alpha'(t)(s,g(s))\cdot v_s(-1,{g'(s)}^{-1}) 
\begin{cases}
 <0 & s\le s_0
\\ \le \rho_0 v_s \alpha'(t) \le - 3C's_0 v_s\alpha(t)  & s\ge s_0,
\end{cases}
\]
on $\{(s\alpha(t),g(s)\alpha(t))\,|\, s\in[\eps(t),e^{-1}]\}$, where the unit outer normal vector is $v_s(-1,\frac 1{g'(s)})$ and 
\[
u(t,s\alpha(t),g(s)\alpha(t))\cdot v_s(-1,{g'(s)}^{-1}) \ge  0
\]
by \eqref{6.3} when $s\in [\eps(t),s_0]$, while
\[
u(t,s\alpha(t),g(s)\alpha(t))\cdot v_s(-1,{g'(s)}^{-1}) \ge  -2C'v_s \,s\alpha(t) > - 3C's_0 v_s\alpha(t) 
\]
by \eqref{6.4} when $s\in [s_0, e^{-1}]$.
(Note that in both corners we consider vectors normal to both segments of $\alpha(t)\Omega_{\eps(t)}$ meeting at that corner.)   Finally, the velocity is $-(\eps(t)\alpha(t))'$ on $\{(\eps(t)\alpha(t),s)\,|\, s\in[0,g(\eps(t))\alpha(t)]\}$, where the unit outer normal vector is $(-1,0)$ and 
\[
u(t,\eps(t)\alpha(t),s)\cdot (-1,0) 
%= - u_1(t,\eps(t)\alpha(t),s) 
\ge \big[ h(\eps(t))|\ln\eps(t)|-Cf(\eps(t))-3C \big]  \eps(t)\alpha(t) - e\, {\eps(t)} \inf_{s\in[0,\alpha(t)]} u_1(t,e^{-1}\alpha(t),s). 
\]
by \eqref{6.5}.  Recalling \eqref{6.6} and the definition of $f$, the last expression will be strictly greater than $ -(\eps(t)\alpha(t))'$ if 
\beq\lb{6.9}
\eps'(t) > -\big[  h(\eps(t))|\ln\eps(t)| -C|\ln\eps(t)|^{1/2}-8C-3C' s_0\rho_0^{-1} \big] \eps(t)
\eeq
holds for all $t\ge 0$.  If this is satisfied,  the strict inequalities above  mean that the boundary of  $\{ \omega(t,\cdot)=1 \}$ can indeed never enter $\alpha(t)\Omega_{\eps(t)}$.  

So then $\omega(t,\eps(t)\alpha(t),s)=1$ for all $t\ge 0$ and $s\in(0,g(\eps(t))\alpha(t)]$.  Since  $\omega(t,0,s)=0$ for these $s$ by symmetry, it follows that
\beq\lb{6.12}
\|\nabla \omega(t,\cdot)\|_{L^\infty} \ge (\eps(t)\alpha(t))^{-1} \ge \eps(t)^{-1} 
\eeq
 for all $t\ge 0$.  But \eqref{6.2} shows that when $\eps(0)>0$ is small enough, \eqref{6.9} has a decreasing solution satisfying 
 \[
 \lim_{t\to\infty} \frac {\ln(-\ln \eps(t))}t = \frac 2\pi.
 \]
So  \eqref{6.12} yields
 \[
 \liminf_{t\to\infty} \frac{ \ln\ln \|\nabla \omega(t,\cdot)\|_{L^\infty} } t\ge \frac 2\pi,
 \]
 which together with \eqref{1.4} finishes the proof. 
