\section{One-loop effective potential}
\label{appendix one loop}

   The one-loop effective potential for a particle in
$d$ dimensions is given by \cite{Schwartz_2013}
\begin{equation}
V_{\mathrm{eff}}^{(d)}=(-)^{F+1} \frac{n_{\mathrm{dof}}}{2^{d+1} \pi^{d / 2}} \int_{s_0}^{\infty} \frac{d s}{s^{\frac{d}{2}+1}} e^{-s m^2}=(-)^{F+1} \frac{n_{\mathrm{dof}}}{2^{d+1} \pi^{d / 2}} s_0^{-d / 2} E_{\frac{d}{2}+1}\left(m^2 s_0\right), \label{eq: oneloopEd}
\end{equation}
where $F$ is the fermion number, $n_{dof}$ counts the degrees of freedom and $E_{\frac{d}{2}+1}$ is the exponential integral function. The expansion of $E_{\frac{d}{2}+1}$ for small $z$ is
\begin{equation}
E_n(z)=\frac{(-z)^{n-1}}{(n-1)!}(\psi(n)-\ln z)-\sum_{\substack{k=0 \\ k \neq n-1}}^{\infty} \frac{(-z)^k}{k!(1-n+k)},
\end{equation}
with $\psi(n)$ being the Digamma function. Substituting for $d=4$ and truncating to the first three terms, we arrive at 
\begin{equation}
    E_3(z) = \frac{z^2}{2}\left(\psi(3)-\log z\right) \, + \frac{1}{2} - z \, + \mathcal{O}(z^3).
\end{equation}
Therefore, putting altogether,  for e.g., the contribution of scalars in the loop, one gets
\begin{equation}
    V_{b} \simeq  \frac{1}{2^6 \pi^2}\left(-\Lambda^4 + 2 m^2\Lambda^2 -m^4\log\left(\frac{\Lambda^2}{m^2}\right) - m^4\psi(3) \right) + \mathcal{O}\left(\frac{m^6}{\Lambda^6}\right).
    \label{Vb}
\end{equation}
Since $\psi(3)=0.922784$, we can approximate the one-loop potential for bosonic particles as
\begin{equation}
    V_{b}^{eff} \simeq  \frac{1}{2^6 \pi^2}\left(-\Lambda^4 + 2 m^2\Lambda^2 -m^4\log\left(\frac{\Lambda^2}{m^2}\right)  \right).
\end{equation}
%
We are interested in supersymmetric theories in which both bosons and fermions circulate in the loop. The total one-loop potential is then given by the sum over all species \cite{PhysRevD.7.2887,PhysRevD.7.1888}
%
\begin{equation}
    V_{total}^{eff} = \frac{1}{2^6 \pi^2}\left(-\text{Str}\mathcal{M}^0\Lambda^4 + 2\,{\rm Str}\mathcal{M}^2\Lambda^2 - 2\, {\rm Str}\mathcal{M}^4 \log\left(\frac{\Lambda}{\mathcal{M}}\right)\right)
\end{equation}
where we have defined
\begin{equation}
    {\rm Str}\mathcal{M}^a = \sum_n (-1)^{2j_n}(2j_n + 1)( m_n)^a,\quad a=0,2,4,
\end{equation}


\subsection{Str\mathtitles{\mathcal{M}^4} computation}\label{app: strm4}

In Section~\ref{section3}, we derived the one-loop effective potential that arises in supersymmetric theories. The general expression takes the form
\begin{equation}
    V_{total}^{eff} = \frac{1}{2^6 \pi^2}\left(-\text{Str}\mathcal{M}^0\Lambda^4 + 2\,{\rm Str}\mathcal{M}^2\Lambda^2 - 2\, {\rm Str}\mathcal{M}^4 \log\left(\frac{\Lambda}{\mathcal{M}}\right)\right), \label{oneloop}
\end{equation}
where the supertraces $\text{Str} \mathcal{M}^k$ are defined by
\begin{equation}
\text{Str} \mathcal{M}^a = \sum_n (-1)^{2j_n}(2j_n + 1)(m_n)^a.
\end{equation}
As discussed in the main text, the dominant contribution to the potential comes from the second term in Eq.~\eqref{oneloop}. The first term vanishes in theories with spontaneous supersymmetry breaking, and the third term, involving $\text{Str}  \mathcal{M}^4$, is typically subleading compared to $\text{Str}  \mathcal{M}^2$.
\newline
In the remainder of this appendix, we explicitly compute this contribution and demonstrate that, for towers of states with varying values of $p$, the term involving $\text{Str}  \mathcal{M}^4$ remains suppressed.

The general expression of this term for the chiral states in a tower of mass $m$, after SUSY breaking, is given by 
\begin{equation}
     {\rm Str}\mathcal{M}^4 \log\left(\frac{\Lambda}{n^{1/p} m}\right) = \frac{2}{p} \sum_n \left[(n^{2/p}m^2 + m_{3/2}^2)^2 - n^{4/p} m^4\right]\log\frac{N}{n}.\label{strm4ap}
\end{equation}
Let us compute this expression for different $p$'s:
\vspace{1em}

\subsubsection*{\underline{$p=1$}}
\begin{align}
    {\rm Str}\mathcal{M}^4 \log\left(\frac{\Lambda}{n m}\right) =& 2 \sum_n \left((n^2m^2 + m_{3/2}^2)^2 - n^4 m^4\right)\log\frac{N}{n}\\
    &\simeq 4 \sum_n n^2 m^2 m_{3/2}^2 \log\frac{N}{n} = 4 m_{3/2}^2 m^2 \sum_n n^2\log N - n^2\log n \notag \\
    & 4 m_{3/2}^2 m^2\left(\frac{1}{6}N(N+1)(2N+1)\log N + \zeta^{'}(-2)-\zeta^{(1,0)}(-2,N+1) \right)\notag
\end{align}
Expanding for large $N$, and taking into account that the characteristic mass (in Planck units) of the tower $m$ scales as $m^2\simeq N^{-3}$ with the number of species, we obtain,
\begin{equation}
   m_{3/2}^2\left( \frac{4}{9}-\frac{1}{3 N^2}+\mathcal{O}(N^{-4})\right).
\end{equation}




\subsubsection*{\underline{$p=2$}}


\begin{align}
    {\rm Str}\mathcal{M}^4 \log\left(\frac{\Lambda}{n^{1/2} m}\right) =&  \sum_n \left((n m^2 + \mu^2)^2 - n^2 m^4\right)\log\frac{N}{n}\\
    &\simeq 2 \sum_n n m^2 \mu^2 \log\frac{N}{n} = 2 \mu^2 m^2 \sum_n n \log N - n\log n \notag\\
    & 2 \mu^2 m^2\left(\frac{1}{2} N (N+1) \log (N)-\log (H(N)) \right) \notag
\end{align}
where $H(N)$ is the hyperfactorial. The hyperfactorial series expansion is given by,
\begin{equation}
   \left(
  A N^{1/12}
  + \frac{A}{720} N^{-23/12}
  + O\left(N^{-37/12}\right)
\right)
e^{\left(
  \frac{1}{4} \left(2 \log N - 1\right) N^2
  + \frac{N}{2} \log N 
  + O\left(N^{-4}\right)
\right)}
\end{equation}
where $A$ is the Glaisher constant. At leading order we obtain, 
\begin{equation}
     {\rm Str}\mathcal{M}^4 \log\left(\frac{\Lambda}{n^{1/2} m}\right)\sim 2 \mu^2 m^2\left(\frac{1}{4}N^2 + \mathcal{O}\log (N^{})\right)\simeq \frac{1}{2}\mu^2 M_{\rm P}^2
\end{equation}
{\underline{String limit}
\vspace{1em}

One could borrow the expression \eqref{strm4ap} and take the limit for infinite $p$, which yields
   \begin{equation}
     {\rm Str}\mathcal{M}^4 \log\left(\frac{\Lambda}{n^{1/p} m}\right) \simeq   lim_{p\rightarrow \infty}   \,\frac{2}{p} \sum_n \left[(n^{2/p}m^2 + m_{3/2}^2)^2 - n^{4/p} m^4\right] \log\left(\frac{\Lambda}{ \Lambda}\right) =0\ .
\end{equation}
However, the actual computation involves summing the string states undergoing the Hagerdorn degeneration. One starts with
\begin{equation}
    \sum_n^{N} d(n) \,\,n\,m_n^2 \,\, m_{3/2}^2\, \log\frac{\Lambda}{n^{1/2}m_n}
\end{equation}
where we can already substitute $m_n=M_s\,$, $d(n)\sim e^{\sqrt{n}}$ and $\Lambda/M_s = N_t^{1/2}$. Therefore, one arrives at
\begin{equation}
  \frac{1}{2}  M_s^2\,m_{3/2}^2\, \sum_n^{N} e^{\sqrt{n}}\,n\,\log\frac{N}{n}.
\end{equation}
The asymptotic result yields
\begin{equation}
    \sum_n^N e^{\sqrt{n}}\,n\,\log \frac{N}{n}\sim 4 Ne^{\sqrt{N}}
\end{equation}
Therefore, putting altogether
\begin{equation}
    2\,M_s^2\,m_{3/2}^2\,Ne^{\sqrt{N}}
\end{equation}
Using that \cite{Castellano:2022bvr},
\begin{equation}
   \left( \frac{M_{\rm P}}{M_s}\right)^2 \simeq 2 N^{3/2}\,e^{\sqrt{N}},
\end{equation}
we obtain
\begin{equation}
   M_{\rm P}^2\, m_{3/2}^2\,\frac{1}{N^{1/2}}\simeq  M_{\rm P}^2\, m_{3/2}^2\,\frac{1}{\log N_t},
\end{equation}
which is a log correction.

Therefore, based on the previous results, we can confirm that the important term in the one-loop potential is given by Str$\mathcal{M}^2$, up to subleading corrections from higher terms in the expansion of \eqref{eq: oneloopEd}




\section{Adding semi-realistic D6-branes to cancel RR tadpoles}\label{apB}

As we said in this particular $\mathbb{Z}_2\times \mathbb{Z}_2$ orientifold model, the fluxes are quantised in multiples of eight, which makes it difficult to cancel out tadpoles. One can slightly improve the situation by the addition of D6-branes. 
This orientifold  contains four types of $O(6)$ planes and the structure of the tadpole conditions for the choice of fluxes of the
previous section (see \cite{Camara:2005dc} for notation ) is
%
\beq
\sum_a N_a n_a^1n_a^2n_a^3\ +\ \frac {1}{2} (h_0m + a_1q_1+a_2q_2+a_3q_3 ) \ = \ 16
\eeq
\beq
\sum_a n_a^1m_a^2m_a^3=\sum_a m_a^1n_a^2m_a^3=\sum_a m_a^1m_a^2n_a^3= \ =\ -16 \ .
\eeq
%
Here $n_a,m_a$, $a=1,2,3$  are integer numbers giving the wrapping numbers of the $D6_a$-branes around the $x-y$ directions of the three
tori. For simplicity it is assumed that all $D6$-branes pass through the sum $\mathbb{Z}_2\times \mathbb{Z}_2$ orbifold point. Each stack of N  $D6$-branes 
(and orbifold images) gives rise to a gauge group $U(N/2)$, so $N$ must be even \cite{Marchesano:2004xz}.

Let us consider the set of D6-branes with wrapping numbers as in table
(\ref{tablaSM}) \cite{Marchesano:2004xz}.   One can see that the massless spectrum of chiral multiplets 
at the intersections  (excluding singlets for simplicity of presentation) is that of   (\ref{espectro}). So it consists of three generations of 
a Pati-Salam group containing the SM fields and a number of $SU(2)_L,SU(2)_R$ doublets.  
 It is easy to check that, in the absence of fluxes, all RR-tadpoles cancel for $N_f=40$.  Note that the additional branes $h_1,h_2$ are 
 crucial because they precisely cancel the 3 twisted tadpoles, and their contribution to the untwisted one  $(n_a^1n_a^2n_a^3)$  is negative 
 and equal to. (-96), allowing for a larger contribution from fluxes.
