Let us now match the LG expansions with $w_{n}^{(j)}(uz;a)$ ($j=0,\pm1$). Firstly, $\lim_{z \to \infty} \eta_{N,0}(u,\alpha,z)=0$. Furthermore, from \cref{eq27}, we note that $\phi \to 0$ as $z \to \infty$, and hence from \cref{eq32,eq33,eq34,eq35} $\lim_{z \to \infty}\mathrm{E}_{s}(\alpha,\phi)=\mathrm{E}_{s}(\alpha,0)=0$. Thus, from \cref{eq36}, $W_{0}(u,a,z)$ has the same unique (recessive) behaviour at $\Re(z)=+\infty$ regardless of the value of $N$, and therefore is independent of this parameter. Likewise for $W_{1}(u,a,z)$ and $W_{-1}^{\pm}(u,a,z)$ with their recessive properties at $\Re(z)=-\infty$ and $z=0^{\pm}$, respectively; for the latter, note from \cref{eq24,eq25} that $\exp(\pm u\xi) \to 0$ as $z \to 0^{\pm}$.

Now, for solutions recessive at $z=\alpha_{0}=+\infty$, from \cref{eq06,eq15,eq23,eq36} we have
%%%%%%%%%%%
\begin{equation} 
\label{eq45}
w_{n}^{(0)}(uz;a)
=C_{n}^{(0)}(a) f^{-1/4}(a,z)W_{0}(u,a,z),
\end{equation}
%%%%%%%%%%%
where, from comparing both sides as $z \to \infty$,
%%%%%%%%%%%
\begin{equation} 
\label{eq46}
C_{n}^{(0)}(a)
=\frac{e^{-u(1+\alpha)\pi i/2} }{\sqrt{2}\,\{4(1+\alpha)\}^{u/2}}
\left\{\frac{e}{2u(1+\alpha)}\right\}^{u\alpha/2}.
\end{equation}
%%%%%%%%%%%

We do a similar matching of the solutions of \cref{eq13} with $f^{-1/4}(a,z)W_{1}(u,a,z)$ and $f^{-1/4}(a,z)W_{-1}(u,a,z)$, again by finding the multiplicative constants by comparison at $z=\infty$ (even though the latter is not recessive at infinity). For the former, we have for solutions recessive at $z=\alpha_{1}=-\infty$
%%%%%%%%%%%
\begin{equation} 
\label{eq47}
w_{n}^{(1)}(uz;a)
=C_{n}^{(1)}(a) f^{-1/4}(a,z)W_{1}(u,a,z),
\end{equation}
%%%%%%%%%%%
for some constant $C_{n}^{(1)}(a)$. As we remarked, to determine this we again compare both sides at $z=\infty$. From \cref{eq09,eq15,eq23,eq37,eq47} and the fact that $\lim_{z \to \infty} \eta_{N,1}(u,a,z)=0$, we find that
%%%%%%%%%%%
\begin{equation} 
\label{eq48}
C_{n}^{(1)}(a)
=\frac{e^{u(1+\alpha)\pi i/2} }{\sqrt{2}}
\left(\frac{1+\alpha}{4}\right)^{u/2}
\left\{\frac{u(1+\alpha)}{2e}\right\}^{u\alpha/2}.
\end{equation}
%%%%%%%%%%%

Finally, the LG solutions $f^{-1/4}(a,z)W_{-1}^{\pm}(u,a,z)$ as given by \cref{eq38,eq39} are both recessive at $z=0$, and hence to within a multiplicative constant are the same, and both proportional to $w_{n}^{(-1)}(uz;a)$. Thus we have
%%%%%%%%%%%
\begin{equation} 
\label{eq49}
w_{n}^{(-1)}(uz;a)
=C_{n}^{(-1)\pm}(a)f^{-1/4}(a,z)W_{-1}^{\pm}(u,a,z),
\end{equation}
%%%%%%%%%%%
where from \cref{eq11,eq15,eq23,eq38}
%%%%%%%%%%%
\begin{equation} 
\label{eq50}
C_{n}^{(-1)+}(a)
=\frac{e^{u(1+\alpha)\pi i/2} (1+\alpha)^{u/2}}
{2^{n+1}\Gamma(n+a-1)}
\left\{\frac{u(1+\alpha)}{2e}\right\}^{u\alpha/2}.
\end{equation}
%%%%%%%%%%%
Similarly, from \cref{eq06,eq09,eq12,eq15,eq23,eq39},
%%%%%%%%%%%
\begin{equation} 
\label{eq51}
C_{n}^{(-1)-}(a)
=\frac{ie^{u(1+\alpha)\pi i/2}}{\sqrt{2}\,
\left\{4(1+\alpha)\right\}^{u/2}n!}
\left\{\frac{e}{2u(1+\alpha)}\right\}^{u\alpha/2}.
\end{equation}
%%%%%%%%%%%


\section{Airy expansions}
\label{sec:Airy}

Following \cite{Dunster:2017:COA} for some appropriately selected functions $\mathcal{A}(u,a,z)$ and $\mathcal{B}(u,a,z)$ let us define
%%%%%%%%%%%%%%%%%%
\begin{equation}
\label{eq52}
Y_{l}(u,a,z)
=\mathrm{Ai}_{l} \left(u^{2/3}\zeta\right)\mathcal{A}(u,a,z)
+\mathrm{Ai}'_{l} \left(u^{2/3}\zeta \right)\mathcal{B}(u,a,z)
\quad (l=0,\pm 1),
\end{equation}
%%%%%%%%%%%%%%%%%%
where $\zeta$ is given by \cref{eq20,eq21}, and we have used Olver's notation for complex-valued Airy functions $\mathrm{Ai}_{j}(z) =\mathrm{Ai}(z e^{-2\pi ij/3})$ ($j=0,\pm 1$) (see \cite[\S 9.2(iii)]{NIST:DLMF}). From (\cite[Eq. 9.2.12]{NIST:DLMF}) we note that
%%%%%%%%%%%%%%%%%%
\begin{equation}
\label{eq53}
\mathrm{Ai}(z) 
=e^{\pi i/3}\mathrm{Ai}_{1}(z) 
+e^{-\pi i/3}\mathrm{Ai}_{-1}(z).
\end{equation}
%%%%%%%%%%%%%%%%%%

Now $Y_{0}(u,a,z)$ is recessive as $z \to \alpha_{0} = +\infty$ since $\Re(\zeta) \to +\infty$ in this limit (cf. \cite[Eq. 9.7.5]{NIST:DLMF}). In addition, $Y_{1}(u,a,z)$ is recessive as $z \to \alpha_{1} = -\infty$ since $\Re(\zeta e^{-2\pi i/3}) \to +\infty$ in this limit. We therefore define $\mathcal{A}(u,a,z)$ and $\mathcal{B}(u,a,z)$ uniquely using the pair of equations
%%%%%%%%%%%
\begin{equation}
\label{eq54}
(-1)^{n} \frac{e^{a\pi i}}{n!} w^{(0)}_{n}(uz; a) 
= e^{-\pi i/3}
\left\{\frac{\zeta}{f(a,z)}\right\}^{1/4} Y_{0}(u,a,z),
\end{equation}
%%%%%%%%%%%
and
%%%%%%%%%%%
\begin{equation}
\label{eq55}
\frac{1}{\Gamma(n + a - 1)} w^{(1)}_{n}(uz; a)
=\left\{\frac{\zeta}{f(a,z)}\right\}^{1/4} Y_{1}(u,a,z),
\end{equation}
%%%%%%%%%%%
noting the similar recessive behaviour at the respective singularities in both cases. The constants appearing in these equations were chosen so that
%%%%%%%%%%%
\begin{equation} 
\label{eq56}
w^{(-1)}_{n}(z; a) = e^{\pi i/3}
\left\{\frac{\zeta}{f(a,z)}\right\}^{1/4} Y_{-1}(u,a,z),
\end{equation}
%%%%%%%%%%%
which comes from \cref{eq12,eq53}. The significance is that both functions in this relation share the same recessive property at $z=\alpha_{-1}=0$ ($\Re(\zeta e^{2\pi i/3}) = +\infty$).

Now, from \cref{eq52} and the Airy functions Wronskian \cite[Eq. 9.2.8]{NIST:DLMF}, on choosing any pair from \cref{eq54,eq55,eq56} and solving the system, we arrive at the following three representations for $\mathcal{A}(u,a,z)$ and $\mathcal{B}(u,a,z)$:
%%%%%%%%%%%
\begin{multline} 
\label{eq57}
\mathcal{A}(u,a,z)=2\pi\left\{\frac{f(a,z)}{\zeta}\right\}^{1/4}
\left\{ (-1)^{n} \frac{e^{(a+\frac16)\pi i}}{n!}
w^{(0)}_{n}(uz; a)\mathrm{Ai}_{\pm 1}'\left(u^{2/3}\zeta\right) 
\right.
\\
\left. -\lambda_{\pm 1} 
w^{(\pm 1)}_{n}(uz; a)\mathrm{Ai}'\left(u^{2/3}\zeta\right) 
\right\},
\end{multline}
%%%%%%%%%%%
%%%%%%%%%%%
\begin{multline} 
\label{eq58}
\mathcal{A}(u,a,z)=2\pi\left\{\frac{f(a,z)}{\zeta}\right\}^{1/4}
\left\{ \frac{i}{\Gamma(n + a - 1)}
w^{(1)}_{n}(uz; a)\mathrm{Ai}_{-1}'\left(u^{2/3}\zeta\right) 
\right.
\\
\left. -e^{\pi i/6}w^{(-1)}_{n}(uz; a)\mathrm{Ai}_{1}'\left(u^{2/3}\zeta\right) 
\right\},
\end{multline}
%%%%%%%%%%%
%%%%%%%%%%%
\begin{multline} 
\label{eq59}
\mathcal{B}(u,a,z)=-2\pi\left\{\frac{f(a,z)}{\zeta}\right\}^{1/4}
\left\{ (-1)^{n} \frac{e^{(a+\frac16)\pi i}}{n!}
w^{(0)}_{n}(uz; a)\mathrm{Ai}_{\pm 1}\left(u^{2/3}\zeta\right) 
\right.
\\
\left. -\lambda_{\pm 1}
w^{(\pm 1)}_{n}(uz; a)\mathrm{Ai}\left(u^{2/3}\zeta\right) 
\right\},
\end{multline}
%%%%%%%%%%%
and
%%%%%%%%%%%
\begin{multline} 
\label{eq60}
\mathcal{B}(u,a,z)=-2\pi\left\{\frac{f(a,z)}{\zeta}\right\}^{1/4}
\left\{ \frac{i}{\Gamma(n + a - 1)} 
w^{(1)}_{n}(uz; a)\mathrm{Ai}_{-1}\left(u^{2/3}\zeta\right) 
\right.
\\
\left. -e^{\pi i/6}w^{(-1)}_{n}(uz; a)\mathrm{Ai}_{1}\left(u^{2/3}\zeta\right) 
\right\},
\end{multline}
%%%%%%%%%%%
where
%%%%%%%%%%%
\begin{equation} 
\label{eq61}
\lambda_{1}=\frac{e^{-\pi i/6}}{\Gamma(n + a - 1)}, \quad
\lambda_{-1}=e^{-\pi i/6}.
\end{equation}
%%%%%%%%%%%

To obtain our desired asymptotic expansions we simply use the LG expansions for the functions involved. For the Airy functions, we have from \cite[Thm. 2.4]{Dunster:2021:SEB} that these LG expansions are given by
%%%%%%%%%%%
\begin{equation}
\label{eq62}
\mathrm{Ai}\left(u^{2/3}\zeta\right) 
\sim \frac{1}{2\pi ^{1/2}u^{1/6}\zeta^{1/4}}
\exp \left\{ -u\xi +\sum\limits_{s=1}^{\infty}
{(-1) ^{s}\frac{a_{s}}{s u^{s}\xi ^{s}}}\right\},
\end{equation}
%%%%%%%%%%%
and 
%%%%%%%%%%%
\begin{equation}
\label{eq63}
\mathrm{Ai}^{\prime }\left( u^{2/3}\zeta\right)
\sim-\frac{u^{1/6}\zeta ^{1/4}}
{2\pi ^{1/2}}\exp \left\{-u\xi
+\sum\limits_{s=1}^{\infty}{(-1)^{s}
\frac{\tilde{a}_{s}}{s u^{s}\xi ^{s}}}\right\},
\end{equation}
%%%%%%%%%%%
as $u \xi \to \infty$, uniformly for $|\arg(\zeta)|\leq \frac{2}{3}\pi$ (or equivalently $|\arg(\xi) | \leq \pi $). These regions are not maximal, but suffice for our purposes (and similarly for the expansions for $\mathrm{Ai}_{\pm 1}(u^{2/3}\zeta)$ and their derivatives). Here 
%%%%%%%%%%%%%%%%%%
\begin{equation}
\label{eq64}
a_{1}=a_{2}=\tfrac{5}{72}, \;
\tilde{a}_{1}=\tilde{a}_{2}=-\tfrac{7}{72},
\end{equation}
%%%%%%%%%%%%%%%%%%
with $a_{s}$ and $\tilde{{a}}_{s}$ ($s=3,4,5,\ldots $) satisfying the recursion formula
%%%%%%%%%%%%%%%%%%
\begin{equation}
\label{eq65}
a_{s+1}=\frac{1}{2}\left(s+1\right) a_{s}+\frac{1}{2}
\sum\limits_{j=1}^{s-1}{a_{j}a_{s-j}} 
\quad (s=2,3,4,\ldots).
\end{equation}
%%%%%%%%%%%%%%%%%%

Next, for $z \in Z_{0,1}$ (see \cref{fig:Z0UZ1}), we use the expressions \cref{eq57,eq59} (with upper signs taken for each $\pm1$), and in these we insert the LG expansions \cref{eq36,eq37,eq45,eq46,eq47,eq48} for $w^{(0)}_{n}(uz; a)$ and $w^{(1)}_{n}(uz; a)$, as well as the ones above for the Airy functions. As a result, we arrive at
%%%%%%%%%%%
\begin{multline}
\label{eq66}
\mathcal{A}(u,a,z)
\sim K_{1}(u,\alpha)\exp\left\{\sum\limits_{s=1}^{\infty}
\frac{\tilde{\mathcal{E}}_{s}(a,z)}{u^{s}}\right\}
\\
+K_{2}(u,\alpha)\exp\left\{\sum\limits_{s=1}^{\infty}(-1)^{s}
\frac{\tilde{\mathcal{E}}_{s}(a,z)}{u^{s}}\right\},
\end{multline}
%%%%%%%%%%%
and
%%%%%%%%%%%
\begin{multline}
\label{eq67}
\mathcal{B}(u,a,z)
\sim \frac{1}
{u^{1/3} \zeta^{1/2}}
\left[K_{1}(u,\alpha)\exp\left\{\sum\limits_{s=1}^{\infty}
\frac{\mathcal{E}_{s}(a,z)}{u^{s}}\right\}
\right.
\\
\left.
-K_{2}(u,\alpha)\exp\left\{\sum
\limits_{s=1}^{\infty}(-1)^{s}
\frac{\mathcal{E}_{s}(a,z)}{u^{s}}\right\}
\right],
\end{multline}
%%%%%%%%%%%
where
%%%%%%%%%%%
\begin{equation} 
\label{eq68}
K_{1}(u,\alpha)
=-e^{\pi i/12}e^{(n+a)\pi i/2}\sqrt{\frac{\pi}{2}}
\frac{u^{1/6}}{\Gamma(n+a-1)}\left(\frac{1+\alpha}{4}
\right)^{u/2}\left\{\frac{u(1+\alpha)}{2e}\right\}^{u\alpha/2},
\end{equation}
%%%%%%%%%%%
%%%%%%%%%%%
\begin{equation} 
\label{eq69}
K_{2}(u,\alpha)
=-e^{\pi i/12}e^{(n+a)\pi i/2}\sqrt{\frac{\pi}{2}}
\frac{u^{1/6}}{n!\{4(1+\alpha)\}^{u/2}}
\left\{\frac{e}{2u(1+\alpha)}\right\}^{u\alpha/2},
\end{equation}
%%%%%%%%%%%
%%%%%%%%%%%
\begin{equation} 
\label{eq70}
\tilde{\mathcal{E}}_{s}(a,z)
=\mathrm{E}_{s}(\alpha,\phi)
+(-1)^{s}\frac{\tilde{a}_{s}}{s\xi^{s}},
\end{equation}
%%%%%%%%%%%
and
%%%%%%%%%%%
\begin{equation} 
\label{eq71}
\mathcal{E}_{s}(a,z)
=\mathrm{E}_{s}(\alpha,\phi)
+(-1)^{s}\frac{a_{s}}{s\xi^{s}}.
\end{equation}
%%%%%%%%%%%

If we follow the same procedure using \cref{eq57,eq59} (with lower signs taken for each $\pm1$) for $z \in Z_{-1,0}$ (see \cref{fig:Zm1UZO}), and using \cref{eq58,eq60} (with lower signs taken for each $\pm1$) for $z \in Z_{-1,1}$ (see \cref{fig:Zm1UZ1}), we obtain the same expansions \cref{eq66,eq67}. Thus, these are valid in $Z_{0,-1}\cup Z_{0,1}\cup Z_{-1,1}$, which upon examination of \cref{fig:Z0UZ1,fig:Zm1UZO,fig:Zm1UZ1} consists of the whole upper half-plane $0 \leq \arg(z) \leq \frac12 \pi$ except for the turning point $z=z_{1}$ (and we shall address this excluded point shortly).

To simplify the expansions, we shall use the identity
%%%%%%%%%%%
\begin{equation} 
\label{eq72}
c_{1}w_{1}+c_{2}w_{2}=\sqrt{c_{1}c_{2}}
\left[\exp\left\{\tfrac12
\ln\left(c_{1}/c_{2}\right)\right\}w_{1}
+\exp\left\{-\tfrac12
\ln\left(c_{1}/c_{2}\right)\right\}w_{2}\right],
\end{equation}
%%%%%%%%%%%
for any $c_{1,2} \neq 0$. In order to do so, from \cref{eq68}, \cref{eq69} and \cite[Eqs. 5.5.5 and 5.11.1]{NIST:DLMF} we have
%%%%%%%%%%%
\begin{multline} 
\label{eq73}
\frac12 \ln \left\{\frac{K_{1}(u,\alpha)}
{K_{2}(u,\alpha)}\right\}
=\frac12 \biggl[u\alpha(\ln(u)-1)+u(1+\alpha)\ln(1+\alpha) 
\biggr.
\\ 
\left.
+\ln\left\{\Gamma\left(u+\frac12\right)\right\}
-\ln\left\{\Gamma\left(u+u\alpha+\frac12\right)\right\}\right]
\sim \sum_{s=0}^{\infty}\frac{d_{2s+1}(\alpha)}{u^{2s+1}}
\quad (u \to \infty),
\end{multline}
%%%%%%%%%%%
observing that this series only involves odd powers of $1/u$. The first four terms are found to be
%%%%%%%%%%%
\begin{equation} 
\label{eq74}
d_{1}(\alpha)=-\frac{\alpha}{48(1+\alpha)},
\end{equation}
%%%%%%%%%%%
%%%%%%%%%%%
\begin{equation} 
\label{eq75}
d_{3}(\alpha)=\frac{7\alpha\left(3+3\alpha
+\alpha^{2}\right)}{5760(1+\alpha)^{3}},
\end{equation}
%%%%%%%%%%%
%%%%%%%%%%%
\begin{equation} 
\label{eq76}
d_{5}(\alpha)=-\frac{31\alpha\left(5+10\alpha
+10\alpha^{2}+5\alpha^{3}+\alpha^{4}\right)}
{80640(1+\alpha)^{5}},
\end{equation}
%%%%%%%%%%%
and
%%%%%%%%%%%
\begin{equation} 
\label{eq77}
d_{7}(\alpha)
=\frac{127\alpha\left(7+21\alpha+35\alpha^{2}
+35\alpha^{3}+21\alpha^{4}+7\alpha^{5}+\alpha^{6}\right)}
{430080(1+\alpha)^{7}}.
\end{equation}
%%%%%%%%%%%
Then, from \cref{eq66,eq67,eq68,eq69,eq72,eq73}, as $u \to \infty$,
%%%%%%%%%%%
\begin{equation} 
\label{eq78}
\mathcal{A}(u,a,z)=\frac{e^{5\pi i/6}e^{(u+a)\pi i/2}
u^{1/6}}{2^{n-1}}
\left\{\frac{\pi }{2^{a}n!\,\Gamma(n+a-1)}
\right\}^{1/2}A(u,a,z),
\end{equation}
%%%%%%%%%%%
and
%%%%%%%%%%%
\begin{equation} 
\label{eq79}
\mathcal{B}(u,a,z)=\frac{e^{5\pi i/6}e^{(u+a)\pi i/2} 
u^{1/6}}{2^{n-1}}
\left\{\frac{\pi }{2^{a}n!\,\Gamma(n+a-1)}
\right\}^{1/2}B(u,a,z),
\end{equation}
%%%%%%%%%%%
where
%%%%%%%%%%%
\begin{equation} 
\label{eq80}
A(u,a,z) \sim 
\exp \left\{ \sum\limits_{s=1}^{\infty}
\frac{\tilde{\mathcal{E}}_{2s}(a,z) }{u^{2s}}\right\} 
\cosh \left\{ \sum\limits_{s=0}^{\infty}
\frac{\tilde{\mathcal{E}}_{2s+1}(a,z)
+d_{2s+1}(\alpha)}
{u^{2s+1}}\right\},
\end{equation}
%%%%%%%%%%%
%%%%%%%%%%%
\begin{equation} 
\label{eq81}
B(u,a,z) \sim \frac{1}{u^{1/3}\zeta^{1/2}}
\exp \left\{ \sum\limits_{s=1}^{\infty}
\frac{\mathcal{E}_{2s}(a,z) }{u^{2s}}\right\} 
\sinh \left\{ \sum\limits_{s=0}^{\infty}
\frac{\mathcal{E}_{2s+1}(a,z)
+d_{2s+1}(\alpha)}
{u^{2s+1}}\right\},
\end{equation}
%%%%%%%%%%%
uniformly for $0 \leq \arg(z) \leq \pi$ with $|z-z_{1}| \geq \delta >0$, under the condition \cref{eq17}.


\begin{lemma}
\label{lem:odd-mero}
Each $(z-z_{1})^{1/2}\{\mathrm{E}_{2s+1}(\alpha,\phi)+d_{2s+1}(\alpha)\}$ ($s=0,1,2,\ldots$), regarded as a function of $z$, is meromorphic at $z=z_{1}$.
\end{lemma}

\begin{proof}
From \cite{Dunster:2017:COA} the even coefficients $\mathrm{E}_{2s}(\alpha,\phi)$ ($s=1,2,3,\ldots$) are meromorphic at $z=z_{1}$. In general, the same is only true for each $(z-z_{1})^{1/2}\mathrm{E}_{2s+1}(\alpha,\phi)$ ($s=0,1,2,\ldots$) if the integration constants in the recursion relation (in our case \cref{eq34} for $s$ even) are suitably chosen, i.e. with appropriate constants added to $\mathrm{E}_{2s+1}(\alpha,\phi)$.  Now, with the aid of Maclaurin series for $\sinh(z)$ (\cite[Eq. 4.33.1]{NIST:DLMF}), we formally expand \cref{eq81} as an asymptotic series in inverse powers of $u^2$. This series holds in a punctured neighbourhood of $z=z_{1}$ ($\zeta=\xi=0$). From this we see that each $(z-z_{1})^{1/2}\{\mathcal{E}_{2s+1}(\alpha,\phi)+d_{2s+1}(\alpha)\}$ must be single-valued in this disk, since $B(u,a,z)$ is analytic at that point, as well as $(z-z_{1})^{1/2}\zeta^{-1/2}$. Now each $(z-z_{1})^{1/2}\xi^{-2s-1}$ is meromorphic at $z=z_{1}$ (see \cref{eq20}), and hence the result follows from \cref{eq71}.
\end{proof}

As an example, we have from \cref{eq16,eq27,eq22,eq29,eq32,eq74}
%%%%%%%%%%%
\begin{multline} 
\label{eq82}
