The sufficient condition for a positive definite correlation matrix was given in Ref.~\cite{PRB71-155115*}.
Here we present a step-by-step derivation specific to NLEFT calculations.
The expectation value of any operator $O$ is expressed as
\begin{eqnarray}
\langle O \rangle &=& \lim_{\tau \rightarrow \infty} \frac{\langle \Phi_T| e^{-\tau H/2} O e^{-\tau H/2} | \Phi_T\rangle} 
   {\langle \Phi_T| e^{-\tau H} |\Phi_T\rangle} = 
    \lim_{L_t \rightarrow \infty} \frac{\langle \Phi_T| M^{L_t / 2}  O M^{L_t / 2} | \Phi_T\rangle} 
   {\langle \Phi_T| M^{L_t} |\Phi_T\rangle} 
    \\\nonumber
   &=& 
   \lim_{L_t \rightarrow \infty} \frac{
   \int\mathcal{D}c \exp(-\sum_{i=1}^{L_t} c_i^2 / 2)\langle \Phi_T | M(c_{L_t}) \cdots M(c_{L_t/2+1}) O M(c_{L_t/2}) \cdots M(c_1) |\Phi_T \rangle
   }{
   \int\mathcal{D}c \exp(-\sum_{i=1}^{L_t} c_i^2 / 2) \langle \Phi_T | M(c_{L_t}) \cdots M(c_1) |\Phi_T \rangle
   },
   \label{eq:path_integral}
\end{eqnarray}
where we have neglected the three-body force and applied the traditional Hubbard-Stratonovich auxiliary field transformation and $\tau = L_t \ a_t$.
The proof remains essentially unchanged if we include the three-body force using the discrete transformation.
Here $M = {:}\exp(-a_t H){:}$ is the transfer matrix, $c_i(\bm{n})$ is the auxiliary field at the $i$-th time slice,
and
\begin{equation}
 M(c)  = \exp\left[ \sum_{\bm{n}, \bm{n}^\prime} a_t \frac{\Psi^\dagger(\bm{n}) \nabla^2_{\bm{n} \bm{n}^\prime} \Psi(\bm{n}^\prime)}{2M} + \sum_{\bm{n}} \sqrt{-a_{t}C_{2}}c(\bm{n})\left(\overline{\rho}(\bm{n})+\frac{C_{s}}{2C_{2}}\overline{\rho}_{s}(\bm{n})\right)\right]
 \label{eq:transformed_transfer_matrix}
\end{equation}
is the transformed transfer matrix. 
The summations over $\bm{n}$, $\bm{n}^\prime$ run over all $L^3$ lattice sites,  
and $\nabla^2_{\bm{n} \bm{n}^\prime}$ represents the discretized Laplacian operator implemented using FFT.

The transfer matrix in Eq.~(\ref{eq:transformed_transfer_matrix}) is bilinear in the fermion creation and annihilation operators.
When acting on a single-particle wave function, it corresponds to a one-body imaginary-time evolution operator of dimension $L^3 \times L^3$.
For products of single-particle wave functions, it induces no many-body correlations and evolves each particle independently:
\begin{equation}
 M(c) \left( |\psi_{1}\rangle \wedge  |\psi_{2}\rangle \wedge \cdots \wedge  |\psi_{A}\rangle \right) =  M(c) |\psi_{1}\rangle \wedge  M(c) |\psi_{2}\rangle \wedge \cdots \wedge  M(c) |\psi_{A}\rangle,
 \label{eq:Single_particle_evolve}
\end{equation}
where $\psi_{1, \ldots, A}$ are a set of single-particle wave functions, and $\wedge$ denotes the antisymmetrized product, \textit{i.e.}, the Slater determinant.

Without loss of generality, we assume that $|\Phi_T\rangle$ is a Slater determinant composed of single-particle wave functions $\phi_1, \phi_2, \ldots, \phi_A$.
Repeated application of Eq.~(\ref{eq:Single_particle_evolve}) allows us to rewrite the denominator of Eq.~(\ref{eq:path_integral}) as
\begin{equation}
    \mathcal{Z} 
    = \int\mathcal{D}c \exp(-\sum_{i=1}^{L_t} c_i^2 / 2)
    \left[ \bigwedge_{i=1}^A \langle \phi_i| \right] 
    \left[ \bigwedge_{i=1}^A \overline{M}(c) |\phi_i\rangle \right] = \int\mathcal{D}c \exp(-\sum_{i=1}^{L_t} c_i^2 / 2) \det(Z(c)), 
\end{equation}
where $\overline{M}(c) = M(c_{L_t}) \cdots M(c_1)$ is the product of single-particle evolution operators, and $Z$ is an $A\times A$ fermionic correlation matrix:
\begin{align}
Z(c) &= 
\bigl[\,\langle \phi_i \mid \overline{M}(c) \mid \phi_j \rangle\bigr]_{i,j=1}^A
=
\begin{pmatrix}
\langle\phi_1\mid \overline{M}(c) \mid\phi_1\rangle & \langle\phi_1\mid \overline{M}(c)\mid\phi_2\rangle & \cdots & \langle\phi_1\mid \overline{M}(c)\mid\phi_A\rangle\\
\langle\phi_2\mid \overline{M}(c)\mid\phi_1\rangle & \langle\phi_2\mid \overline{M}(c)\mid\phi_2\rangle & \cdots & \langle\phi_2\mid \overline{M}(c)\mid\phi_A\rangle\\
\vdots & \vdots & \ddots & \vdots\\
\langle\phi_A\mid \overline{M}(c)\mid\phi_1\rangle & \langle\phi_A\mid \overline{M}(c)\mid\phi_2\rangle & \cdots & \langle\phi_A\mid \overline{M}(c)\mid\phi_A\rangle
\end{pmatrix}
.
\end{align}

In NLEFT calculations, we generate an ensemble of auxiliary-field configurations $\{c\}$ with the probability distribution
\begin{equation}
    P(c) \propto \exp(-\sum_{i=1}^{L_t} c_i^2 / 2) \left| \det(Z(c)) \right|
    \label{eq:probability_distribution}
\end{equation}
and measure observables as arithmetic averages.
The sign problem occurs when the determinant in Eq.~(\ref{eq:probability_distribution}) is not positive definite.
In this case, the averaged sign
\begin{equation}
  \langle e^{i\theta} \rangle = \int \mathcal{D}c P(c) \frac{\det(Z(c))}{\left| \det(Z(c)) \right|} 
 \end{equation}
quantifies the severity of the sign problem.
For $\langle e^{i\theta} \rangle = 1$, there is no sign problem, while $\langle e^{i\theta} \rangle \approx 0$ indicates a severe sign problem.

The single nucleon wave functions include spin and isospin indices and can be written as complex vectors of dimension $4\times L^3$. 
Correspondingly, the transfer matrix in Eq.~(\ref{eq:transformed_transfer_matrix}) becomes a $4L^3 \times 4L^3$ matrix for any given $c$-field configuration.
Since the interaction used in this work has no isospin-mixing term, the determinant factorizes:
\begin{equation}
   \det(Z(c)) = \det(Z_P(c)) \det(Z_N(c)),
\end{equation}
where $Z_P$ and $Z_N$ are the correlation matrices for protons and neutrons, respectively.
In what follows, we omit the isospin degrees of freedom; all conclusions hold for $Z(c)$, $Z_P(c)$, and $Z_N(c)$.

For even-even nuclei, we prepare the single nucleon wave functions as paired by the time-reversal operation:
\begin{equation}
   |\phi_{A/2 + k}\rangle = \mathcal{T} |\phi_k\rangle,\qquad k = 1, 2, \ldots, A/2,
   \label{eq:tsymmetry}
\end{equation}
where $\mathcal{T} = i\sigma_y \mathcal{K}$ is the time-reversal operator and $\mathcal{K}$ denotes complex conjugation.
The matrix $\overline{M}(c)$ commutes with $\mathcal{T}$, as the spin Pauli matrices and the imaginary factor $i$ in $\rho_s$ both contribute sign changes that cancel under time reversal.
Note that we focus on the $\mathcal{T}$-symmetry of the decomposed transfer matrix in Eq.~(\ref{eq:transformed_transfer_matrix}), not the original interactions, which correspond to squares of the decomposed interactions and are always time-reversal even.
For example, while the Coulomb force is time-reversal invariant, its auxiliary field transformation explicitly involves an imaginary phase and cannot be simulated without a sign problem.

Using the properties of $\mathcal{T}$ and Eq.~(\ref{eq:tsymmetry}), we obtain the relations:
\begin{eqnarray}
   \langle \phi_{A/2 + i} | \overline{M}(c) | \phi_{A/2 + j} \rangle &=& 
   \langle \mathcal{T} \phi_{i} | \overline{M}(c) | \mathcal{T} \phi_{j} \rangle =
   \langle \phi_{i} | \overline{M}(c) | \mathcal{T}^\dagger \mathcal{T} \phi_{j} \rangle^* =
   \langle \phi_{i} | \overline{M}(c) | \phi_{j} \rangle^*, \\\nonumber
   \langle \phi_{A/2 + i} | \overline{M}(c) | \phi_{j} \rangle &=&  
   \langle \mathcal{T} \phi_{i} | \overline{M}(c) |  \phi_{j} \rangle =
   \langle \phi_{i} | \overline{M}(c) | \mathcal{T}^\dagger \phi_{j} \rangle^* =
   -\langle \phi_{i} | \overline{M}(c) | \phi_{A/2 + j} \rangle^*.
\end{eqnarray}
The correlation matrix then has the structure:
\begin{equation}
  Z \;=\;
  \begin{pmatrix}
    U & -V^*\\[4pt]
    V &  U^*
  \end{pmatrix}
,
\end{equation}
where $U$ and $V$ are $A/2 \times A/2$ complex matrices.

We define a spin-flipping matrix:
\begin{equation}
\Sigma
\;=\;
i\sigma_{y} \otimes I_{A/2}
\;=\;
\begin{pmatrix}
0 & I_{A/2}\\[6pt]
-I_{A/2} & 0
\end{pmatrix}
,
\end{equation}
where $I_{A/2}$ is the $A/2 \times A/2$ identity matrix.
Direct verification shows that
\begin{equation}\label{eq:core}
  Z\,\Sigma
  \;=\;
  \Sigma\,Z^*.
\end{equation}
For any eigenvalue $\lambda\in\mathbb{C}$ with corresponding eigenvector $v$ satisfying $Z\,v = \lambda\,v$, we have
\begin{equation}
  Z\,(\Sigma\,v^*)
  = \Sigma\,Z^*\,v^*
  = \Sigma\,(\lambda^*\,v^*)
  = \lambda^*\,(\Sigma\,v^*),
\end{equation}
implying that $\lambda^*$ is also an eigenvalue with eigenvector $w=\Sigma v^*$.
Thus, complex eigenvalues of $Z$ always appear in conjugate pairs.
If $\lambda$ is real, we find
\begin{equation}
\langle v \mid w \rangle
= v^\dagger\,\Sigma\,v^*
= (v^T\,\Sigma\,v)^*
= 0,
\end{equation}
indicating that $v$ and $w$ are orthogonal eigenvectors corresponding to the same real eigenvalue.
In this case, the real eigenvalue appears twice in the diagonalized form of $Z$.
Consequently, the determinant $\det(Z)$, being the product of all eigenvalues, is always nonnegative.





