% $\Lambda_{\mathrm{cou}} = 180\,$MeV is a momentum cutoff introduced to remove the singularity at $r=0$, $\bm{q} = \bm{p}^\prime - \bm{p}$ is the momentum transfer.
% In coordinate space, the potential can be expressed using the error function,
% \begin{equation}
%  V_{\mathrm{cou}}(r)
% = \alpha\,\frac{\mathrm{erf}(\Lambda_{\mathrm{cou}}\,r/2)}{r}.
% \end{equation}
% We have the asmptotic conditions,
% \[
%  V_{\mathrm{cou}}(0) = \frac{\alpha\,\Lambda_{\mathrm{cou}}}{\sqrt{\pi}}
% \quad\text{and}\quad
%  V_{\mathrm{cou}}(r)\to \frac{\alpha}{r}
% \quad\text{for}\;\Lambda_{\mathrm{cou}}\to\infty.
% \]
% The potential $ V_{\mathrm{cou}}$ is smooth for any $r$ and can be implemented on the lattice using the FFT.


A static Coulomb force $V_{\mathrm{cou}}$ is included. 
The form is the same as that used in Ref.~\cite{EPJA61-85*} with a different cutoff.
We compute the first-order perturbative energy of $V_{\mathrm{cou}}$.
In momentum space, we have
\begin{equation}
V_{\mathrm{cou}} = \frac{\alpha}{q^2}
\exp\!\Bigl(-\frac{q^2}{2\Lambda_{\mathrm{cou}}^2}\Bigr),
\end{equation}
where $\alpha = 1/137$ is the fine structure constant,
$\Lambda_{\mathrm{cou}} = 180\,\mathrm{MeV}$ is a momentum cutoff that removes the singularity at $r=0$, and $\bm{q} = \bm{p}^\prime - \bm{p}$ is the momentum transfer.
In coordinate space, the potential is expressed using the error function:
\begin{equation}
 V_{\mathrm{cou}}(r)
= \alpha\,\frac{\mathrm{erf}(\Lambda_{\mathrm{cou}}\,r/2)}{r}.
\end{equation}
The asymptotic behavior satisfies
$$  V_{\mathrm{cou}}(0) = \frac{\alpha\,\Lambda_{\mathrm{cou}}}{\sqrt{\pi}} \quad\text{and}\quad  V_{\mathrm{cou}}(r) \to \frac{\alpha}{r} \quad\text{as}\;\Lambda_{\mathrm{cou}}\to\infty. $$
The potential $V_{\mathrm{cou}}$ is smooth for all $r$ and can be implemented on the lattice using FFT.




