\section{Finite element discretisation of multiphysics phase field models}
\label{App:FEdetails}

While in this work the numerical implementation is conducted at the integration point level, details of a more general implementation are also provided for completeness. In a three-field problem involving mechanical deformation, phase transformations and a diffusion-type equation one typically solves for the displacement vector $\mathbf{u}$, the phase field order parameter $\phi$ and the diffusion field $\xi$ as primary (nodal) variables. Their associated balance equations are provided in Eqs. (\ref{Eq:StrMulPhys11}-\ref{Eq:StrMulPhys3}). Then, using test functions $\delta \mathbf{u}$, $\delta \phi$, and $\delta \xi$, the integral form can be written as:
%
\begin{equation}
\begin{aligned}
    &\int_{\Omega} \left[\nabla \cdot \bm{\sigma} + \mathbf{b} \right] \delta \mathbf{u} \, \mathrm{d} V = 0, \\
    &\int_{\Omega} \left[\kappa \nabla^2 \phi - w'(\phi) - g'(\phi) \big( f_{\text{b1}} - f_{\text{b2}} \big) - \eta \dot{ \phi} \right] \delta \phi \, \mathrm{d} V = 0, \\
    &\int_{\Omega} \left[\rho \dot{U_{\xi}} + \nabla \cdot \mathbf{f_{\xi}} - q_{\xi} \right] \delta \xi \, \mathrm{d} V = 0.
\end{aligned}
\end{equation}

\noindent Using the divergence theorem, the weak form of each equation becomes:
%
\begin{equation}
\begin{aligned}
    &\int_{\Omega} \left[- \bm{\sigma} : \nabla^{\text{sym}} \delta \mathbf{u} + \mathbf{b} \delta \mathbf{u} \right] \, \mathrm{d} V + \int_{\partial \Omega} \delta \mathbf{u} \bm{\sigma} \cdot \mathbf{n} \, \mathrm{d} S = 0, \\
    &\int_{\Omega} \left[\left( w'(\phi) + g'(\phi) \big( f_{\text{b1}} + f_{\text{b2}} \big) + \eta \dot{ \phi}\right) \delta \phi + \kappa \nabla \phi \cdot \nabla \delta \phi \right] \, \mathrm{d} V - \int_{\partial \Omega} \delta \phi \kappa \nabla \phi \cdot \mathbf{n} \, \mathrm{d} S = 0, \\
    &\int_{\Omega} \left[\left(\rho \dot{U}_{\xi} - q_{\xi} \right) \delta \xi - \mathbf{f}_{\xi} \cdot \nabla \delta \xi \right] \, \mathrm{d} V + \int_{\partial \Omega} \delta \xi \mathbf{f} \cdot \mathbf{n} \, \mathrm{d} S = 0.
\end{aligned}
\end{equation}

\noindent With the following boundary conditions applying on $\partial \Omega$:
%
\begin{equation}
\begin{aligned}
    &\mathbf{T} = \bm{\sigma} \cdot \mathbf{n}, \\
    &\nabla \phi \cdot \mathbf{n} = 0, \\
    &f_{\xi} = \mathbf{f}_{\xi} \cdot \mathbf{n},
\end{aligned}
\end{equation}

\noindent where $\mathbf{T}$ is the surface traction, $f_{\xi}$ the diffusion field flux.\\

To derive the finite element discretised form, we approximate the variables $\mathbf{u}$, $\phi$, and $\xi$ using shape functions $N_i$ (shape function of node $i$) and nodal values of each field as follows:
%
\begin{equation}\label{Eq:ShapeFun}
\mathbf{u} = \sum_i^n \bm{N}_i \mathbf{u}_i, \quad \phi = \sum_i^n N_i \phi_i, \quad \xi = \sum_i^n N_i \xi_i.
\end{equation}

The gradients of each field are found by taking derivatives of the shape functions with respect to space, creating the $\bm{B}$-matrices:
%
\begin{equation}\label{Eq:BMatrices}
\boldsymbol{\varepsilon} = \sum_i^n \bm{B}_i^u \boldsymbol{u}_i, \quad \nabla \phi = \sum_i^n \bm{B}_i \phi_i, \quad \nabla \xi = \sum_i^n \bm{B}_i \xi_i.
\end{equation}

Using Eqs. (\ref{Eq:ShapeFun}) and (\ref{Eq:BMatrices}), the residual for each equation becomes:
%
\begin{equation}
\begin{aligned}
&\mathbf{R}_i^\mathbf{u} = \int_{\Omega} \left[(\bm{B}_i^\mathbf{u})^T \bm{\sigma} - (\bm{N}_i)^T \mathbf{b}\right] \, \mathrm{d} V - \int_{\partial \Omega} (\bm{N}_i)^T \mathbf{T} \, \mathrm{d} S, \\
&R_i^\phi = \int_{\Omega} \left[\left(\eta \frac{\phi^{t+\delta t} - \phi^{t}}{\delta t} + w^{\prime}(\phi) + g'(\phi) \big( f_{\text{b1}} + f_{\text{b2}} \big)\right) N_i - \kappa \bm{B}_i^T \nabla \phi \right] \, \mathrm{d} V, \\
&R_i^\xi = \int_{\Omega} \left[\left(\rho \frac{U_{\xi}^{t+\delta t} - U_{\xi}^{t}}{\delta t} - q_{\xi}\right) N_i - \bm{B}_i^T \mathbf{f}_{\xi}\right] \, \mathrm{d} V - \int_{\partial \Omega} N_i f_{\xi} \, \mathrm{d} S.
\end{aligned}
\end{equation}

Finally, by taking the variation of each residual with respect to the field variable, we obtain the stiffness matrix:
%
\begin{equation}
\begin{aligned}
&\bm{K}_{ij}^\mathbf{u} = \frac{\partial \mathbf{R}_i^\mathbf{u}}{\partial \mathbf{u}_j} = \int_{\Omega} (\bm{B}_i^\mathbf{u})^T \bm{C} \bm{B}_j^\mathbf{u} \, \mathrm{d} V, \\
&\bm{K}_{ij}^{\phi} = \frac{\partial {R}_i^{\phi}}{\partial \phi_j} = 
 \int_{\Omega} \big(\eta + w^{\prime\prime}(\phi) + g^{\prime\prime}(\phi) ( f_{\text{b1}} + f_{\text{b2}})\big) N_i N_j \, \mathrm{d} V - \int_{\Omega} (\bm{B}_i)^T \bm{B}_j \, \mathrm{d} V, \\
&\bm{K}_{ij}^{\xi} = \frac{\partial {R}_i^{\xi}}{\partial \xi_j} = 
\frac{1}{\delta t} \int_{\Omega} N_i \rho \frac{\partial U_{\xi}}{\partial \xi} N_j \, \mathrm{d} V + \frac{1}{\delta t} \int_{\Omega} N_i \rho \frac{\partial U_{\xi}}{\partial \nabla \xi} \cdot \bm{B}_j \, \mathrm{d} V \\
& \hspace{10mm} - \int_{\Omega} (\bm{B}_i)^T \cdot \frac{\partial \mathbf{f}_{\xi}}{\partial \xi} N_j \, \mathrm{d} V - \int_{\Omega} (\bm{B}_i)^T \cdot \frac{\partial \mathbf{f}_{\xi}}{\partial \nabla \xi} \cdot \bm{B}_j \, \mathrm{d} V \\
& \hspace{10mm} - \int_{\Omega} N_i \frac{\partial r}{\partial \xi} N_j \, \mathrm{d} V - \int_{\partial \Omega} N_i \frac{\partial f_{\xi}}{\partial \xi} N_j \, \mathrm{d} S.
\end{aligned}
\end{equation}

The off-diagonal stiffness matrices are considered zero to reduce computational effort, allowing the inversion process to handle lower-dimensional stiffness matrices more efficiently.

\section{On the arrangement of the phase field equation}
\label{sec:Arang}

We show here how the arrangement of the strong form of the phase field equation (or any type of diffusion equation) can lead to different weak forms (and thus results) if the mobility coefficient varies in space ($L(\mathbf{x})$). This is for example the case when the mobility coefficient is enhanced to capture the role of mechanics in corrosion, as shown in Eq. (\ref{eq:Lmech}). We consider three distinct cases, which should be equivalent for a constant (homogeneous) mobility coefficient $L$:
%
\begin{equation}\label{Eq:StrongDif}
\begin{aligned}
& \frac{1}{L(\mathbf{x})} \dot{\phi} + \nabla \cdot \nabla \phi = 0, \\
& \dot{\phi} + L(\mathbf{x}) \nabla \cdot \nabla \phi = 0, \\
& \dot{\phi} + \nabla \cdot (L(\mathbf{x}) \cdot \nabla \phi) = 0,
\end{aligned}
\end{equation}

\noindent The weak form of each equation can be readily obtained by introducing the test function $\delta \phi$,
%
\begin{equation}
\begin{aligned}
& \int_{\Omega} \left( \frac{1}{ L(x)} \dot{\phi} + \nabla \cdot \nabla \phi \right) \delta \phi \, \mathrm{d} V = 0, \\
& \int_{\Omega} \left( \dot{\phi} +  L(x) \color{black} \nabla \cdot \nabla \phi \right) \delta \phi \, \mathrm{d} V = 0, \\
& \int_{\Omega} \left( \dot{\phi} + \nabla \cdot ( L(x) \color{black} \cdot \nabla \phi) \right) \delta \phi \, \mathrm{d} V = 0.
\end{aligned}
\end{equation}

Utilising the divergence theorem, the weak forms can also be formulated as,
%
\begin{equation}
\begin{aligned}
& \int_{\Omega} \left( \frac{1}{ L(x) \color{black} } \dot{\phi} \delta \phi - \nabla \delta \phi \cdot \nabla \phi \right) \, \mathrm{d} V + \int_{\partial \Omega} \nabla \phi \cdot \mathbf{n} \, \delta \phi \, \mathrm{d} S = 0, \\
& \int_{\Omega} \left( \dot{\phi} \delta \phi -  L(x) \color{black}  \nabla \delta \phi \cdot \nabla \phi - \nabla  L(x) \color{black}  \cdot \nabla \phi \, \delta \phi \right) \, \mathrm{d} V + \int_{\partial \Omega} \nabla \phi \cdot \mathbf{n} \, \delta \phi \, \mathrm{d} S = 0, \\
& \int_{\Omega} \left( \dot{\phi} \delta \phi -  L(x) \color{black}  \nabla \delta \phi \cdot \nabla \phi \right) \, \mathrm{d} V + \int_{\partial \Omega}  L(x) \color{black}  \nabla \phi \cdot \mathbf{n} \, \delta \phi \, \mathrm{d} S = 0.
\end{aligned}
\end{equation}

These derived weak forms yield distinct results. In the first equation, the parameter $L(\mathbf{x})$ acts as a regularization parameter influencing the system's equilibrium. The second equation incorporates the gradient of this parameter into its weak form, while in the third equation, $L(\mathbf{x})$ is a parameter for the gradient term of the field variable. Eq. \eqref{Eq:StrongDif}a is the approach typically adopted \cite{cui2022generalised}. Both Eq. \eqref{Eq:StrongDif}a and Eq. \eqref{Eq:StrongDif}c can be implemented using a \texttt{UMATHT} subroutine.\\


\section{Tangential stiffness matrix for the no-tension split}
\label{Sec:TSM}

In the hydraulic fracture analyses, we chose to adopt the no-tension strain energy decomposition \cite{DelPiero1989,Freddi2010} for both the phase field and the balance of linear momentum equations (i.e., not using the hybrid approach but retaining variational consistency). This requires defining a suitable tangential stiffness tensor, which is the aim of this Appendix. Let us begin by defining the total strain energy density as:
%
\begin{equation}
    \psi \left( \bm{\varepsilon}, \phi \right) = g \left( \phi \right) \psi_1^{\mathrm{M}} \left( \bm{\varepsilon} \right) + \left( 1 - g \left( \phi \right) \right) \psi_2^{\mathrm{M}} \left( \bm{\varepsilon} \right) \, ,
\end{equation}

\noindent with the tangential stiffness tensor being defined as:
%
\begin{equation}\label{Eq:Stiffness}
\bm{C} = g \left( \phi \right) \frac{\partial^2 \psi_1^{\mathrm{M}}}{\partial \boldsymbol\varepsilon^2} + \left( 1 - g \left( \phi \right) \right) \frac{\partial^2 \psi_2^{\mathrm{M}}}{\partial \boldsymbol\varepsilon^2} = g \left( \phi \right) \bm{C}_1^{\mathrm{M}} + \left( 1 - g \left( \phi \right) \right) \bm{C}_2^{\mathrm{M}} \, .
\end{equation}

\noindent Here, $\bm{C}_1^{\mathrm{M}}$ and $\bm{C}_2^{\mathrm{M}}$ are the tangential moduli of the first and second materials, respectively.

For the no-tension model, the strain energy can be expressed as:
%
\begin{equation}
\begin{aligned}
\psi= & \frac{E \nu}{2(1+\nu)(1-2 \nu)}\left\{\left[\epsilon_1-(1-\sqrt{g}) \epsilon_1^t\right]+\left[\epsilon_2-(1-\sqrt{g}) \epsilon_2^t\right]+\left[\epsilon_3-(1-\sqrt{g}) \epsilon_3^t\right]\right\}^2 \\
& + \frac{E}{2(1+\nu)}\left\{\left[\epsilon_1-(1-\sqrt{g}) \epsilon_1^t\right]^2+\left[\epsilon_2-(1-\sqrt{g}) \epsilon_2^t\right]^2+\left[\epsilon_3-(1-\sqrt{g}) \epsilon_3^t\right]^2\right\} \, ,
\end{aligned}
\end{equation}

\noindent where $\epsilon_i$ and $\epsilon_i^t$ are the principal strain and the principal tensile strain, respectively, with $i$ indexing from the minimum to the maximum principal strain ($\epsilon_3 \geq \epsilon_2 \geq \epsilon_1$). The principal tensile strains are defined based on the strain state:
%
\begin{equation}
\begin{aligned}
\text{if} & \quad \epsilon_1>0 & & \quad \Rightarrow \quad \epsilon_1^t = \epsilon_1, \quad \epsilon_2^t = \epsilon_2, \quad \epsilon_3^t = \epsilon_3, \\
\text{elseif} & \quad \epsilon_2 + \nu \epsilon_1 > 0 & & \quad \Rightarrow \quad \epsilon_1^t = 0, \quad \epsilon_2^t = \epsilon_2 + \nu \epsilon_1, \quad \epsilon_3^t = \epsilon_3 + \nu \epsilon_1, \\
\text{elseif} & \quad (1-\nu) \epsilon_3 + \nu (\epsilon_1 + \epsilon_2) > 0 & & \quad \Rightarrow \quad \epsilon_1^t = 0, \quad \epsilon_2^t = 0, \quad \epsilon_3^t = \epsilon_3 + \frac{\nu}{1-\nu} (\epsilon_1 + \epsilon_2), \\
& & & \quad \text{else} \quad \Rightarrow \quad \epsilon_1^t = 0, \quad \epsilon_2^t = 0, \quad \epsilon_3^t = 0.
\end{aligned}
\end{equation}

Based on this definition, the strain energy of the second phase can be expressed as:
%
\begin{equation}
\psi_2^{\text{M}}(\boldsymbol{\varepsilon})=
\begin{cases}
0 & \epsilon_1>0 \\
\frac{E}{2} \epsilon_1^2 & \epsilon_2+\nu \epsilon_1>0 \\
\frac{E}{2\left(1-v^2\right)}\left(\epsilon_1^2+\epsilon_2^2+2 v \epsilon_1 \epsilon_2\right) & (1-\nu)\epsilon_3+\nu (\epsilon_1+\epsilon_2)>0 \\
\frac{E v}{2(1+\nu)(1-2 v)}\left(\epsilon_1+\epsilon_2+\epsilon_3\right)^2+\frac{E}{2(1+\nu)}\left(\epsilon_1^2+\epsilon_2^2+\epsilon_3^2\right) & \text{else}
\end{cases}
\end{equation}

For a fully damaged material, the material Jacobian in the principal direction, $(\bm{C}_2^{\mathrm{M}})'$, is defined as:
%
\begin{equation}
(C_2^{\mathrm{M}})^{'}_{ijkl}=\frac{\partial \psi_s}{\partial \epsilon_{ij} \partial \epsilon_{kl}}=
\begin{cases}
0 & \epsilon_1>0, \\
\delta_{i1} \delta_{j1} \delta_{k1} \delta_{l1} \, E &  \epsilon_2 + \nu \epsilon_1 > 0, \\
\delta_{ij} \delta_{kl} (1-\delta_{i3}) \big(\delta_{ik}+(1-\delta_{k3}) \, \nu \big) \, \frac{E}{1 - \nu^2} & (1-\nu)\epsilon_3 + \nu (\epsilon_1 + \epsilon_2) > 0, \\
\bm{C}_0 ,
\end{cases}
\end{equation}

\noindent where $\delta_{ij}$  is the Kronecker delta. The tangential matrix of the first phase is equal to the elastic stiffness matrix so $\bm{C}_1^{\mathrm{M}}=\bm{C}_0$. The tangential stiffness matrix in the principal direction, $\bm{C}^{'}$, can be written as:
%
\begin{equation}
\bm{C}^{'} = g \left( \phi \right)(\bm{C}_0) + \left( 1 - g \left( \phi \right) \right)(\bm{C}_2^{\mathrm{M}})'.
\end{equation}

The Jacobian matrix in the original direction, $\bm{C}$, is obtained by rotating $\bm{C}^{'}$ to the original orientation using:
%
\begin{equation}\label{Eq:Rotation}
C_{qrst} = a_{qi} a_{rj} a_{sk} a_{tl} C_{ijkl}^{'} \, ,
\end{equation}

\noindent where $\bm{a}$ is the transpose of the direction cosines matrix for the principal directions, defined as:
\begin{equation}
\bm{a}^{'} = [\boldsymbol{v}_1, \boldsymbol{v}_2, \boldsymbol{v}_3] \, ,
\end{equation}

\noindent where $\boldsymbol{v}_1$, $\boldsymbol{v}_2$, and $\boldsymbol{v}_3$ are the principal vectors of the strain tensor, satisfying:
\begin{equation}
(\boldsymbol{\varepsilon} - \epsilon_{ii} \bm{I}) \cdot \boldsymbol{v}_i = 0,
\end{equation}

with $i=1,2,3$ and $\bm{I}$ being the identity matrix.











