\subsection{Barycenter} \label{SS-barycenter}

For a compact convex set $\cK$ in a Hausdorff locally convex topological vector space $V$, we denote by $\ext\, \cK$ the set of extreme points of $\cK$. When $\cK$ is metrizable, for every $\mu\in \cM(\cK)$, there is a unique $x\in \cK$ such that
$$\int_{\cK} \phi(v)\, d\mu(v)=\phi(x)$$
for every continuous linear functional $\phi: V\rightarrow \Rb$ \cite[Proposition 1.1]{Phelps}. This $x$ is called the {\it barycenter} of $\mu$. The map $\Psi: \cM(\cK)\rightarrow \cK$ sending $\mu$ to its barycenter is continuous and affine in the sense that $\Psi(\lambda \mu+(1-\lambda)\nu)=\lambda \Psi(\mu)+(1-\lambda)\Psi(\nu)$ for all $\lambda\in [0, 1]$ and $\mu, \nu\in \cM(\cK)$.



\subsection{Amenable groups} \label{SS-amenable}

The group $\Gamma$ is said to be {\it amenable} if for any $K\in \cF(\Gamma)$ 
and any $\varepsilon>0$ there is an $F\in \cF(\Gamma)$ 
such that
\begin{align} \label{E-Folner}
 |KF\Delta F|<\varepsilon |F|,
\end{align}
where $A\Delta B:=(A\setminus B)\cup (B\setminus A)$ for subsets $A, B$ of $\Gamma$.

Assume that $\Gamma$ is amenable. For a function $\varphi: \cF(\Gamma)\rightarrow \Rb$, we say that {\it $\varphi(F)$ converges to $L\in \Rb$ when $F\in \cF(\Gamma)$ becomes more and more left invariant} if for any $\delta>0$, there are some $K\in \cF(\Gamma)$ and $\varepsilon>0$ such that
$$|\varphi(F)-L|<\delta$$
for every $F\in \cF(\Gamma)$ satisfying \eqref{E-Folner}. In general, we say that {\it the limit supremum of $\varphi(F)$ as $F\in \cF(\Gamma)$ becomes more and more left invariant is $L\in \Rb$} if $L$ is the smallest $t\in \Rb$ satisfying that for any $\delta>0$, there are some $K\in \cF(\Gamma)$ and $\varepsilon>0$ such that
$$\varphi(F)<t+\delta$$
for every $F\in \cF(\Gamma)$ satisfying \eqref{E-Folner}.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{IE-tuples} \label{SS-IE}

Assume that $\Gamma$ is amenable.
Let $k\in \Nb$, and let $\oA=(A_1, \dots, A_k)$ be a tuple of subsets of $X$. For each $F\in \cF(\Gamma)$, we set
$$ \varphi_{\oA}(F)=\max\{|J|: J\subseteq F \mbox{ is an independence set for } \oA\}.$$
The {\it independence density} of $\oA$ is defined as
$$ \oI(\oA)=\inf_{F\in \cF(\Gamma)}\frac{\varphi_\oA(F)}{|F|}.$$
When $F\in \cF(\Gamma)$ becomes more and more left invariant, $\frac{\varphi_\oA(F)}{|F|}$ converges to $\oI(\oA)$ \cite[page 287]{KL16}.
We call $\ox\in X^k$ an {\it IE-tuple} if for every product neighborhood $U_1\times \cdots \times U_k$ of $\ox$ in $X^k$, the tuple $\oU=(U_1, \dots, U_k)$ has positive independence density, i.e., $\oI(\oU)>0$. We denote by $\IE_k(X)$ the set of all IE-tuples of length $k$.

We refer the reader to \cite{MO, KL16} for general information about topological entropy. 
For each finite open cover $\cU$ of $X$, when $\cF\in \cF(\Gamma)$ becomes more and more left invariant, $\frac{1}{|F|}\log N\left(\bigvee_{s\in F}s^{-1}\cU\right)$ converges to a limit \cite[page 220]{KL16}, denoted by $h_{\rm top}(X, \cU)$. The {\it topological entropy} of $\Gamma\curvearrowright X$ is defined as $\sup_\cU  h_{\rm top}(X, \cU)$ for $\cU$ ranging over finite open covers of $X$, and is denoted by $h_{\rm top}(X)$. 

The following summarizes the basic properties of IE-tuples we need \cite[Theorem 12.19 and page 289]{KL16}.

\begin{theorem} \label{T-IE basic}
Let $k\in \Nb$. The following hold:
\begin{enumerate}
\item \label{i-IE invariant} $\IE_k(X)$ is a closed $\Gamma$-invariant subset of $X^k$.
\item \label{i-IE tuple} Let $(A_1, \dots, A_k)$ be a tuple of closed subsets of $X$ with positive independence density. Then there is an IE-tuple $\ox\in A_1\times \cdots \times A_k$.
\item \label{i-IE pair} $\IE_2(X)\setminus \Delta_2(X)$ is nonempty if and only if $h_{\rm top}(X)>0$.
\item \label{i-IE factor} Let $\Gamma\curvearrowright Y$ be another continuous action of $\Gamma$ on a compact metrizable space $Y$, and  let $\pi:X\rightarrow Y$ be a factor map. Then $(\pi\times \cdots \times \pi)(\IE_k(X))=\IE_k(Y)$.
\item \label{i-IE subset} Let $Z$ be a closed $\Gamma$-invariant subset of $X$. Then $\IE_k(Z)\subseteq \IE_k(X)$.
\item \label{i-IE product} If $\Gamma\curvearrowright Y$ is another continuous action of $\Gamma$ on a compact metrizable space $Y$, then
$$ \IE_k(X\times Y)=\IE_k(X)\times \IE_k(Y)$$
under the natural identification of $(X\times Y)^k$ and $X^k\times Y^k$.
\item \label{i-IE 1} $\IE_1(X)$ is the closure of $\bigcup_{\mu\in \cM_\Gamma(X)}\supp(\mu)$.
\end{enumerate}
\end{theorem}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Measure IE-tuples} \label{SS-measure IE}

Assume that $\Gamma$ is amenable.
Let $k\in \Nb$, let $\oA=(A_1, \dots, A_k)$ be a tuple of subsets of $X$, and let $D\subseteq X$. We say $F\in \cF(\Gamma)$ is an {\it independence set for $\oA$ relative to $D$} if 
$$D\cap \bigcap_{s\in F}s^{-1}A_{\sigma(s)}\neq \emptyset$$ 
for every map $\sigma: F\rightarrow [k]$ \cite[Definition 1.1]{KL09}.

Let $\mu\in \cM_\Gamma(X)$. For $\delta>0$, we denote by $\sB(\mu, \delta)$ the set of Borel subsets $D$ of $X$ satisfying $\mu(D)\ge 1-\delta$. For each $F\in \cF(\Gamma)$, we set
$$ \varphi_{\oA, \mu, \delta}(F)=\min_{D\in \sB(\mu, \delta)}\max\{|J|: J\subseteq F \mbox{ is an independence set for } \oA \mbox{ relative to } D\},$$
and define $\upind_\mu(\oA, \delta)$ as the limit supremum of $\frac{1}{|F|}\varphi_{\oA, \mu, \delta}(F)$ as $F\in \cF(\Gamma)$ becomes more and more left invariant.
Then we define the {\it upper $\mu$-independence density of $\oA$} \cite[Definition 2.1]{KL09} as
$$ \upind_\mu(\oA)=\sup_{\delta>0}\upind_\mu(\oA, \delta).$$
We call $\ox=(x_1, \dots, x_k)\in X^k$ a {\it $\mu$-IE-tuple} if for every product neighborhood $U_1\times \cdots \times U_k$ of $\ox$ in $X^k$, the tuple $(U_1, \dots, U_k)$ has positive upper $\mu$-independence density \cite[Definition 2.5]{KL09}. We denote by $\IE^\mu_k(X)$ the set of all $\mu$-IE-tuples of length $k$.


We refer the reader to \cite{MO, OW, KL16} for general information about measure entropy. 
For  each finite Borel partition $\cP$ of $X$, the entropy of $\Gamma\curvearrowright (X, \mu)$ with respect to $\cP$ is defined as
$$ h_\mu(X, \cP)=\inf_{F\in \cF(\Gamma)}\frac{1}{|F|}H_\mu \left(\bigvee_{s\in F}s^{-1}\cP\right).$$
When $\cF\in \cF(\Gamma)$ becomes more and more left invariant, $\frac{1}{|F|}H_\mu \left(\bigvee_{s\in F}s^{-1}\cP\right)$ converges to $h_\mu(X, \cP)$ \cite[page 198]{KL16}. 
The {\it measure entropy} of $\Gamma\curvearrowright (X, \mu)$ is defined as $\sup_\cP  h_\mu(X, \cP)$ for $\cP$ ranging over finite Borel partitions of $X$, and is denoted by $h_\mu(X)$. 

The following summarizes the basic properties of measure IE-tuples we need \cite[Proposition 2.16 and Theorem 2.30]{KL09}.

\begin{theorem} \label{T-measure IE basic}
Let $\mu\in \cM_\Gamma(X)$ and $k\in \Nb$. The following hold:
\begin{enumerate}
\item \label{i-measure IE invariant} $\IE^\mu_k(X)$ is a closed $\Gamma$-invariant subset of $X^k$.
\item \label{i-measure IE tuple} Let $(A_1, \dots, A_k)$ be a tuple of closed subsets of $X$ with positive upper $\mu$-independence density. Then there is a $\mu$-IE-tuple $\ox\in A_1\times \cdots \times A_k$.
\item \label{i-measure IE pair} $\IE^\mu_2(X)\setminus \Delta_2(X)$ is nonempty if and only if $h_\mu(X)>0$.
\item \label{i-measure IE factor} Let $\Gamma\curvearrowright Y$ be another continuous action of $\Gamma$ on a compact metrizable space $Y$, and  let $\pi:X\rightarrow Y$ be a factor map. Then $(\pi\times \cdots \times \pi)(\IE^\mu_k(X))=\IE^{\pi_*\mu}_k(Y)$, where $\pi_*\mu\in \cM_\Gamma(Y)$ is the push-forward of $\mu$ under $\pi$.
\item \label{i-measure IE product} If $\Gamma\curvearrowright Y$ is another continuous action of $\Gamma$ on a compact metrizable space $Y$ and $\nu\in \cM_\Gamma(Y)$, then
$$ \IE^{\mu\times \nu}_k(X\times Y)=\IE^\mu_k(X)\times \IE^\nu_k(Y)$$
under the natural identification of $(X\times Y)^k$ and $X^k\times Y^k$.
%\item $\IE_1(X)=\bigcup_{\mu\in \cM_\Gamma(X)}\supp(\mu)$.
\end{enumerate}
\end{theorem}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{IN-tuples} \label{SS-IN}

Let $k\in \Nb$.
We call $\ox\in X^k$ an {\it IN-tuple} if for every product neighborhood $U_1\times \cdots \times U_k$ of $\ox$ in $X^k$, the tuple $\oU=(U_1, \dots, U_k)$ has arbitrarily large finite independence sets. We denote by $\IN_k(X)$ the set of all IN-tuples of length $k$.

For a sequence $\mathfrak{s}=\{s_n\}_{n\in \Nb}$ in $\Gamma$, the {\it sequence topological entropy} of $\Gamma\curvearrowright X$ with respect to $\mathfrak{s}$ is defined as 
$$h_{\rm top}(X; \mathfrak{s})=\sup_\cU \limsup_{n\to \infty}\frac{1}{n}\log N\left(\bigvee_{i=1}^ns_i^{-1}\cU\right)$$
for $\cU$ ranging over finite open covers of $X$ \cite{Goodman}. We say the action $\Gamma\curvearrowright X$ is {\it null} if $ h_{\rm top}(X; \mathfrak{s})=0$ for every sequence $\mathfrak{s}$ in $\Gamma$. 

The following summarizes the basic properties of IN-tuples we need \cite[Proposition 5.4]{KL07}.

\begin{theorem} \label{T-IN basic}
Let $k\in \Nb$. The following hold:
\begin{enumerate}
\item \label{i-IN invariant} $\IN_k(X)$ is a closed $\Gamma$-invariant subset of $X^k$.
\item \label{i-IN tuple} Let $(A_1, \dots, A_k)$ be a tuple of closed subsets of $X$ with arbitrarily large finite independence sets. Then there is an IN-tuple $\ox\in A_1\times \cdots \times A_k$.
\item \label{i-IN pair} $\IN_2(X)\setminus \Delta_2(X)$ is nonempty if and only if $\Gamma\curvearrowright X$ is nonnull.
\item \label{i-IN factor} Let $\Gamma\curvearrowright Y$ be another continuous action of $\Gamma$ on a compact metrizable space $Y$, and  let $\pi:X\rightarrow Y$ be a factor map. Then $(\pi\times \cdots \times \pi)(\IN_k(X))=\IN_k(Y)$.
\item \label{i-IN subset} Let $Z$ be a closed $\Gamma$-invariant subset of $X$. Then $\IN_k(Z)\subseteq \IN_k(X)$.
\end{enumerate}
\end{theorem}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Measure IN-tuples} \label{SS-measure IN}


Let $k\in \Nb$.
Let $\oA=(A_1, \dots, A_k)$ be a tuple of subsets of $X$, and let $D: \Gamma\rightarrow 2^X$. We say $F\in \cF(\Gamma)$ is an {\it independence set for $\oA$ relative to $D$} if 
$$\bigcap_{s\in F}(D_s\cap s^{-1}A_{\sigma(s)})\neq \emptyset$$ 
for every map $\sigma: F\rightarrow [k]$ \cite[Definition 1.1]{KL09}. 

Let $\mu\in \cM_\Gamma(X)$.
% be a $\Gamma$-invariant Borel probability measure on $X$. 
We denote by $\sB(X)$ the set of Borel subsets of $X$. For $\delta>0$, we denote by $\sB'(\mu, \delta)$ the set of $D: \Gamma\rightarrow \sB(X)$ satisfying 
$$\inf_{s\in \Gamma}\mu(D_s)\ge 1-\delta.$$
We say $\oA$ has {\it positive sequential $\mu$-independence density}  if there are $\delta, c>0$ such that for every $M>0$ there is an $F\in \cF(\Gamma)$ with $|F|\ge M$ so that for every $D\in \sB'(\mu, \delta)$ there is an independence set $J\subseteq F$ for $\oA$ relative to $D$ with $|J|\ge c|F|$.
We call $\ox=(x_1, \dots, x_k)\in X^k$ a {\it $\mu$-IN-tuple} if for every product neighborhood $U_1\times \cdots \times U_k$ of $\ox$ in $X^k$, the tuple $(U_1, \dots, U_k)$ has positive sequential $\mu$-independence density \cite[Definition 4.2]{KL09}. We denote by $\IN^\mu_k(X)$ the set of all $\mu$-IN-tuples of length $k$.


For a sequence $\mathfrak{s}=\{s_n\}_{n\in \Nb}$ in $\Gamma$, the {\it sequence measure entropy} of $\Gamma\curvearrowright (X, \mu)$ with respect to $\mathfrak{s}$ is defined as 
$$h_\mu(X; \mathfrak{s})=\sup_\cP \limsup_{n\to \infty}\frac{1}{n}\log H_\mu\left(\bigvee_{i=1}^ns_i^{-1}\cP\right)$$
for $\cP$ ranging over finite Borel partitions of $X$ \cite{Kushnirenko}. We say the action $\Gamma\curvearrowright (X, \mu)$ is {\it null} if $h_\mu(X; \mathfrak{s})=0$ for every sequence $\mathfrak{s}$ in $\Gamma$. 


The following summarizes the basic properties of measure IN-tuples we need \cite[Proposition 4.7 and Theorem 4.12]{KL09}.

\begin{theorem} \label{T-measure IN basic}
Let $\mu\in \cM_\Gamma(X)$ and $k\in \Nb$. The following hold:
\begin{enumerate}
\item \label{i-measure IN invariant} $\IN^\mu_k(X)$ is a closed $\Gamma$-invariant subset of $X^k$.
\item \label{i-measure IN tuple} Let $(A_1, \dots, A_k)$ be a tuple of closed subsets of $X$ with positive sequential $\mu$-independence density. Then there is a $\mu$-IN-tuple $\ox\in A_1\times \cdots \times A_k$.
\item \label{i-measure IN pair} $\IN^\mu_2(X)\setminus \Delta_2(X)$ is nonempty if and only if $\Gamma\curvearrowright (X,\mu)$ is nonnull.
\item \label{i-measure IN factor} Let $\Gamma\curvearrowright Y$ be another continuous action of $\Gamma$ on a compact metrizable space $Y$, and  let $\pi:X\rightarrow Y$ be a factor map. Then $(\pi\times \cdots \times \pi)(\IN^\mu_k(X))=\IN^{\pi_*\mu}_k(Y)$, where $\pi_*\mu\in \cM_\Gamma(Y)$ is the push-forward of $\mu$ under $\pi$. 
\item \label{i-measure IN product} If $\Gamma\curvearrowright Y$ is another continuous action of $\Gamma$ on a compact metrizable space $Y$ and $\nu\in \cM_\Gamma(Y)$, then
$$ \IN^{\mu\times \nu}_k(X\times Y)=\IN^\mu_k(X)\times \IN^\nu_k(Y)$$
under the natural identification of $(X\times Y)^k$ and $X^k\times Y^k$.
\end{enumerate}
\end{theorem}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{IT-tuples} \label{SS-IT}

Let $k\in \Nb$.
We call $\ox\in X^k$ an {\it IT-tuple} if for every product neighborhood $U_1\times \cdots \times U_k$ of $\ox$ in $X^k$, the tuple $\oU=(U_1, \dots, U_k)$ has an infinite independence set. We denote by $\IT_k(X)$ the set of all IT-tuples of length $k$.

The action $\Gamma\curvearrowright X$ is said to be {\it untame} if there are an $f\in C(X)$, an infinite subset $F$ of $\Gamma$ and a constant $C>0$ such that 
$$\left\|\sum_{s\in F}\lambda_s sf\right\|\ge C\sum_{s\in F}|\lambda_s|$$
for all $\lambda \in \ell_1(F)$. 

The following summarizes the basic properties of IN-tuples we need \cite[Proposition 8.14]{KL16}.

\begin{theorem} \label{T-IT basic}
Let $k\in \Nb$. The following hold:
\begin{enumerate}
\item \label{i-IT invariant} $\IT_k(X)$ is a closed $\Gamma$-invariant subset of $X^k$.
\item \label{i-IT tuple} Let $(A_1, \dots, A_k)$ be a tuple of closed subsets of $X$ with an infinite independence set. Then there is an IT-tuple $\ox\in A_1\times \cdots \times A_k$.
\item \label{i-IT pair} $\IT_2(X)\setminus \Delta_2(X)$ is nonempty if and only if $\Gamma\curvearrowright X$ is untame.
\item \label{i-IT factor} Let $\Gamma\curvearrowright Y$ be another continuous action of $\Gamma$ on a compact metrizable space $Y$, and  let $\pi:X\rightarrow Y$ be a factor map. Then $(\pi\times \cdots \times \pi)(\IT_k(X))=\IT_k(Y)$.
\item \label{i-IT subset} Let $Z$ be a closed $\Gamma$-invariant subset of $X$. Then $\IT_k(Z)\subseteq \IT_k(X)$.
\end{enumerate}
\end{theorem}







