\begin{lemma} \label{L-barycenter identity k}
Let $k\in \Nb$ and $\mu\in \cM(X^k)$. If we treat $\mu$ as a Borel probability measure $\rmm_\mu$ on $\cM(X)^k$ via the embedding $X^k\hookrightarrow \cM(X)^k$, then the barycenter of $\rmm_\mu$ in $\cM(X)^k$ is $(\mu^{(1)}, \dots, \mu^{(k)})$. 
\end{lemma}
\begin{proof} We denote by $\Psi$ the barycenter map $\cM(\cM(X)^k)\rightarrow \cM(X)^k$. We consider the map $\Phi_1: \cM(X^k)\rightarrow \cM(X)^k$ sending $\mu$ to $(\mu^{(1)}, \dots, \mu^{(k)})$, and the map $\Phi_2: \cM(X^k)\rightarrow \cM(X)^k$ sending $\mu$ to $\Psi(\rmm_\mu)$. Both $\Phi_1$ and $\Phi_2$ are affine and continuous. 

Let $(x_1, \dots, x_k)\in X^k$. We have $\Phi_1(\delta_{(x_1, \dots, x_k)})=(\delta_{x_1}, \dots, \delta_{x_k})$. Since $\rmm_{\delta_{(x_1, 
\dots, x_k)}}=\delta_{(\delta_{x_1}, \dots, \delta_{x_k})}$, we also have $\Phi_2(\delta_{(x_1, \dots, x_k)})=(\delta_{x_1}, \dots, \delta_{x_k})$. 
Thus 
$$\Phi_1(\delta_{(x_1, \dots, x_k)})=\Phi_2(\delta_{(x_1, \dots, x_k)}).$$ 


As $\cM(X^k)$ is the closed convex hull of the set of Dirac measures $\delta_{(x_1, \dots, x_k)}$ for $(x_1, \dots, x_k)\in X^k$, we conclude that 
$\Phi_1=\Phi_2$.
\end{proof}

Since we treat $X$ as a closed $\Gamma$-invariant subset of $\cM(X)$ via identifying $x\in X$ with the Dirac measure $\delta_x$ at $x$, by Theorem~\ref{T-IE basic}.\eqref{i-IE subset} we have $\IE_k(X)\subseteq \IE_k(\cM(X))$ for every $k\in \Nb$. 

\begin{lemma} \label{L-conditions for extreme of prob}
Let $k\in \Nb$. Assume that part (1) of Theorem~\ref{T-IE main} holds. Then parts (2) and (3) also hold.
\end{lemma}
\begin{proof}
Since $\IE_k(\cM(X))$ is compact convex by Lemma~\ref{L-IE convex}.(2), we can talk about $\ext\, \IE_k(\cM(X))$. Note that $\ext\, \cM(X)=X$, whence $\ext\, (\cM(X)^k)=(\ext\, \cM(X))^k=X^k$. Thus 
$$\IE_k(X)\subseteq \IE_k(\cM(X))\cap X^k=\IE_k(\cM(X))\cap \ext\, (\cM(X)^k)\subseteq \ext\, \IE_k(\cM(X)).$$
From part (1) of Theorem~\ref{T-IE main} and Lemma~\ref{L-ext} we have $\ext\, \IE_k(\cM(X))\subseteq \IE_k(X)$. Thus part (2) of Theorem~\ref{T-IE main} holds.


We denote by $\Psi$ the barycenter map $\cM(\cM(X)^k)\rightarrow \cM(X)^k$ sending $\rmm$ to its barycenter.

For each $\mu\in \cM(\IE_k(X))$,
we may treat $\mu$ as a Borel probability measure $\rmm$ on $\cM(X)^k$ via the embedding $\IE_k(X)\hookrightarrow X^k\hookrightarrow \cM(X)^k$.
%and then from Lemma~\ref{L-barycenter identity k} we have $\Psi(\rmm)=(\mu^{(1)}, \dots, \mu^{(k)})$. Thus the set of $(\mu^{(1)}, \dots, \mu^{(k)})$ for $\mu\in %\cM(\IE_k(X))$ is the same as $\Psi(\cM(\IE_k(X)))$.
From Lemma~\ref{L-barycenter identity k} we have
$$ \Psi(\cM(\IE_k(X)))=\{(\mu^{(1)}, \dots, \mu^{(k)}): \mu\in \cM(\IE_k(X))\}.$$

Since $\cM(\IE_k(X))$ is the closed convex hull of $\IE_k(X)$ in $\cM(\cM(X)^k)$ and $\Psi$ is affine and continuous, $\Psi(\cM(\IE_k(X)))$ is the closed convex hull  of $\Psi(\IE_k(X))=\IE_k(X)$ in $\cM(X)^k$. Thus part (3) of Theorem~\ref{T-IE main} follows from part (1).
\end{proof}



The case $k=1$ of Theorem~\ref{T-IE main}.(1) is easy to prove. It is mainly based on the following simple fact.

\begin{lemma} \label{L-supp for barycenter}
Let $\rmm\in \cM(\cM(X))$ and let $\mu\in \cM(X)$ be the barycenter of $\rmm$. Then
\begin{align} \label{E-supp for barycenter}
 \bigcup_{\nu\in \supp(\rmm)}\supp(\nu)\subseteq \supp(\mu).
 \end{align}
\end{lemma}
\begin{proof} We argue by contradiction. Assume that \eqref{E-supp for barycenter} fails. Then we can find some $\nu\in \supp(\rmm)$ and some $x\in \supp(\nu)$ such that $x\not\in \supp(\mu)$. By the Tietze extension theorem we can find an $f\in C(X)$ such that $f\ge 0$ on $X$, $f=0$ on $\supp(\mu)$, and $f(x)>0$. Then $\nu(f)>0$ and $\omega(f)\ge 0$ for every $\omega\in \cM(X)$, and hence
$$ \mu(f)=\int_{\cM(X)}\omega(f)\, d\rmm(\omega)>0,$$
which contradicts that $f=0$ on $\supp(\mu)$. Thus  \eqref{E-supp for barycenter} holds.
\end{proof}

We are ready to prove the case $k=1$ of Theorem~\ref{T-IE main}. 

\begin{proof}[Proof of the case $k=1$ of Theorem~\ref{T-IE main}] For any $k\in \Nb$, since $\IE_k(\cM(X))$ is a compact convex subset of $\cM(X)^k$ by Lemma~\ref{L-IE convex}.(2) and $\IE_k(X)\subseteq \IE_k(\cM(X))$ we immediately get $\overline{\rm co}(\IE_k(X))\subseteq \IE_k(\cM(X))$.


Let $\rmm\in \cM_\Gamma(\cM(X))$  and
let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$. By Theorem~\ref{T-IE basic}.\eqref{i-IE 1} we have $\supp(\mu)\subseteq \IE_1(X)$. From Lemma~\ref{L-supp for barycenter} we have $\supp(\nu)\subseteq \supp(\mu)$ for every $\nu\in \supp(\rmm)$. Thus
$$ \nu\in \overline{\rm co}(\supp(\nu))\subseteq \overline{\rm co}(\supp(\mu))\subseteq \overline{\rm co}(\IE_1(X))$$
for every $\nu\in \supp(\rmm)$, whence
$$ \supp(\rmm)\subseteq \overline{\rm co}(\IE_1(X)).$$
Applying Theorem~\ref{T-IE basic}.\eqref{i-IE 1} again we get $\IE_1(\cM(X))\subseteq \overline{\rm co}(\IE_1(X))$. This proves part (1) of Theorem~\ref{T-IE main} in the case $k=1$. From Lemma~\ref{L-conditions for extreme of prob} we conclude that the case $k=1$ of Theorem~\ref{T-IE main} holds. 
\end{proof}

To prove the  $k\ge 2$ case of Theorem~\ref{T-IE main}, we shall use the following lemma and apply some combinatorial lemmas to show that the phenomenon described there cannot happen.

\begin{lemma} \label{L-Hahn Banach IE}
If Theorem~\ref{T-IE main} fails for some $k\in \Nb$, then there are some $(\mu_1, \dots, \mu_k)\in \IE_k(\cM(X))$ and some $(f_1, \dots, f_k)\in C(X)^{\oplus k}$ such that $\sum_{j\in [k]}f_j(x_j)\le 0$
for all $(x_1, \dots, x_k)\in \IE_k(X)$ and
$\sum_{j\in [k]}\mu_j(f_j)>0$.
\end{lemma}
\begin{proof}
In the proof of the case $k=1$ of Theorem~\ref{T-IE main}, we have shown $\overline{\rm co}(\IE_k(X))\subseteq \IE_k(\cM(X))$ for all $k\in \Nb$.

Assume that the case $k$ of Theorem~\ref{T-IE main} fails. Then by Lemma~\ref{L-conditions for extreme of prob} part (1) of  Theorem~\ref{T-IE main} fails for this $k$. Thus $\overline{\rm co}(\IE_k(X))\subsetneq \IE_k(\cM(X))$. Then we can find a $\omu=(\mu_1, \dots, \mu_k)\in \IE_k(\cM(X))\setminus \overline{\rm co}(\IE_k(X))$. Note that the dual of $(C(X)^{\oplus k})^*$ equipped with the weak$^*$-topology
is $C(X)^{\oplus k}$ \cite[Theorem V.1.3]{Conway}.
Since $\overline{\rm co}(\IE_k(X))$ and $\{\omu\}$ are disjoint compact convex sets in $(C(X)^{\oplus k})^*$, by the geometric consequence of the Hahn-Banach theorem \cite[Proposition IV.3.6.(b) and Theorem IV.3.9]{Conway}, there is some $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$  such  that $\sum_{j\in [k]}\nu_j(f_j)\le 0$ for all $(\nu_1, \dots, \nu_k)\in \overline{\rm co}(\IE_k(X))$ and $\sum_{j\in [k]}\mu_j(f_j)>0$. Equivalently, $\sum_{j\in [k]}f_j(x_j)\le 0$ for all $(x_1, \dots, x_k)\in \IE_k(X)$ and $\sum_{j\in [k]}\mu_j(f_j)>0$.
\end{proof}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Case $k=2$ of Theorem~\ref{T-IE main}} \label{SS-k=2}



In this subsection we establish the combinatorial Lemma~\ref{L-half to indep} and use it to prove the case $k=2$ of Theorem~\ref{T-IE main}.

We show first that, when $k=2$, the condition $\sum_{j\in [k]}\mu_j(f_j)>0$ in Lemma~\ref{L-Hahn Banach IE} leads to a combinatorial condition in Lemma~\ref{L-large density}. 

\begin{lemma} \label{L-sum}
Let $\mu_1, \mu_2\in \cM(X)$  and $f_1, f_2\in C(X)$ such that $\sum_{j\in [2]} \mu_j(f_j)>0$. Then there are open sets $U_1, U_2\subseteq X$ such that 
$$\sum_{j\in [2]} \min_{x\in \overline{U_j}}f_j(x)>0 \quad \text{ and } \quad \sum_{j\in [2]}\mu_j(U_j)>1.$$
\end{lemma}
\begin{proof} Let $C=\max(\|f_1||, \|f_2\|)>0$. We denote by $\nu$ the Lebesgue measure on $\Rb$. For $j\in [2]$, setting
$$A_j=\{(x, t)\in X\times [-C, C]: t<f_j(x)\}$$
and denoting by ${\bf 1}_{A_j}$ the characteristic function of $A_j$,
by Fubini's theorem  we have
\begin{align*}
\mu_j(f_j)
&=-C+\int_X (f_j(x)+C)\, d\mu_j(x)=-C+\int_X \int_{[-C, C]}{\bf 1}_{A_j}(x, t)\, d\nu(t)\, d\mu_j(x)\\
&=-C+\int_{[-C, C]}\int_X {\bf 1}_{A_j}(x, t)\, d\mu_j(x)\, d\nu(t)=-C+\int_{[-C, C]}\mu_j(f_j^{-1}((t, C]))\, d\nu(t).
\end{align*}
Thus
\begin{align*}
0&<\sum_{j\in [2]}\mu_j(f_j)\\
&=-2C+\int_{[-C, C]}\mu_1(f_1^{-1}((t, C]))\, d\nu(t)+\int_{[-C, C]}\mu_2(f_2^{-1}((t, C]))\, d\nu(t)\\
&=-2C+\int_{[-C, C]}\mu_1(f_1^{-1}((t, C]))\, d\nu(t)+\int_{[-C, C]}\mu_2(f_2^{-1}((-t, C]))\, d\nu(t)\\
&=-2C+\int_{[-C, C]}\left(\mu_1(f_1^{-1}((t, C]))+\mu_2(f_2^{-1}((-t, C]))\right)\, d\nu(t).
\end{align*}
Then there is some $t\in [-C, C]$ such that
$$ \mu_1(f_1^{-1}((t, C]))+\mu_2(f_2^{-1}((-t, C]))>1.$$
Since $\mu_1(f_1^{-1}((t+\varepsilon, C]))+\mu_2(f_2^{-1}((-t+\varepsilon, C]))$ converges to $\mu_1(f_1^{-1}((t, C]))+\mu_2(f_2^{-1}((-t, C]))$ as $\varepsilon\to 0^+$, we can find an $\varepsilon>0$ such that
$$\mu_1(f_1^{-1}((t+\varepsilon, C]))+\mu_2(f_2^{-1}((-t+\varepsilon, C]))>1.$$
We set $U_1=f_1^{-1}((t+\varepsilon, C])$ and $U_2=f_2^{-1}((-t+\varepsilon, C])$. Then $U_1$ and $U_2$ are open, and $\mu_1(U_1)+\mu_2(U_2)>1$. Clearly
$\sum_{j\in [2]} \min_{x\in \overline{U_j}}f_j(x)\ge 2\varepsilon>0$.
\end{proof}

One might hope to extend Lemma~\ref{L-sum} to the case $k\ge 3$ to yield 
$$\sum_{j\in [k]} \min_{x\in \overline{U_j}}f_j(x)>0 \quad \text{ and } \quad \sum_{j\in [k]}\mu_j(U_j)>k-1.$$ 
The following example shows that such an extension does not hold in general.

\begin{example} \label{E-sum3}
For each $j\in [3]$ let $\mu_j=\frac{1}{2}(\delta_{x_j}+\delta_{y_j})\in \cM(X)$ with distinct $x_j, y_j\in X$. By the Tietze extension theorem we can find an $f_j\in C(X)$ for each $j\in [3]$ such that the following hold:
\begin{enumerate}
\item $f_j(x_j)=-f_j(y_j)\in (1, 2)$ for $j=1, 2$, and
\item $f_3(x_3)\in (1, 2), f_3(y_3)\in (-2, -1)$ and $f_3(x_3)+f_3(y_3)>0$.
\end{enumerate}
Then $\sum_{j\in [3]}\mu_j(f_j)>0$. 

We claim that there are no closed sets $A_j\subseteq X$ for $j\in [3]$ satisfying 
$$\sum_{j\in [3]}\min_{x\in A_j}f_j(x)>0 \quad \text{ and } \quad \sum_{j\in [3]}\mu_j(A_j)>2.$$ 
Indeed, assume that such $A_j$ for $j\in [3]$ exist.
Note that $\mu_j(A_j)\in \{0, 1/2, 1\}$ for all $j\in [3]$. Thus there is some $F\subseteq [3]$ with $|F|=2$ such that $\mu_j(A_j)=1$ for all $j\in F$. Then $y_j\in A_j$ for all $j\in F$, whence $f_j(y_j)\ge \min_{x\in A_j}f_j(x)$ for all $j\in F$. Say, $\{i\}=[3]\setminus F$. Then $\mu_i(A_i)>0$. Thus $A_i\cap \{x_i, y_i\}\neq \emptyset$. Since $f_i(x_i)>0>f_i(y_i)$, we have 
$$ f_i(x_i)=\max\{f_i(x_i), f_i(y_i)\}\ge \min_{x\in A_i}f_i(x).$$
It follows that
$$f_i(x_i)+\sum_{j\in F}f_j(y_j)\ge \sum_{j\in [3]}\min_{x\in A_j}f_j(x)>0.$$
But $f_i(x_i)+\sum_{j\in F}f_j(y_j)<2+(-1)+(-1)=0$, a contradiction. This proves our claim. 
\end{example}

\begin{lemma} \label{L-large density}
Let $\mu_1, \mu_2\in \cM(X)$ and $f_1, f_2\in C(X)$ such that $\sum_{j\in [2]}\mu_j(f_j)>0$. Then there are $0<\delta<1$, nonempty closed sets $A_1, A_2\subseteq X$ and a product neighborhood $V_1\times V_2$ of $(\mu_1, \mu_2)$ in $\cM(X)^2$ such that the following hold:
\begin{enumerate}
\item $\sum_{j\in [2]}\min_{x\in A_j}f_j(x)>0$, and
\item for any independence set $F\in \cF(\Gamma)$ of $(V_1, V_2)$ and any surjective map $\psi: F\rightarrow [2]$, there is an $F_\psi\subseteq F$ so that 
    $$\sum_{j\in [2]} \frac{|F_\psi\cap \psi^{-1}(j)|}{|\psi^{-1}(j)|}>1+\delta \quad \text{ and } \quad \bigcap_{s\in F_\psi}s^{-1}A_{\psi(s)}\neq \emptyset.$$
\end{enumerate}
\end{lemma}
\begin{proof} Let $U_1, U_2$ be given by Lemma~\ref{L-sum}. We set $A_j=\overline{U_j}$ for $j\in [2]$. Then
$$\sum_{j\in [2]}\min_{x\in A_j}f_j(x)=\sum_{j\in [2]} \min_{x\in \overline{U_j}}f_j(x)>0. $$

By our choice of $U_1$ and $U_2$ we have $\sum_{j\in [2]}\mu_j(U_j)>1$.
Thus we can take a  $0<\delta<\big(\sum_{j\in [2]}\mu_j(U_j)-1\big)/3$. Then
$$V_j:=\{\nu\in \cM(X): \nu(U_j)>\mu_j(U_j)-\delta\}$$
is an open neighborhood of $\mu_j$ in $\cM(X)$ for $j\in [2]$.

Let $F\in \cF(\Gamma)$ be an independence set for $(V_1, V_2)$ and let $\psi: F\rightarrow [2]$ be surjective. Then we can find some $\nu\in \bigcap_{s\in F}s^{-1}V_{\psi(s)}$. For each $s\in F$, we have $s\nu\in V_{\psi(s)}$ and hence
$$\nu(s^{-1}A_{\psi(s)})=(s\nu)(A_{\psi(s)})\ge (s\nu)(U_{\psi(s)})>\mu_{\psi(s)}(U_{\psi(s)})-\delta.$$
Therefore
\begin{align*}
\int_X \sum_{j\in [2]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}{\bf 1}_{s^{-1}A_j}(x)\, d\nu(x)&=\sum_{j\in [2]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}\nu(s^{-1}A_j)\\
&\ge \sum_{j\in [2]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(\mu_j(U_j)-\delta)\\
&=\sum_{j\in [2]}(\mu_j(U_j)-\delta)>1+\delta.
\end{align*}
Thus there is some $x\in X$ such that
$$\sum_{j\in [2]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}{\bf 1}_{s^{-1}A_j}(x)>1+\delta.$$
We denote by $F_\psi$ the set of $s\in F$ satisfying $sx\in A_{\psi(s)}$. Then
$$  \sum_{j\in [2]} \frac{|F_\psi\cap \psi^{-1}(j)|}{|\psi^{-1}(j)|}=\sum_{j\in [2]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}{\bf 1}_{s^{-1}A_j}(x)>1+\delta,$$
and $x\in \bigcap_{s\in F_\psi}s^{-1}A_{\psi(s)}$.
\end{proof}


We need the following weak version of Stirling's approximation \cite[Lemma 10.1]{KL16}.

\begin{lemma} \label{L-Stirling}
For every $m\in \Nb$ we have
\begin{align} \label{E-Stirling}
e(\frac{m}{e})^m\le m!\le em(\frac{m}{e})^m.
\end{align}
\end{lemma}

We also need the following consequence of Karpovsky and Milman's generalization of the Sauer-Perles-Shelah lemma \cite{KM, Sauer, Shelah} \cite[Lemma 12.14]{KL16}.

\begin{lemma} \label{L-KM}
Let $k\ge 2$ be an integer and $\lambda>1$. Then there is a $c>0$ depending only on $k$ and $\lambda$ such that for any nonempty finite set $Z$ and any $S\subseteq [k]^Z$ with $|S|\ge ((k-1)\lambda)^{|Z|}$ there exists a $J\subseteq Z$ such that $|J|\ge c|Z|$ and $S|_J=[k]^J$.
\end{lemma}

For a finite set $Z$ and $k\in \Nb$, we shall consider the set of maps $\psi: Z\rightarrow [k]$ which are as equidistributed as possible. When $|Z|$ is divisible by $k$, this means $|\psi^{-1}(j)|=|Z|/k$ for all $j\in [k]$. In general case, the precise meaning is given in the following. 

\begin{notation} \label{N-regular}
Let $k\in \Nb$ and let $Z$ be a finite set. We denote by $\sR(Z, k)$ the set of maps $\psi: Z\rightarrow [k]$ satisfying $\left||\psi^{-1}(j)|-|Z|/k\right|< 1$ for all $j\in [k]$.
\end{notation}

For $t\in \Rb$, we write $\lceil t\rceil$ for the smallest integer no less than  $t$. 
%The following is the key combinatorial lemma for the proof of the case $k=2$ of Theorem~\ref{T-IE main}. 
In the proof of the case $k=2$ of Theorem~\ref{T-IE main}, we shall obtain $F_\psi$ from Lemma~\ref{L-large density} and apply Lemma~\ref{L-half to indep} with $Z=F$ and $Z_\psi=F_\psi$. In order for the condition $\sum_{j\in [2]} \frac{|F_\psi\cap \psi^{-1}(j)|}{|\psi^{-1}(j)|}>1+\delta$ in Lemma~\ref{L-large density} to imply the condition $|Z_\psi|\ge \tau|Z|$ in Lemma~\ref{L-half to indep}, we need $|\psi^{-1}(1)|$  and $|\psi^{-1}(2)|$ to be almost equal, whence in Lemma~\ref{L-half to indep} we restrict our attention to $\psi\in \sR(Z, k)$.  

\begin{lemma} \label{L-half to indep}
Let $k\in \Nb$ and $\tau\in ((k-1)/k, 1]$. Then there exist $c, N>0$ depending only on $k$ and $\tau$ such that the following holds. For any finite set $Z$ with $|Z|\ge N$, if for each $\psi\in \sR(Z, k)$  we take a $Z_\psi\subseteq Z$  with $|Z_\psi|\ge \tau |Z|$, then there is some $J\subseteq Z$ with $|J|\ge c|Z|$ such that every map $\sigma: J\rightarrow [k]$ extends to a $\psi\in \sR(Z, k)$ so that $J\subseteq Z_\psi$.
\end{lemma}
\begin{proof} The case $k=1$ is obvious. Thus we may assume $k\ge 2$. 
Recall the function $g: [0, 1]\rightarrow \Rb$ defined by \eqref{E-Shannon}.
Note that
\begin{align*}
\lim_{\delta \to 0^+}&\frac{-g(\tau)-g(1-\delta)+g(\tau-\delta)+\delta \log k}{\delta}\\
& =-g'(\tau)+g'(1)+\log k=\log (k\tau)>\log (k-1).
\end{align*}
We take $\theta_1>\theta_2$ in $(\log (k-1), \log (k\tau))$. 
Then we can find a $\delta\in (0, \tau)$ small enough so that
\begin{align} \label{E-half to indep1}
 \frac{-g(\tau)-g(1-\delta)+g(\tau-\delta)+\delta \log k}{\delta}>\theta_1.
 \end{align}
Let $\lambda=e^{\theta_2}/(k-1)>1$. Then we have $c>0$ given by Lemma~\ref{L-KM} for $k$ and $\lambda$.
We take a large integer $N\ge k$ such that $(\tau-\delta)N>1$ and
\begin{align} \label{E-half to indep2}
\frac{ (1-\delta)^{-1}k^k}{e^{k+1}t^{2k} (\tau t-\delta t+1)^2} e^{\delta t \theta_1}\ge e^{\theta_2+\delta t\theta_2}
\end{align}
for all $t\ge N$. We shall show that $c\delta$ and $N$ have the desired property. 


Let $Z$ be a finite set with $|Z|\ge N$, and let $Z_\psi\subseteq Z$ with $|Z_\psi|\ge \tau|Z|$ for each $\psi\in \sR(Z, k)$. We can find a $Z'\subseteq Z$ such that $|Z'|$ is divisible by $k$ and $|Z\setminus Z'|<k$.
We denote by $\Xi$ the set of $(\psi, W)$ such that $\psi\in \sR(Z, k)$ and $W\subseteq Z_\psi$ with $|W|=\lceil\delta |Z|\rceil$.


For each $\psi\in \sR(Z, k)$, the number of $W\subseteq Z_\psi$ with $|W|=\lceil\delta |Z|\rceil$ is
$$ \binom{|Z_\psi|}{\lceil\delta |Z|\rceil}\ge \binom{\lceil \tau |Z|\rceil}{\lceil\delta |Z|\rceil}.$$
Thus
\begin{align*}
 |\Xi|&\ge |\sR(Z, k)|\cdot \binom{\lceil\tau |Z|\rceil}{\lceil\delta |Z|\rceil}\ge |\sR(Z', k)|\cdot \binom{\lceil\tau |Z|\rceil}{\lceil\delta |Z|\rceil}\\
 &=\frac{|Z'|!}{\left(\left(\frac{1}{k}|Z'|\right)!\right)^k}\cdot \binom{\lceil \tau |Z|\rceil}{\lceil\delta |Z|\rceil} \ge \frac{|Z|!}{|Z|^{k-1}\left(\left(\frac{1}{k}|Z'|\right)!\right)^k}\cdot \binom{\lceil \tau |Z|\rceil}{\lceil\delta |Z|\rceil}.
 \end{align*}
The number of $W\subseteq Z$ with $|W|=\lceil\delta |Z|\rceil$ is $\binom{|Z|}{\lceil\delta |Z|\rceil}$. Thus we can find some $W\subseteq Z$ with $|W|=\lceil\delta |Z|\rceil$ so that
$$|\Xi_W|\ge |\Xi|/\binom{|Z|}{\lceil\delta |Z|\rceil}\ge \frac{|Z|!}{|Z|^{k-1}\left(\left(\frac{1}{k}|Z'|\right)!\right)^k}\cdot \binom{\lceil \tau |Z|\rceil}{\lceil\delta |Z|\rceil}\Big/\binom{|Z|}{\lceil\delta |Z|\rceil},$$
where $\Xi_W$ is the set of $(\psi, W)\in \Xi$.

The number of maps $\phi: Z\setminus W\rightarrow [k]$ is $k^{|Z\setminus W|}$. Thus we can find some $\phi: Z\setminus W\rightarrow [k]$
such that
$$|\Xi_{W, \phi}|\ge |\Xi_W|/k^{|Z\setminus W|},$$
where $\Xi_{W, \phi}$ is the set of $(\psi, W)\in \Xi_W$ satisfying $\psi|_{Z\setminus W}=\phi$.

We denote by $S$ the set of $\psi|_W$ for $(\psi, W)\in \Xi_{W, \phi}$. The map $\Xi_{W, \phi}\rightarrow S$ sending $(\psi, W)$ to $\psi|_W$ is a bijection. Thus
$$ |S|= |\Xi_{W, \phi}|\ge |\Xi_W|/k^{|Z\setminus W|}\ge \frac{|Z|!}{|Z|^{k-1}\left(\left(\frac{1}{k}|Z'|\right)!\right)^k}\cdot \binom{\lceil \tau |Z|\rceil}{\lceil\delta |Z|\rceil}\Big/\left(\binom{|Z|}{\lceil\delta |Z|\rceil}k^{|Z\setminus W|}\right).$$

Since $(\tau-\delta)|Z|\ge (\tau-\delta)N>1$, we have $\lceil \tau |Z|\rceil>\lceil\delta|Z|\rceil$. We can estimate the last term of the above inequalities as follows:
\begin{align*}
 & \frac{|Z|!}{|Z|^{k-1}\left(\left(\frac{1}{k}|Z'|\right)!\right)^k}\cdot \binom{\lceil \tau |Z|\rceil}{\lceil\delta |Z|\rceil}\Big/\left(\binom{|Z|}{\lceil\delta |Z|\rceil}k^{|Z\setminus W|}\right)\\
&=\frac{\left(\lceil \tau |Z|\rceil\right)!\cdot \left(|Z|-\lceil\delta|Z|\rceil\right)!}{|Z|^{k-1}\left(\left(\frac{1}{k}|Z'|\right)!\right)^k\cdot \left(\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil\right)!\cdot k^{|Z|-\lceil\delta |Z|\rceil}}\\
&\overset{\eqref{E-Stirling}}\ge \frac{e \left(\frac{\lceil \tau |Z|\rceil}{e}\right)^{\lceil \tau |Z|\rceil}e\left(\frac{|Z|-\lceil\delta |Z|\rceil}{e}\right)^{|Z|-\lceil\delta |Z|\rceil}}{|Z|^{k-1}\left(\frac{e}{k}|Z'|\left(\frac{1}{ek}|Z'|\right)^{\frac{1}{k}|Z'|}\right)^k\cdot e\left(\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil\right)\left(\frac{\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil}{e}\right)^{\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil}\cdot k^{|Z|-\lceil\delta |Z|\rceil}}\\
&\ge \frac{e \left(\frac{\lceil \tau |Z|\rceil}{e}\right)^{\lceil \tau |Z|\rceil}e\left(\frac{|Z|-\lceil\delta |Z|\rceil}{e}\right)^{|Z|-\lceil\delta |Z|\rceil}}{|Z|^{k-1}\left(\frac{e}{k}|Z|\left(\frac{1}{ek}|Z|\right)^{\frac{1}{k}|Z|}\right)^k\cdot e\left(\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil\right)\left(\frac{\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil}{e}\right)^{\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil}\cdot k^{|Z|-\lceil\delta |Z|\rceil}}\\
&= \frac{ k^{k+\lceil\delta|Z|\rceil}\lceil \tau |Z|\rceil^{\lceil \tau |Z|\rceil}\left(|Z|-\lceil\delta |Z|\rceil\right)^{|Z|-\lceil\delta |Z|\rceil}}{e^{k-1}|Z|^{2k-1+|Z|}\cdot \left(\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil\right)^{\lceil \tau |Z|\rceil-\lceil\delta|Z|\rceil+1}}\\
&\ge \frac{ k^{k+\delta|Z|}(\tau |Z|)^{ \tau |Z|}(|Z|-\delta |Z|-1)^{|Z|-\delta |Z|-1}}{e^{k-1}|Z|^{2k-1+|Z|}\cdot (\tau |Z|-\delta|Z|+1)^{\tau |Z|-\delta|Z|+2}}.
\end{align*}
Note that $(1+\frac{1}{t})^t\le e$ for all $t> 0$. Since  $|Z|-\delta |Z|\ge (1-\delta)N>1$, we have
$$\left(|Z|-\delta|Z|-1\right)^{|Z|-\delta|Z|-1}\ge \left(|Z|-\delta|Z|\right)^{|Z|-\delta|Z|-1}/e$$
and
 $$\left(\tau|Z|-\delta|Z|+1\right)^{\tau|Z|-\delta|Z|}\le e\left(\tau|Z|-\delta|Z|\right)^{\tau|Z|-\delta|Z|},$$
 and hence
\begin{align*}
|S|&\ge \frac{ k^{k+\delta|Z|}(\tau |Z|)^{ \tau |Z|}(|Z|-\delta |Z|-1)^{|Z|-\delta |Z|-1}}{e^{k-1}|Z|^{2k-1+|Z|}\cdot (\tau |Z|-\delta|Z|+1)^{\tau |Z|-\delta|Z|+2}}\\
&\ge \frac{ k^{k+\delta|Z|}\left(\tau |Z|\right)^{ \tau |Z|}\left(|Z|-\delta |Z|\right)^{|Z|-\delta |Z|-1}}{e^{k+1}|Z|^{2k-1+|Z|}\cdot \left(\tau |Z|-\delta|Z|+1\right)^2\left(\tau |Z|-\delta|Z|\right)^{\tau |Z|-\delta|Z|}}\\
&= \frac{ k^{k+\delta|Z|}\tau^{ \tau |Z|}(1-\delta)^{|Z|-\delta |Z|-1}}{e^{k+1}|Z|^{2k}\cdot \left(\tau |Z|-\delta|Z|+1\right)^2(\tau-\delta)^{\tau |Z|-\delta|Z|}}\\
&=\frac{ (1-\delta)^{-1}k^k}{e^{k+1}|Z|^{2k} \left(\tau|Z|-\delta|Z|+1\right)^2} e^{|Z|(-g(\tau)-g(1-\delta)+g(\tau-\delta)+\delta \log k)}\\
&\overset{\eqref{E-half to indep1}}\ge \frac{ (1-\delta)^{-1}k^k}{e^{k+1}|Z|^{2k} \left(\tau|Z|-\delta|Z|+1\right)^2} e^{|Z|\delta \theta_1}\\
&\overset{\eqref{E-half to indep2}}\ge e^{\theta_2+|Z|\delta \theta_2}\ge e^{\lceil \delta |Z|\rceil \theta_2}=e^{|W|\theta_2}=((k-1)\lambda)^{|W|}.
\end{align*}
By our choice of $c$, we can find some $J\subseteq W$ such that $|J|\ge c|W|$ and $S|_J=[k]^J$. Then $|J|\ge c|W|\ge c\delta |Z|$, and every map $\sigma: J\rightarrow [k]$ extends to a $\psi\in \sR(Z, k)$ such that $J\subseteq W\subseteq Z_\psi$.
\end{proof}

The condition $\tau>(k-1)/k$ in Lemma~\ref{L-half to indep} cannot be weakened to $\tau\ge (k-1)/k$, as the following example shows.


\begin{example} \label{E-half to indep}
Let $k\ge 2$ be an integer. Let $N\in k^2\Nb$ and let $Z=[N]$. Let $\psi\in \sR(Z, k)$.  We choose a $Z_\psi\subseteq Z$ with $|Z_\psi|=\frac{k-1}{k}|Z|$ as follows. For each $j\in [k]$, noting that $|\psi^{-1}(j)|=|Z|/k$, we may list the element of $\psi^{-1}(j)$ as $$a_{j, 1}<a_{j, 2}<\dots< a_{j, N/k},$$
and set
$$b_{j, i}=a_{j, iN/k^2}$$
for $i\in [k]$. We take the $j_1\in [k]$ such that $b_{j_1, 1}$ is the largest among $b_{j, 1}$ for $j\in [k]$. Next we take the $j_2\in [k]\setminus \{j_1\}$ such that $b_{j_2, 2}$ is the largest among $b_{j, 2}$ for $j\in [k]\setminus \{j_1\}$. Inductively, we take the $j_l\in [k]\setminus \{j_1, \dots, j_{l-1}\}$ such that $b_{j_l, l}$ is the largest among $b_{j, l}$ for $j\in [k]\setminus \{j_1, \dots, j_{l-1}\}$. Then $\{j_1, \dots, j_k\}=[k]$. We set
\begin{align*}
Z_{\psi, j_l}&=\psi^{-1}(j_l)\setminus \{a_{j_l, i}: (l-1)N/k^2<i\le lN/k^2\}\\
&=\{z\in \psi^{-1}(j_l): z\le b_{j_l, l-1} \mbox{ or } z>b_{j_l, l}\}
\end{align*}
for each $l\in [k]$, where we set $b_{j_1, 0}=0$, and
$$Z_\psi=\bigcup_{j\in [k]}Z_{\psi, j}.$$
Then
$$|Z_{\psi, j}|=\frac{k-1}{k}|\psi^{-1}(j)|=\frac{k-1}{k}\frac{|Z|}{k}$$
for each $j\in [k]$, and
$$|Z_\psi|=\frac{k-1}{k}|Z|.$$

We claim that there is no strictly increasing map $\xi: [k]\rightarrow Z_\psi$ such that 
$$\psi \circ \xi(l)=j_l$$ 
for all $l\in [k]$. Assume that there is one such $\xi$. Then $\xi(l)\in Z_\psi\cap \psi^{-1}(j_l)=Z_{\psi, j_l}$ for each $l\in [k]$. Note that $\xi(2)>\xi(1)>b_{j_1, 1}>b_{j_2, 1}$, whence $\xi(2)>b_{j_2, 2}$. Then $\xi(3)>\xi(2)>b_{j_2, 2}>b_{j_3, 2}$, whence $\xi(3)>b_{j_3, 3}$. Going on this way, we get $\xi(l)>b_{j_l, l}$ for all $l\in [k]$. In particular, $\xi(k)>b_{j_k, k}$, which is impossible.  This proves our claim.


Now we claim that there is no $J\subseteq Z$ with $|J|\ge k\cdot k!$ such that every map $\sigma: J\rightarrow [k]$ extends to a $\psi\in \sR(Z, k)$ so that $J\subseteq Z_\psi$. Assume that there is one such  $J$. 
We denote by $\Sym(k)$ the permutation group of $[k]$. Then the map $\phi': [k]\rightarrow [k]$ sending $l$ to $j_l$ lies in $\Sym(k)$. Since $|J|\ge k\cdot k!$, we can find pairwise disjoint sets $J_{\phi}\subseteq J$ for $\phi\in \Sym(k)$ such that $|J_{\phi}|=k$ for all $\phi\in \Sym(k)$. We list the elements of $J_{\phi}$ as $a_{\phi, 1}<a_{\phi, 2}<\dots<a_{\phi, k}$ for each $\phi\in \Sym(k)$.  Then we can find  a map $\sigma: J\rightarrow [k]$ such that
$$\sigma(a_{\phi, l})=\phi(l)$$
for all $\phi\in \Sym(k)$ and $l\in [k]$. By assumption $\sigma$ extends to some $\psi\in \sR(Z, k)$ such that $J\subseteq Z_\psi$. We define  a map $\xi: [k]\rightarrow J_{\phi'}\subseteq J\subseteq Z_\psi$ by $\xi(l)=a_{\phi', l}$ for all $l\in [k]$. Then $\xi: [k]\rightarrow Z_\psi$ is strictly increasing and 
$$\psi \circ \xi(l)=\sigma(\xi(l))=\sigma(a_{\phi', l})=\phi'(l)=j_l$$ 
for all $l\in [k]$, which is impossible as we showed in the above paragraph. This proves our claim. 

For any $c>0$, when $|Z|\in k^2\Nb$ is large enough, one has $c|Z|\ge k\cdot k!$. This shows that the condition $\tau>(k-1)/k$ in Lemma~\ref{L-half to indep} is optimal, even if we require that $|Z_\psi\cap \psi^{-1}(j)|$ is the same for all $j\in [k]$.
\end{example}

We are ready to prove the case $k=2$ of Theorem~\ref{T-IE main}.

\begin{proof}[Proof of the case $k=2$ of Theorem~\ref{T-IE main}] In view of Lemma~\ref{L-Hahn Banach IE}, it suffices to show that given any $(\mu_1, \mu_2)\in \IE_2(\cM(X))$ and $f_1, f_2\in C(X)$ satisfying $\sum_{j\in [2]}\mu_j(f_j)>0$, there is a pair $(x_1, x_2)\in \IE_2(X)$ such that $\sum_{j\in [2]}f_j(x_j)>0$.

We have $\delta, A_1, A_2$ and $V_1\times V_2$ given by Lemma~\ref{L-large density}. We set $k=2$ and $\tau=\frac{1}{2}(1+\frac{\delta}{2})$. Then we have $c$ and $N$ given by Lemma~\ref{L-half to indep}. We take an $N_1\ge \max(N, 2)$ such that $\frac{t-1}{2}\cdot (1+\delta)>t\tau$ for all $t\ge N_1$.

Let $F\in \cF(\Gamma)$ be an independence set for $(V_1, V_2)$ such that $|F|\ge N_1$. Let $\psi\in \sR(F, 2)$. Then the map $\psi: F\rightarrow [2]$ is surjective, whence by our choice of $\delta, A_1, A_2$ and $V_1\times V_2$ there is an $F_\psi\subseteq F$ such that 
$$\sum_{j\in [2]}\frac{|F_\psi\cap \psi^{-1}(j)|}{|\psi^{-1}(j)|}>1+\delta \quad \text{ and } \quad \bigcap_{s\in F_\psi}s^{-1}A_{\psi(s)}\neq \emptyset.$$ 
Note that
\begin{align*}
|F_\psi|&=\sum_{j\in [2]}\left(|\psi^{-1}(j)|\cdot \frac{|F_\psi\cap \psi^{-1}(j)|}{|\psi^{-1}(j)|}\right)\ge \sum_{j\in [2]}\left(\frac{|F|-1}{2}\cdot \frac{|F_\psi\cap \psi^{-1}(j)|}{|\psi^{-1}(j)|}\right)\\
&\ge \frac{|F|-1}{2}\cdot(1+\delta)\ge \tau |F|.
\end{align*}
By our choice of $c$ and $N$, we can find a $J\subseteq F$ with $|J|\ge c|F|$ such that every map $\sigma: J\rightarrow [2]$ extends to a $\psi\in \sR(F, 2)$ so that $J\subseteq F_\psi$. Then
$$\bigcap_{s\in J}s^{-1}A_{\sigma(s)}\supseteq \bigcap_{s\in F_\psi}s^{-1}A_{\psi(s)}$$
is nonempty. This means that $J$ is an independence set for $(A_1, A_2)$.

Since $(\mu_1, \mu_2)\in \IE_2(\cM(X))$, the pair $(V_1, V_2)$ has positive independence density. It follows that  $(A_1, A_2)$ has positive independence density. By Theorem~\ref{T-IE basic}.\eqref{i-IE tuple} there is some $(x_1, x_2)\in \IE_2(X)$ such that $x_j\in A_j$ for each $j\in [2]$. Then 
$$\sum_{j\in [2]}f_j(x_j)\ge \sum_{j\in [2]}\min_{x\in A_j}f_j(x)>0$$ 
by our choice of $A_1$ and $A_2$.
\end{proof}



