\subsection{Proof of Lemma~\ref{L-func to indep}} \label{SS-combinatorial}

In this subsection we prove our key combinatorial Lemma~\ref{L-func to indep}.

The following lemma says roughly that given a large enough finite set $Z$, for most $\psi\in [k]^Z$, the partition of $Z$ given by $\psi^{-1}(j)$ for $j\in [k]$ is almost even distributed and furthermore is almost independent to any given partition $\cP$ of $Z$.

\begin{lemma} \label{L-indep to partition}
Let $k\ge 2$ be an integer,  $0<\eta<1$, and $0<\varepsilon<1/k$. Then there are some $\delta_1, N_1>0$ depending only on $k, \eta$ and $\varepsilon$ such that the following holds.  For any finite set $Z$ with $|Z|\ge N_1$, and any partition $\cP$ of $Z$,  setting
$$V_{\cP, \varepsilon, \eta}=\left\{\psi\in [k]^Z: \left|\frac{|\psi^{-1}(j)\cap P|}{|P|}-\frac{1}{k}\right|\ge \varepsilon \mbox{ for some } j\in [k] \mbox{ and }  P\in \cP \mbox{ with } \frac{|P|}{|Z|}\ge \eta\right\},$$
we have
$$ |V_{\cP, \varepsilon, \eta}|\le \left|[k]^Z\right|e^{-\delta_1|Z|}.$$
\end{lemma}
\begin{proof}
Recall the function $g: [0, 1]\rightarrow \Rb$ defined in \eqref{E-Shannon}. We define a 
function $h: [0, 1]\rightarrow \Rb$ by
$$h(t)=g(t)+g(1-t)+(1-t)\log (k-1)$$
for $t\in [0, 1]$.
Note that
$$h'(t)=-\log t+\log (1-t)-\log (k-1)$$
for $t\in (0, 1)$. Clearly $h'$ is strictly decreasing on $(0, 1)$, and $h'(\frac{1}{k})=0$. Thus $h$ is strictly increasing on $[0, \frac{1}{k}]$ and strictly decreasing on $[\frac{1}{k}, 1]$. Note that
$$ h(\frac{1}{k})=\frac{1}{k}\log k+\frac{k-1}{k}\log \frac{k}{k-1}+\frac{k-1}{k}\log (k-1)=\log k,$$
and
$$h(0)=\log (k-1).$$
We set
$$ \delta_1=\frac{\eta}{2}\left(h(\frac{1}{k})-\max_{t\in [0, \frac{1}{k}-\varepsilon]\cup [\frac{1}{k}+\varepsilon, 1]}h(t)\right)>0.$$
Then 
\begin{align} \label{E-indep to partition}
\delta_1\le \frac{\eta}{2}\left(h(\frac{1}{k})-h(0)\right)=\frac{\eta}{2}\left(h(\frac{1}{k})-\log (k-1)\right).
\end{align}
We take a large $N\ge 3$ such that 
$$t(t+1)k/\eta\le e^{t\delta_1/\eta+1}$$ 
for all $t\ge N$. We set $N_1:=N/\eta$. We shall show that $\delta_1$ and $N_1$ have the desired property. 

Let $Z$ be a finite set with $|Z|\ge N_1$ and let $\cP$ be a partition of $Z$.


We denote by $\cP_\eta$ the set of $P\in \cP$ satisfying $\frac{|P|}{|Z|}\ge \eta$. For each $P\in \cP_\eta$ and $j\in [k]$, we set
$$ V_{P, j, \varepsilon}=\left\{\psi\in [k]^Z: \left|\frac{|\psi^{-1}(j)\cap P|}{|P|}-\frac{1}{k}\right|\ge \varepsilon\right\},$$
and
$$ W_{P, j, \varepsilon}=\left\{\psi\in [k]^P: \left|\frac{|\psi^{-1}(j)|}{|P|}-\frac{1}{k}\right|\ge \varepsilon\right\}.$$
We have
\begin{align*}
V_{\cP, \varepsilon, \eta}=\bigcup_{P\in \cP_\eta}\bigcup_{j\in [k]}V_{P, j, \varepsilon},
\end{align*}
whence
\begin{align*}
|V_{\cP, \varepsilon, \eta}|\le \sum_{P\in \cP_\eta, j\in [k]}|V_{P, j, \varepsilon}|=  \sum_{P\in \cP_\eta, j\in [k]}|W_{P, j, \varepsilon}|k^{|Z|-|P|}.
\end{align*}

Let $P\in \cP_\eta$ and $j\in [k]$. We have
$$ |W_{P, j, \varepsilon}|= \sum_{0\le i\le |P|, \left|\frac{i}{|P|}-\frac{1}{k}\right|\ge \varepsilon} (k-1)^{|P|-i}\binom{|P|}{i}.$$
When $\left|\frac{i}{|P|}-\frac{1}{k}\right|\ge \varepsilon$ and $0<i<|P|$, we have
\begin{align*}
(k-1)^{|P|-i}\binom{|P|}{i}&=(k-1)^{|P|-i}\frac{|P|!}{i! (|P|-i)!}\overset{\eqref{E-Stirling}}\le \frac{(k-1)^{|P|-i}e|P|(\frac{|P|}{e})^{|P|}}{e(\frac{i}{e})^i e(\frac{|P|-i}{e})^{|P|-i}}\\
&=(k-1)^{|P|-i}e^{-1}|P|e^{|P|\left(g(\frac{i}{|P|})+g(\frac{|P|-i}{|P|})\right)}\\
&=e^{-1}|P|e^{|P|h(\frac{i}{|P|})}\le e^{-1}|P|e^{|P|\left(h(\frac{1}{k})-2\delta_1/\eta\right)}. 
\end{align*}
Note that $|P|\ge \eta|Z|\ge N\ge 3$. For $i=0$ or $|P|$, clearly
$$ (k-1)^{|P|-i}\binom{|P|}{i}\le (k-1)^{|P|}\le e^{-1}|P|(k-1)^{|P|}\overset{\eqref{E-indep to partition}}\le e^{-1}|P|e^{|P|\left(h(\frac{1}{k})-2\delta_1/\eta\right)}.$$
Thus
$$(k-1)^{|P|-i}\binom{|P|}{i}\le e^{-1}|P|e^{|P|\left(h(\frac{1}{k})-2\delta_1/\eta\right)}$$
for every integer $0\le i\le |P|$ satisfying $\left|\frac{i}{|P|}-\frac{1}{k}\right|\ge \varepsilon$. 
Since $|P|\ge N$, we have
$$ |P|(|P|+1)k/\eta\le e^{|P|\delta_1/\eta+1}.$$
Therefore
$$ |W_{P, j, \varepsilon}|\le (|P|+1)e^{-1}|P|e^{|P|\left(h(\frac{1}{k})-2\delta_1/\eta\right)}\le  \frac{\eta}{k}e^{|P|\left(h(\frac{1}{k})-\delta_1/\eta\right)}=\frac{\eta}{k}e^{|P|(\log k-\delta_1/\eta)}.$$

Note that $|\cP_\eta|\le \frac{1}{\eta}$. 
Thus
\begin{align*}
|V_{\cP, \varepsilon, \eta}|&\le \sum_{P\in \cP_\eta, j\in [k]}|W_{P, j, \varepsilon}|k^{|Z|-|P|}\le  \sum_{P\in \cP_\eta, j\in [k]}\frac{\eta}{k}e^{|P|(\log k-\delta_1/\eta)}k^{|Z|-|P|}\\
&=\sum_{P\in \cP_\eta, j\in [k]}\frac{\eta}{k}e^{|Z|\log k-|P|\delta_1/\eta}\le \sum_{P\in \cP_\eta, j\in [k]}\frac{\eta}{k}e^{|Z|(\log k- \delta_1)}\\
&=|\cP_\eta|\eta e^{|Z|(\log k- \delta_1)}\le e^{|Z|(\log k-\delta_1)}=\left|[k]^Z\right|e^{-\delta_1 |Z|}. \tag*{\qedsymbol}
\end{align*}
     \renewcommand{\qedsymbol}{}
     \vspace{-\baselineskip}
\end{proof}

\begin{notation} \label{N-cover}
Let $k\in \Nb$ and let $Z$ be a finite set. For each  $\phi: Z\rightarrow [k]$, we denote by $U_\phi$ the subset $\prod_{z\in Z}(\{0, 1, \dots, k\}\setminus \{\phi(z)\})$ of $\{0, 1, \dots, k\}^Z$. For any $S\subseteq \{0, 1, \dots, k\}^Z$, we denote by $N_S$ the minimal number of $U_\phi$ needed to cover $S$.
\end{notation}

We need the following lemma of Kerr and Li \cite[Lemma 3.3]{KL07} \cite[Lemma 12.13]{KL16}.

\begin{lemma} \label{L-07}
Let $k\ge 2$ be an integer and $b>0$. There exists a constant $c>0$ depending only on $k$ and $b$ such that for every nonempty finite set $Z$ and $S\subseteq \{0, 1, \dots, k\}^Z$ with $N_S\ge k^{b|Z|}$ there exists a $J\subseteq Z$ with $|J|\ge c|Z|$ and $S|_J\supseteq [k]^J$.
\end{lemma}

For any nonempty finite set $Z$ and any $f: Z\rightarrow \Rb$, we denote by $\|f\|_p$ the $\ell_p$-norm of $f$ for $1\le p\le \infty$, i.e., 
\begin{align}\label{E-p norm1}
 \|f\|_p=\left(\sum_{z\in Z}|f(z)|^p\right)^{1/p} 
 \end{align}
when $1\le p<\infty$ and
\begin{align} \label{E-p norm2}
 \|f\|_\infty=\max_{z\in Z}|f(z)|.
 \end{align}

\begin{lemma} \label{L-func to indep pre}
Let $k\in \Nb$ and $0<r<R\le C$. Also let $1<p\le \infty$ and $1\le q< \infty$ such that $1/p+1/q=1$. Then there exist $c, N, \delta>0$ and a finite set $T\subseteq \Rb^k$ depending only on $k, r, R, C$ and $p$ such that the following hold:
\begin{enumerate}
\item $\frac{1}{k}\sum_{j\in [k]}t_j\ge r$ for every $(t_1, \dots, t_k)\in T$, and
\item for any finite set $Z$ with $|Z|\ge N$ and any $\sR\subseteq [k]^Z$ with $|\sR|\ge \left| [k]^Z\right| e^{-\delta |Z|}$, if for each $\psi\in \sR$  we take an $f_\psi: Z\rightarrow \Rb$  with  $\|f_\psi\|_p\le C$ and $\frac{1}{|Z|^{1/q}}\sum_{z\in Z}f_\psi(z)\ge R$, then there are some $J\subseteq Z$ with $|J|\ge c|Z|$ and $(t_1, \dots, t_k)\in T$  such that every map $\sigma: J\rightarrow [k]$ extends to a $\psi\in \sR$ so that $f_\psi(z)\ge t_j|Z|^{-1/p}$ for all $j\in [k]$ and $z\in \sigma^{-1}(j)$.
\end{enumerate}
\end{lemma}
\begin{proof}
We consider first the case  $k=1$. We may take $N=1$, $T=\{r\}$ and any $c, \delta>0$ such that $R>\max_{t\in [0, c]}\left(Ct^{1/q}+r(1-t)\right)$. Indeed, for any nonempty finite set $Z$, there is only $\psi$ in $[k]^Z$. For any $f_\psi: Z\rightarrow \Rb$ with $\|f_\psi\|_p\le C$ and $\frac{1}{|Z|^{1/q}}\sum_{z\in Z}f_\psi(z)\ge R$, denoting by $J$ the set of $z\in Z$ satisfying $f_\psi(z)\ge r|Z|^{-1/p}$, using Hölder's inequality we have
\begin{align*}
R|Z|^{1/q}&\le \sum_{z\in Z}f_\psi(z)=\sum_{z\in J}f_\psi(z)+\sum_{z\in Z\setminus J}f_\psi(z)\le \|f_\psi\|_p\cdot \|{\bf 1}_J\|_q+\sum_{z\in Z\setminus J}r|Z|^{-1/p}\\
&\le C|J|^{1/q}+r|Z|^{-1/p}|Z\setminus J|,
\end{align*}
whence
$$R\le C\left(\frac{|J|}{|Z|}\right)^{1/q}+r\left(1-\frac{|J|}{|Z|}\right),$$
which implies $|J|>c|Z|$.

Next we consider the case $k\ge 2$.
We take a small $0<\tau<1/2$ such that
$$(k\tau)^{1/q}C\le \frac{R-r}{4}.$$




We take a large $M\in \Nb$ such that
\begin{align} \label{E-func to indep6}
\tau^{-1/p}\frac{C}{M}< \frac{R-r}{2}.
\end{align}
We denote by $I$ the set of $\boldsymbol{i}=(i_1, \dots, i_k)\in [2M]^k$ satisfying
$$\frac{1}{k}\sum_{j\in [k]}\tau^{-1/p}\left(-C+\frac{(i_j-1)C}{M}\right)\ge r.$$
When $i_j=2M$ for all $j\in [k]$, we have
\begin{align*}
 \frac{1}{k}\sum_{j\in [k]}\tau^{-1/p}\left(-C+\frac{(i_j-1)C}{M}\right)&=\tau^{-1/p}\left(-C+\frac{(2M-1)C}{M}\right)\\
 &=\tau^{-1/p}C-\tau^{-1/p}\frac{C}{M}\\
 &> C-\frac{R-r}{2}\ge R-\frac{R-r}{2}>r. 
 \end{align*}
Thus $(2M, \dots, 2M)\in I$, whence $I$ is nonempty. We denote by $T$ the set of
$$\tau^{-1/p}\left(-C+\frac{(i_1-1)C}{M}, \dots, -C+\frac{(i_k-1)C}{M}\right)\in [-\tau^{-1/p}C, \tau^{-1/p}C]^k$$
for $\boldsymbol{i}=(i_1, \dots, i_k)\in I$. Then $\frac{1}{k}\sum_{j\in [k]}t_j\ge r$ for every $(t_1, \dots, t_k)\in T$.

We take $0<\eta<1$ and $0<\varepsilon<1/k$ small enough such that
\begin{align} \label{E-func to indep4}
(k^{|I|}\eta+k\varepsilon+k\tau)^{1/q}C\le \frac{R-r}{2}.
\end{align}
Then we have $\delta_1, N_1>0$ given by Lemma~\ref{L-indep to partition}. We set 
$$\delta=\delta_1/3>0,$$ 
and take a large $N_2>0$ such that
\begin{align} \label{E-func to indep7}
|I|^{|I|}\le e^{\delta N_2}.
\end{align}
We set 
$$N=\max(1/(\varepsilon \eta), N_1, N_2)>0.$$ 
Let $c>0$ be given by Lemma~\ref{L-07} for $k$ and $b=\frac{\delta}{|I|\log k}$. 

We shall show that $c, N, \delta$ and $T$ have the desired property. We have checked that the condition (1) holds. Thus it suffices to check the condition (2). 

Let $Z$ be a finite set with $|Z|\ge N$ and let $\sR\subseteq [k]^Z$ with $|\sR|\ge \left| [k]^Z\right| e^{-\delta |Z|}$.
For each $\psi\in \sR$, we fix an $f_\psi: Z\rightarrow \Rb$ with $\|f_\psi\|_p\le C$ and  $\frac{1}{|Z|^{1/q}}\sum_{z\in Z}f_\psi(z)\ge R$.
For any $\phi, \psi: Z\rightarrow [k]$, we set
$$E_{\phi, \psi}=\{z\in Z: \phi(z)=\psi(z)\}.$$

For each $\psi\in \sR$ and $\boldsymbol{i}=(i_1, \dots, i_k)\in I$, we set
$$Z_{\psi, \boldsymbol{i}}=\bigcup_{j\in [k]}\left(\psi^{-1}(j)\cap f_\psi^{-1}\left((\tau|Z|)^{-1/p}\left[-C+\frac{(i_j-1)C}{M}, C\right]\right)\right)\subseteq Z,$$
and define a map $\psi_{\boldsymbol{i}}: Z\rightarrow \{0, 1, \dots, k\}$ by
\begin{align*}
\psi_{\boldsymbol{i}}(z)=\begin{cases}
\psi(z) & \quad \text{if } z\in Z_{\psi, \boldsymbol{i}}\\
0 & \quad \text{otherwise}.\\
\end{cases}
\end{align*}
We set
$$S_{\boldsymbol{i}}=\{\psi_{\boldsymbol{i}}: \psi\in \sR\}$$
for each $\boldsymbol{i}\in I$, and
$$S=\bigcup_{\boldsymbol{i}\in I}S_{\boldsymbol{i}}.$$

We shall apply Lemma~\ref{L-07} to $S_{\boldsymbol{i}}$ for certain $\boldsymbol{i}\in I$. For this purpose, we shall show that $N_S$ is large, and then conclude that $N_{S_{\boldsymbol{i}}}$ is large for at least one $\boldsymbol{i}\in I$. 
For any $\phi\in [k]^Z$, $\psi\in \sR$ and $\boldsymbol{i}\in I$, note that $\psi_{\boldsymbol{i}}\in U_\phi$ if and only if
$$E_{\phi, \psi}\subseteq  Z\setminus Z_{\psi, \boldsymbol{i}}.$$

Let $W\subseteq [k]^Z$ such that $U_\phi$ for $\phi\in W$ cover $S$. For each $\psi\in \sR$ and $\boldsymbol{i}\in I$, we can find a $\phi_{\psi, \boldsymbol{i}}\in W$ such that $\psi_{\boldsymbol{i}}\in U_{\phi_{\psi, \boldsymbol{i}}}$. This gives us a map $\pi: \sR\rightarrow W^I$ sending $\psi$ to $(\phi_{\psi, \boldsymbol{i}})_{\boldsymbol{i}\in I}$.


Let $w=(w_{\boldsymbol{i}})_{\boldsymbol{i}\in I}\in W^I$. For each $\psi\in \pi^{-1}(w)$, we have $\psi_{\boldsymbol{i}}\in U_{w_{\boldsymbol{i}}}$ and hence
\begin{align} \label{E-func to indep5}
 E_{w_{\boldsymbol{i}}, \psi}\subseteq  Z\setminus Z_{\psi, \boldsymbol{i}}
 \end{align}
for every $\boldsymbol{i}\in I$.
For each $\boldsymbol{i}\in I$, we denote by $\cP_{\boldsymbol{i}}$ the partition of $Z$ consisting of $w_{\boldsymbol{i}}^{-1}(j)$ for $j\in [k]$. Let $\cP$ be the join $\bigvee_{\boldsymbol{i}\in I}\cP_{\boldsymbol{i}}$ of $\cP_{\boldsymbol{i}}$ for $\boldsymbol{i}\in I$, i.e., the partition of $Z$ consisting of sets of the form $\bigcap_{\boldsymbol{i}\in I}P_{\boldsymbol{i}}$ with $P_{\boldsymbol{i}}\in \cP_{\boldsymbol{i}}$ for every $\boldsymbol{i}\in I$. We shall show that
\begin{align} \label{E-func to indep}
\pi^{-1}(w)\subseteq V_{\cP, \varepsilon, \eta},
\end{align}
where $V_{\cP, \varepsilon, \eta}$ is defined in Lemma~\ref{L-indep to partition}.
For each $h\in [k]^I$, let
$$P_h=\bigcap_{\boldsymbol{i}\in I} w_{\boldsymbol{i}}^{-1}(h(\boldsymbol{i}))\subseteq Z.$$
Then $\cP=\{P_h: h\in [k]^I\}$.  We denote by $H_\eta$ the set of $h\in  [k]^I$ satisfying $\frac{|P_h|}{|Z|}\ge \eta$.

We claim that for any $\psi\in \pi^{-1}(w)$ and any $h\in [k]^I$, if $z_j\in \psi^{-1}(j)\cap P_h$ and $|f_\psi(z_j)|\le (\tau|Z|)^{-1/p}C$ for each $j\in [k]$, then
\begin{align} \label{E-func to indep2}
\frac{1}{k}\sum_{j\in [k]}f_\psi(z_j)<\left(r+\tau^{-1/p}\frac{C}{M}\right)|Z|^{-1/p}.
\end{align}
Assume that $\frac{1}{k}\sum_{j\in [k]}f_\psi(z_j)\ge \left(r+\tau^{-1/p}\frac{C}{M}\right)|Z|^{-1/p}$ instead. For each $j\in [k]$, since $|f_\psi(z_j)|\le (\tau|Z|)^{-1/p}C$, 
we can find an $i_j\in [2M]$ such that
\begin{align} \label{E-func to indep3}
|Z|^{1/p}f_\psi(z_j)\in \tau^{-1/p}\left[-C+\frac{(i_j-1)C}{M}, -C+\frac{i_jC}{M}\right].
\end{align}
This gives us an element $\boldsymbol{i}=(i_1, \dots, i_k)$ of $[2M]^k$. Then
$$\frac{1}{k}\sum_{j\in [k]}\tau^{-1/p}\left(-C+\frac{(i_j-1)C}{M}\right)\ge  \frac{1}{k}\sum_{j\in [k]}\left(|Z|^{1/p}f_\psi(z_j)-\tau^{-1/p}\frac{C}{M}\right)\ge r,$$
whence $\boldsymbol{i}\in I$. 
For each $z\in \psi^{-1}(h(\boldsymbol{i}))\cap P_h$, we have 
$$\psi(z)=h(\boldsymbol{i})=w_{\boldsymbol{i}}(z),$$ 
whence $z\in E_{w_{\boldsymbol{i}}, \psi}$. This means
$$\psi^{-1}(h(\boldsymbol{i}))\cap P_h\subseteq E_{w_{\boldsymbol{i}}, \psi}.$$
Thus 
\begin{align*}
z_{h(\boldsymbol{i})}\in \psi^{-1}(h(\boldsymbol{i}))\cap P_h\subseteq E_{w_{\boldsymbol{i}}, \psi}\overset{\eqref{E-func to indep5}}\subseteq Z\setminus Z_{\psi, \boldsymbol{i}},
\end{align*}
and hence $z_{h(\boldsymbol{i})}\not\in \psi^{-1}(h(\boldsymbol{i}))\cap f_\psi^{-1}\left((\tau|Z|)^{-1/p}\left[-C+\frac{(i_{h(\boldsymbol{i})}-1)C}{M}, C\right]\right)$. Since $z_{h(\boldsymbol{i})}\in \psi^{-1}(h(\boldsymbol{i}))$, it follows that
$z_{h(\boldsymbol{i})}\not\in f_\psi^{-1}\left((\tau|Z|)^{-1/p}\left[-C+\frac{(i_{h(\boldsymbol{i})}-1)C}{M}, C\right]\right)$, a contradiction to \eqref{E-func to indep3}. This proves our claim.

To prove \eqref{E-func to indep}, we argue by contradiction. Assume that 
\eqref{E-func to indep} fails.
Then we can find  a $\psi\in \pi^{-1}(w)\setminus V_{\cP, \varepsilon, \eta}$.
We denote by $Z_\psi$ the set of $z\in Z$ such that $|f_\psi(z)|>(\tau|Z|)^{-1/p} C$. When $p=\infty$, $Z_\psi$ is empty. When $p<\infty$, we have
$$ \left((\tau|Z|)^{-1} C^p |Z_\psi|\right)^{1/p} \le \|f_\psi\|_p\le C,$$
whence $|Z_\psi|\le \tau |Z|$. Thus we always have
$$|Z_\psi|\le \tau|Z|.$$
For each $h\in H_\eta$, since $\frac{|P_h|}{|Z|}\ge \eta$ and $\psi\not\in V_{\cP, \varepsilon, \eta}$, we have
 $$ \left|\frac{|\psi^{-1}(j)\cap P_h|}{|P_h|}-\frac{1}{k}\right|< \varepsilon$$
 for each $j\in [k]$, thus we can take a set $Y_h$ with $|Y_h|=\lceil|P_h|(\frac{1}{k}-\varepsilon)\rceil$ and an injective map $g_{h, j}: Y_h \rightarrow \psi^{-1}(j)\cap P_h$ for each $j\in [k]$. For each $h\in H_\eta$, we denote by $Y_h'$ the set of $y\in Y_h$ such that $g_{h, j}(y)\in Z\setminus Z_\psi$ for all $j\in [k]$. The sets $\{g_{h, j}(y): j\in [k]\}$ for $h\in H_\eta$ and $y\in Y_h\setminus Y_h'$ are pairwise disjoint, and each of them intersects with $Z_\psi$. Thus
 \begin{align*}
 \left|\bigcup_{h\in H_\eta}\bigcup_{j\in [k]}g_{h, j}(Y_h\setminus Y_h')\right|=\sum_{h\in H_\eta}\sum_{y\in Y_h\setminus Y_h'}|\{g_{h, j}(y): j\in [k]\}|\le k|Z_\psi|.
 \end{align*}
 Therefore
 \begin{align*}
 &\left|Z\setminus \bigcup_{h\in H_\eta}\bigcup_{j\in [k]}g_{h, j}(Y_h')\right|\\
 &\quad \quad =\left|\bigcup_{h\in [k]^I\setminus H_\eta}P_h\right|+\left|\bigcup_{h\in H_\eta}\left(P_h\setminus \bigcup_{j\in [k]}g_{h, j}(Y_h)\right)\right|+\left|\bigcup_{h\in H_\eta}\bigcup_{j\in [k]}g_{h, j}(Y_h\setminus Y_h')\right|\\
 &\quad \quad \le k^{|I|}\eta |Z|+\sum_{h\in H_\eta}k\varepsilon|P_h|+k|Z_\psi|\\
 &\quad \quad \le k^{|I|}\eta |Z|+k\varepsilon|Z|+k\tau |Z|,
 \end{align*}
 whence by H\"{o}lder's inequality 
 \begin{align*}
 \sum_{z\in Z\setminus \bigcup_{h\in H_\eta}\bigcup_{j\in [k]}g_{h, j}(Y_h')}f_\psi(z)&\le \|f_\psi\|_p\cdot \|{\bf 1}_{Z\setminus \bigcup_{h\in H_\eta}\bigcup_{j\in [k]}g_{h, j}(Y_h')}\|_q\\
 &\le C\left|Z\setminus \bigcup_{h\in H_\eta}\bigcup_{j\in [k]}g_{h, j}(Y_h')\right|^{1/q}\\
 &\le C(k^{|I|}\eta+k\varepsilon+k\tau)^{1/q}|Z|^{1/q}\\
 &\overset{\eqref{E-func to indep4}}\le \frac{R-r}{2}|Z|^{1/q}.
 \end{align*}
 For each $h\in H_\eta$ and $y\in Y'_h$, we have $g_{h, j}(y)\in \psi^{-1}(j)\cap P_h$ and $|f_\psi(g_{h, j}(y))|\le (\tau|Z|)^{-1/p}C$ for every $j\in [k]$, whence
 $$ \frac{1}{k}\sum_{j\in [k]}f_\psi(g_{h, j}(y))<\left(r+\tau^{-1/p}\frac{C}{M}\right)|Z|^{-1/p}$$
 by \eqref{E-func to indep2}. 
 For each $h\in H_\eta$, we have 
 $$|P_h|\varepsilon\ge |Z|\eta\varepsilon\ge N\eta \varepsilon \ge 1,$$  
 whence 
 $$|Y_h|=\lceil|P_h|(\frac{1}{k}-\varepsilon)\rceil< |P_h|(\frac{1}{k}-\varepsilon)+1\le |P_h|/k.$$
 Thus, for each $h\in H_\eta$, we have
 \begin{align*}
 \sum_{y\in Y'_h}\sum_{j\in [k]}f_\psi(g_{h, j}(y))&\le  |Y_h'| k\left(r+\tau^{-1/p}\frac{C}{M}\right)|Z|^{-1/p}\le  |Y_h| k\left(r+\tau^{-1/p}\frac{C}{M}\right)|Z|^{-1/p}\\
 &\le |P_h| \left(r+\tau^{-1/p}\frac{C}{M}\right)|Z|^{-1/p}. 
 \end{align*}
 Therefore
 \begin{align*}
 |Z|^{1/q}R &\le \sum_{z\in Z}f_\psi(z)=\sum_{h\in H_\eta}\sum_{y\in Y'_h}\sum_{j\in [k]}f_\psi(g_{h, j}(y))+\sum_{z\in Z\setminus \bigcup_{h\in H_\eta}\bigcup_{j\in [k]}g_{h, j}(Y_h')}f_\psi(z)\\
 &\le \sum_{h\in H_\eta}|P_h|\left(r+\tau^{-1/p}\frac{C}{M}\right)|Z|^{-1/p}+\frac{R-r}{2}|Z|^{1/q}\\
 &\le |Z|^{1/q}\left(r+\tau^{-1/p}\frac{C}{M}\right)+\frac{R-r}{2}|Z|^{1/q},
 \end{align*}
 a contradiction to \eqref{E-func to indep6}. This proves \eqref{E-func to indep}. 


Since $|Z|\ge N\ge N_1$, by our choice of $\delta_1$ and $N_1$
we have
$$|V_{\cP, \varepsilon, \eta}|\le \left|[k]^Z\right|e^{-\delta_1 |Z|}=\left|[k]^Z\right|e^{-3\delta |Z|}.$$
As $|Z|\ge N\ge N_2$, from \eqref{E-func to indep7} we also have
$$ |I|^{|I|}\le e^{\delta N_2}\le e^{\delta |Z|}.$$
We conclude that for each $w\in W^I$ one has 
$$ |\pi^{-1}(w)|\overset{\eqref{E-func to indep}}\le |V_{\cP, \varepsilon, \eta}|\le \left|[k]^Z\right|e^{-3\delta |Z|}\le |\sR|e^{-2\delta |Z|}\le |\sR|e^{-\delta |Z|}|I|^{-|I|}.$$
Thus
$$ |W|^{|I|}=|W^I|\ge e^{\delta |Z|}|I|^{|I|},$$
and hence
$$ |W|\ge e^{\frac{\delta}{|I|}|Z|}|I|.$$
Then
$$ \sum_{\boldsymbol{i}\in I}N_{S_{\boldsymbol{i}}}\ge N_S\ge e^{\frac{\delta}{|I|}|Z|}|I|,$$
thus we can find some $\boldsymbol{i}=(i_1, \dots, i_k)\in I$ so that
$$ N_{S_{\boldsymbol{i}}}\ge e^{\frac{\delta}{|I|}|Z|}=k^{\frac{\delta}{|I|\log k}|Z|}=k^{b|Z|}.$$
We set $t_j=\tau^{-1/p}\left(-C+\frac{(i_j-1)C}{M}\right)$ for each $j\in [k]$. Then $(t_1, \dots, t_k)\in T$.
By our choice of $c$ we can find some $J\subseteq Z$ so that $|J|\ge c|Z|$ and $S_{\boldsymbol{i}}|_J\supseteq [k]^J$.  Then for every map $\sigma: J\rightarrow [k]$,
there is some $\psi\in \sR$ so that $\psi_{\boldsymbol{i}}$ extends  $\sigma$.
In particular, $\psi$ extends $\sigma$ and $f_\psi(z)\ge t_j|Z|^{-1/p}$ for all $j\in [k]$ and $z\in \sigma^{-1}(j)$.
\end{proof}

The following well-known lemma says that the exponential growth rate of  $|\sR(Z, k)|$ is the same as that of $\left|[k]^Z\right|$, so that  $\sR(Z, k)$ satisfies the hypothesis in Lemma~\ref{L-func to indep pre} for $\sR$. For convenience of the reader, we give a proof. 


\begin{lemma} \label{L-regular}
Let $k\in \Nb$ and $\delta>0$. Then there is some $N>0$ depending only on $k$ and $\delta$ such that for any finite set $Z$ with $|Z|\ge N$ one has
$$|\sR(Z, k)|\ge \left|[k]^Z\right|e^{-\delta |Z|}.$$
\end{lemma}
\begin{proof}
We take a large $N\ge k$ such that  $e^{k-1}t^k\le e^{\delta t}$ for all $t\ge N$.  Let $Z$ be a finite set with $|Z|\ge N$.
We can find a set $Z'\subseteq Z$ such that $|Z'|$ is divisible by $k$ and $|Z\setminus Z'|<k$. Then
\begin{align*}
|\sR(Z, k)|&\ge |\sR(Z', k)|= \frac{|Z'|!}{\left(\left(\frac{|Z'|}{k}\right)!\right)^k}\overset{\eqref{E-Stirling}}\ge \frac{e\left(\frac{|Z'|}{e}\right)^{|Z'|}}{\left(e\frac{|Z'|}{k}\left(\frac{|Z'|}{ek}\right)^{\frac{|Z'|}{k}}\right)^k}= \frac{k^{|Z'|}}{e^{k-1}\left(\frac{|Z'|}{k}\right)^k}\\
&>\frac{k^{|Z|-k}}{e^{k-1}\left(\frac{|Z'|}{k}\right)^k}
=\frac{ k^{|Z|}}{e^{k-1}|Z'|^k}\ge  \frac{k^{|Z|}}{e^{k-1}|Z|^k}\ge |[k]^Z|e^{-\delta |Z|}. \tag*{\qedsymbol}
\end{align*}
     \renewcommand{\qedsymbol}{}
     \vspace{-\baselineskip}
\end{proof}


Now Lemma~\ref{L-func to indep} follows from Lemmas~\ref{L-func to indep pre} and ~\ref{L-regular}.



Via taking suitable $f_\psi$ in Lemma~\ref{L-func to indep}, one can obtain many consequences. As an example, we use it to obtain the following corollary, which in turn generalizes  Lemma~\ref{L-half to indep}.

\begin{corollary} \label{C-partial indep}
Let $k\in \Nb$, $m\in [k]$ and $\tau\in ((m-1)/k, 1]$. Then there exist $c, N>0$ depending only on $k, m$ and $\tau$ such that the following holds. For any finite set $Z$ with $|Z|\ge N$, if for each $\psi\in \sR(Z, k)$  we take a $Z_\psi\subseteq Z$  with $|Z_\psi|\ge \tau |Z|$, then there are some $J\subseteq Z$ with $|J|\ge c|Z|$ and $A\subseteq [k]$ with $|A|\ge m$ such that  every map $\sigma: J\rightarrow [k]$ extends to a $\psi\in \sR(Z, k)$ with $\sigma^{-1}(A)\subseteq Z_\psi$.
\end{corollary}
\begin{proof} Since $k\tau>m-1$, we can find a small $\theta>0$ such that
$$ \frac{k}{\frac{1}{\tau}+\theta}>m-1.$$
Then
$$ \frac{1}{\tau}-1+\theta\ge \theta\ge \theta \tau.$$
We set $C=\max(1, \frac{1}{\tau}-1+\theta)$, $R=\theta \tau$, $r=R/2$, and $p=\infty$. Then $q=1$ and we have $c, N>0$ and $T\subseteq \Rb^k$ given by Lemma~\ref{L-func to indep}.

Let $Z$ be  a finite set with $|Z|\ge N$, and let   $Z_\psi\subseteq Z$  with $|Z_\psi|\ge \tau |Z|$ for each $\psi\in \sR(Z, k)$.
For each $\psi\in \sR(Z, k)$, we define a function $f_\psi: Z\rightarrow [-C, C]$ by
\begin{align*}
f_{\psi}(z)=\begin{cases}
\frac{1}{\tau}-1+\theta & \quad \text{if } z\in Z_\psi\\
-1 & \quad \text{otherwise }.\\
\end{cases}
\end{align*}
Then
\begin{align*}
\frac{1}{|Z|}\sum_{z\in Z}f_\psi(z)=\frac{|Z_\psi|(\frac{1}{\tau}-1+\theta)-|Z\setminus Z_\psi|}{|Z|}= \frac{|Z_\psi|(\frac{1}{\tau}+\theta)}{|Z|}-1\ge R.
\end{align*}
By our choice of $c, N$ and $T$, we can find a $J\subseteq Z$ with $|J|\ge c|Z|$ and a $(t_1, \dots, t_k)\in T$ such that every map $\sigma: J\rightarrow [k]$ extends to some $\psi\in \sR(Z, k)$ so that $f_\psi(z)\ge t_j$ for all $j\in [k]$ and $z\in \sigma^{-1}(j)$. For each $j\in [k]$, taking a map $\sigma: J\rightarrow [k]$ with $j\in \sigma(J)$, we have
$$ t_j\le f_\psi(z)\le \frac{1}{\tau}-1+\theta$$
for all $z\in \sigma^{-1}(j)$.
We denote by $A$ the set of $j\in [k]$ satisfying $t_j>-1$.
Then by our choice of $T$ we have
\begin{align*}
0<r\le \frac{1}{k}\sum_{j\in [k]}t_j\le \frac{1}{k}\left(|A|(\frac{1}{\tau}-1+\theta)-\left|[k]\setminus A\right|\right)=\frac{1}{k}|A|(\frac{1}{\tau}+\theta)-1.
\end{align*}
Therefore
$$ |A|>\frac{k}{\frac{1}{\tau}+\theta}>m-1,$$
whence $|A|\ge m$.
Given any $\sigma$ and $\psi$ as above, for each $j\in A$, since $f_\psi(z)\ge t_j>-1$ for all $z\in \sigma^{-1}(j)$,
we have $\sigma^{-1}(j)\subseteq Z_\psi$.
\end{proof}



