\subsection{General case of Theorem~\ref{T-IE main}} \label{SS-general}

In this subsection we  prove the general case of Theorem~\ref{T-IE main}.

\begin{lemma} \label{L-func to func}
Let $k\in \Nb$, $\omu=(\mu_1, \dots, \mu_k)\in \cM(X)^k$ and $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$. Let $R=\frac{1}{k}\sum_{j\in [k]}\mu_j(f_j)$ and let $r<R$. Then there is some product neighborhood $U_1\times \cdots \times U_k$ of $\omu$ in $\cM(X)^k$ such that the following holds. For any independence set $F\in \cF(\Gamma)$ of $(U_1, \dots, U_k)$ and any surjective map $\psi: F\rightarrow [k]$,  there is
some $x\in X$ such that
\begin{align} \label{E-func to func}
\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\ge r.
\end{align}
\end{lemma}
\begin{proof} For each $j\in [k]$, we denote by $U_j$ the set of $\nu\in \cM(X)$ satisfying
$$\nu(f_j)\ge \mu_j(f_j)-(R-r).$$
This is a neighborhood of $\mu_j$ in $\cM(X)$.


Let $F\in \cF(\Gamma)$ be an independence set for $(U_1, \dots, U_k)$ and let  $\psi: F\rightarrow [k]$ be surjective.
Then $\bigcap_{s\in F}s^{-1}U_{\psi(s)}$ is nonempty, whence we can find  a $\nu\in \bigcap_{s\in F}s^{-1}U_{\psi(s)}$. We have
\begin{align*}
\int_X\left(\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\right)\, d\nu(x)&=\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(s\nu)(f_j)\\
&\ge \frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(\mu_j(f_j)-(R-r))\\
&=\frac{1}{k}\sum_{j\in [k]}(\mu_j(f_j)-(R-r))=r.
\end{align*}
Thus we can find some $x\in X$ such that \eqref{E-func to func} holds.
\end{proof}

\begin{notation} \label{N-tuple}
Let $k\in \Nb$, $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$ and $\ot=(t_1, \dots, t_k)\in \Rb^k$. 
We denote by $\oA_{\of, \ot}$ the $k$-tuple
$$\left(f_1^{-1}\left([t_1, \infty)\right), \dots, f_k^{-1}\left([t_k, \infty)\right)\right)$$
of closed subsets of $X$.
\end{notation}



\begin{lemma} \label{L-func to density}
Let $k\in \Nb$, $\omu=(\mu_1, \dots, \mu_k)\in \cM(X)^k$ and $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$ such that $R:=\frac{1}{k}\sum_{j\in [k]}\mu_j(f_j)>0$.  Let $0<r<R$ and $C\ge \|\of\|$. Then there are some $c, N>0$ and some finite set $T\subseteq \Rb^k$ depending only on $k, r, R$ and $C$,  and some product neighborhood $U_1\times \cdots \times U_k$ of $\omu$ in $\cM(X)^k$ such that the following hold:
\begin{enumerate}
\item $\frac{1}{k}\sum_{j\in [k]}t_j\ge r$ for every $(t_1, \dots, t_k)\in T$, and
\item for any independence set $F\in \cF(\Gamma)$ of $(U_1, \dots, U_k)$ with $|F|\ge N$, there are some $J\subseteq F$ with $|J|\ge c|F|$ and some $\ot\in T$ so that $J$ is an independence set for $\oA_{\of, \ot}$.
    \end{enumerate}
\end{lemma}
\begin{proof} Let $c,N>0$ and $T\subseteq \Rb^k$ be given by Lemma~\ref{L-func to indep} for $k, r, \frac{R+r}{2}, C$ and $p=\infty$.
Then $\frac{1}{k}\sum_{j\in [k]}t_j\ge r$ for every $(t_1, \dots, t_k)\in T$.
By Lemma~\ref{L-func to func} we can find a product neighborhood $U_1\times \cdots \times U_k$ of $\omu$ in $\cM(X)^k$ such that the following holds. For any independence set $F'\in \cF(\Gamma)$ of $\oU=(U_1, \dots, U_k)$ and any surjective map $\psi: F'\rightarrow [k]$,  there is
some $x\in X$ such that
\begin{align*} 
\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\ge \frac{R+r}{2}.
\end{align*}

Let $F\in \cF(\Gamma)$ be an independence set of $\oU$ with $|F|\ge (k-1)+\max(N, k-1)$. We can find a set $F'\subseteq F$ such that $|F'|$ is divisible by $k$ and $|F\setminus F'|\le k-1$. Then $F'$ is also an independence set of $\oU$, $|F'|\ge N$ and $|F'|\ge |F|/2$. Let $\psi\in \sR(F', k)$. Then $\psi$ is surjective, whence we can find  an $x_\psi\in X$ such that
\begin{align}\label{E-func to density}
 \frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx_\psi)\ge \frac{R+r}{2}.
 \end{align}
We define a function $f_\psi: F'\rightarrow [-C, C]$ by
$$ f_\psi(s)=f_{\psi(s)}(sx_\psi)$$
for all $s\in F'$. Since $\psi\in \sR(F', k)$ and $|F'|$ is divisible by $k$, we have
$$|\psi^{-1}(j)|=\frac{1}{k}|F'|$$
for each $j\in [k]$.
Thus
 \begin{align*}
 \frac{1}{|F'|}\sum_{s\in F'}f_\psi(s)=\frac{1}{|F'|}\sum_{s\in F'}f_{\psi(s)}(sx_\psi)=\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx_\psi)\overset{\eqref{E-func to density}}\ge \frac{R+r}{2}.
 \end{align*}
By our choice of $c, N$ and $T$ we can find some $J\subseteq F'$ with $|J|\ge c|F'|\ge \frac{c}{2}|F|$ and some $\ot=(t_1, \dots, t_k)\in T$  such that every map $\sigma: J\rightarrow [k]$ extends to a $\psi\in \sR(F', k)$ so that $f_\psi(s)\ge t_j$ for all $j\in [k]$ and $s\in \sigma^{-1}(j)$. 
Then
$$ f_{\sigma(s)}(sx_\psi)=f_{\psi(s)}(sx_\psi)=f_\psi(s)\ge t_{\sigma(s)}$$
for every $s\in J$, whence
$$ x_\psi\in \bigcap_{s\in J}s^{-1} f_{\sigma(s)}^{-1}([t_{\sigma(s)}, \infty)).$$
Thus $J$ is an independence set for $\oA_{\of, \ot}$.
\end{proof}

We are ready to prove Theorem~\ref{T-IE main}.


\begin{proof}[Proof of Theorem~\ref{T-IE main}]
In view of Lemma~\ref{L-Hahn Banach IE}, it suffices to show that given any $\omu=(\mu_1, \dots, \mu_k)\in \IE_k(\cM(X))$ and $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$ satisfying $\sum_{j\in [k]}\mu_j(f_j)>0$, there is an $(x_1, \dots, x_k)\in \IE_k(X)$ such that $\sum_{j\in [k]}f_j(x_j)>0$.


Let $C=\|\of\|>0$, $R=\frac{1}{k}\sum_{j\in [k]} \mu_j(f_j)>0$ and $r=R/2$. Then we have $c,N>0$, $T\subseteq \Rb^k$ and $U_1\times \cdots \times U_k$ given by Lemma~\ref{L-func to density}. Since $\omu\in \IE_k(\cM(X))$, the tuple $\oU=(U_1, \dots, U_k)$ has positive independence density $\oI(\oU)$ (see Section~\ref{SS-IE}).

We claim that $\oI(\oA_{\of, \ot})\ge c\oI(\oU)$ for some $\ot\in T$. Assume that
$\oI(\oA_{\of, \ot})< c\oI(\oU)$ for every $\ot\in T$ instead.  Then for each $\ot\in T$ we can find some $K_\ot\in \cF(\Gamma)$ and some $\varepsilon_\ot>0$ such that
\begin{align} \label{E-hull for IE}
\varphi_{\oA_{\of, \ot}}(F)< c\oI(\oU)|F|
\end{align}
for every $F\in \cF(\Gamma)$ satisfying $|K_\ot F\Delta F|<\varepsilon_\ot |F|$. We can find an $F\in \cF(\Gamma)$ such that $|F|\ge N/\oI(\oU)$ and $|K_\ot F\Delta F|<\varepsilon_\ot |F|$ for all $\ot\in T$. Then \eqref{E-hull for IE}  holds for every $\ot\in T$. From the definition of $\varphi_{\oU}(F)$ we can find a set $F'\subseteq F$ such that $F'$ is an independence set for $\oU$ and $|F'|\ge \varphi_{\oU}(F)$. Then
$$ |F'|\ge \varphi_{\oU}(F)\ge \oI(\oU)|F|\ge N.$$
By our choice of $c, N, T$ and $U_1\times \cdots \times U_k$, there are some $J\subseteq F'$ with $|J|\ge c|F'|$ and some $\ot\in T$ such that $J$ is an independence set for $\oA_{\of, \ot}$. Then
$$ \varphi_{\oA_{\of, \ot}}(F)\ge |J|\ge c|F'|\ge c\oI(\oU)|F|,$$
a contradiction. This proves our claim.


Let $\ot=(t_1, \dots, t_k)\in T$ such that $\oI(\oA_{\of, \ot})\ge c\oI(\oU)>0$.
By Theorem~\ref{T-IE basic}.\eqref{i-IE tuple} there is some $(x_1, \dots, x_k)\in \IE_k(X)$ such that $x_j\in f_j^{-1}([t_j, \infty])$ for all $j\in [k]$. Then
$$ \sum_{j\in [k]}f_j(x_j)\ge \sum_{j\in [k]}t_j\ge kr>0$$
as desired.
\end{proof}





