\subsection{Consequences of Theorem~\ref{T-IE main}} \label{SS-IE consequence}


As mentioned in Section~\ref{S-introduction}, 
in view of Theorem~\ref{T-IE basic}.\eqref{i-IE pair}, from the case $k=2$ of Theorem~\ref{T-IE main} we immediately obtain the following result of Glasner and Weiss \cite[Theorem A]{GW95}.

\begin{corollary} \label{C-IE for prob}
If $h_{\rm top}(X)=0$, then $h_{\rm top}(\cM(X))=0$.
\end{corollary}




\begin{lemma} \label{L-finite support}
Let $k\in \Nb$. If $\omu=(\mu_1, \dots, \mu_k)\in \IE_k(\cM(X))$ and $\supp(\mu_j)$ is finite for every $j\in [k]$, then $\omu$ is a convex combination of elements in $(\supp(\mu_1)\times \cdots \times \supp(\mu_k))\cap \IE_k(X)$.
\end{lemma}
\begin{proof} By Theorem~\ref{T-IE main}.(3) there exists a $\mu\in \cM(\IE_k(X))$ such that 
$\mu_j=\mu^{(j)}$ 
for all $j\in [k]$. Then $\mu(\supp(\mu_1)\times \cdots \times \supp(\mu_k))=1$. Thus $\supp(\mu)$ is finite and
$$\supp(\mu)\subseteq (\supp(\mu_1)\times \cdots \times \supp(\mu_k))\cap \IE_k(X).$$
Then $\omu$ is a convex combination of elements in $\supp(\mu)$, whence a convex combination of elements in $(\supp(\mu_1)\times \cdots \times \supp(\mu_k))\cap \IE_k(X)$.
\end{proof}


\begin{lemma} \label{L-support to support}
Let $k\in \Nb$ and let $\mu\in \cM(\IE_k(X))$ with finite support. Then
$$\sum_{\onu\in \supp(\mu)}\mu(\{\onu\})\onu\in \IE_k(\cM_{|\supp(\mu)|}(X)).$$
\end{lemma}
\begin{proof} The case $|\supp(\mu)|=1$ is trivial. The general case follows by induction on $|\supp(\mu)|$ using Lemma~\ref{L-IE convex}.(1).
\end{proof}

Now Corollary~\ref{C-IE finite support} follows from Lemmas~\ref{L-finite support} and \ref{L-support to support}. 


We remark that even when $N_1, \dots, N_k$ are all equal, one cannot strengthen  Corollary~\ref{C-IE finite support} to claim
$$ \cM_N(X)^k\cap \IE_k(\cM(X))\subseteq \IE_k(\cM_N(X)).$$
To illustrate this, we give an example in Example~\ref{E-not IE}. For this we need the following lemma.

\begin{lemma} \label{L-not IE}
Let $x_1, x_2, y_1, y_2\in X$ such that $(x_1, x_2), (y_1, x_2), (x_1, y_2)\in \IE_2(X)$ but $(y_1, y_2)\not\in \IE_2(X)$. Let $1/2<\lambda<1$, and set
$$\omu=\lambda(\delta_{x_1}, \delta_{x_2})+(1-\lambda)(\delta_{y_1}, \delta_{y_2})\in \cM_2(X)^2.$$
Then
$\omu\in \IE_2(\cM_3(X))$ but $\omu\not\in \IE_2(\cM_2(X))$.
\end{lemma}
\begin{proof} Note that $\omu$ is a convex combination of $(\delta_{x_1}, \delta_{x_2})$, $(\delta_{y_1}, \delta_{x_2})$ and $(\delta_{x_1}, \delta_{y_2})$:
$$ \omu=(2\lambda-1)(\delta_{x_1}, \delta_{x_2})+(1-\lambda)(\delta_{y_1}, \delta_{x_2})+(1-\lambda)(\delta_{x_1}, \delta_{y_2}).$$
Thus by Lemma~\ref{L-support to support} we have $\omu\in \IE_2(\cM_3(X))$.


Since $(y_1, x_2)\in \IE_2(X)$ and $(y_1, y_2)\not\in \IE_2(X)$, we have $x_2\neq y_2$. Similarly, $x_1\neq y_1$.  Let $V_1$ and $W_1$ be open neighborhoods of $x_1$ and $y_1$ in $X$ respectively such that $V_1\cap W_1=\emptyset$. Also let $V_2$ and $W_2$ be open neighborhoods of $x_2$ and $y_2$ in $X$ respectively such that $V_2\cap W_2=\emptyset$. Let $0<\varepsilon<\min(\lambda-1/2, 1-\lambda)$. Then
$$U_1=\{\mu\in \cM(X): \mu(V_1)>\lambda-\varepsilon, \mu(W_1)>1-\lambda-\varepsilon\}$$
and
$$U_2=\{\mu\in \cM(X): \mu(V_2)>\lambda-\varepsilon, \mu(W_2)>1-\lambda-\varepsilon\}$$
are open neighborhoods of $\lambda\delta_{x_1}+(1-\lambda)\delta_{y_1}$ and $\lambda\delta_{x_2}+(1-\lambda)\delta_{y_2}$ in $\cM(X)$ respectively.

Let $F\in \cF(\Gamma)$ be an independence set of the pair $(U_1\cap \cM_2(X), U_2\cap \cM_2(X))$. For each map $\sigma: F\rightarrow \{1, 2\}$, we can find a $\nu_\sigma\in \cM_2(X)\cap \bigcap_{s\in F}s^{-1}U_{\sigma(s)}$. Say, $\nu_\sigma=t_\sigma \delta_{z_\sigma}+(1-t_\sigma)\delta_{w_\sigma}$ for some $z_\sigma, w_\sigma\in X$ and $t_\sigma\in [1/2, 1]$. For each $s\in F$, we have
$$t_\sigma \delta_{sz_\sigma}+(1-t_\sigma)\delta_{sw_\sigma}=s\nu_\sigma\in U_{\sigma(s)}.$$
Note that $\lambda-\varepsilon>1/2$ and $1-\lambda-\varepsilon>0$. 
If $\sigma(s)=1$, then $sz_\sigma\in V_1$ and $sw_\sigma\in W_1$. If $\sigma(s)=2$, then $sz_\sigma\in V_2$ and $sw_\sigma\in W_2$. Thus $w_\sigma\in \bigcap_{s\in F}s^{-1}W_{\sigma(s)}$.  This shows that $F$ is an independence set of the pair $(W_1, W_2)$.
Thus the independence density of the pair $(W_1, W_2)$ is no less than that of the pair $(U_1\cap \cM_2(X), U_2\cap \cM_2(X))$.

Since $(y_1, y_2)\not\in \IE_2(X)$, if we take $W_1$ and $W_2$ small enough, then the pair $(W_1, W_2)$ has zero independence density, and hence the pair $(U_1\cap \cM_2(X), U_2\cap \cM_2(X))$ has zero independence density. Therefore $\omu\not\in \IE_2(\cM_2(X))$.
\end{proof}

\begin{example} \label{E-not IE}
We consider the right shift action of $\Gamma$ on $\{0, 1,2 \}^\Gamma$:
$$ (sx)_\gamma=x_{\gamma s}$$
for all $x\in \{0, 1, 2\}^\Gamma$ and $s, \gamma\in \Gamma$. 
Let 
$$X=\{0, 1\}^\Gamma\cup \{1, 2\}^\Gamma\subseteq \{0, 1, 2\}^\Gamma.$$ 
Then $X$ is a closed $\Gamma$-invariant subset of $\{0, 1, 2\}^\Gamma$, thus we may consider the restriction of  the shift action to $X$. It is easily checked that
$$\IE_2(X)=(\{0, 1\}^\Gamma\times \{0, 1\}^\Gamma)\cup (\{1, 2\}^\Gamma\times \{1, 2\}^\Gamma).$$
Let $z$ be the constant function $\Gamma\rightarrow \{1\}$ in $X$.
We take $x_2=z$ and any $x_1\in \{1, 2\}^\Gamma$,  $y_1\in \{0, 1\}^\Gamma\setminus \{z\}$, and $y_2\in \{1, 2\}^\Gamma\setminus \{z\}$. Then $x_1, x_2, y_1, y_2$ satisfy the conditions in Lemma~\ref{L-not IE}. Therefore, for any $1/2<\lambda<1$, we have
$$ \lambda(\delta_{x_1}, \delta_{x_2})+(1-\lambda)(\delta_{y_1}, \delta_{y_2})\in \left(\cM_2(X)^2\cap \IE_2(\cM_3(X))\right)\setminus\IE_2(\cM_2(X)).$$
\end{example}

One may decompose the space $\cM_N(X)$ according to the weights at the points, as in the following notation. 


\begin{notation} \label{N-finite support2}
Let $N\in \Nb$. We denote by $\orP_N$ the set of probability vectors of length $N$, i.e., 
$$ \orP_N=\{\olambda=(\lambda_1, \dots, \lambda_N)\in [0, 1]^N: \sum_{i\in [N]}\lambda_i=1\}.$$
For each $\olambda=(\lambda_1, \dots, \lambda_N)\in \orP_N$, we denote by $\cM_\olambda(X)$ the set of $\mu$ in $\cM(X)$ of the form $\sum_{i\in [N]}\lambda_i \delta_{x_i}$ for $(x_1, \dots, x_N)\in X^N$. This is a $\Gamma$-invariant closed subset of $\cM_N(X)$. We denote by $\pi_\olambda$ the factor map $X^N\rightarrow \cM_\olambda(X)$ sending $(x_1, \dots, x_N)$ to $\sum_{i\in [N]}\lambda_i \delta_{x_i}$.
\end{notation}



For $k\in \Nb$, we say $\Gamma\curvearrowright X$ has {\it  Uniform Positive Entropy (UPE) of order $k$} if $\IE_k(X)=X^k$. The notion of UPE of order $2$ was introduced by Blanchard in \cite[Definition 1]{Blanchard92} in terms of positivity for topological entropy of standard open covers, as an analogue of the K-property for topological dynamical systems. It was extended to the notion of UPE of order $k$ for $k\ge 2$ by Glasner and Weiss in \cite[page 306]{GW952} in terms of entropy tuples of length $k$. When $k\ge 2$, the definition we use here is equivalent to theirs, as one can see from the coincidence of entropy tuples  and non-diagonal IE-tuples \cite[Theorem 12.20]{KL16}. 

\begin{corollary} \label{C-UPE}
Let $k, N\in \Nb$ and $\olambda\in \orP_N$.
The following are equivalent:
\begin{enumerate}
\item $\Gamma\curvearrowright X$ has UPE of order $k$.
\item $\Gamma\curvearrowright \cM_\olambda(X)$ has UPE of order $k$.
\item $\Gamma\curvearrowright \cM(X)$ has UPE of order $k$.
\end{enumerate}
\end{corollary}
\begin{proof} (1)$\Longrightarrow$(3) follows from Theorem~\ref{T-IE main}.(1).

(1)$\Longrightarrow$(2). Assume that (1) holds. From Theorem~\ref{T-IE basic}.\eqref{i-IE product} we know that $\Gamma\curvearrowright X^N$ has UPE of order $k$. Since $\Gamma \curvearrowright \cM_\olambda(X)$ is a factor of $\Gamma\curvearrowright X^N$, from Theorem~\ref{T-IE basic}.\eqref{i-IE factor} we conclude that $\Gamma\curvearrowright \cM_\olambda(X)$ has UPE of order $k$.

Both (2)$\Longrightarrow$(1) and (3)$\Longrightarrow(1)$ follow from Theorem~\ref{T-IE main}.(2).
\end{proof}

The case $k=2$ and $\olambda=(\underbrace{1/N, \dots, 1/N}_{N})$ of Corollary~\ref{C-UPE} was established by Bernardes, Darji and Vermersch in \cite[Theorem 4]{BDV22} for $\Gamma=\Zb$ and by Liu and Wei in \cite[Theorem 1.1]{LW} for all amenable groups $\Gamma$.

