\section{Measure $\IE$-tuples of $\cM(X)$} \label{S-measure IE for prob}


In this section we study measure IE-tuples and prove Theorem~\ref{T-measure IE main}. Throughout this section, we consider a continuous action of a countably infinite amenable group $\Gamma$ on a compact metrizable space $X$. 



The following fact is well known. For convenience of the reader, we give a proof.

\begin{lemma} \label{L-barycenter}
Let $\rmm\in \cM(\cM(X))$ and let $\mu\in \cM(X)$ be the barycenter of $\rmm$. For each Borel subset $D$ of $X$, the function on $\cM(X)$ sending $\nu$ to $\nu(D)$ is Borel, and
\begin{align} \label{E-barycenter}
 \mu(D)=\int_{\cM(X)}\nu(D)\, d\rmm(\nu).
 \end{align}
\end{lemma}
\begin{proof} Consider first the case $D$ is open. We can find an increasing sequence $\{f_n\}_{n\in \Nb}$ in $C(X)$ such that $0\le f_n\le 1$ for every $n\in \Nb$ and $f_n\rightarrow {\bf 1}_D$ pointwisely as $n\to \infty$. Then
$$\nu(D)=\lim_{n\to \infty}\nu(f_n)$$
for every $\nu\in \cM(X)$. Thus the function on $\cM(X)$ sending $\nu$ to $\nu(D)$ is the pointwise limit of a sequence of continuous functions, and hence is Borel. Furthermore, by the bounded convergence theorem we have
$$ \mu(D)=\lim_{n\to \infty}\mu(f_n)=\lim_{n\to \infty}\int_{\cM(X)}\nu(f_n)\, d\rmm(\nu)=\int_{\cM(X)}\nu(D)\, d\rmm(\nu), $$
establishing \eqref{E-barycenter} for $D$.

We denote by $\sB$ the collection of all Borel subsets $D$ of $X$ such that the function on $\cM(X)$ sending $\nu$ to $\nu(D)$ is Borel and that \eqref{E-barycenter} holds for $D$. Then $\sB$ contains the collection of all open subsets of $X$, and is closed under taking complements and countable disjoint unions. For any collection $\sU$ of subsets of $X$ closed under taking finite intersections, the $\sigma$-algebra generated by $\sU$ is the smallest collection of subsets of $X$ which contains $\sU$ and is closed under taking complements and countable disjoint unions \cite[Theorem 10.1.(iii)]{Kechris}. Thus $\sB$ is the Borel $\sigma$-algebra of $X$.
\end{proof}

The following is an analogue of Lemma~\ref{L-func to func}. 

\begin{lemma} \label{L-measure func to func}
Let $\rmm\in \cM_\Gamma(\cM(X))$ and let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$. Let $k\in \Nb$, $\onu=(\nu_1, \dots, \nu_k)\in \cM(X)^k$ and $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$.  Let $R=\frac{1}{k}\sum_{j\in [k]}\nu_j(f_j)$ and let $r<R$.
Then there are some $0<\delta<1$ and some product neighborhood $U_1\times \cdots \times U_k$ of $\onu$ in $\cM(X)^k$ such that the following holds. For any $0<\eta\le 1$ and any $D\in \sB(\mu, \eta \delta)$ (see Section~\ref{SS-measure IE}) there is some $D'\in \sB(\rmm, \eta)$ so that for any independence set $F\in \cF(\Gamma)$ of $(U_1, \dots, U_k)$ relative to $D'$ and any surjective map $\psi: F\rightarrow [k]$,  there is
some $x\in D$ such that
\begin{align} \label{E-measure func to func}
\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\ge r.
\end{align}
\end{lemma}
\begin{proof} Let $C>0$ with $C\ge \|\of\|$. Then $R\le C$. We take $0<\theta, \delta<1$ small such that
$$\frac{R-\theta-C\delta}{1-\delta}\ge r. $$
For each $j\in [k]$, we denote by $U_j$ the set of $\omega\in \cM(X)$ satisfying $\omega(f_j)\ge \nu_j(f_j)-\theta$. This is a neighborhood of $\nu_j$ in $\cM(X)$. We shall show that $\delta$ and $U_1\times \cdots \times U_k$ have the desired property. 

Let $0<\eta\le 1$
and $D\in \sB(\mu, \eta \delta)$. We denote by $D'$ the set of $\omega\in \cM(X)$ satisfying $\omega(D)\ge 1-\delta$. From Lemma~\ref{L-barycenter} we know that $D'$ is Borel and
\begin{align*}
\eta \delta &\ge \mu(X\setminus D)=\int_{\cM(X)}\omega(X\setminus D)\, d\rmm(\omega)\ge \int_{\cM(X)\setminus D'}\omega(X\setminus D)\, d\rmm(\omega)\\
&\ge \delta\cdot \rmm(\cM(X)\setminus D')=\delta(1-\rmm(D')),
\end{align*}
whence
$$\rmm(D')\ge 1-\eta.$$
That is, $D'\in \sB(\rmm, \eta)$.

Let $F\in \cF(\Gamma)$ be an independence set for $(U_1, \dots, U_k)$ relative to $D'$ and let $\psi: F\rightarrow [k]$ be surjective. Then $D'\cap \bigcap_{s\in F}s^{-1}U_{\psi(s)}$ is nonempty, whence we can find some $\omega\in D'\cap \bigcap_{s\in F}s^{-1}U_{\psi(s)}$.
We have
\begin{align*}
\int_X \left(\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\right)\, d\omega(x)&=\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(s\omega)(f_j)\\
&\ge \frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(\nu_j(f_j)-\theta)\\
&=\frac{1}{k}\sum_{j\in [k]}(\nu_j(f_j)-\theta)=R-\theta,
\end{align*}
and hence
\begin{align*}
\frac{1}{\omega(D)}&\int_D \left(\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\right)\, d\omega(x)\\
&\ge \frac{1}{\omega(D)}\left(\int_X \left(\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\right)\, d\omega(x)-C\omega(X\setminus D)\right)\\
&\ge \frac{R-\theta-C(1-\omega(D))}{\omega(D)}= \frac{R-\theta-C}{\omega(D)}+C\\
&\ge  \frac{R-\theta-C}{1-\delta}+C=\frac{R-\theta-C\delta}{1-\delta}\ge r,
\end{align*}
where in the 3rd inequality we use that $R-\theta-C<0$ and $\omega(D)\ge 1-\delta$.
Thus we can find some $x\in D$ such that \eqref{E-measure func to func} holds.
\end{proof}

The following lemma is an analogue of Lemma~\ref{L-Hahn Banach IE}, and can be proved in the same way.

\begin{lemma} \label{L-Hahn Banach measure IE}
Let $\rmm\in \cM_\Gamma(\cM(X))$ and let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$.
If $ \IE^\rmm_k(\cM(X))\nsubseteq \overline{\rm co}(\IE^\mu_k(X))$ for some $k\in \Nb$, then there are some $(\nu_1, \dots, \nu_k)\in \IE^\rmm_k(\cM(X))$ and some $(f_1, \dots, f_k)\in C(X)^{\oplus k}$ such that $\sum_{j\in [k]}f_j(x_j)\le 0$
for all $(x_1, \dots, x_k)\in \IE^\mu_k(X)$ and
$\sum_{j\in [k]}\nu_j(f_j)>0$.
\end{lemma}

We are ready to prove Theorem~\ref{T-measure IE main}. 

\begin{proof}[Proof of Theorem~\ref{T-measure IE main}]
(1). In view of Lemma~\ref{L-Hahn Banach measure IE}, it suffices to show that given any $\onu=(\nu_1, \dots, \nu_k)\in \IE^\rmm_k(\cM(X))$ and  $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$ satisfying $\sum_{j\in [k]}\nu_j(f_j)>0$, there is an $(x_1, \dots, x_k)\in \IE^\mu_k(X)$ such that $\sum_{j\in [k]}f_j(x_j)>0$.


Let $C>0$ with $C\ge \|\of\|$. Let $R=\frac{1}{k}\sum_{j\in [k]} \nu_j(f_j)>0$ and $r=R/4$. Then we have $c, N>0$ and $T\subseteq \Rb^k$ given by Lemma~\ref{L-func to indep} for $k, r, \frac{R}{2}, C$ and $p=\infty$.
By Lemma~\ref{L-measure func to func} we can find a
$0<\delta<1$ and a product neighborhood $U_1\times \cdots \times U_k$ of $\onu$ in $\cM(X)^k$ such that the following holds. For any $0<\eta\le 1$ and any $D\in \sB(\mu, \eta \delta)$ there is some $D'\in \sB(\rmm, \eta)$ so that for any  independence set $F\in \cF(\Gamma)$ of $\oU=(U_1, \dots, U_k)$ relative to $D'$ and any surjective map $\psi: F\rightarrow [k]$,  there is
some $x\in D$ such that
$$\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\ge \frac{R}{2}.$$

Since $\onu\in \IE^\rmm_k(\cM(X))$, we have $\upind_\rmm(\oU)>0$. Then we can find a $0<\eta\le 1$ such that $\upind_\rmm(\oU, \eta)>0$.

We claim that
\begin{align} \label{E-measure IE for prob}
 \max_{\ot\in T}\upind_\mu(\oA_{\of, \ot})\ge \frac{c}{3}\upind_\rmm(\oU, \eta),
 \end{align}
where $\oA_{\of, \ot}$ is given in Notation~\ref{N-tuple}.
Let $\varepsilon>0$ and $K\in \cF(\Gamma)$. We can find an $F'\in \cF(\Gamma)$ with $|KF'\Delta F'|<\varepsilon |F'|$ and $\frac{1}{|F'|}\varphi_{\oU, \rmm, \eta}(F')>\frac{1}{2}\upind_\rmm(\oU, \eta)$.
Let $D\in \sB(\mu, \eta \delta)$. By our choice of $\delta$ and $U_1\times \cdots \times U_k$, we can find some $D'\in \sB(\rmm, \eta)$ so that
for any independence set $F\in \cF(\Gamma)$ of $\oU$ relative to $D'$ and any surjective map $\psi: F\rightarrow [k]$,  there is
some $x\in D$ such that
$$\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\ge \frac{R}{2}.$$
When $\varepsilon$ is small enough and $|K|$ is large enough, we have $\frac{1}{6}\upind_\rmm(\oU, \eta)|F'|\ge \max(k-1, N/2)$, whence we can find an independence set $F\subseteq F'$ for $\oU$ relative to $D'$ such that $|F|$ is divisible by $k$ and
$$|F|\ge \varphi_{\oU, \rmm, \eta}(F')-(k-1)>\frac{1}{2}\upind_\rmm(\oU, \eta)|F'|-(k-1)\ge \frac{1}{3}\upind_\rmm(\oU, \eta)|F'|\ge N.$$
For each $\psi\in \sR(F, k)$, since $|F|$ is divisible by $k$, we have $|\psi^{-1}(j)|=|F|/k$ for every $j\in [k]$.  In particular, $\psi$ is surjective. Thus we can find an $x_\psi\in D$ such that 
$$\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx_\psi)\ge \frac{R}{2}.$$
We define a function $f_\psi: F\rightarrow [-C, C]$ by
$$ f_\psi(s)=f_{\psi(s)}(sx_\psi).$$
Then
$$ \frac{1}{|F|}\sum_{s\in F}f_\psi(s)=\frac{1}{|F|}\sum_{s\in F}f_{\psi(s)}(sx_\psi)=\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx_\psi)\ge \frac{R}{2}.$$
By our choice of $c, N$ and $T$ we can find some $J\subseteq F$ with $|J|\ge c|F|$ and some $\ot=(t_1, \dots, t_k)\in T$  such that every map $\sigma: J\rightarrow [k]$ extends to a $\psi\in \sR(F, k)$ 
so that $f_\psi(s)\ge t_j$ for all $j\in [k]$ and $s\in \sigma^{-1}(j)$. 
Then
$$f_{\sigma(s)}(sx_\psi)=f_{\psi(s)}(sx_\psi)=f_\psi(s)\ge t_{\sigma(s)}$$
for every $s\in J$, whence
$$x_\psi\in D\cap \bigcap_{s\in J}s^{-1}f_{\sigma(s)}^{-1}([t_{\sigma(s)}, \infty)).$$
Thus $J$ is an independence set for  $\oA_{\of, \ot}$ relative to $D$.
Note that
$$|J|\ge c|F|\ge \frac{c}{3}\upind_\rmm(\oU, \eta)|F'|.$$
If for each $\ot\in T$ there is some $D_\ot\in \sB(\mu, \eta\delta/|T|)$ such that $\oA_{\of, \ot}$ has no independence set in $F'$ relative to $D_\ot$ with cardinality at least $  \frac{c}{3}\upind_\rmm(\oU, \eta)|F'|$, then setting $D=\bigcap_{\ot\in T}D_\ot\in \sB(\mu, \eta\delta)$, from the above we know that $\oA_{\of, \ot}$ for some $\ot\in T$ has an independence set $J$ in $F'$ relative to $D$ with cardinality at least $\frac{c}{3}\upind_\rmm(\oU, \eta)|F'|$, but then $J$ is also an independence set for $\oA_{\of, \ot}$ in $F'$ relative to $D_\ot$, a contradiction. This means that
$$\max_{\ot \in T}\varphi_{\oA_{\of, \ot}, \mu, \eta \delta/|T|}(F')\ge \frac{c}{3}\upind_\rmm(\oU, \eta)|F'|.$$
It follows that
$$ \max_{\ot\in T}\upind_\mu(\oA_{\of, \ot})\ge \max_{\ot \in T}\upind_\mu(\oA_{\of, \ot}, \eta \delta/|T|)\ge \frac{c}{3}\upind_\rmm(\oU, \eta),$$
establishing \eqref{E-measure IE for prob}.

Now we can take a $\ot=(t_1, \dots, t_k)\in T$ such that $\upind_\mu(\oA_{\of, \ot})\ge \frac{c}{3}\upind_\rmm(\oU, \eta)>0$. By Theorem~\ref{T-measure IE basic}.\eqref{i-measure IE tuple} there is an $(x_1, \dots, x_k)\in \IE^\mu_k(X)$ with $x_j\in f_j^{-1}\left([t_j, \infty)\right)$ for every $j\in [k]$.
Then
$$ \sum_{j\in [k]}f_j(x_j)\ge \sum_{j\in [k]}t_j\ge kr>0$$
as desired.

(2). Note that $\ext\, \cM(X)=X$, whence $\ext(\cM(X)^k)=(\ext\, \cM(X))^k=X^k$. By Theorem~\ref{T-measure IE basic}.\eqref{i-measure IE invariant} we know that $\IE^\mu_k(X)$ is closed in $X^k$. From part (1) and Lemma~\ref{L-ext} we have
\begin{align*}
\IE^\rmm_k(\cM(X))\cap X^k &\subseteq \overline{\rm co}(\IE^\mu_k(X))\cap X^k=\overline{\rm co}(\IE^\mu_k(X))\cap \ext(\cM(X)^k)\\
&\subseteq \ext\, \overline{\rm co}(\IE^\mu_k(X))\subseteq \IE^\mu_k(X). \tag*{\qedsymbol}
\end{align*}
     \renewcommand{\qedsymbol}{}
     \vspace{-\baselineskip}
\end{proof}

\begin{remark} \label{R-measure IE not convex}
Despite the product formula for measure IE-tuples in Theorem~\ref{T-measure IE basic}.\eqref{i-measure IE product}, $\IE_k^\rmm(\cM(X))$ may fail to be convex for $\rmm\in \cM_\Gamma(\cM(X))$. For example, let $\mu_1, \mu_2\in \cM_\Gamma(X)$ be distinct, and let $0<\lambda<1$. Then $\rmm=\lambda \delta_{\mu_1}+(1-\lambda)\delta_{\mu_2}$ is in $\cM_\Gamma(\cM(X))$. It is easily checked that
$$\IE^\rmm_2(\cM(X))=\{(\mu_1, \mu_1), (\mu_2, \mu_2)\}$$
is not convex.
\end{remark}

Next we give a few consequences of Theorem~\ref{T-measure IE main}. As mentioned in Section~\ref{S-introduction},
in view of Theorem~\ref{T-measure IE basic}.\eqref{i-measure IE pair}, from the case $k=2$ of Theorem~\ref{T-measure IE main}.(1) we immediately obtain the following result of Glasner, Thouvenot and Weiss \cite[Theorem 1.1]{GW95} \cite[Theorem 7]{GTW}.

\begin{corollary} \label{C-measure IE for prob}
Let $\rmm\in \cM_\Gamma(\cM(X))$ and let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$. If $h_\mu(X)=0$, then $h_\rmm(\cM(X))=0$.
\end{corollary}

For $\mu\in \cM_\Gamma(X)$ and $k\in \Nb$, following Vermersch \cite{Vermersch},
we say that $\Gamma\curvearrowright X$ has {\it $\mu$-Uniform Positive Entropy ($\mu$-UPE) of order $k$} if $\IE^\mu_k(X)=X^k$. From Theorem~\ref{T-measure IE main}.(2) we have the following corollary.

\begin{corollary} \label{C-measure UPE}
Let $\rmm\in \cM_\Gamma(\cM(X))$ and let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$. Let $k\in \Nb$. If $\Gamma\curvearrowright \cM(X)$ has $\rmm$-UPE of order $k$, then $\Gamma\curvearrowright X$ has $\mu$-UPE of order $k$.
\end{corollary}

The case $k=2$ of Corollary~\ref{C-measure UPE} was established by Vermersch for $\Gamma=\Zb$ and ergodic $\rmm$ in \cite[Theorem 6]{Vermersch}.


\begin{corollary} \label{C-average}
Let $N\in \Nb$ and $\olambda\in \orP_N$. Let $\mu\in \cM_\Gamma(X)$, and set $\rmm=(\pi_\olambda)_*\mu^N\in \cM_\Gamma(\cM_\olambda(X))$ (see Notation~\ref{N-finite support2}).
For any $k\in \Nb$, $\Gamma\curvearrowright X$ has $\mu$-UPE of order $k$ if and only if $\Gamma\curvearrowright \cM_\olambda(X)$ has $\rmm$-UPE of order $k$.
\end{corollary}
\begin{proof} Assume that $\Gamma\curvearrowright X$ has $\mu$-UPE of order $k$. From Theorem~\ref{T-measure IE basic}.\eqref{i-measure IE product} we know that $\Gamma\curvearrowright X^N$ has $\mu^N$-UPE of order $k$,
then from Theorem~\ref{T-measure IE basic}.\eqref{i-measure IE factor} we get that $\Gamma\curvearrowright \cM_\olambda(X)$ has $\rmm$-UPE of order $k$. This proves the
``only if'' part.

We may think of $\rmm$ as an element of $\cM_\Gamma(\cM(X))$. It is easily checked that $\IE^\rmm_k(\cM_\olambda(X))\subseteq \IE^\rmm_k(\cM(X))$. Say, $\olambda=(\lambda_1, \dots, \lambda_N)$. For any $f\in C(X)$, we have
$$ \int_{\cM(X)}\nu(f)\, d\rmm(\nu)=\int_{\cM_\olambda(X)}\nu(f)\, d\rmm(\nu)=\int_{X^N}\sum_{j\in [N]}\lambda_j f(x_j)\, d\mu^N(x_1, \dots, x_N)=\mu(f).$$
Thus the barycenter of $\rmm$ is $\mu$.

Assume that $\Gamma\curvearrowright \cM_\olambda(X)$ has $\rmm$-UPE of order $k$. By Theorem~\ref{T-measure IE main}.(2)  we have
$$ X^k=\cM_\olambda(X)^k\cap X^k=\IE^\rmm_k(\cM_\olambda(X))\cap X^k\subseteq \IE^\rmm_k(\cM(X))\cap X^k\subseteq \IE^\mu_k(X)\subseteq X^k,$$
whence $X^k=\IE^\mu_k(X)$. This proves the ``if'' part.
\end{proof}

The case $k=2$ and $\olambda=(\underbrace{1/N, \dots, 1/N}_{N})$ of Corollary~\ref{C-average} was established by Vermersch for $\Gamma=\Zb$ and ergodic $\mu$ in \cite[Theorem 3]{Vermersch}.



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{$\IN$-tuples of $\cM(X)$} \label{S-IN for prob}

In this section we prove Theorem~\ref{T-IN main}. Throughout this section, we consider a continuous action of a countably infinite (not necessarily amenable) group $\Gamma$ on a compact metrizable space $X$. 



As we shall see later in Section~\ref{S-example}, the set $\IN_k(\cM(X))$ may fail to be convex. In order to obtain an analogue of Theorem~\ref{T-IE main}.(3) for IN-tuples, we need to replace $\cM(\IN_k(X))$ by a suitable subset. 
The following definition provides such a subset, and it involves not only $\IN_k(X)$ but also $\IN_k(X^n)$ for all $n\in \Nb$. 

\begin{definition} \label{D-IN measure}
Let $k\in \Nb$. We say $\mu\in \cM(X^k)$ is an {\it $\IN$-measure} if for any $n\in \Nb$ and   any $(x_1^{(i)}, \dots, x_k^{(i)})\in \supp(\mu)$ for $i\in [n]$, one has
$$\left((x_1^{(1)}, \dots, x_1^{(n)}), (x_2^{(1)}, \dots, x_2^{(n)}), \dots, (x_k^{(1)}, \dots, x_k^{(n)})\right)\in \IN_k(X^n).$$
We denote by $\cM_\IN(X^k)$ the set of all $\IN$-measures in  $\cM(X^k)$.
\end{definition}

\begin{remark} \label{R-IN measure}
For each $n\in \Nb$, we have the $\Gamma$-equivariant embedding $X^n\rightarrow X^{n+1}$ sending $(x_1, \dots, x_n)$ to $(x_1, \dots, x_n, x_n)$ repeating the last coordinate. From Theorem~\ref{T-IN basic}.\eqref{i-IN subset} we see that for any $k, n\in \Nb$ and 
$$\left((x_1^{(1)}, \dots, x_1^{(n)}), (x_2^{(1)}, \dots, x_2^{(n)}), \dots, (x_k^{(1)}, \dots, x_k^{(n)})\right)\in \IN_k(X^n),$$
one has 
$$\left((x_1^{(1)}, \dots, x_1^{(n)}, x_1^{(n)}), (x_2^{(1)}, \dots, x_2^{(n)}, x_2^{(n)}), \dots, (x_k^{(1)}, \dots, x_k^{(n)}, x_k^{(n)})\right)\in \IN_k(X^{n+1}).$$
It follows that in Definition~\ref{D-IN measure} we obtain the same definition no matter we require the points $(x_1^{(i)}, \dots, x_k^{(i)})\in \supp(\mu)$ for $i\in [n]$ to be distinct or not. 
\end{remark}

\begin{proposition} \label{P-IN measure basic}
For each $k\in \Nb$, $\cM_\IN(X^k)$ is a $\Gamma$-invariant closed subset of $\cM(\IN_k(X))$.
\end{proposition}
\begin{proof} For each $\mu\in \cM_\IN(X^k)$, taking $n=1$ in Definition~\ref{D-IN measure} we see that $\supp(\mu)\subseteq \IN_k(X)$, whence $\mu$ is actually a measure on $\IN_k(X)$. 

From Theorem~\ref{T-IN basic}.\eqref{i-IN invariant} we know that  $\IN_k(X^n)$ is $\Gamma$-invariant for each $n\in \Nb$. It follows that $\cM_\IN(X^k)$ is $\Gamma$-invariant.

Let $\mu$ be in the closure of $\cM_\IN(X^k)$. Let $n\in \Nb$ and $\ox^{(i)}=(x_1^{(i)}, \dots, x_k^{(i)})\in \supp(\mu)$ for each $i\in  [n]$.
We have the natural homeomorphism $\Phi: (X^k)^n\rightarrow (X^n)^k$ sending
$$\left((z_1^{(1)}, \dots, z_k^{(1)}), (z_1^{(2)}, \dots, z_k^{(2)}), \dots, (z_1^{(n)}, \dots, z_k^{(n)})\right)$$
to
$$\left((z_1^{(1)}, \dots, z_1^{(n)}), (z_2^{(1)}, \dots, z_2^{(n)}), \dots, (z_k^{(1)}, \dots, z_k^{(n)})\right).$$
Let $V$ be a neighborhood of $\Phi(\ox^{(1)}, \dots, \ox^{(n)})$ in $(X^n)^k$.
Then we can find an open neighborhood $U_i$ of $\ox^{(i)}$ in $X^k$ for each $i\in [n]$ such that $\Phi(U_1\times \cdots \times U_n)\subseteq V$. Note that $\mu(U_i)>0$ for each $i\in [n]$. Since the function $\cM(X^k)\rightarrow \Rb$ sending $\nu$ to $\nu(U)$ is lower semicontinuous for each open subset $U$ of $X^k$, we can find a $\nu\in \cM_\IN(X^k)$ close enough to $\mu$ such that $\nu(U_i)>0$ for all $i\in [n]$. Then there exists $\oy^{(i)}=(y_1^{(i)}, \dots, y_k^{(i)})\in \supp(\nu)\cap U_i$ for each $i\in [n]$. Since $\nu\in \cM_\IN(X^k)$, we have
$$\left((y_1^{(1)}, \dots, y_1^{(n)}), (y_2^{(1)}, \dots, y_2^{(n)}), \dots, (y_k^{(1)}, \dots, y_k^{(n)})\right)\in \IN_k(X^n).$$
This point is $\Phi(\oy^{(1)}, \cdots, \oy^{(n)})\in \Phi(U_1\times \cdots \times U_n)\subseteq V$. Thus $V\cap \IN_k(X^n)\neq \emptyset$. From Theorem~\ref{T-IN basic}.(1) we know that $\IN_k(X^n)$ is a closed subset of $(X^n)^k$. We conclude that $\Phi(\ox^{(1)}, \dots, \ox^{(n)})\in \IN_k(X^n)$. Thus $\mu\in \cM_\IN(X^k)$. Therefore $\cM_\IN(X^k)$ is closed. 
\end{proof}


For $k, n\in \Nb$,
we set 
$$\cM_{\IN, n}(X^k)=\cM_\IN(X^k)\cap \cM_n(X^k)$$ 
to be the set of $\mu\in \cM_\IN(X^k)$ with $|\supp(\mu)|\le n$, and set (see Notation~\ref{N-finite support2})
$$\cA_{k, n}=\bigcup_{\olambda\in \orP_n}(\pi_\olambda\times \cdots \times \pi_\olambda)(\IN_k(X^n))\subseteq  \cM_n(X)^k.$$
In order to prove part (3) of Theorem~\ref{T-IN main}, we shall show that both $\{(\mu^{(1)}, \dots, \mu^{(k)}): \mu\in \cM_\IN(X^k)\}$ and $\IN_k(\cM(X))$ are equal to 
$\overline{\bigcup_{n\in \Nb}\cA_{k, n}}$ in Lemmas~\ref{L-IN closure vs push} and \ref{L-IN dense} respectively. 

\begin{lemma} \label{L-IN finite support}
For any $k, n\in \Nb$, we have
$$\cA_{k, n}=\{(\mu^{(1)}, \dots, \mu^{(k)})\in \cM(X)^k: \mu\in \cM_{\IN, n}(X^k)\}.$$
\end{lemma}
\begin{proof} From Remark~\ref{R-IN measure} we see that the set $\cM_{\IN, n}(X^k)$ consists of 
$$ \mu=\sum_{i\in [n]}\lambda_i \delta_{(x_1^{(i)}, \dots, x_k^{(i)})}$$
for $\olambda=(\lambda_1, \dots, \lambda_n)\in \orP_n$ and 
$$\ox=\left((x_1^{(1)}, \dots, x_1^{(n)}), (x_2^{(1)}, \dots, x_2^{(n)}), \dots, (x_k^{(1)}, \dots, x_k^{(n)})\right)\in \IN_k(X^n).$$
Then
$$(\mu^{(1)}, \dots, \mu^{(k)})=\left(\sum_{i\in [n]}\lambda_i \delta_{x_1^{(i)}}, \dots, \sum_{i\in [n]}\lambda_i \delta_{x_k^{(i)}}\right)$$
is exactly $(\pi_\olambda\times \cdots \times \pi_\olambda)(\ox)$.
\end{proof}



\begin{lemma} \label{L-IN convex}
We have $\cA_{k, n}\subseteq  \IN_k(\cM_n(X))$ for all $k, n\in \Nb$.
\end{lemma}
\begin{proof}
From parts \eqref{i-IN factor} and \eqref{i-IN subset} of Theorem~\ref{T-IN basic} we have
\begin{displaymath}
 \cA_{k, n}=\bigcup_{\olambda\in \orP_n}\IN_k(\cM_\olambda(X))\subseteq \IN_k(\cM_n(X)). \tag*{\qedsymbol}
\end{displaymath}
     \renewcommand{\qedsymbol}{}
     \vspace{-\baselineskip}
\end{proof}





\begin{lemma} \label{L-IN closure vs push}
Let $k\in \Nb$. Then
$$\overline{\bigcup_{n\in \Nb}\cA_{k, n}}=\{(\mu^{(1)}, \dots, \mu^{(k)})\in \cM(X)^k: \mu\in \cM_\IN(X^k)\}.$$
\end{lemma}
\begin{proof} The map $\pi: \cM(X^k)\rightarrow \cM(X)^k$ sending $\nu$ to $(\nu^{(1)}, \dots, \nu^{(k)})$ is continuous. 
Note that $\cM_\IN(X^k)':=\bigcup_{n\in \Nb}\cM_{\IN, n}(X^k)$ is dense in $\cM_\IN(X^k)$. 
We have
$$ \pi(\cM_\IN(X^k)')\subseteq \pi(\cM_\IN(X^k))=\pi(\overline{\cM_\IN(X^k)'})\subseteq \overline{\pi(\cM_\IN(X^k)')}.$$
By Proposition~\ref{P-IN measure basic} the space $\cM_\IN(X^k)$ is compact. Thus $\pi(\cM_\IN(X^k))$ is compact, and hence closed in $\cM(X)^k$.
Then from the first inclusion above we have 
$$\overline{\pi(\cM_\IN(X^k)')}\subseteq \pi(\cM_\IN(X^k)).$$
It follows that 
\begin{align*}
\pi(\cM_\IN(X^k))=\overline{\pi(\cM_\IN(X^k)')}=\overline{\bigcup_{n\in \Nb}\cA_{k, n}},
\end{align*}
where the last equality is from Lemma~\ref{L-IN finite support}. 
\end{proof}




Let $m\in \Nb$. For any $\ot=(t_1, \dots, t_m)\in \Rb^m$, we set
$$ \|\ot\|_\infty=\max_{j\in [m]}|t_j|,  \mbox{ and } \|\ot\|_1=\sum_{j\in [m]}|t_j|.$$
We also set
$$D_m=\{(t_1, \dots, t_m)\in \Rb^m: t_j\ge 0 \mbox{ for all } j\in [m]\}.$$
For $\boldsymbol{w}, \boldsymbol{t}\in \Rb^m$, we write $\left< \boldsymbol{w}, \boldsymbol{t}\right>$ for their inner product.

\begin{lemma} \label{L-convex intersection}
Let $m\in \Nb$ and $C>1$. There are an $\varepsilon\in (0, 1)$ and a finite set $\Lambda\subseteq \orP_m$ depending only on $m$ and $C$ such that the following holds. If we take a point $\ow^{(\olambda)}\in \Rb^m$ satisfying $\|\ow^{(\olambda)}\|_\infty\le C$ and $\left<\ow^{(\olambda)}, \olambda\right>\ge 1-\varepsilon$ for each $\olambda\in \Lambda$, then the convex hull of $\{\ow^{(\olambda)}: \olambda\in \Lambda\}$ intersects $\frac{1}{2}\ov+D_m$, where $\ov=(\underbrace{1, \dots, 1}_{m})\in \Rb^m$.
\end{lemma}
\begin{proof} Let $\varepsilon=1/4$. Since $\orP_m$ is compact, we can find a finite set $\Lambda\subseteq \orP_m$ such that for each $\olambda\in \orP_m$ there is some $\olambda'\in \Lambda$ so that $\|\olambda-\olambda'\|_1<1/(4C)$. We shall show that $\varepsilon$ and $\Lambda$ have the desired property.

Let $\ow^{(\olambda)}\in \Rb^m$ for each $\olambda\in \Lambda$ such that $\|\ow^{(\olambda)}\|_\infty\le C$ and $\left<\ow^{(\olambda)}, \olambda\right>\ge 1-\varepsilon$.
We denote by $\cK$ the convex hull of $\{\ow^{(\olambda)}: \olambda\in \Lambda\}$. We argue by contradiction.  Assume that $\cK\cap (\frac{1}{2}\ov+D_m)=\emptyset$.
Since $\Lambda$ is finite, $\cK$ is compact.
By the geometric consequence of the Hahn-Banach theorem \cite[Proposition IV.3.6.(b) and Theorem IV.3.9]{Conway}, there is some $\boldsymbol{\lambda}\in \Rb^m$ such that
\begin{align} \label{E-convex intersection}
\max_{\ot\in \cK}\left< \ot, \olambda\right>< \inf_{\ot\in \frac{1}{2}\ov+D_m}\left< \ot, \olambda\right>.
\end{align}
Then
$$\frac{1}{2}\left< \ov, \olambda\right>+\inf_{\ot\in D_m}\left< \ot, \olambda\right>=\inf_{\ot\in \frac{1}{2}\ov+D_m}\left< \ot, \olambda\right>$$
is finite, and hence $\olambda\in D_m$. Multiplying $\olambda$ by a scalar if necessary, we may assume that $\|\olambda\|_1=1$. Then $\olambda\in \orP_m$. By our choice of $\Lambda$ we can find a $\olambda'\in \Lambda$ such that $\|\olambda-\olambda'\|_1<1/(4C)$. We have
\begin{align*}
\max_{\ot\in \cK}\left< \ot, \olambda\right>&\ge
\left<\ow^{(\olambda')}, \olambda\right>\ge
\left<\ow^{(\olambda')}, \olambda'\right>-\|\ow^{(\olambda')}\|_\infty\cdot \|\olambda-\olambda'\|_1\\
&> \left<\ow^{(\olambda')}, \olambda'\right>-1/4\ge 1-\varepsilon-1/4=1/2,
\end{align*}
and
\begin{align*}
\inf_{\ot\in \frac{1}{2}\ov+D_m}\left< \ot, \olambda\right>
=\left< \frac{1}{2}\ov, \olambda\right>=1/2,
\end{align*}
a contradiction to \eqref{E-convex intersection}. Therefore $\cK\cap (\frac{1}{2}\ov+D_m)\neq \emptyset$.
\end{proof}



\begin{lemma} \label{L-IN simul}
Let $k, n\in \Nb$, $\omu=(\mu_1, \dots, \mu_k)\in \cM(X)^k$  and $\of^{(l)}=(f_1^{(l)}, \dots, f_k^{(l)})\in C(X)^{\oplus k}$ for $l\in [n]$ such that $R^{(l)}:=\frac{1}{k}\sum_{j\in [k]}\mu_j(f_j^{(l)})>0$ for each $l\in [n]$. 
%Let $C>0$ with $C\ge \max_{l\in [n]}\|\of^{(l)}\|$ and  
Let $0<r^{(l)}<R^{(l)}$ for each $l\in [n]$.  Then there are some finite set $T^{(l)}\subseteq \Rb^k$ for each $l\in [n]$,  some $c, N>0$, 
 and some product neighborhood $U_1\times \cdots \times U_k$ of $\omu$ in $\cM(X)^k$ such that the following hold:
 \begin{enumerate}
 \item $\frac{1}{k}\sum_{j\in [k]}t_j\ge r^{(l)}$ for every $l\in [n]$ and $(t_1, \dots, t_k)\in T^{(l)}$, and
 \item for any independence set $F\in \cF(\Gamma)$ of $(U_1, \dots, U_k)$ with $|F|\ge N$,
 there are  some $J\subseteq F$ with $|J|\ge c|F|$ and some $\ot^{(l)}=(t_1^{(l)}, \dots, t_k^{(l)})\in T^{(l)}$ for each $l\in [n]$ so that
 $J$ is an independence set for the $k$-tuple
 \begin{align} \label{E-IN simul}
 \Big(\prod_{l\in [n]} (f_1^{(l)})^{-1}([t_1^{(l)}, \infty)), \dots, \prod_{l\in [n]} (f_k^{(l)})^{-1}([t_k^{(l)}, \infty))\Big)
  \end{align}
  of subsets of $X^n$.
  \end{enumerate}
 \end{lemma}
\begin{proof} We take a $C\ge \max_{l\in [n]}\|\of^{(l)}\|$. For each $l\in [n]$, we have $c^{(l)}, N^{(l)}$, $T^{(l)}$ and $U_1^{(l)}\times \cdots \times U_k^{(l)}$ given by Lemma~\ref{L-func to density} for $k, r^{(l)}, R^{(l)}, C, \omu$ and $\of^{(l)}$. We set $c=\prod_{l\in [n]}c^{(l)}>0$. We take a large $N>0$ such that $Nc^{(1)}\cdots c^{(l-1)}\ge N^{(l)}$ for all $l\in [n]$. We also set $U_j=\bigcap_{l\in [n]}U_j^{(l)}$ for each $j\in [k]$. Then $\frac{1}{k}\sum_{j\in [k]}t_j\ge r^{(l)}$ for every $l\in [n]$ and $(t_1, \dots, t_k)\in T^{(l)}$, and $U_1\times \cdots \times U_k$ is a product neighborhood  of $\omu$ in $\cM(X)^k$.

Let $F\in \cF(\Gamma)$ be  an  independence set of $(U_1, \dots, U_k)$ with $|F|\ge N$. We set $J_0=F$.
Via induction on $l=1, \dots, n$, from our choice of $c^{(l)}, N^{(l)}$, $T^{(l)}$ and $U_1^{(l)}\times \cdots \times U_k^{(l)}$ we can find some $J_l\subseteq J_{l-1}$ and some $\ot^{(l)}\in T^{(l)}$ such that $|J_l|\ge c^{(l)}|J_{l-1}|$ and $J_l$ is an independence set for $\oA_{\of^{(l)}, \ot^{(l)}}$ (see Notation~\ref{N-tuple}). Then $|J_n|\ge c|F|$ and $J_n$ is an independence set for $\oA_{\of^{(l)}, \ot^{(l)}}$ for every $l\in [n]$. It follows that $J_n$ is an independence set for
the $k$-tuple in \eqref{E-IN simul}.
\end{proof}


\begin{lemma} \label{L-IN dense}
Let $k\in \Nb$. Then $\IN_k(\cM(X))=\overline{\bigcup_{n\in \Nb}\cA_{k, n}}$.
\end{lemma}
\begin{proof} By Theorem~\ref{T-IN basic}.\eqref{i-IN subset} we have $\IN_k(\cM(X))\supseteq \IN_k(\cM_n(X))$ for every $n\in \Nb$. 
Thus from Lemma~\ref{L-IN convex} we have $\IN_k(\cM(X))\supseteq \bigcup_{n\in \Nb}\cA_{k, n}$. From Theorem~\ref{T-IN basic}.\eqref{i-IN invariant} we know that $\IN_k(\cM(X))$ is a closed subset of $\cM(X)^k$. Therefore $\IN_k(\cM(X))\supseteq \overline{\bigcup_{n\in \Nb}\cA_{k, n}}$.

Let $\omu=(\mu_1, \dots, \mu_k)\in \IN_k(\cM(X))$. We shall show that $\omu\in \overline{\bigcup_{n\in \Nb}\cA_{k, n}}$.

Let $U$ be a neighborhood of $\omu$ in $\cM(X)^k$. It suffices to show $U\cap \bigcup_{n\in \Nb}\cA_{k, n}\neq \emptyset$. Shrinking $U$ if necessary, we may assume that there are $m\in \Nb$ and
$$\of^{(i)}=(f^{(i)}_1, \dots, f^{(i)}_k)\in C(X)^{\oplus k}$$
for $i\in [m]$ such that
$$\sum_{j\in [k]}\mu_j(f^{(i)}_j)=1$$
for each $i\in [m]$ and
$$ U=\{(\nu_1, \dots, \nu_k)\in \cM(X)^k: \sum_{j\in [k]}\nu_j(f^{(i)}_j)\ge 0 \mbox{ for all } i\in  [m]\}.$$

We set $C=2+k\max_{i\in  [m]}\|\of^{(i)}\|>1$.  Then we have $\varepsilon>0$ and a finite set $\Lambda\subseteq \orP_m$ given by Lemma~\ref{L-convex intersection}.  For each $\olambda=(\lambda_1, \dots, \lambda_m)\in \Lambda$, we set
$$f^{(\olambda)}_j=\sum_{i\in [m]} \lambda_i f^{(i)}_j\in C(X)$$
for $j\in [k]$, and
$$\of^{(\olambda)}=\sum_{i\in [m]} \lambda_i\of^{(i)}=\left(\sum_{i\in [m]} \lambda_i f^{(i)}_1, \dots, \sum_{i\in [m]} \lambda_i f^{(i)}_k\right)=(f^{(\olambda)}_1, \dots, f^{(\olambda)}_k)\in C(X)^{\oplus k}.$$
Then 
$$\|\of^{(\olambda)}\|=\max_{j\in [k]}\|f^{(\olambda)}_j\|\le \max_{j\in [k]}\max_{i\in [m]}\|f^{(i)}_j\|=\max_{i\in [m]}\|\of^{(i)}\|\le C,$$ 
and
$$\sum_{j\in [k]}\mu_j(f^{(\olambda)}_j)=\sum_{j\in [k]}\sum_{i\in [m]} \lambda_i\mu_j(f^{(i)}_j)=\sum_{i\in [m]}\sum_{j\in [k]} \lambda_i\mu_j(f^{(i)}_j)=\sum_{i\in [m]}\lambda_i=1$$
for every $\olambda\in \Lambda$.

We set $R=1/k$ and $r=(1-\varepsilon)/k$. By Lemma~\ref{L-IN simul}  there are some finite set $T^{(\olambda)}\subseteq \Rb^k$ for each $\olambda\in \Lambda$, some $c, N>0$,
 and some product neighborhood $U_1\times \cdots \times U_k$ of $\omu$ in $\cM(X)^k$ such that the following hold:
  \begin{enumerate}
  \item $\frac{1}{k}\sum_{j\in [k]}t_j^{(\olambda)}\ge r$ for all $\olambda\in \Lambda$ and $(t_1^{(\olambda)}, \dots, t_k^{(\olambda)})\in T^{(\olambda)}$, and
  \item for any independence set $F\in \cF(\Gamma)$ of $\oU=(U_1, \dots, U_k)$ with $|F|\ge N$,
 there are  some $J\subseteq F$ with $|J|\ge c|F|$ and some $\ot^{(\olambda)}=(t_1^{(\olambda)}, \dots, t_k^{(\olambda)})\in T^{(\olambda)}$ for each $\olambda\in \Lambda$ so that
 $J$ is an independence set for the $k$-tuple
 \begin{align} \label{E-IN dense}
 \left(\prod_{\olambda\in \Lambda} (f_1^{(\olambda)})^{-1}([t_1^{(\olambda)}, \infty)), \dots, \prod_{\olambda\in \Lambda} (f_k^{(\olambda)})^{-1}([t_k^{(\olambda)}, \infty))\right)
 \end{align}
 of closed subsets of $X^\Lambda$.
 \end{enumerate}

We claim that there is some $\ot^{(\olambda)}=(t_1^{(\olambda)}, \dots, t_k^{(\olambda)})\in T^{(\olambda)}$ for each $\olambda\in \Lambda$ so that the tuple \eqref{E-IN dense} has arbitrarily large finite independence sets. We argue by contradiction. Assume that the tuple \eqref{E-IN dense} does not have arbitrarily large finite independence sets
for any choice of $\ot^{(\olambda)}=(t_1^{(\olambda)}, \dots, t_k^{(\olambda)})\in T^{(\olambda)}$ for each $\olambda\in \Lambda$. Since $\Lambda$ is finite and $T^{(\olambda)}$ for each $\olambda\in \Lambda$ is finite, it follows that there is some $L\in \Nb$ such that for any choice of $\ot^{(\olambda)}=(t_1^{(\olambda)}, \dots, t_k^{(\olambda)})\in T^{(\olambda)}$ for each $\olambda\in \Lambda$, every independence set for the tuple \eqref{E-IN dense} has cardinality $<L$.
Since $\omu\in \IN_k(\cM(X))$, we can find an independence set $F\in \cF(\Gamma)$ for $\oU$ with $|F|\ge \max(N, L/c)$.
Then there are  some $J\subseteq F$ with $|J|\ge c|F|\ge L$ and some $\ot^{(\olambda)}=(t_1^{(\olambda)}, \dots, t_k^{(\olambda)})\in T^{(\olambda)}$ for each $\olambda\in \Lambda$ so that
 $J$ is an independence set for the tuple \eqref{E-IN dense}, a contradiction. This proves our claim.

 Let $\ot^{(\olambda)}=(t_1^{(\olambda)}, \dots, t_k^{(\olambda)})\in T^{(\olambda)}$ for each $\olambda\in \Lambda$ so that the tuple \eqref{E-IN dense} has arbitrarily large finite independence sets. By Theorem~\ref{T-IN basic}.\eqref{i-IN tuple} there is some
 $$ ((x^{(\olambda)}_1)_{\olambda\in \Lambda}, \dots, (x^{(\olambda)}_k)_{\olambda\in \Lambda})$$
in the intersection of $\big(\prod_{\olambda\in \Lambda} (f_1^{(\olambda)})^{-1}([t_1^{(\olambda)}, \infty))\big)\times \cdots \times \big(\prod_{\olambda\in \Lambda}(f_k^{(\olambda)})^{-1}([t_k^{(\olambda)}, \infty))\big)$ and
$\IN_k(X^\Lambda)$.

Let $\olambda=(\lambda_1, \dots, \lambda_m)\in \Lambda$. We have
$$(x^{(\olambda)}_1, \dots, x^{(\olambda)}_k)\in (f_1^{(\olambda)})^{-1}([t_1^{(\olambda)}, \infty))\times \cdots \times (f_k^{(\olambda)})^{-1}( [t_k^{(\olambda)}, \infty)). $$
Since  $\ot^{(\olambda)}=(t_1^{(\olambda)}, \dots, t_k^{(\olambda)})\in T^{(\olambda)}$ ,  we have
$$ \frac{1}{k}\sum_{j\in [k]} f^{(\olambda)}_j(x^{(\olambda)}_j)\ge \frac{1}{k}\sum_{j\in [k]} t_j^{(\olambda)}\ge r=\frac{1}{k}(1-\varepsilon). $$
 We set
$$ \ow^{(\olambda)}=\left(\sum_{j\in [k]} f^{(1)}_j(x^{(\olambda)}_j), \dots, \sum_{j\in [k]} f^{(m)}_j(x^{(\olambda)}_j)\right)\in \Rb^m.$$
Then  $\|\ow^{(\olambda)}\|_\infty\le k\max_{i\in [m]}\|\of^{(i)}\|\le C$, and
$$\left<\ow^{(\olambda)}, \olambda\right>=\sum_{i\in [m]} \lambda_i\sum_{j\in [k]} f^{(i)}_j(x^{(\olambda)}_j)=\sum_{j\in [k]}\sum_{i\in [m]} \lambda_i f^{(i)}_j(x^{(\olambda)}_j)=\sum_{j\in [k]} f^{(\olambda)}_j(x^{(\olambda)}_j)\ge 1-\varepsilon.$$

By our choice of $\varepsilon$ and $\Lambda$, the convex hull of $\{\ow^{(\olambda)}: \olambda\in \Lambda\}$ intersects $\frac{1}{2}\ov+D_m$, where $\ov=(\underbrace{1, \dots, 1}_{m})\in \Rb^m$. Thus we can find $t_{\olambda}\in [0, 1]$ for each $\olambda\in \Lambda$ such that $\sum_{\olambda\in \Lambda}t_{\olambda}=1$ and $\sum_{\olambda\in \Lambda}t_{\olambda}\ow^{(\olambda)}\in \frac{1}{2}\ov+D_m$. Now we have
$$ \onu:=\left(\sum_{\olambda\in \Lambda}t_{\olambda}\delta_{x_1^{(\olambda)}}, \dots, \sum_{\olambda\in \Lambda}t_{\olambda}\delta_{x_k^{(\olambda)}}\right)\in \cA_{k, |\Lambda|}.$$
For each $i\in [m]$,
\begin{align*}
\sum_{j\in [k]}\left(\sum_{\olambda\in \Lambda}t_{\olambda}\delta_{x_j^{(\olambda)}}\right)(f_j^{(i)})
= \sum_{\olambda\in \Lambda}\sum_{j\in [k]} t_{\olambda}f_j^{(i)}(x_j^{(\olambda)})
\end{align*}
is the $i$-th coordinate of $\sum_{\olambda\in \Lambda}t_{\olambda}\ow^{(\olambda)}$, and hence is $\ge 1/2$. Thus $\onu\in U\cap \cA_{k, |\Lambda|}$. This finishes the proof.
\end{proof}

We are ready to prove Theorem~\ref{T-IN main}. 


\begin{proof}[Proof of Theorem~\ref{T-IN main}] 
For each $n\in \Nb$ and 
$$\left((x_1^{(1)}, \dots, x_1^{(n)}), (x_2^{(1)}, \dots, x_2^{(n)}), \dots, (x_k^{(1)}, \dots, x_k^{(n)})\right)\in \IN_k(X^n),$$
from Theorem~\ref{T-IN basic}.\eqref{i-IN factor} we know that 
$$ (x_1^{(i)}, \dots, x_k^{(i)})\in \IN_k(X)$$
for every $i\in [n]$. 
Thus $\cA_{k, n}$ is included in the convex hull of $\IN_k(X)$ in $\cM(X)^k$ for every $n\in \Nb$. Then part (1) follows from Lemma~\ref{L-IN dense}.

Part (3) follows from Lemmas~\ref{L-IN closure vs push} and \ref{L-IN dense}. 

From Theorem~\ref{T-IN basic}.\eqref{i-IN subset} we have $\IN_k(X)\subseteq \IN_k(\cM(X))\cap X^k$. From part (3) we have
$\IN_k(\cM(X))\cap X^k\subseteq \IN_k(X)$. This proves part (2). 
\end{proof}

Next we prove Corollary~\ref{C-IN finite support}. 

\begin{proof}[Proof of Corollary~\ref{C-IN finite support}] Let $\omu\in (\cM_{N_1}(X)\times \cdots \times \cM_{N_k}(X))\cap \IN_k(\cM(X))$. By Theorem~\ref{T-IN main}.(3) we have $\omu=(\mu^{(1)}, \dots, \mu^{(k)})$ for some $\mu\in \cM_\IN(X^k)$. 
%there exists a $\mu\in \cM_\IN(X^k)$ such that $\mu_j$ is the push-forward of $\mu$ under the $j$-th coordinate map $X^k\rightarrow %X$ for each $j\in [k]$. 
Then $$\mu\left(\supp(\mu^{(1)})\times \cdots \times \supp(\mu^{(k)})\right)=1,$$
and $|\supp(\mu^{(j)})|\le N_j$ for every $j\in [k]$. 
Thus $|\supp(\mu)|\le N$, and hence $\mu\in \cM_{\IN, N}(X^k)$. By Lemmas~\ref{L-IN finite support} and \ref{L-IN convex}
% and Theorem~\ref{T-IN basic}.\eqref{i-IN subset} 
we have $\omu\in \cA_{k, N}\subseteq \IN_k(\cM_N(X))$. 
\end{proof}

In view of Theorem~\ref{T-IN basic}.\eqref{i-IN pair}, from the case $k=2$  of parts (1) and (2) of Theorem~\ref{T-IN main} we obtain immediately the following result of
Kerr and Li \cite[Theorem 5.10]{KL05}.


\begin{corollary} \label{C-IN for prob}
$\Gamma\curvearrowright X$ is null if and only if $\Gamma\curvearrowright \cM(X)$ is null.
\end{corollary}

In \cite[Theorem 1]{QZ} Qiao and Zhou strengthened Corollary~\ref{C-IN for prob}. They showed that for any fixed sequence $\mathfrak{s}$ in $\Gamma$, $h_{\rm top}(X; \mathfrak{s})=0$ if and only if $h_{\rm top}(\cM(X); \mathfrak{s})=0$.


For $k\in \Nb$, we say $\Gamma\curvearrowright X$ is {\it uniformly nonnull of order $k$} if $\IN_k(X)=X^k$ \cite[page 894]{KL07}. In view of Theorem~\ref{T-IN basic}.\eqref{i-IN subset}, from Theorem~\ref{T-IN main}.(2) we have the following corollary.

\begin{corollary} \label{C-IN order k}
Let  $k, N\in \Nb$ and $\olambda\in \orP_N$. If $\Gamma\curvearrowright \cM_\olambda(X)$ or $\Gamma\curvearrowright \cM(X)$ is uniformly nonnull of order $k$, then so is $\Gamma\curvearrowright X$.
\end{corollary}




