\section{Measure $\IN$-tuples of $\cM(X)$} \label{S-measure IN for prob}

In this section we prove Theorem~\ref{T-measure IN main}. Throughout this section we consider a continuous action of a countably infinite group $\Gamma$ on a compact metrizable space $X$. 



We start with the following  generalization of  Lemma~\ref{L-measure func to func}.

\begin{lemma} \label{L-measure IN func to func}
Let $\rmm\in \cM_\Gamma(\cM(X))$ and let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$. Let $k\in \Nb$, $\onu=(\nu_1, \dots, \nu_k)\in \cM(X)^k$ and $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$.  Let $R=\frac{1}{k}\sum_{j\in [k]}\nu_j(f_j)$ and let $r<R$.
Let $C\in \Rb$.
Then there are some $0<\delta<1$ and some product neighborhood $U_1\times \cdots \times U_k$ of $\onu$ in $\cM(X)^k$ such that the following holds. For any $0<\eta\le 1$ and any $D\in \sB'(\mu, \eta \delta)$ (see Section~\ref{SS-measure IN}) there is some $D'\in \sB'(\rmm, \eta)$ so that for any independence set $F\in \cF(\Gamma)$ of $(U_1, \dots, U_k)$ relative to $D'$ and any surjective map $\psi: F\rightarrow [k]$,  there is
some $x\in X$ such that
\begin{align} \label{E-measure IN func to func}
\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}\left(f_j(sx){\bf 1}_{D_s}(x)-(k-1)C{\bf 1}_{X\setminus D_s}(x)\right)\ge r.
\end{align}
\end{lemma}
\begin{proof} We take a $C_1>0$ such that $C_1\ge \|\of\|$. We also take $0<\theta, \delta<1$ small such that
$$R-\theta-(C_1+(k-1)|C|)\delta  \ge r. $$
For each $j\in [k]$, we denote by $U_j$ the set of $\omega\in \cM(X)$ satisfying $\omega(f_j)\ge \nu_j(f_j)-\theta$. This is a neighborhood of $\nu_j$ in $\cM(X)$. We shall show that $\delta$ and $U_1\times \cdots \times U_k$  have the desired property. 

Let $0<\eta\le 1$
and $D\in \sB'(\mu, \eta \delta)$. For each $s\in \Gamma$, we denote by $D'_s$ the set of $\omega\in \cM(X)$ satisfying $\omega(D_s)\ge 1-\delta$. By Lemma~\ref{L-barycenter} we know that $D_s'$ is Borel and
\begin{align*}
\eta \delta &\ge \mu(X\setminus D_s)=\int_{\cM(X)}\omega(X\setminus D_s)\, d\rmm(\omega)\ge \int_{\cM(X)\setminus D'_s}\omega(X\setminus D_s)\, d\rmm(\omega)\\
&\ge \delta\cdot \rmm(\cM(X)\setminus D'_s)=\delta(1-\rmm(D'_s)),
\end{align*}
whence
$$\rmm(D'_s)\ge 1-\eta.$$
That is, $D'\in \sB'(\rmm, \eta)$.

Let $F\in \cF(\Gamma)$ be an independence set for $(U_1, \dots, U_k)$ relative to $D'$ and let $\psi: F\rightarrow [k]$ be surjective. Then $\bigcap_{s\in F}(D'_s\cap s^{-1}U_{\psi(s)})$ is nonempty, whence 
we can find some $\omega\in \bigcap_{s\in F}(D'_s\cap s^{-1}U_{\psi(s)})$.
We have
\begin{align*}
\int_X \left(\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\right)\, d\omega(x)&=\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(s\omega)(f_j)\\
&\ge \frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(\nu_j(f_j)-\theta)\\
&=\frac{1}{k}\sum_{j\in [k]}(\nu_j(f_j)-\theta)=R-\theta,
\end{align*}
where in the inequality we use $s\omega\in U_{\psi(s)}$ for all $s\in F$, and hence
\begin{align*}
& \int_X \left(\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}\left(f_j(sx){\bf 1}_{D_s}(x)-(k-1)C {\bf 1}_{X\setminus D_s}(x)\right)\right)\, d\omega(x)\\
&\quad \quad = \int_X \left(\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}f_j(sx)\right)\, d\omega(x)\\
&\quad \quad \quad \quad -\int_X \left(\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(f_j(sx)+(k-1)C){\bf 1}_{X\setminus D_s}(x)\right)\, d\omega(x)\\
&\quad \quad\ge R-\theta-\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}(C_1+(k-1)|C|)\omega(X\setminus D_s)\\
&\quad \quad\ge R-\theta-(C_1+(k-1)|C|)\delta \ge r,
\end{align*}
where in the second inequality we use $\omega\in D_s'$ for all $s\in F$.
Thus we can find some $x\in X$ such that \eqref{E-measure IN func to func} holds.
\end{proof}

The following lemma is an analogue of Lemmas~\ref{L-Hahn Banach IE} and \ref{L-Hahn Banach measure IE}, and can be proved in the same way.

\begin{lemma} \label{L-Hahn Banach measure IN}
Let $\rmm\in \cM_\Gamma(\cM(X))$ and let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$.
If $ \IN^\rmm_k(\cM(X))\nsubseteq \overline{\rm co}(\IN^\mu_k(X))$ for some $k\in \Nb$, then there are some $(\nu_1, \dots, \nu_k)\in \IN^\rmm_k(\cM(X))$ and some $(f_1, \dots, f_k)\in C(X)^{\oplus k}$ such that $\sum_{j\in [k]}f_j(x_j)\le 0$
for all $(x_1, \dots, x_k)\in \IN^\mu_k(X)$ and
$\sum_{j\in [k]}\nu_j(f_j)>0$.
\end{lemma}



We are ready to prove Theorem~\ref{T-measure IN main}.

\begin{proof}[Proof of Theorem~\ref{T-measure IN main}]
(1). In view of Lemma~\ref{L-Hahn Banach measure IN}, it suffices to show that given any $\onu=(\nu_1, \dots, \nu_k)\in \IN^\rmm_k(\cM(X))$ and  $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$ satisfying $\sum_{j\in [k]}\nu_j(f_j)>0$, there is an $(x_1, \dots, x_k)\in \IN^\mu_k(X)$ such that $\sum_{j\in [k]}f_j(x_j)>0$.

We take a  $C>0$ with $C\ge \|\of\|$. We set $R=\frac{1}{k}\sum_{j\in [k]} \nu_j(f_j)>0$ and $r=R/4$. Then we have $c, N>0$ and $T\subseteq \Rb^k$ given by Lemma~\ref{L-func to indep} for $k, r, \frac{R}{2}, kC$ and $p=\infty$.
By Lemma~\ref{L-measure IN func to func} we can find a
$0<\delta<1$ and a product neighborhood $U_1\times \cdots \times U_k$ of $\onu$ in $\cM(X)^k$ such that the following holds. For any $0<\eta\le 1$ and any $D\in \sB'(\mu, \eta \delta)$ there is some $D'\in \sB'(\rmm, \eta)$ so that for any independence set $F\in \cF(\Gamma)$ of $\oU=(U_1, \dots, U_k)$ relative to $D'$ and any surjective map $\psi: F\rightarrow [k]$,  there is
some $x\in X$ such that
$$\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}\left(f_j(sx){\bf 1}_{D_s}(x)-(k-1)C{\bf 1}_{X\setminus D_s}(x)\right)\ge \frac{R}{2}.$$

Since $\onu\in \IN^\rmm_k(\cM(X))$, $\oU$ has positive sequential $\rmm$-independence density. Then there are $0< \eta, c_1<1$ such that for every $M>0$ there is an $F'\in \cF(\Gamma)$ with $|F'|\ge M$ so that for every $D'\in \sB'(\rmm, \eta)$ there is an independence set $F\subseteq F'$ for $\oU$ relative to $D'$ with $|F|\ge c_1|F'|$.

Let $D\in \sB'(\mu, \eta \delta)$ and let $F'\in \cF(\Gamma)$ with $|F'|\ge \frac{2\max(N, k)}{c_1}$ such that for every $D'\in \sB'(\rmm, \eta)$ there is an independence set $F\subseteq F'$ for $\oU$ relative to $D'$ with $|F|\ge c_1|F'|$. We claim that there are some $J\subseteq F'$ with $|J|\ge \frac{cc_1}{2}|F'|$ and  some $\ot\in T$ such that $J$ is an independence set for $\oA_{\of, \ot}$ (see Notation~\ref{N-tuple}) relative to $D$.
By our choice of $\delta$ and $U_1\times \cdots \times U_k$, we can find some $D'\in \sB'(\rmm, \eta)$ such that
for any independence set $F\in \cF(\Gamma)$ of $\oU$ relative to $D'$ and any surjective map $\psi: F\rightarrow [k]$,  there is
some $x\in X$ such that
$$\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}\left(f_j(sx){\bf 1}_{D_s}(x)-(k-1)C{\bf 1}_{X\setminus D_s}(x)\right)\ge \frac{R}{2}.$$
By our assumption on $F'$ we can find an independence set $F\subseteq F'$ for $\oU$ relative to $D'$ such that $|F|$ is divisible by $k$ and
$$|F|\ge c_1|F'|-(k-1)\ge \frac{c_1}{2}|F'|\ge N.$$
For each $\psi\in \sR(F, k)$, since $|F|$ is divisible by $k$, we have $|\psi^{-1}(j)|=|F|/k$ for every $j\in [k]$. In particular, $\psi$ is surjective. Thus, 
by our choice of $D'$ we can find an $x_\psi\in X$ so that
\begin{align*}
 \frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}\left(f_j(sx_\psi){\bf 1}_{D_s}(x_\psi)-(k-1)C{\bf 1}_{X\setminus D_s}(x_\psi)\right)\ge \frac{R}{2}.
 \end{align*}
We define a function $f_\psi: F\rightarrow [-kC, kC]$ by
$$ f_\psi(s)=f_{\psi(s)}(sx_\psi){\bf 1}_{D_s}(x_\psi)-(k-1)C{\bf 1}_{X\setminus D_s}(x_\psi).$$
Then
\begin{align*}
 \frac{1}{|F|}\sum_{s\in F}f_\psi(s)&=\frac{1}{|F|}\sum_{s\in F}\left(f_{\psi(s)}(sx_\psi){\bf 1}_{D_s}(x_\psi)-(k-1)C{\bf 1}_{X\setminus D_s}(x_\psi)\right)\\
 &=\frac{1}{k}\sum_{j\in [k]}\frac{1}{|\psi^{-1}(j)|}\sum_{s\in \psi^{-1}(j)}\left(f_j(sx_\psi){\bf 1}_{D_s}(x_\psi)-(k-1)C{\bf 1}_{X\setminus D_s}(x_\psi)\right)\ge \frac{R}{2}.
 \end{align*}
By our choice of $c, N$ and $T$ we can find some $J\subseteq F$ with $|J|\ge c|F|$ and some $\ot=(t_1, \dots, t_k)\in T$  such that every map $\sigma: J\rightarrow [k]$ extends to a $\psi\in \sR(F, k)$ so that $f_\psi(s)\ge t_j$ for all $j\in [k]$ and $s\in \sigma^{-1}(j)$.
For each $j\in [k]$, taking a $\sigma: J\rightarrow [k]$ with $j\in \sigma(J)$, we have
$$t_j\le f_\psi(s)\le C$$
for all $s\in \sigma^{-1}(j)$. Let $\sigma$ and $\psi$ be as above.
If $x_\psi\in X\setminus D_\gamma$ for some $\gamma\in J$, then
\begin{align*}
r\le \frac{1}{k}\sum_{j\in [k]}t_j=\frac{1}{k}\left(t_{\sigma(\gamma)}+\sum_{j\in [k]\setminus \{\sigma(\gamma)\}}t_j\right)\le
\frac{1}{k}(f_\psi(\gamma)+(k-1)C)=0,
\end{align*}
which is impossible. Thus, $x_\psi\in \bigcap_{s\in J}D_s$. Then
$$ f_{\sigma(s)}(sx_\psi)=f_{\psi(s)}(sx_\psi)=f_\psi(s)\ge t_{\sigma(s)}$$
for all $s\in J$, and whence
$$x_\psi\in \bigcap_{s\in J}(D_s\cap s^{-1}f_{\sigma(s)}^{-1}([t_{\sigma(s)}, \infty))).$$
Therefore $J$ is an independence set for  $\oA_{\of, \ot}$ relative to $D$.
Note that
$$|J|\ge c|F|\ge \frac{cc_1}{2}|F'|.$$
This proves our claim.

Next we claim that there is some $\ot\in T$ such that $\oA_{\of, \ot}$ has positive sequential $\mu$-independence density.
We argue by contradiction. Assume that for each $\ot\in T$ the tuple $\oA_{\of, \ot}$ does not have positive sequential $\mu$-independence density.
Then there is some $M_\ot>0$ such that for any $F'\in \cF(\Gamma)$ with $|F'|\ge M_\ot$, there is some $D\in \sB'(\mu, \eta \delta/|T|)$ so that $\oA_{\of, \ot}$ has no independence sets $J\subseteq F'$ relative to $D$ with $|J|\ge \frac{cc_1}{2}|F'|$. 
We set
$$M=\max\left(\max_{\ot\in T}M_\ot, \frac{2\max(N, k)}{c_1}\right)>0.$$
By our choice of $\eta$ and $c_1$ we can find an $F'\in \cF(\Gamma)$ with $|F'|\ge M$ such that for every $D'\in \sB'(\rmm, \eta)$ there is an independence set $F\subseteq F'$ for $\oU$ relative to $D'$ with $|F|\ge c_1|F'|$. For each $\ot\in T$, since $|F'|\ge M\ge M_\ot$, there is some $D_\ot\in \sB'(\mu, \eta \delta/|T|)$ so that $\oA_{\of, \ot}$ has no independence sets $J\subseteq F'$ relative to $D_\ot$ with $|J|\ge \frac{cc_1}{2}|F'|$.
We set
$$D_s=\bigcap_{\ot\in T}(D_\ot)_s\in \sB(\mu, \eta\delta)$$
for each $s\in \Gamma$. Then $D\in \sB'(\mu, \eta\delta)$. From the above paragraph we can find some $J\subseteq F'$ with $|J|\ge \frac{cc_1}{2}|F'|$ and  some $\ot\in T$ such that $J$ is an independence set for $\oA_{\of, \ot}$ relative to $D$. Then $J$ is also an independence set for $\oA_{\of, \ot}$ relative to $D_\ot$, a contradiction to our choice of $D_\ot$. This proves our claim.

Now we can take a $\ot=(t_1, \dots, t_k)\in T$ such that $\oA_{\of, \ot}$ has positive sequential $\mu$-independence density.
By Theorem~\ref{T-measure IN basic}.\eqref{i-measure IN tuple} there is an $(x_1, \dots, x_k)\in \IN^\mu_k(X)$ with $x_j\in f_j^{-1}([t_j, \infty))$ for every $j\in [k]$.
Then
$$ \sum_{j\in [k]}f_j(x_j)\ge \sum_{j\in [k]}t_j\ge kr>0$$
as desired.

(2) is proved in the same way as Theorem~\ref{T-measure IE main}.(2), using part (1), Theorem~\ref{T-measure IN basic} and Lemma~\ref{L-ext}.
\end{proof}

\begin{remark} \label{R-measure IN not convex}
Despite the product formula for measure IN-tuples in Theorem~\ref{T-measure IN basic}.\eqref{i-measure IN product}, $\IN_k^\rmm(\cM(X))$ may fail to be convex for $\rmm\in \cM_\Gamma(\cM(X))$. Similar to the example in Remark~\ref{R-measure IE not convex}, for distinct $\mu_1, \mu_2\in \cM_\Gamma(X)$ and $0<\lambda<1$, if we set $\rmm=\lambda \delta_{\mu_1}+(1-\lambda)\delta_{\mu_2}\in \cM_\Gamma(\cM(X))$, then  it is easily checked that
$$\IN^\rmm_2(\cM(X))=\{(\mu_1, \mu_1), (\mu_2, \mu_2)\}$$
is not convex.
\end{remark}

%$\IN^\mu_2(X)\subseteq \Delta_2(X)$ 
The action $\Gamma\curvearrowright (X, \mu)$ is null if and only if 
%$\Gamma\curvearrowright (X, \mu)$ 
it has discrete spectrum, i.e., every $f\in L^2(X, \mu)$ has compact orbit closure \cite[Theorem 5.5]{KL09} \cite{Kushnirenko}. In view of Theorem~\ref{T-measure IN basic}.\eqref{i-IN pair}, from Theorem~\ref{T-measure IN main}.(1) we have the following consequence.

\begin{corollary}  \label{C-measure IN for prob}
Let $\rmm\in \cM_\Gamma(\cM(X))$ and let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$. If $\Gamma\curvearrowright (X, \mu)$ has discrete spectrum, then so does $\Gamma\curvearrowright (\cM(X), \rmm)$.
\end{corollary}

From Theorem~\ref{T-measure IN main}.(2) we have the following corollary.

\begin{corollary} \label{C-measure uniform IN}
Let $\rmm\in \cM_\Gamma(\cM(X))$ and let $\mu\in \cM_\Gamma(X)$ be the barycenter of $\rmm$. Let $k\in \Nb$. If $\IN^\rmm_k(\cM(X))=\cM(X)^k$, then $\IN^\mu_k(X)=X^k$.
\end{corollary}

The following is an analogue of Corollary~\ref{C-average}, and can be proved in the same way, using Theorems~\ref{T-measure IN main} and 
\ref{T-measure IN basic}.

\begin{corollary} \label{C-average IN}
Let $N\in \Nb$ and $\olambda\in \orP_N$. Let $\mu\in \cM_\Gamma(X)$, and set $\rmm=(\pi_\olambda)_*\mu^N\in \cM_\Gamma(\cM_\olambda(X))$ (see Notation~\ref{N-finite support2}).
For any $k\in \Nb$, $\IN^\mu_k(X)=X^k$ if and only if $\IN^\rmm_k(\cM_\olambda(X))=\cM_\olambda(X)^k$.
\end{corollary}



