\section{$\IT$-tuples of $\cM(X)$} \label{S-IT for prob}

In this section we prove Theorem~\ref{T-IT main}. Throughout this section we consider a continuous action of a countably infinite group $\Gamma$ on a compact metrizable space $X$. 








Similar to the case of IN-tuples, $\IT_k(\cM(X))$ may fail to be convex (see Section~\ref{S-example} for an example). In order to obtain an explicit description of elements of $\IT_k(\cM(X))$ like that for $\IE_k(\cM(X))$ in Theorem~\ref{T-IE main}.(3), we need to find a suitable subset of $\cM(\IT_k(X))$.  
The following is the IT version of Definition~\ref{D-IN measure}.

\begin{definition} \label{D-IT measure}
Let $k\in \Nb$. We say $\mu\in \cM(X^k)$ is an {\it $\IT$-measure} if for any $n\in \Nb$ and   any $(x_1^{(i)}, \dots, x_k^{(i)})\in \supp(\mu)$ for $i\in [n]$, one has
$$\left((x_1^{(1)}, \dots, x_1^{(n)}), (x_2^{(1)}, \dots, x_2^{(n)}), \dots, (x_k^{(1)}, \dots, x_k^{(n)})\right)\in \IT_k(X^n).$$
We denote by $\cM_\IT(X^k)$ the set of all $\IT$-measures in  $\cM(X^k)$.
\end{definition}

\begin{remark} \label{R-IT measure}
Similar to Remark~\ref{R-IN measure}, using Theorem~\ref{T-IT basic}.\eqref{i-IT subset} one sees that in Definition~\ref{D-IT measure} we obtain the same definition no matter we require the points $(x_1^{(i)}, \dots, x_k^{(i)})\in \supp(\mu)$ for $i\in [n]$ to be distinct or not. 
\end{remark}


The following is an analogue of Proposition~\ref{P-IN measure basic}, and can be proved in the same way using Theorem~\ref{T-IT basic}.\eqref{i-IT invariant}.


\begin{proposition} \label{P-IT measure basic}
For each $k\in \Nb$, $\cM_\IT(X^k)$ is a $\Gamma$-invariant closed subset of $\cM(\IT_k(X))$.
\end{proposition}

For $k, n\in \Nb$, we set
$$\cM_{\IT, n}(X^k)=\cM_\IT(X^k)\cap \cM_n(X^k)$$
to be the set of $\mu\in \cM_\IN(X^k)$ with $|\supp(\mu)|\le n$, and  set (see Notation~\ref{N-finite support2})
$$\cB_{k, n}=\bigcup_{\olambda\in \orP_n}(\pi_\olambda\times \cdots \times \pi_\olambda)(\IT_k(X^n))\subseteq  \cM_n(X)^k.$$
In order to prove part (3) of Theorem~\ref{T-IT main}, as in Section~\ref{S-IN for prob}, we shall show that both $\{(\mu^{(1)}, \dots, \mu^{(k)}): \mu\in \cM_\IT(X^k)\}$
and $\IT_k(\cM(X))$ are equal to $\overline{\bigcup_{n\in \Nb}\cB_{k, n}}$ in Lemmas~\ref{L-IT closure vs push} and \ref{L-IT dense} respectively. 

The following is an analogue of Lemma~\ref{L-IN finite support}, and can be proved in the same way using 
Remark~\ref{R-IT measure}.

\begin{lemma} \label{L-IT finite support}
For any $k, n\in \Nb$, we have
$$\cB_{k, n}=\{(\mu^{(1)}, \dots, \mu^{(k)})\in \cM(X)^k: \mu\in \cM_{\IT, n}(X^k)\}.$$
\end{lemma}




The following is an analogue of Lemma~\ref{L-IN convex}, and can be proved in the same way using 
Theorem~\ref{T-IT basic}.

\begin{lemma} \label{L-IT convex}
We have $\cB_{k, n}\subseteq \IT_k(\cM_n(X))$ for all $k, n\in \Nb$.
\end{lemma}



The following is an analogue of Lemma~\ref{L-IN closure vs push}, and can be proved in the same way using Proposition~\ref{P-IT measure basic} and Lemma~\ref{L-IT finite support}. 

\begin{lemma} \label{L-IT closure vs push}
Let $k\in \Nb$. Then
$$\overline{\bigcup_{n\in \Nb}\cB_{k, n}}=\{(\mu^{(1)}, \dots, \mu^{(k)})\in \cM(X)^k: \mu\in \cM_\IT(X^k)\}.$$
\end{lemma}

To prove Lemma~\ref{L-IT dense}, we need Lemma~\ref{L-func to infinite}, which is an analogue of Lemma~\ref{L-func to density}. While Lemma~\ref{L-func to density} is based on Lemma~\ref{L-func to indep}, the combinatorial fact behind Lemma~\ref{L-func to infinite} is the following 
dichotomy of Rosenthal \cite[Theorem 8.4]{KL16}, which is the  $k$-tuple version  of   \cite[Theorem 2]{Rosenthal74}.
For $k\in \Nb$ and a set $Y$, we say that a family $\{(A_{i, 1}, \dots, A_{i, k}): i\in F\}$ of $k$-tuples of subsets of $Y$ is {\it independent} if 
$$\bigcap_{i\in J} A_{i, \sigma(i)}\neq \emptyset$$
for every nonempty finite set $J\subseteq F$ and every map $\sigma: J\rightarrow [k]$. 

\begin{lemma} \label{L-IT combinatorial}
Let $k\in \Nb$ and let $\{(A_{n, 1}, \dots, A_{n, k})\}_{n\in \Nb}$ be a sequence of $k$-tuples of subsets of a set $Y$. Then there is an infinite set $F\subseteq \Nb$ such that either $\{(A_{n, 1}, \dots, A_{n, k}): n\in F\}$ is independent  or for every $y\in Y$ there exists a $j\in [k]$ such that the set $\{n\in F: y\in A_{n, j}\}$ is finite.
\end{lemma}

We also need the following result of Bergelson \cite[Theorem 1.1]{Bergelson85}. In \cite[Theorem 1.1]{Bergelson85} it is assumed that $\nu(A_n)=\delta$ for all $n\in \Nb$, but the proof works when $\nu(A_n)\ge \delta$ for all $n\in \Nb$.

\begin{lemma} \label{L-finite intersection}
Let $(Y, \sB, \nu)$ be a probability measure space, $\delta>0$, and $A_n\in \sB$ with $\nu(A_n)\ge \delta$ for each $n\in \Nb$. Then there is an infinite set $F\subseteq \Nb$ such that $\nu\left(\bigcap_{n\in J}A_n\right)>0$ for every nonempty finite set $J\subseteq F$.
\end{lemma}


\begin{lemma} \label{L-func to infinite}
Let $k\in \Nb$, $\omu=(\mu_1, \dots, \mu_k)\in \cM(X)^k$ and $\of=(f_1, \dots, f_k)\in C(X)^{\oplus k}$ such that $R:=\frac{1}{k}\sum_{j\in [k]}\mu_j(f_j)>0$.  Let $0<r<R$ and $C\ge \|\of\|$. Then there are some  finite set $T\subseteq \Rb^k$ depending only on $k, r, R$ and $C$,  and some product neighborhood $U_1\times \cdots \times U_k$ of $\omu$ in $\cM(X)^k$ such that the following hold:
\begin{enumerate}
\item $\frac{1}{k}\sum_{j\in [k]}t_j\ge r$ for every $(t_1, \dots, t_k)\in T$, and
\item for any infinite independence set $F\subseteq \Gamma$ of $(U_1, \dots, U_k)$, there are some infinite set $J\subseteq F$ and some $\ot\in T$ so that $J$ is an independence set for $\oA_{\of, \ot}$ (see Notation~\ref{N-tuple}).
    \end{enumerate}
\end{lemma}
\begin{proof} We take an $M\in \Nb$ such that
$$\frac{C}{M}< \frac{R-r}{2}.$$
We denote by $I$ the set of $\boldsymbol{i}=(i_1, \dots, i_k)\in [2M]^k$ satisfying
$$\frac{1}{k}\sum_{j\in [k]}\left(-C+\frac{(i_j-1)C}{M}\right)\ge r.$$
When $i_j=2M$ for all $j\in [k]$, we have
$$ \frac{1}{k}\sum_{j\in [k]}\left(-C+\frac{(i_j-1)C}{M}\right)=-C+\frac{(2M-1)C}{M}=C-\frac{C}{M}>R-\frac{R-r}{2}>r.$$
Thus $(2M, \dots, 2M)\in I$, whence $I$ is nonempty. We denote by $T$ the set of
$$\left(-C+\frac{(i_1-1)C}{M}, \dots, -C+\frac{(i_k-1)C}{M}\right)\in [-C, C]^k$$
for $\boldsymbol{i}=(i_1, \dots, i_k)\in I$. Then $\frac{1}{k}\sum_{j\in [k]}t_j\ge r$ for every $(t_1, \dots, t_k)\in T$.

For each $j\in [k]$, we denote by $U_j$ the set of $\nu\in \cM(X)$ satisfying
$$ \nu(f_j)\ge \mu_j(f_j)-(R-r)/4.$$
This is a closed neighborhood of $\mu_j$ in $\cM(X)$.

We shall show that $T$ and $U_1\times \cdots \times U_k$ have the desired property. We have checked that the condition (1) holds. 
Thus it suffices to check the condition (2). 

Let $F\subseteq \Gamma$ be an infinite independence set for $\oU=(U_1, \dots, U_k)$. We argue by contradiction. Assume that for each $\ot\in T$ the tuple $\oA_{\of, \ot}$ has no infinite independence set $J\subseteq F$.
We list the elements of $T$ as
$$\ot^{(1)}=(t_1^{(1)}, \dots, t_k^{(1)}), \dots, \ot^{(|T|)}=(t_1^{(|T|)}, \dots, t_k^{(|T|)}).$$
We set $F_0=F$. Via induction on $l=1, \dots, |T|$,  by Lemma~\ref{L-IT combinatorial} we can find an infinite set $F_l\subseteq F_{l-1}$ such that for every $x\in X$ there exists a $j_{l, x}\in [k]$ such that the set $\{s\in F_l: x\in s^{-1}f_{j_{l, x}}^{-1}([t_{j_{l, x}}^{(l)}, \infty))\}$ is finite.


Since $F_{|T|}$ is infinite, we can find an injective map $\psi_j: \Nb\rightarrow F_{|T|}$ for each $j\in [k]$ such that the sets $\psi_j(\Nb)$ for $j\in [k]$ are pairwise disjoint. Since $F$ is an independence set for $\oU$ and $\oU$ is a tuple of compact sets, we can find a
$$\nu\in \bigcap_{n\in \Nb}\bigcap_{j\in [k]}\psi_j(n)^{-1}U_j.$$

Let $n\in \Nb$. We set
$$ X_{n, \ot}=\bigcap_{j\in [k]}\psi_j(n)^{-1}f_j^{-1}([t_j, \infty))$$
for every $\ot=(t_1, \dots, t_k)\in T$, and set
$$ X_n=\bigcup_{\ot\in T}X_{n, \ot}, \mbox{ and }  X_n'=\left\{x\in X: \frac{1}{k}\sum_{j\in [k]}f_j(\psi_j(n)x)\ge \frac{R+r}{2}\right\}.$$
Note that
\begin{align*}
\int_X \frac{1}{k}\sum_{j\in [k]}f_j(\psi_j(n)x)\, d\nu(x)&=\frac{1}{k}\sum_{j\in [k]} (\psi_j(n) \nu)(f_j)\\
&\ge \frac{1}{k}\sum_{j\in [k]}(\mu_j(f_j)-(R-r)/4)=\frac{3R+r}{4},
\end{align*}
and
\begin{align*}
\int_X \frac{1}{k}\sum_{j\in [k]}f_j(\psi_j(n)x)\, d\nu(x)&\le \nu(X_n')C+\nu(X\setminus X_n')\frac{R+r}{2}\\
&=\nu(X_n')(C-\frac{R+r}{2})+\frac{R+r}{2}.
\end{align*}
Thus
$$\frac{3R+r}{4}\le \nu(X_n')(C-\frac{R+r}{2})+\frac{R+r}{2},$$
whence
$$ \nu(X_n')\ge \frac{R-r}{4C-2R-2r}.$$
Let $x\in X_n'$. For each $j\in [k]$
we can find an $i_j\in [2M]$ so that
$$-C+\frac{(i_j-1)C}{M}\le f_j(\psi_j(n)x)\le -C+\frac{i_j C}{M}.$$
We set $t_j=-C+\frac{(i_j-1)C}{M}$ for each $j\in [k]$.
Note that
\begin{align*}
\frac{R+r}{2}\le \frac{1}{k}\sum_{j\in [k]}f_j(\psi_j(n)x)\le \frac{1}{k}\sum_{j\in [k]}\left(t_j+\frac{C}{M}\right),
\end{align*}
whence
$$ \frac{1}{k}\sum_{j\in [k]}t_j\ge \frac{R+r}{2}-\frac{C}{M}\ge r,$$
which means that $(i_1, \dots, i_j)$ lies in $I$ and $\ot:=(t_1, \dots, t_k)$ lies in $T$. We have $x\in X_{n, \ot}\subseteq X_n$, and hence $X_n'\subseteq X_n$.  Thus
$$\nu(X_n)\ge \nu(X_n')\ge \frac{R-r}{4C-2R-2r}.$$
Then there is some $\ot^{\{n\}}\in T$ such that
$$ \nu(X_{n, \ot^{\{n\}}})\ge \frac{R-r}{(4C-2R-2r)|T|}=:\delta.$$

We can find some $l\in [|T|]$ and some infinite set $W\subseteq \Nb$ such that $\ot^{\{n\}}=\ot^{(l)}$ for all $n\in W$. By Lemma~\ref{L-finite intersection} there is some infinite set $W'\subseteq W$ such that 
$$\nu\left(\bigcap_{n\in W''}X_{n, \ot^{(l)}}\right)=\nu\left(\bigcap_{n\in W''}X_{n, \ot^{\{n\}}}\right)>0$$ 
for every nonempty finite set $W''\subseteq W'$. In particular, $\bigcap_{n\in W''}X_{n, \ot^{(l)}}\neq \emptyset$ for every nonempty finite set $W''\subseteq W'$. Since $X_{n, \ot^{(l)}}$ is compact for each $n\in \Nb$, it follows that $\bigcap_{n\in W'}X_{n, \ot^{(l)}}\neq \emptyset$. Then we can find an $x\in \bigcap_{n\in W'}X_{n, \ot^{(l)}}$. For each $j\in [k]$,
$$\{s\in F_l: x\in s^{-1}f_j^{-1}([t_j^{(l)}, \infty))\}\supseteq \psi_j(W')$$
is infinite, a contradiction to our choice of $F_l$. Therefore, $\oA_{\of, \ot}$ for some $\ot\in T$ has an infinite independence set $J\subseteq F$.
\end{proof}

The following is an analogue of Lemma~\ref{L-IN simul}, and can be proved in the same way using Lemma~\ref{L-func to infinite}.

\begin{lemma} \label{L-IT simul}
Let $k, n\in \Nb$, $\omu=(\mu_1, \dots, \mu_k)\in \cM(X)^k$  and $\of^{(l)}=(f_1^{(l)}, \dots, f_k^{(l)})\in C(X)^{\oplus k}$ for $l\in [n]$ such that $R^{(l)}:=\frac{1}{k}\sum_{j\in [k]}\mu_j(f_j^{(l)})>0$ for each $l\in [n]$. 
%Let $C>0$ with $C\ge \max_{l\in [n]}\|\of^{(l)}\|_\infty$ and  
Let $0<r^{(l)}<R^{(l)}$ for each $l\in [n]$.  Then there are some finite set $T^{(l)}\subseteq \Rb^k$ for each $l\in [n]$,
 and some product neighborhood $U_1\times \cdots \times U_k$ of $\omu$ in $\cM(X)^k$ such that the following hold:
  \begin{enumerate}
  \item $\frac{1}{k}\sum_{j\in [k]}t_j\ge r^{(l)}$ for every $l\in [n]$ and $(t_1, \dots, t_k)\in T^{(l)}$, and
  \item for any infinite independence set $F\subseteq \Gamma$ of $(U_1, \dots, U_k)$,
 there are  some infinite set $J\subseteq F$ and some $\ot^{(l)}=(t_1^{(l)}, \dots, t_k^{(l)})\in T^{(l)}$ for each $l\in [n]$ so that
 $J$ is an independence set for the $k$-tuple
 \begin{align*}
 \Big(\prod_{l\in [n]} (f_1^{(l)})^{-1}([t_1^{(l)}, \infty)), \dots, \prod_{l\in [n]} (f_k^{(l)})^{-1}([t_k^{(l)}, \infty))\Big)
  \end{align*}
  of subsets of $X^n$.
  \end{enumerate}
 \end{lemma}


The following lemma is proved in the same way as Lemma~\ref{L-IN dense}, using Theorem~\ref{T-IT basic} and Lemmas~\ref{L-IT convex},
\ref{L-convex intersection} and \ref{L-IT simul}.


\begin{lemma} \label{L-IT dense}
Let $k\in \Nb$. Then $\IT_k(\cM(X))=\overline{\bigcup_{n\in \Nb}\cB_{k, n}}$.
\end{lemma}


Now Theorem~\ref{T-IT main} can be proved in the same way as Theorem~\ref{T-IN main}, using Theorem~\ref{T-IT basic} and Lemmas~\ref{L-IT dense} and \ref{L-IT closure vs push}.





The following is an analogue of Corollary~\ref{C-IN finite support} with essentially the same proof, using Theorem~\ref{T-IT main} and Lemmas~\ref{L-IT finite support} and \ref{L-IT convex}.

\begin{corollary} \label{C-IT finite support}
Let $k\in \Nb$.
Then for any $N_1, \dots, N_k\in \Nb$, setting $N=\prod_{j\in [k]}N_j$, one has
$$ (\cM_{N_1}(X)\times \cdots \times \cM_{N_k}(X))\cap \IT_k(\cM(X))\subseteq \IT_k(\cM_N(X)).$$
\end{corollary}



In view of parts (3) and (5) of Theorem~\ref{T-IT basic}, from the case $k=2$ of parts (1) and (2) of Theorem~\ref{T-IT main} we obtain immediately the following result, which also follows from \cite[Proposition 6.6]{KL07}.

\begin{corollary} \label{C-IT for prob}
$\Gamma\curvearrowright X$ is tame if and only if $\Gamma\curvearrowright \cM(X)$ is tame.
\end{corollary}

For $k\in \Nb$, we say $\Gamma\curvearrowright X$ is {\it uniformly untame of order $k$} if $\IT_k(X)=X^k$ \cite[page 897]{KL07}. In view of Theorem~\ref{T-IT basic}.\eqref{i-IT subset}, from Theorem~\ref{T-IT main}.(2) we have the following corollary.

\begin{corollary} \label{C-IT order k}
Let  $k, N\in \Nb$ and $\olambda\in \orP_N$. If $\Gamma\curvearrowright \cM_\olambda(X)$ or $\Gamma\curvearrowright \cM(X)$ is uniformly untame of order $k$, then so is $\Gamma\curvearrowright X$.
\end{corollary}

