\section{Non-convexity of $\IN$ and $\IT$-tuples} \label{S-example}

In this section we construct a minimal subshift of $\Gamma=\Zb$ such that neither $\IN_2(\cM(X))$ nor $\IT_2(\cM(X))$ is convex.

We first use Theorem~\ref{T-IN main} to deduce a sufficient condition for certain pairs in $\cM_2(X)$ to fail to be in $\IN_2(\cM(X))$.

\begin{lemma} \label{L-not IN}
Let a countably infinite group $\Gamma$ act on a compact metrizable space $X$ continuously. Let $(x_1, x_2)$ and $(x_3, x_4)$ be distinct elements in $X^2$ such that $(x_1, x_4), (x_2, x_3)\not\in \IN_2(X)$ and $((x_1, x_3), (x_2, x_4))\not\in \IN_2(X^2)$. Then for each $0<\lambda<1$,
$$(\lambda \delta_{x_1}+(1-\lambda)\delta_{x_3},  \lambda \delta_{x_2}+(1-\lambda)\delta_{x_4})\not\in \IN_2(\cM(X)).$$
\end{lemma}
\begin{proof} We argue by contradiction. Assume that $(\lambda \delta_{x_1}+(1-\lambda)\delta_{x_3},  \lambda \delta_{x_2}+(1-\lambda)\delta_{x_4})\in \IN_2(\cM(X))$ for some $0<\lambda<1$. By Theorem~\ref{T-IN main}.(3) there is some $\mu\in \cM_\IN(X^2)$ such that
\begin{align} \label{E-not IN}
 \mu^{(1)}=\lambda \delta_{x_1}+(1-\lambda)\delta_{x_3} \quad \text{ and } \quad \mu^{(2)}=\lambda \delta_{x_2}+(1-\lambda)\delta_{x_4}.
\end{align}
Then
\begin{align*}
\supp(\mu)\subseteq \{x_1, x_3\}\times \{x_2, x_4\}=\{(x_1, x_2), (x_1, x_4), (x_3, x_2), (x_3, x_4)\}.
\end{align*}
Since $\mu\in \cM_\IN(X^2)$ and $(x_1, x_4), (x_3, x_2)\not\in \IN_2(X)$, we must have
$$ \supp(\mu)\subseteq \{(x_1, x_2),  (x_3, x_4)\}. $$
Using $\mu\in \cM_\IN(X^2)$ again and $((x_1, x_3), (x_2, x_4))\not\in \IN_2(X^2)$, we see that $\supp(\mu)$ cannot be equal to $\{(x_1, x_2),  (x_3, x_4)\}$. Therefore $\supp(\mu)$ is equal to either $\{(x_1, x_2)\}$ or $\{(x_3, x_4)\}$, i.e., $\mu$ is equal to either $\delta_{(x_1, x_2)}$ or
$\delta_{(x_3, x_4)}$. From \eqref{E-not IN} we conclude that $(x_1, x_2)=(x_3, x_4)$, a contradiction to the assumption that $(x_1, x_2)$ and $(x_3, x_4)$ are distinct.
\end{proof}

Let $m\in \Nb$. An element $x\in \Omega_m:=\{0, 1, \dots, m-1\}^\Zb$ is called a {\it Toeplitz sequence} if for each $j\in \Zb$ there is an $n\in \Nb$ such that $x(j+tn)=x(j)$ for all $t\in \Zb$. We endow $\Omega_m$ with the shift $\Zb$-action given by $(Tx)(s)=x(s+1)$ for all $s\in \Zb$. The subshift generated by $x$, i.e., the restriction of the shift action to the orbit closure of $x$,  is called a {\it Toeplitz subshift} \cite{JK}.  Note that every Toeplitz subshift is minimal \cite[Theorem 4]{JK}.



We set $m=5$. We choose an increasing sequence $n_1<n_2<\cdots$ in $\Nb$ with $n_p|n_{p+1}$ for each $p\in \Nb$ and $2^{p+2}$ distinct elements $y_{p, 1}, y_{p, 2}, \dots, y_{p, 2^{p+1}}, y'_{p, 1}, \dots, y'_{p, 2^{p+1}}$ in $\Zb/n_p\Zb$ for each $p\in \Nb$ with the following properties.
\begin{enumerate}[label=(\roman*)]
\item $y_{p+1, 2q-1}\equiv y_{p+1, 2q}\equiv y'_{p+1, 2q-1}\equiv y'_{p+1, 2q}\equiv y'_{p, q} \mod n_p$ for all $p\in \Nb$ and all $q\in [2^{p+1}]$.
\item For each $p\in \Nb$ there are $z_p, u_p\in \Zb/n_p\Zb$ such that $y'_{p, q}=y_{p, q}+z_p$ for all $q\in [2^p]$ and $y'_{p, q}=y_{p, q}+u_p$ for all $q\in [2^{p+1}]\setminus [2^p]$.
%\item There does not exist any $z\in \Zb$ with $z+n_p\Zb \in \{y'_{p, q}: 1\le q\le 2^{p+1}\}$ for all $p\in \Nb$.
\item For each $p\in \Nb$ and any $v_1, v_2, v_3\in V_p:=\bigcup_{q\in [2^p]}\{y_{p, q}, y'_{p, q}\}$ and any $w\in W_p:=\bigcup_{q\in [2^{p+1}]\setminus [2^p]}\{y_{p, q}, y'_{p, q}\}$ we have $v_1-v_2\neq v_3-w$.
\item For each $p\in \Nb$ and any distinct $v_1, v_2\in V_p$ and any $w_1, w_2\in W_p$, we have $v_1-v_2\neq w_1-w_2$.
\item There does not exist any $z\in \Zb$ such that $z+n_p\Zb \in \{y'_{p, q}: q\in [2^{p+1}]\}$ for all $p\in \Nb$.
\end{enumerate}
To see that such $n_p$ and $y_{p, q}, y'_{p, q}$ exist, we shall construct them inductively on $p$ to satisfy the above properties (i)-(iv) and (v') below which is stronger than (v):
\begin{enumerate}
\item[(v')] For each $p\in \Nb$, none of $t+n_p\Zb$ for $t=-p, -p+1, \dots, 0, \dots, p-1, p$ lies in $\{y'_{p, q}: q\in [2^{p+1}]\}$.
\end{enumerate}

To start, for $p=1$, we take integers $1<\tilde{y}_{1, 1}<\tilde{y}_{1, 2}$ first, then take an integer $\tilde{z}_1>\tilde{y}_{1, 2}$ and set $\tilde{y}'_{1, q}=\tilde{y}_{1, q}+\tilde{z}_1$ for $q\in [2]$. Next we take integers $2\tilde{y}'_{1, 2}<\tilde{y}_{1, 3}<\tilde{y}_{1, 4}$ such that
$\tilde{y}_{1, 4}-\tilde{y}_{1, 3}>\tilde{y}'_{1, 2}$, and take an integer $\tilde{u}_1>\tilde{y}_{1, 4}$ and set $\tilde{y}'_{1, q}=\tilde{y}_{1, q}+\tilde{u}_1$ for $q\in [4]\setminus [2]$. Finally, we take an integer $n_1>\tilde{y}'_{1, 4}+\tilde{y}'_{1, 2}+1$, and set
$$y_{1, q}=\tilde{y}_{1, q}+n_1\Zb \quad \mbox{ and }  \quad y'_{1, q}=\tilde{y}'_{1, q}+n_1\Zb \quad \mbox{ for all } q\in [2^2],$$
and 
$$z_1=\tilde{z}_1+n_1\Zb \quad \mbox{ and } \quad u_1=\tilde{u}_1+n_1\Zb. $$
Then (ii)-(iv) and (v') hold for $p=1$. 

Assume that we have constructed $n_1<n_2<\dots <n_j$ satisfying $n_p|n_{p+1}$ for all $1\le p<j$ and distinct $y_{p, q}, y'_{p, q}\in \Zb/n_p\Zb$ for $p\in [j]$ and $q\in [2^{p+1}]$ satisfying (i) for $1\le p<j$ and (ii)-(iv) and (v') for $p\in [j]$. We take integers $j+1<\tilde{y}_{j+1, 1}<\dots <\tilde{y}_{j+1, 2^{j+1}}$ first such that
$$\tilde{y}_{j+1, 2q-1}\equiv \tilde{y}_{j+1, 2q}\equiv y'_{j, q} \mod n_j\Zb$$
for all $q\in [2^j]$, then take an integer $\tilde{z}_{j+1}\in n_j\Zb$ satisfying $\tilde{z}_{j+1}>\tilde{y}_{j+1, 2^{j+1}}$ and set $\tilde{y}'_{j+1, q}=\tilde{y}_{j+1, q}+\tilde{z}_{j+1}$ for all $q\in [2^{j+1}]$. Next we take integers $2\tilde{y}'_{j+1, 2^{j+1}}<\tilde{y}_{j+1, 2^{j+1}+1}<\dots<\tilde{y}_{j+1, 2^{j+2}}$ such that
$\tilde{y}_{j+1, q+1}-\tilde{y}_{j+1, q}>\tilde{y}'_{j+1, 2^{j+1}}$ for all $2^{j+1}<q< 2^{j+2}$ and
$$\tilde{y}_{j+1, 2q-1}\equiv \tilde{y}_{j+1, 2q}\equiv y'_{j, q} \mod n_j\Zb$$
for all $q\in [2^{j+1}]\setminus [2^{j}]$, and take an integer $\tilde{u}_{j+1}\in n_j\Zb$ with $\tilde{u}_{j+1}>\tilde{y}_{j+1, 2^{j+2}}$ and set $\tilde{y}'_{j+1, q}=\tilde{y}_{j+1, q}+\tilde{u}_{j+1}$ for $q\in [2^{j+2}]\setminus [2^{j+1}]$. Finally, we take an integer $n_{j+1}\in n_j\Zb$ such that $n_{j+1}>\tilde{y}'_{j+1, 2^{j+2}}+\tilde{y}'_{j+1, 2^{j+1}}+j+1+n_j$, and set
\begin{align*}
y_{j+1, q}=\tilde{y}_{j+1, q}+n_{j+1}\Zb \quad \mbox{ and }  \quad y'_{j+1, q}=\tilde{y}'_{j+1, q}+n_{j+1}\Zb \quad \mbox{ for all } q\in [2^{j+2}],
\end{align*}
and
\begin{align*}
z_{j+1}=\tilde{z}_{j+1}+n_{j+1}\Zb \quad \mbox{ and } \quad u_{j+1}=\tilde{u}_{j+1}+n_{j+1}\Zb.
\end{align*}
Then (i) holds for all $p\in [j]$ and (ii)-(iv) and (v') hold for all $p\in [j+1]$. This finishes the induction step and gives us the $n_p$ and $y_{p, q}, y'_{p, q}$ as desired.


We define a map $h: \bigcup_{p\in \Nb}\{y_{p, q}: q\in [2^{p+1}]\}\rightarrow [4]$ by
\begin{align*}
h(y_{p, q})=\begin{cases}
1, & \quad \text{if } q\le 2^p \text{ and is odd,}\\
2, & \quad \text{if } q\le 2^p \text{ and is even,}\\
3, & \quad \text{if } q> 2^p \text{ and is odd,}\\
4, & \quad \text{if } q> 2^p \text{ and is even.}
\end{cases}
\end{align*}
Now we define an $x\in \Omega_5$ by
\begin{align*}
x(s)=\begin{cases}
h(y_{p, q}),  & \quad \text{if } s\equiv y_{p, q} \mod n_p \text{ for some } p\in \Nb \text{ and some } q\in  [2^{p+1}],\\
0 & \quad \text{ otherwise.}
\end{cases}
\end{align*}

\begin{lemma} \label{L-Toplitz}
The element $x$ is well defined and Toeplitz.
\end{lemma}
\begin{proof} From Property (i) it is clear that if $s\in \Zb$, $p_i\in \Nb$ and $q_i\in [2^{p_i+1}]$ for $i=1, 2$ such that
$s\equiv y_{p_i, q_i} \mod n_{p_i}$ for $i=1, 2$, then $p_1=p_2$ and $q_1=q_2$. Thus $x$ is well defined.

Let $s\in \Zb$ such that $x(s)\in [4]$. Then
$$s \equiv y_{p, q} \mod n_p$$
for some $p\in \Nb$ and $q\in [2^{p+1}]$. For any $t\in \Zb$, we have
$$s+tn_p \equiv s \equiv y_{p, q} \mod n_p,$$
whence $x(s+tn_p)=h(y_{p, q})=x(s)$.

Let $s\in \Zb$ such that $x(s)=0$. By Property (v) we can find some $p\in \Nb$ such that $s+n_p\Zb\not\in \{y'_{p, q}: q\in  [2^{p+1}]\}$. Let $t\in \Zb$. We claim that $s+tn_p \not\equiv y_{p', q'} \mod n_{p'}$ for all $p'\in \Nb$ and $q'\in [2^{p'+1}]$. Indeed, for any $p'>p$ and any $q'\in [2^{p'+1}]$, by Property (i) we have $y_{p', q'}\equiv y'_{p, q} \mod n_p$ for some $q\in [2^{p+1}]$, whence
$$s+tn_p\equiv s\not\equiv y_{p', q'} \mod n_p,$$
which implies that $s+tn_p \not\equiv y_{p', q'} \mod n_{p'}$. If $s+tn_p\equiv y_{p', q'} \mod n_{p'}$ for some $p'\le p$ and $q'\in [2^{p'+1}]$, then
$$ s\equiv s+t n_p\equiv y_{p', q'} \mod n_{p'},$$
and hence $x(s)=h(y_{p', q'})\in [4]$, which is impossible. This proves our claim. Then $x(s+tn_p)=0=x(s)$.

Now we conclude that $x$ is Toeplitz.
\end{proof}

We denote by $X$ the orbit closure of $x$ under the shift action. We shall show that neither $\IN_2(\cM(X))$ nor $\IT_2(\cM(X))$ is convex. 


\begin{lemma} \label{L-difference}
For any $p\in \Nb$ and $q_1, q_2\in [2^p]$ or $q_1, q_2\in [2^{p+1}]\setminus [2^p]$, we have
$$y_{p+1, 2q_1-1}-y_{p+1, 2q_2-1}\equiv y_{p, q_1}-y_{p, q_2} \mod n_p.$$
\end{lemma}
\begin{proof}  Using Properties (i) and (ii) we have
\begin{displaymath}
y_{p+1, 2q_1-1}-y_{p+1, 2q_2-1}\equiv y'_{p, q_1}-y'_{p, q_2}\equiv y_{p, q_1}-y_{p, q_2} \mod n_p. \tag*{\qedsymbol}
\end{displaymath}
     \renewcommand{\qedsymbol}{}
     \vspace{-\baselineskip}
\end{proof}

\begin{lemma} \label{L-realize map}
The following hold:
\begin{enumerate}
\item For any $p\in \Nb$ and any map $\sigma: [p]\rightarrow [2]$ there are some $q_i\in [2^i]$ for each $i\in [p]$ such that $q_{i+1}\in \{2q_i-1, 2q_i\}$ for each $1\le i<p$ and $h(y_{i, q_i})=\sigma(i)$ for all $i\in [p]$.
\item For any $p\in \Nb$ and any map $\sigma: [p]\rightarrow \{3, 4\}$ there are some $q_i\in [2^{i+1}]\setminus [2^i]$ for each $i\in [p]$ such that $q_{i+1}\in \{2q_i-1, 2q_i\}$ for each $1\le i<p$ and $h(y_{i, q_i})=\sigma(i)$ for all $i\in [p]$.
\end{enumerate}
\end{lemma}
\begin{proof} We prove (1) by induction on $p$. The case $p=1$ is trivial. Assume that the assertion holds for $p=l$. Let $\sigma: [l+1]\rightarrow [2]$. By the inductive assumption there are some $q_i\in [2^i]$ for each $i\in [l]$ such that $q_{i+1}\in \{2q_i-1, 2q_i\}$ for each $1\le i<l$ and $h(y_{i, q_i})=\sigma(i)$ for all $i\in [l]$.
If $\sigma(l+1)=1$, setting $q_{l+1}=2q_l-1$ we have $q_{l+1}\in [2^{l+1}]$,
and
$$h(y_{l+1, q_{l+1}})=1=\sigma(l+1).$$
If $\sigma(l+1)=2$, setting $q_{l+1}=2q_l$ we have $q_{l+1}\in [2^{l+1}]$,
and
$$h(y_{l+1, q_{l+1}})=2=\sigma(l+1).$$
This finishes the induction step and proves (1). The proof for (2) is similar.
\end{proof}

For each $j\in [4]$ we denote by $A_j$ the set of elements in $X$ taking value $j$ at $0$. This is a clopen subset of $X$. For each $p\in \Nb$ we take $a_p, b_p\in \Zb$ such that
$$y_{p, 1}=a_p+ n_p\Zb \quad  \mbox{ and } \quad y_{p, 2^p+1}=b_p+n_p\Zb.$$

\begin{lemma} \label{L-example IT}
The set $\{a_p: p\in \Nb\}$ is an independence set for the pair $(A_1, A_2)$, and the set $\{b_p: p\in \Nb\}$ is an independence set for the pair $(A_3, A_4)$.
\end{lemma}
\begin{proof} We prove the first assertion. The proof for the second assertion is similar.

It suffices to show that $\{a_1, \dots, a_p\}$ is an independence set for the pair $(A_1, A_2)$ for every $p\in \Nb$. Let $\sigma: [p]\rightarrow [2]$. By Lemma~\ref{L-realize map} we can find some $q_i\in [2^i]$ for each $i\in [p]$ such that $q_{i+1}\in \{2q_i-1, 2q_i\}$ for each $1\le i<p$ and $h(y_{i, q_i})=\sigma(i)$ for all $i\in [p]$. We take an $a\in \Zb$ such that 
$$a\equiv a_p-y_{p, q_p}\mod n_p.$$ 
If $1\le i<p$, by Property (i) and Lemma~\ref{L-difference} we have
$$  a_{i+1}-y_{i+1, q_{i+1}}\equiv  y_{i+1, 1}-y_{i+1, 2q_i-1}\equiv y_{i, 1}-y_{i, q_i}\equiv a_i-y_{i, q_i}\mod n_i.$$
Taking $i=p-1$ we get
$$ a\equiv a_{p}-y_{p, q_{p}} \equiv a_{p-1}-y_{p-1, p_{p-1}} \mod n_{p-1}.$$
Taking $i=p-2$ we get
$$ a \equiv a_{p-1}-y_{p-1, q_{p-1}} \equiv a_{p-2}-y_{p-2, p_{p-2}} \mod n_{p-2}.$$
Going on this way, we get
$$ a \equiv a_i-y_{i, q_i} \mod n_i$$
for all $i\in [p]$. Equivalently,
$$ a_i-a \equiv y_{i, q_i} \mod n_i$$
for all $i\in [p]$. 
Then
$$(T^{a_i-a}x)(0)=x(a_i-a)=h(y_{i, q_i})=\sigma(i)$$
for all $i\in [p]$, i.e., $T^{-a} x\in \bigcap_{i\in [p]}T^{-a_i}A_{\sigma(i)}$. Therefore $\{a_1, \dots, a_p\}$ is an independence set for the pair $(A_1, A_2)$.
\end{proof}

For each $s\in \Zb$ with $x(s)\in [4]$, let $P(s)$ and $Q(s)$ denote the unique positive integers such that $1\le Q(s)\le 2^{P(s)+1}$ and $s\equiv y_{P(s), Q(s)} \mod n_{P(s)}$. The uniqueness of such $P(s)$ and $Q(s)$ is shown in the proof of Lemma~\ref{L-Toplitz}. 

\begin{lemma} \label{L-not IN1}
Let $i\in \{1, 2\}$ and $j\in \{3, 4\}$. Then each independence set for the pair $(A_i, A_j)$ has cardinality at most $1$.
\end{lemma}
\begin{proof} We argue by contradiction. Assume that $\{s_1, s_2\}$ is an independence set for $(A_i, A_j)$ for some distinct $s_1, s_2\in \Zb$. Then we can find some $z, z'\in X$ such that
$$z\in T^{-s_1}A_i\cap T^{-s_2}A_i \quad \text{ and } \quad z'\in T^{-s_1}A_i \cap T^{-s_2}A_j.$$ 
We may find $a, b\in \Zb$ so that $T^{a}x$ and $T^{b}x$ are close enough to $z$ and $z'$ respectively such that
$$T^ax\in T^{-s_1}A_i\cap T^{-s_2}A_i \quad \text{ and } \quad T^b x\in T^{-s_1}A_i \cap T^{-s_2}A_j.$$ 
This means
$$x(s_1+a)=x(s_2+a)=x(s_1+b)=i \quad \text{ and } \quad x(s_2+b)=j.$$ 
Let
$$p=\min(P(s_1+a), P(s_2+a), P(s_1+b), P(s_2+b)).$$
By Property (i) we have 
$$s_1+a +n_p \Zb, \, s_2+a+n_p\Zb, \, s_1+b+n_p\Zb \in V_p \quad \text{ and } \quad s_2+b+n_p\Zb \in W_p.$$ 
From Property (iii) we have
$$ (s_1+a)-(s_2+a)\not\equiv (s_1+b)-(s_2+b) \mod n_p,$$
which is impossible. Therefore each independence set for the pair $(A_i, A_j)$ has cardinality at most $1$.
\end{proof}

\begin{lemma} \label{L-not IN2}
Each independence set for the pair $(A_1\times A_3, A_2\times A_4)$ has cardinality at most $1$.
\end{lemma}
\begin{proof} We argue by contradiction. Assume that $\{s_1, s_2\}$ is an independence set for $(A_1\times A_3, A_2\times A_4)$ for some distinct $s_1, s_2\in \Zb$. Then 
we can find some $(z, z')\in X^2$ such that
$$(z, z')\in T^{-s_1}(A_1\times A_3)\cap T^{-s_2}(A_2\times A_4).$$ 
We may find $a, b\in \Zb$ so that $(T^{a}x, T^{b}x)$ is close enough to $(z, z')$ such that
$$(T^a x, T^b x)\in T^{-s_1}(A_1\times A_3)\cap T^{-s_2}(A_2\times A_4).$$ 
This means
$$x(s_1+a)=1, \quad x(s_2+a)=2, \quad x(s_1+b)=3 \quad \text{ and } \quad x(s_2+b)=4.$$ 
%we can find some $a, b\in \Zb$ such that $x(s_1+a)=1$, $x(s_2+a)=2$, $x(s_1+b)=3$, and $x(s_2+b)=4$. Set
Let
$$p=\min(P(s_1+a), P(s_2+a), P(s_1+b), P(s_2+b)).$$
By Property (i) we have 
$$s_1+a +n_p \Zb, \, s_2+a+n_p\Zb\in V_p \quad \text{ and } \quad s_1+b+n_p\Zb, \, s_2+b+n_p\Zb \in W_p.$$
Since
$$ (s_1+a)-(s_2+a)\equiv (s_1+b)-(s_2+b) \mod n_p,$$
by Property (iv) we have 
$$ s_1+a\equiv s_2+a \mod n_p \quad \text{ and } \quad  s_1+b\equiv s_2+b\mod n_p.$$
If $p=\min(P(s_1+a), P(s_2+a))$, then $x(s_1+a)=x(s_2+a)$, contrary to the fact that $x(s_1+a)=1$ and $x(s_2+a)=2$.
If $p=\min(P(s_1+b), P(s_2+b))$, then $x(s_1+b)=x(s_2+b)$, contrary to the fact that $x(s_1+b)=3$ and $x(s_2+b)=4$.
Therefore each independence set for the pair $(A_1\times A_3, A_2\times A_4)$ has cardinality at most $1$.
\end{proof}

Since $A_1, A_2, A_3$ and $A_4$ are all closed, by Lemma~\ref{L-example IT} and Theorem~\ref{T-IT basic}.\eqref{i-IT tuple}
we can find $x_j\in A_j$ for $j\in [4]$ such that 
$$(x_1, x_2), (x_3, x_4)\in \IT_2(X).$$ 
For any $i\in \{1, 2\}$ and $j\in\{3, 4\}$, since $A_i\times A_j$ is a product neighborhood of $(x_i, x_j)$ in $X^2$, by Lemma~\ref{L-not IN1} we have $(x_i, x_j)\not\in \IN_2(X)$. Because $A_1\times A_3$ and $A_2\times A_4$ are neighborhoods of $(x_1, x_3)$ and $(x_2, x_4)$ in $X^2$ respectively, from Lemma~\ref{L-not IN2} we know that $((x_1, x_3), (x_2, x_4))\not\in \IN_2(X^2)$. By Lemma~\ref{L-not IN} we have
$$(\lambda \delta_{x_1}+(1-\lambda)\delta_{x_3},  \lambda \delta_{x_2}+(1-\lambda)\delta_{x_4})\not\in \IN_2(\cM(X))$$
for all $0<\lambda<1$. As IT-tuples are always IN-tuples, we also have
$$(x_1, x_2), (x_3, x_4)\in \IN_2(X),$$
and 
$$(\lambda \delta_{x_1}+(1-\lambda)\delta_{x_3},  \lambda \delta_{x_2}+(1-\lambda)\delta_{x_4})\not\in \IT_2(\cM(X))$$
for all $0<\lambda<1$. 
Therefore neither $\IN_2(\cM(X))$ nor $\IT_2(\cM(X))$ is convex.



