\section{Application to local theory of Banach spaces} \label{S-Banach}



For a set $E$ in a normed vector space $V$, we denote by $\widetilde{\rm co}(E)$ the convex hull of $E\cup \{0\}$ in $V$. For $r>0$, we denote by $B_r(V)$ the closed $r$-ball of $V$, i.e., 
$$B_r(V)=\{v\in V: \|v\|\le r\}.$$
For $n\in \Nb$ and $1\le p\le \infty$, we write $\ell_p^n$ for $\Rb^n$ equipped with the $\ell_p$-norm given in \eqref{E-p norm1} and \eqref{E-p norm2}. 

\begin{lemma} \label{L-FLM}
Let $0<\delta\le 1$ and $1<p\le \infty$. There exist a finite set $T\subseteq \Rb^2$ and $c'>0$, depending only on $\delta$ and $p$, such that the following hold:
\begin{enumerate}
\item $t_1\ge t_2+\delta$ for every $(t_1, t_2)\in T$, and
\item for any $n\in \Nb$, if $E\subseteq B_1(\ell_p^n)$  and $\widetilde{\rm co}(E)\supseteq B_\delta(\ell_p^n)$, then there are some $J\subseteq [n]$ with $|J|\ge c'n$
and $(t_1, t_2)\in T$ such that for any map $\sigma: J\rightarrow [2]$ there is some $v\in E$ so that $v(j)\ge t_1n^{-1/p}$ for all $j\in \sigma^{-1}(1)$ and $v(j)\le t_2n^{-1/p}$ for all $j\in \sigma^{-1}(2)$.
\end{enumerate}
\end{lemma}
\begin{proof} We take $1\le q<\infty$ such that $1/p+1/q=1$. Let $k=2$, $C=1$, $R=\delta$, and $r=\delta/2$. Then we have $c, N$ and $T$ given by Lemma~\ref{L-func to indep}. We may assume that $N\ge 2$. We set
$$T'=\{(t_1, t_2): (t_1, -t_2)\in T\}.$$
We shall show that $T''=T'\cup \{(\delta, -\delta)\}$ and $c'=\min(c, \frac{1}{N})$ have the desired property. 

For each $(t_1, t_2)\in T'$, we have $\frac{1}{2}(t_1-t_2)\ge r=\delta/2$, whence $t_1\ge t_2+\delta$. It follows that (1) holds. 

Let $n\in \Nb$ and $E\subseteq B_1(\ell_p^n)$  such that $\widetilde{\rm co}(E)\supseteq B_\delta(\ell_p^n)$.

 We consider first the case $n\ge N$.
 Let $\psi: [n]\rightarrow [2]$. We denote by $g_\psi$ the element in $B_\delta(\ell_p^n)$ given by
 $$g_\psi(i)=(-1)^{\psi(i)+1}\delta n^{-1/p}$$
 for all $i\in [n]$.
Then $g_\psi \in \widetilde{\rm co}(E)$, and hence we can write $g_\psi$ as $\sum_{v\in E}t_v v$ for some $t_v\in [0, 1]$ for each $v\in E$ such that $\sum_{v\in E}t_v\le 1$. Note that
\begin{align*}
\sum_{v\in E}t_v\frac{1}{n^{1/q}}\sum_{i\in [n]}(-1)^{\psi(i)+1}v(i)&=\frac{1}{n^{1/q}}\sum_{i\in [n]}(-1)^{\psi(i)+1}\sum_{v\in E}t_v v(i)\\
&=\frac{1}{n^{1/q}}\sum_{i\in [n]}(-1)^{\psi(i)+1}g_\psi(i)\\
&=\frac{1}{n^{1/q}}\sum_{i\in [n]}\delta n^{-1/p}=\delta,
\end{align*}
whence we can find some $v_\psi\in E$ such that
$$ \frac{1}{n^{1/q}}\sum_{i\in [n]}(-1)^{\psi(i)+1}v_\psi(i)\ge \delta.$$
We define a function $f_\psi: [n]\rightarrow \Rb$ by
$$ f_\psi(i)=(-1)^{\psi(i)+1}v_\psi(i)$$
for all $i\in [n]$. 
Then
$$ \|f_\psi\|_p=\|v_\psi\|_p\le 1=C,$$
and 
$$ \frac{1}{\left|[n]\right|^{1/q}}\sum_{i\in [n]}f_\psi(i)=\frac{1}{n^{1/q}}\sum_{i\in [n]}(-1)^{\psi(i)+1}v_\psi(i)\ge \delta=R.$$
By our choice of $c, N$ and $T'$, we can find some $J\subseteq [n]$ with $|J|\ge cn\ge c'n$ and $(t_1, t_2)\in T'$ such that  every map $\sigma: J\rightarrow [2]$ extends to a
$\psi\in \sR([n], 2)$
so that $f_\psi(i)\ge t_1\left| [n]\right|^{-1/p}$ for all $i\in \sigma^{-1}(1)$ and $f_\psi(i)\ge (-t_2)\left| [n]\right|^{-1/p}$ for all $i\in \sigma^{-1}(2)$. That is, 
$$v_\psi(i)=(-1)^{\sigma(i)+1}v_\psi(i)=(-1)^{\psi(i)+1}v_\psi(i)=f_\psi(i)\ge t_1\left| [n]\right|^{-1/p}=t_1n^{-1/p}$$
for all $i\in \sigma^{-1}(1)$ and
 $$-v_\psi(i)=(-1)^{\sigma(i)+1}v_\psi(i)=(-1)^{\psi(i)+1}v_\psi(i)=f_\psi(i)\ge (-t_2)\left| [n]\right|^{-1/p}=-t_2n^{-1/p}$$
 for all $i\in \sigma^{-1}(2)$. 

Next we consider the case $n<N$. We set $J=\{1\}$ and $(t_1, t_2)=(\delta, -\delta)\in T''$. Then $|J|\ge n/N\ge c'n$.
Since
$$ (\delta, \underbrace{0, \dots, 0}_{n-1})\in B_\delta(\ell_p^n)\subseteq \widetilde{\rm co}(E),$$
we can find some $v\in E$ such that $v(1)\ge \delta\ge t_1 n^{-1/p}$. Similarly, using 
$$ (-\delta, \underbrace{0, \dots, 0}_{n-1})\in B_\delta(\ell_p^n)\subseteq \widetilde{\rm co}(E),$$
we can find some $w\in E$ such that $w(1)\le -\delta\le t_2n^{-1/p}$. Then for a map $\sigma: J\rightarrow [2]$, we can use $v$ when $\sigma(1)=1$ and $w$ when $\sigma(1)=2$ to fulfill the requirement of (2). 
\end{proof}


We are ready to prove Theorem~\ref{T-FLM}. 

\begin{proof}[Proof of Theorem~\ref{T-FLM}] We set $\delta=1/C\in (0, 1)$ and take $1<p\le \infty$ such that $1/p+1/q=1$. Then we have $T$ and $c'$ given by Lemma~\ref{L-FLM}. Set $c=\frac{2}{c'\log 2}>0$. 

Let $n, m\in \Nb$ with $m\ge 2$ such that $\ell_q^n$ is $C$-isomorphic to a linear subspace of $\ell_\infty^m$. Then we have 
an injective linear map $\Phi: \ell_q^n\rightarrow \ell_\infty^m$ such that $\|\Phi\|\cdot \|\Phi^{-1}\|\le C$, where $\Phi^{-1}$ denotes the inverse map from $\Phi(\ell_q^n)$ to $\ell_q^n$. Multiplying $\Phi$ by a scalar if necessary, we may assume that $\|\Phi\|=1$. Then $\|\Phi^{-1}\|\le C$.

For each Banach space $V$, we denote by $V^*$ the dual space of $V$. For each $\phi\in (\ell_q^n)^*=\ell_p^n$, $\phi\circ \Phi^{-1}$ is in $(\Phi(\ell_q^n))^*$ with
$$\| \phi\circ \Phi^{-1}\|\le \|\phi\|\cdot \|\Phi^{-1}\|\le \|\phi\|C,$$
and hence by the Hahn-Banach theorem $\phi \circ \Phi^{-1}$ extends to a $\omega\in (\ell_\infty^m)^*=\ell_1^m$ with
$$\|\omega\|=\|\phi\circ \Phi^{-1}\|\le \|\phi\|C.$$
Thus, denoting by $\Phi^*$ the dual map $\ell_1^m=(\ell_\infty^m)^*\rightarrow (\ell_q^n)^*=\ell_p^n$ of $\Phi$, we have
$$ \|\Phi^*\|=\|\Phi\|=1 \mbox{ and } \Phi^*(B_1(\ell_1^m))\supseteq B_{1/C}(\ell_p^n)=B_{\delta}(\ell_p^n).$$

We denote by $E$ the standard basis of $\ell_1^m$. Clearly $\widetilde{\rm co}(E\cup (-E))=B_1( \ell_1^m)$. We set $E'=\Phi^*(E\cup (-E))\subseteq B_1(\ell_p^n)$. Then
$$\widetilde{\rm co}(E')=\Phi^*(\widetilde{\rm co}(E\cup (-E)))=\Phi^*(B_1( \ell_1^m))\supseteq B_{\delta}(\ell_p^n).$$
By our choice of $T$ and $c'$, we can find some $J\subseteq [n]$ with $|J|\ge c'n$ and some $(t_1, t_2)\in T$ such that for any map $\sigma: J\rightarrow [2]$ there is some $v\in E'$ so that $v(j)\ge t_1n^{-1/p}$ for all $j\in \sigma^{-1}(1)$ and $v(j)\le t_2n^{-1/p}$ for all $j\in \sigma^{-1}(2)$. Since $t_1\ge t_2+\delta>t_2$, different $\sigma$ must yield different $v$. Thus
$$ 2^{c'n}\le 2^{|J|}\le |E'|\le 2m.$$
Therefore, using $m\ge 2$, we get
\begin{displaymath}
n \le \frac{1}{c'\log 2}\log (2m)\le \frac{2}{c'\log 2}\log m=c\log m. \tag*{\qedsymbol}
\end{displaymath}
     \renewcommand{\qedsymbol}{}
     \vspace{-\baselineskip}
\end{proof}

The bound in Theorem~\ref{T-FLM} is also optimal, as one can see from the following well-known fact (cf. \cite[page 65]{FLM} or \cite[page 56]{Pisier}).

\begin{lemma} \label{L-embedding exist}
Let $C>1$. There is a constant $\lambda>1$ depending only on $C$ such that  every finite-dimensional normed space $V$ is $C$-isomorphic to a linear subspace of $\ell_\infty^m$ for some $m\le \lambda^{\dim V}$.
\end{lemma}



