		\vertex{E}{1};
		\vertex{F}{1};}
	$} + \resizebox{\dThree}{!}{$\diagram{
		\DecayTypeFour;
		\vertex{B}{1};
		\vertex{C}{1};
	}$}\nonumber\\
    &+ \resizebox{\dThree}{!}{$\diagram{
		\DecayTypeFour;
		\vertex{B}{1};
		\vertex{C}{2};
	}$} + \resizebox{\dThree}{!}{$\diagram{
