\section{Detail calculations of the correlation functions  }\label{app:MediumGORPhysBasis}
In this appendix, we show the details of calculations of the correlation functions used in \cref{sec:in-medium-pion-properties,sec:in-medium-GOR}. We first consider the correlation function $\Pi^{ab}(q)$ in the physical basis for $a=\pm,b=\mp$ given as 
\begin{align}
    \Pi^{\pm\mp}(q) =  \int \dd[4]x \eu^{\im q \cdot x} \langle \Omega | \mathsf T P^\pm(x) P^\mp(0) | \Omega \rangle.
\end{align}
The correlation function in the coordinate space reads:
\begin{widetext}
\begin{align} \label{eq:apC1}
    \MoveEqLeft \langle\Omega|\mathsf T P^\pm (x) P^\mp(0)|\Omega\rangle = \nonumber\\
	&\sum\limits_n\int \frac{\dd[3]\vec p_n}{(2\pi)^32\omega_n} \bigg[ \Heavi(x_0) \langle\Omega|P^\pm (x) |n(p_n)\rangle\langle n(p_n)|P^\mp(0)|\Omega\rangle + \Heavi(-x_0) \langle\Omega|P^\mp(0) |n(p_n)\rangle\langle n(p_n)|P^\pm (x)|\Omega\rangle \bigg],
\end{align}
\end{widetext}
where we have inserted a complete set of one particle states. The inclusion of multiple particle states can be done straightforwardly. We use the matrix elements of the pseudoscalar current between one in-medium pion state and an asymptotic state in nuclear matter defined in~\cref{eq:P_coupling_medium,eq:P_coupling_medium_cc}.
\begin{comment}
\begin{subequations}
\begin{align}
    \langle\Omega|P^{\pm,0} (x)|\pi^{* \pm,0}(p)\rangle &=  G^{*}_{\pi^{\pm,0}}  \eu^{- \im p \cdot x},\\
    \langle\Omega|A_0^{\pm,0}(x)|\pi^{*\pm,0}(p)\rangle &= \im f^{*(t)}_{\pi^{\pm,0}} p_0\eu^{- \im p \cdot x}, \\
	\langle\Omega|A_i^{\pm,0}(x)|\pi^{*\pm,0}(p)\rangle &= \im f^{*(s)}_{\pi^{\pm,0}} p_i\eu^{- \im p \cdot x}.
\end{align}
\end{subequations}
and their complex conjugate 
\begin{subequations}
\begin{align}
    \langle \pi^{* \pm,0}(p) |P^{\mp,0} (x)|\Omega \rangle &= \bar G^{*}_{\pi^{\pm,0}}\eu^{ \im p \cdot x},\\
    \langle\pi^{*\pm,0}(p)|A_0^{\mp,0}(x)|\Omega\rangle &= -\im \bar{f}^{*(t)}_{\pi^{\pm,0}} p_0\eu^{ \im p \cdot x}, \\
	\langle\pi^{*\pm,0}(p)|A_i^{\mp,0}(x)|\Omega\rangle &= -\im \bar{f}^{*(s)}_{\pi^{\pm,0}} p_i\eu^{ \im p \cdot x}.
\end{align}
\end{subequations}
where $P^{\pm}(x) = (P^1(x) \mp \im P^2 (x)) / \sqrt{2}$ and $P^0(x) = P^3(x)$.
\end{comment}
Substituting them into each term in \cref{eq:apC1}, we obtain:
\begin{widetext}
\begin{align}
    \MoveEqLeft \langle\Omega|\mathsf T P^\pm (x) P^\mp(0)|\Omega\rangle =
	 \sum\limits_{n^\pm}\int \frac{\dd[3]\vec p_{n^\pm}}{(2\pi)^3} \Heavi(x_0) \frac{G^{*}_{\pi^{\pm}_n} \bar G^{*}_{\pi^\pm_n}(p_{n^\pm}) \eu^{- \im p_{n^\pm} \cdot x}}{2\omega_{n^\pm}} + \sum\limits_{n^\mp}\int \frac{\dd[3]\vec p_{n^\mp}}{(2\pi)^3} \Heavi (-x_0) \frac{\bar G^{*}_{\pi^\mp_n} G^*_{\pi^\mp_n}(p_{n^\mp}) \eu^{\im p_{n^\mp} \cdot x}}{{2\omega_{n^\mp}}} ,
\end{align}
where $n$ labels $\pi^\pm$ excited states, and $p^\mu_{n^{\pm}}=(\omega_{n^\pm}(\vec p_{n^{\pm}}),\vec p_{n^{\pm}})$. We can now use the following mathematical identity: 
\begin{align}
	\Heavi(\pm x_0)\eu^{\mp \im \omega_n x_0} &= \pm\frac{1}{2\pi\im} \int\limits_{-\infty}^{\infty}\dd{\omega}\frac{\eu^{\im\omega x_0}}{\omega \pm \omega_n \mp \im\epsilon}.
    \label{eq:mathematical_identity}
\end{align}
By using this, we write 
\begin{comment}
the integral as a four-dimensional momentum integral: 
\begin{align}
