	-\im \bigg[ \sum\limits_{n^\pm}\int \frac{\dd[3]\vec p_{n^\pm} \dd s}{
    (2\pi)^4} \frac{G^{*}_{\pi^{\pm}_n} \bar G^{*}_{\pi^\pm_n}(p_{n^\pm}) \eu^{\im (sx_0 + \vec p_{n^\pm} \cdot \vec x)}}{2\omega_{n^\pm}(s + \omega_{n^\pm} - \im \epsilon)} - \sum\limits_{n^\mp}\int \frac{\dd[3]\vec p_{n^\mp} \dd s}{
    (2\pi)^4} \frac{\bar G^{*}_{\pi^{\mp}_n} G^{*}_{\pi^\mp_n}(p_{n^\mp}) \eu^{\im (sx_0 - \vec p_{n^\mp} \cdot \vec x)}}{2\omega_{n^\mp}(s - \omega_{n^\mp} + \im \epsilon)} \bigg].
\end{align}
Thus, 
\end{comment}
the correlation function $\Pi^{\pm\mp} (q)$ as 
\begin{align}
    \Pi^{\pm\mp} (q) &= -\im \int \dd[4]x \eu^{\im q\cdot x} \bigg[ \sum \limits_{n^\pm} \int \frac{\dd[3]\vec p_{n^\pm}\dd s}{
    (2\pi)^4} \frac{G^{*}_{\pi^{\pm}_n} \bar G^{*}_{\pi^\pm_n}(p_{n^\pm}) \eu^{\im (sx_0 + \vec p_{n^\pm} \cdot \vec x)}}{2\omega_{n^\pm}(s + \omega_{n^\pm} - \im \epsilon)} - \sum \limits_{n^\mp} \int \frac{\dd[3]\vec p_{n^\mp} \dd s}{
