    m_q\lim_{\vec q \to 0}\Pi^{\pm\mp} (q) &= \im m_q \left[ \sum_{n^\pm} \frac{G^{*}_{\pi^\pm_n} \bar G^*_{\pi^\pm_n}}{2m_{\pi_n^\pm}^*\left(q^0 -m_{\pi_n^\pm}^* + \im \epsilon\right)} - \sum_{n^\mp}\frac{\bar G^{*}_{\pi^\mp_n} G^*_{\pi^\mp_n}}{2m_{\pi_n^\mp}^*\left(q^0 + m_{\pi_n^\mp}^* - \im \epsilon\right)} \right],\\
    \im q^0\lim_{\vec q \to 0}\Pi_{50}^{00} (q) &= -\im q^0 \sum_{n^0} \left[ \frac{\left(m^*_{\pi_n^0}F^*_{\pi_n^0}+N_{\pi_n^0}^*\right) \bar G^*_{\pi^0_n}}{2m^*_{\pi_n^0}\left(q^0 -m_{\pi_n^0}^* + \im \epsilon\right)} + \frac{\left(m^*_{\pi_n^0}\bar{F}^*_{\pi_n^0}+\bar{N}_{\pi_n^0}^*\right) G^*_{\pi^0_n}}{2m_{\pi_n^0}^*\left(q^0 + m_{\pi_n^0}^* - \im \epsilon\right)} \right],\\
    \im q^0\lim_{\vec q \to 0}\Pi_{50}^{\pm\mp} (q) &= -\im q^0\left[\sum_{n^\pm} \frac{\left(m^*_{\pi_n^\pm}F^*_{\pi_n^\pm}+N_{\pi_n^\pm}^*\right) \bar G^*_{\pi^\pm_n}}{2m_{\pi_n^\pm}^*\left(q^0 -m_{\pi_n^\pm}^* + \im \epsilon\right)} + \sum_{n^\mp} \frac{\left(m^*_{\pi_n^\mp}\bar{F}^*_{\pi_n^\mp}+\bar{N}_{\pi_n^\mp}^*\right) G^*_{\pi^\mp_n}}{2m_{\pi_n^\mp}^*\left(q^0 + m_{\pi_n^\mp}^* - \im \epsilon\right)} \right],
\end{align}
\end{subequations}
where $n^{\pm,0}$ label $\pi^{\pm,0}$ excited states.
We now use the PCAC relation for the pion states \cite{Jido2008}
\begin{align}    
    (\omega_{n^{\pm,0}}(\vec p)^2- \vec p \cdot \vec p )F_{\pi_n^{\pm,0}}^{*}+\omega_{n^{\pm,0}}(\vec p)N_{\pi_n^{\pm,0}}^{*}  = m_q G_{\pi_n^{\pm,0}}^*.
\end{align}
In the rest frame, then, we arrive at
\begin{subequations}\label{eq:gorfn}
\begin{align}
    \frac{1}{2} \sum_{n^+}  \left[\left|m^*_{\pi_n^+}F^*_{\pi_n^+}+N_{\pi_n^+}^*\right|^2\right] 
    + \frac{1}{2} \sum_{n^-}  \left[\left|m^*_{\pi_n^-}F^*_{\pi_n^-}+N_{\pi_n^-}^*\right|^2 \right]&=-m_q\langle \bar qq\rangle^*,\label{eq:apqqch}\\
    \sum_{n^0}  \left[\left|m^*_{\pi_n^0}F^*_{\pi_n^0}+N_{\pi_n^0}^*\right|^2 \right]&=-m_q\langle \bar qq\rangle^*.\label{eq:apqqn}
\end{align}
\end{subequations}
Equation (\ref{eq:apqqch}) has been obtained from the correlation functions for the charged particles, which provide the equivalent sum rule, while the correlation functions for the neutral pion give \cref{eq:apqqn}. Both sum rules share the same right-hand side. These are the generalized GOR relations in isospin asymmetric nuclear matter. It can be considered in terms of the decay constants.
