We will need a technical lemma below. It basically says, for our purpose, we may assume the twisted Hodge module $\gr^{W_1}\gr^{V_1} M$ is of pure support, i.e., $\gr^{W_1}\gr^{V_1} M$ is the intermediate extension of the (twisted) VHS on the open part. Given a VHS on $(\Delta^*)^n$, we extend it as a Hodge module $M$. Consider the $V$-filtration along a coordinate axis, say $D_1=(z_1=0)$. The following lemma says, if $F_p M$ is the lowest piece of $M$, then $F_p \gr^{W_1}\gr^{V_1} M$ is torsion free on $D_1$. Even if $\gr^{W_1}\gr^{V_1} M$ has $\D$-module components supported on lower dimensional subvarieties of $D_1$, the lower dimensional components doesn't contribute to the lowest piece, which means $F_p \gr^{W_1}\gr^{V_1} M$ only comes from the VHS on $D_1^*=(\Delta^*)^{n-1}$. 

%\textcolor{red}{I suspect something stronger is true, i.e., $\gr^{W_1}\gr^{V_1} M$ has pure support on $D_1$.}

\begin{lemma}
	Given a polarizable Hodge-Lefschetz module $(M,N,W_{\sbullet} = W(N)_{\sbullet})$ in the sense of Definition 3.6 in \cite{davis2024archimedeanzetafunctionssingularities} which is torsion-free on a smooth variety $Y$. Let $F_p M\neq 0$ and $F_{p-1}M=0$, then the lowest piece of Hodge modules $F_p\gr^W_r M$ for $r\geq 0$ are torsion-free on $Y$, and $F_p \gr^W_r M =0$ for $r<0$.
\end{lemma}
\begin{proof}
	Given a local section $m\in F_p M$, and $m\in W_l\backslash W_{l-1}$. such that $f\cdot [m]=0\in \gr^W_l M$ for some local holomorphic function $f$. By \cite[Lemma 3.7]{davis2024archimedeanzetafunctionssingularities}, we have $l$ is the minimum such that $N^{l+1}m=0\in M$. And we know $f\cdot m\in W_{l-h}\backslash W_{l-h-1}$ for some $h\geq 1$ since $f\cdot[m]=0$. Also $f\cdot m\in F_p M$, then by that lemma again we have $N^{l-h+1} fm = f(N^{l-h+1}m)=0$. Since $M$ is assumed to be torsion-free, $N^{l-h+1}m=0$, which contradicts the minimality of $l$. Hence $F_p\gr^W_l M$ is torsion-free. 
\end{proof}

We prove the first part of the main theorem, which is the case when $C$ is not inside the boundary divisor. Also note that here we don't need to assume that $D$ is SNC, but the price is $F_p M$ may not be locally free.
\begin{theorem}
	Let $X$ be a compact complex manifold, $D$ is a divisor on $X$, $\mathcal{V}$ is a VHS on $X\backslash D$, and $M$ is the extension of $\mathcal{V}$ as a Hodge module. Given a map $f:C\rightarrow X$ where $C$ is a smooth projective curve, if $\IM(C)\nsubseteq D$, then $f^* F_p M$ is a nef coherent sheaf on $C$. 
\end{theorem}
\begin{proof}
	Since the image of $C$ is not contained in $D$, we can first pullback the generic VHS to a Zariski open set of $C$, and extend it to a Hodge module $M_C$ on $C$. By functoriality of Hodge modules, as long as the image of $C$ is not contained in $D$, there exists a map $F_p M_C \rightarrow f^* F_p M$ which is generically an isomorphism \cite[Lemma 2.6]{bakker2023hodgetheoreticproofhwangstheorem}. 

	Since $F_p M_C$ is a nef vector bundle by Theorem \ref{thm:curvetwistingtheorem}, $f^* F_p M$ is also a nef coherent sheaf on $C$. The same argument works even when $D$ is not simple normal crossing, so when $D$ is not SNC $f^* F_p M$ is still nef on $C$.
\end{proof}





Now let $X,D,\mathcal{V}$ be as at the beginning of this section, i.e., $X$ will be a compact complex manifold, $D=\sum_i D_i$ is a SNC divisor on $X$, $\mathcal{V} $ is a polarized variations of Hodge structures on $X\backslash D$. For a fixed $i$, let $-1 <\beta_{ij}\leq 0$ be eigenvalues of residues of the canonical extension $V^{>-1}$ along $D_i$. 

For completeness and convenience, we include the following lemma. It says when a coherent sheaf on a curve is filtered, and we want to give a lower bound on the degrees of its line bundle quotients, it suffices to give such lower bounds on the graded objects of the filtration. To keep the statement of the lemma concise, we denote by $d(\F)$ be the smallest degree of quotient line bundles of a coherent sheaf $\F$ on a curve. 
	\begin{lemma}\label{bounding degrees of filtrations}
		Given a coherent sheaf $\F$ on a smooth projective curve with a finite increasing filtration $L_{\sbullet} \F$ on a curve, then 
		$$d(\F)\geq \min_i \{d(\gr^L_i \F)\}.$$	
	\end{lemma}
	\begin{proof}
		Assume $0=L_0 \F \subset L_1\F\subset \cdots \subset L_k \F=\F $. It suffices to show $d(\F)\geq \min\{d(\gr^L_k \F),d(L_{k-1}\F)\}$, then an easy induction will completes the proof of the lemma.

		Let $\F\rightarrow P$ be a quotient line bundle. If the composition of the morphisms $L_{k-1}\F\rightarrow \F\rightarrow P$ is nonzero, then $d(\F)\geq\deg P\geq d(L_{k-1} \F)$; otherwise the morphism $\F\rightarrow P$ factors through $\F\rightarrow \gr^L_k \F\rightarrow P$, so $P$ is also a quotient of $\gr^L_k \F$, and we have $d(\F)\geq \deg P\geq d(\gr^L_k \F)$. We have proved $d(\F)\geq \min\{d(\gr^L_k \F),d(L_{k-1}\F)\}$.

	\end{proof}


\begin{theorem}
	Let $C$ be a smooth projective curve. Let $f: C\rightarrow X$, such that $\IM(C)\subset D_{(k)}\defeq D_1\cap \cdots \cap D_k$, but the image of $C$ doesn't lie in any $(k+1)$ intersections of boundary divisors, and $f^* F_p M\rightarrow P$ is a quotient line bundle, then 
	$$\deg P \geq \min_{\text{over all possible }j_i} \big\{ \sum_{i=1}^k (- \beta_{ij_i}\cdot \deg f^* \strucsheaf_X(D_i)) \big\}.$$

	 %When the monodromies are unipotent, we have all $\beta_{rs}$ equal to zero, this implies $F_p M$ is a nef vector bundle on $X$. Therefore we have recovered the semi-positivity theorem of Kawamata \cite{Kawamata1981}, see also \cite{fujinovmhs}, \cite{MR3167580}, \cite{semipo}.
\end{theorem}


\begin{proof}
	If $\IM(C)\subset D$, to illustrate the idea, assume $f: C\rightarrow D_1\hookrightarrow X$, and the image of $C$ doesn't lie in the intersections of boundary divisors. Remember $N=M\otimes K_X$ is the corresponding right $\D$-module. Consider the $V$-filtration of $N$ along $D_1$. As explained in section 2,  $F_p N|_{D_1} $ is filtered by coherent subsheaves 
		$$\frac{F_pV_{\alpha_1}N}{F_p V_{<-1}N},\cdots,\frac{F_pV_{\alpha_k}N}{F_p V_{<-1}N},$$
		where $-1\leq \alpha_1<\cdots<\alpha_k<0$ are related to the monodromy along $D_1$; in fact, $ (-\alpha_{i}-1)$ are exactly the eigenvalues of residues of canonical extension of $\V$ along $D_1$. The graded quotients of this filtration by subsheaves are $F_p \text{gr}^V_{\alpha_i}$, which is the pushforward of a coherent sheaf from $D_1$ to $X$. By \cite[Proposition 3.12]{schnell2024highermultiplierideals}, we know $\gr^W_l \gr^V_\alpha N$ is an $\alpha L$-twisted Hodge module on $X$ supported on $D_1$, for $\alpha\in [-1,0)$, $l\in \Z$, where $L=\strucsheaf_X(D_1)$. Now by Lemma \ref{bounding degrees of filtrations}, it remains to understand the degree lower bounds of quotient line bundles of the lowest piece of twisted Hodge modules $F_p \gr^W_l\gr^{V}_{\alpha_i} N\otimes K_{X}^{-1}$ on $D_1$, since $F_p \gr^W_l\gr^{V}_{\alpha_i} N\otimes K_{X}^{-1}$ are subquotients of $F_p M|_{D_1}$.

		By Theorem \ref{thm:curvetwistingtheorem}, every line bundle quotient $P_{\alpha_i,l}$ of $$f^* (F_p \gr^W_l\gr^V_{\alpha_i} N \otimes K_{X}^{-1}) = f^* (F_p \gr^W_l\gr^V_{\alpha_i} N\otimes K_{D_1}^{-1}\otimes (K_{D_1}\otimes K_{X}^{-1}|_{D_1})$$ has $\deg P_{\alpha_i, l} - \deg f^*(K_{D_1}\otimes K_{X}^{-1}|_{D_1}) \geq \alpha_i \cdot \deg f^* L$, hence
		$$\deg P_{\alpha_i,l}\geq (1+\alpha_i)\cdot \deg f^*\strucsheaf_X(D_1) = -\beta_i \deg \strucsheaf_X(D_1).$$
		Here the the appearance of canonical bundles of $X$ and $D_1$ is due to left-right conversions of $\D$-modules, since our convention for taking twisted Hodge modules is using right $\D$-modules \cite[Remark 3.3]{schnell2024highermultiplierideals}, but the object we are interested in is the lowest piece of the left Hodge module.

		Now we return to our original object, $f^* F_p M$. It's filtered by some coherent subsheaves, and the quotient line bundles of the subquotients have degree lower bounds in terms of $\deg f^*\strucsheaf_X(D_1)$ and monodromy along $D_1$. Then by Lemma \ref{bounding degrees of filtrations}, the degree of the quotient line bundles $f^* F_p M\rightarrow P$ is bounded below by the minimum of all the lower bounds, if given a map $f: C\rightarrow D_1\hookrightarrow X$,
		$$\deg P\geq \min_i \{-\beta_i \cdot \deg f^*\strucsheaf_X(D_1)\}.$$

	In the general case, if $\IM(C)\subset D_{(k)}\defeq D_1\cap \cdots \cap D_k$, but the image of $C$ doesn't lie in any $(k+1)$ intersections of boundary divisors, then
	we take nearby cycles along $D_1$ up to $D_k$, and the object we get is an
	$$(\alpha_{1}\cdot \strucsheaf_X(D_1)|_{D_{(k)}},\cdots,\alpha_{k}\cdot \strucsheaf_X(D_k)|_{D_{(k)}})\text{-twisted Hodge module } N_k.$$
	By assumption $\IM(C)$ is not contained in the singular locus of this (twisted) Hodge module, we can first pullback the (twisted) VHS to $C$, then extend it as a multiply twisted Hodge module $N'$ on $C$. Then there exists a map $F_p N'\otimes K_C^{-1}\rightarrow f^* (F_p N_k\otimes K_{D_{(k)}}^{-1} )$ as in \cite[Lemma 2.6]{bakker2023hodgetheoreticproofhwangstheorem} which is generically an isomorphism. The quotient line bundle $f^* (F_p N_k\otimes K_{X}^{-1} ) \rightarrow L$, by an application of Theorem \ref{thm:curvetwistingtheorem} in the multiply twisted case, has a degree lower bound $\sum \alpha_i f^*\strucsheaf_X(D_i) + f^*(K_{D_{(k)}} \otimes K_X^{-1}) = \sum (1+\alpha_i)f^* \strucsheaf_X(D_i)$, which implies our theorem.
\end{proof}






Now we state two corollaries. The first one is originally due to Kawamata \cite{Kawamata1981}. His proof uses Cattani-Kaplan-Schmid's results about VHS, and our proof of the main theorem is essentially in the same spirit of Kawamata, by specializing the lowest piece to the intersection of divisors. It's also proved in \cite{semipo} using asymptotics of the Hodge metric, and a current approximation theorem in complex analytic geometry. See also \cite{fujinovmhs} and \cite{MR3167580} The second corollary is new. In the case of abelian varieties, it is also proved in \cite[Corollary 20.2]{pps2017}, using methods of generic vanishing theory. They actually proved something stronger in that case, that $F_p M$ becomes globally generated possibly after some isogenies.



\begin{corollary}
	If $D$ is a normal corssing divisor, and the monodromies along each component of $D$ are unipotent, then $F_p M$ is a nef vector bundle on $X$.
\end{corollary}
\begin{proof}
	When $D$ is simple normal crossing, because all $\beta_{ij}=0$ in the case of unipotent monodromy, then the main theorem implies all quotient line bundles have non-negative degrees.

	If the divisor is only assumed to be normal crossing, then each component $D_i$ could have self-intersections. We blow up all the intersections of divisors and get $\mu: \tilde{X}\rightarrow X$, to make $\mu^* D$ have simple normal crossing support. Pullback the canonical extension $V$ on $X$ to $\tilde{X}$, call it $\tilde{V}$, and $\tilde{V}$ is a locally free sheaf with a logarithmic connection along $\mu^{-1}(D)$, extending the VHS on $\tilde{X}-\mu^{-1}(D) $. Since the VHS on $X-D$ is unipotent, the residues of the canonical extension are nilpotent. By a local computation of blowing ups, $\tilde{V}$ also has nilpotent residues. By uniqueness \cite[Theorem 5.2.17]{htt}, this implies $\tilde{V}$ is the canonical extension on $\tilde{X}$. Denote the corresponding Hodge module on $\tilde{X}$ by $\tilde{M}$, we have $F_p \tilde{M} = F_p \tilde{V} $ by \cite[exercise 11.2]{overview}. Then
	$$F_p \tilde{M} = F_p \tilde{V}  = \mu^* F_p V = \mu^* F_p M.$$
	By the first paragraph, $F_p \tilde{M}$ is nef, then $F_p M$ is also nef.
\end{proof}





\begin{corollary}
	\begin{itemize}
		\item[(a)] If each component of $D$ is a nef divisor, and $D$ is simple normal crossing, then $F_p M$ is a nef vector bundle on $X$. 

		\item[(b)] If $X$ is a surface, and each $D_i$ is a nef divisor (could be singular), then $F_p M$ is a nef coherent sheaf on $X$.
	\end{itemize}

\end{corollary}


\begin{proof}
	For (a), this is because $-\beta_{ij}\geq 0$, and each $\strucsheaf_X(D_i)$ is a nef line bundle. For (b), the same conclusion of the main theorem is still true for surfaces, with possibly non-SNC boundary divisor $D$, since taking nearby cycles along a singular curve on a surface can only have extra components of twisted Hodge modules at the singular points of the curve, so doesn't really contribute to quotient line bundles. 
\end{proof}



