\[\cF^{A}\coloneqq \lbrace (\cH^{A}, \nabla^{A}), (\cH_R^{A}, \nabla_R^{A}), \id \rbrace / \bbk\dbb{\btau_{\leq r}} ,\]
where $\btau_{\leq r} = \lbrace \tau_{i,k} , 1\leq i\leq r, k\in\bbN^n\rbrace$ parametrizes the $\bbk$-linear F-bundle, and $\tau_{\leq r} = \lbrace \tau_i ,1\leq i\leq r\rbrace$ parametrizes the $R$-linear (T)-structure.



The quotient maps $\bbk\dbb{\btau}\rightarrow \bbk\dbb{\btau_{\leq r}}$ and $R\dbb{\tau}\rightarrow R\dbb{\tau_{\leq r}}$ together with the natural identification of the fibers produce an unfolding of the equivariant F-bundle $\iota\colon \cF^{A}\rightarrow \cF^{A,\bigquantum}$.

\begin{proposition}\label{prop: A model maximal}
The morphism $\iota\colon \cF^{A}\rightarrow \cF^{A,\bigquantum}$ is a maximal unfolding of $\bbk$-linear equivariant F-bundles, with cyclic vector given by $1\in H_T^{\ast}(X,\bbk)$.
\end{proposition}
\begin{proof}
  We have already proven the morphism $\iota:\cH^A\rightarrow \cF^{A,\bigquantum}$ is an unfolding, and it remains to check that $(\cH^A_R,\nabla^A_R)$ is maximal. 
  We take the cyclic vector $v=1\in \cH_{R}^{A,\bigquantum}|_{\tau=u=0}=H^*_T(X,\bbk)$. 
  The $R$-linear evaluation map is the 
  \begin{align*}
      \mu_{v=1}\colon \bigoplus_{j=1}^N R\partial_{\tau_j} &\longrightarrow H_T^{\ast} (X,\bbk)\\
      \partial_{\tau_j} &\longmapsto \nabla_{u\partial_{\tau_j}}|_{\tau=u=0}(1) = \sigma_{v_j}+\lambda_{i_j}.
  \end{align*}
  Since $\{\sigma_{v_i}\}_i$ is an $R=\bbk[\lambda]$ basis of $H^\ast_T(X,\bbk)$ by equation (\ref{eq: R linear basis}), $\mu_{v=1}$ is an $R$-isomorphism and we conclude that $\iota$ is maximal unfolding. 
\end{proof}



\subsection{\texorpdfstring{The small $D$-module mirror symmetry for $G/P$}{The small D-module mirror symmetry for G/P}} \label{subsec:small-B-model}
In this section, we review the $B$-side of mirror symmetry for for $G/P$ as in \cite{Riet}, construct a $R$-linear (T)-structure $(\cH_R^B,\nabla_R^B)$ from the Gauss-Manin connection, and state the small mirror symmetry as in \cite{chow2024dmodulemirrorconjectureflag}.

\subsubsection{Small $D$-module mirror symmetry}
Let $G^\vee$ be the Langlands dual group of $G$, and $T^\vee$, $B^\vee$, $P^\vee$ be the Langlands dual of $T, B, P$ respectively.
Rietsch's equivariant mirror superpotential is a triple $(X^{\vee}_{P}, \mathcal{W}, p)$. Here $X^\vee_P$ is a subvariety of $G^\vee\times Z$ isomorphic to 
\[\big((G^\vee/P^\vee)\setminus -K_{G^\vee/P^\vee} \big)\times \mbox{Spec } \mathbb{C}[\tilde q_{i}^{\pm 1}|\alpha_i\in \Delta\backslash \Delta_P ],\]
where $Z$ is the center of the Levi subgroup of $P^\vee$, $-K_{G^\vee/P^\vee}$ is the anti-canonical divisor of the dual partial flag variety ${G^\vee/P^\vee}$ given in \cite{KLS}. The holomorphic function
$\mathcal{W}: X^\vee_P\to \mathbb{C}$ is the non-equivariant mirror superpotential of $G/P$, and $p: X^\vee_P\to T^\vee$ is a morphism which gives information on the equivariant part of Rietsch's original mirror superpotential $\mathcal{W}+\ln \phi( ; h)$ (see \cite{Riet}). 


  Denote by $\Omega^i(X^\vee_P/Z)$ the space of holomorphic $i$-forms over $X^\vee_P$ with respect to \[Z\cong\mbox{Spec } \mathbb{C}\big[\tilde q_{i}^{\pm 1}\ \big|\ \alpha_i\in \Delta\backslash \Delta_P \big]\] via the aforementioned isomorphism. Identify the Lie algebra $\mathfrak{t}^\vee=\mbox{Lie}(T^\vee)$ with $\mathfrak{t}^*$.
Let $\{(\lambda_i)^{*}\}\subset (\mathfrak{t}^\vee)^*$ be the dual base of $\{\lambda_i\}\subset \mathfrak{t}^\vee$, and 
${\rm mc}_{T^\vee}\in \Omega^1(T^\vee; \mathfrak{t}^\vee)$ denote the
Maurer-Cartan form of $T^\vee$.




In \cite{chow2024dmodulemirrorconjectureflag}, the $B$-model $D$-module $\big(G_0(X_P^{\vee}, \mathcal{W}, p),\nabla\big)$ consists of a $\bbC[\lambda,u]
[\tilde{q}_i^{\pm 1}]$-module defined by
\begin{align*}
     G_0(X_P^{\vee}, \mathcal{W}, p)&= \mbox{coker} \big(\bbC[\lambda, u]\otimes_\bbC \Omega^{{\rm top}-1}(X^\vee_P/Z)\overset{\partial}{\longrightarrow} \bbC[\lambda,u]\otimes_\bbC \Omega^{\rm top}(X^\vee_P/Z)\big),\\ 
     \partial & = 1\otimes \big(ud + d\mathcal{W}\wedge  -\sum_{j=1}^n  \lambda_j  (p^*\langle (\lambda_j)^{*}, {\rm mc}_{T^\vee}\rangle)\wedge \big),
\end{align*}
It is equipped with a meromorphic connection having a logarithmic pole in the $\tilde{q_i}$-direction
\[\nabla_{  \partial_{\tilde{q}_i}}([\omega]) = 
\big[\mathcal{L}_{\partial_{\tilde{q}_{i}}} (\omega)+ u^{-1}\frac{\partial \mathcal{W}}{\partial \tilde{q}_{i} } \omega  -u^{-1}\sum_{j=1}^n \lambda_j \big(\iota_{\partial_{\tilde{q}_{i}}} p^{\ast} \big\langle (\lambda_j)^{\ast}, {\rm mc}_{T^{\vee}}  \big\rangle\big)\omega \big].
\]
Here $p^{\ast} \big\langle (\lambda_j)^{\ast}, {\rm mc}_{T^{\vee}}  \big\rangle \in \Omega^1(X^{\vee}_{P}/Z)$, and $\partial, \nabla$ are linear on $\mathbb{C}[\lambda, u]$. 


\remark{For any $\omega\in \bbC[\lambda,u]\otimes \Omega^{\rm top}(X^\vee_P/Z)$, $\omega=g \omega_{0}$ for some $g\in \mathcal{O}(X^{\vee}_{P})$ and $\omega_{0}\in \Omega^{\rm top}( (G^\vee/P^\vee)\setminus -K_{G^\vee/P^\vee} )$ }. We have the Lie derivative $ \mathcal{L}_{\partial_{ {\tilde{q}_{i}}}}(\omega)=\frac{\partial g}{\partial \tilde{q_{i}}}\omega_{0} .$

The small quantum $D$-module mirror symmetry holds for $G/P$ in the following sense.
\begin{proposition}[\protect{\cite[Theorem 1.2]{chow2024dmodulemirrorconjectureflag}}]\label{prop: iso_small_Dmodule current version}
    There exists a unique $\bbC[\lambda,u][\tilde{q_i}^{\pm 1}]$-linear map
    \begin{equation}\label{eq:chow-mirror-map}
        \Phi_{\rm mir}: G_0(X^{\vee}_{P}, \mathcal{W},  p)\longrightarrow \QH_{T}^{\ast}(G/P)[u, \tilde q_1^{-1},\cdots, \tilde q_r^{-1}] 
    \end{equation}
    satisfying the following:
    \begin{enumerate}[wide]
        \item $\Phi_{\rm mir}$ is bijective, and preserves the connection, 
        \item $\Phi_{\rm mir}([\Omega])=1$, where $\Omega$ is the unique (up to sign) volumn form in $\Omega^\top (X_P^\vee/Z)$, whose restrictions to every torus chart of $(G^\vee/P^\vee)\setminus -K_{G^\vee/P^\vee}$ is equal to the standard volumn form $\pm dz_1\wedge \dots \wedge dz_K/z_1\dots z_K,$
        \item  at the semi-classical limit, we have  a ring isomorphism
        \begin{equation} \label{eq:jacobi-isomorphism}
            \Phi_{\rm mir}^{u=0}: {\rm Jac}(X^{\vee}_{P}, \mathcal{W},  p)\overset{\cong}{\longrightarrow} \QH_{T}^{\ast}(G/P)[\tilde q_1^{-1},\cdots, \tilde q_r^{-1}],
        \end{equation}
        \item $\Phi_{\rm mir}$  intertwines the shift operators (see \cite[Sections 3.3 and 4.5]{chow2024dmodulemirrorconjectureflag}), and
        \item $\Phi_{\mir}$ preserves the $\mathbb{Z}$-grading.
    \end{enumerate}
\end{proposition}
In \eqref{eq:jacobi-isomorphism}, ${\rm Jac}(X^{\vee}_{P}, \mathcal{W},  p)$ denotes the Jacobi ring,  which  is the coordinate ring of the scheme-theoretic zero locus of certain relative 1-forms in $\Omega^1(X^\vee_P\times \mathfrak{t}/Z\times \mathfrak{t})$ (see \cite[Definition 4.9]{chow2024dmodulemirrorconjectureflag} for more details).
It corresponds to setting $u=0$ in the $B$-model $D$-module. 
% $$ {\rm pr}^*_{X^\vee_P}d\mathcal{W}-\langle 
%  {{\rm pr}_{\mathfrak{t}}}, (p \circ {\rm pr}_{X^\vee_P})^*{\rm  mc}_{T^\vee}\rangle \in \Omega^1(X^\vee_P\times \mathfrak{t}/Z\times \mathfrak{t})$$
% where   ${\rm pr}_{X^\vee_P}:  X^\vee_P\times \mathfrak{t}\to   X^\vee_P$ and ${\rm pr}_{\mathfrak{t}}: X^\vee_P\times \mathfrak{t}\to\mathfrak{t}$
%  are the projections.


We remark that the above isomorphism is a bit implicit. Below we provide an example with explicit isomorphism of small quantum $D$-modules from \cite{MaRi}.




\begin{example}
For $G/P=\Gr(3, 5)=\{V\leq \mathbb{C}^5\mid \dim V=3\}$, the Langlands dual flag variety  $G^\vee/P^\vee$ is the Grassmannian $\Gr(2, 5) \hookrightarrow \mathbb{P}^9$, whose image   is defined by the Pl\"ucker  relations $p_{a_1a_2}p_{a_3a_4}-p_{a_1a_3}p_{a_2a_4}+p_{a_1a_4}p_{a_2a_3}=0$ for $1\leq a_1<a_2<a_3<a_4\leq 5$. 
   In this case,  $-K_{G^\vee/P^\vee}=\{p_{12}p_{23}p_{34}p_{45}p_{15}=0\}$.
   The $\mathcal{W}$-part of Rietsch's equivariant superpotential 
   is given by 
   $$\mathcal{W}=\frac{p_{13}}{p_{12}}+\frac{p_{24}}{p_{23}}+\frac{p_{35}}{p_{34}}+\tilde q \frac{p_{14}}{p_{45}}+\frac{p_{25}}{p_{15}}.$$
   The degree of the inhomogeneous coordinate $\theta_{ij}=\frac{p_{ij}}{p_{12}}$ is equal to $2(i+j-3)$.
   The volume form
   $\Omega=\frac{d\theta_{13}d\theta_{14}d\theta_{15}d\theta_{23}d\theta_{24}d\theta_{25}}{\theta_{23}\theta_{34}\theta_{45}\theta_{15}}$ is of degree $0$.
   For $1\leq i<j\leq 5$, 
   $\Phi_{\rm mir}([\theta_{ij} \Omega])=\sigma_w$
   with $w\in S_5$ the unique permutation satisfying   $w(4)=6-j$, $w(5)=6-i$ and 
    $w(1)<w(2)<w(3)$.
\end{example}

\subsubsection{Equivariant F-bundles formulation}
In our setting of (T)-structures, we need to replace the logarithmic $\tilde{q}_i$-directions with a regular meromorphic connection in $y_i$-directions. This is achieved by the $D$-module inverse image under
\begin{align*}
\psi_1\colon \bbC[\lambda,u][\tilde{q_i}^{\pm 1}]&\longrightarrow \bbC[\lambda,u][q_i^{\pm 1}]\dbb{y_{\leq r}}\\
    \tilde{q}_i &\longmapsto q_i e^{y_i},
\end{align*}
where $y_{\leq r} = \lbrace y_i, 1\leq i\leq r\rbrace$. For the purpose of applying our reconstruction theorem to obtain big mirror symmetry, we need to further take the fraction field of $q$ and formalize $u$. 
So we compose $\psi_1$ with the following base change
\[\psi_2\colon \bbC[\lambda,u][q_i^{\pm 1}]\dbb{y_{\leq r}} \longrightarrow  \bbC[\lambda,u][q_i^{\pm 1}]\dbb{y_{\leq r}}\otimes_{\bbC[q_i^{\pm 1},u]}\bbC(q)\dbb{u}.\]
Namely we have the following, where we recall $\bbk=\bbC(q)$ and $R=\bbk[\lambda]$. 
\begin{equation}\label{eq1: change ring}
    \psi\coloneqq \psi_2\circ\psi_1\colon\bbC[\lambda,u][\tilde{q}_i^{\pm 1}]\longrightarrow R\dbb{y_{\leq r},u}.
\end{equation}

The $B$-model $R$-linear (T)-structure  $(\cH_R^{B} , \nabla_R^{B})$ is the $D$-module inverse image $\psi^*\big(\big(G_0(X_P^{\vee}, \mathcal{W}, p),\allowbreak \nabla\big)\big)$, whose underlying $R\dbb{y_{\leq r},u}$-module is
\[\cH_R^{B} = G_0 (X_P^{\vee} , \cW , p)\otimes R\dbb{y_{\leq r} , u}, \]
and the connection is given by 
\begin{align}\label{eq:Gauss-Manin-connection}
    \nabla^B_{R, \partial_{y_{i}}}([\omega])=\big[\mathcal{L}_{\partial_{y_{i}}} (\omega)+ u^{-1}\frac{\partial \mathcal{W}}{\partial y_{i} } \omega  -u^{-1}\sum_{j=1}^n \lambda_j \big(\iota_{\partial_{y_{i}}} p^{\ast} \big\langle (\lambda_j)^{\ast}, {\rm mc}_{T^{\vee}}  \big\rangle\big)\omega \big].
\end{align}



Next we define the $B$-model $\bbk$-linear F-bundle. Fix the $\bbk$-basis of $R$ given by $\blambda = (\lambda^k , k\in \bbN^n)$ and let $\by_{\leq r} \coloneqq \lbrace y_{i,k}, 1\leq i\leq r, k\in\bbN^n \rbrace$. Consider the following change of variables
\begin{align}\label{eq2: change variables}
    \psi_{\blambda}:R\dbb{y_{\leq r},u} &\longrightarrow R\dbb{\by_{\leq r},u}
    \\y_i &\longmapsto \sum_{k\in\bbN^n} \lambda^k y_{i,k}. \nonumber
\end{align}

The underlying (T)-structure 
 $(\cH^B,\nabla^B)$ of the $B$-model $\bbk$-linear F-bundle is defined as the $D$-module inverse image $\psi_{\blambda}^*(\cH_R^B,\nabla^B_R)$ and restrict scalars from $R$ to $\bbk$, as in \cref{lifting lemma}. Explicitly, the underlying $\bbk\dbb{\by_{\leq r},u}$-module is 
\[\cH^{B}= G_0 (X_P^{\vee} ,\cW ,p)\otimes  R\dbb{\by_{\leq r},u},\]
equipped with a regular meromorphic connection 
\[ \nabla^{B}_{\partial_{y_{i, k}}}([\omega ])=\big[\mathcal{L}_{\partial_{y_{i,k}}} (\omega)+  u^{-1}\frac{\partial \mathcal{W}}{\partial y_{i,k} } \omega  -u^{-1}\sum_{j=1}^n \lambda_j \big(\iota_{\partial_{y_{i, k}}} p^{*} \big\langle (\lambda_j)^{*}, {\rm mc}_{T^{\vee}}  \big\rangle\big)\omega \big],\]
where $\mathcal{W}$ is in variables ${y_{i,k}}$.
The $u$-direction is defined in \cref{eq:u-direction-small-B-model}, its definition uses the grading operator on the $B$-model, which we now define. 
We first construct a grading on $\Omega^{\top} (X_P^{\vee}/Z) \otimes \bbk\dbb{\by_{\leq r},u}$.




\begin{construction}[Grading on differential forms] \label{constr:grading-fiber-small-model}
We construct a $\bbk\dbb{\by_{\leq r},u}$-linear operator $\mu_B$ on $\Omega^{\top} (X_P^{\vee} / Z ) \otimes\bbk\dbb{\by_{\leq r},u}$, which defines a grading on differential forms. 

Recall that $\Omega^{\top} (X_P^{\vee} /Z) \otimes\bbk\dbb{\by_{\leq r} , u}$ is a rank $1$ free module over $\cO\big( X_P^{\vee} \big)\dbb{\by_{\leq r}, u}$.
The choice of $\Omega$ in \cref{prop: iso_small_Dmodule current version}(2) produces a basis of this module. 
For any differential form  $\omega = h\Omega$ with $h\in\cO\big( X_P^{\vee} \big)\dbb{\by_{\leq r}, u}$, we define
\[\mu_B ( h\Omega ) \coloneqq \frac{\deg_B (h)}{2}\Omega ,\]
where the degree operator $\deg_B$ is defined on functions in $\cO (X_P^{\vee} )$ using the $\bbG_m$-action on $X_P^{\vee}$ constructed in \cite[Lemma 4.6]{chow2024dmodulemirrorconjectureflag}, and extended by $\bbk\dbb{\by_{\leq r} ,u}$-linearity. 
Using the Jacobian isomorphism \eqref{eq:jacobi-isomorphism} and the grading operator $\mu_A$, we can describe $\deg_B$ as follows. For any local chart, we take a coordinate system $(z_{i})_{i}$ so that $z_{i}$ are homogeneous.
 For a monomial function $h\in \cO \big((G^\vee/P^\vee)\setminus -K_{G^\vee/P^\vee} \big)$, we have $\deg_B (h) = 2dh$ where $d\in \bbZ$ is given by:
\[\big(\sum_{i=1}^{r} \frac{\deg(q_{i})}{2}q_{i}\frac{\partial}{\partial q_{i}}+ \mu_{A} \big) \Phi_{\mir}^{u=0,y=0} (\overline{h})=d \Phi_{\mir}^{u=0,y=0} (\overline{h}),\]
where $\overline{h}$ denotes the image of $h$ in $\Jac (X_P^{\vee}, \cW ,p)$ and $\Phi_{\mir}^{u=0,y=0}$ is the Jacobi isomorphism \eqref{eq:jacobi-isomorphism}. It is then extended to a $\bbk\dbb{\by_{\leq r},u}$-linear operator on $\cO (X_P^{\vee} )\dbb{\by_{\leq r},u}$.
\end{construction}

We use the simple example of $X=\mathbb{CP}^{1}$ case to illustrate the definition of $\deg_{B}$.
\begin{example}[$\mu_B$ for $\bbC\bbP^1$]
For $X=\mathbb{CP}^{1}$, we have $\bbk= \mathbb{C}(q)$.
The equivariant (small) quantum cohomology $\QH_T^{\ast} (X)$ is isomorphic to $\bbk[ H,\lambda] / (H^2 - H\lambda - q)$, where $q$ has degree $4$.
The mirror $X_P^{\vee}$ is the family $\bbG_m\times \Spec \bbC [q^{\pm 1}]\rightarrow \Spec \bbC [q^{\pm 1} ]$, the superpotential is $\cW = z+ \frac{q}{z}$ and the Jacobi ring $\Jac (X_P^{\vee} , \cW, p)$ is isomorphic to $\bbk [z,z^{-1} ,\lambda ] / \big( 1 - \frac{\lambda}{z} - \frac{q}{z^2}\big)$.
The mirror isomorphism $\Phi_{\mir}^{u=0,y=0}$ at $u=0$, $y=0$ is given the morphism of $\bbk [\lambda]$-modules defined by $z\mapsto H$.

We have $\deg_B (qz^3) = q\deg_B (z^3) = 6qz^3$, where the last equality follows from the computation:
\begin{align*}
(\frac{\deg(q)}{2}q\frac{\partial}{\partial q} + \mu_{A} ) \Phi_{\mir}^{u=0,y=0} (\overline{z^{3}})&= \big(\frac{\deg(q)}{2}q\frac{\partial}{\partial q} + \mu_{A} \big)(\lambda^{2}H+qH+q\lambda)\\
&=3 (\lambda^{2}H+qH+q\lambda). 
\end{align*}
\end{example}



The $u$-direction connection of the $B$-model $\bbk$-linear F-bundle $(\cH^B,\nabla^B)$ is defined as 
\begin{align} \label{eq:u-direction-small-B-model}
 \nabla^{B}_{u\partial_u}&\coloneqq \Gr^{B} - \nabla_{E^{\rm }_{B}} , \\
 \Gr^B &\coloneqq u\partial_u + E_B + \mu_B, \nonumber
\end{align}
where $u\partial_u$ measures the degree in $u$, $\mu_B$ is the grading operator on differential forms (see \cref{constr:grading-fiber-small-model}), and $E_B$ is the Euler vector field measuring the degree of the $\by$-variables and accounting for the degree of $q$:
\[E^{\rm }_{B}\coloneqq \sum_{1\leq j\leq r}\frac{\deg(q_j)}{2}\partial_{y_{j,0}} -\sum_{1\leq j\leq r,k\in \bbN^{n}}|k| y_{j,k}\partial_{y_{j,k}}.\]
In the following proposition, we note that even though $\mu_B$ is only defined on differential forms, the total grading operator $\Gr^B$ is well-defined on equivalences classes.

\begin{proposition}\label{grading operator well defined.}
The grading operator $\Gr^{B}$ produces a well-defined operator on $\cH^B$.
\end{proposition}
\begin{proof}
Let $K$ denote the rank of $\Omega^1 (X_P^{\vee} /Z)$.
We only need to prove that for any $(K-1)$-form $\eta$, there exists a $(K-1)$-form $\eta'$ such that
\begin{align}\label{grading on n-1 form}
    \Gr^{B}\big((ud+d\mathcal{W}\wedge)\eta\big)= (ud+d\mathcal{W}\wedge)\eta'
\end{align}
Fix a torus-invariant local chart with coordinates $(z_i)_i$ and write
\[\eta=\sum_i g_{i} (z,q,\by_{\leq r},u) \iota_{\partial_{z_{i}} }\big(\bigwedge_{j=1}^{K} dz_{j}\big).\]
Let 
\[\eta' \coloneqq\sum_i \big( (u\partial_u + E_B + \deg_B)(g_{i} )+\big(1-\frac{\deg_{B}(z_{i})}{2 z_{i}}\big)g_{i}  \iota_{\partial_{z_{i}} }\big(\bigwedge_{j=1}^{K} dz_{j}\big) .\]
A direct computation shows that this choice of $\eta'$ satisfies \eqref{grading on n-1 form}.
We conclude that $\Gr^B$ descends to an operator on $\cH^B$, completing the proof. 
\end{proof}








