The following proposition essentially follows from Proposition \ref{prop: iso_small_Dmodule current version}.
Here we add the explanation in detail for completeness.

\begin{proposition}\label{small mirror} 
The $A$-model small equivariant F-bundle $\cF^A$ over $\bbk\dbb{\btau_{\leq r}}$ is isomorphic to the $B$-model small equivariant F-bundle $\cF^B$ over $\bbk\dbb{\by_{\leq r}}$ under an isomorphism  $\big((\mir_\bbk,{\Phi_{\mir,\bbk}}), (\mir,\Phi_\mir) \big)$ where $\Phi_{\mir}$ is as in \cref{prop: iso_small_Dmodule current version}, $\Phi_{\mir ,\bbk}$ is the induced $\bbk$-linear map, and $\mir_\bbk\colon y_{i, k}\mapsto \tau_{i, k}$, $\mir\colon y_{i}\mapsto \tau_{i}$ identify the variables of the equivariant F-bundles.
\end{proposition}
\begin{proof} 
Our construction of $B$-model small equivariant F-bundle \[\cF^B = \lbrace(\cH^{B}, \nabla^{B}), (\cH_R^{B}, \nabla_R^{B}), \id \rbrace / \bbk\dbb{\by_{\leq r}}\] 
consists of the (T)-structure obtained as $D$-module inverse image:
\begin{align*}
    (\cH^B_R,\nabla^B_R) &= \psi^* \big(G_0(X_P^{\vee}, \mathcal{W}, p),\nabla\big),\\
    (\cH^B,\nabla^B) &= (\psi_{\blambda}\circ \psi)^* \big(G_0(X_P^{\vee}, \mathcal{W}, p),\nabla\big),
\end{align*}
where $\psi$ and $\psi_{\blambda}$ are base change maps defined in equations \eqref{eq1: change ring} and \eqref{eq2: change variables}, together with a $u$-direction on $(\cH^B,\nabla^B)$.
\\Our construction of $A$-model small equivariant F-bundle $\cF^{A}= \lbrace (\cH^{A}, \nabla^{A}), \allowbreak (\cH_R^{A}, \nabla_R^{A}), \id \rbrace / \bbk\dbb{\btau_{\leq r}}$ in \cref{subsection: Equivariant F-bundle structures of G/P}, can also be written as (T)-structures $(\cH^A,\nabla^A)$ and $(\cH^A_R,\nabla^A_R)$ obtained as $D$-module inverse image under the same maps, together with a $u$-direction on $(\cH^A,\nabla^A)$. \\
By the functoriality of pullback, the isomorphism in Proposition \ref{prop: iso_small_Dmodule current version} induces an isomorphism
\[((\mir_\bbk,\Phi_{\mir,\bbk}),  (\mir,\Phi_{\mir}))\colon\cF^B\longrightarrow \cF^A\]
of the underlying (T)-structures. 
It suffices to prove that in our setting $\Phi_{\mir}$ is also graded, i.e.\ that $(\mir_{\bbk})_{\ast} E_B = E_A$ and
\begin{equation}\label{eq:compatibility-gradings}
    \Phi_{\mir,\bbk}\circ \Gr^{B} = \mir_\bbk^\ast \Gr^A \circ \Phi_{\mir,\bbk},
\end{equation}
where $\mir_\bbk^\ast \Gr^A$ is the grading operator on $\mir_\bbk^*\cH_A$ induced from $\Gr^A$. 
The compatibility of the Euler vector fields is clear from their definition and the fact that $\mir_{\bbk}$ identifies the variables $\by_{\leq r}$ and $\btau_{\leq r}$.
For \eqref{eq:compatibility-gradings}, we need to check that for all $f\in O(X_P^\vee)\dbb{\by_{\leq r},u}$, we have 
\[ \Phi_{\mir,\bbk}([(u\partial_{u}+E_{B}+\mu_{B})(f\Omega)])= (u\partial_{u}+E_B+\mu_{A})(\Phi_{\mir,\bbk}([f\Omega])).\]
Since both sides are linear in $q$ and satisfy the Leibniz rule for $y$ and $u$, it suffices to check the equation for $f\in \cO\big((G^\vee/P^\vee)\backslash -K_{G^\vee/P^\vee}\big)$.

In this case, the left-hand side reduces to $\Phi_{\mir,\bbk} ([\mu_{B}(f\Omega)])$.
For the right-hand side, observe that $\Phi_{\mir,\bbk} ([f\Omega] )$ is obtained by first applying the mirror map \eqref{eq:chow-mirror-map} from \cite{chow2024dmodulemirrorconjectureflag} to $[f\Omega ]$, and then pulling back under the change of variables $\tq_i \mapsto  q_i e^{\sum_k \lambda^k y_{i,k}}$.
Hence $\Phi_{\mir,\bbk} ([f\Omega] )$ is a power series in the variables $\lbrace q_ie^{\sum_k \lambda^k y_{i,k}}\rbrace_{1\leq i\leq r}$ with coefficients in $H_T^{\ast} (X,\bbC )$.
For an equivariant cohomology class $\alpha\in H_T^{\ast}(X,\bbC )$, we have 
\[q_i\frac{\partial}{\partial q_i} (q_i e^{\sum_k \lambda^k y_{i,k} }\alpha) = \frac{\partial}{\partial y_{i,0}} (q_ie^{\sum_k \lambda^k y_{i,k}} \alpha).\]
It follows that at $y=0$, the right hand side is 
\begin{align*}
    (u\partial_u + E_B + \mu_A)(\Phi_{\mir,\bbk} ([f\Omega] )) &= \big( u\partial_u + \sum_{i=1}^r \frac{\deg (q_i)}{2} q_i\frac{\partial}{\partial q_i} + \mu_A\big)(\Phi_{\mir,\bbk} ([f\Omega] )) \\
    &= \Phi_{\mir,\bbk} ([\mu_B (f\Omega )]),
\end{align*}
where the last equality follows from \cref{Chow compatible with grading}. So this implies that the bundle map is compatible with $u$-direction at $y=0$. This implies by \cref{corollary: bundle map is uniquely determined on a point} that \cref{eq:compatibility-gradings} holds for any $y$.
We deduce that $(\mir_{\bbk}, \Phi_{\mir,\bbk})$ is an isomorphism of F-bundles, concluding the proof.
\end{proof}


\subsection{\texorpdfstring{The big $D$-module mirror symmetry for $G/P$}{The big D-module mirror symmetry for G/P}} 

In this subsection, we prove the big $D$-module mirror symmetry for  $G/P$ in the framework of equivariant F-bundles.
We first construct a maximal unfolding of the small B-model equivariant F-bundle by unfolding the superpotential $\cW$ (\cref{constr:unfolded-potential}).
In particular, we discuss freeness in \cref{Lemma: formal Nakayama,B side R-linear T-structure}, and flatness in \cref{B side R-linear T-structure,remark:flatness-B-model}.
We obtain the equivariant big mirror symmetry for flag varieties in \cref{thm:big-mirror-symmetry-flag}, and deduce a non-equivariant version in \cref{thm:non-equivariant}.

\subsubsection{Unfolding of the B-model}
We fix formal variables $y = \lbrace y_1,\dots, y_N\rbrace$ and $\by = \lbrace y_{i,k} , 1\leq i\leq N, k\in\bbN^n\rbrace$.

\begin{construction}[Unfolded superpotential]\label{constr:unfolded-potential}
    For any $r<j\leq N$, let $\bar{f}_{j}\coloneqq (\Phi^{u=0,y=0}_{\rm mir})^{-1}(\sigma_{v_{j}})\in  {\rm Jac}(X^{\vee}_{P}, \mathcal{W},  p)$.
    Let $f_j\in \mathcal{O}(X^{\vee}_{P})$ be a lift of $\bar{f}_{j}$ such that the function $f_{j}$ is independent of $y_{1},...,y_{N}$.
    The unfolded superpotential $\widetilde{\cW}$ is
    $$\widetilde{\mathcal{W}}\coloneqq \mathcal{W}+\sum_{j=r+1}^N y_{j} f_j.$$
\end{construction}

Similar to the previous section on the small $B$-model equivariant $F$-bundle, we now associate to $\widetilde{\cW}$ the big $B$-model equivariant F-bundle 
\[\cF^{B,\bigquantum} \coloneqq \lbrace(\cH^{B, {\rm big}}, \nabla^{B, {\rm big}}), (\cH_R^{B, {\rm big}}, \nabla_R^{B, {\rm big}}), \id \rbrace / \bbk\dbb{\by} .\]
We first construct an $R$-linear (T)-structure $(\cH_R^{B,\bigquantum},\nabla_R^{B,\bigquantum})$ , consisting of a $R\dbb{y,u}$-module defined by
\begin{align*}
    \cH_R^{B,\bigquantum}&\coloneqq \mbox{coker} \big(R\dbb{y, u} \otimes_{\bbC[\tilde{q}_i^{\pm 1}]} \Omega^{{\rm top}-1}(X^\vee_P/Z)\overset{\partial}{\longrightarrow} R\dbb{y, u}\otimes_{{\bbC[\tilde{q}_i^{\pm 1}]}} \Omega^{\rm top}(X^\vee_P/Z)\big),\\
     \partial &\coloneqq 1\otimes \big( ud + d\widetilde{\cW}\wedge  -\sum_{j=1}^n  \lambda_j  (p^*\langle (\lambda_j)^{*}, {\rm mc}_{T^\vee}\rangle)\wedge\big),
\end{align*}
equipped with a connection defined by 
\[\nabla^{B, {\rm big}}_{R, \partial_{y_{i}}}([\omega])\coloneqq\big[\mathcal{L}_{\partial_{y_{i}}} (\omega)+ u^{-1}\frac{\partial \widetilde{\mathcal{W}}}{\partial y_{i} } \omega  - u^{-1}\sum_{j=1}^n \lambda_j \big(\iota_{\partial_{y_{i}}} p^{*} \big\langle (\lambda_j)^{*}, {\rm mc}_{T^{\vee}}  \big\rangle \big)\omega \big].\]


\begin{proposition}\label{B side R-linear T-structure}
    The data $(\cH_R^{B,\bigquantum},\nabla_R^{B,\bigquantum})/R\dbb{y}$ defines an $R$-linear (T)-structure.
\end{proposition}
\begin{proof} 
We first check that $\cH^{B,\bigquantum}_R$ is a free $R\dbb{y,u}$-module. 
By construction we have 
$\cH_R^{B,\bigquantum}\vert_{y_{\geq r+1}=0} = \cH_R^{B}$, which is a finite free $R\dbb{y_{\leq r},u}$-module (see \cite[p.\ 52]{chow2024dmodulemirrorconjectureflag}). 
Since $y_j\omega \in \im(\partial)$ if and only if $\omega \in \im(\partial)$, the element $y_j$ is torsion-free. 
Hence, the freeness of $\cH_R^{B,\bigquantum}$ follows from \cref{Lemma: formal Nakayama} below.
The flatness of $\nabla_R^{B,\bigquantum}$ follows from the facts that $\frac{\partial \widetilde{\mathcal{W}}}{\partial y_i}=f_i$ is independent of $y_1,\dots,y_N$, that  $[\cL_{\partial_{y_s}},\cL_{\partial_{y_t}}]=0$, and that $[\cL_{\partial_{y_s}},\iota_{y_t}]=0$.
\end{proof}

\begin{lemma}\label{Lemma: formal Nakayama}
Let $R_0$ be a commutative unital ring and $M$ be an $R_0\dbb{z_1,\cdots,z_m}$-module such that $z_i$ is torsion-free for all $1\leq i\leq m$. 
Let $\Omega_1,\dots, \Omega_N\in M$.
If $\{\bar \Omega_1,\cdots, \bar \Omega_N\}$ is an $R_{0}$-basis of $M/(z_{1},...,z_{m})M$, then $\{\Omega_1,\cdots,\Omega_N\}\subset M$ is
an $R_{0}\dbb{z_1,\cdots, z_m}$-basis of $M\dbb{z_1,\cdots, z_m}$.
\end{lemma}
\begin{proof}
By Nakayama lemma \cite[\S VIII.3, Corollary 2]{Zariski_commutative_II}, $\lbrace \Omega_1,\cdots,\Omega_N\rbrace$ generates $M$ as an $R_0\dbb{z_1,\cdots,\allowbreak z_m}$-module. It remains to prove the freeness. 

We first treat the case $m=1$.
Let $g_i(z_{1})\in R_{0}\dbb{z_{1}}$ be coefficients such that $\sum_i g_i(z_{1})\Omega_i=0$. 
Since $\lbrace \Omega_i\rbrace$ induces a basis of $M/z_1M$, we have $g_i(0)=0$. 
Assume $g_i$ has no terms of degree less than or equal to $b-1$ in $z_1$, i.e. we can write $g_i = z_{1}^bh_i$.
Then we have 
\begin{equation*}
    \sum_i z_{1}^b h_i\Omega_i=0.
\end{equation*}
Since $z_1^b$ is torsion-free in $M$, we deduce that $\sum_i h_i\Omega_i=0$, which implies $h_i(0)=0$.
Hence, $g_i$ has no terms of degree less than or equal to $b$.
By induction on $b$, this implies $g_i=0$.

The case $m\geq 2$ follows from the case $m=1$ by a direct induction on the number of variables.
The proof is complete.
\end{proof}

The $\bbk$-linear F-bundle $(\cH^{B,\bigquantum},\nabla^{B,\bigquantum})/\bbk\dbb{\by}$ is given by the $D$-module inverse image of $(\cH_R^{B,\bigquantum},\allowbreak \nabla_R^{B,\bigquantum})$ under the map of $R\dbb{u}$-algebras $
    R\dbb{y,u}\rightarrow R\dbb{\by,u}$ given by $y_i\mapsto \sum_{k\in \bbN^n}\lambda^k{y_{i,k}}$.
More explicitly:
\begin{align*}
    \cH^{B,\bigquantum} &\coloneqq\cH_R^{B,\bigquantum}\otimes_{\bbk\dbb{y, u}}\bbk\dbb{\by ,u} ,\\
     \nabla^{B,{\rm big}}_{\partial_{y_{i, k}}}([\omega ])&\coloneqq \big[\mathcal{L}_{\partial_{y_{i,k}}} (\omega)+ u^{-1}\frac{\partial \widetilde{\mathcal{W}}}{\partial y_{i,k} } \omega  - u^{-1}\sum_{j=1}^n \lambda_j \big(\iota_{\partial_{y_{i,k}}} p^{*} \big\langle (\lambda_j)^{*}, {\rm mc}_{T^{\vee}}  \big\rangle \big)\omega \big],
\end{align*}
equipped with the $u$-direction connection
\begin{align*}
    \nabla^{B,{\rm big}}_{u\partial_u}&\coloneqq \Gr^{B,\bigquantum} - \nabla_{E_B^{\bigquantum}}, \\
    \Gr^{B,\bigquantum} &\coloneqq u\partial_u + E_B^{\bigquantum} + \mu_B,
\end{align*}
where the Euler vector field is given by
\[E^{\rm big}_{B}\coloneqq \sum_{1\leq j\leq r}\frac{\deg(q_j)}{2}\partial_{y_{j,0}} +  \sum_{1\leq j\leq N,k\in \bbN^{n}} (1-\ell(v_j)-|k|) y_{j,k}\partial_{y_{j,k}},\]
and where the grading on differential forms $\mu_B$ (see \cref{constr:grading-fiber-small-model}) is extended to a $\bbk\dbb{\by,u}$-linear operator.
Similar to \cref{grading operator well defined.}, the total grading operator $\Gr^{B,\bigquantum}$ lifts to $\cH^{B,\bigquantum}$.

\begin{proposition}\label{remark:flatness-B-model}
The big Gauss-Manin connection $\nabla^{B, {\rm big}}$ is flat. 
\end{proposition}
\begin{proof}
 The underlying (T)-structure of $(\cH^{B,\bigquantum},\nabla^{B,\bigquantum})$ is flat, as it is obtained from the $R$-linear (T)-structure $(\cH_R^{B,\bigquantum} ,\nabla_R^{B,\bigquantum} )$, whose flatness was established in \cref{B side R-linear T-structure}.
    We check the flatness in the $u$-direction as follows.
    We have:
\begin{align*}
      \big[   \nabla_{u\partial_u}^{B, {\rm big}} , \nabla_{\partial_{y_{j,k}}}^{B,\bigquantum} ]
        &= \big[\Gr^{B,\bigquantum} , \nabla_{\partial_{y_{j,k}}}^{B,\bigquantum}\big] -\big[ \nabla_{E_B^{\bigquantum}}^{B,\bigquantum} , \nabla_{\partial_{y_{j,k}}}^{B,\bigquantum} \big]  
 \end{align*}
 Since the underlying (T)-structure of $(\cH^{B,\bigquantum} , \nabla^{B,\bigquantum})$ is flat, we have 
\begin{align}\label{eq:commutator-euler-vector-field-B-model}
    \big[ \nabla_{E_B^{\bigquantum}}^{B,\bigquantum} , \nabla_{\partial_{y_{j,k}}}^{B,\bigquantum} \big] &= \nabla_{[E_B^{\bigquantum} , \partial_{y_{j,k}}]}^{B,\bigquantum} = - (1- \ell (v_j) - \vert k\vert ) \nabla_{\partial_{y_{j,k}}}^{B,\bigquantum} .
\end{align}
We claim that the grading structure is compatible with the connection, in the sense that 
\begin{equation}\label{eq:grading-compatible-connection}
    \big[\Gr^{B,\bigquantum} , \nabla_{\partial_{y_{j,k}}}^{B,\bigquantum} \big]=-(1 - \ell(v_j) - |k|)\nabla_{\partial_{y_{j,k}}}^{B,\bigquantum}. 
\end{equation}
When $1\leq j\leq r$, the equality holds because $\nabla^{B}$ is flat.
When $r+1\leq j\leq N$, the equality holds because for any $[\omega]\in \cH^{B, big}$ we have
\begin{align*}
   \Gr^{B,\bigquantum}([f_{j}\omega])-f_{j}\Gr^{B,\bigquantum}([\omega]) &= [\ell(v_j)f_{j}\omega],  \\
   \Gr^{B,\bigquantum}([u^{-1}\omega])-u^{-1}\Gr^{B,\bigquantum}([\omega])&=-[u^{-1}\omega], \\
   \Gr^{B,\bigquantum}([\lambda^{k}\omega])-\lambda^{k} \Gr^{B,\bigquantum}([\omega])&=[|k|\lambda^{k}\omega],
\end{align*}
where we use \cref{eq: mu_b leibniz rule} and the homogeneity of the elements $f_j$, $u^{-1}$ and $\lambda^k$.
Note that $f_j$ is homogeneous of degree $\ell (v_j)$ by our choice of lift in \cref{constr:unfolded-potential}.
Now, flatness follows from equations \eqref{eq:commutator-euler-vector-field-B-model} and \eqref{eq:grading-compatible-connection}, concluding the proof.
\end{proof}


Similar to the $A$-model, we note that the quotient maps $\bbk\dbb{\by}\rightarrow \bbk\dbb{\by_{\leq r}}$ and $R\dbb{y}\rightarrow R\dbb{y_{\leq r}}$ induce an unfolding of equivariant F-bundles $\iota_B\colon\cF^B\rightarrow \cF^{B,\bigquantum}$.


\begin{proposition}\label{prop: B model is maximal}
    The morphism $\iota_B\colon \cF^{B}\rightarrow \cF^{B,\bigquantum}$ is a maximal unfolding of $\bbk$-linear equivariant F-bundles, with cyclic vector given by $[\Omega ]  :=\Phi_{\rm mir}^{-1}(1),$ where $1 \in H_T^{\ast}(X,\bbk)$ is the cyclic vector on the $A$-side.
\end{proposition}
\begin{proof}
 We only need to check that $\cF^{B,\bigquantum}$ is a maximal unfolding of $\cF^B$ with cyclic vector induced from $[\Omega ]$.
By definition of $\cF^{B,\bigquantum}$, for $r < j\leq N$ we have
\[\Phi_{\rm mir}\big([u\nabla^{B, {\rm big}}_{R, \partial_{y_j}}]\vert_{y=u=0}([\Omega] )\big)= \Phi^{u=0, y=0}_{\rm mir}(\bar{f}_j)=\sigma_{v_j}. \]
For $1\leq j\leq r$, by \cref{small mirror} we have 
\[\Phi_{\rm mir}\big([u\nabla^{B, {\rm big}}_{R, \partial_{y_j}}]\vert_{y=u=0}([\Omega] )\big) = [u\nabla_{\partial t_j}^{A} ]\vert_{t=u=0} (1) = \sigma_{v_j} .\]
Since $\Phi_{\rm mir}$ is an isomorphism and $\lbrace \sigma_{v_j} , 1 \leq j\leq N\rbrace$ is a basis of $H_T^{\ast} (X,\bbk ) $, we conclude that the unfolding is maximal.
\end{proof}





\subsubsection{Mirror symmetry}
Now we can show the big $D$-module mirror symmetry for $X=G/P$ in the following sense.
\begin{theorem}[Equivariant big mirror symmetry]\label{thm:big-mirror-symmetry-flag}
    There exists a unique isomorphism of equivariant F-bundles
    \[\big( (\mir_{\bbk}^{\bigquantum} , \Phi_{\mir,\bbk}^{\bigquantum} ), (\mir^{\bigquantum}, \Phi_{\mir}^{\bigquantum} ) \big)\colon \cF^{B,\bigquantum} \longrightarrow \cF^{A,\bigquantum}\] 
    extending the small mirror map $\big((\mir_\bbk,{\Phi_{\mir,\bbk}}), (\mir,\Phi_\mir) \big)$ in \cref{small mirror}.
\end{theorem}

\begin{proof}
By \cref{prop: A model maximal}, we have a maximal unfolding of the small $A$-model equivariant F-bundle, given by $\cF^A\rightarrow \cF^{A,\bigquantum}$. Composing the small mirror isomorphism  $\big((\mir_\bbk,{\Phi_{\mir,\bbk}}), (\mir,\Phi_\mir) \big): \cF^A\rightarrow \cF^B$ of \cref{small mirror}, with the $B$-model maximal unfolding $\iota: \cF^B\rightarrow \cF^{B,\bigquantum}$, we obtain another maximal unfolding $\cF^A\rightarrow\cF^{B,\bigquantum}$.

To apply \cref{thm:max-unfolding-arbitrary-rank} and obtain a unique isomorphism $\cF^{A,\bigquantum} \rightarrow \cF^{B,\bigquantum}$, we need to check the small $A$-model equivariant F-bundle satisfies the (GC') condition as in \cref{def:IC-GC-conditions}.
We take $v=1\in H^*_T(X,\bbk) =\cH^A|_{\tau=u=0}$. After base change to $\Frac(R)=\bbk(\lambda)$, we have the evaluation map of $\bbk(\lambda)$-modules:
\begin{align} 
    \mu_{v=1}\colon \bigoplus_{1\leq j\leq r} \bbk(\lambda)\partial_{\tau_j} &\longrightarrow H_T^*(X,\bbk)\otimes \bbk(\lambda),\\
     \partial_{\tau_j} &\longmapsto \mu (\partial_{\tau_j})(1)= \sigma_{v_j}+\lambda_{i_j} . \nonumber
\end{align}
By \cref{lemma:QHG/PH2}, $H^*_T(X,\bbk)\otimes \bbk(\lambda)$ is generated as a $\bbk(\lambda)$-algebra by $\sigma_{v_j}$ for $1\leq j\leq r$, so the orbit of $v=1$ under the action of $R[\im \mu]$ is the fiber $\cH^{A}_{R}/ (\tau_1,\dots, \tau_N,u)\cH_R^{A}\otimes_R \Frac (R)$, and (GC') is verified.
The proof is complete.
\end{proof}


We deduce a non-equivariant limit of the theorem by applying the base-change associated to the quotient map $R\rightarrow R/ (\lambda )$.
This corresponds to setting $\lambda=0$ in all the previous formulas.
We use the superscript $\lambda_0$ to indicate that the non-equivariant limit is taken.
We note that since $R/(\lambda )\simeq \bbk$, in the non-equivariant limit the equivariant F-bundles can be reduced to $\bbk$-linear F-bundles (see \cref{remark:when-R-is-k}).

On the A-side, we have 
$\tau_{i}=\sum \lambda^{k}\tau_{i, k}= \tau_{i, 0}$. 
The big quantum $D$-module $(\cH^{A,\bigquantum, \lambda_0},\nabla^{A,\bigquantum, \lambda_0})$ is an F-bundle over $\bbk\dbb{\tau} = \bbk\dbb{\tau_1,\dots, \tau_N}$ defined by
\begin{align*}
\cH^{A,\bigquantum,\lambda_0} &= H^*(X,\bbC)\otimes \bbk\dbb{\tau,u} , \\
\nabla^{A,\bigquantum, \lambda_0}_{\partial_{\tau_{j}}}&= \partial_{\tau_{j}}+u^{-1}\sigma_{v_j}\star^{\bigquantum ,\lambda_0}  ,\\
    \nabla_{u\partial_u}^{A,\bigquantum, \lambda_0} &= \Gr^{A,\bigquantum,\lambda_0} - \nabla_{E_A^{\bigquantum,\lambda_0}}^{A,\bigquantum,\lambda_0} ,
\end{align*}
where $\Gr^{A,\bigquantum,\lambda_0} = u\partial_u + E_A^{\bigquantum,\lambda_0} + \mu_A$, with the Euler vector field
\[E^{{\rm big}, \lambda_0}_{A}\coloneqq \sum_{1\leq j\leq r}\frac{\deg(q_j)}{2}\partial_{\tau_{j}} +  \sum_{1\leq j\leq N} (1-\ell(v_j)) \tau_{j}\partial_{\tau_{j}}.\]

On the B-side, we have
$y_{i}=\sum \lambda^{k}y_{i, k}= y_{i, 0}$. 
The non-equivariant big Gauss-Manin system is an F-bundle $(\cH^{B,\bigquantum, \lambda_0},\nabla^{B,\bigquantum, \lambda_0})$ over $\bbk\dbb{y} = \bbk\dbb{y_1,\dots, y_N}$ defined by
\begin{align*}
\cH^{B,\bigquantum,\lambda_0}&= \coker\big(\bbk\dbb{y, u}\otimes \Omega^{\rm top -1}(X^\vee_P/Z) \xrightarrow{1 \otimes (ud+d\widetilde{\mathcal{W}}\wedge)} \bbk\dbb{y, u}\otimes \Omega^{\rm top }(X_P^\vee/Z)\big),
\\
\nabla^{B,\bigquantum, \lambda_0}_{\partial_{y_j}}&=\cL_{\partial_{y_j}}+\frac{\partial \widetilde{\mathcal{W}}}{\partial y_j}, \\
\nabla^{B,\bigquantum, \lambda_0}_{u\partial_u}&=u\partial_u-u^{-1}\widetilde{\cW} \qquad  (\mbox{by \cref{prop:nablaBnon-equiv} 
 below}). 
\end{align*}
 \begin{proposition} \label{prop:nablaBnon-equiv}
At the non-equivariant limit, we have $\nabla^{B,\bigquantum, \lambda_0}_{u\partial_u}=u\partial_u-u^{-1}\widetilde{\cW}$.
\end{proposition}

\begin{proof}
In this proof, to simplify notations we drop the superscript $\lambda_0$.
For any $[\omega]\in \cH^{B,\bigquantum}$, we can write $\omega= g\Omega$ where  $g\in \mathcal{O}(X_{P}^{\vee})\dbb{y,u}$  and $\Omega$ is given in \cref{prop: iso_small_Dmodule current version}(2). We have
% \[\nabla_{E_{B}^{\rm big}}^{B, {\rm big}}([g \Omega])=[E_{B}^{\rm big}(g)\Omega+u^{-1}E_{B}^{\rm big}(\widetilde{W})g\Omega].\]
\begin{align*}
\nabla^{B , {\rm big}}_{u\partial_{u}}([g\Omega])&=[u\partial_{u}(g\Omega)+E_{B}^{\rm big}(g)\Omega+\mu_{B}(g\Omega)]-\nabla_{E_{B}^{\rm big}}^{B, {\rm big}}([g \Omega])\\
&= [u\partial_{u}(g\Omega)+\mu_{B}(g\Omega)-u^{-1}E_{B}^{\rm big}(\widetilde{\cW})g\Omega  ]
\\&= [u\partial_{u}(g\Omega)+\mu_{B}(g\Omega)-u^{-1}g\Gr^{B,\bigquantum}(\widetilde{\cW}\Omega)+ g\partial_{u}(\widetilde{\cW})\Omega+g \mu_{B}(\widetilde{\cW}\Omega) ]. 
\end{align*}
We claim that $\Gr^{B,\bigquantum} (\tcW\Omega ) = \tcW \Omega$, or equivalently that $\tcW$ is homogeneous of degree $1$ as an element of $\cO (X_P^{\vee} ) \dbb{y,u}$.
By  \cite[Lemma 4.3]{chow2025gammaconjectureiflag}, we have $\Phi_{\rm mir}([\cW\Omega])=c_1(G/P)$, hence $\cW$ is homogeneous of degree $1$ since $\Phi_{\mir}$ is graded (\cref{prop: iso_small_Dmodule current version}(5)).
For $r< j\leq N$, our choice of lift in \cref{constr:unfolded-potential} shows that $\Gr^{B,\bigquantum}(y_{j}f_{j}\Omega)=E^{\bigquantum}_{B}(y_{j})f_{j}\Omega+y_{j}\mu_{B}(f_{j}\Omega)=y_jf_{j}\Omega$.
Since $\tcW$ is independent of $u$, we have
\[ 
\nabla^{B , {\rm big}}_{u\partial_{u}}([g\Omega])= [u\partial_{u}(g\Omega)-u^{-1}\widetilde{\cW}g\Omega]+ [u \mu_{B}(g\Omega)+g\mu_{B}(\widetilde{\cW}\Omega)].  \]
By \cite[Remark 4.13]{chow2024dmodulemirrorconjectureflag} and the references therein, after fixing local coordinates $(z_i)_i$ we can write 
$\Omega=\frac{\bigwedge_{i=1}^{K} dz_{i}}{z_{1}...z_{K}}$.
By \cref{eq: mu_b leibniz rule}, we have 
\[\mu_{B}(g\Omega)=\sum_{i=1}^{K} \frac{\partial g}{\partial z_{i}} \mu_{B}(z_{i} \Omega).\]
Consider  the  $K-1$ form  
\(\eta\coloneqq\sum_{i=1}^{K} g\iota_{\partial_{z_i}} \mu_B (z_i\Omega) \).
We have:
\begin{align*}
    ud\eta &= u\sum_{i,j=1}^K \frac{\partial g}{\partial z_j} dz_j\wedge \iota_{\partial_{z_i}}\mu_B (z_i\Omega ) + u g \sum_{i=1}^K d(\iota_{\partial_{z_i}} \mu_B (z_i\Omega ) ) \\
    &= u\sum_{i=1}^K \frac{\partial g}{\partial z_i}\mu_B (z_i\Omega ) = u\mu_B (g\Omega ),
\end{align*}
and 
\begin{align*}
    d\tcW\wedge \eta &= \sum_{i=1}^K \frac{\partial \tcW}{\partial z_i} dz_i\wedge (g\iota_{\partial_{z_i}} \mu_B (z_i\Omega ))\\
    &= g\mu_B (\tcW\Omega ).
\end{align*}
We deduce that 
\[[u\mu_B (g\Omega ) + g\mu_B (\tcW \Omega )] = [ (ud+d\tcW\wedge)\eta ] = 0,\]
concluding the proof.
%This holds for any fixed torus chart, so we finished the proof.
\end{proof}

As a direct consequence of Theorem \ref{thm:big-mirror-symmetry-flag}, we obtain the following non-equivariant big $D$-module mirror symmetry.
\begin{theorem}[Non-equivariant big mirror symmetry]\label{thm:non-equivariant}  
The non-equivariant limit of  $(\mir_{\bbk}^{\bigquantum},\Phi^{\bigquantum}_{\mir,\bbk})$ in \cref{thm:big-mirror-symmetry-flag}
gives an isomorphism of $\bbk$-linear F-bundles
\[(\cH^{A,\bigquantum, \lambda_0},\nabla^{B,\bigquantum, \lambda_0})\overset{\sim}{\longrightarrow}(\cH^{B,\bigquantum, \lambda_0},\nabla^{B,\bigquantum, \lambda_0}).\]
This isomorphism is uniquely determined by the non-equivariant small mirror isomorphism.
\end{theorem}

\begin{proof}
    The existence is clear.
    The uniqueness follows from \cite[Proposition 4.27]{HYZZ_decomposition_and_framing_of_F_bundles}, which applies because the F-bundles are maximal and admit framings.
\end{proof}


