\centering
        \includegraphics[width = \textwidth]{CAS_figs/k33evol.pdf}
        \caption{Evolution of the principal direction permeability $\bar{K}_{33}$, at the left side in function of the decimal logarithm of the Reynolds number and at the right-hand side, in function of the decimal logarithm of the imposed inlet pressure.}
    \label{fig: K33evol}
\end{figure}

